\subsubsection{Multivariate case} % (fold)
\label{ssub:uniform_multiv}

We adapt the definition of $\tau_{1P}$ (resp. $\tau_{2P}$) in the following manner:
\begin{align}
\tau_{1P}: \; [0,1]^3 & \to  \R^d \label{eq:def_tau1_mult} \\
 (u_1,u_2,u_3) & \mapsto  (\lambda^*_{\min}(\Omega_{1P}) + \mathds{1}\{\lambda^*_{\min}(\Omega_{1P}) = \infty\})^{-1/2}E_P[Y_{11} \mid U_{10} = u_1]\notag,	
\end{align}
where $\lambda^*_{\min}(A)$ denotes the smallest strictly positive eigenvalue of $A$ (with the convention that $\lambda^*_{\min}(0)=\infty$). We define $\tau_{2P}$ similarly. Also, let us consider the following two conditions:
\begin{align}
	\textrm{range}(\Omega_{3P}) \subseteq \textrm{range}(\Omega_{1P}+\Omega_{2P}) & \text{ and } \lambda_{\max}(\Omega_{3P}) \leq m^{-1}\lambda_{\min}^*(\Omega_{1P}+\Omega_{2P}), \label{eq:cond_multiv_G} \\
	\|\Omega_{1P}\|\wedge \|\Omega_{2P}\|  =0 & \text{ and } \lambda_{\min}\left(\Omega_{1P}+\Omega_{2P}+\Omega_{4P}\right)\ge m,
 \label{eq:cond_multiv_NG}
\end{align}
where, for any symmetric matrix $A$, $\lambda_{\min}(A)$ denotes its smallest eigenvalue. Then, for $H$ a compact subset of $L_2([0,1]^3,\R^d)$ and $m>0$, we define
\begin{align*}
\mathcal{P}_{m,H}^d=& \big\{P\in\P: \; \lambda_{\min}\left(V_P(Y_{1,1})\right) \ge m, \; \exists \tau_P \in H \text{ satisfying  \eqref{eq:AHK}} \\
&  \text{ s.t. } \tau_{kP}\in H \,(k=1,2) \text{ and either } \eqref{eq:cond_multiv_G} \text{ or } \eqref{eq:cond_multiv_NG} \text{ hold}\,\big\},
\end{align*}
Similarly, let $\mathcal{P}_{m,H}^{d,G}= \{P \in \mathcal{P}_{m,H}^d: \eqref{eq:cond_multiv_G} \text{ holds}\,\}$. As in the univariate case, we then let $\mathcal{P}_{m,H,\RP}^d=\RP\cap \mathcal{P}_{m,H}^d$ and $\mathcal{P}_{m,H,\RP}^{d,G}=\RP \cap \mathcal{P}_{m,H}^{d,G}$. Note that the first conditions in $\mathcal{P}_{m,H}^d$ are the multivariate counterpart of the first two lines in $\mathcal{P}_{m,H}^1$. Condition \eqref{eq:cond_multiv_G} includes DGPs with Gaussian regimes. Its first part is Assumption~\ref{as:pointw_multiv}-(i), while its second part is the multivariate version of the restriction $\Omega_{3P} \le m^{-1}(\Omega_{1P}+\Omega_{2P})$ that we imposed in $\mathcal{P}_{m,H}^1$. Condition \eqref{eq:cond_multiv_NG}, which includes DGPs with non-Gaussian regimes, may be seen as a uniform version of Assumption~\ref{as:pointw_multiv}-(ii).

\medskip
Finally, we also introduce a class of probability distributions on $(Y_{ij})_{i,j\ge 1}$ for which the test based on Bonferroni correction is valid. Hereafter, for any $k\in\{1,...,d\}$, $m>0$ and $H$ a compact subset of $L_2([0,1]^3,\R)$, let $\mathcal{P}_{m,H}^{1(k)}$  denote the same set as $\mathcal{P}_{m,H}^1$ but replacing $Y_{1,1}$ therein by its $k$-th component, $Y_{1,1}^{(k)}$:
\begin{align*}
\mathcal{P}_{m,H,\RP}^{d,b}=& \big\{P\in\RP: P \in \mathcal{P}_{m,H}^{1(k)} \quad \forall k=1,...,d\big\}.
\end{align*}
An advantage of this approach is that for any appropriate choices of the compact subsets $H$ and $H'$, the set $\mathcal{P}_{m,H',\RP}^{d,b}$ includes $\mathcal{P}_{m,H,\RP}^d$.\footnote{Formally, let $\pi_k(x_1,...,x_d)=x_k$ ($k=1,...,d$) and for $H$ a compact subset of $L_2([0,1]^3,\R^d)$, let $H_k=\pi_k(H)$. Then, we can show that $\mathcal{P}_{m,H,\RP}^d\subseteq \mathcal{P}_{m,\cup_{k=1}^d H_k,\RP}^{d,b}$.} In other words, we can obtain uniform results on larger sets of DGPs when considering the Bonferroni test.

\begin{theorem}
	\label{thm:unif_multiv}
Fix $m>0$, $H$ a compact subset of $L_2([0,1]^3,\R)$ and $\RP \subseteq \P$ satisfying \eqref{eq:unif_reste}. If Assumption~\ref{as:asym} holds, we have, for any $\alpha \in (0,1)$,
	\begin{equation}
		\limsup_{n \to \infty} \sup_{P \in \mathcal{P}_{m,H,\RP}^d} \E_P[\phi_\alpha] \le \alpha.
		\label{eq:valid_unif_multiv}
	\end{equation}
	Moreover, if $\mathcal{P}_{m,H,\RP}^{d,G}\ne\emptyset$,
	\begin{equation}
		\limsup_{n \to \infty} \sup_{P \in \mathcal{P}_{m,H,\RP}^{d,G}} \E_P[\phi_\alpha] =
		\liminf_{n \to \infty} \inf_{P \in \mathcal{P}_{m,H,\RP}^{d,G}} \E_P[\phi_\alpha]= \alpha.
		\label{eq:exactness_unif_multiv}
	\end{equation}
	Finally,
	\begin{equation}
		\limsup_{n \to \infty} \sup_{P \in \mathcal{P}_{m,H,\RP}^{d,b}} \E_P[\phi^b_\alpha] \le \alpha,
		\label{eq:valid_unif_multiv_bon}
	\end{equation}
\end{theorem}		

With the same reasoning as in the univariate case, we obtain that Theorem \ref{thm:unif_multiv} generalizes the pointwise result above.

