	\subsection{Two key lemmas}
	\label{ssec:key_lemmas}
	The following lemmas are crucial for the proofs of our main results. Their proofs appear in the Supplemental Appendix.

	\subsubsection{A representation lemma}

Our first lemma is a representation result on $Y_{ij}$. Let $\psi_0(x)=1$ and $\psi_k(x)=\sqrt{2}\cos(k\pi x)$ for $k\ge 1$. The functions $(\psi_k)_{k\in\N}$ form an orthonormal basis for the Hilbert space $L^2[0,1]$, when considering the usual scalar product $\langle f,g\rangle=\int_0^1 f(x)g(x)dx$.

	\begin{lemma}
		\label{lem:mu_nu}
		Suppose that Assumptions~\ref{as:DGP},~\ref{as:asym} and~\ref{as:as_lin} hold. Then, there exists $\tau \in L_2([0,1]^3,\Rb)$, $\bm{\mu} := (\mu^n_{\k})_{\k\in\N^{3}} \in \ell^2_d$ and mutually independent standard uniform variables $(U_{ij})_{(i,j)\in\N^2}$ such that for all $(i,j)\in \N^{*2}$, almost surely
		\begin{equation}
			Y_{ij} = \tau(U_{i0},U_{0j},U_{ij}) = \sum_{\k \in \N^3}\mu^n_{\k}\psi_{k_1}(U_{i0})\psi_{k_2}(U_{0j})\psi_{k_3}(U_{ij}).
			\label{eq:AHK_l2}
		\end{equation}
		Moreover, $V(\overline{Y})$ is invertible for every $n$, which implies the following representation holds true almost surely (with $V_n := V(\overline{Y})^{-1/2}$)
		\begin{equation}
			V_nY_{ij} = \sum_{\k \in \N^3}\left(C_1^{\ind{k_1+ k_3>0}}C_2^{\ind{k_2+ k_3>0}}\right)^{1/2}\nu^n_{\k}\psi_{k_1}(U_{i0})\psi_{k_2}(U_{0j})\psi_{k_3}(U_{ij})
			\label{eq:AHK_l2_standardized}
		\end{equation}		
		with
		\begin{equation}
			\nu_{\k}^n=V_n\frac{\mu^n_{\k}}{\left(C_1^{\ind{k_1+ k_3>0}}C_2^{\ind{k_2+ k_3>0}}\right)^{1/2}} \quad \forall \k\in\N^{3*}.
			\label{eq:def_nu}
		\end{equation}
	\end{lemma}

Equation \eqref{eq:AHK_l2} is obtained by the AHK representation \eqref{eq:AHK} with uniform variables, and the decomposition of the $L_2$-integrable function $\tau$ on the basis $(\psi_k)_{k\in\N}$. Lemma~\ref{lem:mu_nu} provide two different parametrizations of the distribution of $\phi_\alpha$, either in terms of  $\bm{\mu}$ or $\bm{\nu}^n$. In subsequent proofs, we alternate between these two parametrizations, since each happens to be particularly convenient in different situations.

\subsubsection{A weak convergence lemma}
\label{ssub:weak_conv_seq}	

	Let us define the sets $(\K_j)_{j=1,...,4}$, which form a partition of $\N^{3\ast}$:
	\begin{align*}
		\K_1 &:= \left\{ \k \in \mathbb{N}^{3\ast} : k_1 > 0,\;  k_2 = k_3 = 0 \right\}, \\
		\K_2 &:= \left\{ \k \in \mathbb{N}^{3\ast} : k_2 > 0,\; k_1 = k_3 = 0 \right\}, \\
		\K_3 &:= \{ \k \in \mathbb{N}^{3\ast} : k_1>0, \;k_2>0, \; k_3 = 0 \}, \\
		\K_4 &:= \left\{ \k \in \mathbb{N}^{3\ast} : k_3 > 0 \right\}.	
	\end{align*}

	\begin{lemma}
		\label{lem:weak_conv_means}
		Suppose that Assumptions~\ref{as:DGP},~\ref{as:asym} and~\ref{as:as_lin} hold and let $\bm{\nu}^n$ satisfy~\eqref{eq:def_nu} in Lemma~\ref{lem:mu_nu}. If $\bm{\nu}^n\convLtwo \bm{\nu}^\infty$ for some $\bm{\nu}^\infty$, we have:
		$$\bigg[V_n \overline{Y}, V_n(\widehat{V}_1^{\inf}, \widehat{V}_2^{\inf},  \widehat{V}_{12}^{\inf})V_n\bigg] \convD (L, V_1, V_2, V_{12}),$$
		where, letting $(Z_{\k})_{\k \in \N^{3*}}$ denote an array of i.i.d. standard normal variables,
		\begin{align*}
			L & := \sum_{\k\in\K_1}\nu_{\k}^{\infty}Z_{\k} + \sum_{\k\in\K_2}\nu_{\k}^{\infty}Z_{\k} %\\ & \;
			+ \sum_{\k \in \K_3}\nu_{\k}^{\infty}Z_{k_1,0,0}Z_{0,k_2,0} + \sum_{\k \in \K_4}\nu_{\k}^{\infty}Z_{\k}, \\
			V_1  & :=   \sum_{\k\in\K_4}(\nu_{\k}^{\infty})^{\otimes 2} + \sum_{k_1>0}\left( \nu_{k_1,0,0}^{\infty} + \sum_{k_2 > 0}\nu_{k_1,k_2,0}^{\infty}Z_{0,k_2,0} \right)^{\otimes 2} \\
			V_2 & :=   \sum_{\k\in\K_4}(\nu_{\k}^{\infty})^{\otimes 2} +  \sum_{k_2>0}\left( \nu_{0,k_2,0}^{\infty} + \sum_{k_1 > 0}\nu_{k_1,k_2,0}^{\infty}Z_{k_1,0,0} \right)^{\otimes 2} \\
			V_{12} &:=   \sum_{\k\in\K_{3}\cup\K_{4}} (\nu_{\k}^{\infty})^{\otimes 2}.
		\end{align*}	
	\end{lemma}


	\subsection{Proof of the main results and key lemmas}
We recall that $V_n=V(\overline{Y})^{-1/2}$. For $i=1,...,4$, we also let  $\K_i(\overline{k})=\K_i\cap[0,\overline{k}]^3$, $\K_{i_1...i_p}=\cup_{k=1}^p \K_{i_k}$ and define similarly $\K_{i_1...i_p}(\overline{k})$. Hereafter, we suppose wlog that $\underline{C}:=C_1\wedge C_2\ge 2$ for all $n\ge 1$. The norm symbol $||\cdot||$ stands for the Euclidean norm for vectors and the matrix 2-norm for matrices.

	\subsubsection{Lemma~\ref{lem:decomp}}

	Theorem 3.2., Statement b in \cite{kallenberg1989} ensures that $\mathcal{S}_1\subset \sigma(U_{i0}:i\geq1)$ and $(Y_{ij})_{i,j\geq 1}\indep (U_{i0})_{i\geq 1}|\mathcal{S}_1$. It follows that $E(Y_{ij}|U_{i0})=E(Y_{ij}|(U_{i'0})_{i'\geq 1})=E(Y_{ij}|(U_{i'0})_{i'\geq 1},\mathcal{S}_1)=E(Y_{ij}|\mathcal{S}_1)$. Similarly, $E(Y_{ij}|U_{0j})=E(Y_{ij}|\mathcal{S}_2)$. Theorem 3.2., Statement c in \cite{kallenberg1989} ensures that $\mathcal{S}_{12}\subset \sigma((U_{i0},U_{0j}):i\geq1, j\geq 1)$ and $(Y_{ij})_{i,j\geq 1}\indep (U_{i0},U_{0j})_{i,j\geq 1}|\mathcal{S}_{12}$. Next, $E(Y_{ij}|U_{i0},U_{0j})=E(Y_{ij}|(U_{i'0},U_{0j'})_{i',j'\geq 1})=E(Y_{ij}|(U_{i'0},U_{0j'})_{i',j'\geq 1},\mathcal{S}_{12})=E(Y_{ij}|\mathcal{S}_{12})$.

\medskip
Because $\Cov(Y_{11},Y_{12}|U_{10})=0$, we have	
$$\Omega_1=V(E(Y_{11}|U_{10}))=\Cov(E(Y_{11}|U_{10}),E(Y_{12}|U_{10}))=\Cov(Y_{11},Y_{12}).$$
Similarly, $\Omega_2=\Cov(Y_{11},Y_{12})$. Next, $\Cov(\alpha_i,\beta_j)=0$ by independence of $U_{i0}$ and $U_{0j}$ and then \begin{align*}\Cov(\gamma_{ij},\alpha_i)&=\Cov(E(Y_{ij}|U_{i0},U_{0j}),\alpha_i)-V(\alpha_i)\\
	&=E\left[E(Y_{ij}|U_{i0},U_{0j})E(Y_{ij}|U_{i0})'\right]-E(Y_{11})^{\otimes 2}-V(\alpha_i)\\
	&=E(E(Y_{ij}|U_{i0})^{\otimes 2})-E(Y_{11})^{\otimes 2}-V(\alpha_i)=0\end{align*}
	and similarly $\Cov(\gamma_{ij},\beta_j)=0$. And by definition of $\varepsilon_{ij}$, we have:
	\begin{align*}
	\Cov(\varepsilon_{ij},\alpha_i)&=\Cov(Y_{ij},\alpha_i)-V(\alpha_i)\\&=E\left[(Y_{ij}-\mu_0)\alpha_i'\right]-E(\alpha_i\alpha_i')\\
	&=E\left[E(Y_{ij}-\mu_0|U_{i0})\alpha_i'\right]-E(\alpha_i\alpha_i')=0,
	\end{align*}
	and similarly, $\Cov(\epsilon_{ij},\beta_j)=0$. The last covariance term is
	\begin{align*}
	\Cov(\varepsilon_{ij},\gamma_{ij})&=\Cov(Y_{ij},\gamma_i)-V(\gamma_{ij})\\&=E\left[(Y_{ij}-E(Y_{11}))\gamma_{ij}'\right]-V(\gamma_{ij})\\
	&=E\left[E(Y_{ij}-E(Y_{11})|U_{i0},U_{0j})\gamma_{ij}'\right]-V(\gamma_{ij})\\
	&=V(\gamma_{ij})+\Cov(\alpha_i,\gamma_{ij})+\Cov(\beta_j,\gamma_{ij})-V(\gamma_{ij})=0.
	\end{align*}
	This ensures that $V(Y_{11})=\Omega_1+\Omega_2+\Omega_3+\Omega_4$. $\Box$


\subsubsection{Lemma~\ref{lem:invertible_QF}}

If $p_2<p_1$ then $G^{\otimes 2}$ and $E(G)^{\otimes 2}$ are singular and we have nothing to prove. For $p_2\geq p_1$, let $G_1,...,G_{p_2}$ the columns of $G$ and let $\mu$ and $\Sigma$ the expectation and covariance matrix of $(G_1',...,G_{p_2}')'$. Let $P'\Delta P$ the singular value decomposition of $\Sigma$ with $P$ an orthogonal matrix and $\Delta$ a non negative diagonal matrix. Let $\overline{u}_i\in \mathbb{R}^{p_1p_2}$, for $i=1,...,p_1p_2$, denote the columns of $P' \Delta^{1/2}$. For $Z\sim \mathcal{N}(0,\textrm{I}_{p_1p_2})$ we have $(G_1',...,G_{p_2}')'\stackrel{d}{=}\sum_{i=1}^{p_1p_2}\overline{u}_iZ_i+\mu$ with $\overline{u}'_i\overline{u}_{j}=0$ if $i\neq j$ and $\sum_{i=1}^{p_1p_2}\overline{u}_i\overline{u}'_i=\Sigma$. To prove $P(\det(GG')=0)\in\{0,1\}$, we can assume wlog that $(G_1',...,G_{p_2}')'=\sum_{i=1}^{p_1p_2}\overline{u}_iZ_i+\mu$.

\medskip
Let $\mu_j\in \mathbb{R}^{p_1}$ such that $\mu=(\mu'_1,...,\mu'_{p_2})'$. Let $u_{ji}\in \mathbb{R}^{p_1}$ for $j=1,...,p_2$ such that $\overline{u}_i=(u_{1i}',...,u_{p_2i}')'$ and for notational convenience let $u_{j0}=\mu_j$ and $Z_{0}=1$. Note that $G_j=\sum_{i=1}^{p_1p_2}u_{ji}Z_i+\mu_j=\sum_{i=0}^{p_1p_2}u_{ji}Z_i$ and $GG'=\sum_{j=1}^{p_2}G_jG_j'=\sum_{j=1}^{p_2}\left(\sum_{i=0}^{p_1p_2}u_{ji}Z_i\right)\left(\sum_{i=0}^{p_1p_2}u'_{ji}Z_{i}\right)$. The event $\det(GG')=0$ is equivalent to
\begin{align*}Q(Z_1,...,Z_{p_1p_2})
	&=\det\left(\sum_{j=1}^{p_2}\left(\sum_{i=0}^{p_1p_2}u_{ji}Z_i\right)\left(\sum_{i=0}^{p_1p_2}u'_{ji}Z_{i}\right)\right) \\
	&=\det\left(\sum_{i=0}^{p_1p_2}\sum_{i'=0}^{p_1p_2}Z_iZ_{i'}\sum_{j=1}^{p_2}u_{ji}u'_{ji'}\right)=0.
\end{align*}
$Q$ is a polynomial of $p_1p_2$ independent Gaussian of degree lower or equal to $2p_1p_2$. The set of roots of a non-zero polynomial has zero Lebesgue measure (this can be easily shown by induction on the number of variables, using Fubini Theorem). It follows that $P\left(\det(GG')=0\right)=1$ if $Q(z_1,...,z_{p_1p_2})=0$ for any $(z_1,...,z_{p_1p_2})\in \mathbb{R}^{p_1p_2}$ and $P\left(\det(GG')=0\right)=0$ otherwise.

\medskip

Now assume that $E[G]^{\otimes 2}$ is invertible. If the $u_{ji}$ vectors are all null, $G = E[G]$ and there is nothing to prove. We thus focus on the alternative scenario. The key step consists in proving that $$P(||G^{\otimes 2} - E[G]^{\otimes 2}|| \le \lambda_{\min}(E[G]^{\otimes 2})/2) > 0.$$
Adding and substracting terms and using the triangle inequality and submultiplicativity of the matrix 2-norm, we remark that $||G^{\otimes 2} - E[G]^{\otimes 2}|| \le 2||E[G]||\,||E[G]-G|| + ||E[G]-G||^2.$ Let $u_{ji}^{(\ell)}$ denote the $\ell$-th entry of the vector $u_{ji}$ and $|u|_\infty := \max_{(i,j,\ell) \in [1,\dots,p_1p_2]\times[1,\dots,p_2]\times[1,\dots,p_1]}|u_{ji}^{(\ell)}|$. We have
$$||E[G]-G|| \le p_1p_2|u|_\infty\max_{1\leq i \leq p_1p_2}|Z_i|.$$
Since $(Z_i)_{i=1}^{p_1p_2}$ are independent standard normal variables, we have, for all $\varepsilon>0$, $P(\max_{1\leq i \leq p_1p_2}|Z_i| \leq \varepsilon) = (1-2\Phi(-\varepsilon))^{p_1p_2}>0$. When $\max_{1\leq i \leq p_1p_2}|Z_i| \leq \varepsilon$, remark that $||G^{\otimes 2} - E[G]^{\otimes 2}|| \le 2||E[G]||\varepsilon + \varepsilon^2$. Moreover, $||E[G]||>0$ since $E[G]^{\otimes 2}$ is invertible. Then, choosing $\varepsilon = \lambda_{\min}(E[G]^{\otimes 2})/(8||E[G]||)$, we can check that  $||G^{\otimes 2} - E[G]^{\otimes 2}|| \le \lambda_{\min}(E[G]^{\otimes 2})/2$ and this event happens with strictly positive probability. On this event, thanks to Weyl's inequalities, we have $\lambda_{\min}(G^{\otimes 2}) \ge \lambda_{\min}(E[G]^{\otimes 2})/2>0$. As a result, $P(\det(G^{\otimes 2})\neq 0)>0$, and thus $P(\det(G^{\otimes 2})\neq 0)=1$, meaning that $G^{\otimes 2}$ is invertible almost surely. $\Box$

\subsubsection{Theorem~\ref{thm:point_univ}}

We prove that Theorem~\ref{thm:point_univ} follows from Theorem~\ref{thm:unif_univ}. With $P$ the probability distribution of $\bm{W}^\infty$, let $\tau_P$ satisfy \eqref{eq:AHK}. Then, define $\tau_{1P}$ according to \eqref{eq:def_tau1} and let $\tau_{2P}$ be defined accordingly. Finally, let $H=\{\tau_P,\tau_{1P},\tau_{2P}\}$. Because $H$ is finite, it is compact. Next, if $\Omega_{1P} + \Omega_{2P} = 0$ or $\Omega_{3P}=0$, let $m=V_P(Y_{11})$; otherwise, let $m=\min(V_P(Y_{11}), (\Omega_{1P} + \Omega_{2P})/\Omega_{3P})$. By construction, $P\in \mathcal{P}_{m,H,\RP}^1$, and \eqref{eq:pointwise_valid}, the first result of Theorem \ref{thm:point_univ},  follows from \eqref{eq:valid_unif}. Moreover, if $\Omega_{1P} + \Omega_{2P} > 0$ or $\Omega_{3P}=0$, then $\Omega_{3P} \le m^{-1} (\Omega_{1P}+\Omega_{2P})$, and thus $P\in \mathcal{P}_{m,H,\RP}^{1,G}$. Hence, \eqref{eq:pointwise_exact}, the second result of Theorem \ref{thm:point_univ},  follows from \eqref{eq:exactness_unif}. $\Box$

\subsubsection{Theorem \ref{thm:point_multiv}} % (fold)
\label{ssub:theorem_ref_thm_point_multiv}

We proceed as in the proof of Theorem~\ref{thm:point_univ}. We simply need to check that there exists $m$ such that $m\le \lambda_{\min}(V_P(Y_{11}))$ and either
\begin{equation}
\left[\textrm{range}(\Omega_3)\subseteq \textrm{range}(\Omega_1+\Omega_2) \text{ and } \lambda_{\max}(\Omega_{3P}) \leq m^{-1}\lambda_{\min}^*(\Omega_{1P}+\Omega_{2P})\right]	
	\label{eq:cond1_for_corr_mult}
\end{equation}
or $\big[\|\Omega_{1P}\|\wedge \|\Omega_{2P}\|=0$ and $\lambda_{\min}\left(\Omega_{1P}+\Omega_{2P}+\Omega_{4P}\right)\ge m\big]$. Suppose first that Assumption \ref{as:pointw_multiv}-(i) holds. If $\lambda_{\max}(\Omega_{3P})>0$, let
$$m=\min\left(\lambda_{\min}(V_P(Y_{11})), \frac{\lambda_{\min}^*(\Omega_{1P}+\Omega_{2P})}{\lambda_{\max}(\Omega_{3P})}\right),$$
otherwise, simply let $m=\lambda_{\min}(V_P(Y_{11}))$. In this latter case, \eqref{eq:cond1_for_corr_mult} obviously holds. In the former case, \eqref{eq:cond1_for_corr_mult} holds as well since $m>0$. In both cases, we also have $m\le \lambda_{\min}(V_P(Y_{11}))$.

\medskip

Now, suppose that Assumption \ref{as:pointw_multiv}-(ii) holds. Let
$$m=\min\left(\lambda_{\min}(V_P(Y_{11})), \lambda_{\min}(\Omega_{1P}+\Omega_{2P}+\Omega_{4P})\right).$$
Assumption \ref{as:pointw_multiv}-(ii) ensures that $m>0$. Moreover, $m\le \lambda_{\min}(V_P(Y_{11}))$ and $\big[\|\Omega_{1P}\|\wedge \|\Omega_{2P}\|=0$ and $\lambda_{\min}\left(\Omega_{1P}+\Omega_{2P}+\Omega_{4P}\right)\ge m\big]$. $\Box$

