\subsubsection{Theorem~\ref{thm:unif_univ}} % (fold)

Let us fix a sequence $(P_n)_{n\ge 1}$ in $\mathcal{P}_{m,H,\RP}^1$. \eqref{eq:valid_unif} follows if we prove
\begin{align}
\limsup_{n\to\infty} E_{P_n}[\phi_\alpha] & \le \alpha. \label{eq:for_thm_unif_seq}
\end{align}
To this end, let us consider a subsequence $(P_{\varphi(n)})_{n\ge 1}$. By Lemma \ref{lem:mu_nu}, $(P_n)_{n\ge 1}$ (resp. $(P_{\varphi(n)})_{n\ge 1}$) is associated to a sequence $(\bm{\nu}^n)_{n\ge 1}$ (resp. a subsequence $(\bm{\nu}^{\varphi(n)})_{n\ge 1}$). Now, the proof of Theorem~\ref{thm:unif_univ} is divided in four steps. First, we first prove that there exists a further subsequence $(\bm{\nu}^{\psi(n)})_{n\ge 1}$ that converges in $\ell^2_1$. Second, we show that along $\psi(\cdot)$, $(\widehat{\theta}-\theta)/s\convNor{1}$ for some $s\le \se$. The fourth step proves that \eqref{eq:for_thm_unif_seq} and thus \eqref{eq:valid_unif} hold. Finally, the fourth step shows how to adapt the reasoning to prove \eqref{eq:exactness_unif}.\\
\textbf{Step 1: existence of a further subsequence $(\bm{\nu}^{\psi(n)})_{n\ge 1}$ converging in $\ell^2_1$.}\\ % (fold)
For a fixed $n$, let $\mathcal{V}^n_{m,H,\RP}$ denote the set of $\bm{\nu}^n$ corresponding to $\mathcal{P}_{m,H,\RP}^1$ (we refer to Lemma \ref{lem:compacity_mu_nu} for a more formal definition of $\mathcal{V}_{m,H,\RP}$) and let $\mathcal{V}_{m,H,\RP} := \cup_{n\ge 1} \mathcal{V}_{m,H,\RP}^n$. By Lemma~\ref{lem:compacity_mu_nu}, the closure of $\mathcal{V}_{m,H,\RP}$ ($\overline{\mathcal{V}_{m,H,\RP}}$) is compact in $\ell^2_1$. Thus, $(\bm{\nu}^{\varphi(n)})_{n\ge 1}$, as a sequence in $\overline{\mathcal{V}_{m,H,\RP}}$, admits a converging subsequence, $(\bm{\nu}^{\psi(n)})_{n\ge 1}$ say.\\
% paragraph step_1_existence_of_a_further_subsequence_of_bm_nu_varphi_n___n_ge_1_converging_in_ell_2_n_r (end)
\textbf{Step 2: along $\psi(\cdot)$, $(\widehat{\theta}-\theta)/s\convNor{1}$ for some $s\le \se$.}~\\ % (fold)
We reason here along the subsequence $\psi(\cdot)$. We denote by $\bm{\nu}^\infty$ the limit of $(\bm{\nu}^{\psi(n)})_{n\ge 1}$ and
$$M_n:= (V_{n}(\widehat{\theta}-\theta), V_{n}^2 \widehat{V}_1, V^2_{n} \widehat{V}_2, V^2_{n} \widehat{V}_u).$$
By construction, we have in an almost sure sense
\begin{equation*}
	M_n = (V_{n}\overline{Y} + R_n, V_{n}^2 \widehat{V}_1^{\inf} + R_{1,n}, V^2_{n} \widehat{V}_2^{\inf} + R_{2,n}, V^2_{n} \widehat{V}_u^{\inf} + R_{1,n} + R_{2,n} - R_{12,n}),
\end{equation*}
with $R_n$, $R_{1,n}$, $R_{2,n}$ and $R_{12,n}$ given in Assumptions~\ref{as:as_lin} and  \ref{as:consistent_V}. By definition of $\mathcal{P}_{m,H,\mathcal{Q}}^1$, these remainder terms are $o_P(1)$ terms uniformly over $\mathcal{P}_{m,H,\mathcal{Q}}^1$. This observation together with the fact that $P_{\psi(n)} \in \mathcal{P}_{m,H,\mathcal{Q}}^1$ for every $n$ ensure
\begin{equation*}
	M_{\psi(n)} = (V_{\psi(n)}\overline{Y}, V^2_{\psi(n)} \widehat{V}_1^{\inf}, V^2_{\psi(n)} \widehat{V}_2^{\inf}, V^2_{\psi(n)} \widehat{V}_u^{\inf}) + o_{P_{\psi(n)}}(1).
\end{equation*}
Lemma~\ref{lem:weak_conv_means} and the continuous mapping theorem (CMT) then yield
\begin{align}
M_{\psi(n)} \convD (L, V_1, V_2, V_u),   \label{eq:conv_dist_theta}
\end{align}
where $(L, V_1, V_2)$ is defined in Lemma \ref{lem:weak_conv_means} and $V_u:=V_1+V_2-V_{12}$.\\
Now, let $\Sigma_j(\bm{\nu}) := \sum_{\k \in \K_j}\nu_{\k}^{2}$ for $j=1,\dots,4$. Since $\Sigma_j(\cdot)$ is continuous, $\Sigma_j(\bm{\nu}^{\psi(n)}) \to\Sigma_j^\infty := \Sigma_j(\bm{\nu}^\infty)$ for $j=1,\dots,4$. Then, Lemma~\ref{lem:limit_behaviour_nu} ensures $\min\left(\Sigma_1^\infty,\Sigma_2^\infty,\Sigma_3^\infty\right) = 0$.\\
Suppose first that $\Sigma_3^\infty=0$. By Lemma \ref{lem:weak_conv_means} again, $L\sim\mathcal{N}(0,1)$ and
$$(V_1,V_2,V_u)=(\Sigma_1^\infty+\Sigma_4^\infty, \Sigma_2^\infty+\Sigma_4^\infty,  \Sigma_1^\infty+\Sigma_2^\infty+\Sigma_4^\infty).$$
Moreover, since $\Sigma_1^n+\Sigma_2^n+\Sigma_3^n+\Sigma_4^n=1$ and $\Sigma_3^\infty=0$,  $\Sigma_1^\infty+\Sigma_2^\infty+\Sigma_4^\infty=1$. Hence, by the CMT again,
\begin{equation}
\frac{\widehat{\theta}-\theta}{\se} \convNor{1}, \quad \frac{\se_u}{\se} \convP 1.	
	\label{eq:equiv_usual}
\end{equation}
Now, assume that $\Sigma_3^\infty>0$ and suppose wlog that $\Sigma_2^\infty=0$ (the reasoning is the same with $\Sigma_1^\infty=0$). In this case $L = \sum_{\boldsymbol{k} \in \K_{1}\cup\K_4}\nu_{\k}^{\infty}Z_{\k} + \sum_{\k \in \K_3}\nu_{\k}^{\infty}Z_{k_1,0,0}Z_{0,k_2,0}$ and
\begin{align*}
	V_1 = & \sum_{\k\in\K_4}(\nu_{\k}^{\infty})^{2} + \sum_{k_1>0}\left( \nu_{k_1,0,0}^{\infty} + \sum_{k_2 > 0}\nu_{k_1,k_2,0}^{\infty}Z_{0,k_2,0} \right)^2.
\end{align*}
Then, $L|(Z_{0,k_2,0})_{k_2>0} \sim \mathcal{N}(0,V_1)$. Moreover, because $\Sigma_3^\infty>0$, there exists $\nu_{k^*_1,k^*_2,0}^{\infty}\ne 0$. Thus,
$$\nu_{k^*_1,0,0}^{\infty} + \sum_{k_2 > 0}\nu_{k^*_1,k_2,0}^{\infty}Z_{0,k_2,0} \sim \mathcal{N}\left(\nu_{k^*_1,0,0}^{\infty}, \sum_{k_2 > 0}\nu_{k^*_1,k_2,0}^{\infty\, 2}\right),$$
with $\sum_{k_2 > 0}\nu_{k^*_1,k_2,0}^{\infty\, 2}>0$. As a result, $P(V_1>0)=1$. From this, the CMT and \eqref{eq:conv_dist_theta}, we obtain
$$\frac{\widehat{\theta}-\theta}{\se_1} \convNor{1}.$$
% paragraph step_2 (end)	
\textbf{Step 3: \eqref{eq:for_thm_unif_seq} and \eqref{eq:valid_unif} hold.}\\ % (fold)
By Step 2 and the definition of $\phi_\alpha$, the sequence $v_n := \max(E_{P_n}[\phi_\alpha], \alpha)$ satisfies $\lim_{n \to \infty} v_{\psi(n)}\geq\alpha$. Because the initial subsequence was arbitrary, we obtain, by Urysohn's principle, $\lim_{n \to \infty} v_n\geq\alpha$. This is the same as \eqref{eq:for_thm_unif_seq}. Equation \eqref{eq:valid_unif} follows.\\
% paragraph step_4_conclusion (end)
\textbf{Step 4: Equation \eqref{eq:exactness_unif} holds.}\\  % (fold)
The reasoning is very similar. In this case, $(P_n)_{n\ge 1}$ is a sequence in $\mathcal{P}_{m,H,\RP}^{1,G}$. Step 1 still holds in this case. In Step 2, Lemma \ref{lem:limit_behaviour_nu} shows that $\Sigma_3^\infty =0$. Then, as shown in Step 2, $(\widehat{\theta}-\theta)/\se\convNor{1}$, and $v_n := E_{P_n}[\phi_\alpha]$ satisfies $\lim_{n \to \infty} v_{\psi(n)}=\alpha$. By Urysohn's principle again, $\lim_{n \to \infty} v_n=\alpha$.  Equation \eqref{eq:exactness_unif_multiv} follows. $\Box$

% paragraph step_5_conclusion (end)

% subsubsection Theorem_inf_unif_scalar (end)


\subsubsection{Theorem \ref{thm:unif_multiv}} % (fold)
\label{ssub:thm_inf_unif_multiv}

To obtain \eqref{eq:valid_unif_multiv} and \eqref{eq:exactness_unif_multiv} (\eqref{eq:valid_unif_multiv_bon} is proved below), the structure of the proof is the same as that of Theorem \ref{thm:unif_univ}, and only Step 2 needs to be modified. We now prove that $\widetilde{F} \convD \chi^2(d)$ for some $F$-statistic $\widetilde{F}$ satisfying $\widetilde{F}\le F$. We let, as before
$$M_n:=(V_{n}(\widehat{\theta}-\theta), V_n \widehat{V}_1 V_n, V_{n} \widehat{V}_2, V_{n}, V_{n} \widehat{V}_u V_{n}).$$
Then, by definition of the remainder terms $R_n$, $R_1$, $R_2$ and $R_{12}$ in Assumptions~\ref{as:as_lin} and~\ref{as:consistent_V}, the definition of $\mathcal{P}_{m,H,\mathcal{Q}}^d$, and Lemma \ref{lem:weak_conv_means}, $M_{\psi(n)}\convD (L,V_1,V_2,V_u)$. As above, we analyze separately the cases $\Sigma_3^{\infty}= 0$ and $\Sigma_3^{\infty}\ne 0$.\\
\textbf{Case $\Sigma_3^{\infty}= 0$.}\\
As in the proof of Theorem \ref{thm:unif_univ}, $L\sim\mathcal{N}(0,\Id)$ and
$$(V_1,V_2,V_u)=(\Sigma_1^\infty+\Sigma_4^\infty, \Sigma_2^\infty+\Sigma_4^\infty,  \Sigma_1^\infty+\Sigma_2^\infty+\Sigma_4^\infty).$$
Moreover, $\Sigma_3^{\infty}= 0$ implies that $\Sigma_1^\infty+\Sigma_2^\infty+\Sigma_4^\infty=\Id$. Let us define
\begin{align*}
	g_n: \; \Rb^d\times(\mathrm{S}_+^d)^{2}\times\mathrm{S}^d &\to \; \Rb \\
	(x_1,x_2,x_3,x_4)  & \mapsto \liminf_{\lambda\downarrow 0} \min\big\{x_1'(\lambda V_n^2 + x_2)^{-1}x_1, x_1'(\lambda V_n^2 + x_3)^{-1}x_1, \\
    & \hspace{2.8cm} x_1'(\lambda V_n^2 + x_4)^{-1}x_1 \big\} \cap \Rb^+, \\
	g:\; \Rb^d\times(\mathrm{S}_+^d)^{2}\times\mathrm{S}_{++}^d & \to \; \Rb \\
	(x_1,x_2,x_3,x_4)  & \mapsto \;  x_1' x_4^{-1} x_1.
\end{align*}
We wish to prove that
\begin{equation}
g_{\psi(n)}(M_{\psi(n)}) \convD g(L,V_1,V_2,V_u) \sim\chi^2(d).
    \label{eq:conv_g_multiv}
\end{equation}
To this end, we check the conditions of Theorem 18.11 in \cite{vanderVaart2000}, which is an extended CMT. It suffices to prove that for every $(x_{1n},x_{2n},x_{3n},x_{4n})_{n\ge 1}$ converging to $(x_1, \Sigma_1^\infty+\Sigma_4^\infty, \Sigma_2^\infty+\Sigma_4^\infty, \Id) \in \Rb^d\times (\mathrm{S}^d_+)^3$, we have
\begin{equation}
	\label{eq:extended_continuity_argument_normal_case}
	\lim_{n\to\infty} g_n(x_{1n},x_{2n},x_{3n},x_{4n}) = g\left(x_1,\Sigma_1^\infty+\Sigma_4^\infty,\Sigma_2^\infty+\Sigma_4^\infty,\Id\right).
\end{equation}
For $n$ large enough, $x_{4n}$ is symmetric positive definite; we consider such $n$'s hereafter. Then, $x_1'(\lambda V_n^2 + x_j)^{-1}x_1\ge 0$ for $j\in\{2,3,4\}$. Hence, for any $x_4$ symmetric positive definite,
\begin{align*}
	g_n(x_1,x_2,x_3,x_4)= & \liminf_{\lambda\downarrow 0} \min\left\{x_1'(\lambda V_n^2 + x_2)^{-1}x_1, x_1'(\lambda V_n^2 + x_3)^{-1}x_1, x_1'(\lambda V_n^2 + x_4)^{-1}x_1 \right\},\\
	= & \min\left\{\lim_{\lambda\downarrow 0} x_1'(\lambda V_n^2 + x_2)^{-1}x_1, \lim_{\lambda\downarrow 0} x_1'(\lambda V_n^2 + x_3)^{-1}x_1, \lim_{\lambda\downarrow 0} x_1'(\lambda V_n^2 + x_4)^{-1}x_1 \right\} \\
	= & \min\left\{\lim_{\lambda\downarrow 0} x_1'(\lambda V_n^2 + x_2)^{-1}x_1, \lim_{\lambda\downarrow 0} x_1'(\lambda V_n^2 + x_3)^{-1}x_1, x_1' x_4^{-1}x_1 \right\},
\end{align*}
where the second equality follows since the minimum function is continuous, and the functions $\lambda \mapsto x_1'(\lambda V_n^2 + x_j)^{-1}x_1$, $j\in\{2,3,4\}$, are decreasing. Let us define
\begin{align*}
	u_n & = \lim_{\lambda\downarrow 0} x_{1n}'(\lambda V_n^2 + x_{2n})^{-1}x_{1n}, \\
	v_n & = \lim_{\lambda\downarrow 0} x_{1n}'(\lambda V_n^2 + x_{3n})^{-1}x_{1n}, \\
	w_n & = x_{1n}' x_{4n}^{-1}x_{1n},
\end{align*}
so that $g_n(x_{1n},x_{2n},x_{3n},x_{4n})=\min\{u_n,v_n,w_n\}$. By continuity, $\lim_{n\to\infty}w_n = x_1' x_1$. Thus, to prove the result, it suffices to show that $\liminf u_n\ge x_1' x_1$ and $\liminf v_n\ge x_1' x_1$. We focus on $u_n$ as the reasoning is the same for $v_n$. Since $x_{2n}\to \Sigma_1^\infty+\Sigma_2^\infty = I - \Sigma_4^\infty$, there exists $A_n$ symmetric positive, $A_n\to 0$, such that $\Id + A_n \gg x_{2n}$. Thus,
$$x_{1n}'(\lambda V_n^2 + x_{2n})^{-1}x_{1n}\ge x_{1n}'(\lambda V_n^2 + \Id + A_n)^{-1}x_{1n}.$$
Letting $\lambda\to 0$ on the left- and then on the right-hand side, we obtain
$$u_n \ge \overline{w}_n:=x_{1n}'(\Id + A_n)^{-1}x_{1n}.$$
Moreover, $\lim_{n\to\infty}\overline{w}_n=x_1' x_1$. Equation~\eqref{eq:extended_continuity_argument_normal_case} follows. Then, by Theorem 18.11 in \cite{vanderVaart2000}, \eqref{eq:conv_g_multiv} holds as well.\\
\textbf{Case $\Sigma_3^{\infty}\ne 0$.}\\
As in the univariate case, since $\min(\|\Sigma_1^{\infty}\|,\|\Sigma_2^{\infty}\|,\|\Sigma_3^{\infty}\|)=0$,
we can assume wlog $\Sigma_2^{\infty}=0$. We wish to prove that
\begin{equation}
\widetilde{F}:=\lim_{\lambda\downarrow 0} (\widehat{\theta}-\theta)'(\lambda \Id+\widehat{V}_1)^{-1} (\widehat{\theta}-\theta) \convD \chi^2(d).
\label{eq:conv_g_nongG}
\end{equation}
To this end, we use
\begin{equation}
(V_n(\widehat{\theta}-\theta), V_n \widehat{V}_1 V_n)\convD (L,V_1)
    \label{eq:conv_with_V1}
\end{equation}
and we apply the same extended CMT as above, to the functions
\begin{align*}
	g_n: \; \Rb^d\times \mathrm{S}_+^d &\to \; \Rb \\
	(x_1,x_2)  & \mapsto \lim_{\lambda\downarrow 0} x_1'(\lambda V_n^2 + x_2)^{-1}x_1, \\
	g: \; \Rb^d\times \mathrm{S}_{++}^d & \to \; \Rb \\
	(x_1,x_2)  & \mapsto \;  x_1' x_2^{-1} x_1.
\end{align*}

We first prove that $V_1$ is invertible almost surely. Let
\begin{equation*}
	V_{1,\overline{k}}:= \sum_{\k \in \K_4(\overline{k})}\nu_{\k}^{\infty \otimes 2}+\sum_{0<k_1\leq \overline{k}}\left(\nu_{k_1,0,0}^{\infty}+\sum_{k_2>0}\nu_{k_1,k_2,0}^{\infty}Z_{0,k_2,0}\right)^{\otimes 2}.
\end{equation*}
Let $G_{\overline{k}}$ denote the matrix with first rows equal to $\nu^{\infty}_{\k}$ for $\k \in \K_3(\overline{k})$ and next rows equal to $\nu_{k_1,0,0}^{\infty}+\sum_{k_2>0}\nu_{k_1,k_2,0}^{\infty}Z_{0,k_2,0}$ for $k_1=1,...,\overline{k}$, so that $V_{1,\overline{k}}=G_{\overline{k}}^{\otimes 2}$. As $\sum_{\k \in \N^{3\ast}}||\nu^{\infty}_{\k}||^2<\infty$, all the components of $\E(G_{\overline{k}})^{\otimes 2}$ are arbitrarily close to the components of $\sum_{\k \in \K_{14}}\nu^{\infty \otimes 2}_{\k}=\Sigma_1^\infty+\Sigma_4^\infty$ for sufficiently large $\overline{k}$. By Lemma \ref{lem:limit_behaviour_nu} and $\Sigma_2^{\infty}=0$, $\lambda_{\min}\left[\Sigma_1^\infty + \Sigma_4^\infty \right] > 0$. Hence, for $\overline{k}$ large enough, $\E(G_{\overline{k}})^{\otimes 2}$ is invertible. Then, by Lemma~\ref{lem:invertible_QF}, $V_{1,\overline{k}}$ is invertible almost surely.
Since $V_{1,\overline{k}}$ and $V_1-V_{1,\overline{k}}$ are both symmetric non-negative matrices,
this implies that $V_1$ is invertible with probability 1. This implies that the support of the distribution of $(L,V_1)$ is at most $\Rb^d\times\mathrm{S}_{++}^d$.

\medskip
Now, to apply Theorem 18.11 in \cite{vanderVaart2000}, we prove that for every sequence $(x_1^n,x_2^n)$ in $\Rb^d\times\mathrm{S}_+^d$ converging to $(x_1,x_2) \in \Rb^d\times\mathrm{S}_{++}^d$, we have
\begin{equation}
	\label{eq:extended_continuity_argument}
	\lim_{n\to\infty} g_n(x_1^n,x_2^n) = g(x_1,x_2),
\end{equation}
Since $x_2^n$ converges to $x_2$, $x_2^n$ is strictly positive definite for $n$ large enough. Then, $x_2^n$ is strictly positive definite and $g_n(x_1^n,x_2^n) = (x_1^n)' (x_2^n)^{-1} x_1^n = g(x_1^n,x_2^n)$. Continuity of $g$ on $\Rb^d\times\mathrm{S}_{++}^d$ ensures that \eqref{eq:extended_continuity_argument} holds. Then, by Theorem 18.11 in \cite{vanderVaart2000} and \eqref{eq:conv_with_V1}, we obtain
$$\widetilde{F} \convD L'V_1^{-1} L.$$
Now, as in Theorem \ref{thm:unif_multiv}, we have $L|(Z_{0,k_2,0})_{k_2>0} \sim \mathcal{N}(0,V_1)$. Thus, conditional on the $(Z_{0,k_2,0})_{k_2>0}$ and then unconditionally, $L'V_1^{-1} L \sim \chi^2(d)$. Eq. \eqref{eq:conv_g_nongG} follows.\\ 
\textbf{Proof of \eqref{eq:valid_unif_multiv_bon}} % (fold)
\label{par:proof_of_eqref}\\
Let $e_k$ denote the $k$-th canonical vector and $\widehat{\theta}_k:=e_k'\widehat{\theta}$, $\theta_{0k}:=e_k'\theta_0$. We first show that we can apply Theorem \ref{thm:unif_univ} to the parameter $\theta_{0k}$ and its estimator $\widehat{\theta}_k$. It suffices to prove that
\begin{align*}
R_n^{(k)}:=& V(\overline{Y}^{(k)})^{-1/2}[\widehat{\theta}_k-\theta_{0k} - \overline{Y}^{(k)}], \\
R^{(k)}_{j,n}:= & V(\overline{Y}^{(k)})^{-1/2}e_k'\left[\widehat{V}_j - \widehat{V}^{\inf}_j\right]e_kV(\overline{Y}^{(k)})^{-1/2}	
\end{align*}
satisfy \eqref{eq:unif_reste}, where we recall that $\overline{Y}^{(k)}$ is the $k$-th component of $\overline{Y}$. First, we have
	$$\widehat{\theta}_k - \theta_{0k} = \overline{Y}^{(k)}+ e_k'V(\overline{Y})^{1/2}R_n.$$
	with $R_n$ satisying \eqref{eq:unif_reste}. Then, $R_n^{(k)} = V(\overline{Y}^{(k)})^{-1/2} e_k'V(\overline{Y})^{1/2}R_n$. Moreover, letting $x_n:=V(\overline{Y})^{1/2}e_k$,
$$	\left|V(\overline{Y}^{(k)})^{-1/2} e_k'V(\overline{Y})^{1/2}R_n\right| = \left|\left(\frac{x_n}{\|x_n\|}\right)'R_n\right| \le \|R_n\|,$$
	where the inequality follows by Cauchy-Schwarz inequality. Thus, $R_n^{(k)}$ satisfies the first part of  \eqref{eq:unif_reste}. Next, we have, for $j\in\{1,2,12\}$,
	$$e_k'(\widehat{V}_j - \widehat{V}^{\inf}_j)e_k = e_k'V(\overline{Y})^{1/2} R_{j,n} V(\overline{Y})^{1/2} e_k,$$
	where $\|R_{j,n}\|=o_P(1)$. Thus,
	\begin{align*}
	R^{(k)}_{j,n} = &
	\frac{e_k'V(\overline{Y})^{1/2} R_{j,n} V(\overline{Y})^{1/2} e_k}{e_k'V(\overline{Y}) e_k} \\
	= & \frac{x_n'R_{j,n} x_n}{x_n' x_n}\le  \|R_{j,n}\|,
	\end{align*}
which implies that $R^{(k)}_{j,n}$ satisfies the second part of  \eqref{eq:unif_reste}.

\medskip
Then, by definition of $\mathcal{P}_{m,H,\RP}^{d,b}$ and Theorem \ref{thm:unif_univ}, we have, for all $k\in\{1,...,d\}$,
$$\limsup_{n\to\infty} \sup_{P\in\mathcal{P}_{m,H,\RP}^{d,b}} E_{P}[\ind{|t^k|>z_{1-\frac{\alpha}{2d}}}]\le \frac{\alpha}{d}.$$
As a result,
\begin{align*}
	\limsup_{n\to\infty} \sup_{P\in\mathcal{P}_{m,H,\RP}^{d,b}} E_P[\phi_{\alpha}^b] & = \limsup_{n\to\infty} \sup_{P\in\mathcal{P}_{m,H,\RP}^{d,b}} E_P\left[\max_{k=1,...,d}\ind{|t^k|>z_{1-\frac{\alpha}{2d}}}\right] \\
	& \le \limsup_{n\to\infty} \sup_{P\in\mathcal{P}_{m,H,\RP}^{d,b}} \sum_{k=1}^d E_P\left[\ind{|t^k|>z_{1-\frac{\alpha}{2d}}}\right] \\
	& \le \sum_{k=1}^d \limsup_{n\to\infty}  \sup_{P\in\mathcal{P}_{m,H,\RP}^{d,b}}  E_P\left[\ind{|t^k|>z_{1-\frac{\alpha}{2d}}}\right] \\
	& \le \alpha. \qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad
\end{align*}
Note that the first inequality is strict if the $(t^k)_{k=1,...,d}$ are independent. $\Box$

