\subsection{Lemma~\ref{lem:mu_nu}}

The Aldous-Hoover-Kallenberg representation ensures $Y_{ij}=\tau(U_{i0},U_{0j},U_{ij})$. Next, considering $\mu_{\k}=E\left(Y_{ij}\psi_{k_1}(U_{i0})\psi_{k_2}(U_{0j})\psi_{k_3}(U_{ij})\right)$, Equation  \eqref{eq:AHK_l2} holds.
Because $E(Y_{11})=0$, we have $\mu^n_{0,0,0}=0$. There remains to prove $V(\overline{Y})$ is nonsingular for every $n \ge 1$ under Assumptions~\ref{as:DGP},~\ref{as:asym} and~\ref{as:as_lin} (the second representation in~\eqref{eq:AHK_l2_standardized} is straightforward once invertibility of $V(\overline{Y})$ has been obtained). Using Assumption~\ref{as:DGP} and the corresponding AHK representation, we can write
\begin{align*}
	V(\overline{Y}) & = (C_1C_2)^{-1}V(Y_{11}) + \frac{(C_2-1)}{C_2C_1}E[Y_{11}Y_{12}'] + \frac{(C_1-1)}{C_1C_2}E[Y_{11}Y_{21}'] \\
	& = (C_1C_2)^{-1}V(Y_{11}) + \frac{(C_2-1)}{C_2C_1}V[E[Y_{11}\mid U_{10}]] + \frac{(C_1-1)}{C_1C_2}V[E[Y_{11}\mid U_{01}]].
\end{align*}
By Assumption~\ref{as:as_lin}, $V(Y_{11})$ is nonsingular. We conclude that for every $n \ge 1$, $V(\overline{Y}) \gg (C_1C_2)^{-1}V(Y_{11})$ so that $V(\overline{Y})$ is itself nonsingular. $\Box$

\subsection{Lemma~\ref{lem:weak_conv_means}}

	Let us define
	\begin{align*}
		\widetilde{V}_1 := & \frac{1}{C_1^2}\sum_{i=1}^{C_1}\left(\frac{1}{C_2}\sum_{j=1}^{C_2}V_nY_{ij}\right)^{\otimes 2}, \\
		\widetilde{V}_2 := & \frac{1}{C_2^2}\sum_{j=1}^{C_2}\left(\frac{1}{C_1}\sum_{i=1}^{C_1}V_nY_{ij}\right)^{\otimes 2},
	\end{align*}
	and define $\widetilde{V}_{12}$ similarly. Let us also introduce $\xi_{ij} := V_nY_{ij}$. For a square matrix $A$, $A^{\dagger}$ denotes its Moore-Penrose inverse. We first prove the convergence in distribution of $\left(V_n\overline{Y}, \widetilde{V}_1,\widetilde{V}_2,\widetilde{V}_{12}\right)$ to $(L,V_1,V_2, V_{12})$ (first step). Next, we show that $\widetilde{V}_j=V_n\widehat{V}_j^{\inf}V_n+o_p(1)$ for $j=1,2,12$. This ensures the convergence in distribution of $\left(V_n\overline{Y}, V_n(\widehat{V}_1^{\inf},\widehat{V}_2^{\inf},\widehat{V}_{12}^{\inf})V_n\right)$ to $(L,V_1,V_2,V_{12})$ (second step).

	\medskip

	\noindent\textbf{First step: Convergence of $\left(V_n\overline{Y}, \widetilde{V}_1,\widetilde{V}_2,\widetilde{V}_{12}\right)$ to $(L,V_1,V_2, V_{12})$.} Prior to proving the result, we need to introduce a number of objects.

	\medskip
	Let $\mathcal{K}_j(\overline{k}):=\mathcal{K}_j\cap\{\k\in \mathbb{N}^{3\ast}:\max(k_1,k_2,k_3)\leq \overline{k}\}$ and
	 \begin{align*}\xi_{ij}(\overline{k}):=&\sum_{\k\in \K_1(\overline{k})}\sqrt{C_1}\nu^n_{k_1,0,0}\psi_{k_1}(U_{i0})+\sum_{\k\in \K_2(\overline{k})}\sqrt{C_2}\nu^n_{0,k_2,0}\psi_{k_2}(U_{0j})
		\\&+\sum_{\k \in\K_{3}(\overline{k})\cup \K_{4}(\overline{k})} \sqrt{C_1C_2}\nu^n_{\k}\psi_{k_1}(U_{i0}) \psi_{k_2}(U_{0j})\psi_{k_3}(U_{ij}),\\
		\overline{\xi}(\overline{k}):=&\frac{1}{C_1C_2} \sum_{i,j} \xi_{ij}(\overline{k}),
		\\ \widetilde{V}_1(\overline{k}):=&\frac{1}{C^2_1}\sum_{i=1}^{C_1}\left(\frac{1}{C_2}\sum_{j=1}^{C_2}\xi_{ij}(\overline{k})\right)^{\otimes 2},\\ \widetilde{V}_2(\overline{k}):=&\frac{1}{C^2_2}\sum_{j=1}^{C_2}\left(\frac{1}{C_1}\sum_{i=1}^{C_1}\xi_{ij}(\overline{k})\right)^{\otimes 2}, \\
		\widetilde{V}_{12}(\overline{k}):=&\frac{1}{(C_1C_2)^2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}\left(\xi_{ij}(\overline{k})\right)^{\otimes 2}.
	\end{align*}
	Let $\Lambda_n$, $\Lambda_n(\overline{k})$ the following quantities:
	\begin{align*}
		\Lambda_n:=&\left(V_n\overline{Y},\widetilde{V}_1,\widetilde{V}_2,\widetilde{V}_{12}\right),\\
		\Lambda_n(\overline{k}):=&\left(\overline{\xi }(\overline{k}),\widetilde{V}_1(\overline{k}),\widetilde{V}_2(\overline{k}),\widetilde{V}_{12}(\overline{k})\right).
	\end{align*}
	We also introduce the limit counterparts of $\Lambda_n$ and $\Lambda_n(\overline{k})$, namely $\Lambda_\infty$ and $\Lambda_{\infty}(\overline{k})$:
	\begin{align*}
		\Lambda_\infty := & \left(L,V_1,V_2,V_{12}\right), \\
		\Lambda_\infty(\overline{k}) := & \left(L(\overline{k}),V_1(\overline{k}),V_2(\overline{k}),V_{12}(\overline{k})\right),
	\end{align*}
	where $L(\overline{k})$, $V_1(\overline{k})$, $ V_2(\overline{k})$ and $V_{12}(\overline{k})$ are similar to $L$, $V_1$, $V_2$ and $V_{12}$ with $(\K_j)_{j=1,\dots,4}$ replaced with $(\K_j(\overline{k}))_{j=1,\dots,4}$ and the sums on $k_j>0$ are replaced with sums on $\overline{k}\geq k_j>0$ for $j=1,2,3$.

	\medskip

	We wish to prove convergence in distribution of $\Lambda_n$ to $\Lambda_\infty$. This is equivalent to proving that for any bounded Lipschitz function $h$,
	\begin{equation}
		\label{eq:weak_conv_result}
		\lim_n\left| \E[h(\Lambda_n)] - \E[h(\Lambda_\infty)]  \right| =0.
	\end{equation}
	Let $\mathcal{M}_d(\Rb)$ denote the space of real square matrices of dimension $d$. We remark that $\Lambda_n$ and $\Lambda_\infty$ belong to $\Rb^d \times \mathcal{M}_d(\Rb) \times \mathcal{M}_d(\Rb) \times \mathcal{M}_d(\Rb)$. We need to introduce a norm $||.||_\Lambda$ on that space. For any $A := (A_1,A_2,A_3,A_4) \in \Rb^d \times \mathcal{M}_d(\Rb) \times \mathcal{M}_d(\Rb) \times \mathcal{M}_d(\Rb)$, we write
	\begin{equation*}
		||A||_\Lambda := \sum_{\ell = 1}^4||A_\ell||.
	\end{equation*}
	For some $C_h$, the triangle and Lipschitz inequalities ensure
		\begin{align}
		\left| \E[h(\Lambda_n)] - \E[h(\Lambda_\infty)]  \right| 
		\leq & C_h\left\{ \E\left[||\Lambda_n - \Lambda_n(\overline{k})||_\Lambda\right] + \E\left[||\Lambda_\infty - \Lambda_\infty(\overline{k})||_\Lambda\right] \right\} \nonumber \\
		& + \left| \E[h(\Lambda_n(\overline{k}))] - \E[h(\Lambda_\infty(\overline{k}))]  \right|.
		\label{eq:fundamental_bound}
	\end{align}
and next it is sufficient to prove $\lim_{\overline{k}}\limsup_{n}\E\left[||\Lambda_n - \Lambda_n(\overline{k})||_\Lambda\right] =0$, $\lim_{\overline{k}}\E\left[||\Lambda_\infty - \Lambda_\infty(\overline{k})||_\Lambda\right]=0$ and $\lim_n \left| \E[h(\Lambda_n(\overline{k}))] - \E[h(\Lambda_\infty(\overline{k}))]  \right|=0$ for any $\overline{k}$ .

	\medskip

	\textbf{Substep 1:  $\lim_{\overline{k}}\limsup_{n}\E\left[||\Lambda_n - \Lambda_n(\overline{k})||_\Lambda\right]=0$.}

	We have:
	\begin{align}
		\E\left[||\Lambda_n - \Lambda_n(\overline{k})||_\Lambda\right] = &  \E\left[\left|\left|V_n\overline{Y}-\overline{\xi}(\overline{k})\right|\right|\right] + \E\left[\left|\left|\widetilde{V}_1-\widetilde{V}_1(\overline{k})\right|\right|\right] \nonumber  \\
		&  ~~~ + \E\left[\left|\left|\widetilde{V}_2-\widetilde{V}_2(\overline{k})\right|\right|\right] + \E\left[\left|\left|\widetilde{V}_{12}-\widetilde{V}_{12}(\overline{k})\right|\right|\right] .
		\label{eq:norm_equivalence_decomposition}
	\end{align}
	We handle the terms on the right-hand side of~\eqref{eq:norm_equivalence_decomposition} separately. First, we can write: 	\begin{align*}
		& \E\left[\left|\left|V_n\overline{Y}-\overline{\xi}(\overline{k})\right|\right|\right]^2 \nonumber\leq \E\left[\left|\left|V_n\overline{Y}-\overline{\xi}(\overline{k})\right|\right|^2\right]\\
		= & \E\left[\left|\left|\sum_{\k\in \cup_{\ell=1}^4\left(\K_{\ell}\backslash \K_{\ell}(\overline{k})\right)}V_n\mu_{\k}\frac{1}{C_1C_2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}\psi_{k_1}(U_{i0})\psi_{k_2}(U_{0j})\psi_{k_3}(U_{ij})\right|\right|^2\right] \nonumber\\
		= & \sum_{\k\in \cup_{\ell=1}^4\left(\K_{\ell}\backslash \K_{\ell}(\overline{k})\right)} ||\nu^n_{\k}||^2.
		\label{eq:control_y_bar}
	\end{align*}

Using the matrix identity $A^{\otimes 2}-B^{\otimes 2}=(A+B)(A-B)'/2+(A-B)(A+B)'/2$, plus the triangle and Cauchy-Schwarz inequalities, we obtain:
\begin{align*}
	&\E\left[\left|\left|\widetilde{V}_1-\widetilde{V}_1(\overline{k})\right|\right|\right] \\
	&\leq \frac{1}{2C_1}\E\left[\left|\left|\left(\frac{1}{C_2}\sum_{j=1}^{C_2}\left(\xi_{1j}+\xi_{1,j}(\overline{k})\right)\right)\left(\frac{1}{C_2}\sum_{j=1}^{C_2}\left(\xi_{1j}-\xi_{1j}(\overline{k})\right)\right)'\right|\right|\right]\\
	&~~~~+\frac{1}{2C_1}\E\left[\left|\left|\left(\frac{1}{C_2}\sum_{j=1}^{C_2}\left(\xi_{1j}-\xi_{1j}(\overline{k})\right)\right)\left(\frac{1}{C_2}\sum_{j=1}^{C_2}\left(\xi_{1j}+\xi_{1j}(\overline{k})\right)\right)'\right|\right|\right]\\
	&\leq \frac{1}{C_1}\E\left[\left|\left|\frac{1}{C_2}\sum_{j=1}^{C_2}\left(\xi_{1j}+\xi_{1j}(\overline{k})\right)\right|\right|\times \left|\left|\frac{1}{C_2}\sum_{j=1}^{C_2}\left(\xi_{1j}-\xi_{1j}(\overline{k})\right)\right|\right|\right]
	\\
	&\leq \sqrt{\frac{1}{C_1}\E\left[\left|\left|\frac{1}{C_2}\sum_{j=1}^{C_2}\left(\xi_{1j}+\xi_{1j}(\overline{k})\right)\right|\right|^2\right]}\times\sqrt{\frac{1}{C_1}\E \left[\left|\left|\frac{1}{C_2}\sum_{j=1}^{C_2}\left(\xi_{1j}-\xi_{1j}(\overline{k})\right)\right|\right|^2\right]}.
\end{align*}
We further have: 
\begin{align*}
	\frac{1}{C_1}\E\left[\left|\left|\frac{1}{C_2}\sum_{j=1}^{C_2}\left(\xi_{1j}-\xi_{1j}(\overline{k})\right)\right|\right|^2\right] 
	= & \sum_{\k \in \cup_{\ell\neq 2}\left(\K_{\ell}\backslash \K_{\ell}(\overline{k})\right)}||\nu^n_{\k}||^2+\frac{1}{C_1}\sum_{\k \in \K_2\backslash\K_2(\overline{k})}||\nu^n_{\k}||^2 \nonumber \\
	\leq & \sum_{\k\in \cup_{\ell=1}^4\left(\K_{\ell}\backslash\K_{\ell}(\overline{k})\right)}||\nu^n_{\k}||^2
\end{align*}
Orthogonality of the $(\psi_k)_{k\geq 0}$ in $L^2([0,1])$ ensures that $\xi_{1j}-\xi_{1j}(\overline{k})$ and $\xi_{1j}(\overline{k})$ are uncorrelated. Next,
\begin{align*}
\frac{1}{C_1}\E\left[\left|\left|\frac{1}{C_2}\sum_{j=1}^{C_2}\left(\xi_{1j}+\xi_{1j}(\overline{k})\right)\right|\right|^2\right]&=\frac{1}{C_1}\E\left[\left|\left|\frac{1}{C_2}\sum_{j=1}^{C_2}\left(\xi_{1j}-\xi_{1j}(\overline{k})\right)\right|\right|^2\right]+\frac{4}{C_1}\E\left[\left|\left|\frac{1}{C_2}\sum_{j=1}^{C_2}\xi_{1j}(\overline{k})\right|\right|^2\right]\\
&\leq 4 \sum_{\k \in \N^{3*}}	||\nu^n_{\k}||^2
\end{align*}
Similar inequalities hold for $\E\left[\left|\left|\widetilde{V}_2-\widetilde{V}_2(\overline{k})\right|\right|\right]$. As for $\E\left[\left|\left|\widetilde{V}_{12}-\widetilde{V}_{12}(\overline{k})\right|\right|\right]$, the following holds true:
\begin{align*}
	\E\left[\left|\left|\widetilde{V}_{12}-\widetilde{V}_{12}(\overline{k})\right|\right|\right] 
	&\leq \frac{1}{C_1C_2}\E\left[\left|\left|\xi_{11}+\xi_{11}(\overline{k})\right|\right|\times \left|\left|\xi_{11}-\xi_{11}(\overline{k})\right|\right|\right]	\\
	&\leq \sqrt{\frac{1}{C_1C_2}\E\left[\left|\left|\xi_{11}+\xi_{11}(\overline{k})\right|\right|^2\right]}\times\sqrt{\frac{1}{C_1C_2}\E \left[\left|\left|\xi_{11}-\xi_{11}(\overline{k})\right|\right|^2\right]},
\end{align*}
with \begin{align*}&\frac{1}{C_1C_2}\E \left[\left|\left|\xi_{11}-\xi_{11}(\overline{k})\right|\right|^2\right]\\
	&=\frac{1}{C_2}\sum_{\k \in \left(\mathcal{K}_1\backslash\mathcal{K}_1(\overline{k})\right)}\left|\left|\nu^n_{\k}\right|\right|^2+\frac{1}{C_1}\sum_{\k \in \left(\mathcal{K}_2\backslash\mathcal{K}_2(\overline{k})\right)}\left|\left|\nu^n_{\k}\right|\right|^2+\sum_{\k \in \cup_{\ell=3}^4\left(\mathcal{K}_{\ell}\backslash\mathcal{K}_{\ell}(\overline{k})\right)}\left|\left|\nu^n_{\k}\right|\right|^2\\
	&\leq \sum_{\k\in \cup_{\ell=1}^4\left(\K_{\ell}\backslash\K_{\ell}(\overline{k})\right)}||\nu^n_{\k}||^2
	\end{align*}
and
\begin{align*}
	\frac{1}{C_1C_2}\E \left[\left|\left|\xi_{11}+\xi_{11}(\overline{k})\right|\right|^2\right]&=\frac{1}{C_1C_2}\E \left[\left|\left|\xi_{11}-\xi_{11}(\overline{k})\right|\right|^2\right]+\frac{4}{C_1C_2}\E \left[\left|\left|\xi_{11}(\overline{k})\right|\right|^2\right]\\
	&\leq 4\sum_{\k \in \N^{3*}}	||\nu^n_{\k}||^2.
	\end{align*}
Coming back to~\eqref{eq:norm_equivalence_decomposition}, we deduce that 
\begin{align}
		\E\left[||\Lambda_n - \Lambda_n(\overline{k})||_\Lambda\right] \leq & \left(1+6 \left(\sum_{\k \in \N^{3*}}	||\nu^n_{\k}||^2\right)^{1/2}\right)\left( \sum_{\k\in \cup_{\ell=1}^4\left(\K_{\ell}\backslash\K_{\ell}(\overline{k})\right)}||\nu^n_{\k}||^2\right)^{1/2}
	\end{align}
Note that for any $A\subseteq \N^{3*}$, we have by the reverse triangle inequality $$\left|\left(\sum_{\k \in A}	||\nu^n_{\k}||^2\right)^{1/2}-\left(\sum_{\k \in A}	||\nu^{\infty}_{\k}||^2\right)^{1/2}\right|\leq \left(\sum_{\k \in A}	||\nu^n_{\k}-\nu^{\infty}_{\k}||^2\right)^{1/2}.$$ 
This and convergence of $\bm{\nu}^n$ to $\bm{\nu}^{\infty}$ in $\ell^2$ ensure $\lim_n \sum_{\k \in A}	||\nu^n_{\k}||^2=\sum_{\k \in A}	||\nu^{\infty}_{\k}||^2$. It follows that
\begin{align*}
		&\limsup_{n}\E\left[||\Lambda_n - \Lambda_n(\overline{k})||_\Lambda\right]\\
		& \leq  \left(1+6 \left(\sum_{\k \in \N^{3*}}	||\nu^{\infty}_{\k}||^2\right)^{1/2}\right)\left( 	\sum_{\k\in \cup_{\ell=1}^4\left(\K_{\ell}\backslash\K_{\ell}(\overline{k})\right)}||\nu^{\infty}_{\k}||^2\right)^{1/2},
\end{align*}
and because $\sum_{\k\in \N^{3\ast}}||\nu^{\infty}_{\k}||^2<\infty$, we have
$\lim_{\overline{k}}\sum_{\k\in \cup_{\ell=1}^4\left(\K_{\ell}\backslash \K_{\ell}(\overline{k})\right)} ||\nu^{\infty}_{\k}||^2=0$.

	\medskip

	\textbf{Substep 2:  $\lim_{\overline{k}}\E\left[||\Lambda_\infty - \Lambda_\infty(\overline{k})||_\Lambda\right]=0$.}

	Using the fact that $(Z_{\k})_{\k \in \cup_{\ell =1}^4\K_\ell}$ is a sequence of \textit{i.i.d.} $\mathcal{N}(0,1)$ random variables, we have
	\begin{align*}
		\E\left(\left|\left|L(\overline{k})-L\right|\right|^2\right)= & \sum_{\k\in \cup_{\ell=1}^4\left(\K_{\ell}\backslash\K_{\ell}(\overline{k})\right)}||\nu^{\infty}_{\k}||^2,\\
		\E\left(\left|\left|L\right|\right|^2\right)= & \sum_{\k\in \N^{3\ast}}||\nu^{\infty}_{\k}||^2.
	\end{align*}
	Coming to $V_1(\overline{k})-V_1$ (similar calculations are valid for $V_2(\overline{k})-V_2$), we can write
	\begin{align*}
		& \E\left(\left|\left|V_1(\overline{k})-V_1\right|\right|\right) \\
		&=\E\left(\left|\left|\V\left(L(\overline{k})|(Z_{\k})_{\k\in \K_2}\right)-\V\left(L|(Z_{\k})_{\k\in \K_2}\right)\right|\right|\right) \\
		&=\E\left(\left|\left|\V\left(L-L(\overline{k})|(Z_{\k})_{\k\in \K_2}\right)+2\Cov\left(L(\overline{k})-L,L|(Z_{\k})_{\k\in \K_2}\right)\right|\right|\right) \\
		&\leq \E\left(\left|\left|L(\overline{k})-L\right|\right|^2\right)+2\E\left(\left|\left|\Cov\left(L(\overline{k})-L,L|(Z_{0,k,0})_{1\leq \overline{k}}\right)\right|\right|\right) \\
		&\leq \E\left(\left|\left|L(\overline{k})-L\right|\right|^2\right)+2\E\left[ \left|\left|L-L(\overline{k})-\E\left(L-L(\overline{k})|(Z_{0,k,0})_{1\leq \overline{k}}\right)\right|\right|\times \left|\left|L-\E\left(L|(Z_{0,k,0})_{1\leq \overline{k}}\right)\right|\right|\right] \\
		&\leq \E\left(\left|\left|L(\overline{k})-L\right|\right|^2\right)+2\E\left(\left|\left|L(\overline{k})-L\right|\right|^2\right)^{1/2}\E(\left|\left|L\right|\right|^2)^{1/2}.
	\end{align*}
We also have:	\begin{equation*}
	\left|\left|V_{12}(\overline{k})-V_{12}\right|\right| = \sum_{\k\in \cup_{\ell=3}^4\K_{\ell}\backslash\K_{\ell}(\overline{k})}||\nu^{\infty}_{\k}||^2 \leq \sum_{\k\in \cup_{\ell=1}^4\K_{\ell}\backslash\K_{\ell}(\overline{k})}||\nu^{\infty}_{\k}||^2.
	\end{equation*}
We can conclude that:
\begin{align}
	\E\left[||\Lambda_\infty - \Lambda_\infty(\overline{k})||_\Lambda\right]\leq & ~~4 \sum_{\k\in \cup_{\ell=1}^4\K_{\ell}\backslash\K_{\ell}(\overline{k})}||\nu^{\infty}_{\k}||^2\nonumber\\&+4\left(\sum_{\k\in \cup_{\ell=1}^4\K_{\ell}\backslash\K_{\ell}(\overline{k})}||\nu^{\infty}_{\k}||^2\right)^{1/2}\left(\sum_{\k\in \N^{3\ast}}||\nu^{\infty}_{\k}||^2\right)^{1/2},\label{eq:control_limite_troncation}
	\end{align}	
and next $\lim_{\overline{k}}\E\left[||\Lambda_\infty - \Lambda_\infty(\overline{k}_{\varepsilon_1})||_\Lambda\right]=0$.

	\medskip

	\textbf{Substep 3: $\lim_{n}\left| \E[h(\Lambda_n(\overline{k}))] - \E[h(\Lambda_\infty(\overline{k}))]  \right|=0$ for any $\overline{k}>0$.}

	Let
	\begin{align*}
		Z^n_{\k} & :=\frac{1}{C_1^{1/2}}\sum_{i=1}^{C_1} \psi_{k_1}(U_{i0})\text{ if }\k\in \K_1,\\ &:=\frac{1}{C_2^{1/2}}\sum_{j=1}^{C_2} \psi_{k_2}(U_{0j})\text{ if }\k\in \K_2,\\ &:=\frac{1}{(C_1C_2)^{1/2}}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2} \psi_{k_1}(U_{i0})\psi_{k_2}(U_{0j})\psi_{k_3}(U_{ij})\text{ if }\k\in \K_4, \\
		V_{1,n}(\overline{k}) & := \sum_{\boldsymbol{k}\in\K_4(\overline{k})}\nu_{\k}^{n\otimes 2} + \sum_{k_1=1}^{\overline{k}}\left( \nu^n_{k_1,0,0} + \sum_{k_2=1}^{\overline{k}}\nu^n_{k_1,k_2,0}Z_{0,k_2,0}^n \right)^{\otimes 2}, \\
		V_{2,n}(\overline{k}) & := \sum_{\boldsymbol{k}\in\K_4(\overline{k})}\nu_{\k}^{n\otimes 2} + \sum_{k_2=1}^{\overline{k}}\left( \nu^n_{0,k_2,0} + \sum_{k_1=1}^{\overline{k}}\nu^n_{k_1,k_2,0}Z_{k_1,0,0}^n \right)^{\otimes 2}, \\
		V_{12,n}(\overline{k}) & := \sum_{\boldsymbol{k}\in\K_{3}(\overline{k})\cup\K_{4}(\overline{k})}\nu_{\k}^{n\otimes 2}.
	\end{align*}
	We also define $\Lambda_n^\infty(\overline{k}) := \left( \overline{\xi}(\overline{k}), V_{1,n}(\overline{k}), V_{2,n}(\overline{k}), V_{12,n}(\overline{k}) \right)$. By the Lipschitz property of $h$ and the triangle and Jensen inequalities:
	\begin{align*}
		\left| \E[h(\Lambda_n(\overline{k}))] - \E[h(\Lambda_\infty(\overline{k}))]  \right| \leq & \left| \E[h(\Lambda_n(\overline{k})) - h(\Lambda_n^\infty(\overline{k}))]  \right| + \left| \E[h(\Lambda_n^\infty(\overline{k}))] - \E[h(\Lambda_\infty(\overline{k}))]  \right| \\
		\leq & C_h \E\left[\left|\left| \Lambda_n(\overline{k}) - \Lambda_n^\infty(\overline{k})\right|\right|_\Lambda\right] + \left| \E[h(\Lambda_n^\infty(\overline{k}))] - \E[h(\Lambda_\infty(\overline{k}))]  \right|.
	\end{align*}
Lemma \ref{lem:weak_conv_finite_dim_Z} ensures	$(Z^n_{\k})_{\k\in \K_{124}(\overline{k})}$ converges in distribution to $(Z_{\k})_{\k\in \K_{124}(\overline{k})}\sim \mathcal{N}(0,\Id)$.\\ Let $g_n\left((Z^n_{\k})_{\k\in \K_{124}(\overline{k})}\right)=\Lambda_n^\infty(\overline{k})$ and $g_{\infty}\left((Z_{\k})_{\k\in \K_{124}(\overline{k})}\right)=\Lambda_{\infty}(\overline{k})$. For any $\k$, $\lim_n \nu^n_{\k}=\nu^{\infty}_{\k}$ implies: $$\lim_n g_n\left((z^n_{k_1,0,0},z^n_{0,k_2,0})_{1\leq k_1,k_2\leq \overline{k}}\right)=g_{\infty}\left((z^{\infty}_{k_1,0,0},z^{\infty}_{0,k_2,0})_{1\leq k_1,k_2\leq \overline{k}}\right)$$ for $z^n_{\k}$ such that $\lim_n z^n_{\k}=z^{\infty}_{\k}$. Next, Theorem 18.11 in \cite{vanderVaart2000} ensures convergence in distribution of $\Lambda_n^{\infty}(\overline{k})$ to $\Lambda_{\infty}(\overline{k})$ and
\begin{equation}
	\lim_n\left| \E[h(\Lambda_n^\infty(\overline{k}))] - \E[h(\Lambda_{\infty}(\overline{k}))]  \right|=0.
	\label{eq:portemanteau_intermediary}
\end{equation}
It remains to control $\E\left[\left|\left| \Lambda_n(\overline{k}) - \Lambda_n^\infty(\overline{k})\right|\right|_\Lambda\right]$. To do so, note that:	
\begin{align*}
		\E\left[\left|\left| \Lambda_n(\overline{k}) - \Lambda_n^\infty(\overline{k})\right|\right|_\Lambda\right] =& 
		\E\left[\left|\left| \widetilde{V}_1(\overline{k}) - V_{1,n}(\overline{k}) \right|\right|\right] + \E\left[\left|\left| \widetilde{V}_2(\overline{k}) - V_{2,n}(\overline{k}) \right|\right|\right]  \\
		& + \E\left[\left|\left| \widetilde{V}_{12}(\overline{k}) - V_{12,n}(\overline{k}) \right|\right|\right].
	\end{align*}
We detail first how to control $\E\left[\left|\left| \widetilde{V}_1(\overline{k}) - V_{1,n}(\overline{k}) \right|\right|\right]$ ($\E\left[\left|\left| \widetilde{V}_2(\overline{k}) - V_{2,n}(\overline{k}) \right|\right|\right]$ can be dealt with using similar arguments). We then handle $\E\left[\left|\left| \widetilde{V}_{12}(\overline{k}) - V_{12,n}(\overline{k}) \right|\right|\right]$.

\medskip

\textbf{Subsubstep 1: $\lim_{n}\E\left[\left|\left| \widetilde{V}_1(\overline{k}) - V_{1,n}(\overline{k}) \right|\right|\right] + \E\left[\left|\left| \widetilde{V}_2(\overline{k}) - V_{2,n}(\overline{k}) \right|\right|\right]=0$ for any $\overline{k}>0$.} \\
The term $\widetilde{V}_1(\overline{k})$ can be decomposed as follows 
\begin{align}
	\widetilde{V}_1(\overline{k})&= \frac{1}{C_1^2}\sum_{i=1}^{C_1} \left(T^n_{i,1}+T^n_{i,2}+T^n_{i,3}+T^n_{i,4}\right)^{\otimes 2},
	\label{eq:sigma_a}
\end{align}
with
	\begin{align*}
	T^n_{i,1}&=\sqrt{C_1}\sum_{\k \in \K_1(\overline{k})}\nu^n_{\k}\psi_{k_1}(U_{i0})\\
	T^n_{i,2}&=\sqrt{C_2}\sum_{\k \in \K_2(\overline{k})}\nu^n_{\k}\frac{1}{C_2}\sum_{j=1}^{C_2}\psi_{k_2}(U_{0j})=\sum_{\k \in \K_2(\overline{k})}\nu^n_{\k}Z^n_{\k}\\
	T^n_{i,3}&=\sqrt{C_1C_2}\sum_{\k \in \K_3(\overline{k})}\nu^n_{\k}\frac{1}{C_2}\sum_{j=1}^{C_2}\psi_{k_1}(U_{i0})\psi_{k_2}(U_{0j}^n)=\sqrt{C_1}\sum_{\k \in \K_3(\overline{k})}\nu^n_{\k}\psi_{k_1}(U_{i0})Z^n_{0,k_2,0}\\
	T_{i,4}^n&=\sqrt{C_1C_2}\sum_{\k \in \K_4(\overline{k})}\nu^n_{\k}\frac{1}{C_2}\sum_{j=1}^{C_2}\psi_{k_1}(U_{i0})\psi_{k_2}(U_{0j})\psi_{k_3}(U_{ij}).
\end{align*}
Let $h_{k_1}^n=\nu^n_{k_1,0,0}+\sum_{k_2=1}^{\overline{k}}\nu_{k_1,k_2,0}^nZ_{0,k_2,0}^n$. We can write
\begin{align*}
	\frac{1}{C_1^2}\sum_{i=1}^{C_1} (T^n_{i,1}+T^n_{i,3})^{\otimes 2}- \sum_{k_1=1}^{\overline{k}}(h_{k_1}^{n})^{\otimes 2}=& \sum_{k_1=1}^{\overline{k}}(h_{k_1}^n)^{\otimes 2}\left(\frac{1}{C_1}\sum_{i=1}^{C_1}  \psi_{k_1}^2(U_{i0})-1\right)\\
	&+\sum_{1\leq k_1\neq k_1'\leq \overline{k}} h_{k_1}^nh_{k'_1}^{n \prime}\left(\frac{1}{C_1}\sum_{i=1}^{C_1}\psi_{k_1}(U_{i0})\psi_{k'_1}(U_{i0})\right)
\end{align*}
Next, by the triangle inequality and because $(h_k^n)_{k\geq 1}$ and $(U_{i0})_{i\geq1}$ are independent, we have:
\begin{align*}
	&E\left[\left|\left|\frac{1}{C_1^2}\sum_{i=1}^{C_1} (T^n_{i,1}+T^n_{i,3})^{\otimes 2}- \sum_{k_1=1}^{\overline{k}}(h_{k_1}^{n})^{\otimes 2}\right|\right|\right]\leq \sum_{k_1=1}^{\overline{k}}E\left[\left|\left|h_{k_1}^n\right|\right|^2\right]E\left[\left|\frac{1}{C_1}\sum_{i=1}^{C_1}  \psi_{k_1}^2(U_{i0})-1\right|\right]\\
	&~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~+\sum_{1\leq k_1\neq k_1'\leq \overline{k}} E\left[||h_{k_1}^n|| ||h_{k'_1}^{n}||\right]E\left[\left|\frac{1}{C_1}\sum_{i=1}^{C_1}\psi_{k_1}(U_{i0})\psi_{k'_1}(U_{i0})\right|\right].
	\end{align*}
Because $E[Z^n_{0,k_2,0}]=0$ and $E[(Z^n_{0,k_2,0})^2]=1$, we have $E[||h_{k_1}^n||^2]=||\nu^n_{k_1,0,0}||^2+\sum_{k_2=1}^{\overline{k}}||\nu^n_{k_1,k_2,0}||^2$, $E[||h_{k_1}^n|| ||h_{k'_1}^{n}||]\leq  E[||h_{k_1}^n|| ^2]/2+E[ ||h_{k'_1}^{n}||^2]/2$. Because $\sup_{u\in[0,1]}\left|\psi_k^2(u)-1\right|=1$ and $E[\psi_k^2(U_{i0})]=1$ and by independence of $U_{i0}$ accross $i$, we have $$E\left[\left|\frac{1}{C_1}\sum_{i=1}^{C_1}  \psi_{k_1}^2(U_{i0})-1\right|\right]\leq E\left[\left|\frac{1}{C_1}\sum_{i=1}^{C_1}  \psi_{k_1}^2(U_{i0})-1\right|^2\right]^{1/2}\leq C_1^{-1/2}$$
and similarly, because $\sup_{u\in[0,1]}\left|\psi_k(u)\psi_{k'}(u)\right|=2$ we have $E[|\frac{1}{C_1}\sum_{i=1}^{C_1}\psi_{k_1}(U_{i0})\psi_{k'_1}(U_{i0})|]\leq 2C_1^{-1/2}$. This ensures:
\begin{align}
	E\left[\left|\left|\frac{1}{C_1^2}\sum_{i=1}^{C_1} (T^n_{i,1}+T^n_{i,3})^{\otimes 2}- \sum_{k_1=1}^{\overline{k}}(h_{k_1}^{n})^{\otimes 2}\right|\right|\right]\leq& \overline{k}( 2\overline{k}-1) C_1^{-1/2}\sum_{\k\in \N^{3\ast}}||\nu^n_{\k}||^2.
		\label{eq:control_T_31}
	\end{align}
$T^n_{i,2}$ does not depend on $i$, $E[Z^n_{0,k_2,0}]=0$ and $E[Z^n_{0,k_2,0}Z^n_{0,k'_2,0}]=\mathds{1}\{k_2=k_2'\}$, which ensures:
\begin{align}
	\E\left[\left|\left| \frac{1}{C_1^2}\sum_{i=1}^{C_1} T^n_{i,2}{}^{\otimes 2} \right|\right|\right] & \le \frac{E[||T_{1,2}^n||^2]}{C_1} = \frac{1}{C_1}\sum_{\k \in \K_2(\overline{k})}\left|\left|\nu^n_{\k}\right|\right|^2 \leq C_1^{-1}\sum_{\k \in \N^{3\ast}}\left|\left|\nu^n_{\k}\right|\right|^2.
	\label{eq:control_T_2}	
\end{align}


Let $V_{ijj'}(\k,\k')=\psi_{k_1}(U_{i0}^n) \psi_{k'_1}(U_{i0}^n)\psi_{k_2}(U_{0j}^n)\psi_{k_2'}(U_{0j'}^n)\psi_{k_3}(U_{ij}^n)\psi_{k'_3}(U_{ij'}^n)$, we can write with the triangle and Jensen inequalities, as well as subadditivity and submultiplicativity of the matrix 2-norm
\begin{align*}
	 &\E\left[\left|\left| \frac{1}{C_1^2}\sum_{i=1}^{C_1} T^n_{i,4}{}^{\otimes 2} - \sum_{\k\in\K_4(\overline{k})}\nu_{\k}^{\otimes 2} \right|\right|\right]\nonumber\\&=\E\left[\left|\left| \sum_{(\k,\k') \in \K_4(\overline{k})^2} \nu_{\k}\nu_{\k'}'\left( \frac{1}{C_1C_2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}\sum_{j'=1}^{C_2}V_{ijj'}(\k,\k') - \mathds{1}\{\k=\k'\} \right)  \right|\right|\right] \nonumber \\
	\leq & \E\left[\left|\left| \sum_{(\k,\k') \in \K_4(\overline{k})^2} \nu_{\k}\nu_{\k'}'\left( \frac{1}{C_1C_2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}V_{ijj}(\k,\k') - \mathds{1}\{\k=\k'\} \right)  \right|\right|\right] \nonumber \\
	& + \E\left[\left|\left| \sum_{(\k,\k') \in \K_4(\overline{k})^2} \nu_{\k}\nu_{\k'}'\frac{1}{C_1C_2}\sum_{i=1}^{C_1}\sum_{1\leq j \neq j' \leq C_2}V_{ijj'}(\k,\k') \right|\right|\right] \nonumber \\
	\leq & \sum_{(\k,\k') \in \K_4(\overline{k})^2}||\nu_{\k}||\,||\nu_{\k'}||\left\{ \E\left[\left(\frac{1}{C_1C_2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}V_{ijj}(\k,\k') - \mathds{1}\{\k=\k'\}\right)^2\right]^{1/2} \right. \nonumber\\
	& \left. ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ + \E\left[\left(\frac{1}{C_1C_2}\sum_{i=1}^{C_1}\sum_{1\leq j \neq j' \leq C_2}V_{ijj'}(\k,\k')\right)^2\right]^{1/2} \right\}.
\end{align*}
We remark that $\E\left[V_{ijj}(\k,\k')\right] = \mathds{1}\{\k=\k'\}$ and $||\psi_k||_{\infty}\leq \sqrt{2}$. This and independence of $(U_{i0},U_{0j},U_{ij})$ across $(i,j)$ ensure $\left|\Cov(V_{ijj}(\k,\k'),V_{i'j'j'}(\k,\k'))\right|\leq (2^3-1)^2\mathds{1}\{\k=\k'\}\mathds{1}\{i=i'\text{ or } j=j'\}+2^6\mathds{1}\{\k \neq \k'\}\mathds{1}\{i=i'\text{ or } j=j'\}$. %\textcolor{red}{Not obvious to get on the top of one's head right???} It follows:
\begin{align*}
	\E\left[\left(\frac{1}{C_1C_2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}V_{ijj}(\k,\k') - \mathds{1}\{\k=\k'\}\right)^2\right]^{1/2}&\leq 8\left(\frac{1}{C_1C_2}+\frac{1}{C_1}+\frac{1}{C_2}\right)^{1/2}\leq \frac{8\sqrt{2}}{\Cinf^{1/2}}
	\end{align*}
Moreover $\E(V_{ijj'}(\k,\k'))=0$ if $j\neq j'$, and for $i\neq i'$ and $j,j',j'',j'''$ four distinct elements,
$\Cov\left(V_{ijj'}(\k,\k'),V_{ij''j'''}(\k,\k')\right)$, $\Cov(V_{ijj'}(\k,\k'),V_{i'jj''}(\k,\k'))$, $\Cov(V_{ijj'}(\k,\k'),V_{i'jj''}(\k,\k'))$, \\
$\Cov(V_{ij'j}(\k,\k'),V_{ij''j}(\k,\k'))$, $\Cov(V_{ijj'}(\k,\k'),V_{ijj''}(\k,\k'))$ and $\Cov(V_{ijj'}(\k,\k'),V_{i'jj'}(\k,\k'))$ are null. Next, $\left|\Cov\left(V_{ijj'}(\k,\k'),V_{i'j''j'''}(\k,\k')\right)\right|\leq 2^6 \mathds{1}\{i=i'\}\mathds{1}\{\{j,j'\}=\{j'',j'''\}\}$ and:
\begin{align*}
	\E\left[\left(\frac{1}{C_1C_2}\sum_{i=1}^{C_1}\sum_{1\leq j \neq j' \leq C_2}V_{ijj'}(\k,\k')\right)^2\right]^{1/2}&\leq 2^3\left(\frac{2C_1C_2(C_2-1)}{C_1^2C_2^2}\right)^{1/2}\leq \frac{8\sqrt{2}}{C_1^{1/2}}
\end{align*}
Since $||\nu_{\k}||\,||\nu_{\k'}||\leq ||\nu_{\k}||^2/2+||\nu_{\k'}||^2/2$ we conclude:
\begin{align}
	\E\left[\left|\left| \frac{1}{C_1^2}\sum_{i=1}^{C_1} T^n_{i,4}{}^{\otimes 2} - \sum_{\k\in\K_4(\overline{k})}\nu_{\k}^{\otimes 2} \right|\right|\right]&\leq \frac{16\overline{k}(\overline{k}+1)^2\sqrt{2}}{\Cinf^{1/2}}\sum_{\k\in\N^{3\ast}}||\nu^n_{\k}||^2
	\label{eq:control_T_4}
\end{align}
We remark that $E(T^{n\prime}_{i,\ell}\ T^{n}_{i',\ell'})=E\left(||T^n_{1,\ell}||^2\right)\mathds{1}\{i=i',\ell=\ell'\}=C_1\left(\sum_{\k\in \K_{\ell}(\overline{k})}||\nu^n_{\k}||^2\right)\mathds{1}\{i=i',\ell=\ell'\}$ for $(\ell,\ell') \in \{1,3,4\}^2$ and $T^n_{i,2}=T^n_{1,2}$. Based on these observations, we get:
\begin{align}
	E\left[\left|\left|\frac{1}{C_1^2}\sum_{i=1}^{C_1}\left(T^n_{i,1}+T^n_{i,3}+T^n_{i,4}\right)T^{n \prime}_{i,2}\right|\right|\right]&\leq E\left[\left|\left|\frac{1}{C_1^2}\sum_{i=1}^{C_1}\left(T^n_{i,1}+T^n_{i,3}+T^n_{i,4}\right)\right|\right| \left|\left|T^{n \prime}_{1,2}\right|\right|\right]\nonumber\\ &\leq C_1^{-1}E\left[\left|\left|\frac{1}{C_1}\sum_{i=1}^{C_1}\left(T^n_{i,1}+T^n_{i,3}+T^n_{i,4}\right)\right|\right|^2\right]^{1/2} \left(\sum_{\k \in \K_2(\overline{k})}\left|\left|\nu^n_{\k}\right|\right|^2\right)^{1/2}\nonumber\\
	&\leq C_1^{-1}\sum_{\k\in\N^{3\ast}}||\nu^n_{\k}||^2.
	\label{eq:control_T_134_2}
\end{align}

Let $F_{ij}(\k,\k')=\psi_{k_1}(U_{i0}) \psi_{k'_1}(U_{i0})\psi_{k_2'}(U_{0j})\psi_{k_3'}(U_{ij})$. If $\k'\in\K_4$,  we have $\E[F_{ij}(\k,\k')]=0$ and $|E(F_{ij}(\k,\k')F_{i'j'}(\k,\k'))|=E(S^2_{11}(\k,\k'))\mathds{1}\{i=i',j=j'\}\leq 16\mathds{1}\{i=i',j=j'\}$. This implies:
\begin{align}
	 \E\left[\left|\left| \frac{1}{C_1^2}\sum_{i=1}^{C_1} T^n_{i,1} T^{n\prime}_{i,4} \right|\right|\right]\leq&\sum_{\k,\k'\in \K_1(\overline{k})\times\K_4(\overline{k})}||\nu^n_{\k}\nu^{n \prime}_{\k'}|| \E\left[\left|\frac{1}{C_1C_2^{1/2}}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}F_{ij}(\k,\k')\right|\right]\notag\\
	\leq & \sum_{\k,\k'\in \K_1(\overline{k})\times\K_4(\overline{k})}||\nu_{\k}||\,||\nu_{\k'}|| \E\left[ \left(\frac{1}{C_1C_2^{1/2}}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2} F_{ij}(\k,\k')\right)^2 \right]^{1/2}\notag\\
	\leq& \frac{1}{2}\sum_{\k,\k'\in \K_1(\overline{k})\times\K_4(\overline{k})}\left(||\nu_{\k}||^2+||\nu_{\k'}||^2\right) \frac{1}{C_1^{1/2}}\sup_{\k,\k'}\E\left[ F^2_{11}(\k,\k') \right]^{1/2}\notag\\
	\leq &\frac{2\overline{k}\left(1+(\overline{k}+1)^2\right)}{C_1^{1/2}}\sum_{\k\in \N^{3\ast}}||\nu^n_{\k}||^2.
		\label{eq:control_T_1_4}
	\end{align}
Let $Q_{ijj'}(\k,\k')=\psi_{k_1}(U_{i0}) \psi_{k'_1}(U_{i0})\psi_{k_2}(U_{0j})\psi_{k_2'}(U_{0j'})\psi_{k_3'}(U_{ij'})$. If $\k\in \K_4$, we have $E(Q_{ijj'}(\k,\k'))=0$ and $|E(Q_{ijj'}(\k,\k')Q_{i'j''j'''}(\k,\k'))|\leq 2^5\mathds{1}\{i=i',j=j'', j'=j'''\}$.
\begin{align}
	\E\left[\left|\left| \frac{1}{C_1^2}\sum_{i=1}^{C_1} T^n_{i,3} T^{n\prime}_{i,4} \right|\right|\right]\leq&\sum_{\k,\k'\in \K_3(\overline{k})\times\K_4(\overline{k})}||\nu^n_{\k}\nu^{n \prime}_{\k'}|| \E\left[\left|\frac{1}{C_1C_2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}\sum_{j'=1}^{C_2}Q_{ijj'}(\k,\k')\right|\right]\notag\\
	\leq& \frac{1}{2}\sum_{\k,\k'\in \K_3(\overline{k})\times\K_4(\overline{k})}\left(||\nu_{\k}||^2+||\nu_{\k'}||^2\right) \left(\frac{2^5}{C_1}\right)^{1/2}\notag\\
	\leq &\frac{2^{3/2}\overline{k}\left(\overline{k}+(\overline{k}+1)^2\right)}{C_1^{1/2}}\sum_{\k\in \N^{3\ast}}||\nu^n_{\k}||^2
		\label{eq:control_T_3_4}
	\end{align}

We conclude from \eqref{eq:control_T_31}, \eqref{eq:control_T_2}, \eqref{eq:control_T_4}, \eqref{eq:control_T_134_2}, \eqref{eq:control_T_1_4} and \eqref{eq:control_T_3_4} there exists some universal constant $K_1$ such that:
\begin{align}
	E\left[\left|\left|\widetilde{V}_1(\overline{k}) - V_{1,n}(\overline{k})\right|\right|\right]+E\left[\left|\left|\widetilde{V}_2(\overline{k}) - V_{2,n}(\overline{k})\right|\right|\right]&\leq \frac{K_1\overline{k}^3}{\Cinf^{1/2}}\sum_{\k \in \N^{3\ast}}||\nu^n_{\k}||^2.\label{eq:control_V1}
\end{align}

\medskip

\textbf{Subsubstep 2: $\lim_{n}\E\left[\left|\left| \widetilde{V}_{12}(\overline{k}) - V_{12,n}(\overline{k}) \right|\right|\right]=0$ for any $\overline{k}>0$.} \\
We have \begin{align}
	\widetilde{V}_{12}(\overline{k})&= \frac{1}{C_1^2C_2^2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2} \left(S^n_{ij,1}+S^n_{ij,2}+S^n_{ij,3}+S^n_{ij,4}\right)^{\otimes 2},
	\label{eq:sigma_gamma_eps}
\end{align}
with
\begin{align*}
	S^n_{ij,1}&:=\sqrt{C_1}\sum_{\k \in \K_1(\overline{k})}\nu^n_{\k}\psi_{k_1}(U_{i0})\\
	S^n_{ij,2}&:=\sqrt{C_2}\sum_{\k \in \K_2(\overline{k})}\nu^n_{\k}\psi_{k_2}(U_{0j})\\
	S^n_{ij,3}&:=\sqrt{C_1C_2}\sum_{\k \in \K_3(\overline{k})}\nu^n_{\k}\psi_{k_1}(U_{i0})\psi_{k_2}(U_{0j}^n)\\
	S^n_{ij,4}&:=\sqrt{C_1C_2}\sum_{\k \in \K_4(\overline{k})}\nu^n_{\k}\psi_{k_1}(U_{i0})\psi_{k_2}(U_{0j}^n)\psi_{k_3}(U_{ij})	.
\end{align*}
For \begin{align*}P_{ij}(\k,\k'):=&C_1^{1-(\mathds{1}\{\k\in \K_2\}+\mathds{1}\{\k'\in \K_2\})/2}C_2^{1-(\mathds{1}\{\k\in \K_1\}+\mathds{1}\{\k'\in \K_1\})/2}\\
	&\left(\psi_{k_1}(U_{i0})\psi_{k'_1}(U_{i0})\psi_{k_2}(U_{0j})\psi_{k'_2}(U_{0j})\psi_{k_3}(U_{ij})\psi_{k'_3}(U_{ij})-\mathds{1}\{\k=\k'\}\right),\end{align*}
we have for $(\ell,\ell')\in\{1,2,3,4\}^2$:
\begin{align}
	&E\left[\left|\left|\frac{1}{C_1^2C_2^2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}S^n_{ij,\ell}S^{n\prime}_{ij,\ell'}-\mathds{1}\{\ell=\ell'\}C_1^{-\mathds{1}\{\ell = 2\}}C_2^{-\mathds{1}\{\ell = 1\}}\sum_{\k\in\K_{\ell}(\overline{k})}\nu^{n\otimes 2}_{k}\right|\right|\right]\notag\\
	&\leq \sum_{\k\in \K_{\ell}(\overline{k})}\sum_{\k'\in \K_{\ell'}(\overline{k})}||\nu^n_{\k}||\  ||\nu^n_{\k'}||E\left[\left|\frac{1}{C_1^2C_2^2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}P_{ij}(\k,\k')\right|\right]\notag\\
	&\leq \sum_{\k\in \K_{\ell}(\overline{k})}\sum_{\k'\in \K_{\ell'}(\overline{k})}\left(\frac{||\nu^n_{\k}||^2}{2}+\frac{ ||\nu^n_{\k'}||^2}{2}\right)E\left[\left|\frac{1}{C_1^2C_2^2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}P_{ij}(\k,\k')\right|\right]\notag\\
	&\leq \overline{k}(\overline{k}+1)^2\left(\sum_{\k\in \N^{3\ast}}||\nu^n_{\k}||^2\right) \left(\sup_{(\k,\k')\in \K_{\ell}(\overline{k})\times \K_{\ell'}(\overline{k})}E\left[\left|\frac{1}{C_1^2C_2^2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}P_{ij}(\k,\k')\right|\right]\right).\label{eq:control_S}
\end{align}
If $\{\ell,\ell'\}=\{1,2\}$ we have by independence of $(U_{i0},U_{0j})_{i,j}$, the Cauchy-Schwarz inequality and $\sup_{u\in[0,1]}|\psi_k(u)|\leq \sqrt{2}$:
\begin{align}
	&\sup_{(\k,\k')\in \K_{\ell}(\overline{k})\times \K_{\ell'}(\overline{k})}E\left[\left|\frac{1}{C_1^2C_2^2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}P_{ij}(\k,\k')\right|\right]\notag\\
	&= \frac{1}{C_1^{1/2}C_2^{1/2}}\sup_{1\leq k_1,k_2\leq \overline{k}}E\left[\left|\frac{1}{C_1}\sum_{i=1}^{C_1}\psi_{k_1}(U_{i0})\right|\times\left|\frac{1}{C_2}\sum_{j=1}^{C_2}\psi_{k_2}(U_{0j})\right|\right]\notag\\
	&\leq \frac{1}{C_1C_2}\sup_{1\leq k_1,k_2\leq \overline{k}}E(\psi_{k_1}^2(U_{1,0}))^{1/2}E(\psi_{k_2}^2(U_{0,1}))^{1/2}\notag\\
	&\leq \frac{2}{C_1C_2}.\label{eq:control_S_1_2}
	\end{align}
If $\{\ell,\ell'\}=\{1,3\}$ we have:
\begin{align}
	&\sup_{(\k,\k')\in \K_{\ell}(\overline{k})\times \K_{\ell'}(\overline{k})}E\left[\left|\frac{1}{C_1^2C_2^2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}P_{ij}(\k,\k')\right|\right]\notag\\	&= \frac{1}{C_2^{1/2}}\sup_{(\k,\k')\in \K_1(\overline{k})\times \K_3(\overline{k})}E\left[\left|\frac{1}{C_1}\sum_{i=1}^{C_1}\psi_{k_1}(U_{i0})\psi_{k'_1}(U_{i0})\right|\times\left|\frac{1}{C_2}\sum_{j=1}^{C_2}\psi_{k'_2}(U_{0j})\right|\right]\notag\\
&\leq \frac{2}{C_2^{1/2}}\sup_{1\leq k_2\leq \overline{k}}E\left[\left|\frac{1}{C_2}\sum_{j=1}^{C_2}\psi_{k_2}(U_{0j})\right|\right]\leq \frac{2}{C_2}\sup_{1\leq k_2\leq \overline{k}}E(\psi_{k_2}^2(U_{0,1}))^{1/2}\leq \frac{2\sqrt{2}}{C_2}\label{eq:control_S_1_3}
\end{align}
Symmetrically, if $\{\ell,\ell'\}=\{2,3\}$, $\sup_{(\k,\k')\in \K_{\ell}(\overline{k})\times \K_{\ell'}(\overline{k})}E\left[\left|\frac{1}{C_1^2C_2^2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}P_{ij}(\k,\k')\right|\right]\leq \frac{2\sqrt{2}}{C_1}$.\\ If $\{\ell,\ell'\}=\{1,4\}$, we obtain:
\begin{align}
		&\sup_{(\k,\k')\in \K_{\ell}(\overline{k})\times \K_{\ell'}(\overline{k})}E\left[\left|\frac{1}{C_1^2C_2^2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}P_{ij}(\k,\k')\right|\right]\notag\\	&= \frac{1}{C_2^{1/2}}\sup_{(\k,\k')\in \K_{\ell}(\overline{k})\times \K_{\ell'}(\overline{k})}E\left[\left|\frac{1}{C_1C_2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}\psi_{k_1}(U_{i0})\psi_{k'_1}(U_{i0})\psi_{k'_2}(U_{0j})\psi_{k'_3}(U_{ij})\right|\right]\notag\\
	&\leq \frac{1}{C_1^{1/2}C_2}\sup_{(\k,\k')\in \K_{\ell}(\overline{k})\times \K_{\ell'}(\overline{k})}E\left[\psi_{k_1}^2(U_{0,1})\psi_{k'_1}^2(U_{0,1})\psi_{k'_2}^2(U_{1,0})\psi_{k'_3}^2(U_{11})\right]^{1/2}\notag\\
	&\leq \frac{4}{C_1^{1/2}C_2}\label{eq:control_S_1_4},
\end{align}
and if $\{\ell,\ell'\}=\{2,4\}$, $\sup_{(\k,\k')\in \K_{\ell}(\overline{k})\times \K_{\ell'}(\overline{k})}E\left[\left|\frac{1}{C_1^2C_2^2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}P_{ij}(\k,\k')\right|\right]\leq \frac{4}{C_1C_2^{1/2}}$.\\
If $\{\ell,\ell'\}=\{3,4\}$,
\begin{align}
	&\sup_{(\k,\k')\in \K_{\ell}(\overline{k})\times \K_{\ell'}(\overline{k})}E\left[\left|\frac{1}{C_1^2C_2^2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}P_{ij}(\k,\k')\right|\right]\notag\\
	&= \sup_{(\k,\k')\in \K_{\ell}(\overline{k})\times \K_{\ell'}(\overline{k})}E\left[\left|\frac{1}{C_1C_2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}\psi_{k_1}(U_{i0})\psi_{k_2}(U_{0j})\psi_{k'_1}(U_{i0})\psi_{k'_2}(U_{0j})\psi_{k'_3}(U_{ij})\right|\right]\notag\\
	&\leq \frac{1}{C_1^{1/2}C_2^{1/2}}\sup_{(\k,\k')\in \K_{\ell}(\overline{k})\times \K_{\ell'}(\overline{k})}E\left[\psi_{k_1}^2(U_{0,1})\psi_{k_2}^2(U_{1,0})\psi_{k'_1}^2(U_{0,1})\psi_{k'_2}^2(U_{1,0})\psi_{k'_3}^2(U_{11})\right]^{1/2}\notag\\
	&\leq \frac{4\sqrt{2}}{C_1^{1/2}C_2^{1/2}}.\label{eq:control_S_3_4}
\end{align}
As $\sup_{k,k',u}|\psi_k(u)\psi_{k'}(u)-\mathds{1}\{k=k'\}|=2$, we get:
\begin{align}
		&\sup_{(\k,\k')\in \K_{1}(\overline{k})^2}E\left[\left|\frac{1}{C_1^2C_2^2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}P_{ij}(\k,\k')\right|\right]\notag\\
		&= \frac{1}{C_2}\sup_{1\leq k_1,k_1'\leq \overline{k}}E\left[\left|\frac{1}{C_1}\sum_{i=1}^{C_1}  \psi_{k_1}(U_{i0})\psi_{k'_1}(U_{i0})-\mathds{1}\{k_1=k'_1\}\right|\right]\notag\\
		&\leq \frac{1}{C_2C_1^{1/2}}\sup_{1\leq k_1,k_1'\leq \overline{k}}E\left[\left|  \psi_{k_1}(U_{i0})\psi_{k'_1}(U_{i0})-\mathds{1}\{k_1=k'_1\}\right|^2\right]^{1/2}\leq \frac{2}{C_2C_1^{1/2}}\label{eq:control_S_1},
\end{align}
and similar arguments ensure $\sup_{(\k,\k')\in \K_{2}(\overline{k})^2}E\left[\left|\frac{1}{C_1^2C_2^2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}P_{ij}(\k,\k')\right|\right]\leq \frac{2}{C_1C_2^{1/2}}$.
We note that $\sup_{k_1,k'_1,k_2,k'_2,u,v}\left|\psi_{k_1}(u)\psi_{k_2}(v)\psi_{k'_1}(u)\psi_{k'_2}(v)-\mathds{1}\{k_1=k'_1,k_2=k'_2\}\right|=4$, which implies:
\begin{align}
 	&\sup_{(\k,\k')\in \K_{3}(\overline{k})^2}E\left[\left|\frac{1}{C_1^2C_2^2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}P_{ij}(\k,\k')\right|\right]\notag \\
 	&=\sup_{(\k,\k')\in \K_{3}(\overline{k})^2}E\left[\left|\frac{1}{C_1C_2}\sum_{i,j}\psi_{k_1}(U_{i0})\psi_{k'_1}(U_{i0})\psi_{k_2}(U_{0j})\psi_{k'_2}(U_{0j})-\mathds{1}\{\k=\k'\}\right|\right]\notag\\
 	&\leq \frac{1}{C_1^{1/2}C_2^{1/2}}\sup_{(\k,\k')\in \K_{3}(\overline{k})^2}E\left[\left(\psi_{k_1}(U_{1,0})\psi_{k'_1}(U_{1,0})\psi_{k_2}(U_{0,1})\psi_{k'_2}(U_{0,1})-\mathds{1}\{\k=\k'\}\right)^2\right]^{1/2}\notag\\
 &\leq \frac{4}{C_1^{1/2}C_2^{1/2}},\label{eq:control_S_3}
 	\end{align}
Since $\sup_{k_1,k'_1,k_2,k'_2,k_3,k'_3,u,v,w}\left|\psi_{k_1}(u)\psi_{k_2}(v)\psi_{k_3}(w)\psi_{k'_1}(u)\psi_{k'_2}(v)\psi_{k'_3}(w)-\prod_{j=1}^3\mathds{1}\{k_j=k'_j\}\right|=8$, we have:
\begin{align}
	\sup_{(\k,\k')\in \K_{4}(\overline{k})^2}E\left[\left|\frac{1}{C_1^2C_2^2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}P_{ij}(\k,\k')\right|\right]&\leq \frac{8}{C_1^{1/2}C_2^{1/2}}.\label{eq:control_S_4}
\end{align}
It follows from \eqref{eq:control_S}, \eqref{eq:control_S_1_2}, \eqref{eq:control_S_1_3}, \eqref{eq:control_S_1_4}, \eqref{eq:control_S_3_4}, \eqref{eq:control_S_1}, \eqref{eq:control_S_3} and \eqref{eq:control_S_4} that for some universal constant $K'_1$:
\begin{align}E\left[\left|\left|\widetilde{V}_{12}(\overline{k}) - V_{12,n}(\overline{k})\right|\right|\right]&\leq \frac{K'_1\overline{k}^3}{\Cinf}\sum_{\k \in \N^{3\ast}}||\nu^n_{\k}||^2.\label{eq:control_V12}
\end{align}
Next, we deduce from \eqref{eq:control_V1} and \eqref{eq:control_V12} that for some constant $K>0$:
\begin{align}
	\E\left[\left|\left| \Lambda_n(\overline{k}) - \Lambda_n^\infty(\overline{k})\right|\right|_\Lambda\right]&\leq \frac{K \overline{k}^3}{\Cinf^{1/2}}\left(\sum_{\k\in\N^{3\ast}}||\nu^n_{\k}||^2\right).
	\label{eq:expec_control}
\end{align}
Combining~\eqref{eq:portemanteau_intermediary} and~\eqref{eq:expec_control}, we conclude $\lim_{n}\left| \E[h(\Lambda_n(\overline{k}))] - \E[h(\Lambda_\infty(\overline{k}))]  \right|=0$ for any $\overline{k}>0$ and any bounded Lipschitz function $h$.

\medskip

\textbf{Substep 4: Conclusion}\\
Combining the results of Substeps 1, 2 and 3, we conclude that for any bounded Lipschitz function $h$ $$\lim_n	\left| \E[h(\Lambda_n)] - \E[h(\Lambda_\infty)]  \right|=0.$$
As mentioned above, this is equivalent to convergence in distribution of $\Lambda_n$ to $\Lambda_\infty$.

\medskip


\textbf{Second step: $\widetilde{V}_j=V_n\widehat{V}_j^{\inf}V_n+o_p(1)$ for $j=1,2,12$}\\
Note that by direct computations, $V_n\widehat{V}_1^{\inf}V_n=\widetilde{V}_1-\frac{1}{C_1} \left(V_n\overline{Y}\right)^{\otimes 2}$, $V_n\widehat{V}_2^{\inf}V_n=\widetilde{V}_2-\frac{1}{C_2} \left(V_n\overline{Y}\right)^{\otimes 2}$ and $V_n\widehat{V}_{12}^{\inf}V_n = \widetilde{V}_{12}-\frac{1}{C_1C_2}\left(V_n\overline{Y}\right)^{\otimes 2}$. By definition of the matrix 2-norm, for any real vector $u$, we have $||u^{\otimes 2}|| \le \tr(u^{\otimes 2})$. It follows that
\begin{equation*}
	E\left[\left|\left|\left(V_n\overline{Y}\right)^{\otimes 2}\right|\right|\right] \le E\left[\tr\left(\left(V_n\overline{Y}\right)^{\otimes 2}\right)\right]=\tr \left(V_nE\left[\overline{Y}^{\otimes 2}\right]V_n\right)= d.
\end{equation*} 
We conclude that $\left(V_n\overline{Y},V_n(\widehat{V}_1^{\inf},\widehat{V}_2^{\inf},\widehat{V}_{12}^{\inf})V_n\right)$
converges in distribution to $\Lambda_{\infty}=\left(L,V_1,V_2,V_{12}\right)$. $\Box$


\subsection{Theorem \ref{thm:GMM}}

By compacity of $\Theta$ and twice continuous differentiability of $\beta \mapsto \psi(z,\beta)$ for every $z \in \R^{d_z}$, we note that the map
\begin{equation*}
	\beta \mapsto \left(\frac{1}{C_1C_2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}\psi_{ij}(\beta)\right)'\Wh \left(\frac{1}{C_1C_2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}\psi_{ij}(\beta)\right)
\end{equation*}
is minimized over $\Theta$ almost surely. This implies well-definition of $\widehat{\beta} \in \Theta$, a fact that will prove useful when verifying that Assumptions~\ref{as:as_lin} and~\ref{as:consistent_V} are satisfied.

\medskip

\textbf{Proof of Assumption \ref{as:as_lin}:} Since $Y_{ij}=B(J'\W J)^{-1}J'\W \psi_{ij}(\beta_0)$, we have:
\begin{align*}
	\E\left[||Y_{11}||^2\right]\leq&\E\left[||\psi_{11}(\beta_0)||^2\right]\frac{\lambda_{\max}(\W )^2\lambda_{\max}(JJ')}{\lambda_{\min}(\W )^2\lambda_{\min}(J'J)^2}\lambda_{\max}\left(BB'\right), \\
	\lambda_{\min}\left(\V(Y_{11})\right)\geq& \lambda_{\min}\left(\V\left(\psi_{11}(\beta_0)\right)\right)\frac{\lambda_{\min}(\W )^2\lambda_{\min}(J'J)}{\lambda_{\max}(\W )^2\lambda_{\max}(J'J)^2}\lambda_{\min}\left(BB'\right).
	\end{align*}
The quantities $\lambda_{\min}\left(\V\left(\psi_{11}(\beta_0)\right)\right)$, $\lambda_{\min}\left(BB'\right)$, $\lambda_{\min}(J'J)$ and $\lambda_{\min}(\W )$ are positive, and $\E\left[||\psi_{11}(\beta_0)||^2\right]$, $\lambda_{\max}\left(B'B\right)=\lambda_{\max}\left(BB'\right)$, $\lambda_{\max}(JJ')=\lambda_{\max}(J'J)$ and $\lambda_{\max}(\W )$ are finite. From this, we deduce that $\lambda_{\min}\left(\V(Y_{11})\right)>0$ and $\E\left[||Y_{11}||^2\right]<\infty$. Moreover, because $\E\left[\psi_{11}(\beta_0)\right]=0$, we obtain $\E\left[Y_{11}\right]=0$. Recall that Assumption \ref{as:DGP} holds for $Y_{ij}$. This ensures that decomposition \eqref{eq:decomp} and Lemma \ref{lem:decomp} hold as well for $Y_{ij}$. Next, $\V\left(\overline{Y}\right)=\frac{1}{C_1C_2}\V(Y_{11})+\frac{C_2-1}{C_1C_2}E(Y_{11}Y'_{1,2})+\frac{C_1-1}{C_1C_2}E(Y_{11}Y'_{2,1})$ with $E(Y_{11}Y'_{1,2})=\V(E(Y_{11}|\mathcal{S}_1))$ and $E(Y_{11}Y'_{2,1})=\V(E(Y_{11}|\mathcal{S}_2))$ symmetric and non negative matrices. It follows that $\lambda_{\min}\left(\V\left(\overline{Y}\right)\right)\geq \frac{1}{C_1C_2}\lambda_{\min}\left(\V\left(Y_{11}\right)\right)$ and $\V\left(\overline{Y}\right)^{-1/2}$ is well defined.

\medskip 

Let $\mathbb{P}_n(\beta):=\frac{1}{C_1C_2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}\psi_{ij}(\beta)$ and $\mathbb{P}(\beta):=\E\left(\psi_{11}(\beta)\right)$. As $\left|\left|\psi_{11}(\beta)-\psi_{11}(\tilde{\beta})\right|\right|\leq \left|\left|\sup_{b\in \Theta}\Deriv{\psi_{11}(b)}{\beta}\right|\right|\cdot\left|\left|\beta-\tilde{\beta}\right|\right|$ for any $(\beta,\tilde{\beta})\in \Theta^2$ and $\Theta$ is bounded, the class $\mathcal{F}=\{(n,(z_\ell)_{\ell \ge 1}) \mapsto \sum_{\ell=1}^n\psi(z_\ell,\beta), \beta\in \Theta\}$ has finite $L^1(P)$-bracketing number $N_{[\,]}(\varepsilon,L^1(P),\mathcal{F})<\infty$ (see example 19.7 in \citep{vanderVaart2000}). Theorem 3.4 in \cite{ddg2021} ensures that $\sup_{\beta \in \Theta}\left|\left|\mathbb{P}_n(\beta)-\mathbb{P}(\beta)\right|\right|$ converges in probability to 0. Moreover for any $\beta\in\Theta$, $\left|\left|\mathbb{P}(\beta)\right|\right|\leq \E\left[\sup_{b\in \Theta}\left|\left|\Deriv{\psi(b)}{\beta}\right|\right|\right]\text{diam}(\Theta)$. Let $M_n(\beta)=-\mathbb{P}_n(\beta)'\Wh \mathbb{P}_n(\beta)$ and $M_{\infty}(\beta)=-\mathbb{P}(\beta)'\W\mathbb{P}(\beta)$. We have:
\begin{align*}
	\sup_{\beta \in \Theta}\left|M_n(\beta)-M_{\infty}(\beta)\right|\leq& \sup_{\beta\in \Theta}\left| (\mathbb{P}_n(\beta)-\mathbb{P}(\beta))'\Wh (\mathbb{P}_n(\beta)+\mathbb{P}(\beta))\right|\\
	&+\sup_{\beta \in \Theta}\left|\mathbb{P}(\beta)(\W -\Wh )\mathbb{P}(\beta)\right|\\
	\leq&\left(\sup_{\beta\in \Theta}\left|\left|\mathbb{P}_n(\beta)-\mathbb{P}(\beta)\right|\right|\right)^2 \left|\left|\Wh \right|\right|\\
	&+2\sup_{\beta\in \Theta}\left|\left|\mathbb{P}_n(\beta)-\mathbb{P}(\beta)\right|\right| \left|\left|\Wh \right|\right|\E\left[\sup_{\beta\in \Theta}\left|\left|\Deriv{\psi_{11}(\beta)}{\beta}\right|\right|\right]\text{diam}(\Theta)\\
	&+ \left|\left|\Wh-\W\right|\right|\left(\E\left[\sup_{\beta\in \Theta}\left|\left|\Deriv{\psi_{11}(\beta)}{\beta}\right|\right|\right]\text{diam}(\Theta)\right)^2
	\end{align*}
We remark that $\left|\left|\Wh \right|\right|\leq\left|\left|\Wh-\W\right|\right|+\left|\left|\W \right|\right|$. This plus the convergence in probability of $\left|\left|\Wh-\W\right|\right|$ and $\sup_{\beta\in \Theta}\left|\left|\mathbb{P}_n(\beta)-\mathbb{P}(\beta)\right|\right|$ to 0 ensure that $\sup_{\beta \in \Theta}\left|M_n(\beta)-M_{\infty}(\beta)\right|$ converges to 0 in probability as well. We also have
\begin{equation*}
	\sup_{\beta:||\beta-\beta_0||\geq \epsilon}M_{\infty}(\beta)\leq -\inf_{\beta:||\beta-\beta_0||\geq \epsilon}\left|\left|E\left[\psi_{11}(\beta)\right]\right|\right|^2\lambda_{\min}(\W )<0=M_{\infty}(\beta_0).
\end{equation*}
Next, Theorem 5.7 in \cite{vanderVaart2000} yields the convergence in probability of $\widehat{\beta}$ to $\beta_0$.

\medskip

Our final goal is to prove that $\left|\left||\V(\overline{Y})^{-1/2}\left(\widehat{\theta}-\theta_0-\overline{Y}\right)\right|\right| = o_P(1)$. Let $\mathcal{V}_\eta := \left\{\beta \in\Theta : ||\beta-\beta_0||\le \eta\right\}$, $\mathbb{D}_n(b)=\frac{1}{C_1C_2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}\Deriv{\psi_{ij}(b)}{\beta}$ and $\mathbb{D}(b)=\E\left[\Deriv{\psi_{11}(b)}{\beta}\right]$. To derive our result, we first show that for every fixed $\eta>0$, the event 
\begin{equation*}
	\mathcal{E}_n := \left\{ \widehat{\beta} \in \mathcal{V}_\eta\right\} \cap \left\{ ||\Wh-\W|| \le \eta \right\} \cap \left\{ \sup_{\beta\in\Theta}\left|\left| \mathbb{D}_n(\beta)-\mathbb{D}(\beta) \right|\right| \le \eta \right\}
\end{equation*}
has probability tending to one. Consistency of $\widehat{\beta}$ and $\Wh $, and Theorem 3.4 in \cite{ddg2021} yield this result immediately. Second, we show that for $\eta>0$ small enough, the following holds on $\mathcal{E}_n$: $\widehat{J}\Wh \mathbb{P}_n(\widehat{\beta})=0$ and $\inf_{\beta_1,...,\beta_q \in \mathcal{V}_\eta^q}\lambda_{min}\left(\sum_{k=1}^qe_ke_k'\widehat{J}'\Wh \mathbb{D}_n(\beta_k)\right)>0$. For $\eta$ small enough, $\mathcal{V}_\eta \subset \overset{\circ}{\Theta}$. As a result, we obtain $\deriv{M_n(\widehat{\beta})}{\beta}=0$ or equivalently $\widehat{J}\Wh \mathbb{P}_n(\widehat{\beta})=0$. Recall that $\widehat{J} = \mathbb{D}_n(\widehat{\beta})$ and let $A:= \sup_{\beta\in\Theta}\left|\left| \mathbb{D}_n(\beta)-\mathbb{D}(\beta) \right|\right|$, $B := ||\Wh-\W||$ and $C := E\left[\sup_{b\in \Theta}\left|\left|\Deriv{{}^2\psi_{11}(b)}{\beta\partial \beta}\right|\right|\right] \sup_{\beta \in \mathcal{V}_\eta}\left|\left|\beta-\beta_0\right|\right| = \eta E\left[\sup_{b\in \Theta}\left|\left|\Deriv{{}^2\psi_{11}(b)}{\beta\partial \beta}\right|\right|\right]$. By repeated use of the triangle inequality and submultiplicativity of the matrix 2-norm, we can write for $(e_1,...,e_q)$ the canonical basis of $\R^q$ and for any $\beta_1,...,\beta_q \in \mathcal{V}_\eta^q$
\begin{align}
	\left|\left| \sum_{k=1}^qe_ke_k'\widehat{J}'\Wh \mathbb{D}_n(\beta_k) - J'\W J \right|\right| &=\left|\left| \sum_{k=1}^qe_ke_k'\left[\widehat{J}'\Wh \mathbb{D}_n(\beta_k) - J'\W J\right] \right|\right|\notag\\ &\le q\left(||\W || + B\right) \left[ (A+C)^2 + ||J||(A+C) + ||J||^2B \right]\notag\\& \le \varphi(\eta)
	\label{eq:control_sandwich}
\end{align}
with $\varphi: \Rb_+ \to \Rb_+$ strictly increasing and such that $\varphi(0) = 0$ ($\varphi$ depends on $q$, $||\W ||$, $||J||$ and $E\left[\sup_{b\in \Theta}\left|\left|\Deriv{{}^2\psi_{11}(b)}{\beta\partial \beta}\right|\right|\right]$). For $\eta$ sufficiently small $\varphi(\eta) \le \lambda_{min}(J'\W J)/2$, and then $\inf_{\beta_1,...,\beta_q \in \mathcal{V}_\eta^q}\lambda_{min}\left(\sum_{k=1}^qe_ke_k'\widehat{J}'\Wh \mathbb{D}_n(\beta_k)\right)>0$.

\medskip

We are now in a position to conclude. On $\mathcal{E}_n$, the Taylor Theorem with Lagrange remainder ensures existence of $t_1,...,t_q\in[0,1]^q$ and $\widetilde{\beta}_k=t_k\widehat{\beta}+(1-t_k)\beta_{0}$ such that $0=e'_k\widehat{J}'\Wh  \mathbb{P}_n(\beta_0)+e'_k\widehat{J}'\Wh \sum_{k=1}^p\mathbb{D}_n(\widetilde{\beta}_k)(\widehat{\beta}-\beta_{0})$. Since $\sum_{k=1}^qe_ke_k'=\Id$ and $\sum_{k=1}^qe_ke_k'\widehat{J}'\Wh \mathbb{D}_n(\widetilde{\beta}_k)$ is non singular on $\mathcal{E}_n$, we can write $(\widehat{\theta}-\theta_0) \mathds{1}_{\{\mathcal{E}_n\}}= -\widetilde{T}\mathbb{P}_n(\beta_0)\mathds{1}_{\{\mathcal{E}_n\}}$ with $\widetilde{T}:=B(\sum_{k=1}^qe_ke'_k\widehat{J}'\Wh \mathbb{D}_n(\widetilde{\beta}_k))^{-1}\widehat{J}'\Wh $. Letting $T:=B(J'\W J)^{-1}J'\W $, we have $\overline{Y}=-T\mathbb{P}_n(\beta_0)$ and \\ $\left|\left|\V(\overline{Y})^{-1/2}\right|\right|\leq\left(\lambda_{\min}\left(\V(\mathbb{P}_n(\beta_0)\right) \times \lambda_{\min}(TT')\right)^{-1/2}$. Next: 
\begin{align*}
	& \left|\left|\V(\overline{Y})^{-1/2}\left(\widehat{\theta}-\theta_0-\overline{Y}\right)\right|\right| \\
	=
	&\left|\left|\V(\overline{Y})^{-1/2}\left(-\widetilde{T}\mathbb{P}_n(\beta_0)-\overline{Y}\right)\mathds{1}_{\{\mathcal{E}_n\}}+\V(\overline{Y})^{-1/2}\left(\widehat{\theta}-\theta_0-\overline{Y}\right)\mathds{1}_{\{\mathcal{E}_n^c\}}\right|\right| \\
	= &\left|\left|\V(\overline{Y})^{-1/2}\left(T-\widetilde{T}\right)\mathbb{P}_n(\beta_0)\mathds{1}_{\{\mathcal{E}_n\}}+\V(\overline{Y})^{-1/2}\left(\widehat{\theta}-\theta_0-\overline{Y}\right)\mathds{1}_{\{\mathcal{E}_n^c\}}\right|\right| \\
	\leq & \left( \frac{\lambda_{\max}\left(\V(\mathbb{P}_n(\beta_0)\right)}{\lambda_{\max}\left(\V(\mathbb{P}_n(\beta_0)\right)}\lambda_{\min}(TT')^{-1}\right)^{1/2} \left|\left|T-\widetilde{T}\right|\right|\mathds{1}_{\{\mathcal{E}_n\}} \left|\left|\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\mathbb{P}_n(\beta_0)\right|\right| \\
	& +\left|\left|\V(\overline{Y})^{-1/2}\left(\widehat{\theta}-\theta_0-\overline{Y}\right)\right|\right|\mathds{1}_{\{\mathcal{E}_n^c\}}.
\end{align*}
Theorem 3.4 in \cite{ddg2021}, applied to $\mathbb{D}_n$, and the continuous mapping in probability (applied to $\mathbb{D}$ and to the matrix inverse operator in particular) imply $\left|\left|T-\widetilde{T}\right|\right|\mathds{1}_{\{\mathcal{E}_n\}} = o_P(1)$.
Combining this with $\frac{\lambda_{\max}\left(\V(\mathbb{P}_n(\beta_0)\right)}{\lambda_{\min}\left(\V(\mathbb{P}_n(\beta_0)\right)}=O(1)$,  $\left|\left|\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\mathbb{P}_n(\beta_0)\right|\right|=O_P(1)$ (implied in particular by Assumption~\ref{as:GMM_main}) and $\lim_n P(\mathcal{E}_n^c)=0$, we conclude that Assumption \ref{as:as_lin} holds.

\medskip
\textbf{Proof of Assumption \ref{as:consistent_V}:} Let $\widehat{M}:=B(\widehat{J}'\Wh \widehat{J})^{+}\widehat{J}'\Wh $, we already know that $\widehat{M}$ converges to $M$ in probability. Let $\mathbb{Q}_{1,n}(\beta):=\frac{1}{C_1C_2^2}\sum_{i=1}^{C_1}\left(\sum_{j=1}^{C_2}\left(\psi_{ij}(\beta)-\mathbb{P}_n(\beta)\right)\right)^{\otimes 2}=\frac{1}{C_1C_2^2}\sum_{i=1}^{C_1}\left(\sum_{j=1}^{C_2}\psi_{ij}(\beta)\right)^{\otimes 2}-\mathbb{P}_n(\beta)^{\otimes 2}$. We have:
\begin{align*}
	&\left|\left|\V(\overline{Y})^{-1/2}(\widehat{V}_1-\widehat{V}_1^{\inf})\V(\overline{Y})^{-1/2}\right|\right|\\
	&=\frac{1}{C_1} \left|\left|\V(\overline{Y})^{-1/2}\left(\widehat{M}\mathbb{Q}_{1,n}(\widehat{\beta})\widehat{M}'-M\mathbb{Q}_{1,n}(\beta_0)M'\right)\V(\overline{Y})^{-1/2}\right|\right|\\
	&\leq\frac{1}{C_1}\left|\left|\V(\overline{Y})^{-1}\right|\right|\,\left|\left|\V\left(\mathbb{P}_n(\beta_0)\right)\right|\right|\,\left|\left|\V(\mathbb{P}_n(\beta_0))^{-1/2}\left(\mathbb{Q}_{1,n}(\widehat{\beta})-\mathbb{Q}_{1,n}(\beta_0)\right)\V(\mathbb{P}_n(\beta_0))^{-1/2}\right|\right|\,\left|\left|\widehat{M}\right|\right|^2\\
	&+\frac{1}{C_1}\left|\left|\V(\overline{Y})^{-1}\right|\right|\,\left|\left|\V\left(\mathbb{P}_n(\beta_0)\right)\right|\right|\,\left|\left| \V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\mathbb{Q}_{1,n}(\beta_0)\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\right|\right| \times \\
	& \,\,\,\, \left(2\left|\left|M\right|\right| \left|\left|\widehat{M}-M\right|\right|+  \left|\left|\widehat{M}-M\right|\right|^2\right)
\end{align*}
 Since $\left|\left|\V(\overline{Y})^{-1}\right|\right|\,\left|\left|\V\left(\mathbb{P}_n(\beta_0)\right)\right|\right|=O_P(1)$ and $\left|\left|\widehat{M}-M\right|\right|=o_P(1)$, we just have to prove that $$\frac{1}{C_1}\left|\left| \V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\mathbb{Q}_{1,n}(\beta_0)\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\right|\right|=O_P(1),$$ and $$\frac{1}{C_1}\left|\left|\V(\mathbb{P}_n(\beta_0))^{-1/2}\left(\mathbb{Q}_{1,n}(\widehat{\beta})-\mathbb{Q}_{1,n}(\beta_0)\right)\V(\mathbb{P}_n(\beta_0))^{-1/2}\right|\right|=o_P(1),$$ to ensure Assumption \ref{as:consistent_V} is satisfied for $\widehat{V}_1$ and $\widehat{V}_1^{inf}$. \\

We have: $\frac{1}{C_1}\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\mathbb{Q}_{1,n}(\beta_0)\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}=\frac{1}{C^2_1C^2_2}\sum_{i=1}^{C_1}\left(\sum_{j=1}^{C_2}\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\psi_{ij}(\beta_0)\right)^{\otimes 2}-\frac{1}{C_1}\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\mathbb{P}_n(\beta_0)^{\otimes 2}\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}$. Given $\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\mathbb{P}_n(\beta_0)^{\otimes 2}\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}$ is symmetric positive, we obtain the following inequality: $$\left|\left|\frac{1}{C_1}\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\mathbb{Q}_{1,n}(\beta_0)\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\right|\right|\leq \frac{1}{C^2_1C^2_2}\sum_{i=1}^{C_1}\left|\left|\sum_{j=1}^{C_2}\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\psi_{ij}(\beta_0)\right|\right|^{ 2}.$$ 
We also have:
\begin{align*}
	&\E\left[\frac{1}{C_1^2}\sum_{i=1}^{C_1}\left|\left| \frac{1}{C_2}\sum_{j=1}^{C_2}\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\psi_{ij}(\beta_0) \right|\right|^2\right]\\
	&=\E\left(\frac{1}{C_1C_2^2}\sum_{j,j'=1}^{C_2}\psi_{1j}(\beta_0)'\V\left(\mathbb{P}_n(\beta_0)\right)^{-1}\psi_{1j'}(\beta_0)\right)\\
	&=\E\left(\frac{1}{C_1C_2^2}\sum_{j,j'=1}^{C_2}\tr\left[\psi_{1j}(\beta_0)'\V\left(\mathbb{P}_n(\beta_0)\right)^{-1}\psi_{1j'}(\beta_0)\right]\right)\\
	&=\E\left(\frac{1}{C_1C_2^2}\sum_{j,j'=1}^{C_2}\tr\left[\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\psi_{1j'}(\beta_0)\psi_{1j}(\beta_0)'\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\right]\right)\\
	&=\tr\left[\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\E\left(\frac{1}{C_1C_2^2}\sum_{j,j'=1}^{C_2}\psi_{1j'}(\beta_0)\psi_{1j}(\beta_0)'\right)\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\right]\\
	&= \tr\left[\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\left[ \frac{1}{C_1C_2}\V\left(\psi_{11}(\beta_0)\right)+\frac{C_2-1}{C_1C_2}\E\left(\psi_{11}(\beta_0)\psi_{12}(\beta_0)'\right)\right]\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\right]\\
	&\leq \tr(\Id)=p,
\end{align*}
where the last inequality follows from $\V(\mathbb{P}_n(\beta_0))=\frac{1}{C_1C_2}\V\left(\psi_{11}(\beta_0)\right)+\frac{C_2-1}{C_1C_2}\E\left(\psi_{11}(\beta_0)\psi_{12}(\beta_0)'\right)+\frac{C_1-1}{C_1C_2}\E\left(\psi_{11}(\beta_0)\psi_{21}(\beta_0)'\right)$ with $\E\left(\psi_{11}(\beta_0)\psi_{12}(\beta_0)'\right)$ and $\E\left(\psi_{11}(\beta_0)\psi_{21}(\beta_0)'\right)$ symmetric positive definite. All in all, we can claim by Markov's inequality that $$\frac{1}{C_1} \V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\mathbb{Q}_{1,n}(\beta_0)\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}=O_P(1).$$
Let us now consider the following decomposition:
\begin{align*}
	\frac{1}{C_1}\V(\mathbb{P}_n(\beta_0))^{-1/2}\left(\mathbb{Q}_{1,n}(\widehat{\beta})-\mathbb{Q}_{1,n}(\beta_0)\right)\V(\mathbb{P}_n(\beta_0))^{-1/2}&=R_1+R_1'+R_2+R_3+R_3'+R_4,
	\end{align*}
where
\begin{align*}
	R_1 & := \frac{1}{C_1^2}\sum_{i=1}^{C_1}\left(\frac{1}{C_2}\sum_{j=1}^{C_2}\V(\mathbb{P}_n(\beta_0))^{-1/2}\big(\psi_{ij}(\widehat{\beta}) - \psi_{ij}(\beta_0)\big)\right)\left(\frac{1}{C_2}\sum_{j=1}^{C_2}\V(\mathbb{P}_n(\beta_0))^{-1/2}\psi_{ij}(\beta_0)\right)',\\
	R_2 & := \frac{1}{C_1^2}\sum_{i=1}^{C_1}\left(\frac{1}{C_2}\sum_{j=1}^{C_2}\V(\mathbb{P}_n(\beta_0))^{-1/2}\big(\psi_{ij}(\widehat{\beta}) - \psi_{ij}(\beta_0)\big)\right)^{\otimes 2}, \\
	R_3 & := -C_1^{-1}\left(\frac{1}{C_1C_2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}\V(\mathbb{P}_n(\beta_0))^{-1/2}\big(\psi_{ij}(\widehat{\beta}) - \psi_{ij}(\beta_0)\big)\right)\left(\V(\mathbb{P}_n(\beta_0))^{-1/2}\mathbb{P}_n(\beta_0)\right)', \\
	R_4 & := -C_1^{-1}\left(\frac{1}{C_1C_2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}\V(\mathbb{P}_n(\beta_0))^{-1/2}\big(\psi_{ij}(\widehat{\beta}) - \psi_{ij}(\beta_0)\big)\right)^{\otimes 2}.
\end{align*}
Triangle, Cauchy-Schwarz and Lipschitz inequalities ensure:
\begin{align*}
	\left|\left|R_1\right|\right|&\leq \frac{1}{C_1^2}\sum_{i=1}^{C_1}\left|\left|\frac{1}{C_2}\sum_{j=1}^{C_2}\V(\mathbb{P}_n(\beta_0))^{-1/2}\big(\psi_{ij}(\widehat{\beta}) - \psi_{ij}(\beta_0)\big)\right|\right|\left|\left|\frac{1}{C_2}\sum_{j=1}^{C_2}\V(\mathbb{P}_n(\beta_0))^{-1/2}\psi_{ij}(\beta_0)\right|\right|\\
&\leq \frac{\left|\left|\widehat{\beta}-\beta_0\right|\right|}{C_1^2}\left|\left|\V(\mathbb{P}_n(\beta_0))^{-1/2}\right|\right|\sum_{i=1}^{C_1}\left(\frac{1}{C_2}\sum_{j=1}^{C_2}\sup_{b\in \Theta}\left|\left|\Deriv{\psi_{ij}(b)}{\beta}\right|\right|\right)\left|\left|\frac{1}{C_2}\sum_{j=1}^{C_2}\V(\mathbb{P}_n(\beta_0))^{-1/2}\psi_{ij}(\beta_0)\right|\right|\\
	&\leq \frac{||\hat{\beta}-\beta_0||}{\sqrt{C_1}}\times  \lambda_{\min}^{-1/2}\left(\V(\mathbb{P}_n(\beta_0))\right)\\
	&~~~ \times \sqrt{\frac{1}{C_1C_2}\sum_{i,j}\sup_{b\in \Theta}\left|\left|\Deriv{\psi_{ij}(b)}{\beta}\right|\right|^2} \sqrt{\frac{1}{C_1^2C_2^2}\sum_{i=1}^{C_1}\left|\left| \sum_{j=1}^{C_2}\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\psi_{ij}(\beta_0) \right|\right|^2}.
	\end{align*}

We have previously shown that $\frac{1}{C_1^2C_2^2}\sum_{i=1}^{C_1}\left|\left| \sum_{j=1}^{C_2}\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\psi_{ij}(\beta_0) \right|\right|^2=O_P(1)$. We have also established that $(\widehat{\beta}-\beta_0)\mathds{1}\{\mathcal{E}_n\}=-\left(\widehat{J}'\Wh \mathbb{D}_n(\widetilde{\beta})\right)^{+}\widehat{J}\Wh \mathbb{P}_n(\beta_0)\mathds{1}\{\mathcal{E}_n\}$. As $\lim_n P(\mathcal{E}_n)=1$ and $ \left(\widehat{J}'\Wh \mathbb{D}_n(\widetilde{\beta})\right)^{+}\widehat{J}\Wh $ converges in probability to $\left(J'\W J\right)^{-1}J'\W $, it follows that $\left|\left|\widehat{\beta}-\beta_0\right|\right|=O_P\left(\left|\left|\mathbb{P}_n(\beta_0)\right|\right|\right)=O_p\left(\left|\left|\V\left(\mathbb{P}_n(\beta_0)\right)\right|\right|^{1/2}\right)=O_p\left(\lambda_{\max}^{1/2}\left(\V\left(\mathbb{P}_n(\beta_0)\right)\right)\right)$, and finally $\frac{||\hat{\beta}-\beta_0||}{\lambda_{\max}^{1/2}\left(\V(\mathbb{P}_n(\beta_0))\right)}=O_P(1)$. Combining the previous remarks with $$E\left(\frac{1}{C_1C_2}\sum_{i,j}\sup_{b\in \Theta}\left|\left|\Deriv{\psi_{ij}(b)}{\beta}\right|\right|^2\right)=E\left(\sup_{b\in \Theta}\left|\left|\Deriv{\psi_{11}(b)}{\beta}\right|\right|^2\right)<\infty$$ 
and $\frac{\lambda_{\max}^{1/2}\left(\V(\mathbb{P}_n(\beta_0))\right)}{\lambda_{\min}^{1/2}\left(\V(\mathbb{P}_n(\beta_0))\right)}=O(1)$, we conclude that $\left|\left|R_1\right|\right|=\left|\left|R_1'\right|\right|=O_P(C_1^{-1/2})=o_P(1)$. As for $R_2$, we can write
\begin{align*}
	||R_2|| \le C_1^{-1}\frac{||\widehat{\beta}-\beta_0||^2}{\lambda_{\min}\left(\V(\mathbb{P}_n(\beta_0))\right)}\frac{1}{C_1C_2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}\sup_{b \in \Theta}\left|\left|\Deriv{\psi_{ij}(b)}{\beta}\right|\right|^2,
\end{align*}
and the right-hand side is $O_P(C_1^{-1}) = o_P(1)$, following the reasoning for $R_1$. Analogous arguments yield $\left|\left|R_3\right|\right| \vee \left|\left|R_4\right|\right| = O_P(C_1^{-1}) = o_P(1)$. This ensures that Assumption \ref{as:consistent_V} holds for $\widehat{V}_1$ and $\widehat{V}^{inf}_1$. Similar reasoning holds for $\widehat{V}_2$ and $\widehat{V}^{inf}_2$. 

\medskip

Let $\mathbb{Q}_{12,n}(\beta)=\frac{1}{C_1C_2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}\left(\psi_{ij}(\beta)-\mathbb{P}_n(\beta)\right)^{\otimes 2}=\frac{1}{C_1C_2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}\psi_{ij}(\beta)^{\otimes 2}-\mathbb{P}_n(\beta)^{\otimes 2}$. We can write:
\begin{align*}
	&\left|\left|\V(\overline{Y})^{-1/2}(\widehat{V}_{12}-\widehat{V}_{12}^{\inf})\V(\overline{Y})^{-1/2}\right|\right|\\
	&\leq\frac{1}{C_1C_2}\left|\left|\V(\overline{Y})\right|\right|^{-1}\left|\left|\V\left(\mathbb{P}_n(\beta_0)\right)\right|\right|\left|\left|\V(\mathbb{P}_n(\beta_0))^{-1/2}\left(\mathbb{Q}_{12,n}(\widehat{\beta})-\mathbb{Q}_{12,n}(\beta_0)\right)\V(\mathbb{P}_n(\beta_0))^{-1/2}\right|\right|\left|\left|\widehat{M}\right|\right|^2\\
	&+\frac{1}{C_1C_2}\left|\left|\V(\overline{Y})\right|\right|^{-1}\left|\left|\V\left(\mathbb{P}_n(\beta_0)\right)\right|\right|\left|\left| \V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\mathbb{Q}_{12,n}(\beta_0)\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\right|\right| \times \\ 
	& \,\,\,\, \left(2\left|\left|M\right|\right| \left|\left|\widehat{M}-M\right|\right|+  \left|\left|\widehat{M}-M\right|\right|^2\right)\\
	&\leq \frac{1}{C_1C_2}\left|\left|\V(\mathbb{P}_n(\beta_0))^{-1/2}\left(\mathbb{Q}_{12,n}(\widehat{\beta})-\mathbb{Q}_{12,n}(\beta_0)\right)\V(\mathbb{P}_n(\beta_0))^{-1/2}\right|\right| O_P(1)\\
	&+\frac{1}{C_1C_2}\left|\left| \V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\mathbb{Q}_{12,n}(\beta_0)\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\right|\right|o_P(1).
\end{align*}
Using the fact that $ \V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\mathbb{Q}_{12,n}(\beta_0) \V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}=\frac{1}{C_1C_2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}\left(\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\psi_{ij}(\beta_0)\right)^{\otimes 2}-\left(\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\mathbb{P}_n(\beta_0)\right)^{\otimes 2}$
and that $\left(\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\mathbb{P}_n(\beta_0)\right)^{\otimes 2}$ is a symmetric positive matrix, we get 
$$\left|\left|\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\mathbb{Q}_{12,n}(\beta_0)\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\right|\right|\leq \frac{1}{C_1C_2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}\left|\left|\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\psi_{ij}(\beta_0)\right|\right|^2.$$
We also have:
\begin{align*}
E\left[	\frac{1}{C_1^2C_2^2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}\left|\left|\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\psi_{ij}(\beta_0)\right|\right|^2\right]&=\frac{1}{C_1C_2}E\left(\psi_{11}(\beta_0)'\V\left(\mathbb{P}_n(\beta_0)\right)^{-1}\psi_{11}(\beta_0)\right)\\
&=\tr\left[\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\frac{1}{C_1C_2}\V(\psi_{11}(\beta_0))\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\right]\\
&\leq \tr(\Id)=p
	\end{align*}
where the last inequality follows from $\V(\mathbb{P}_n(\beta_0))=\frac{1}{C_1C_2}\V\left(\psi_{11}(\beta_0)\right)+\frac{C_2-1}{C_1C_2}\E\left(\psi_{11}(\beta_0)\psi_{12}(\beta_0)'\right)+\frac{C_1-1}{C_1C_2}\E\left(\psi_{11}(\beta_0)\psi_{21}(\beta_0)'\right)$ with $\E\left(\psi_{11}(\beta_0)\psi_{12}(\beta_0)'\right)$ and $\E\left(\psi_{11}(\beta_0)\psi_{21}(\beta_0)'\right)$ some symmetric positive matrices. We conclude that 
\begin{equation}
	\label{eq:control_V_12_1}
	\frac{1}{C_1C_2}\left|\left| \V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\mathbb{Q}_{12,n}(\beta_0)\V\left(\mathbb{P}_n(\beta_0)\right)^{-1/2}\right|\right|=O_P(1).
\end{equation}
Moreover:
\begin{align*}
&\frac{1}{C_1C_2}\left|\left|\V(\mathbb{P}_n(\beta_0))^{-1/2}\left(\mathbb{Q}_{12,n}(\widehat{\beta})-\mathbb{Q}_{12,n}(\beta_0)\right)\V(\mathbb{P}_n(\beta_0))^{-1/2}\right|\right|	\\
& \leq 2||\widetilde{R}_1|| + ||\widetilde{R}_2|| + (C_1C_2)^{-1}\left|\left|\left(\V(\mathbb{P}_n(\beta_0))^{-1/2}\mathbb{P}_n(\beta_0)\right)^{\otimes 2}-\left(\V(\mathbb{P}_n(\beta_0))^{-1/2}\mathbb{P}_n(\widehat{\beta})\right)^{\otimes 2}\right|\right|,
\end{align*}
where $\widetilde{R}_1 :=\frac{1}{C_1^2C_2^2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}\V(\mathbb{P}_n(\beta_0))^{-1/2}\left(\psi_{ij}(\widehat{\beta})-\psi_{ij}(\beta_0)\right)\left(\V(\mathbb{P}_n(\beta_0))^{-1/2}\psi_{ij}(\beta_0)\right)'$ and $\widetilde{R}_2:=\frac{1}{C_1^2C_2^2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}\left(\V(\mathbb{P}_n(\beta_0))^{-1/2}\left(\psi_{ij}(\widehat{\beta})-\psi_{ij}(\beta_0)\right)\right)^{\otimes 2}.$ We can bound $\widetilde{R}_1$ and $\widetilde{R}_2$ as follows:
\begin{align*}
	& ||\widetilde{R}_1|| \\
	\le &  (C_1C_2)^{-1/2}\left|\left|\V(\mathbb{P}_n(\beta_0))^{-1/2}\right|\right|\,\left|\left|\widehat{\beta}-\beta_0\right|\right|\sqrt{\frac{1}{C_1C_2}\sum_{i,j}\left|\left|\sup_{b\in \Theta}\Deriv{\psi_{ij}(b)}{\beta}\right|\right|^2}\sqrt{\frac{1}{C_1^2C_2^2}\sum_{i,j}\left|\left|\V(\mathbb{P}_n(\beta_0))^{-1/2}\psi_{ij}(\beta_0)\right|\right|^2} \\
	= & O_P((C_1C_2)^{-1/2})
\end{align*} 
and
\begin{align*}
	||\widetilde{R}_2|| \le (C_1C_2)^{-1}\left|\left|\V(\mathbb{P}_n(\beta_0))^{-1/2}\right|\right|^2\,\left|\left|\widehat{\beta}-\beta_0\right|\right|^2\frac{1}{C_1C_2}\sum_{i,j}\left|\left|\sup_{b\in \Theta}\Deriv{\psi_{ij}(b)}{\beta}\right|\right|^2 = O_P((C_1C_2)^{-1}).
\end{align*}
The term
\begin{equation*}
	(C_1C_2)^{-1}\left|\left|\left(\V(\mathbb{P}_n(\beta_0))^{-1/2}\mathbb{P}_n(\beta_0)\right)^{\otimes 2}-\left(\V(\mathbb{P}_n(\beta_0))^{-1/2}\mathbb{P}_n(\widehat{\beta})\right)^{\otimes 2}\right|\right|
\end{equation*}
can be controlled in a similar fashion as $R_3+R_3'+R_4$, and we deduce that this term is $O_P((C_1C_2)^{-1})$. Gathering all intermediary results, 
\begin{equation}
	\label{eq:control_V_12_2}
	\frac{1}{C_1C_2}\left|\left|\V(\mathbb{P}_n(\beta_0))^{-1/2}\left(\mathbb{Q}_{12,n}(\widehat{\beta})-\mathbb{Q}_{12,n}(\beta_0)\right)\V(\mathbb{P}_n(\beta_0))^{-1/2}\right|\right| = o_P(1).
\end{equation}
Equations~\eqref{eq:control_V_12_1} and~\eqref{eq:control_V_12_2} ensure Assumption~\ref{as:consistent_V} is satisfied by $\widehat{V}_{12}$ and $\widehat{V}_{12}^{\inf}$. This achieves the proof. 

\medskip

\textbf{Proof of asymptotic validity of our inference method:} The array $(N_{ij},(Z_{ij\ell})_{\ell \ge 1})_{i,j \ge 1}$ is dissociated and separately exchangeable with a distribution independent from $n$. This is also the case for $(Y_{ij})_{i,j \ge 1}$ with $Y_{ij} = -B\left(J'\W J \right)^{-1} J'\W \psi_{ij}(\beta_0)$. Assumption~\ref{as:asym} has been imposed. Assumptions~\ref{as:as_lin} and~\ref{as:consistent_V} have been shown to be implied by Assumptions~\ref{as:GMM_regul} and~\ref{as:GMM_main}. The conditions to apply Theorem~\ref{thm:point_multiv} are met, hence the result. $\Box$



