\section{Additional lemmas and proofs}

\begin{lemma}
	Let $X$ a closed and bounded subset of a separable Hilbert space $H$ equipped with a scalar product $\left\langle .,.\right\rangle$. Let $(e_k)_{k\in \mathbb{N}}$ an orthonormal basis of $H$. $X$ is compact if and only if $\lim_{N\rightarrow\infty}\sup_{x\in X}\sum_{k>N}\left\langle x,e_k \right\rangle^2=0$.\label{lem:compact_Hilbert}
\end{lemma}

\medskip

\noindent
\textit{Proof of Lemma~\ref{lem:compact_Hilbert}.} If $X$ is compact and  $\lim_{N\rightarrow\infty}\sup_{x\in X}\sum_{k>N}\left\langle x,e_k \right\rangle^2>0$, then for $\varepsilon=\frac{1}{2}\lim_{N\rightarrow\infty}\sup_{x\in X}\sum_{k>N}\left\langle x,e_k \right\rangle^2$, we have a sequence $x_n\in X$ such that $\sum_{k>N}\left\langle x_N,e_k \right\rangle^2>\varepsilon$. We can extract from $x_n$ a subsequence $x_{\sigma(n)}$ that converges to some $y\in X$. It follows that \begin{align*}\varepsilon&<\sum_{k>\sigma(N)}\left\langle x_{\sigma(N)},e_k \right\rangle^2\\
	&\leq  2\sum_{k>\sigma(N)}\left\langle x_{\sigma(N)}-y,e_k \right\rangle^2+2\sum_{k>\sigma(N)}\left\langle y,e_k \right\rangle^2\\
	&\leq 2 ||x_{\sigma(N)}-y||^2+2\sum_{k>\sigma(N)}\left\langle y,e_k \right\rangle^2\\
	&<\varepsilon/2 \text{ for sufficiently large }N, \text{ a contradiction.}
\end{align*}
Reciprocally assume that $\lim_{N\rightarrow\infty}\sup_{x\in X}\sum_{k>N}\left\langle x,e_k \right\rangle^2=0$. Let $(x_n)_{n\geq 1}$ a sequence in $X$. Since for any $k$, $\left\langle x_n,e_k \right\rangle^2\leq \sup_{x\in X}||x||^2<\infty$, there exists a subsequence $x_{\sigma_1(n)}$ such that $\left\langle x_{\sigma_1(n)},e_1 \right\rangle$ converges. Next there exists a sub-sub sequence such that $\left\langle x_{\sigma_2\circ \sigma_1(n)},e_2 \right\rangle$ converges, and so on. Let $y_n=x_{\sigma_n\circ \cdots \circ \sigma_1(n)}$. This is a subsequence of $(x_n)_{n\geq 1}$ and for any $k$, $\left(\left\langle y_n,e_k\right\rangle\right)_{n}$ converges (and next is Cauchy). Fix an arbitrary $\varepsilon>0$ and $N$ such that $\sup_{x\in X}\sum_{k>N}\left\langle x,e_k \right\rangle^2\leq \varepsilon$. There exists $N'$ such that $\sup_{k\leq N}\sup_{m,m'\geq N'}\left|\left\langle y_m,e_k\right\rangle-\left\langle y_{m'},e_k\right\rangle\right|\leq \sqrt{\varepsilon/N}$. Next, for $m,m'\geq N'$:
\begin{align*}
	\norm{y_m-y_{m'}}^2&=\sum_{k\geq1}\left\langle y_m-y_{m'},e_k\right\rangle^2\\
	&\leq \sum_{k\leq N}\left\langle y_m-y_{m'},e_k\right\rangle^2+2 \sum_{k>N}\left\langle y_m,e_k\right\rangle^2+2 \sum_{k>N}\left\langle y_{m'},e_k\right\rangle^2\\
	&\leq 5\varepsilon.
\end{align*}
This means that $(y_n)_n$ is Cauchy and next converges (because an Hilbert is complete). Because $X$ is closed, $(y_n)_n$ converges in $X$. This ensures that $X$ is compact. $\Box$


\begin{lemma}\label{lem:compacity_mu_nu}
	The set $\overline{\mathcal{V}_{m,H,\RP}}$ is compact in $\ell^2_d$.
\end{lemma}

\medskip

\noindent
\textit{Proof of Lemma~\ref{lem:compacity_mu_nu}.} We only prove the result for $d>1$ since the proof is analoguous with $d=1$. We first define $\mathcal{V}_{m,H,\RP}^n$ formally. For any  $h \in H$, let $X_h:=\E[h(U_{10},U_{01},U_{11})\mid U_{10}]$ and  define
$$\begin{array}{rrcl} h_1: & [0,1]^3 & \to & \R \\
 & (u_1,u_2,u_3) & \mapsto & \left(\lambda_{\min}^*(V(X_h)) + \mathds{1}\{\lambda_{\min}^*(V(X_h))=\infty\}\right)^{-1/2}X_h\end{array}.	$$
We define $h_2$ symmetrically. Then, for every $\bm{\mu} \in \ell^2_d$, let $ \Omega_j(\bm{\mu}) := \sum_{\k \in \K_j} \mu_{\k}^{\otimes 2}$ and let us introduce the sets $H_0 := \left\{ h \in H: h_j \in H, j=1,2 \right\}$ and 
	\begin{align*}
		K_H:=&\left\{\bm{\mu} \in \ell_d^2, \bm{\mu}=\left(\int h(u) \psi_{k_1}(u_1)\psi_{k_2}(u_2)\psi_{k_3}(u_3)d\lambda^{\otimes 3}(u)\right)_{\k\in \mathbb{N}^3}\text{ for } h \in H_0\right\},\\
		K_m := & \Bigg\{ \bm{\mu} \in \ell_d^2, \lambda_{\min}\left(\sum_{j=1}^4\Omega_j(\bm{\mu})\right) \ge m, \\
		& \quad \text{ either } \big[\textrm{range}(\Omega_3(\bm{\mu}))\subseteq \textrm{range}(\Omega_1(\bm{\mu})+\Omega_2(\bm{\mu})) \\
        & \quad \text{ and } \lambda_{\max}(\Omega_3(\bm{\mu})) \le m^{-1} \lambda_{\min}^*(\Omega_1(\bm{\mu})+\Omega_2(\bm{\mu}))\big], \\
		& \quad \text{ or } \big[\Omega_{1}(\bm{\mu})\wedge \Omega_{2}(\bm{\mu})= 0 \text{ and } \lambda_{\min}\left(\Omega_1(\bm{\mu})+\Omega_{2}(\bm{\mu}) +\Omega_4(\bm{\mu})\right)\ge m\big] \Bigg\},\\
        \mathcal{V}_{m,H,\RP}^n:=&\left\{\bm{\nu}^n \in \ell^2\left(\mathbb{N}^3,\mathbb{R}^d\right) : \nu_{\k}^n \text{ satisfies~\eqref{eq:def_nu} }\forall\k\in\N^{3}, \bm{\mu} \in K_H \cap K_m \right\},
	\end{align*}
The set $\overline{\mathcal{V}_{m,H,\RP}}$ is closed in $\ell^2_d$. Let us prove that $\overline{\mathcal{V}_{m,H,\RP}}$ is bounded and satisfies
\begin{equation*}
	\lim_{\underline{k}\rightarrow \infty} \sup_{\bm{\nu} \in \overline{\mathcal{V}_{m,H,\RP}}}\sum_{\k:\max(k_1,k_2,k_3)>\underline{k}}\norm{\nu_{\k}}^2=0.
\end{equation*}

\medskip

Let $(\bm{\nu}^n)_n$ be some arbitrary sequence that satisfies $\bm{\nu}^n \in \mathcal{V}_{m,H,\RP}^n$ for every $n$. By definition, this sequence is associated with a sequence $(\bm{\mu}^n)_n$ such that $\bm{\mu}_n \in K_m \cap K_H$ for every $n$.
The key step is to derive an upper bound on $||\nu_{\k}^n||$ that solely depends on $\bm{\mu}^n$, $m$ and $H$ for every $\k \in \N^{3\ast}$. In the rest of the proof, we use the shortcut $\Omega_j^n$ for $\Omega_j(\bm{\mu}^n)$ and resort to the following useful observation: any $\bm{\mu}_n \in K_m \cap K_H$ satisfies
\begin{equation}
	\label{eq:invertibility_V_Y}
	\lambda_{\min}\left(\Omega_1^n+\Omega_2^n+\Omega_3^n+\Omega_4^n\right) \ge m.
\end{equation}


\medskip

\textbf{Upper bound on $||\nu_{\k}^n||$:} By definition of $\mathcal{V}_{m,H,\RP}^n$, $\nu_{\k}^n$ satisfies
$$\nu_{\k}^n = \left[\Omega_3^n+\Omega_4^n+C_2\Omega_1^n + C_1\Omega_2^n\right]^{-1/2} \gamma_{\k,n} \mu_{\k},$$
where
$$\gamma_{\k,n}=\left|\begin{array}{cl} C_2^{1/2} & \text{ if } \k\in\K_1 \\ C_1^{1/2} & \text{ if } \k\in\K_2 \\ 1 & \text{ otherwise.} \end{array}\right.$$

\medskip

Let us focus on $\k \in \K_1$ first. Note $A_1 \gg A_2$ when $A_1-A_2$ is symmetric semi-definite positive. Then, using~\eqref{eq:invertibility_V_Y},
$$\Omega_3^n+\Omega_4^n+C_2\Omega_1^n + C_1\Omega_2^n \gg C_2\left[\frac{m}{C_2} \Id + \left(1-\frac{1}{C_2}\right) \Omega_1^n\right].$$
Hence, for all $k\in\K_1$.
$$\|\nu_{\k}^n\|^2 \le (\mu_{\k}^n)'\left[\frac{m}{C_2} \Id + \left(1-\frac{1}{C_2}\right) \Omega_1^n\right]^{-1} \mu_{\k}^n.$$
Now, let $B:=$span$(\mu_{\k}^n: \; \k\in\K_1)$ and $x=\sum_{\k\in\K_1} \alpha_{\k} \mu_{\k}^n \in B$. If $B=\{0\}$, $\|\nu_{\k}^n\|^2=0$. Otherwise, if $\Omega_1^nx=0$, then $x'\Omega_1^nx=0$ and thus $(\mu_k^n)'x=0$ for all $k$. Hence,
$(\sum_{\k\in\K_1} \alpha_{\k}\mu_{\k}^n)'x=0$, implying that $x=0$. Let $f$ be the endomorphism associated to $\Omega_1^n$.  Then $f(B)\subseteq B$ and since Ker$(f)\cap B=\{0\}$, $f_{|B}$ is invertible with smallest eigenvalue equal to $\lambda_{\min}^*(\Omega_1^n)$. Then, for all $x\in B$, because $C_2\ge 2$,
$$x' \left[\frac{m}{C_2} \Id + \left(1-\frac{1}{C_2}\right) \Omega_1^n\right] x \ge \frac{\lambda_{\min}^*(\Omega_1^n)}{2} \|x\|^2.$$
As a result, for all $\k\in\K_1$,
\begin{equation}
	\label{eq:up_bound_nu_k1}
	\|\nu_{\k}^n\|^2 \le (\mu_{\k}^n)' \left[\frac{m}{C_2} \Id + \left(1-\frac{1}{C_2}\right) \Omega_1^n\right]^{-1} \mu_{\k}^n \le 2\lambda_{\min}^*(\Omega_1^n)^{-1} \|\mu_{\k}^n\|^2
\end{equation}
since $\mu_{\k}^n\in B$ for all $\k\in\K_1$. Similarly, for all $\k\in\K_2$,
\begin{equation}
	\label{eq:up_bound_nu_k2}
	\|\nu_{\k}^n\|^2 \le 2\lambda_{\min}^*(\Omega_2^n)^{-1} \|\mu_{\k}^n\|^2.
\end{equation}
For $\k\in\K_{34}$, we simply use $\Omega_3^n+\Omega_4^n+C_2\Omega_1^n + C_1\Omega_2^n \gg \Omega_1^n+\Omega_2^n+\Omega_3^n+\Omega_4^n\gg m \Id$. Hence,
\begin{equation}
	\label{eq:up_bound_nu_k3_k4}
	\|\nu_{\k}^n\|^2 \le \lambda_{\min}\left(\Omega_1^n+\Omega_2^n+\Omega_3^n+\Omega_4^n\right)^{-1} \|\mu_{\k}^n\|^2 \le m^{-1}\|\mu_{\k}^n\|^2.
\end{equation}

\medskip

\textbf{Boundedness and uniform tail control over $\overline{\mathcal{V}_{m,H,\RP}}$:} Putting all steps together (and recalling that $\lambda_{\min}^*(\Omega_j^n) = \infty$ when $\mu_k^n = \zero$ for every $\k \in \K_j$), we obtain
\begin{align*}
	\sup_{n\ge 1}\sup_{\bm{\nu} \in \mathcal{V}_{m,H,\RP}^n}||\bm{\nu}||^2
	\le & m^{-1}\sup_{\bm{\mu} \in K_m \cap K_H}\bigg\{\sum_{\k \in \K_{34}}||\mu_{\k}||^2 \bigg\} \\
	 & + \sup_{\bm{\mu} \in K_m \cap K_H}\bigg\{\sum_{\k\in\K_{12}}\frac{||\mu_{\k}||^2}{\lambda_{\min}^*(\Omega_j^n) + \mathds{1}\{\lambda_{\min}^*(\Omega_j^n) = \infty\}}\bigg\}.
\end{align*}
We recall that $H$ is compact (hence bounded) in $L_2([0,1]^3,\Rb^d)$ and $\tau$, $\tau_1$ and $\tau_2$ belong to $H$. As a result, there exists $M_H$ such that
\begin{equation*}
	\sup_{\bm{\mu} \in K_m \cap K_H}\bigg\{\sum_{\k \in \K_{34}}||\mu_{\k}||^2 \bigg\} \vee \sup_{\bm{\mu} \in K_m \cap K_H}\bigg\{\sum_{\k\in\K_{12}}\frac{||\mu_{\k}||^2}{\lambda_{\min}^*(\Omega_j^n) + \mathds{1}\{\lambda_{\min}^*(\Omega_j^n) = \infty\}}\bigg\} \le M_H.
\end{equation*}
Thus, $\sup_{n\ge 1}\sup_{\bm{\nu} \in \mathcal{V}_{m,H,\RP}^n}||\bm{\nu}||^2 \le (m^{-1}+1)M_H$. Using the fact that
\begin{equation}
	\label{eq:sup_equivalence}
	\sup_{n\ge 1}\sup_{\bm{\nu} \in \mathcal{V}_{m,H,\RP}^n}||\bm{\nu}||^2 = \sup_{\bm{\nu} \in \cup_{n\ge 1}\mathcal{V}_{m,H,\RP}^n}||\bm{\nu}||^2 = \sup_{\bm{\nu} \in \overline{\mathcal{V}_{m,H,\RP}}}||\bm{\nu}||^2,
\end{equation}
we can claim that $\overline{\mathcal{V}_{m,H,\RP}}$ is bounded in $\ell^2_d$.

\medskip

There remains to prove
\begin{equation*}
	\lim_{\underline{k}\rightarrow \infty} \sup_{\bm{\nu} \in \overline{\mathcal{V}_{m,H,\RP}}}\sum_{\k:\max(k_1,k_2,k_3)>\underline{k}}\norm{\nu_{\k}}^2=0.
\end{equation*}
By construction, $\tau$, $\tau_1$ and $\tau_2$ belong to $H$ which implies
\begin{equation}
	\label{eq:unif_tail_condition_tau}
	\lim_{\underline{k} \to \infty} \sup_{\bm{\mu} \in K_m \cap K_H} \sum_{\k : \max(k_1,k_2,k_3) > \underline{k}} ||\mu_{\k}||^2 = 0,
\end{equation}
and
\begin{equation}
	\label{eq:unif_tail_condition_tauj}
	\lim_{\underline{k} \to \infty} \sup_{\bm{\mu} \in K_m \cap K_H} \sum_{\k \in \K_j : \max(k_1,k_2,k_3) > \underline{k}} \frac{||\mu_{\k}||^2}{\lambda_{\min}^*(\Omega_j^n) + \mathds{1}\{\lambda_{\min}^*(\Omega_j^n) = \infty\}} = 0, \, j = 1,2.
\end{equation}
Combining~\eqref{eq:up_bound_nu_k1},~\eqref{eq:up_bound_nu_k2},~\eqref{eq:up_bound_nu_k3_k4},~\eqref{eq:sup_equivalence},~\eqref{eq:unif_tail_condition_tau} and~\eqref{eq:unif_tail_condition_tauj}, we obtain
\begin{equation*}
	\lim_{\underline{k}\rightarrow \infty} \sup_{n\ge 1}\sup_{\bm{\nu} \in \mathcal{V}_{m,H,\RP}^n}\sum_{\k:\max(k_1,k_2,k_3)>\underline{k}}\norm{\nu_{\k}}^2 = \lim_{\underline{k}\rightarrow \infty} \sup_{\bm{\nu} \in \overline{\mathcal{V}_{m,H,\RP}}}\sum_{\k:\max(k_1,k_2,k_3)>\underline{k}}\norm{\nu_{\k}}^2 = 0.
\end{equation*}


\medskip

\textbf{Conclusion:} We consider $(e_1,...,e_d)$ the canonical basis of $\mathbb{R}^d$ and $(u_j)_{j\ge 1}$ a sequence of elements in $\ell^2_d$ such that $u_{j\k}=e_{j-\lfloor\frac{j-1}{d}\rfloor d}\mathds{1}\{\sigma\left(\lfloor\frac{j-1}{d}\rfloor\right)=\k\}$ for $\sigma$ a one-to-one mapping from $\N$ to $\N^{3}$. For any $\nu,\tilde{\nu} \in (\ell^2_d)^2$, we have: $\langle\nu,\tilde{\nu}\rangle_{\ell^2_d}=\sum_{\k\in\N^3}\nu_{\k}'\tilde{\nu}_{\k}=\sum_{\k\in\N^3}\sum_{\ell=1}^d\nu_{\k,\ell}\tilde{\nu}_{\k,\ell}$. We have: $\langle u_j,u_{j'}\rangle_{\ell^2_d}=\mathds{1}\{j=j'\}$ and next $(u_j)_{j\ge 1}$ is an orthonormal basis of $\ell^2_d$. We also note: $\norm{\nu_{\k}}^2= \sum_{j:\sigma\left(\lfloor\frac{j-1}{d}\rfloor\right)=\k}\langle \nu,u_{j}\rangle^2_{\ell^2_d}$. For any $\underline{j}$, let $$\underline{k}(\underline{j})=\min_{j\geq \underline{j}}\max\left(\sigma\left(\lfloor\frac{j-1}{d}\rfloor\right)_1,\sigma\left(\lfloor\frac{j-1}{d}\rfloor\right)_2,\sigma\left(\lfloor\frac{j-1}{d}\rfloor\right)_3\right)-1.$$ We have $\sum_{j>\underline{j}}\langle \nu,u_{j}\rangle^2_{\ell^2_d}\leq \sum_{\k:\max(k_1,k_2,k_3)>\underline{k}(\underline{j})}\norm{\nu_{\k}}^2$ and $\lim_{\underline{j}\rightarrow \infty}\underline{k}(\underline{j})=\infty$. This ensures:
\begin{align*}
	\lim_{\underline{j}\rightarrow \infty} \sup_{\bm{\nu} \in \overline{\mathcal{V}_{m,H,\RP}}}\sum_{j>\underline{j}}\langle \nu,u_{j}\rangle^2_{\ell^2_d}&\leq \lim_{\underline{k}\rightarrow \infty} \sup_{\bm{\nu} \in \overline{\mathcal{V}_{m,H,\RP}}}\sum_{\k:\max(k_1,k_2,k_3)>\underline{k}}\norm{\nu_{\k}}^2=0,
\end{align*}
and next Lemma \ref{lem:compact_Hilbert} ensures $\overline{\mathcal{V}_{m,H,\RP}}$ is compact. $\Box$

\medskip

In the next lemmas, we use the notation $\Sigma_j^n := \sum_{\k \in \K_j}(\nu_{\k}^n)^{\otimes 2}$ and, for any $\bm{\nu}^n \convLtwo \bm{\nu}^\infty$, $\Sigma_j^\infty := \sum_{\k \in \K_j}(\nu_{\k}^\infty)^{\otimes 2}$.

\begin{lemma}\label{lem:limit_behaviour_nu}
	We have
	\begin{equation}
		\label{eq:min_to_0}
		\lim_{n\to\infty}\sup_{\bm{\nu}^n \in \mathcal{V}_{m,H,\RP}^n}\min(\|\Sigma_1^n\|,\|\Sigma_2^n\|,\|\Sigma_3^n\|) = 0,
	\end{equation}
	\begin{equation}
		\label{eq:det_lower_bound}
		\liminf_{n\to\infty}\inf_{\bm{\nu}^n \in \mathcal{V}_{m,H,\RP}^n} \det(\Sigma_1^n+\Sigma_2^n+\Sigma_4^n) > 0,
	\end{equation}
	and
	\begin{equation}
		\label{eq:sigma_4_to_0}
		\lim_{n\to\infty}\sup_{\bm{\nu}^n \in \mathcal{V}_{m,H,\RP}^{n,G}}\|\Sigma_3^n\| = 0.
	\end{equation}
\end{lemma}



\medskip

\noindent
\textit{Proof of Lemma~\ref{lem:limit_behaviour_nu}.}
In the present lemma, the parameter $\bm{\mu}^n$ associated with $\bm{\nu}^n$ may depend on $n$. In that case, quantities such as $\Omega_j$, $j = 1,\dots,4$, also depend on $n$. We use the notation $\Omega_j^n$ to stress that dependence in the rest of the proof.

\medskip

\textbf{Proof of~\eqref{eq:min_to_0}:} First suppose $d=1$. If $\min(\Omega_1^n,\Omega_2^n,\Omega_3^n)=0$, we also have $\min(\|\Sigma_1^n\|,\|\Sigma_2^n\|,$ $\|\Sigma_3^n\|)=0$. Otherwise, using
$\Omega_1^n + \Omega_2^n + \Omega_4^n + \Omega_3^n = V(Y_{11}) \ge m$, $(\Omega_1^n+\Omega_2^n)/\Omega_3^n \ge m$ we get
\begin{align*}
	\Omega_3^n+\Omega_4^n+C_2\Omega_1^n + C_1\Omega_2^n \geq V(Y_{11}) + (\Cinf - 1)(\Omega_1^n+\Omega_2^n) \ge m + m(\Cinf - 1)\Omega_3^n.
\end{align*}
Then, using $\underline{C}\ge 2$ and the definition of $(\nu_{\k}^n)_{\k\in\K_3}$,
\begin{align*}
	\Sigma_3^n \leq \frac{\Omega_3^n}{\Cinf\left(\Cinf^{-1} m + (1-\Cinf^{-1})m\Omega_3^n\right)} \le \frac{1}{\Cinf(1-\Cinf^{-1})m} \le 2(m\Cinf)^{-1}.
\end{align*}
Hence, we  either have $\min(\|\Sigma_1^n\|,\|\Sigma_2^n\|,\|\Sigma_3^n\|)=0$ or $\min(\|\Sigma_1^n\|,\|\Sigma_2^n\|,\|\Sigma_3^n\|) \le 2(m\Cinf)^{-1}$. Equation \eqref{eq:min_to_0} follows. %, which implies Equation~\eqref{eq:majorization_sigmas} with $\eta_n := 1 / [\Cinf(1-\Cinf^{-1})m]$.

\medskip
Now suppose $d>1$. If $\|\Omega_1^n\|\wedge \|\Omega_2^n\|=0$, then $\min(\|\Sigma_1^n\|,\|\Sigma_2^n\|,\|\Sigma_3^n\|)=0$. Otherwise, we have $\textrm{range}(\Omega_3^n)\subseteq \textrm{range}(\Omega_1^n+\Omega_2^n)$ and $\lambda_{\max}(\Omega_3^n) \le m^{-1}\lambda_{\min}^*(\Omega_1^n+\Omega_2^n)$. Since $\lambda_{\min}\left( \sum_{j=1}^4\Omega_j^n \right) \ge m$, we obtain
$$\Omega_3^n+\Omega_4^n+C_2\Omega_1^n + C_1\Omega_2^n \gg m \Id + (\underline{C}-1) (\Omega_1^n +\Omega_2^n).$$
This ensures
\begin{equation}
	\|\Sigma_3^n\| \le \sum_{\k \in \K_3} ||\nu_{\k}^n||^2 \le \frac{1}{\underline{C}} \sum_{\k\in\K_3} (\mu_{\k}^n)' \left[\frac{m}{\underline{C}} \Id + \left(1-\frac{1}{\underline{C}}\right) (\Omega_1^n +\Omega_2^n)\right]^{-1} \mu_{\k}^n.	
	\label{eq:ineg_Sigma4}
\end{equation}
The same reasoning as in the proof of Lemma~\ref{lem:compacity_mu_nu} shows that the endomorphism associated to $\Omega_1^n+\Omega_2^n$ is invertible on its range, which is equal to $B:=$span$(\mu_{\k}^n: \; \k\in\K_{12})$. Also, $\textrm{range}(\Omega_3^n)=$span$(\mu_{\k}^n: \; \k\in\K_3)$, which implies that $\mu_{\k}^n\in B$ for all $\k\in\K_3$. Then, reasoning as above, we obtain
\begin{align*}
	\sum_{\k\in\K_3} (\mu_{\k}^n)' \left[\frac{m}{\underline{C}} \Id + \left(1-\frac{1}{\underline{C}}\right) (\Omega_1^n +\Omega_2^n)\right]^{-1} \mu_{\k}^n & \le \frac{1}{\left(1-\Cinf^{-1}\right)\lambda_{\min}^*\left(\Omega_1^n+\Omega_2^n\right)} \sum_{\k\in\K_3}||\mu_k^n||^2 \\
	& \le \frac{2\tr\left(\Omega_3^n\right)}{\lambda_{\min}^*\left(\Omega_1^n+\Omega_2^n\right)} \le \frac{2\lambda_{\max}\left(\Omega_3^n\right)}{\lambda_{\min}^*\left(\Omega_1^n+\Omega_2^n\right)} \le 2m^{-1}.
\end{align*}
This implies, in view of \eqref{eq:ineg_Sigma4}, that $\|\Sigma_3^n\| \le 2(m\Cinf)^{-1}$. Thus, in the end, we either have $\min(\|\Sigma_1^n\|,\|\Sigma_2^n\|,\|\Sigma_3^n\|)=0$ or $\min(\|\Sigma_1^n\|,\|\Sigma_2^n\|,\|\Sigma_3^n\|) \le 2(m\Cinf)^{-1}$, which implies \eqref{eq:min_to_0}.

\medskip
\textbf{Proof of~\eqref{eq:det_lower_bound}:} When $\textrm{range}(\Omega_3^n)\subseteq \textrm{range}(\Omega_1^n+\Omega_2^n)$ and $\lambda_{\max}(\Omega_3^n) \leq m^{-1}\lambda_{\min}^*(\Omega_1^n+\Omega_2^n)$, we have just shown that $\|\Sigma_3^n\|\le 2(m\Cinf)^{-1}$. Since $\Sigma_1^n+\Sigma_2^n+\Sigma_3^n+\Sigma_4^n=\Id$, we obtain that for all $n$ large enough, $\textrm{range}(\Omega_3^n)\subseteq \textrm{range}(\Omega_1^n+\Omega_2^n)$ and $\lambda_{\max}(\Omega_3^n) \leq m^{-1}\lambda_{\min}^*(\Omega_1^n+\Omega_2^n)$ imply
$\det(\Sigma_1^n+\Sigma_2^n+\Sigma_4^n) > 1/2$. Now, assume instead that $\|\Omega_1^n\|\wedge \|\Omega_2^n\|=0$ and $\lambda_{\min}\left(\Omega_1^n+\Omega_2^n+\Omega_4^n\right)\ge m$. Then, $\Omega_1^n+\Omega_2^n+\Omega_4^n\gg m \Id$ and thus,
$$\Omega_3^n+\Omega_4^n+C_2 \Omega_1^n + C_1 \Omega_2^n \gg \Omega_3^n + m \Id.$$
Hence, for any $x\in\R^d$ such that $x'x=1$,
\begin{align*}
	x'\Sigma_3^n x \le & x'\left(\Omega_3^n + m \Id\right)^{-1/2} \Omega_3^n \left(\Omega_3^n + m \Id\right)^{-1/2}x \\
	= & x'\left(\Omega_3^n + m \Id\right)^{-1/2} (\Omega_3^n + m \Id - m \Id) \left(\Omega_3^n + m \Id\right)^{-1/2}x \\
	= & \|x\|^2 -  x'\left(\Omega_3^n + m \Id\right)^{-1/2} (m \Id) \left(\Omega_3^n + m \Id\right)^{-1/2}x \\
	= & x'(\Sigma_1^n+\Sigma_2^n+\Sigma_3^n+\Sigma_4^n) x - m x'\left(\Omega_3^n + m \Id\right)^{-1} x.
\end{align*}
Hence,
\begin{equation}
	x'(\Sigma_1^n+\Sigma_2^n+\Sigma_4^n) x \ge m x'\left(\Omega_3^n + m \Id\right)^{-1} x.	
	\label{eq:for_condit_det}
\end{equation}
Moreover,
$$\Omega_3^n + m \Id \ll \Omega_3^n + \Omega_1^n+\Omega_2^n+\Omega_4^n = V(Y_{11}).$$
As a result,
$$x'\left(\Omega_3^n + m \Id\right)^{-1} x \ge \frac{1}{\lambda_{\max}(V(Y_{11}))}.$$
Since $H$ is compact, there exists $M_H$ such that $\lambda_{\max}\left(V(Y_{11})\right) \le M_H$. When combined with \eqref{eq:for_condit_det}, this implies
$$\lambda_{\min}(\Sigma_1^n+\Sigma_2^n+\Sigma_4^n) \ge \frac{m}{\lambda_{\max}(V(Y_{11}))} \ge \frac{m}{M_H} > 0.$$
Hence, in the end, for all $n$ large enough, we have $\lambda_{\min}(\Sigma_1^n+\Sigma_2^n+\Sigma_4^n) \ge (m/M_H) \wedge 1/2$. The result follows.

\medskip

\textbf{Proof of~\eqref{eq:sigma_4_to_0}:} the result follows from the proof of~\eqref{eq:min_to_0} and the definition of $\mathcal{V}_{m,H,\RP}^{n,G}$. $\Box$

\begin{lemma}
	\label{lem:weak_conv_finite_dim_Z}
	For every $\overline{k}<+\infty$, $Z^n := vec\left((Z_{\k}^n)_{\k\in\K_{124}(\overline{k})}\right) \in \Rb^{\overline{k}\left(2+(\overline{k}+1)^2\right)}$ satisfies
	\begin{equation*}
		Z^n \convD \mathcal{N}\left(\mathbf{0},\Id\right).
	\end{equation*}
\end{lemma}

\noindent
\textit{Proof of Lemma~\ref{lem:weak_conv_finite_dim_Z}.} We first remark that by construction, $Z_1^n := vec\left((Z_{\k}^n)_{\k\in\K_1(\overline{k})}\right)$ and $Z_2^n := vec\left((Z_{\k}^n)_{\k\in\K_2(\overline{k})}\right)$ are two $\overline{k}$-dimensional vectors of sample means that depend on $(U_{i0}^n)_{1\leq i \leq C_1}$ and $(U_{0j}^n)_{1\leq j \leq C_2}$ respectively. To prove asymptotic normality of $Z_1^n$ and $Z_2^n$, we need to verify the Lindeberg-Feller condition due to the triangular array structure at play. The $\psi_k$s form an orthonormal basis of $L_2([0,1])$ and are all uniformly bounded, while $(U_{i0}^n)_{1\leq i \leq C_1}$ and $(U_{0j}^n)_{1\leq j \leq C_2}$ are sequences of \textit{i.i.d.} standard uniform random variables. As a result, the conditions of the Lindeberg-Feller CLT can be easily checked and we conclude that $Z_1^n \convD \mathcal{N}\left(\mathbf{0},\Id\right)$ and $Z_2^n \convD \mathcal{N}\left(\mathbf{0},\Id\right)$. Since $(U_{i0}^n)_{1\leq i \leq C_1}$ and $(U_{0j}^n)_{1\leq j \leq C_2}$ are independent sequences, we can also claim that $Z_{12}^n := ((Z_1^n)',(Z_2^n)')' \in \Rb^{2\overline{k}}$ satisfies
\begin{equation*}
	Z_{12}^n \convD \mathcal{N}\left(\mathbf{0},\Id\right).
\end{equation*}

We now wish to show that for every $t \in \Rb^{\overline{k}\left(2+(\overline{k}+1)^2\right)}$
\begin{equation}
	\label{eq:weak_conv_final_result}
	t'Z^n \convD \mathcal{N}(0,||t||^2),
\end{equation}
which is equivalent to the statement of the theorem by the Cramer-Wold device. We decompose $t$ in two parts, $t_{12} \in \Rb^{2\overline{k}}$ and $t_4 \in \Rb^{\overline{k}(\overline{k}+1)^2}$ and write
\begin{equation*}
	t'Z^n = t_{12}'Z_{12}^n + t_4'Z_4^n,
\end{equation*}
with $Z_4^n := vec\left((Z_{\k}^n)_{\k\in\K_4(\overline{k})}\right) \in \Rb^{\overline{k}(\overline{k}+1)^2}$. We first remark that by a simple application of the continuous mapping in distribution
\begin{equation}
	\label{eq:weak_conv_first_part}
	t_{12}'Z_{12}^n \convD \mathcal{N}(0,||t_{12}||^2).
\end{equation}
If $t_4$ is the null vector, \eqref{eq:weak_conv_first_part} is enough to get~\eqref{eq:weak_conv_final_result}. For the remaining of the proof, we thus focus on the situation when $t_4$ is different from the null vector, and we go through the steps of the proof of Theorem 2 in \cite{ChenRao2007}. We let $K_{12,n} := t_{12}'Z_{12}^n$, $K_{4,n} := t_4'Z_4^n$ and $\mathcal{B}_n$ be the sigma-algebra generated by $\left((U_{i0}^n)_{1\le i \le C_1}, (U_{0j}^n)_{1 \le j \le C_2}\right)$. By construction, $K_{4,n}$ is an i.n.i.d sum of bounded random variables conditional on $\mathcal{B}_n$. We also have
\begin{align*}
	V\left( K_{4,n} \mid \mathcal{B}_n \right) & = \frac{1}{C_1C_2}\sum_{i=1}^{C_1}\sum_{j=1}^{C_2}\sum_{1 \le k_1,k_2,k_1',k_2',k_3 \le \overline{k} : k_3>0}t_{4,k_1k_2k_3}t_{4,k_1'k_2'k_3}\psi_{k_1}(U_{i0}^n)\psi_{k_1'}(U_{i0}^n)\psi_{k_2}(U_{0j}^n)\psi_{k_2'}(U_{0j}^n) \\
	& \convAS ||t_4||^2.
\end{align*}
A conditional version of the Lindeberg-Feller CLT immediately yields
\begin{equation}
	\label{eq:as_conv_to_0_cond_clt}
	\sup_{x \in \Rb} \left| P\left( K_{4,n} \leq x \mid \mathcal{B}_n \right) - \Phi(x/||t_4||) \right| \convAS 0.
\end{equation}
Obtaining~\eqref{eq:weak_conv_final_result} is equivalent to proving for every $x \in \Rb$
\begin{equation}
	\label{eq:rewriting_weak_conv}
	\lim_{n \to \infty} P\left( K_{4,n} + K_{12,n} \leq x \right) = \Phi(x/||t||).
\end{equation}
We can write
\begin{align*}
	P\left( K_{4,n} + K_{12,n} \leq x \right) & = E\left[\Phi\left(\frac{x-K_{12,n}}{||t_4||}\right)\right] + E\left[ P\left( K_{4,n} \leq x - K_{12,n} \mid \mathcal{B}_n \right) - \Phi\left(\frac{x-K_{12,n}}{||t_4||}\right) \right] \\
	& \le E\left[\Phi\left(\frac{x-K_{12,n}}{||t_4||}\right)\right] + E\left[ \sup_{y \in \Rb} \left| P\left( K_{4,n} \leq y \mid \mathcal{B}_n \right) - \Phi\left(\frac{y}{||t_4||}\right) \right| \right].
\end{align*}
The random variable $\sup_{y \in \Rb} \left| P\left( K_{4,n} \leq y \mid \mathcal{B}_n \right) - \Phi\left(\frac{y}{||t_4||}\right) \right|$ is almost surely bounded and converges to 0 almost surely as well by~\eqref{eq:as_conv_to_0_cond_clt}. We can therefore apply the dominated convergence theorem and claim
\begin{equation}
	\label{eq:dct}
	\lim_{n \to \infty} E\left[ \sup_{y \in \Rb} \left| P\left( K_{4,n} \leq y \mid \mathcal{B}_n \right) - \Phi\left(\frac{y}{||t_4||}\right) \right| \right] = 0.
\end{equation}
Let $Z_{12}$ and $Z_4$ be two independent random variables that satisfy $Z_{12} \sim \mathcal{N}(0,||t_{12}||^2)$ and $Z_4 \sim \mathcal{N}(0,||t_4||^2)$. Using the fact that $v \mapsto \Phi\left((x-v)/||t_4||\right)$ is a bounded and continuous function, the weak convergence result~\eqref{eq:weak_conv_first_part} implies
\begin{align}
	\label{eq:weak_conv_equivalence_criterion}
	\lim_{n \to \infty} E\left[\Phi\left(\frac{x-K_{12,n}}{||t_4||}\right)\right] & = E\left[\Phi\left(\frac{x-Z_{12}}{||t_4||}\right)\right] \nonumber \\
	& = E\left[P\left( Z_4 \leq x - Z_{12} \mid Z_{12}\right)\right] \nonumber \\
	& = P\left(Z_{12}+Z_4 \le x \right) = \Phi(x/||t||).
\end{align}
Combining~\eqref{eq:dct} and~\eqref{eq:weak_conv_equivalence_criterion} yields~\eqref{eq:rewriting_weak_conv} and the final result. $\Box$

