\begin{lemm}[Lemma 1.4, \cite{Peter}]\label{duoi}
\hfill\\
If $e_\alpha(\pi) \ne 0 $ then $e_\alpha(\pi)(1)=\pi(1)+\alpha$. If $f_\alpha(\pi) \ne 0$ then $f_\alpha(\pi)(1)=\pi(1)-\alpha$. 
\end{lemm}

\begin{lemm}[Proposition 1.5, \cite{Peter}]\label{maxminef}\hfill\\
$e_\alpha^n(\pi)=0$ if and only if $n>-Q$ and $f_\alpha^n(\pi)=0$ if and only if $n>[h_\alpha(1)-Q]$.
\end{lemm}

\subsubsection{Lakshmibai-Seshadri paths and character formula}
For each $\lambda\in P_+$, let $W_\lambda$ the stabilizer of $\lambda$ and $\leq$ the Bruhat order on $W/W_\lambda$. We denote $(\underline{\tau},\underline{a})$ the pair of a sequence  in $W/W_\lambda$ $$\underline{\tau}:\tau_1 > \tau_2 > \dots > \tau_r$$  and a sequence in $\mathbb{Q}$ $$\underline{a}: 0=a_0<a_1<\dots <a_r=1.$$ We associate this pair with a piecewise linear path $\pi^\lambda_{(\underline{\tau},\underline{a})}:[0,1]\rightarrow P_{\mathbb{R}}$ by \begin{equation*}
\pi^\lambda _{(\underline{\tau},\underline{a})}(t) :=\sum\limits_{i=1}^{j-1}(a_i-a_{i-1})\tau_i(\lambda)+(t-a_{j-1})\tau_j(\lambda)\text{ for } a_{j-1}\leq t \leq a_j.
\end{equation*} We call such paths like this a rational $W$-path of shape $\lambda$.\\

\noindent For each pair $(\tau, \sigma)$ in $W/W_\lambda$ with $\tau >\sigma$ and a rational number $a$ in $(0,1)$. We say an $a$-chain of $(\tau,\sigma)$ a sequence in $W/W_\lambda$ $$\kappa_0:= \tau >\kappa_1:= s_{\beta_1}\tau > \kappa_3 := s_{\beta_2}s_{\beta_1}\tau >\dots >\kappa_s:= s_{\beta_s}...s_{\beta_1}\tau  =\sigma, $$ where $\beta_1,\dots,\beta_s$ are positive real roots such that $a (\kappa_i(\lambda)|\beta_i^\vee) \in \mathbb{Z}$ and $l(\kappa_i)-1 =l(\kappa_{i-1})$.

\noindent For each $\lambda\in P_+$, A Lakshmibai-Seshadri path of shape $\lambda $ is defined to be an $W$-path of shape $\lambda$ $\pi^\lambda_{(\underline{\tau},\underline{a})}$ such that there exists an $a_i$-chain for the pair $(\tau_i,\tau_{i+1})$ for all $i =1,...,r-1$. The set of all Lakshmibai-Seshadri paths of shape $\lambda$ is denoted by $\wp_\lambda$.  
\begin{lemm}[Lemma 3.5 and Proposition 4.2, \cite{Peter}]\label{Qmin}$\wp_\lambda \subset \wp$ and the set of $\{0\}\cup \wp_\lambda$ is stable under the action of operators $e_\alpha$ and $f_\alpha$. Moreover, for each $\pi \in \wp_\lambda$, we have $\min_{t\in [0,1]}\{h_\alpha(t)\}$ is $Q$.
\end{lemm} 

\begin{theo}[Character formula, \cite{Peter}] \label{charpath} Let $\mathfrak{g}$ be a symmetrisable Kac-Moody algebra and $\lambda \in P_+$. Then the set $\wp_\lambda$ is equal to the set of all paths $\pi$ of the form \begin{equation*}
\pi= f_{\alpha_1} \circ f_{\alpha_2} \circ \dots \circ f_{\alpha_s}(\pi_\lambda) 
\end{equation*} where $\alpha_1,\dots,\alpha_s$ are simple roots and $\pi_\lambda$ is the straight line in $P_\mathbb{R}$ connecting $0$ with $\lambda$. Furthermore, \begin{equation*}ch_\lambda = \sum\limits_{\pi \in \wp_\lambda}e_{\pi(1)}.
\end{equation*}
\end{theo}

\section{The main results}\label{result} 
Let $\mathfrak{g}$ be an affine Kac-Moody algebra and $A$ the generalized Cartan matrix which defines $\mathfrak{g}$. Fix $u\in \mathbb{Z}_{>0}$ relative prime to $a_0$ in the null vector $a$ of $A$. Let $\mathfrak{g}[u]$ be the corresponding winding subalgebra. For each $k\in\mathbb{N}$, let $P_+^k$ be the set of all dominant integral weights of level $k$. For each integrable irreducible highest weight $\mathfrak{g}$-module $L(\lambda)$ of level $k>0$, we can decompose it into a direct sum of integrable irreducible highest weight modules $\dot{L}(\lambda')$ of level $uk$ (since $\dot{K}=uK$). Each $\dot{L}(\lambda')$ appears in $L(\lambda)$ with finite multiplicity, which we denote by $c_\lambda^{\lambda'}$ \begin{equation*}L(\lambda)=\bigoplus\limits_{\lambda'\in\dot{P}_+^{uk}}c_{\lambda}^{\lambda'}\dot{L}(\lambda').
\end{equation*}

\noindent A path $\pi \in \wp_\lambda$ is called $\mathfrak{g}[u]$-dominant if its image is contained in the dominant Weyl chamber of the root system of $\mathfrak{g}[u]$. We obtain the branching rule for $\mathfrak{g}[u]\subset \mathfrak{g}$ in the following theorem.
\begin{theo}\label{windingdecomp} Let $\mathfrak{g}$ be an affine Kac-Moody Lie algebra and $\mathfrak{g}[u]$ be a winding subalgebra of $\mathfrak{g}$. Then for any $\lambda\in P_+$, we have 
\begin{equation*}
L(\lambda)=\bigoplus\limits_{\pi}\dot{L}(\pi(1)),
\end{equation*}
where the sum runs over all $\mathfrak{g}[u]$-dominant paths in $\wp_{\lambda}$. In particular, for each $\lambda' \in \dot{P}_+$ the multiplicity $c_\lambda^{\lambda'}$ is equal the number of $\mathfrak{g}[u]$-dominant paths in $\wp_\lambda$ with end point $\lambda'$. 
\end{theo}
\begin{proof}
By using Kac's character formula for $\dot{ch}_{\lambda'}$, the equality \begin{equation*}
ch_\lambda =\sum\limits_{\lambda' \in \dot{P}_+^{uk}} c_{\lambda}^{\lambda'} \dot{ch}_{\lambda'}
\end{equation*} becomes 
\begin{equation}
\sum\limits_{\mu}m_\lambda(\mu)\sum\limits_{\sigma\in\dot{W}}\epsilon(\sigma)e_{\mu+\sigma(\dot{\rho})} = \sum\limits_{\lambda'\in \dot{P}_+^{uk}}c_\lambda^{\lambda'}\sum\limits_{\sigma\in\dot{W}}\epsilon(\sigma)e_{\sigma(\lambda'+\dot{\rho})}. \label{eq:char1'}
\end{equation}
Replace $\mu$ by $\sigma(\mu)$, then the left-hand side of the equation (\ref{eq:char1'}) does not change. So we have
\begin{equation}
\sum\limits_{\mu}m_\lambda(\mu)\sum\limits_{\sigma\in\dot{W}}\epsilon(\sigma)e_{\sigma(\mu+\dot{\rho})} = \sum\limits_{\lambda'\in \dot{P}_+^{uk}}c_\lambda^{\lambda'}\sum\limits_{\sigma\in\dot{W}}\epsilon(\sigma)e_{\sigma(\lambda'+\dot{\rho})}. \label{eq:char2'}
\end{equation}  We change the variable both sides of the equation (\ref{eq:char2'}) by putting $\eta = \sigma(\mu+\dot{\rho}) -\dot{\rho}$ on the left, $\eta = \sigma(\lambda'+\dot{\rho})-\dot{\rho}$ on the right, and then replacing $\sigma^{-1}$ by $\sigma$ to obtain 
\begin{equation}
\sum\limits_{\eta}\sum\limits_{\sigma\in\dot{W}} \epsilon(\sigma)m_\lambda(\sigma(\eta+\dot{\rho})-\dot{\rho})e_{\eta+\dot{\rho}} = \sum\limits_{\eta}\sum\limits_{\sigma\in\dot{W}}\epsilon(\sigma)c_\lambda^{\sigma(\eta+\dot{\rho})-\dot{\rho}}e_{\eta+\dot{\rho}}. \label{eq:char3'}
\end{equation}
As a weight of $\mathfrak{g}[u]$, if $\eta$ is dominant then $\eta +\dot{\rho}$ is strictly dominant. Then $\sigma(\eta+\dot{\rho})-\dot{\rho}$ is not dominant unless $\sigma=1$. Hence $c_{\lambda}^{\sigma(\eta +\dot{\rho})-\dot{\rho}}=0$ unless $\sigma =1$. So, if we restrict both sides of the equation (\ref{eq:char3'}) over $\eta \in \dot{P}_+$ and then delete $e_{\dot{\rho}}$ both sides we get 
\begin{equation}
\sum\limits_{\eta \in \dot{P}_+}\sum\limits_{\sigma\in\dot{W}} \epsilon(\sigma)m_\lambda(\sigma(\eta+\dot{\rho})-\dot{\rho})e_{\eta} = \sum\limits_{\eta \in \dot{P}_+}c_\lambda^\eta e_{\eta}. \label{eq:char4'}
\end{equation}
We see that if there exist $\sigma \in \dot{W}$ such that $\sigma(\mu+\dot{\rho})-\dot{\rho}$ is a dominant weight then $\sigma$ and $\eta$ are uniquely determined by $\mu$. Then we set $p(\mu):=\epsilon(\sigma)$ and $\{\mu\}:=\eta$. In the case there does not exist $\sigma \in \dot{W}$ satisfing above condition, we set $p(\mu):=0$ and $\{u\}:=0$. By Theorem \ref{charpath}, each weight $\mu$ of $L(\lambda)$ is a endpoint $\pi(1)$ of some path $\pi\in \wp_\lambda$. Furthermore, the multiplicity $m_\lambda(\mu)$ is equal to the number of Lakshmibai-Seshadri paths of shape $\lambda$ with endpoint $\mu$. So, in the language of paths, we can rewrite the equation (\ref{eq:char4'}) as 
\begin{equation*}
\sum\limits_{\pi\in \wp_\lambda}p(\pi(1))e_{\{\pi(1)\}}=\sum\limits_{\eta\in \dot{P}_+}c^\eta_\lambda e_\eta. \label{eq:char5'}
\end{equation*} 
By character formula in Theorem \ref{charpath}, we obtain 
\begin{equation}
\sum\limits_{\pi\in \wp_\lambda}p(\pi(1))\dot{ch}_{\{\pi(1)\}}=\sum\limits_{\eta\in\dot{P}_+}c_\lambda^\eta \dot{ch}_\eta. 
\label{eq:char6'}
\end{equation}
Let $\Omega$ be the set of all $\pi$ in $\wp_\lambda$ such that $\pi$ is $\mathfrak{g}[u]$-dominant and let $\Omega'$ be the completion of $\Omega$ in $\wp_\lambda$. We see that for each $\pi \in \Omega$, $\pi(1)$ is dominant then $p(\pi(1))=1$ and $\{\pi(1)\}=\pi(1)$. By Lemma \ref{cancel} below, we show that for each $\pi \in \Omega'$, there exist $\bar{\pi} \in \Omega'$ such that $p(\bar{\pi}(1))=-p(\pi(1))$ and $\{\bar{\pi}(1)\}=\{\pi(1)\}$. Hence by equation (\ref{eq:char6'}) we have 
\begin{equation*}
\sum\limits_{\pi\in \Omega}\dot{ch}_{\pi(1)}=\sum\limits_{\eta\in \dot{P}_+}c^\eta_\lambda \dot{ch}_\eta.
\end{equation*}
It implies that the set of all $\eta \in \dot{P}_+^{uk}$ such that $\dot{L}(\eta) \subset L(\lambda)$ as $\mathfrak{g}[u]$-modules is the set of endpoints of paths in $\Omega$. The multiplicity $c_\lambda^\eta$ is then equal to the number of paths in $\Omega$ with endpoint $\eta$. 
\end{proof}

\begin{lemm}\label{cancel} With the notation in the proof of Theorem \ref{windingdecomp}. For each $\pi \in \Omega'$, there exist $\bar{\pi}\in \Omega'$ such that $p(\bar{\pi}(1))=-p(\pi(1))$ and $\{\bar{\pi}(1)\}=\{\pi(1)\}$. 
\end{lemm} 
\begin{proof}
For each $\pi \in \Omega'$, there exist $t\in [0,1]$ such that $\pi(t)$ is not contained in the dominant Weyl chamber of $\mathfrak{g}[u]$. It means that there exist a simple root $\alpha$ of $\mathfrak{g}[u]$ and $t\in [0,1]$ such that $(\pi(t)|\alpha^\vee)<0$. By Lemma \ref{Qmin}, $\min_{t\in[0,1]}\{(\pi(t)|\alpha^\vee)\}=Q$ is an integer, we can choose $s$ to be the minimum value of $t\in [0,1]$ and a simple root $\alpha$ of $\mathfrak{g}[u]$ such that $(\pi(s)|\alpha^\vee)=-1$. Let $M_\pi$ be the subset of $\wp_\lambda$ of all paths $\pi'$ such that $\pi'(zt)= \pi(st)$ for some $z\in [0,1]$. Clearly that $M_\pi \subset \Omega'$ for each $\pi \in \Omega'$. By the minimum value of $s$, two sets $M_\pi, M_{\pi'}$ are the same set or have no common path for each $\pi,\pi' \in \Omega'$. Hence $\Omega'$ is the disjoint union of some subsets $M_\pi$ for $\pi \in \Omega'$.

Fix a path $\pi'\in\Omega'$. We need to show that for each $\pi \in M_{\pi'}$, we can find a path $\bar{\pi}$ in $M_{\pi'}$ that satisfies the statement of the lemma. Or equivalently, for each $(\pi,\sigma)\in M_{\pi'} \times \dot{W}$ such that $\sigma(\pi(1)+\dot{\rho})-\dot{\rho} \in \dot{P}_+$, there exist $(\bar{\pi},\bar{\sigma})\in M_{\pi'} \times \dot{W}$ such that $\epsilon(\sigma)=-\epsilon(\bar{\sigma})$ and $\sigma(\pi(1)+\dot{\rho})=\bar{\sigma}(\bar{\pi}(1)+\dot{\rho})$. This can be done by choosing $\bar{\sigma}=\sigma s_\alpha$ and $\bar{\pi} = f_\alpha^{1+(\pi(1)|\alpha^\vee)}(\pi)$. Indeed, we have $f_\alpha(M_\pi) \subset M_\pi \cup \{0\}$. Since $(\pi(1)|\alpha^\vee)+1 \leq (\pi(1)|\alpha^\vee)-Q$, we have $\bar{\pi}\ne 0$ by Lemma \ref{maxminef}. Finally, $\sigma(\pi(1)+\dot{\rho})=\bar{\sigma}(\bar{\pi}(1)+\dot{\rho})$ by Lemma \ref{duoi}.

\end{proof}

\begin{theo}Let $\mathfrak{g}$ be an affine Kac-Moody algebra and $\mathfrak{g}[u]$ be a winding subalgebra of $\mathfrak{g}$. Then for any $\lambda\in P_+^k$ and $\lambda' \in \dot{P}_+^{uk}$, we have \begin{equation*}
c_\lambda^{\lambda'}=\sum\limits_{\sigma\in W}\sum\limits_{\tau\in\dot{W}}\epsilon(\sigma\tau)\mathcal{P}(\sigma(\lambda+\rho)+\tau(\dot{\rho})-(\lambda'+\rho+\dot{\rho})).
\end{equation*}
\end{theo}
\begin{proof}
By Kac's character formula, the equality \begin{equation*}
ch_\lambda =\sum\limits_{\lambda' \in \dot{P}_+^{uk}} c_{\lambda}^{\lambda'} \dot{ch}_{\lambda'}
\end{equation*} becomes 
\begin{equation}ch_\lambda \sum\limits_{\sigma \in \dot{W}} \epsilon(\sigma)e_{\sigma(\dot{\rho})} = \sum\limits_{\lambda' \in \dot{P}_+^{uk}}c_{\lambda}^{\lambda'} \sum\limits_{\sigma\in \dot{W}}\epsilon(\sigma) e_{\sigma(\lambda'+\dot{\rho})}. \label{eq:char5} 
\end{equation} Now we use Theorem \ref{multpart}, to rewrite $ch_\lambda$ in the left-hand side of equation (\ref{eq:char5}), we get \begin{equation}\sum\limits_{\mu}\sum\limits_{\tau\in W}\sum\limits_{\sigma\in \dot{W}} \epsilon(\tau\sigma) \mathcal{P}(\tau(\lambda+\rho)-(\mu+\rho))e_{\sigma(\dot{\rho})+\mu}=\sum\limits_{\lambda' \in \dot{P}_+^{uk}}c_{\lambda}^{\lambda'} \sum\limits_{\sigma\in \dot{W}}\epsilon(\sigma) e_{\sigma(\lambda'+\dot{\rho})}.  \label{eq:char6}
\end{equation} We change the variable both sides of the equation (\ref{eq:char6}) by putting $\eta = \sigma(\dot{\rho})+\mu -\dot{\rho}$ on the left, $\eta = \sigma(\lambda'+\dot{\rho})-\dot{\rho}$ on the right and then replacing $\sigma^{-1}$ on the right-hand side by $\sigma$ to obtain \begin{equation}
\sum\limits_{\eta}\sum\limits_{\tau\in W}\sum\limits_{\sigma\in \dot{W}} \epsilon(\tau\sigma) \mathcal{P}(\tau(\lambda+\rho)+\sigma(\dot{\rho})-(\eta+\rho+\dot{\rho}))e_{\eta +\dot{\rho}}
=
\sum\limits_\eta\sum\limits_{\sigma \in \dot{W}}\epsilon(\sigma)c_\lambda^{\sigma(\eta+\dot{\rho})-\dot{\rho}} e_{\eta+\dot{\rho}}. \label{eq:char7}
\end{equation}
As a weight of $\mathfrak{g}[u]$, if $\eta$ is dominant then $\eta +\dot{\rho}$ is strictly dominant. Then $\sigma(\eta+\dot{\rho})-\dot{\rho}$ is not dominant unless $\sigma=1$. Hence, $c_{\lambda}^{\sigma(\eta +\dot{\rho})-\dot{\rho}}=0$ unless $\sigma =1$. So, if we restrict both sides of the equation (\ref{eq:char7}) over $\eta \in \dot{P}_+$ then we get 
\begin{equation*}\sum\limits_{\eta \in \dot{P}_+}\sum\limits_{\tau\in W}\sum\limits_{\sigma\in \dot{W}} \epsilon(\tau\sigma) \mathcal{P}(\tau(\lambda+\rho)+\sigma(\dot{\rho})-(\eta+\rho+\dot{\rho}))e_{\eta +\dot{\rho}}
=
\sum\limits_{\eta \in \dot{P}_+} c_\lambda^\eta e_{\eta+\dot{\rho}}.
\label{eq:char4}
\end{equation*} Note that $\eta$ in both sides belong to $\dot{P}_+^{uk}$. It implies the formula of $c_{\lambda}^\eta$ in terms of Weyl groups and generalized Konstant's partition function for any $\lambda$ in $P_+^k$ and $\eta \in \dot{P}_+^{uk}$.
\end{proof}

