\title{Kappa distributions in the language of superstatistics}

\author{Sergio Davis$^{1,2}$, Biswajit Bora$^{1,2}$, Cristian Pavez$^{1,2}$\\ and Leopoldo Soto$^{1,2}$}
\address{$^1$Research Center in the Intersection in Plasma Physics, Matter and Complexity (P$^2$mc), Comisión Chilena de Energía Nuclear, Casilla 188-D, Santiago, Chile}
