\begin{abstract}
The kappa distribution of velocities appears routinely in the study of collisionless plasmas present in Earth's magnetosphere, the solar wind among other contexts where particles 
are unable to reach thermal equilibrium. Originally justified through the use of Tsallis' non-extensive statistics, nowadays there are alternative frameworks that provide insight into 
these distributions, such as superstatistics. In this work we review the derivation of the multi-particle and single-particle kappa distributions for collisionless plasmas within the 
framework of superstatistics, as an alternative to the use of non-extensive statistics. We also show the utility of the superstatistical framework in the computation of expectation 
values under kappa distributions. Some consequences of the superstatistical formalism regarding correlations, temperature and entropy of kappa-distributed plasmas are also discussed.
\end{abstract}

%
%
%
\section{Introduction}

The Maxwell-Boltzmann distribution is the probability density of particle velocities observed in systems that reach thermal equilibrium. For a particle with mass $m$ at temperature 
$T$, the Maxwell-Boltzmann distribution is the three-dimensional Gaussian
%
\begin{equation}
\label{eq:maxwell}
P(\bm v|\beta, m) = \left(\frac{m\beta}{2\pi}\right)^{\frac{3}{2}} \exp\left(-\frac{\beta m\bm{v}^2}{2}\right),
\end{equation}
%
with $\beta \defeq 1/(k_B T)$ the inverse temperature. On the other hand, collisionless plasmas such as the ones present in the Earth's magnetosphere~\cite{Antonova2008, Espinoza2018, 
Kirpichev2020, Eyelade2021}, the solar wind~\cite{Maksimovic1997b, Nicolaou2019, ZentenoQuinteros2021} and the interstellar medium~\cite{Raymond2010, Nicholls2017} are unable to reach 
thermal equilibrium, and in that case what is commonly observed is that particle velocities are best described by the kappa distribution~\cite{Livadiotis2017, Lazar2021}, a generalization 
of \eqref{eq:maxwell} given by
%
\begin{equation}
\label{eq:kappa}
P(\bm v|\kappa, \vth) = \left[\pi\left(\kappa-\frac{3}{2}\right) \vth^2\right]^{-\frac{3}{2}} \frac{\Gamma(\kappa+1)}{\Gamma(\kappa-\frac{1}{2})}
\left[1 + \frac{1}{\kappa-\frac{3}{2}}\frac{\bm{v}^2}{\vth^2}\right]^{-(\kappa+1)},
\end{equation}
%
where $\kappa$ is referred to as the \emph{spectral index} and $\vth$ is the \emph{thermal velocity}. Outside space plasmas, kappa distributions have only recently been 
proposed~\cite{Knapp2013, Klir2015} as plausible models for velocity distributions in laboratory plasmas such as Z-pinch discharges, even when power law distributions in such 
configurations have been reported previously~\cite{Potter1971,Bernstein1972,Stygar1982, Vikhrev2007,Vikhrev2012}. It is particularly interesting to explore the existence of kappa 
distributions in plasma focus discharges~\cite{Soto2005, Haines2011}, where phenomena such as jets and filaments similar to the ones observed in astrophysical environments, have 
been observed~\cite{Soto2014, Pavez2015, Pavez2022}.

In the limit $\kappa \rightarrow \infty$, the kappa distribution in \eqref{eq:kappa} reduces to a Maxwellian as in \eqref{eq:maxwell} with temperature $T$ given by
%
\begin{equation}
k_B T = \frac{m\vth^2}{2}.
\end{equation}

The thermodynamic foundations leading to the Maxwell-Boltzmann distribution in \eqref{eq:maxwell} are well understood. Let us consider a system of $N$ classical particles with microstate 
$\bm \Gamma \defeq (\bm P, \bm R)$, where $\bm P \defeq (\bm{p}_1, \ldots, \bm{p}_N)$ are the kinetic degrees of freedom and $\bm R \defeq (\bm{r}_1, \ldots, \bm{r}_N)$ the configurational degrees of freedom, and such that the Hamiltonian of the system is
%
\begin{equation}
\H(\bm P, \bm R) = \sum_{i=1}^N \frac{\bm{p}_i^2}{2 m_i} + \Phi(\bm R),
\end{equation}
%
with $\Phi$ the interaction (potential) energy. The distribution of microstates $p(\bm \Gamma)$ that maximizes the Boltzmann-Gibbs entropy
%
\begin{equation}
\label{eq:entropy}
\mathcal{S}[p] \defeq -k_B\int d\bm{\Gamma} p(\bm \Gamma)\ln p(\bm \Gamma)
\end{equation}
%
subject to the constraint of fixed mean energy
%
\begin{equation}
\big<\H\big>_p = \int d\bm{\Gamma} p(\bm \Gamma) \H(\bm \Gamma) = \overline{E}
\end{equation}
%
is known as the canonical ensemble, the equilibrium distribution given by
%
\begin{equation}
\label{eq:canonical}
P(\bm P, \bm R|\beta) = \frac{\exp\big(-\beta \H(\bm P, \bm R)\big)}{Z(\beta)}.
\end{equation}

The equilibrium distribution of momenta $P(\bm P|\beta)$ is then obtained by integration of the configurational degrees of freedom $\bm R$ in 
\eqref{eq:canonical}, that is,
%
\begin{equation}
P(\bm P|\beta) = \int \frac{d\bm R}{Z(\beta)}\,\exp\left(-\beta\left[\sum_{i=1}^N \frac{\bm{p}_i^2}{2 m_i} + \Phi(\bm R)\right]\right)
\end{equation}
%
which reduces to
%
\begin{equation}
\label{eq:multi_p}
P(\bm P|\beta) = \left(\frac{\beta}{2\pi \tilde{m}}\right)^{\frac{3N}{2}}\;\exp\left(-\beta \sum_{i=1}^N \frac{\bm{p}_i^2}{2 m_i} \right),
\end{equation}
%
with $\tilde{m}$ the geometric mean mass,
%
\begin{equation}
\label{eq:geom_mass}
\tilde{m} \defeq \left(\prod_{i=1}^N m_i\right)^{\frac{1}{N}} = m_A^{N_A/N}\cdot m_B^{N_B/N},
\end{equation}
%
where in the last equality we have assumed, for simplicity, a two-species plasma with species $A$ and $B$, having masses $m_A$ and $m_B$, and number of particles $N_A$ and $N_B$  
respectively, such that $N = N_A+N_B$.

The distribution in \eqref{eq:multi_p} is universal, in the sense that it does not depend on the interaction potential $\Phi$. Moreover, it clearly factors as the product of $N$ 
independent, single-particle momentum distributions, 
%
\begin{equation}
P(\bm P|\beta) = \prod_{i=1}^N P(\bm{p}_i|\beta),
\end{equation}
%
where
%
\begin{equation}
P(\bm{p}_i|\beta) = \left(\frac{\beta}{2\pi m_i}\right)^{\frac{3}{2}}\exp\left(-\frac{\beta\bm{p}_i^2}{2 m_i}\right).
\end{equation}

The single-particle momentum distribution $P(\bm{p}|\beta)$ is equivalent to \eqref{eq:maxwell} if we recall that $\bm{p} = m\bm{v}$ and use the scaling property
%
\begin{equation}
P(\bm{v}|\beta) = m^3\,P(\bm{p} = m\bm{v}|\beta).
\end{equation}

Taking this procedure as a basis, an early theoretical attempt~\cite{Tsallis1988} to explain the origin of the kappa distribution lead to Tsallis' non-extensive statistics~\cite{Tsallis2009}, which postulates that the functional that must be maximized under appropriate constraints is not \eqref{eq:entropy} but the more general $q$-entropy, 
defined by
%
\begin{equation}
S_q[p] \defeq \frac{k_B}{q-1}\left(1-\int d\bm{\Gamma}\,p(\bm \Gamma)^q \right),
\end{equation}
%
where $q$ is known as the \emph{entropic index}, and such that $S_q$ reduces to the Boltzmann-Gibbs entropy in \eqref{eq:entropy} in the limit $q \rightarrow 1$. However, Tsallis 
statistics has not been free of criticisms, due to the fact that its application can lead to inconsistencies~\cite{Nauenberg2003, Presse2013, Presse2014, Marechal2024}. 

Moreover, nowadays there exist alternative formalisms that can explain the existence of kappa distributions without the need to postulate a different definition of entropy. Among them, 
one of the most promising is the theory of superstatistics~\cite{Beck2003, Beck2004}, where the inverse temperature $\beta$ is promoted from a constant to a random variable having its 
own probability density. This mechanism cleanly produces non-equilibrium ensembles, including the power laws such as \eqref{eq:kappa} commonly associated with non-extensive statistics, 
using instead mixtures of canonical ensembles.

In this work we will review the derivation of the kappa distribution from the point of view of superstatistics, using an invariant parameterization of the distribution of inverse 
temperatures, as well as derive new results regarding correlations, entropy and temperature of kappa-distributed plasmas.

%
%
%
%
\section{Superstatistics}

The formalism of superstatistics~\cite{Beck2003, Beck2004} is an alternative to non-extensive statistics that effectively recovers non-canonical ensembles in an elegant manner. 
It has been successfully applied to plasma physics~\cite{Ourabah2015, Davis2019b, Ourabah2020b, Sanchez2021, Gravanis2021}, condensed matter systems~\cite{Dixit2013, Dixit2015, Herron2021}, high-energy physics and gravitation~\cite{Jizba2010, Ayala2018, Ourabah2019}, among other fields~\cite{Schafer2018, Costa2022}.

In superstatistics the inverse temperature $\beta$ is not a constant but a random variable, having a probability density $P(\beta|\params)$ where $\params$ represents the parameters 
defining a particular ensemble. The canonical ensemble in \eqref{eq:canonical} is then replaced by a joint distribution $P(\bm \Gamma, \beta|\params)$ of the microstates $\bm \Gamma$ and the inverse temperature $\beta$, and this joint distribution is factorized as
%
\begin{equation}
\label{eq:joint}
P(\bm \Gamma, \beta|\params) = P(\beta|\params)P(\bm \Gamma|\beta, \params)
\end{equation}
%
using the product rule of probability theory. Because $\params$ represents knowledge about $\beta$, we see that the state of knowledge $(\beta, \params)$ can be replaced by $\beta$ 
itself and thus we can replace $P(\bm \Gamma|\beta, \params)$ by $P(\bm \Gamma|\beta)$ as given by \eqref{eq:canonical}. Therefore, we can write \eqref{eq:joint} as
%
\begin{equation}
\label{eq:super_joint}
P(\bm \Gamma, \beta|\params) = P(\beta|\params)\frac{\exp\big(-\beta \H(\bm \Gamma)\big)}{Z(\beta)},
\end{equation}
%
and the superstatistical distribution of microstates $P(\bm \Gamma|\params)$ as the integral over $\beta$ of \eqref{eq:super_joint},
%
\begin{equation}
\label{eq:super_ensemble}
P(\bm \Gamma|\params) = \int_0^\infty d\beta\,P(\beta|\params)\frac{\exp\big(-\beta \H(\bm \Gamma)\big)}{Z(\beta)}.
\end{equation}

Because $\beta$ and $\Gamma$ are correlated in \eqref{eq:super_joint}, the marginal distribution $P(\bm \Gamma|\params)$ is, in general, different from the canonical ensemble. This 
provides us with a mechanism to obtain non-canonical ensembles by postulating different inverse temperature distributions without the need to replace the Boltzmann-Gibbs entropy.

The canonical ensemble is a particular case of superstatistics where $\beta$ becomes again a constant, that is, when the uncertainty over $\beta$ vanishes. This is of course achieved for
%
\begin{equation}
\label{eq:prob_beta_delta}
P(\beta|\beta_0) = \delta(\beta-\beta_0),
\end{equation}
%
as in this case $P(\bm \Gamma|\params)$ in \eqref{eq:super_ensemble} reduces to \eqref{eq:canonical} with $\beta = \beta_0$.

We will now define two quantities of interest for superstatistical steady states. First, the mean inverse temperature of the ensemble, denoted by $\beta_S$, will be the mean value of 
$\beta$ under the distribution $P(\beta|\params)$, that is,
%
\begin{equation}
\label{eq:betaS}
\beta_S \defeq \big<\beta\big>_{\params} = \int_0^\infty d\beta\,P(\beta|\params)\beta.
\end{equation}

\noindent
Secondly, we will define
%
\begin{equation}
\U \defeq \big<(\delta \beta)^2\big>_{\params} = \int_0^\infty d\beta\,P(\beta|\params)\big(\beta-\beta_S\big)^2,
\end{equation}
%
as the variance of $\beta$ under the distribution $P(\beta|\params)$. The relative variance $u$ is then given by
%
\begin{equation}
\label{eq:u}
u \defeq \frac{\U}{(\beta_S)^2}.
\end{equation}

The distribution $P(\beta|\params)$ has been shown~\cite{Davis2022b} to be invariant under the choice of subsystems in a composite system, therefore its moments $\beta_S$ and $\U$ are 
promising candidates for any parameterization of a superstatistical state. The same is true of $u$, being a combination of $\U$ and $\beta_S$. In particular, using $u$ as one of the 
superstatistical parameters is useful because the limit $u \rightarrow 0$ turns $P(\beta|\params)$ into a Dirac delta distribution, therefore being the canonical (equilibrium) limit of 
superstatistics.

%
%
%
\section{Kappa distribution as a superstatistical mixture of Maxwellians}

Let $\bm V \defeq (\bm{v}_1, \bm{v}_2, \ldots, \bm{v}_N)$ be the $3N$-dimensional vector containing the velocities of $N$ particles. The Maxwell-Boltzmann distribution for $\bm V$ at 
inverse temperature $\beta$ is the equivalent in velocity space of the distribution of momenta in \eqref{eq:multi_p}. It is given by
%
\begin{equation}
\label{eq:multi_maxwell}
P(\bm V|\beta) = \prod_{i=1}^N P(\bm{v}_i|\beta, m_i) = \left(\frac{\tilde{m}\beta}{2\pi}\right)^{\frac{3N}{2}}\exp\big(-\beta K(\bm V)\big),
\end{equation}
%
with $P(\bm{v}_i|\beta, m_i)$ the single-particle Maxwell-Boltzmann distribution in \eqref{eq:maxwell} and
%
\begin{equation}
K(\bm V) \defeq \sum_{i=1}^N \frac{m_i \bm{v}_i^2}{2}
\end{equation}
%
the kinetic energy of the $N$-particle system. From \eqref{eq:multi_maxwell}, the Maxwell-Boltzmann distribution of kinetic energy is obtained as
%
\begin{equation}
\label{eq:kindist_canon}
P(K|\beta) = \int d\bm{V}\,P(\bm V|\beta)\,\delta\left(\sum_{i=1}^N \frac{m_i \bm{v}_i^2}{2} - K\right) = \frac{\exp(-\beta K)\Omega_K(K; N)}{Z_N(\beta)}
\end{equation}
%
where $\Omega_K$ is the density of states of $K(\bm V)$, defined by
%
\begin{equation}
\label{eq:kindos}
\Omega_K(K; N) = \int d\bm{V}\,\delta\left(\sum_{i=1}^N \frac{m_i \bm{v}_i^2}{2} - K\right) = \frac{K^{\frac{3N}{2}-1}}{\Gamma\left(\frac{3N}{2}\right)}\left(\frac{2\pi}{\tilde{m}}\right)^{\frac{3N}{2}}
\end{equation}
%
and
%
\begin{equation}
\label{eq:Z_N}
Z_N(\beta) = \int_0^\infty dK\,\exp(-\beta K)\Omega_K(K; N) = \left(\frac{2\pi}{\tilde{m}\beta}\right)^{\frac{3N}{2}}.
\end{equation}

\noindent
Replacing \eqref{eq:kindos} into \eqref{eq:kindist_canon} we see that $P(K|\beta)$ is a gamma distribution, namely
%
\begin{equation}
\label{eq:multi_canon_K}
P(K|\beta) = \frac{\beta^{\frac{3N}{2}}}{\Gamma\left(\frac{3N}{2}\right)} \exp(-\beta K)K^{\frac{3N}{2}-1}.
\end{equation}

In order to move from the Maxwellian to the kappa distribution within the superstatistical framework, we need to postulate a distribution $P(\beta|\params)$ of inverse temperatures. 
The particular distribution that achieves this is a gamma distribution,
%
\begin{equation}
\label{eq:prob_beta_kappa}
P(\beta|u, \beta_S) = \frac{1}{u\beta_S\Gamma\left(\frac{1}{u}\right)}\exp\left(-\frac{\beta}{u\beta_S}\right)\left(\frac{\beta}{u\beta_S}\right)^{\frac{1}{u}-1},
\end{equation}
%
as parameterized in Ref.~\cite{Davis2023e}. This fixes our superstatistical parameters to be $\params = (u, \beta_S)$, with $u$ and $\beta_S$ as defined in \eqref{eq:u} and 
\eqref{eq:betaS}, respectively. The most probable value of $\beta$ under this distribution is
%
\begin{equation}
\beta^* \defeq \beta_S\,(1-u),
\end{equation}
%
while the mean and variance of $\beta$ are given by
%
\begin{subequations}
\begin{align}
\label{eq:beta_mean}
\big<\beta\big>_{u, \beta_S} & = \beta_S, \\
\big<(\delta \beta)^2\big>_{u, \beta_S} & = u (\beta_S)^2,
\end{align}
\end{subequations}
%
as expected. If we replace \eqref{eq:prob_beta_kappa} into \eqref{eq:super_ensemble} and introduce the variable $t \defeq \beta/(u\beta_S)$, we obtain
%
\begin{equation}
\label{eq:prob_V_pre}
P(\bm V|u, \beta_S) = \frac{(u\beta_S)^{\frac{3N}{2}}}{\Gamma\left(\frac{1}{u}\right)}\left(\frac{\tilde{m}}{2\pi}\right)^{\frac{3N}{2}}
\int_0^\infty dt\,t^{\frac{1}{u}+\frac{3N}{2}-1}\exp\left(-t\Big[1+ u\beta_S K(\bm V)\Big]\right),
\end{equation}
%
and after performing the integral in $t$ and using \eqref{eq:Z_N}, we recover the multi-particle kappa distribution~\cite{Livadiotis2019},
%
\begin{equation}
\label{eq:multi_kappa}
P(\bm V|u, \beta_S) = \frac{C_N(u)}{Z_N(\beta_S)}\Big[1 + u\beta_S K(\bm V)\Big]^{-\left(\frac{1}{u}+\frac{3N}{2}\right)}
\end{equation}
%
with a size-dependent spectral index
%
\begin{equation}
\kappa_N \defeq \frac{1}{u} + \frac{3N}{2}-1,
\end{equation}
%
where we have defined
%
\begin{equation}
C_N(u) \defeq \frac{u^{\frac{3N}{2}} \Gamma\left(\frac{3N}{2}+\frac{1}{u}\right)}{\Gamma\left(\frac{1}{u}\right)}.
\end{equation}

\noindent
Note that
%
\begin{equation}
\lim_{u \rightarrow 0} C_N(u) = 1
\end{equation}
%
for all $N$, and also
%
\begin{equation}
\lim_{u \rightarrow 0} \Big[1+u\beta_S K\Big]^{-\left(\frac{1}{u}+\frac{3N}{2}\right)} = \exp(-\beta_S K),
\end{equation}
%
thus confirming that the limit $u \rightarrow 0$ of \eqref{eq:multi_kappa} yields the Maxwell-Boltzmann distribution in \eqref{eq:multi_maxwell} with 
$\beta = \beta_S$. For a single particle, \eqref{eq:multi_kappa} reduces to
%
\begin{equation}
\label{eq:kappa_new}
P(\bm v|u, \beta_S) = \left(\frac{m u \beta_S}{2\pi}\right)^{\frac{3}{2}} \frac{\Gamma\left(\frac{3}{2}+\frac{1}{u}\right)}{\Gamma\left(\frac{1}{u}\right)}
\left[1 + u\beta_S \frac{m\bm{v}^2}{2}\right]^{-\left(\frac{1}{u}+\frac{3}{2}\right)}
\end{equation}
%
which is exactly the kappa distribution as defined in \eqref{eq:kappa}, under the substitutions
%
\begin{subequations}
\begin{align}
\kappa & \defeq \frac{1}{u} + \frac{1}{2}, \\
\frac{m\vth^2}{2} & \defeq \frac{1}{\beta^*}.
\end{align}
\end{subequations}

One of the advantages of the superstatistical framework is that in many cases it simplifies the computation of expectation values. For instance, we can easily obtain all the moments of 
the $N$-particle energy distribution associated to \eqref{eq:multi_kappa} without computing the distribution explicitly, by using the moments of the canonical energy distribution in 
\eqref{eq:multi_canon_K}, which is a gamma distribution. Recalling that for a gamma distribution of the form
%
\begin{equation}
P(X|r, \theta) = \frac{\exp(-X/\theta)X^{r-1}}{\Gamma(r)\theta^r}
\end{equation}
%
the $n$-th moment is given by
%
\begin{equation}
\label{eq:gamma_moments}
\big<X^n\big>_{r, \theta} = \frac{1}{\Gamma(r)\theta^r}\int_0^\infty dX \exp(-X/\theta)X^{r+n-1} = \theta^n\,\frac{\Gamma(r+n)}{\Gamma(r)}, \qquad n > -r,
\end{equation}
%
we obtain the canonical energy moments as
%
\begin{equation}
\label{eq:moments_canon}
\big<K^n\big>_\beta = \beta^{-n}\,\frac{\Gamma\left(\frac{3N}{2}+n\right)}{\Gamma\left(\frac{3N}{2}\right)}, \qquad n > -\frac{3N}{2}.
\end{equation}

\noindent
Taking expectation over $P(\beta|u, \beta_S)$ we have
%
\begin{equation}
\label{eq:moments_pre}
\big<K^n\big>_{u, \beta_S} = \big<\beta^{-n}\big>_{u, \beta_S}\,\frac{\Gamma\left(\frac{3N}{2}+n\right)}{\Gamma\left(\frac{3N}{2}\right)}
\end{equation}
%
and by using the fact that $P(\beta|u, \beta_S)$ in \eqref{eq:prob_beta_kappa} is also a gamma distribution, we use \eqref{eq:gamma_moments} to easily get
%
\begin{equation}
\label{eq:moments_beta}
\big<\beta^n\big>_{u, \beta_S} = (u\beta_S)^n \;\frac{\Gamma\left(\frac{1}{u}+n\right)}{\Gamma\left(\frac{1}{u}\right)}.
\end{equation}

\noindent
Replacing \eqref{eq:moments_beta} into \eqref{eq:moments_pre} we obtain the moments of $P(K|u, \beta_S)$ as
%
\begin{equation}
\label{eq:moments_K}
\big<K^n\big>_{u, \beta_S} = (u\beta_S)^{-n}\,\frac{\Gamma\left(\frac{3N}{2}+n\right)}{\Gamma\left(\frac{3N}{2}\right)}\frac{\Gamma\left(\frac{1}{u}-n\right)}{\Gamma\left(\frac{1}{u}\right)}, \qquad -\frac{3N}{2} < n < \frac{1}{u}.
\end{equation}

The upper bound for $n$ imposes an upper bound for $u$ (lower bound for $\kappa$). For instance, in order for the kinetic energy to have a well-defined variance, we must have $u < 1/2$ 
(equivalently, $\kappa > 5/2$). On the other hand, the existence of higher moments of $K$ imposes an even more strict bound on $u$.

Replacing $n = 1$ in \eqref{eq:moments_K} and using the property $z\Gamma(z) = \Gamma(z+1)$ we obtain the mean kinetic energy of the system,
%
\begin{equation}
K_S \defeq \big<K\big>_{u, \beta_S} = \frac{3N}{2\beta_S (1-u)} = \frac{3N}{2\beta^*},
\end{equation}
%
and we see that the $N$-particle kappa distribution follows a form of equipartition theorem with equipartition temperature
%
\begin{equation}
k_B T_{\text{equip}} \defeq \frac{k_B T_S}{1-u}.
\end{equation}

\noindent
Similarly, using \eqref{eq:moments_K} with $n = 2$ and some algebra we obtain the variance of $K$,
%
\begin{equation}
\big<(\delta K)^2\big>_{u, \beta_S} = \left(\frac{3N}{2 \beta^*}\right)^2 \frac{(3N-2)u + 2}{3N(1-2u)},
\end{equation}
%
and we see that the relative variance
%
\begin{equation}
\frac{\big<(\delta K)^2\big>_{u, \beta_S}}{(K_S)^2} = \frac{(3N-2)u + 2}{3N(1-2u)}
\end{equation}
%
does not vanish in the thermodynamic limit unless $u = 0$, due to the uncertainty in $\beta$. For $N = 1$, the mean and variance of the single-particle kinetic energy are given by
%
\begin{subequations}
\begin{align}
k_S & \defeq \big<k\big>_{u, \beta_S} = \frac{3}{2 \beta^*}, \\
\sigma_k^2 & \defeq \big<(\delta k)^2\big>_{u, \beta_S} = \frac{u+2}{3(1-2u)} (k_S)^2,
\end{align}
\end{subequations}
%
respectively, thus from $k_S$ and $\sigma_k^2$ we can determine $u$ and $\beta_S$ as
%
\begin{subequations}
\begin{align}
u & = \frac{3\sigma_k^2 - 2 k_S^2}{6\sigma_k^2 + k_S^2}, \\
\beta_S & = \frac{3}{2(1-u)k_S}.
\end{align}
\end{subequations}

On the other hand, for $u < 1/3$, that is, $\kappa > 7/2$, we can also define the single-particle kinetic energy \emph{skewness},
%
\begin{equation}
s(u) \defeq \frac{1}{\sigma_k^3} \left<\left(\frac{m\bm{v}^2}{2} - k_S\right)^3\right>_{u, \beta_S} = \frac{4(1+2u)}{1-3u}\sqrt{\frac{1-2u}{3(2+u)}}.
\end{equation}

Not only is the skewness $s(u)$ non-negative, implying that the kinetic energy tails always extend to the right, it increases monotonically with $u$ from its minimum value at $u = 0$, 
which is $s(0) = 2\sqrt{2/3}$.

%
%
%
\section{Correlation between particle kinetic energies}

The kinetic energies of particles in a multi-particle kappa distribution such as \eqref{eq:multi_kappa} are correlated due to the presence of inverse temperature variations, and in 
fact, the existence of a linear dependence between kinetic energies has been shown to be a sufficient condition to obtain the kappa distribution~\cite{Davis2023e}. 

In this section we will evaluate this correlation between the energies of two trial particles with energies $k_1$ and $k_2$, through the covariance
%
\begin{equation}
\big<\delta k_1 \delta k_2\big>_{u, \beta_S} \defeq \big<k_1 k_2\big>_{u, \beta_S} - \big<k_1\big>_{u, \beta_S} \big<k_2\big>_{u, \beta_S}.
\end{equation}

First we use the fact that kinetic energies in the canonical ensemble are uncorrelated, therefore $\big<\delta k_1\delta k_2\big>_\beta = 0$ and
%
\begin{equation}
\big<k_1 k_2\big>_\beta = \big<k_1\big>_\beta \; \big<k_2\big>_\beta.
\end{equation}
%
Now, because the single-particle kinetic energies are identically distributed,
%
\begin{equation}
\big<k_1\big>_\beta = \big<k_2\big>_\beta = \big<k\big>_\beta = \frac{3}{2\beta}
\end{equation}
%
and we have
%
\begin{equation}
\big<k_1 k_2\big>_\beta = \left(\frac{3}{2\beta}\right)^2,
\end{equation}
%
hence taking expectation under $P(\beta|u, \beta_S)$ we have
%
\begin{equation}
\big<k_1 k_2\big>_{u, \beta_S} = \left< \big<k_1 k_2\big>_\beta\right>_{u, \beta_S} = \left(\frac{3}{2}\right)^2 \big<\beta^{-2}\big>_{u, \beta_S}
= \left(\frac{3}{2\beta_S}\right)^2\;\frac{1}{(1-u)(1-2u)}
\end{equation}
%
where we have used \eqref{eq:moments_beta} for $n = -2$. Therefore the covariance between $k_1$ and $k_2$ is
%
\begin{equation}
\label{eq:k1_k2_cov}
\big<\delta k_1 \delta k_2\big>_{u, \beta_S} = \frac{u}{1-2u}(k_S)^2.
\end{equation}

We see that the covariance is positive for $0 < u < 1/2$ and moreover, increases strictly with $u$, being zero only for $u = 0$. From \eqref{eq:k1_k2_cov} we can compute the Pearson correlation, which 
yields
%
\begin{equation}
\label{eq:pearson}
\rho_{k_1, k_2}(u) \defeq \frac{\big<\delta k_1 \delta k_2\big>_{u, \beta_S}}{\big<(\delta k)^2\big>_{u, \beta_S}} = \frac{3u}{u+2},
\end{equation}
%
and also strictly increases with $u$. However, a more robust indicator of correlation is the mutual information $I_{k_1, k_2}$ between $k_1$ and $k_2$, defined by
%
\begin{equation}
\label{eq:mutinf}
I_{k_1, k_2}(u, \beta_S) \defeq \left<\ln \left[\frac{P(k_1, k_2|u, \beta_S)}{P(k_1|u, \beta_S) P(k_2|u, \beta_S)}\right]\right>_{u, \beta_S}.
\end{equation}

\noindent
From \eqref{eq:kappa_new} we readily obtain the distribution of single-particle kinetic energies
%
\begin{equation}
\label{eq:marg_k1}
\begin{split}
P(k|u, \beta_S) & = \int d\bm{v}P(\bm v|u, \beta_S)\delta\left(k-\frac{m\bm{v}^2}{2}\right) \\
& = \frac{2(u\beta_S)^{\frac{3}{2}}\,\Gamma\left(\frac{3}{2}+\frac{1}{u}\right)}{\sqrt{\pi}\,\Gamma\left(\frac{1}{u}\right)}\Big[1 + u\beta_S k\Big]^{-\left(\frac{1}{u}+\frac{3}{2}\right)} \sqrt{k},
\end{split}
\end{equation}
%
which is shown in Fig.~\ref{fig:kindist}. Similarly, from \eqref{eq:multi_kappa} we can compute the joint distribution of $k_1$ and $k_2$ as
%
\begin{equation}
\label{eq:joint_k1_k2}
\begin{split}
P(k_1, k_2|u, \beta_S) & = \int d\bm{v}_1 d\bm{v}_2 P(\bm{v}_1, \bm{v}_2|u, \beta_S)\delta\left(k_1-\frac{m_1\bm{v}_1^2}{2}\right)\delta\left(k_2-\frac{m_2\bm{v}_2^2}{2}\right) \\
& = \frac{4(\beta_S)^3\,(1+u)(1+2u)}{\pi} \Big[1+u\beta_S(k_1+k_2)\Big]^{-\frac{1}{u}-3} \sqrt{k_1\; k_2}.
\end{split}
\end{equation}

\noindent
Upon replacing \eqref{eq:joint_k1_k2} and \eqref{eq:marg_k1} into \eqref{eq:mutinf}, we can finally evaluate $I_{k_1, k_2}$ as
%
\begin{equation}
\label{eq:mutual}
I_{k_1, k_2}(u) = 2F\Big(\frac{1}{u}+\frac{3}{2}\Big) - F\Big(\frac{1}{u}\Big) - F\Big(\frac{1}{u}+3\Big),
\end{equation}
%
where we have defined
%
\begin{equation}
F(z) \defeq z\psi(z) - \ln\,\Gamma(z)
\end{equation}
%
with $\psi$ the digamma function, $\psi(z) \defeq \Gamma'(z)/\Gamma(z)$. Because $F'(z) = z\psi'(z) > 0$ for $z > 0$ we can show that $I_{k_1, k_2}(u)$ strictly increases with $u$, 
and by using the asymptotic approximation
%
\begin{equation}
F(z) \approx z + \frac{1}{2}\ln z - \frac{1}{2}\Big(\ln\,(2\pi) + 1\Big) 
\end{equation}
%
for large values of $z$ we can verify that
%
\begin{equation}
\lim_{u \rightarrow 0} I_{k_1, k_2}(u) = 0,
\end{equation}
%
therefore we confirm that $k_1$ and $k_2$ are uncorrelated only in the canonical limit. Fig.~\ref{fig:mutual_pearson} shows $I_{k_1, k_2}$ and $\rho_{k_1, k_2}$ as a function of $u$.

