\includegraphics[width=0.475\textwidth]{Pearson.png}
\end{center}
\caption{Left, mutual information $I_{k_1, k_2}(u)$ in \eqref{eq:mutual} as a function of $u$. Right, Pearson correlation $\rho_{k_1, k_2}(u)$ in \eqref{eq:pearson} as a function of $u$.}
\label{fig:mutual_pearson}
\end{figure}

