\section{Observable temperature for kappa distributions}

It has been established~\cite{Davis2018} as a general property of non-canonical superstatistics that no function $\hat{\beta}(\bm \Gamma)$ exists being interchangeable with $\beta$ in 
the sense that
%
\begin{equation}
\big<G\big(\hat{\beta}(\bm \Gamma)\big)\big>_{\params} = \big<G(\beta)\big>_{\params}
\end{equation}
%
for an arbitrary function $G$. A consequence of this theorem is that $P(\beta|\params)$ cannot be written as a sampling distribution, in other words, there is no function 
$\hat{\beta}(\bm \Gamma)$ such that
%
\begin{equation}
\label{eq:sampling}
P(\beta|\params) = \big<\delta\big(\hat{\beta}(\bm \Gamma)-\beta\big)\big>_{\params}.
\end{equation}

One way to understand this impossibility theorem in the case of kappa distributions, is to notice that the uncertainty in $\beta$ does not vanish even when knowing the velocities 
$\bm V$ of all the particles. In fact, if such a function $\hat{\beta}(\bm V)$ existed for which \eqref{eq:sampling} with $\bm \Gamma = \bm V$ and $\params = (\bm V, u, \beta_S)$ 
would hold, it would imply
%
\begin{equation}
\label{eq:beta_no_uncertainty}
P(\beta|\bm V, u, \beta_S) = \delta\big(\beta - \hat{\beta}(\bm V)\big).
\end{equation}

In the case of our multi-particle kappa distribution, following Ref.~\cite{Davis2024} we will compute the conditional distribution of $\beta$ given $\bm V$ using the product rule of probability,
%
\begin{equation}
\label{eq:bayes}
P(\beta|\bm V, u, \beta_S) = \frac{P(\bm V, \beta|u, \beta_S)}{P(\bm V|u, \beta_S)}.
\end{equation}

The superstatistical joint distribution of velocities and inverse temperature $P(\bm V, \beta|u, \beta_S)$ is, according to \eqref{eq:super_joint} and \eqref{eq:prob_beta_kappa},
%
\begin{equation}
\label{eq:joint_velocities_beta}
P(\bm{V}, \beta|u, \beta_S) = \left(\frac{\tilde{m}\beta}{2\pi}\right)^{\frac{3N}{2}}\frac{1}{u\beta_S\,\Gamma\left(\frac{1}{u}\right)}
\exp\left(-\frac{\beta}{u\beta_S}\Big[1 + u\beta_S K(\bm{V})\Big]\right)\left(\frac{\beta}{u\beta_S}\right)^{\frac{1}{u}-1},
\end{equation}
%
thus replacing \eqref{eq:joint_velocities_beta} and \eqref{eq:multi_kappa} into \eqref{eq:bayes} yields
%
\begin{equation}
P(\beta|\bm V, u, \beta_S) = \frac{\Big[1+u\beta_S K(\bm V)\Big]^{\frac{3N}{2}+\frac{1}{u}}}{u\beta_S\,\Gamma\left(\frac{3N}{2}+\frac{1}{u}\right)}
\exp\left(-\frac{\beta}{u\beta_S}\Big[1 + u\beta_S K(\bm V)\Big]\right)\left(\frac{\beta}{u\beta_S}\right)^{\frac{1}{u}+\frac{3N}{2}-1}.
\end{equation}

\noindent
This is again a gamma distribution, but with mean
%
\begin{equation}
\big<\beta\big>_{\bm V, u, \beta_S} = \left(1 + \frac{3Nu}{2}\right)\frac{\beta_S}{1 + u\beta_S K(\bm V)},
\end{equation}
%
and with relative variance
%
\begin{equation}
\frac{\big<(\delta \beta)^2\big>_{\bm V, u, \beta_S}}{\big<\beta\big>^2_{\bm V, u, \beta_S}} = \left(\frac{1}{u} + \frac{3N}{2}\right)^{-1},
\end{equation}
%
which is in general greater than zero and less than $u$, vanishing in the limit $u \rightarrow 0$ ($\kappa \rightarrow \infty$), that is, when the kappa distribution reduces to the Maxwellian, and also in the limit $N \rightarrow \infty$ for $u > 0$. In the latter case, we can approximate
%
\begin{equation}
\big<\beta\big>_{\bm V, u, \beta_S} \approx \frac{3N}{2K(\bm V)},
\end{equation}
%
and, together with $\big<(\delta \beta)^2\big>_{\bm V, u, \beta_S} \rightarrow 0$, we are led to conclude that
%
\begin{equation}
\label{eq:limit}
\lim_{N \rightarrow \infty} P(\beta|\bm{v}_1, \bm{v}_2, \ldots, \bm{v}_N, u, \beta_S) = \delta\big(\beta - \hat{\beta}_{\infty}\big),
\end{equation}
%
then agreeing with \eqref{eq:beta_no_uncertainty}, where
%
\begin{equation}
\label{eq:hat_beta}
\hat{\beta}_{\infty}(\bm{v}_1, \bm{v}_2, \ldots) = \lim_{N \rightarrow \infty} \frac{3N}{2 K(\bm{v}_1, \bm{v}_2, \ldots)}.
\end{equation}

In fact this means that only in the thermodynamic limit, there is a unique value of inverse temperature given the set of velocities $\bm{v}_1, \bm{v}_2, \ldots$, namely $\hat{\beta}$ in 
\eqref{eq:hat_beta}. It follows by taking expectation under $P(\bm V|u, \beta_S)$ on both sides of \eqref{eq:limit} and recognizing that $P(\beta|u, \beta_S)$ is independent of $N$, that
%
\begin{equation}
\label{eq:gravanis_pre}
P(\beta|u, \beta_S) = \left<\delta\left(\beta-\hat{\beta}_{\infty}\right)\right>_{u, \beta_S},
\end{equation}
%
which is precisely the result by Gravanis \emph{et al}~\cite{Gravanis2020} on the interpretation of the superstatistical inverse temperature in the thermodynamic limit. We can rewrite 
the right-hand side of \eqref{eq:gravanis_pre} to read
%
\begin{equation}
\label{eq:gravanis}
P(\beta|u, \beta_S) = \lim_{N \rightarrow \infty} \Big<\delta\Big(\beta-\frac{3N}{2K}\Big)\Big>_{u, \beta_S} 
= \lim_{N \rightarrow \infty}\;\frac{3N}{2\beta^2}\, P\Big(K = \frac{3N}{2\beta}\Big|u, \beta_S\Big),
\end{equation}
%
and this result can be validated by replacing the distribution
%
\begin{equation}
P(K|u, \beta_S) = \frac{C_N(u)}{Z_N(\beta_S)}\Big[1+u\beta_S K\Big]^{-\left(\frac{1}{u}+\frac{3N}{2}\right)} \Omega_K(K; N),
\end{equation}
%
into the rightmost-hand side of \eqref{eq:gravanis}, upon which we obtain
%
\begin{equation}
\begin{split}
P(\beta|u, \beta_S) & = \frac{1}{u\beta_S\,\Gamma\left(\frac{1}{u}\right)}\lim_{N \rightarrow \infty}
\frac{2\,\Gamma\left(\frac{3N}{2}+\frac{1}{u}\right)}{3N\,\Gamma\left(\frac{3N}{2}\right)} \left(\frac{3Nu\beta_S}{2\beta}\right)^{\frac{3N}{2}+1}
\Big[1+\frac{3Nu\beta_S}{2\beta}\Big]^{-\left(\frac{1}{u}+\frac{3N}{2}\right)} \\
& = \frac{1}{u\beta_S\Gamma\left(\frac{1}{u}\right)}\exp\left(-\frac{\beta}{u\beta_S}\right)\left(\frac{\beta}{u\beta_S}\right)^{\frac{1}{u}-1},
\end{split}
\end{equation}
%
exactly recovering $P(\beta|u, \beta_S)$ as in \eqref{eq:prob_beta_kappa}.

%
%
%
\section{Entropy of particle velocities in a collisionless plasma}

We can compute the Boltzmann-Gibbs entropy, as defined in \eqref{eq:entropy}, associated to the superstatistical joint distribution of velocities and inverse temperature in 
\eqref{eq:joint_velocities_beta}, as the integral
%
\begin{equation}
\label{eq:joint_entropy}
\mathcal{S}_{\beta, \bm V}(u, \beta_S) \defeq -\int_0^\infty d\beta\,\int d\bm{V} P(\bm V, \beta|u, \beta_S)\ln P(\bm V, \beta|u, \beta_S).
\end{equation}

\noindent
Replacing \eqref{eq:joint_velocities_beta} into \eqref{eq:joint_entropy}, and using \eqref{eq:beta_mean} and \eqref{eq:moments_canon} with $n = 1$ to obtain
%
\begin{equation}
\big<\beta K\big>_{u, \beta_S} = \left< \big<\beta K\big>_\beta \right>_{u, \beta_S} = \frac{3N}{2},
\end{equation}
%
together with
%
\begin{equation}
\big<\ln \beta\big>_{u, \beta_S} = \ln\,(u\beta_S) + \psi\left(\frac{1}{u}\right),
\end{equation}
%
we finally have, after replacing $\tilde{m}$ according to \eqref{eq:geom_mass}, that
%
\begin{equation}
\label{eq:kin_entropy}
\mathcal{S}_{\beta, \bm V}(u, \beta_S) = \frac{3N}{2} \Big[1+\ln\,(2\pi) -\frac{N_A}{N}\ln m_A - \frac{N_B}{N}\ln m_B -\psi\Big(\frac{1}{u}\Big)-\ln\,(u\beta_S)\Big] 
+ \mathcal{S}_{\beta}(u, \beta_S),
\end{equation}
%
where
%
\begin{equation}
\mathcal{S}_\beta (u, \beta_S) \defeq -\int_0^\infty d\beta\,P(\beta|u, \beta_S)\ln P(\beta|u, \beta_S) = \frac{1}{u} -F\left(\frac{1}{u}\right) 
+ \psi\left(\frac{1}{u}\right) + \ln\,(u\beta_S)
\end{equation}
%
is the entropy of the superstatistical inverse temperature distribution in \eqref{eq:prob_beta_kappa}. We see that the entropy $\mathcal{S}_{\beta, \bm V}$ is in general non-additive, 
due precisely to this last term that reflects the uncertainty in $\beta$. For instance, for two particles the entropy can be written as
%
\begin{equation}
\mathcal{S}_{\beta, \bm{v}_1, \bm{v}_2} = \mathcal{S}_{\beta, \bm{v}_1} + \mathcal{S}_{\beta, \bm{v}_2} - \mathcal{S}_\beta (u, \beta_S).
\end{equation}

\noindent
The derivative of the entropy in \eqref{eq:kin_entropy} with respect to $u$ is
%
\begin{equation}
\frac{\partial \mathcal{S}_{\beta, \bm V}(u, \beta_S)}{\partial u} = \frac{(3N-2)u + 2}{2u^3}\;\Big(\psi'\left(\frac{1}{u}\right)-u\Big)
\end{equation}
%
which is non-negative, thus entropy increases monotonically with $u$. On the other hand, we can evaluate the derivative
%
\begin{equation}
\label{eq:entropy_deriv}
\left(\frac{\partial \mathcal{S}_{\beta, \bm V}}{\partial K_S}\right)_{u, N} = \frac{\partial \mathcal{S}_{\beta, \bm V}(u, \beta_S)}{\partial \beta_S}\cdot \frac{\partial \beta_S}{\partial K_S}
= \left(\frac{3N-2}{3N}\right)\beta_S\,(1-u),
\end{equation}
%
hence
%
\begin{equation}
\lim_{N \rightarrow \infty} \left(\frac{\partial \mathcal{S}_{\beta, \bm V}}{\partial K_S}\right)_{u, N} = \beta^*,
\end{equation}
%
consistent with the fact that $\beta^*$ plays the role of the inverse equipartition temperature.

%
%
%
\section{Concluding remarks}

We have reviewed the derivation of the multi-particle and single-particle kappa distribution from the assumption of a gamma distribution of inverse temperatures in superstatistics. 
This is not only a promising route to explain the origin of the kappa distribution in collisionless plasmas, a superstatistical perspective also brings analytical tools from probability 
theory that allow us to simplify the computation of observables in superstatistical states. We have illustrated through the computation of the Pearson correlation and the mutual 
information between kinetic energies of two distinct particles in a kappa distribution that those energies are always positively correlated, and that their correlation increases with 
the distance to equilibrium, as measured by $u$. We are able to interpret the result by Gravanis \emph{et al} on the interpretation of the superstatistical temperature in kappa plasmas 
as the vanishing of the uncertainty about $\beta$ given knowledge of all particle velocities in the thermodynamic limit.

