\section{Probabilistic ODE Solvers via Bayesian Filtering}\label{sec:method}

\rodeo
% provides a probabilistic framework for
is designed to solve arbitrary-order multivariable ODE systems which satisfy an initial value problem (IVP).  For a univariate function $x(t)$, an ODE-IVP is of the form
\begin{equation}
    \label{eq:hode}
    \WW\xx(t) = \ff(\xx(t), t), \qquad \xx(\tmin) = \vv, \qquad t \in [\tmin, \tmax],
\end{equation}
where $\xx(t) = \big(x^{(0)}(t), x^{(1)}(t), \ldots, x^{(p-1)}(t)\big)$ consists of $x(t) = x^{(0)}(t)$ and its first $p-1$ derivatives, $\WW_{r \times p}$ is a coefficient matrix, and $\ff(\xx(t), t) = \big(f_1(\xx(t), t), \ldots, f_r(\xx(t), t)\big)$ is a nonlinear function representing $r$ equations.  The ODE in~\eqref{eq:hode} can always be written in the more usual ``first-order'' form,
\begin{equation}
  \label{eq:ode1}
  \dv{t} x^{(i)}(t) = g_i(\xx(t), t), \qquad i=0,\ldots,p-2.
\end{equation}
Equivalently, any ODE in the first-order form~\eqref{eq:ode1} can be written in the form of~\eqref{eq:hode} with $\ff(\xx(t), t) = (g_0(\xx(t), t), \ldots, g_{p-2}(\xx(t), t))$ and $\WW_{(p-1)\times p} = [\bz_{(p-1)\times 1} \mid \Id_{(p-1) \times (p-1)}]$.  While the first-order form~\eqref{eq:ode1} is unique, the formulation in~\eqref{eq:hode} 
% Here we adopt a slightly more general framework than the usual ODE-IVP formulation with $\frac{\ud}{\ud t} x^{(i)}(t) = f_i(\xx(t), t)$, $i = 0,\ldots, q-2$, which is given by~\eqref{eq:hode} with $\WW_{(q-1)\times q} = [\bz_{(q-1)\times 1} \mid \Id_{(q-1) \times (q-1)}]$.  This
often allows a given ODE-IVP to be specified in multiple ways, which in turn could affect the accuracy of the stochastic solver to be described below. 
% Since the ODE-IVP~\eqref{eq:hode} generally cannot be solved in closed form, numerical solvers are used to compute an estimate of $x(t)$ at time points $t = t_0, \ldots, t_N$, where $t_n = nT/N$.  The value of 


Unlike deterministic solvers, \rodeo employs a probabilistic approach to solving~\eqref{eq:hode} based on a widely adopted paradigm of Bayesian nonlinear filtering~\citep{tronarp.etal18}.  This approach consists of putting a Gaussian Markov process prior on $\xx(t)$, and updating it with information from the ODE-IVP~\eqref{eq:hode} at time points $t = t_0, \ldots, t_N$, where $t_n = n(\tmax-\tmin)/N$.  Specifically, let $\xx_n = \xx(t_n)$ and consider the general indexing notation $\xx_{m:n} = (\xx_m, \ldots, \xx_n)$.  If $\xx(t)$ is the solution to~\eqref{eq:hode}, we would have $\zz_n = \WW \xx_n - \ff(\xx_n, t_n) = \bz$.  Based on this observation,  \cite{tronarp.etal18} consider a state-space model in $\xx_n$ and $\zz_n$ of the form
%the Bayesian model of~\cite{tronarp.etal18} for the stochastic ODE solver is then
%\begin{equation}\label{eq:bnf}
%    \begin{aligned}
%        % \xx_0 & = \vv \\
%        \xx_{n+1} \mid \xx_n & \sim \N(\QQ (\xx_n-\vv) + \vv, \RR) \\
%        % \xx_{0:N} & \sim \N(\mmu_0, \SSi_0) \\
%        \mi_n & \ind \N(\WW \xx_n - \ff(\xx_n, t_n), \vi_n),
%    \end{aligned}
%\end{equation}
\begin{equation}\label{eq:bnf}
    \begin{aligned}
        % \xx_0 & = \vv \\
        \xx_{n+1} \mid \xx_n & \sim \N(\QQ \xx_n, \RR) \\
        % \xx_{0:N} & \sim \N(\mmu_0, \SSi_0) \\
        \mi_n & \ind \N(\WW \xx_n - \ff(\xx_n, t_n), \vi_n),
    \end{aligned}
\end{equation}
where $\xx_0 = \vv$, $\QQ$ and $\RR$ are determined by the Gaussian Markov process prior, and $\vi_{1:N}$ are tuning parameters.  The stochastic ODE solution is then given by the posterior distribution 
% output of the stochastic solver is the posterior distribution
\begin{equation}\label{eq:solpost}
  p(\xx_{1:N} \mid \mi_{1:N} = \bz).
\end{equation}
  % , or sometimes simply the posterior expectation $\E[\xx_{0:N} \mid \mi_{1:N} = \bz]$.


As $N \to \infty$, the stochastic ODE solution~\eqref{eq:solpost} gets arbitrarily close to the true ODE solution as the computational complexity increases~\citep{kersting20}.  
% Restricting the Bayesian model to Markov processes rather than more general Gaussian process priors for $\xx(t)$ reduces complexity from $\bO(N^3)$ to $\bO(N)$~\citep{tronarp.etal18}.
However, the posterior distribution~\eqref{eq:solpost} generally
cannot be sampled from directly.  Alternatives include Markov chain
Monte Carlo sampling~\citep{chkrebtii.etal16,yang.etal21} and particle
filtering~\citep{tronarp.etal18}.  A less accurate, but ostensibly much
faster approach is to linearize~\eqref{eq:bnf} using Taylor
expansions~\citep{tronarp.etal18}.  This amounts to the surrogate model
%\begin{equation}\label{eq:mi}
%    \begin{aligned}
%        % \xx_0 & = \vv \\
%        \xx_{n+1} \mid \xx_n & \sim \N(\QQ (\xx_n -\vv) + \vv, \RR) \\
%        % \xx_{0:N} & \sim \N(\mmu_0, \SSi_0) \\
%        \mi_n & \ind \N(\WW \xx_n, \vi_n),
%    \end{aligned}
%\end{equation}
\begin{equation}\label{eq:mi}
    \begin{aligned}
        % \xx_0 & = \vv \\
        \xx_{n+1} \mid \xx_n & \sim \N(\QQ \xx_n, \RR) \\
        % \xx_{0:N} & \sim \N(\mmu_0, \SSi_0) \\
        \mi_n & \ind \N((\WW + \BB_n)\xx_n + \aa_n, \vi_n),
    \end{aligned}
\end{equation}
where $\aa_n, \BB_n$ and $\vi_n$
%where instead of conditioning on $\mi_{1:N} = \bz$, both $\mi_n$ and $\vi_n$ 
are obtained sequentially by a process called \emph{model interrogation}~\citep{chkrebtii.etal16} (see Section~\ref{sec:mi}).  The upshot is that a random draw from the posterior
\begin{equation}\label{eq:plin}
  p_\L(\xx_{1:N} \mid \mi_{1:N} = \bz)
\end{equation}
induced by the working model~\eqref{eq:mi} can be easily obtained using the Kalman filtering and smoothing algorithms.  Denote the posterior mean and variance of the solution process under the working model~\eqref{eq:mi} as
\begin{equation}
  \begin{aligned}
    \mmu_{m|n} & = \E_\L[\xx_m \mid \mi_{1:n} = \bz], \\
    \SSi_{m|n} & = \var_\L(\xx_m \mid \mi_{1:n} = \bz).
  \end{aligned}
\end{equation}
Using this notation, the steps of the Kalman ODE solver are presented in Algorithm~\ref{alg:Kalman}. The formulation of the Kalman recursions used in Algorithm~\ref{alg:Kalman} can be found in Appendix~\ref{sec:kalmanfun}.
\begin{algorithm}[!htb]
  \caption{The Kalman ODE solver.}\label{alg:Kalman}
  \begin{algorithmic}[1]
    \Procedure{\code{kalman\_ode\_sim}}{$\WW, \ff(\xx, t), \vv, \QQ, \RR$}
    \State $\mmu_{0|0}, \ldots, \mmu_{N|N}, \SSi_{0|0}, \ldots, \SSi_{N|N} \gets \mcode{kalman\_ode\_forward}(\WW, \ff(\xx, t), \vv, \QQ, \RR)$
    \State $\xx_N \sim \N(\mmu_{N|N}, \SSi_{N|N})$
    \For{$n=N-1:0$}
    \State $\xx_n \gets \ksample(\xx_{n+1}, \mmu_{n|n}, \SSi_{n|n}, \mmu_{n+1|n}, \SSi_{n+1|n}, \QQ)$
    % \State $\tilde{\mmu}_{n|N}, \tilde \SSi_{n|N} \gets \ksample(\xx_{n+1}, \mmu_{n|n}, \SSi_{n|n}, \mmu_{n+1|n}, \SSi_{n+1|n}, \QQ)$
    % \State $\xx_n \gets \N(\tilde \mmu_{n|N}, \tilde \SSi_{n|N})$
    % \State $\mmu_{n|N}, \SSi_{n|N} \gets \ksmooth(\mmu_{n+1|N}, \SSi_{n+1|N}, \mmu_{n|n}, \SSi_{n|n}, \mmu_{n+1|n}, \SSi_{n+1|n}, \QQ)$
    \EndFor
    \State \textbf{return} $\xx_{0:N}$
    \EndProcedure
    \State
    \Procedure{\code{kalman\_ode\_mv}}{$\WW, \ff(\xx, t), \vv, \QQ, \RR$}
    \State $\mmu_{0|0}, \ldots, \mmu_{N|N}, \SSi_{0|0}, \ldots, \SSi_{N|N} \gets \mcode{kalman\_ode\_forward}(\WW, \ff(\xx, t), \vv, \QQ, \RR)$
    % \State $\xx_N \sim \N(\mmu_{N|N}, \SSi_{N|N})$
    \For{$n=N-1:0$}
    % \State $\tilde{\mmu}_{n|N}, \tilde \SSi_{n|N} \gets \ksample(\xx_{n+1}, \mmu_{n|n}, \SSi_{n|n}, \mmu_{n+1|n}, \SSi_{n+1|n}, \QQ)$
    % \State $\xx_n \gets \N(\tilde \mmu_{n|N}, \tilde \SSi_{n|N})$
    \State $\mmu_{n|N}, \SSi_{n|N} \gets \ksmooth(\mmu_{n+1|N}, \SSi_{n+1|N}, \mmu_{n|n}, \SSi_{n|n}, \mmu_{n+1|n}, \SSi_{n+1|n}, \QQ)$
    \EndFor
    \State \textbf{return} $\mmu_{0:N|N}, \SSi_{0:N|N}$
    \EndProcedure
    \State
    \Procedure{\code{kalman\_ode\_forward}}{$\WW, \ff(\xx, t), \vv, \QQ, \RR$}
    \State $\mmu_{0|0}, \Sigma_{0|0} \gets \vv, \bz$
    \State $\mi_{1:N} \gets \bz$
    \For{$n=1:N$}
    \State $\mmu_{n|n-1}, \SSi_{n|n-1} \gets \kpredict(\mmu_{n-1|n-1}, \SSi_{n-1|n-1}, \bz, \QQ, \RR)$
    \State $\aa_n, \BB_n, \vi_n \gets \inter(\mmu_{n|n-1}, \SSi_{n|n-1}, \WW, \ff(\xx, t))$\label{ln:inter} \Comment{See Table~\ref{tab:inter}}
    \State $\mmu_{n|n}, \SSi_{n|n} \gets \kupdate(\mmu_{n|n-1}, \SSi_{n|n-1}, \mi_n, \aa_n, \WW + \BB_n, \vi_n)$
    \EndFor
    \State \textbf{return} $\mmu_{0|0}, \ldots, \mmu_{N|N}, \SSi_{0|0}, \ldots, \SSi_{N|N}$
    \EndProcedure
  \end{algorithmic}
\end{algorithm}
