\subsection{Multiple Variables and Blocking} \label{sec:block}
For a multivariable function $\xx(t) = \big(x_1(t), \ldots, x_d(t)\big)$, let $\XX_k(t) = (x^{(0)}_k(t),\ldots, x^{(p_k-1)}_k(t))$ denote $x_k(t) = x_k^{(0)}(t)$ and its first $p_k-1$ derivatives.  An ODE-IVP for $\xx(t)$ can then be written as  
% The ODE-IVP for a multi-variable function $\xx(t) = \big(x_1(t), \ldots, x_d(t)\big)$ is of the form
\begin{equation}\label{eq:mode}
    \WW \XX(t) = \ff(\XX(t), t), \qquad \XX(\tmin) = \vv, \qquad t \in [\tmin, \tmax],
\end{equation}
where
\begin{equation}\label{eq:block}
    %\begin{aligned}
  \XX(t) = \big(\XX_1(t), \ldots, \XX_d(t)\big).
  % , \qquad \XX_k(t) = (x^{(0)}_k(t),\ldots, x^{(p_k-1)}_k(t)),
    %\end{aligned}
\end{equation}
% contains $x_k(t) = x_k^{(0)}(t)$ and its first $p_k-1$ derivatives.
The Kalman ODE solver described in Algorithm~\ref{alg:Kalman} can be applied almost exactly for multiple ODE variables as for the univariate case.  It is easy to see that Algorithm~\ref{alg:Kalman} scales linearly in the number of evaluation points $N$.  However, it scales as $\bO(d^3)$ in the number of ODE variables $d$, which is a significant drawback for large ODE systems.

Suppose that it is possible to rearrange the rows of $\WW$ (and corresponding outputs of $f(\XX(t), t)$) such that
\begin{equation}
  \WW =
  \begin{bmatrix}
    \WW^{(1)}_{r_1\times p_1} & & \\
                              & \ddots & \\
                              & & \WW^{(d)}_{r_d\times p_d}
  \end{bmatrix}
\end{equation}
is block diagonal.  Furthermore, suppose that the outputs of the interrogation method are also blocked by system variable, i.e.,
\begin{equation}\label{eq:blockinter}
  \aa_n =
  \begin{bmatrix}
    \aa^{(1)}_{p_1\times 1} \\ \vdots \\ \aa^{(d)}_{p_d\times 1}\big)
  \end{bmatrix}, \qquad
  \BB_n =
  \begin{bmatrix}
    \BB^{(1)}_{p_1\times p_1} & & \\
                              & \ddots & \\
                              & & \BB^{(d)}_{p_d\times p_d}
  \end{bmatrix}, \qquad
  \vi_n =
  \begin{bmatrix}
    \vi^{(1)}_{p_1\times p_1} & & \\
                              & \ddots & \\
                              & & \vi^{(d)}_{p_d\times p_d})
  \end{bmatrix}.
\end{equation}
Then by setting the Gaussian Markov prior on $\XX(t)$ to consist of independent priors for each $\XX_k(t)$, $k = 1,\ldots, d$, i.e., such that
\begin{equation}
  \QQ =
  \begin{bmatrix}
    \QQ^{(1)}_{p_1\times p_1} & & \\
                              & \ddots & \\
                              & & \QQ^{(d)}_{p_d \times p_d}
  \end{bmatrix}, \qquad
  \RR =
  \begin{bmatrix}
    \RR^{(1)}_{p_1\times p_1} & & \\
                              & \ddots & \\
                              & & \RR^{(d)}_{p_d \times p_d}
  \end{bmatrix},
\end{equation}
each of the steps in Algorithm~\ref{alg:Kalman} can be performed variable-wise, thus reducing the computational complexity from $\bO(d^3)$ to $\bO(d)$~\citep{kramer21}.  This acceleration technique, together with the smoothing step to approximate $\XX_{0:N}$ by $\mmu_{0:N|N}$, gives \rodeo a low memory footprint particularly advantageous for backpropagation.  That is, while solvers with high memory cost must approximate gradients via the adjoint method~\citep[e.g.,][]{chen.etal18, kidger21}, \rodeo can simply backpropagate through the solver steps which is typically much faster~\citep{kidger21}.

The block interrogation condition~\eqref{eq:blockinter} is satisfied by the interrogation methods of~\cite{chkrebtii.etal16} and~\cite{schober.etal19} in Table~\ref{tab:inter}, but notably not by the method of~\cite{tronarp.etal18}. The issue lies in the Jacobian $\JJ_f(\xx, t)$, which may not necessarily be block diagonal. The method of~\cite{kramer21} addresses this by keeping only the block diagonal components of $\JJ_f(\xx, t)$ to form $\JJ^*_f(\xx, t)$, and setting the remaining components to zero.  There is extensive evidence in our experiments and those of~\cite{kramer21} suggesting there is minimal loss in accuracy compared to using the full Jacobian $\JJ_f(\xx, t)$ while greatly reducing computational complexity.

The Kalman ODE solver for multiple variables with blocking is extremely similar to Algorithm~\ref{alg:Kalman}: one simply replaces $\xx_n$ by $\XX_n$ and performs the Kalman recursions blockwise.  Defining $\vv = (\vv^{(1)}, \ldots, \vv^{(d)})$, $\mmu_{m|n} = (\mmu_{m|n}^{(1)}, \ldots, \mmu_{m|n}^{(d)})$, $\SSi_{m|n} = \diag(\SSi_{m|n}^{(1)}, \ldots, \SSi_{m|n}^{(d)})$, etc., 
for completeness, the exact steps of the \rodeo solver are presented in Algorithm~\ref{alg:KalmanBlock}.
\begin{algorithm}[!htb]
    \caption{The \rodeo probabilistic ODE solver.  \fct{rodeo\_ode\_sim} is used to obtain a draw from $p_\L(\XX_{1:N} \mid \ZZ_{1:N} = \bz)$, whereas \fct{rodeo\_ode\_mv} is used to obtain $\mmu_{0:N|N}$ and $\SSi_{0:N|N}$, where $\mu_{n|N} = E_\L[\XX_{n} \mid \ZZ_{1:N}=\bz]$ and $\SSi_{n|N} = \var_\L(\XX_n \mid \ZZ_{1:N}=\bz)$.  Both use the same forward pass through the model interrogations in \fct{rodeo\_forward}.  The \code{block} versions of the Kalman algorithms are elementary extensions of the non-block versions.  Thus, only the pseudocode for \fct{kalman\_block\_sample} is provided.}\label{alg:KalmanBlock}
    \begin{algorithmic}[1]
      \Procedure{\code{rodeo\_ode\_sim}}{$\WW, \ff(\XX, t), \vv, \QQ, \RR$}
      \State $(\mmu_{0|0}, \SSi_{0|0}), \ldots, (\mmu_{N|N}, \SSi_{N|N}) \gets \mcode{rodeo\_forward}(\WW, \ff(\XX, t), \vv, \QQ, \RR)$
      \For{$k=1:d$}
      \State $\XX_N^{(k)} \sim \N(\mmu_{N|N}^{(k)}, \SSi_{N|N}^{(k)})$ \label{ln:prng}
      \EndFor
      \State $\XX_N \gets (\XX_N^{(1)}, \ldots, \XX_N^{(d)})$
        \For{$n=N-1:0$}
        \State $\XX_n \gets \kbsample(\XX_{n+1}, \mmu_{n|n}, \SSi_{n|n}, \mmu_{n+1|n}, \SSi_{n+1|n}, \QQ)$
        % \State $\tilde{\mmu}_{n|N}, \tilde \SSi_{n|N} \gets \mcode{kalman\_block\_sample}(\XX_{n+1}, \mmu_{n|n}, \SSi_{n|n}, \mmu_{n+1|n}, \SSi_{n+1|n}, \QQ)$
        % \State $\XX_n \gets \BN(\tilde \mmu_{n|N}, \tilde \SSi_{n|N})$
        \EndFor
        \State \textbf{return} $\XX_{0:N}$  
        \EndProcedure
        \State
      \Procedure{\code{rodeo\_ode\_mv}}{$\WW, \ff(\XX, t), \vv, \QQ, \RR$}
      \State $(\mmu_{0|0}, \SSi_{0|0}), \ldots, (\mmu_{N|N}, \SSi_{N|N}) \gets \mcode{rodeo\_forward}(\WW, \ff(\XX, t), \vv, \QQ, \RR)$
        \For{$n=N-1:0$}
        \State $\mmu_{n|N}, \SSi_{n|N} \gets \kbsmooth(\mmu_{n+1|N}, \SSi_{n+1|N}, \mmu_{n|n}, \SSi_{n|n}, \mmu_{n+1|n}, \SSi_{n+1|n}, \QQ)$
        \EndFor
        \State \textbf{return} $\mmu_{0:N|N}, \SSi_{0:N|N}$  
        \EndProcedure
        \State
        \Procedure{\code{rodeo\_forward}}{$\WW, \ff(\XX, t), \vv, \QQ, \RR$}
        \State $\mmu_{0|0}, \Sigma_{0|0} \gets \vv, \bz$
        \State $\ZZ_{1:N} \gets \bz$
        \For{$n=1:N$}
        \State $\mmu_{n|n-1}, \SSi_{n|n-1} \gets \kbpredict(\mmu_{n-1|n-1}, \SSi_{n-1|n-1}, \bz, \QQ, \RR)$
        \State $\aa_n, \BB_n, \vi_n \gets \binter(\mmu_{n|n-1}, \SSi_{n|n-1}, \WW, \ff(\XX, t))$ 
        \State $\mmu_{n|n}, \SSi_{n|n} \gets \kbupdate(\mmu_{n|n-1}, \SSi_{n|n-1}, \ZZ_n, \aa_n, \WW + \BB_n, \vi_n)$ \label{ln:filter}
        \EndFor
        \State \textbf{return} $(\mmu_{0|0}, \SSi_{0|0}), \ldots, (\mmu_{N|N}, \SSi_{N|N})$
        \EndProcedure
        \State \Procedure{\kbsample}{$\XX_{n+1}, \mmu_{n|n}, \SSi_{n|n}, \mmu_{n+1|n}, \SSi_{n+1|n}, \QQ$}
        \For{$k=1:d$}
        \State $\XX_n^{(k)} \gets \ksample(\XX_{n+1}^{(k)}, \mmu_{n|n}^{(k)}, \SSi_{n|n}^{(k)}, \mmu_{n+1|n}^{(k)}, \SSi_{n+1|n}^{(k)}, \QQ^{(k)})$
        \EndFor
        \State \textbf{return} $\XX_n = (\XX_n^{(1)}, \ldots, \XX_n^{(d)})$        
        \EndProcedure
    \end{algorithmic}
\end{algorithm}


\section{Parameter Inference} \label{sec:parinf}


The parameter-dependent extension of the ODE-IVP~\eqref{eq:mode} 
% for a multi-variable function $\xx(t) = \big(x_1(t), \ldots, x_d(t)\big)$
is of the form
\begin{equation}\label{eq:pode}
    \WW_\tth \XX(t) = \ff_\tth(\XX(t), t), \qquad \XX(\tmin) = \vv_\tth, \qquad t \in [\tmin, \tmax].
\end{equation}
The corresponding nonlinear state-space model is
\begin{equation}\label{eq:pbnf}
    \begin{aligned}
        % \xx_0 & = \vv \\
        \XX_{n+1} \mid \XX_n & \sim \N(\QQ_\eet \XX_n, \RR_\eet) \\
        % \xx_{0:N} & \sim \N(\mmu_0, \SSi_0) \\
        \ZZ_n & \ind \N(\WW_\tth \XX_n - \ff_\tth(\XX_n, t_n), \vi_n),
    \end{aligned}
\end{equation}
and the surrogate model is
\begin{equation}\label{eq:pmi}
    \begin{aligned}
        \XX_{n+1} \mid \XX_n & \sim \N(\QQ_\eet \XX_n, \RR_\eet) \\
        \ZZ_n & \ind \N((\WW_\tth + \BB_n)\XX_n + \aa_n, \vi_n),
    \end{aligned}
\end{equation}
where the Gaussian Markov process parameters $\QQ_\eet$ and $\RR_\eet$ depend on tuning parameters $\eet$.
The learning problem consists of estimating the unknown parameters $\tth$ which determine $\XX(t)$ in~\eqref{eq:pode} from noisy observations $\YY_{0:M} = (\YY_0, \ldots, \YY_M)$, recorded at times $t = t'_0, \ldots, t'_M$ under the measurement model
\begin{equation}\label{eq:meas}
    \YY_i \ind p(\YY_i \mid \XX(t'_i), \pph).
\end{equation}
Parameter inference is conducted via the likelihood function for $\TTh = (\tth, \pph, \eet)$,
\begin{equation}\label{eq:likepar}
  \begin{aligned}
    \Ell(\TTh \mid \YY_{0:M}) & \propto p(\YY_{0:M} \mid \ZZ_{1:N} = \bz, \TTh) \\
                              & = \int p(\YY_{0:M} \mid \XX_{0:N}, \pph) p(\XX_{1:N} \mid \ZZ_{1:N}= \bz, \tth, \eet) \dd{\XX_{1:N}}.
  \end{aligned}
\end{equation}

Unlike other software for probabilistic ODE solvers, \rodeo is primarily concerned with parameter inference.  Several methods for ODE parameter inference within the \rodeo framework are presented in the subsections below.


