        \State $\AA_N, \bb_N, \CC_N \gets \bz, \mmu_{N|N}, \SSi_{N|N}$
        \State $\mmu_N, \SSi_N \gets \kbforecast(\mmu_{N|N}, \SSi_{N|N}, \bz, \DD_M, \OOm_M)$
        \State $\ell \gets \ell + \nlogpdf(\yy_N; \mmu_N, \SSi_N)$
        \State $\mmu_{N|N}^\prime, \SSi_{N|N}^\prime \gets  \kbupdate(\mmu_{N|N}, \SSi_{N|N}, \YY_M, \bz, \DD_M, \OOm_M)$
        \For{$n=N-1:0$}
        \State $\AA_n, \bb_n, \CC_n \gets \kbcond(\mmu_{n|n}, \SSi_{n|n}, \mmu_{n+1|n}, \SSi_{n+1|n}, \QQ)$
        \State $\mmu_{n|n+1}^\prime, \SSi_{n|n+1}^\prime \gets \kpredict(\mmu_{n+1|n+1}^\prime, \SSi_{n+1|n+1}^\prime, \bb_n, \AA_n, \CC)$
        \If{$t_n = t_{n(i)}$}
        \State $\mmu_n, \SSi_n \gets \kbforecast(\mmu_{n|n+1}^\prime, \SSi_{n|n+1}^\prime, \bz, \DD_i, \OOm_i)$
        \State $\ell \gets \ell + \nlogpdf(\YY_i; \mmu_n, \SSi_n)$ 
        \State $\mmu_{n|n}^\prime, \SSi_{n|n}^\prime \gets \kbupdate(\mmu_{n|n+1}^\prime, \SSi_{n|n+1}^\prime, \yy_n, \bz, \DD_i, \OOm_i)$ 
        \State $i \gets i - 1$
        \Else 
        \State $\mmu_{n|n}^\prime, \SSi_{n|n}^\prime \gets \mmu_{n|n+1}^\prime, \SSi_{n|n+1}^\prime$
        \EndIf
        \EndFor
        \State \textbf{return} $\ell$ %: a random draw from $p(\xx_{0:N} \mid \mi_{1:N})$.
        \EndProcedure
    \end{algorithmic}
\end{algorithm}


\subsection{DALTON}\label{sec:dalton}


The \fenrir approximation can be applied to any of the model interrogations in Table~\ref{tab:inter}.  However, each of these model interrogation methods is data-free, in the sense that it does not use any of the noisy observations $\YY_{0:M}$ in the ODE solver.  In contrast, the \dalton approximation~\citep{wu.etal24} is data-adaptive in that it uses the $\YY_{0:M}$ to approximate the ODE solution.  \dalton provides two methods for computing~\eqref{eq:likepar} depending on whether the measurement model~\eqref{eq:meas} is Gaussian or non-Gaussian. The former uses the identity
\begin{equation}\label{eq:condp}
    p(\YY_{0:M} \mid \ZZ_{1:N} = \bz, \TTh) = \frac{p(\YY_{0:M}, \ZZ_{1:N} = \bz \mid \TTh)}{p(\ZZ_{1:N} = \bz \mid \TTh)}.
\end{equation}
The denominator $p(\ZZ_{1:N} = \bz \mid \TTh)$ on the right-hand side is estimated using a Kalman filter on the data-free surrogate model~\eqref{eq:pmi}~\citep[e.g.,][and see details in Algorithm~\ref{alg:dalton}]{tronarp.etal18, schober.etal19}. The numerator $p(\YY_{0:M}, \ZZ_{1:N} = \bz \mid \TTh)$ can be computed by augmenting the surrogate model~\eqref{eq:pmi} at the measurement locations $n = n(i)$ via
\begin{equation}\label{eq:daltonlin}
    \begin{aligned}
        \begin{bmatrix}
            \ZZ_{n(i)} \\
            \YY_i
        \end{bmatrix} & \ind 
        \N\left(\left(\begin{bmatrix}
            \WW_\tth \\
            \DD^{(\pph)}_i
        \end{bmatrix} + \begin{bmatrix}
            \BB_{n(i)} \\
            \bz
        \end{bmatrix}\right)\XX_{n(i)} + \begin{bmatrix} \aa_{n(i)} \\ \bz \end{bmatrix}, 
        \begin{bmatrix}
            \VV_{n(i)} & \bz \\
            \bz & \OOm^{(\pph)}_i
        \end{bmatrix} \right),
    \end{aligned}
\end{equation}
where the data-free interrogation coefficients $\aa_{n(i)}$, $\BB_{n(i)}$, and $\VV_{n(i)}$ are computed exactly as in Table~\ref{tab:inter}. Additionally, \dalton can also benefit from blocking by having the same requirements for $\DD_i^{(\pph)}$ and $\OOm_i^{(\pph)}$ as \fenrir. The exact computations are presented in Algorithm~\ref{alg:dalton}.  The non-Gaussian case is somewhat more involved and detailed in Appendix~\ref{sec:daltonng}.


