\begin{algorithm}[!htb]
    \caption{DALTON probabilistic ODE likelihood approximation for Gaussian measurements.}\label{alg:dalton}
    \begin{algorithmic}[1]
        \Procedure{\code{dalton}}{}$\left(
        \begin{aligned}
          & \WW = \WW_\tth, \quad \ff(\XX, t) = \ff_\tth(\XX, t), \quad \vv = \vv_\tth, \\
          & \QQ = \QQ_\eet, \quad \RR = \RR_\eet, \\
          & \YY_{0:M}, \quad \DD_{0:M} = \DD^{(\pph)}_{0:M}, \quad \OOm_{0:M} = \OOm^{(\pph)}_{0:M}
        \end{aligned}
      \right)$
        \State $\mmu_{0|0}, \Sigma_{0|0} \gets \vv, \bz$ \Comment{Initialization}
        \State $\ZZ_{1:N} \gets \bz$
        \State $\ell_z, \ell_{yz} \gets 0, 0$
        \State $i \gets 1$ \Comment{Used to map $t_n$ to $t'_i$}
        \State \Comment{Lines 7-12 compute $\log p(\ZZ_{1:N} = \bz \mid \TTh)$}
        \For{$n=1:N$}
        \State $\mmu_{n|n-1}, \SSi_{n|n-1} \gets \kbpredict(\mmu_{n-1|n-1}, \SSi_{n-1|n-1}, \bz, \QQ, \RR)$
        \State $\aa_n, \BB_n, \VV_n \gets \binter(\mmu_{n|n-1}, \SSi_{n|n-1}, \WW, \ff(\XX, t_n))$
        \State $\mmu_n, \SSi_n \gets \kbforecast(\mmu_{n|n-1}, \SSi_{n|n-1}, \aa_n, \WW + \BB_n, \VV_n)$
        \State $\ell_z \gets \ell_z + \nlogpdf(\ZZ_n^{(k)}; \mmu_n^{(k)}, \SSi_n^{(k)})$ 
        \State $\mmu_{n|n}, \SSi_{n|n} \gets \kbupdate(\mmu_{n|n-1}, \SSi_{n|n-1}, \ZZ_n, \aa_n, \WW + \BB_n, \VV_n)$
        \EndFor
        \State \Comment{Lines 14-25 compute $\log p(\YY_{0:M}, \ZZ_{1:N} = \bz \mid \TTh)$}
        \State $\ell_{yz} \gets \nlogpdf(\YY_0; \DD_0\vv, \OOm_0)$
        \For{$n=1:N$}
        \State $\mmu_{n|n-1}, \SSi_{n|n-1} \gets \kbpredict(\mmu_{n-1|n-1}, \SSi_{n-1|n-1}, \bz, \QQ, \RR)$
        \State $\aa_n, \BB_n, \VV_n \gets \inter(\mmu_{n|n-1}, \SSi_{n|n-1}, \WW, \ff(\XX, t_n))$
        \If{$t_n = t_{n(i)}$}
        \For{$k=1:d$}
        \State $\ZZ_n^{(k)} \gets  \begin{bmatrix}
            \ZZ_n^{(k)} \\
            \YY_i^{(k)}
        \end{bmatrix}, \qquad
        \WW^{(k)} \gets \begin{bmatrix} 
            \WW^{(k)} \\
            \DD_i^{(k)}
        \end{bmatrix}, \qquad
        \BB_n^{(k)} \gets \begin{bmatrix}
            \BB_n^{(k)} \\
            \bz
        \end{bmatrix}$
        \State $\aa_n^{(k)} \gets \begin{bmatrix}
            \aa_n^{(k)} \\
            \bz
        \end{bmatrix}, \qquad
        \VV_n^{(k)} \gets \begin{bmatrix}
            \VV_n^{(k)} & \bz \\
            \bz & \OOm_i^{(k)}
        \end{bmatrix}$ 
        \State $i \gets i + 1$
        \EndFor
        \EndIf
        \State $\mmu_n, \SSi_n \gets \kbforecast(\mmu_{n|n-1}, \SSi_{n|n-1}, \aa_n, \WW + \BB_n, \VV_n)$    
        \State $\ell_{yz} \gets \ell_{yz} + \nlogpdf(\ZZ_n; \mmu_n, \SSi_n)$
        \State $\mmu_{n|n}, \SSi_{n|n} \gets \kbupdate(\mmu_{n|n-1}, \SSi_{n|n-1}, \ZZ_n, \aa_n, \WW + \BB_n, \VV_n)$
        \EndFor
        \State
        \State \textbf{return} $\ell_{yz} - \ell_z$ \Comment{Estimate of $\log p(\YY_{0:M} \mid \ZZ_{1:N} = \bz, \TTh)$}
        \EndProcedure
    \end{algorithmic}
\end{algorithm}


\subsection{Marginal MCMC} \label{sec:chkmcmc}


In principle, the \fenrir and \dalton algorithms can be applied with any of the model interrogations in Table~\ref{tab:inter}.  
% the \fenrir approximation can be applied to any of the model interrogations in Table~\ref{tab:inter}.
However, the interrogation method of~\cite{chkrebtii.etal16} produces the $\aa_n$ stochastically, such that a direct application of \fenrir would not include the additional uncertainty resulting from this step.  To address this,~\cite{chkrebtii.etal16} adopt a Bayesian approach, whereby for a given parameter prior $\pi(\TTh)$ and arbitrary measurement model~\eqref{eq:meas}, they present a marginal MCMC algorithm for
\begin{equation}
  \begin{aligned}
    \hat{p}(\TTh, \XX_{1:N} \mid \YY_{0:M}, \ZZ_{1:N} = \bz) & \propto \pi(\TTh) \times p(\YY_{0:M} \mid \XX_{0:N}, \pph) \\
                                                             & \times \int \hat{p}_\L(\XX_{1:N}, \ipar_{1:N} \mid \ZZ_{1:N} = \bz, \tth, \eet) \dd{\ipar_{1:N}},
    \end{aligned}
\end{equation}
where $\hat{p}_\L(\XX_{1:N}, \ipar_{1:N} \mid \ZZ_{1:N} = \bz, \tth, \eet)$ corresponds to the surrogate model~\eqref{eq:pmi} with possibly stochastic model interrogation terms $\ipar_{1:N} = (\aa_{1:N}, \BB_{1:N}, \VV_{1:N})$.  The relevant Metropolis-Hastings update is described in Algorithm~\ref{alg:Chkrebtii}.  The term ``marginal'' refers to the fact that $\hat{p}_\L(\XX_{1:N}, \ipar_{1:N} \mid \ZZ_{1:N} = \bz, \tth, \eet)$ appears both in the target posterior density and the Markov transition kernel, thus dropping out of the Metropolis-Hastings acceptance rate completely.  For the Gaussian measurement model~\eqref{eq:measnorm} and deterministic interrogation terms $\ipar_{0:N}$, the marginal MCMC algorithm targets the posterior distribution of the \fenrir likelihood combined with the given prior $\pi(\TTh)$.
% described in Algorithm~\ref{alg:Chkrebtii}, which can be employed for any model interrogation method with possibly stochastic linearization terms $\aa_n$, $\BB_n$, and $\VV_n$.
% can be used The \fenrir approach conditions on $\aa_n$, $\BB_n$, and $\vi_n$ in the backward Markov chain of~\eqref{eq:fenrirback}. However, the interrogation method of~\cite{chkrebtii.etal16} gives random outputs for which \fenrir cannot use. In contrast, the \chkrebtii algorithm integrates over these random quantities via MCMC~\citep{chkrebtii.etal16}. \chkrebtii begins by initializing $\tth_0$ from a given prior $\pi(\tth)$. Next, a sample solution, $\xx_{0:N}$ dependent on $\tth_0$ is computed from Algorithm~\ref{alg:KalmanBlock} with the interrogation of~\cite{chkrebtii.etal16}.  At each sampling step, $\tth' \sim q(\tth_{i-1})$ is sampled from the proposal distribution and is used to compute a new sample solution, $\xx_{0:N}'$. Finally, a rejection ratio is used to decide if $\tth_i = \tth'$ is updated or $\tth_i = \tth_{i-1}$ is kept. The exact steps are presented in Algorithm~\ref{alg:Chkrebtii} where $S$ samples of the posterior of $\tth$ are returned.
\begin{algorithm}[!htb]
    \caption{Marginal MCMC algorithm of~\cite{chkrebtii.etal16}.}\label{alg:Chkrebtii}
    \begin{algorithmic}[1]
      \Procedure{\code{marginal\_mcmc\_step}}{$\TTh^\curr, \XX_{0:N}^\curr, \YY_{0:M}$}
        \State $\TTh^\prop \sim q(\TTh \mid \TTh^\curr)$
        \State $\XX_{0:N}^\prop \gets \mcode{rodeo\_ode\_sim}(\WW_{\tth^\prop}, f_{\tth^\prop}(\XX, t), \vv_{\tth^\prop}, \QQ_{\eet^\prop}, \RR_{\eet^\prop})$ \label{ln:rwkernel}
        % \State $\rho^\prop \gets p(\YY_{0:M} \mid \XX_{n(0:M)}^\prop, \eet^\prop) \times \pi(\TTh^\prop)$
        \State $\displaystyle \rho \gets \frac{p(\YY_{0:M} \mid \XX_{n(0:M)}^\prop, \eet^\prop) \times \pi(\TTh^\prop) / q(\TTh^\prop \mid \TTh^\curr)}{ p(\YY_{0:M} \mid \XX_{n(0:M)}^\curr, \eet^\curr) \times \pi(\TTh^\curr) / q(\TTh^\curr \mid \TTh^\prop)}$
        \State $v \sim \operatorname{Uniform}(0,1)$
        \If{$v < \rho$}
        \State $\TTh^\curr, \XX_{0:N}^\curr \gets \TTh^\prop, \XX_{0:N}^\prop$
        \EndIf
        \State \textbf{return} $\TTh^\curr, \XX_{0:N}^\curr$ 
        \EndProcedure
