% \end{equation} 
% and together with the first and third terms in~\eqref{eq:magijoint}, we obtain
% \begin{equation} \label{eq:magimarkov}
% \begin{aligned}
% p(\TTh, \UU_{0:N}, \ZZ_{1:N}, \YY_{0:M}) & = \pi(\TTh) \times \prod_{n=1}^N p(\XX_n \mid \XX_{n-1}, \eet) \times p(\YY_{0:M} \mid \XX_{0:N}, \pph).
% \end{aligned}
% \end{equation}
% The (non-degenerate) \magi posterior distribution in this context is given by
% \begin{equation}\label{eq:magipost}
% p(\TTh, \UU_{0:N} \mid \ZZ_{1:N} = \bz, \YY_{0:M}) = C^{-1} \times p(\TTh, \UU_{0:N}, \ZZ_{1:N} = \bz, \YY_{0:M}),
% \end{equation}
% where
% $$
% C = \int p(\TTh, \UU_{0:N}, \ZZ_{1:N} = \bz, \YY_{0:M}) \ud \TTh \ud \UU_{0:N},
% $$
% and $p(\TTh, \UU_{0:N}, \ZZ_{1:N}=\bz, \YY_{0:M})$ is given by~\eqref{eq:magimarkov}.

Sampling from the \magi posterior in~\eqref{eq:magipost} is done via MCMC, which as a byproduct produces samples from $p(\TTh \mid \ZZ_{1:N} = \bz, \YY_{0:M})$. However, it is often possible to significantly reduce the number of variables in the MCMC sampler. That is, consider the smallest subset $\tilde \UU_{0:N} \subseteq \UU_{0:N}$ such that, for $\tilde \XX_{0:N} = (\tilde \UU_{0:N}, \WW_{0:N})$, we have
\begin{equation}
  \begin{aligned}
    \ff_\tth(\tilde \UU_{0:N}, t_{0:N}) & = \ff_\tth(\UU_{0:N}, t_{0:N}), \\
    p(\YY_{0:M} \mid \tilde \XX_{0:N}, \pph) & = p(\YY_{0:M} \mid \XX_{0:N}, \pph).
  \end{aligned}
\end{equation}
Continuing with the example in~\eqref{eq:exode}, we have 
\begin{equation}
\tilde \UU_n = \begin{bmatrix} x^{(0)}_n \end{bmatrix}, \qquad
\tilde\XX_n = \begin{bmatrix} 
        x^{(0)}_n \\ x^{(1)}_n
        \end{bmatrix}.
\end{equation}
The \magi posterior in terms of the smallest subset $\tilde{\UU}_{0:N}$ is
\begin{equation}\label{eq:magimodified}
  \begin{aligned}
    p(\TTh, \tilde \UU_{1:N} \mid \YY_{0:M}, \ZZ_{1:N} = \bz) & \propto \pi(\TTh) \times p(\tilde \XX_{1:N} \mid \TTh) \times p(\YY_{0:M} \mid \tilde \XX_{0:N}, \pph), \\
    & = \pi(\TTh) \times p(\tilde \XX(\tilde \UU_{1:N}) \mid \eet) \times p(\YY_{0:M} \mid \tilde \XX(\tilde \UU_{0:N}), \pph),
    \end{aligned}
\end{equation}
where $\tilde \XX(\tilde \UU_{n}) = (\tilde{\UU}_n, \ff_{\tth}(\tilde{\UU}_n, t_n))$.  In other words, the second term in~\eqref{eq:magimodified} is the density induced by the Gaussian Markov process prior in~\eqref{eq:pbnf} on $\tilde \XX_{0:N} = (\tilde \UU_{0:N}, \WW_{0:N})$, evaluated at $\tilde \XX(\tilde \UU_{0:N})$.

The $\tilde \XX_{1:N}$ in~\eqref{eq:magimodified} are typically not Markov. However, since $\tilde \XX_{1:N}$ is a subset of the Gaussian Markov random variables $\XX_{1:N}$, we can use Kalman recursions to efficiently compute the joint density $p(\tilde \XX_{1:N} \mid \eet)$ with linear time complexity $\bO(N)$.  Thus, the \magi posteriors~\eqref{eq:magipost} and~\eqref{eq:magimodified} for the full and subset variables $\UU_{1:N}$ and $\tilde \UU_{1:N}$ have the same computational complexity per evaluation, but the latter contains $c \times N$ fewer random variables, where $c$ is a function of the number of system variables $d$ and the number of additional derivatives $q-p$ in the IBM prior~\eqref{eq:ibm}.  This can be a significant advantage for speeding up the convergence of the MCMC sampler on~\eqref{eq:magimodified}.

In practice, the length of the solution process $N$ is often much greater than the number of observations $M$, in which case the modified \magi posterior in~\eqref{eq:magimodified} is dominated by the second term~\citep{yang.etal21}. This occurs because the density of $p(\tilde \XX_{1:N} \mid \eet)$ includes many more terms than the likelihood $p(\YY_{0:M} \mid \tilde \XX_{0:N}, \pph)$. To address this imbalance,~\cite{yang.etal21} suggests tempering the density $p(\tilde \XX_{1:N} \mid \eet)^{1/\beta}$ by a hyperparameter $\beta$, referred to as the prior temperature, to better balance the contributions of the density and the likelihood.  The $\beta$-modulated \magi posterior is thus
\begin{equation}\label{eq:magimodbeta}
  \begin{aligned}
    p_\beta(\TTh, \tilde \UU_{1:N} \mid \ZZ_{1:N}, \YY_{0:M})
    & \propto p_\beta(\TTh, \tilde \UU_{1:N}, \ZZ_{1:N} = \bz, \YY_{0:M}) \\
    & = \pi(\TTh) \times p(\tilde \XX(\tilde \UU_{1:N}) \mid \eet)^{1/\beta} \times p(\YY_{0:M} \mid \tilde \XX(\tilde \UU_{0:N}), \pph).
  \end{aligned}
\end{equation}
The exact steps for computing~\eqref{eq:magimodbeta} are presented in Algorithm~\ref{alg:magi}.
% The main advantage of the modified \magi posterior in~\eqref{eq:magimodified} is that the number of variables in the MCMC sampler remains unchanged as the parameter $q$,  which governs the number of derivatives in the Gaussian Markov process prior from Section~\ref{sec:prior}, increases. 
\begin{algorithm}[!htb]
    \caption{\magi algorithm of~\cite{yang.etal21} for computing the $\beta$-modulated posterior~\eqref{eq:magimodbeta} with Gaussian Markov process prior.}\label{alg:magi}
    \begin{algorithmic}[1]
        \Procedure{\code{magi\_logpost}}{$\tilde \UU_{0:N}, \ff(\XX, t) = \ff_\tth(\XX, t), \vv = \vv_\tth, \QQ = \QQ_\eet, \RR = \RR_\eet, \YY_{0:M}, \beta$}
        \State $\mmu_{0|0}, \Sigma_{0|0} \gets \vv, \bz$ \Comment{Lines 2-10 compute $p(\tilde \UU_{0:N}, \ZZ_{1:N} = \bz \mid \TTh)$}
        \State $\ell \gets 0$
        \State $\tilde \XX_{0:N} \gets (\tilde \UU_{0:N}, \ff(\tilde \UU_{0:N}, t_{0:N}))$
        \State $\tilde \WW \gets \begin{bmatrix}\Id_{d\times q} & \bz_{d \times p-q}\end{bmatrix}$ \Comment{The dimensions are $\XX_{d\times p}$ and $\tilde \XX_{d\times q}$.}
        \For{$n=1:N$}
        \State $\mmu_{n|n-1}, \SSi_{n|n-1} \gets \kbpredict(\mmu_{n-1|n-1}, \SSi_{n-1|n-1}, \bz, \QQ, \RR)$
        \State $\mmu_n, \SSi_n \gets \kbforecast(\mmu_{n|n-1}, \SSi_{n|n-1}, \bz, \tilde \WW, \bz)$
        \State $\ell \gets \ell + \nlogpdf(\tilde \XX_n; \mmu_n, \SSi_n)$ 
        \State $\mmu_{n|n}, \SSi_{n|n} \gets \kbupdate(\mmu_{n|n-1}, \SSi_{n|n-1}, \tilde \XX_n, \bz, \tilde \WW, \bz)$
        \EndFor
        \State \Comment{Line 12 computes $\log p_\beta(\TTh, \tilde \UU_{1:N}, \ZZ_{1:N} = \bz, \YY_{0:M})$}
        \State $\ell \gets \log \pi(\TTh) + \frac{1}{\beta} \ell + \log p(\YY_{0:M} \mid \tilde \XX_{0:N}, \pph)$
        \State \textbf{return} $\ell$
        % \Comment{Estimate of $\log p(\tilde \XX_{0:N} \mid \TTh)$}
        \EndProcedure
    \end{algorithmic}
\end{algorithm}



\section{Implementation} \label{sec:packstruct}


\rodeo is designed to serve two types of users.  The first is statisticians and data scientists wishing to use probabilistic solvers to calibrate ODEs to empirical data.  The second is researchers interested in developing new probabilistic methods of ODE parameter inference within the general \rodeo framework
%Examples include adaptive step-size selection~\citep{chkrebtii.etal19}, initialization via deterministic solvers~\citep{schober.etal19}, uncertainty calibration~\citep{conrad.etal17, tronarp.etal18}, 
% strong convergence rates of probabilistic integrators~\citep{lie.etal17}, probabilistic solutions to ODEs~\citep{tronarp.etal18}, a modern retrospective on probabilistic numerics~\citep{Oates2019AMR}
and optimal tuning of the solution prior~\citep{chkrebtii.etal16}.
% \correct{find as many references to methodological developments as possible!  The Stat Comp special issue is a great place to start}.  


To best serve these audiences, \rodeo is written in \python using the \jax library for scientific computing.  \jax is a near drop-in replacement for the widely used \pkg{NumPy} linear algebra library~\citep{numpy}, making use of \rodeo straightforward for most \python users.  In addition to programming convenience, \jax offers state-of-the-art JIT compilation and automatic differentiation capabilities, of which the former offers a substantial performance increase over plain \pkg{NumPy} code, and the latter enables the use of high-performance gradient-based parameter learning algorithms (as shown in Section~\ref{sec:examples}).  In particular, parameter inference using the \rodeo likelihood approximations outlined in Section~\ref{sec:parinf} can be conducted using powerful \jax libraries for optimization (\pkg{JAXopt}~\citep{jaxopt}, \pkg{Optax}~\citep{optax}) and MCMC (\pkg{BlackJAX}~\citep{blackjax}).


There are three main components to the \rodeo library.  The first is a general-purpose Kalman filter and smoother.  The main Kalman algorithms are:
\begin{itemize}
\item \fct{predict}: Given $\mmu_{n-1|n-1}$ and $\SSi_{n-1|n-1}$, calculate $\mmu_{n|n-1}$ and $\SSi_{n|n-1}$.
\item \fct{update}: Given $\mmu_{n|n-1}$ and $\SSi_{n|n-1}$, calculate $\mmu_{n|n}$ and $\SSi_{n|n}$.
\item \fct{smooth}: Given $\mmu_{n+1|N}$ and $\SSi_{n+1|N}$, calculate $\mmu_{n|N}$ and $\SSi_{n|N}$.
\end{itemize}
The standard version of these algorithms (and a few related ones) are detailed in Appendix~\ref{sec:kalmanfun}. However, it has been shown that the so-called square-root variant of these algorithms~\citep{kaminski.etal71, bierman73} can greatly improve numerical accuracy in high-dimensional and/or stiff ODE systems~\citep{kramer20}. Both the standard and square-root of these algorithms are shipped in the \code{kalman} module of the \rodeo libary.
% We provide these in the \kalmantv\footnote{https://github.com/mlysy/kalmantv-jax} library, offering both the linear version and the square-root version.


The second primary component of \rodeo is the ODE solver itself.  This consists of two functions, \fct{solve\_mv} and \fct{solve\_sim}, which return the mean and variance $(\mmu_{0:N|N}, \SSi_{0:N|N})$ and a random draw $\XX_{1:N} \sim p(\XX_{1:N} \mid \ZZ_{1:N} = \bz)$, respectively, for the surrogate model~\eqref{eq:pmi}.  The common parameters to these functions are:
\begin{itemize}
\item \code{key}: A \jax pseudo-RNG key.  This is needed for any \jax calculation which requires random samples.
\item \code{ode\_weight}, \code{ode\_init}, \code{ode\_fun}, \code{params}: The ODE-IVP model components $\WW$, $\vv$, $\ff_\tth(\XX, t)$ and $\tth$.  The ODE function has argument signature \code{function(X, t, **params)}, such that the parameters of the model may be passed via arbitrary key-value pairs.  These same key-value pairs must then be supplied to \fct{solve\_sim} and \fct{solve\_mv}.
\item \code{t\_min}, \code{t\_max}, \code{n\_steps}: The time interval $(\tmin, \tmax)$ over which the ODE solution is sought, and the number of solver discretization points $N$.
\item \code{prior\_weight}, \code{prior\_var}: The weight and variance matrices $\QQ$ and $\RR$ of the solution prior as discretized to time intervals of size $\dt = (\tmax - \tmin)/N$.
\item \code{interrogate}: An interrogation function, i.e., a function with arguments \code{key}, $\mmu_{n|n-1}$, $\SSi_{n|n-1}$, $\WW$, $\ff_\tth(\XX, t)$, and $\tth$ which returns the interrogation variables $\aa_n$, $\BB_n$, and $\VV_n$ used in the surrogate model~\eqref{eq:pmi}.  Note that the \code{key} argument is used here to implement stochastic interrogation methods such as that of~\cite{chkrebtii.etal16} in Table~\ref{tab:inter}.
\item \code{kalman\_type}: This argument allows users to select either the standard or square-root implementation of the Kalman algorithms available in \rodeo.
% An object with methods consisting of the Kalman functions \fct{predict}, \fct{update}, \fct{smooth}, and etc. This argument allows users to supply alternative variants of the Kalman algorithms that may be better suited to their specific problem, rather than being limited to the standard and square-root implementations provided in \rodeo.
\end{itemize}


The third main component of \rodeo consists of implementations of the Basic, \fenrir, \dalton, marginal MCMC, and \magi inference algorithms described in Section~\ref{sec:parinf}.  These implementations share many of the same arguments as \fct{solve\_sim} and \fct{solve\_mv}.  Additional arguments are:
\begin{itemize}
\item \code{obs\_data}, \code{obs\_times}: The observed data $\YY_{0:M}$ and corresponding observation times $t'_{0:M}$.  For simplicity, these are rounded to the nearest values of the solution grid $t_{0:N}$.
\item \code{obs\_weight}, \code{obs\_var}: For the \fenrir and Gaussian \dalton algorithms, the weight and variance matrices $\DD_{1:M}^{(\pph)}$ and $\OOm_{1:M}^{(\pph)}$ in the multivariate normal observation model~\eqref{eq:measnorm}.
\item \code{obs\_loglik}: For the Basic and Marginal MCMC algorithms, the log of the observation likelihood $p(\YY_{0:M} \mid \XX_{n(0:M)}, \pph)$ in~\eqref{eq:meas}.  This is a function with argument signature \code{function(obs\_data, ode\_data, **params)}, corresponding to $\YY_{0:M}$, $\XX_{n(0:M)}$, and $\pph$, respectively.
% \item \code{obs\_loglik\_i}: For the non-Gaussian \dalton algorithm, the log of the observation likelihood at each index $p_i(\YY_i, \mid \XX_{n(i)}, \pph)$. This is a function with argument signature
% \code{function(obs\_data\_i, ode\_data\_i, ind, **params)}, corresponding to  $\YY_i$, $\XX_{n(i)}$, index $i$ and $\pph$, respectively. This is similar to \code{obs\_loglik} but broken down by observation indices.
\end{itemize}
A few other algorithm-specific arguments will be discussed in the relevant examples in Section~\ref{sec:examples}.
% In particular, we implement Chkrebtii in Algorithm~\ref{alg:Chkrebtii} assuming the proposal distribution to be $\TTh^\prop \sim \N(\TTh^\curr, \VV_\gga)$ where $\VV_\gga$ is a diagonal matrix with tuning parameter $\gga$. Specific examples for each of the inference methods above are provided in Section~\ref{sec:examples}.


Finally, \rodeo provides a few helper functions.  The two most important ones are \fct{ibm\_init} and \fct{indep\_init} to help set up the prior.  \fct{ibm\_init} creates the weight and variance matrices \code{prior\_weight} and \code{prior\_var} for the solution prior $\XX(t)$, for given time interval $\dt$ and number of required continuous derivatives per ODE variable, $p_1, \ldots, p_d$.


By default, we set all $p_k$, $k = 1,\ldots,d$ equal to their maximum value and return \jax arrays of size $d \times p \times p$, where $p = \max_{1\le k\le d} p_k$.  It is suggested that the ODE-IVP components \code{ode\_weight}, \code{ode\_init}, and \code{ode\_fun} be zero-padded accordingly (see Section~\ref{sec:examples}), and similarly stored in block format, i.e.,  with system variables as the leading dimension of \jax arrays.  This typically offers a performance boost despite padding when there are lots of variables with a similar number of derivatives. 


% \item \fct{indep\_init} combines separate $(\QQ^{(k)}, \RR^{(k)})$ for each ODE variable $k = 1,\ldots,d$ into block diagonal matrices $\QQ = \diag(\QQ^{(1)}, \ldots, \QQ^{(d)})$ and $\RR = \diag(\RR^{(1)}, \ldots, \RR^{(d)})$, effectively assuming independent Gaussian Markov process priors for each ODE variable.  When all the $(\QQ^{(k)}, \RR^{(k)})$ have the same dimensions, $\QQ$ and $\RR$ are stored as three-dimensional arrays as above.  Otherwise, they are stored as dense block diagonal matrices.


Zero-padding can be disabled in \fct{solve\_mv} and \fct{solve\_sim} by passing the ODE-IVP components as a single block.  To disable zero-padding for the IBM prior, we can compute $\QQ^{(k)}$ and $\RR^{(k)}$ separately for each $k = 1,\dots,d$, then combine them into densely-stored block-diagonal matrices using \fct{indep\_init}. % (see Example~\ref{sec:hode}).





\section{Examples} \label{sec:examples}


The following examples illustrate the use of \rodeo for solving and learning the parameters of various ODE-IVPs on $\xx(t) = (x_1(t), \ldots, x_d(t))$. All examples are implemented with variable blocking as described above.  That is, if the ODE-IVP involves the first $p_k-1$ derivatives of $x_k(t)$, then $x_k(t)$ is given an IBM prior with $p = \max_{1\le k \le d} p_k$ continuous derivatives, i.e., $q_k = p+1$, and the ODE-IVP is padded accordingly.  In the context of parameter inference, it will be convenient to introduce a problem-specific parameter transformation $\TTh = \utrans(\tth, \pph, \eet)$ such that the support of $\TTh$ is all of $\mathbb{R}^{\dim\{\tth\} + \dim\{\pph\} + \dim\{\eet\}}$.
% The specification of $\utrans(\tth, \pph, \eet)$ is problem-dependent


% , whenever the support of $\TTh$ is restricted to a proper subset of $\mathbb{R}^{\dim\{\TTh\}}$.  When $\TTh$ has unrestricted support, we simply make the identification $\upar = \TTh$.
% In the context of parameter learning, it will be convenient to introduce parameter transformation $\upar = \bm{\mathcal{G}}(\TTh)$ such that the support of $\upar$ is all of $\mathbb{R}^{\dim\{\upar\}}$, whenever the support of $\TTh$ is restricted to a proper subset of $\mathbb{R}^{\dim\{\TTh\}}$.  When $\TTh$ has unrestricted support, we simply make the identification $\upar = \TTh$.


% then the the prior on $\XX(t) = (\XX_1(t), \ldots, \XX_d(t))$ In the examples below, the prior on $\XX(t)$ is a product of $d$ independent IBM priors~\eqref{eq:ibm} with $p_k = q_k+1$ for $k=1,\ldots,d$. In other words, we assume that the prior on $x_k(t)$ has one more continuous derivative than the number of its derivatives appearing in the ODE-IVP~\eqref{eq:mode}. Furthermore, we assume $p = \max{p_k}$ for $k=1,\ldots,d$ and pad all variables up to the p-th order of derivative. 
