\section{Kalman Recursions}\label{sec:kalmanfun}
The Kalman recursions used in Algorithms~\ref{alg:Kalman},~\ref{alg:KalmanBlock},~\ref{alg:Fenrir},~\ref{alg:dalton} and~\ref{alg:daltonng} are formulated in terms of the general Gaussian state space model
\begin{equation}
    \begin{aligned}
        \XX_n &= \QQ_n \XX_{n-1} + \cc_n + \RR_n^{1/2} \eps_n \\
        \ZZ_n &= \WW_n \XX_n + \aa_n + \VV_n^{1/2} \eet_n
    \end{aligned}, \qquad \eps_n, \eet_n \ind \N(\bz,\Id).
\end{equation}
Throughout, we use the notation $\mmu_{n|m} = \E[\XX_n \mid \ZZ_{1:m}]$ and $\SSi_{n|m} = \var(\XX_n \mid \ZZ_{1:m})$.
\begin{algorithm}[H]
    \caption{Standard Kalman filtering and smoothing functions.}\label{alg:kalman}
    \begin{algorithmic}[1]
%        \LeftComment{Perform the prediction step.}
        \Procedure{\kpredict}{$\mmu_{n-1|n-1}, \SSi_{n-1|n-1}, \cc_n, \QQ_n, \RR_n$} % \Comment{Perform the prediction step.}
        \State $\mmu_{n|n-1} \gets \QQ_n\mmu_{n-1|n-1} + \cc_n$
        \State $\SSi_{n|n-1} \gets \QQ_n\SSi_{n-1|n-1}\QQ_n' + \RR_n$
        \State \textbf{return} $\mmu_{n|n-1}, \SSi_{n|n-1}$ % \Comment{Predicted mean and variance: $\E[\XX_n \mid \ZZ_{0:n-1}], \var[\XX_n \mid \ZZ_{0:n-1}]$}
        \EndProcedure
        % \LeftComment{Perform the update step.}
        \Procedure{\kupdate}{$\mmu_{n|n-1}, \SSi_{n|n-1}, \ZZ_n, \aa_n, \WW_n, \VV_n$} % \Comment{Perform the update step.}
        \State $\AA_n \gets \SSi_{n|n-1} \WW_n'[\WW_n\SSi_{n|n-1} \WW_n' + \VV_n]^{-1}$
        \State $\mmu_{n|n} \gets \mmu_{n|n-1}+\AA_n(\ZZ_n - \WW_n\mmu_{n|n-1} - \aa_n)$
        \State $\SSi_{n|n} \gets \SSi_{n|n-1} - \AA_n \WW_n\SSi_{n|n-1}$
        \State \textbf{return} $\mmu_{n|n}, \SSi_{n|n}$ % \Comment{Updated mean and variance: $\E[\XX_n \mid \ZZ_{1:N}], \var[\XX_n \mid \ZZ_{1:N}]$}
        \EndProcedure
        % \LeftComment{Perform the smoothing step.}
        \Procedure{\ksmooth}{$\mmu_{n+1|N}, \SSi_{n+1|N}, \mmu_{n|n}, \SSi_{n|n}, \mmu_{n+1|n}, \SSi_{n+1|n}, \QQ_{n+1}$} % \Comment{Perform the smoothing step.}
        \State $\AA_n \gets \SSi_{n|n}\QQ_{n+1}'\SSi_{n+1|n}^{-1}$
        \State $\mmu_{n|N} \gets \mmu_{n|n} + \AA_n(\mmu_{n+1|N} - \mmu_{n+1|n})$
        \State $\SSi_{n|N} \gets \SSi_{n|n} + \AA_n(\SSi_{n+1|N} - \SSi_{n+1|n}) \AA_n'$
        \State \textbf{return} $\mmu_{n|N}, \SSi_{n|N}$ % \Comment{Smoothing mean and variance: $\E[\XX_n \mid \ZZ_{1:N}], \var[\XX_n \mid \ZZ_{1:N}]$}
        \EndProcedure
        % \LeftComment{Perform the sampler smoothing step.}
        \Procedure{\ksample}{$\XX_{n+1}, \mmu_{n|n}, \SSi_{n|n}, \mmu_{n+1|n}, \SSi_{n+1|n}, \QQ_{n+1}$} % \Comment{Perform the sampler smoothing step.}
        \State $\AA_n \gets \SSi_{n|n}\QQ_{n+1}'\SSi_{n+1|n}^{-1}$
        \State $\tilde{\mmu}_{n|N} \gets \mmu_{n|n} + \AA_n(\XX_{n+1} - \mmu_{n+1|n})$ \Comment{$\tilde{\mmu}_{n|N} = \E[\XX_n \mid \XX_{n+1:N}, \ZZ_{1:N}]$}
        \State $\tilde{\SSi}_{n|N} \gets \SSi_{n|n} - \AA_n\QQ_{n+1}\SSi_{n|n}$ \Comment{$\tilde{\SSi}_{n|N} = \var[\XX_n \mid \XX_{n+1:N}, \ZZ_{1:N}]$}
        \State $\XX_n \sim \N(\tilde{\mmu}_{n|N}, \tilde{\SSi}_{n|N})$
        \State \textbf{return} $\XX_n$
        % \State \textbf{return} $\tilde{\mmu}_{n|N}, \tilde{\SSi}_{n|N}$ % \Comment{Smoothing sampler mean and variance: $\E[\XX_n \mid \XX_{n+1}, \ZZ_{1:N}], \var[\XX_n \mid \XX_{n+1}, \ZZ_{1:N}]$}
        \EndProcedure
        % \LeftComment{Perform the forecast step.}
        \Procedure{\kforecast}{$\mmu_{n|n-1}, \SSi_{n|n-1}, \aa_n, \WW_n, \VV_n$} % \Comment{Perform the forecast step.}
        \State $\lla_{n|n-1} \gets \WW_n \mmu_{n|n-1} + \aa_n$ \Comment{$\lla_{n|n-1} = \E[\ZZ_n \mid \ZZ_{1:n-1}]$}
        \State $\OOm_{n|n-1} \gets \WW_n \mmu_{n|n-1} \WW_n' + \VV_n$ \Comment{$\OOm_{n|n-1} = \var[\ZZ_n \mid \ZZ_{1:n-1}]$}
        \State \textbf{return} $\lla_{n|n-1}, \OOm_{n|n-1}$ 
        \EndProcedure
%        \LeftComment{Compute the parameters for the Markov chain going backwards in time.}
        \Procedure{\kcond}{$\mmu_{n|n}, \SSi_{n|n}, \mmu_{n+1|n}, \SSi_{n+1|n}, \QQ_{n+1}$}
        \State $\AA_n \gets \SSi_{n|n}\QQ_{n+1}'\SSi_{n+1|n}^{-1}$
        \State $\bb_n \gets \mmu_{n|n} - \AA_n \mmu_{n+1|n}$
        \State $\CC_n \gets \SSi_{n|n} - \AA_n \QQ_n \SSi_{n|n}$
        \State \textbf{return} $\AA_n, \bb_n, \CC_n$ \Comment{$\XX_n \mid \XX_{n+1} \sim \N(\AA_n \XX_{n+1} + \bb_n, \CC_n)$}
        \EndProcedure
    \end{algorithmic}
\end{algorithm}


\section{DALTON for Non-Gaussian Measurements}\label{sec:daltonng}


In the case of the general measurement model~\eqref{eq:meas}, which we write as
\begin{equation}\label{eq:nongmeas}
    \YY_i \ind \exp\{-g_i(\YY_i \mid \xobs_{n(i)}, \pph)\},
\end{equation}
where $\xobs_{n(i)} = \DD_i \XX_{n(i)}$ and $\xun_{n(i)}$ denote observed and unobserved components of $\xx(t)$ at time $t = t_i'$, such that \mbox{$\pdv{\xun_{n(i)}} p(\YY_i \mid \xx_{n(i)}, \pph) = \bz$} and $\DD_i$ is a mask matrix of zeros and ones. In order to compute the likelihood~\eqref{eq:likepar}, omitting the dependence on $\TTh$ we consider the identity,
\begin{equation}\label{eq:nongdec}
    \begin{aligned}
        & \phantom{\;=\;} p(\YY_{0:M} \mid \ZZ_{1:N} = \bz) =  \frac{p(\YY_{0:M}, \XX_{1:N} \mid \ZZ_{1:N} = \bz)}{p(\XX_{1:N} \mid \YY_{0:M}, \ZZ_{1:N} = \bz)} \\
        & = \frac{p(\XX_{1:N} \mid \ZZ_{1:N} = \bz) \times \prod_{i=0}^M \exp\{-g_i(\YY_i \mid \xobs_{n(i)})\}}{p(\XX_{1:N} \mid \YY_{0:M}, \ZZ_{1:N} = \bz)},
    \end{aligned}
\end{equation}
which holds for any value of $\XX_{0:N}$. The numerator of~\eqref{eq:nongdec} $p(\XX_{1:N} \mid \ZZ_{1:N} = \bz)$ can be approximated using the Kalman smoothing algorithm applied to the data-free surrogate model~\eqref{eq:pmi}, whereas the product term is obtained via straightforward calculation of~\eqref{eq:nongmeas}. As for the denominator of~\eqref{eq:nongdec}, we propose to approximate it by a multivariate normal distribution which after simplifications gives the model
\begin{equation}\label{eq:pgauss}
    \begin{aligned}
        \XX_{n+1} \mid \XX_n & \sim \N(\QQ_\eet \XX_n, \RR_\eet) \\
        \ZZ_n & \ind \N(\dot \xx_n - \ff_\tth(\xx_n, t_n), \VV) \\
        \hat \YY_i & \ind \N(\xobs_{n(i)}, [\nabla^2 h_i(\hxobs_{n(i)})]^{-1}).
    \end{aligned}
\end{equation}
where $h_i(\xobs) = g_i(\YY_i \mid \xobs, \pph)$ is a short-hand notation, $\nabla h_i$ and $\nabla^2 h_i$ are the gradient and Hessian of $h_i$ respectively, and $\hat \YY_i = \hxobs_{n(i)} - \nabla^2 h_i(\hxobs_{n(i)})^{-1}\nabla h_i(\hxobs_{n(i)})$. We may now augment the surrogate model~\eqref{eq:pmi} exactly as in Gaussian setting of Section~\ref{sec:dalton} to obtain an estimate of $p_\L(\XX_{1:N} \mid \hat \YY_{0:M}, \ZZ_{1:N} = \bz)$ by the Kalman smoother. To complete the algorithm, there remains the choice $\XX_{0:N}$ to plug into~\eqref{eq:nongdec}, and the choice of $\hxobs_{n(i)}$ in~\eqref{eq:pgauss}.  For the latter, we use
% \begin{equation}
$\hxobs_{n(i)} = \E_\L[\xobs_{n(i)} \mid \hat \YY_{0:i-1}, \ZZ_{1:n(i)-1} = \bz]$, 
% \end{equation}
the predicted mean of the surrogate model obtained from~\eqref{eq:pgauss}.  For the former, we use
$\XX_{0:N} = \E_\L[\XX_{0:N} \mid \hat \YY_{0:M}, \ZZ_{1:N} = \bz]$, the Kalman smoother mean of $p_\L(\XX_{1:N} \mid \hat \YY_{0:M}, \ZZ_{1:N} = \bz)$. For full details, please see~\cite{wu.etal24}.

\begin{algorithm}[!htb]
    \caption{\dalton probabilistic ODE likelihood approximation for non-Gaussian measurements.}\label{alg:daltonng}
    \begin{algorithmic}[1]
        \Procedure{\code{daltonng}}{}$\left(
        \begin{aligned}
          & \WW = \WW_\tth, \quad \ff(\XX, t) = \ff_\tth(\XX, t), \quad \vv = \vv_\tth, \\
          & \QQ = \QQ_\eet, \quad \RR = \RR_\eet, \\
          & \YY_{0:M}, \quad \DD_{0:M}, \qquad \gg_{0:M}(\YY, \XX) = \gg_{0:M}(\YY, \XX, \pph)
        \end{aligned}
      \right)$
        \State $\mmu_{0|0}, \Sigma_{0|0} \gets \vv, \bz$ \Comment{Initialization}
        \State $\ZZ_{1:N} \gets \bz$
        \State $\ell_{xz}, \ell_{xyz}, \ell_y \gets 0, 0, 0$
        \State $i \gets 0$ \Comment{Used to map $t_n$ to $t'_i$}
        \State \Comment{Lines 7-23 compute $\log p(\XX_{1:N} \mid \hat \YY_{0:M}, \ZZ_{1:N}=\bz, \TTh)$}
        \For{$n=1:N$} 
        \State $\mmu_{n|n-1}, \SSi_{n|n-1} \gets \kbpredict(\mmu_{n-1|n-1}, \SSi_{n-1|n-1}, \bz, \QQ, \RR)$
        \State $\aa_n, \BB_n, \VV_n \gets \inter(\mmu_{n|n-1}, \SSi_{n|n-1}, \WW, \ff(\XX, t_n))$
        \If{$t_n = t_{n(i)}$}
        \State $\gg_{(1)} \gets \pdv{\xobs_{n(i)}} g_i(\YY_i, \DD_i \mmu_{n|n-1})$
        \State $\gg_{(2)} \gets \pdv{}{\xobs_{n(i)}}{\xobs_{n(i)}'} g_i(\YY_i, \DD_i \mmu_{n|n-1})$
%        \State $\DD_i \gets \mcode{where}(\gg_{(2)} \neq 0)$ \Comment{Mask matrix for which elements in Hessian is not 0
        \For{$k=1:d$}
        \State $\hat \YY_i^{(k)} \gets \DD_i^{(k)}\mmu_{n|n-1}^{(k)} - {\gg_{(2)}^{-1}}^{(k)}\gg_{(1)}^{(k)}$ \Comment{Compute pseudo-observations}
        \State $\ZZ_n ^{(k)}\gets  \begin{bmatrix}
            \ZZ_n^{(k)} \\
            \hat \YY_i^{(k)}
        \end{bmatrix}, \qquad
        \WW^{(k)} \gets \begin{bmatrix} 
            \WW \\
            \DD_i^{(k)}
        \end{bmatrix}, \qquad
        \BB_n^{(k)} \gets \begin{bmatrix}
            \BB_n^{(k)} \\
            \bz
        \end{bmatrix}$
        \State $\aa_n^{(k)} \gets \begin{bmatrix}
            \aa_n^{(k)} \\
            \bz
        \end{bmatrix}, \qquad
        \VV_n^{(k)} \gets \begin{bmatrix}
            \VV_n^{(k)} & \bz \\
            \bz & {-\gg_{(2)}^{-1}}^{(k)}
        \end{bmatrix}$
        \EndFor
        \State $i \gets i + 1$
        \EndIf
        \State $\mmu_{n|n}, \SSi_{n|n} \gets \kbupdate(\mmu_{n|n-1}, \SSi_{n|n-1}, \ZZ_n, \aa_n, \WW +\BB_n, \VV_n)$ 
        \EndFor
        \For{$n=N-1:1$} 

        \State $\mmu_{n|N}, \SSi_{n|N} \gets \kbsmooth(\mmu_{n+1|N}, \SSi_{n+1|N}, \mmu_{n|n}, \SSi_{n|n}, \mmu_{n+1|n}, \SSi_{n+1|n}, \QQ)$
        \State $\mmu_n, \SSi_n \gets \kbsample(\mmu_{n+1|N}, \mmu_{n|n}, \SSi_{n|n}, \mmu_{n+1|n}, \SSi_{n+1|n}, \QQ)$
        \State $\ell_{xyz} \gets \ell_{xyz} + \nlogpdf(\mmu_{n|N}; \mmu_n, \SSi_n)$
        \EndFor
        \State $\ell_{xyz} \gets \ell_{xyz} + \nlogpdf(\mmu_{N|N}; \mmu_{N|N}, \SSi_{N|N})$
        \State \Comment{Lines 25-34 compute $\log p(\XX_{1:N} \mid \ZZ_{1:N}=\bz, \TTh)$}
        \State $\ZZ_{1:N} \gets \bz$ \Comment{Reset $\ZZ_{1:N} =\bz$}
        \State $\mmu'_{0:N|N} \gets \mmu_{0:N|N}$ \Comment{Store $\mmu_{0:N|N} = \E[\XX_{0:N} \mid \ZZ_{1:N}, \hat \YY_{0:N}]$ for later}
        \For{$n=1:N$}
        \State $\mmu_{n|n-1}, \SSi_{n|n-1} \gets \kbpredict(\mmu_{n-1|n-1}, \SSi_{n-1|n-1}, \bz, \QQ, \RR)$
        \State $\aa_n, \BB_n, \VV_n \gets \inter(\mmu_{n|n-1}, \SSi_{n|n-1}, \WW, \ff(\XX, t_n))$
        \State $\mmu_{n|n}, \SSi_{n|n} \gets \kupdate(\mmu_{n|n-1}, \SSi_{n|n-1}, \ZZ_n, \aa_n, \WW + \BB_n, \VV_n$
        \EndFor
        \For{$n=N-1:1$}
        \State $\mmu_n, \SSi_n \gets \kbsample(\mmu'_{n+1|N}, \mmu_{n|n}, \SSi_{n|n}, \mmu_{n+1|n}, \SSi_{n+1|n}, \QQ)$
        \State $\ell_{xz} \gets \ell_{xz} + \nlogpdf(\mmu'_{n|N}; \mmu_n, \SSi_n)$
        \EndFor
        \State $\ell_{xz} \gets \ell_{xz} + \nlogpdf(\mmu'_{N|N}; \mmu_{N|N}, \SSi_{N|N})$
        \State \Comment{Lines 36-37 compute $\log p(\YY_{0:M} \mid \XX_{0:N}, \pph)$}
        \For{$i=0:M$} 
        \State $\ell_y \gets \ell_y + g_i(\YY_i, \DD_i\mmu'_{n(i)|N})$
        \EndFor
        \State 
        \State \textbf{return} $\ell_{xz} - \ell_y - \ell_{xyz}$ \Comment{Estimate of $\log p(\YY_{0:M} \mid \ZZ_{1:N} = \bz, \TTh)$}
        \EndProcedure
        % \algstore{daltonng}
    \end{algorithmic}
\end{algorithm}

