\section{Hopf algebra's definition}

\subsection{Hopf algebras and integrals}

We begin by establishing the conventions on Hopf algebras that will be used throughout this work.

Let $H = (H, \eta, m, \epsilon, \Delta)$ be a finite-dimensional Hopf algebra over a field $\korps$, with bijective antipode $S$, and unit map $\eta: \korps \to H$ defining the unit element $1_H := \eta(1) \in H$.
For every $n \in \mathbb{N}$, we denote by $\Delta^{(n)} : H \to H^{\otimes n}$ the iteration of the coproduct defined recursively by $\Delta^{(0)} = \epsilon$, $\Delta^{(1)} = \Id_H$ and $\Delta^{(n+1)} = (\Id^{\otimes (n-1)} \otimes \Delta) \circ \Delta^{(n)}$ for $n \geq 1$. 
We will always use Sweedler’s notation for the coproduct,
\begin{equation}
\Delta^{(n)}(x) = x_{(1)} \otimes \cdots \otimes x_{(n)} \label{Not:Sweedler}
\end{equation}
that hides the summation symbol.

A map $f$ will occasionally be written as $f(\varspadesuit)$, where $\varspadesuit$ denotes the argument. 
We denote by $\tau : H \otimes H \to H \otimes H$ the map $ : a \otimes b \mapsto b \otimes a$.

We recall some standard definitions on Hopf algebras (see \cite{RadHA} and \cite{GPP} for more details).

\begin{defi}
\begin{itemize}
\item A right (resp. left) \emph{integral} on $H$ is an element $\lambda \in H^*$ such that
$$ \lambda(x_{(1)})x_{(2)} = \lambda(x) 1_H \qquad (\text{resp. } x_{(1)}\lambda(x_{(2)}) = \lambda(x) 1_H), $$
for all $x \in H$.

\item A left (resp. right) \emph{cointegral} in $H$ is an element $\Lambda \in H$ such that
$$ x \Lambda = \epsilon(x) \Lambda \qquad (\text{resp. } \Lambda x  = \epsilon(x) \Lambda), $$
for all $x \in H$.

\item A \emph{group-like} element in $H$ is an element $g \in H$ satisfying $\Delta (g) = g \otimes g$ and $\epsilon(g) = 1$.
\end{itemize}
\end{defi}

It follows from the definition that a group-like element $g$ is invertible and satisfies $S(g) = g^{-1}$.


\begin{defi}

\begin{itemize}
\item Let $\Lambda$ be a nonzero left cointegral of $H$. 
There exists a group-like element $\alpha \in H^*$ determined by the relation  
$$ \Lambda v = \alpha(v) \Lambda, $$
for all $v \in H$. 
We call $\alpha$ the \emph{$H$-distinguished group-like element of $H^*$}. 

\item Let $\lambda$ be a nonzero right integral of $H$.
There exists a group-like element  $a \in H$ determined by the relation
$$ f \lambda = f(a) \lambda, $$
for all $f \in H^*$. 
We call $a$ the \emph{$H$-distinguished group-like element of $H$}. 
\end{itemize}
\end{defi}

Since $H$ is finite-dimensional, there is a unique (up to a scalar) right integral and left cointegral.
Therefore, the distinguished group-like elements $\alpha$ and $a$ are independent from the choice of $\Lambda$ and $\lambda$. 
From now on, we fix a right integral $\lambda \in H^*$ and a left cointegral $\Lambda \in H$ such that $\lambda(\Lambda)=1$. 


\begin{defi}
A Hopf algebra $H$ is said to be \emph{unimodular} if it is finite-dimensional and if left cointegrals are also right cointegrals.
\end{defi}

\Rq Saying that $H$ is unimodular is equivalent to having $\alpha = \epsilon$. 
\vspace{5pt} 

\Rq \cite{RadHA}  If $H$ is unimodular, then $\lambda$ is a quantum character, i.e., $\lambda(xy) = \lambda(S^2(y)x)$ for all $x, y \in H$. 
In particular, $\lambda \circ S^2 = \lambda$. 
\vspace{5pt}


\begin{defi}
\begin{itemize}
\item A Hopf algebra $H$ with antipode $S$ is called \emph{pivotal} with pivot $g \in H$ if $g$ is a group-like element such that $ \forall x \in H, S^2(x) = gxg^{-1}$. 

\item A Hopf algebra is called \emph{spherical} if it is pivotal and unimodular (hence finite-dimensional), with its pivot $g$ satisfying $g^2 = a$. 
\end{itemize}

\end{defi}


\Rq In the spherical case, we have the equality $\lambda \circ S = \lambda (g^2 \varspadesuit)$ (direct consequence of \cite[Th. 10.5.4]{RadHA}). 
\vspace{5pt}

\begin{defi}
A \emph{symmetrized integral} in a pivotal Hopf algebra $H$ is a linear form $\mu$ satisfying:
\begin{enumerate}
\item $(\mu \otimes g)\Delta(x) = \mu(x)1_H$ for all $ x \in H$,
\item $\mu(xy) = \mu(yx)$ for all $x, y \in H$,
\item $\mu(S(x))= \mu(x)$ for all $x \in H$. 
\end{enumerate}
\end{defi}


\begin{propo}
Let $H$ be a spherical Hopf algebra and $\lambda$ a right integral. 
 Then the linear form $\mu \in H^*$ defined by $\mu := \lambda(g \varspadesuit)$ is a symmetrized integral.
\end{propo}

\begin{proof}

For all $x \in H$, by the definition of a right integral, we have
$$ \mu(x)1_H = \lambda(gx) 1_H = \lambda((gx)_{(1)})(gx)_{(2)} = \lambda(gx_{(1)}) gx_{(2)} = (\mu \otimes g) \Delta(x). $$
Thus, equality $1.$ is verified. 

In the unimodular case, by properties of right integrals and the definition of $g$ as the pivot, for all $x, y \in H$ we have
$$ \mu(xy) = \lambda(gxy) = \lambda(S^2(y)gx) = \lambda(gyx) = \mu(yx) $$
Thus, equality $2.$ is verified. 

Since $g$ is group-like, in particular $S(g) = g^{-1}$ and $S(g^{-1}) = g$. 
Therefore, for all $x \in H$, we have
$$ \mu(S(x)) = \lambda(gS(x)) = \lambda(S(xg^{-1})) = \lambda(g^2 x g^{-1}) = \lambda(gx) = \mu(x), $$
due to the properties of right integrals in the unimodular and spherical case.
Thus, equality $3.$ is verified.  
\end{proof}

From now on, we will consider the symmetrized integral defined by $\mu:= \lambda(g \varspadesuit)$.  

\begin{defi}
A Hopf algebra $H$ is called \emph{quasitriangular} if it admits an invertible element $R \in H \otimes H$, denoted $R = \sum^n_{i=1} r_i \otimes s_i$, satisfying
\begin{enumerate}
\item $\sum^n_{i=1} \Delta(r_i) \otimes s_i = \sum^n_{i,j=1} r_i \otimes r_j \otimes s_i s_j $,
\item $\sum^n_{i=1} r_i \otimes \Delta(s_i) = \sum^n_{i,j=1} r_j r_i \otimes s_i \otimes s_j, $
\item $ \tau \circ \Delta(h) R = R \Delta(h).$
\end{enumerate}
This element $R$ is called the $R$-matrix of $H$. 
To alleviate the notations, we will sometimes leave the summation implicit and write $R = r \otimes s$ (or $R= r_i \otimes s_i$ to keep track of the pairing between $r$ and $s$ when multiple iterations of $R$ appear). 
\end{defi}

The element $u := \sum_{i=1}^n S(s_i) r_i \in H$ is called the Drinfeld element.
It is invertible and satisfies, for all $h \in H$, $S^2(h) = u h u^{-1}$ and $uS(u) = S(u)u \in Z(H)$. 

\begin{defi}
A quasitriangular Hopf algebra $H$ is called \emph{ribbon} if it admits an element $\theta \in Z(H)$, called the ribbon element, satisfying the following equations
$$ \theta^{-2} = uS(u), \qquad S(\theta) = \theta, \qquad \epsilon(\theta) = 1, \qquad \Delta(\theta) = (\sum_{i,j} s_j r_i \otimes r_j s_i)(\theta \otimes \theta). $$ 
The algebra is then pivotal with pivot element $g = u \theta$ (more details in the proof of \cite[Prop 12.3.6]{RadHA}).
\end{defi}

An equivalent definition in the case of a pivotal structure is given as follows (see \cite{GPP}). 

\begin{defi}[Equivalent definition, \cite{GPP}]
A quasitriangular pivotal Hopf algebra $H$ is called \emph{ribbon} if the element $\theta := m(\tau((g \otimes 1_H)R))$ satisfies
$$ \theta = m((1_H \otimes g^{-1})R).$$
\end{defi}

\Rq Since $(S \otimes S)(R) = R$, this definition is equivalent to requiring that $\theta$ satisfies  $S(\theta) = \theta$. 
\vspace{5pt}

\begin{propo} \label{PivotalEnrubanné}
An unimodular, quasitriangular, pivotal Hopf algebra $H$ is ribbon if and only if it is spherical.
\end{propo}

\begin{proof}
If a Hopf algebra $H$ is unimodular, then $a = u S(u^{-1})$, with $a$ the distinguished group-like element of $H$ (see \cite[Th 12.3.3.b]{RadHA}). 


Let us define $\theta := m(\tau((g \otimes 1_H)R))$. 
Then it can be seen that $u= \theta^{-1} g$, and thus, that $\theta \in Z(H)$. 

Let us assume that $H$ is ribbon. 
Since $\theta = S(\theta)$ and $g$ is a pivot for $H$, we compute 
$$a = uS(u^{-1}) = S(u^{-1})u = \theta g  \theta^{-1} g = g \theta \theta^{-1} g = g^2. $$

Thus, $H$ is spherical. 

Conversely, let us assume that $H$ is spherical. 
Then, 
\begin{align*}
& \qquad u S(u^{-1}) = \theta^{-1} g^2 S(\theta) \\
\iff &\qquad a = \theta^{-1} g^2 S(\theta) \\
\iff &\qquad \theta g^2 = g^2 S(\theta) \\
\iff &\qquad g^2 \theta = g^2 S(\theta) \\
\iff &\qquad \theta = S(\theta) 
\end{align*}

Thus, $H$ is ribbon. 
\end{proof}


\textit{Example of a spherical Hopf algebra:}

The small quantum group $U_q = \overline{U_q(\mathfrak{sl}(2))}$ (with $q$ a $2r$-th root of unity) is the algebra generated by $E, F, K, K^{-1}$ together with the relations:
$$ K^r = 1, \quad E^r = F^r = 0, \quad (r \in \mathbb{N}) $$
$$ K K^{-1} = K^{-1} K = 1, $$
$$  KE = q^2 EK,  \quad \quad KF = q^{-2} FK,$$
$$ [E,F] = \frac{K - K^{-1}}{q- q^{-1}} $$

The following theorem gives its structure as a vector space. 
(A demonstration of this theorem and more details about $U_q$ can be found in \cite{Kassel}.)

\begin{theorem}[Poincaré-Birkhoff-Witt] 
\hfill

    The set $\{ K^m E^n F^l\}_{ m,n,l \in \{0, ..., r-1\}}$ is a basis of $U_q$. 
\end{theorem}

The following relations give $U_q$ a structure as a Hopf algebra. 
$$ \Delta (K)= K \otimes K, \quad \Delta(K^{-1}) = K^{-1} \otimes K^{-1} $$
$$ \Delta (E) = 1 \otimes E + E \otimes K, \quad \Delta (F) = K^{-1} \otimes F + F \otimes 1, $$
$$ \epsilon(E) = \epsilon (F) = 0, \quad \epsilon(K) = \epsilon(K^{-1}) = 1, $$
$$ S(K) = K^{-1}, \quad S(K^{-1})= K, \quad S(E) = -E K^{-1}, \quad S(F) = -K F. $$

Furthermore, it can be seen that $S^2(x) = K x K^{-1}$, thus, $g = K$ can be chosen as pivot of $U_q$. 

Let $c \in \korps$ be an invertible constant, a right integral of $U_q$ is defined, on the previously mentioned basis of $U_q$, by 
    $$ \lambda(K E^{r-1} F^{r-1})  = \frac{r}{c}, \quad \text{ and } \quad \lambda(K^m E^n F^l) = 0 \text{ si }(m,n,l) \not =  (1, r-1, r-1) $$
and a cointegral $\Lambda$ is given by
$$ \Lambda = c(\frac{1}{r} \sum^{r-1}_{j=0} K^j)E^{r-1}F^{r-1}. $$
We can note that $\lambda(\Lambda) = 1$ (more details in \cite{CGHP}).

From $\lambda$, we get the symmetrized integral $\mu$, defined by
  $$ \mu(E^{r-1} F^{r-1})  = \frac{r}{c}, \quad \text{ and } \quad \mu(K^m E^n F^l) = 0 \text{ si }(m,n,l) \not =  (0, r-1, r-1).$$


\subsection{Drinfeld double}\label{PartDoubleDrinfeld}

We consider the finite-dimensional Hopf algebra $H^{*,\mathrm{cop}}$ defined from $H$ by $H^{*,\mathrm{cop}} := (H^*)^{\mathrm{cop}} = (H^*, { }^t\epsilon, { }^t\Delta, { }^t\eta, { }^tm^{\mathrm{op}})$ with antipode ${ }^t(S^{-1})$.
Here, ${ }^tm^{\mathrm{op}}$ is the map defined by $(m^{\mathrm{op}}(f))(x \otimes y) = f(yx),$ for all $f \in H^*$ and all $x, y \in H$. 
The map ${ }^t \Delta : H^* \otimes H^* \to H^*$ is defined through the identification $(H \otimes H)^*=H^* \otimes H^*$ by $({ }^t \Delta(f \otimes g))(x) = f(x_{(1)}) \otimes g(x_{(2)})$, for all $x \in H$ and all $f, g \in H^*$. 

\emph{Structure on $D(H)$ : }
Following the conventions of \cite{Chang_Cui} and \cite{RadHA}, the Drinfeld double $D(H) = H^{*\mathrm{cop}} \otimes H$ of a finite-dimensional Hopf algebra $H$ is a quasitriangular Hopf algebra with the structure given below.

For all $f \in (H^*)^{\mathrm{cop}}$ and all $v \in H$, we have

$$ 1^D = \epsilon \otimes 1_H, \qquad \epsilon^D = 1_H \otimes \epsilon, \qquad \Delta^D = (f_{(1)} \otimes x_{(1)}) \otimes (f_{(2)} \otimes x_{(2)}), $$
$$ M^D(f \otimes v, f' \otimes v') = (f f'(S^{-1}(v_{(3)}) \varspadesuit v_{(1)}) \circ \Delta \otimes v_{(2)}v',$$
$$ S^D(f \otimes v) = M^D(\epsilon \otimes S(v) , f \circ S^{-1} \otimes 1) = f \circ S^{-1}(v_{(3)} \varspadesuit S(v_{(1)})) \otimes S(v_{(2)}).$$

Let $(e_1, ..., e_n)$ be a basis of $H$ and $(e^*_1, ..., e^*_n)$ the dual basis of $H^{*,\mathrm{cop}}$, we can make explicit the $R$-matrix of $D(H)$ by
$$ R^D := \sum^n_{i = 1} (\epsilon \otimes e_i) \otimes (e^*_i \otimes 1_H) $$
and its inverse by 
$$ (R^D)^{-1} := \sum^n_{i = 1} (\epsilon \otimes S(e_i)) \otimes (e^*_i \otimes 1_H). $$

From now on, we denote the multiplication in the double by $(f \otimes v)( f' \otimes v') := M^D(f \otimes v, f' \otimes v')$. 
It can be noted, by direct calculation, that $(f \otimes 1_H)( f' \otimes v') = f f' \otimes v'$ and $(f \otimes v)( \epsilon \otimes v') = f \otimes v v'$, for all $(f \otimes v), ( f' \otimes v') \in D(H)$. 


\begin{propo}\cite[Th 13.2.1]{RadHA} 
The Drinfeld double $D(H) = H^{* \mathrm{cop}} \otimes H$ of a finite-dimensional Hopf algebra $H$ is an unimodular Hopf algebra (for it is both quasitriangular and factorizable).
\end{propo}

As with the structure maps of $D(H)$, we can define a right integral and a $D(H)$-distinguished group-like element based on those previously established on $H$, 
$$ \lambda^D := \Lambda \otimes \lambda \qquad \text{ and } \qquad a^D = \alpha \otimes a,$$
(see \cite[Part. 2.4]{Chang_Cui} and \cite[Part 13.7]{RadHA}).

\begin{lemme}\cite[Lemma 13.7.2]{RadHA}\label{Lemmeg_D}
Let $H$ be a finite-dimensional Hopf algebra over a field $\korps$, and let $a$ and $\alpha$ be the $H$-distinguished and $H^*$-distinguished group-like elements, respectively. 
Then, for any pair $(\beta , b) \in H^* \times H$ such that
\begin{itemize}
\item $\beta$ and $b$ are group-like elements, 
\item $\beta^{-2} = \alpha$, $b^{-2} = a$, and 
\item $S^2(h)= b^{-1}(\beta(h_{(1)})h_{(2)} \beta^{-1}(h_{(3)}))b $, for all $h \in H$,
\end{itemize} 
the element $(\beta \otimes b)^{-1}$ is a pivot of $D(H)$.  
\end{lemme}

When $H$ is spherical (and so, unimodular), we have $\alpha= \epsilon$ and $g^2 = a$. 
Therefore, the following proposition can be deduced from the lemma. 

\begin{propo}\label{g_D}
Let $H$ be a spherical Hopf algebra with $g$ as its pivot. 
Then its Drinfeld double $D(H)$ is also spherical with $g^D:= \epsilon \otimes g$ as its pivot. 
\end{propo}

\begin{proof}
First, let us show that the pair $(\epsilon, g^{-1})$ satisfies the assumptions of Lemma \ref{Lemmeg_D}. 

By definition, $g$ and $\epsilon$ are group-like, therefore, $g^{-1}$ also is. 
Since $H$ is spherical and unimodular, we have that $\alpha= \epsilon$ and $g^2 = a$. 

It remains to verify that $S^2(h)= g(\epsilon^{-1}(h_{(1)})h_{(2)} \epsilon(h_{(3)}))g^{-1} $ for all $h \in H$.
However, by the definition of $\epsilon$ and of the pivot $g$, we have
$$ g(\epsilon^{-1}(h_{(1)})h_{(2)} \epsilon(h_{(3)}))g^{-1} = ghg^{-1} = S^2(h),$$ 
for all $h \in H$.
Therefore, $g^D=(\epsilon \otimes g^{-1})^{-1}$ can be set as pivot of $D(H)$.

As mentioned earlier, by direct calculation we have $(\epsilon \otimes g^{-1}) (\epsilon \otimes g) = \epsilon \otimes 1_H$. 
Therefore $(\epsilon \otimes g^{-1})^{-1} = \epsilon \otimes g$. 

Furthermore, since $H$ is spherical, we note that 
$$ (g^D)^2 = (\epsilon \otimes g)(\epsilon \otimes g) = \epsilon \otimes g^2 = \epsilon \otimes a = a^D. $$ 
Thus, $D(H)$ is also spherical.
\end{proof}

We can argue similarly that, if a pair $(\beta , b) \in H^* \times H$ as described in Lemma \ref{Lemmeg_D} exists, then $D(H)$ with the pivot $\beta^{-1} \otimes b^{-1}$ is spherical. 

\vspace{5pt}
\Rq Proposition \ref{g_D} allows us to express a symmetrized integral of $D(H)$ through elements of $H$ and $H^*$. 
$$ \mu^D = \lambda^D(g^D \varspadesuit) = \Lambda \otimes \mu $$

\Rq Since the Drinfeld double of a Hopf algebra is unimodular and quasitriangular (see \cite[Th 13.2.1]{RadHA}), Propositions \ref{PivotalEnrubanné} and \ref{g_D} imply that the double of a spherical Hopf algebra is also ribbon. 


\section{Computation of the $\HKR$ invariant}\label{Part:CalcHenn}


Let $M$ be a $3$-dimensional manifold and $L$ an oriented surgery link of $M$. 
Let $H$ be a finite-dimensional ribbon Hopf algebra with pivot $g$, and $\mu$ a symmetrized non-degenerate integral of $H$ (i.e. $\mu(g \theta)\mu(g^{-1} \theta^{-1}) \not = 0 \in \korps$). 
We denote $\delta := \mu ( g \theta) \in \korps$. 
In the rest of this article, we assume that $\mu$ is renormalized such that $\mu(g \theta)\mu(g^{-1} \theta^{-1}) =1 \in \korps$. 
Therefore, we will use the $\HKR$ invariant with the computational algorithm described in \cite{GPP} that we express as follows. 

\begin{itemize}
\item Let $D$ be a planar diagram of $L$ with each component admitting a base point.
For each cap, cup, and crossing, we place on $D$ the beads described in Figure \ref{fig:FoncPerleGPP}.
Each bead is colored by an element of the algebra $H$. 
Furthermore, we denote $R = r \otimes s$.
\begin{figure}[hbtp]
\centering
\includegraphics[scale=0.7]{figs/FoncteurPerle.pdf}
\caption{Beads placement (according to the conventions of \cite{GPP}) }\label{fig:FoncPerleGPP}
\end{figure}

\item Starting from the base point and following the orientation, we multiply all beads in one element, which gives an element of $H$ for each component. 
(All multiplications are performed from the left.) 
This produces an element $PT(D) \in H^{\otimes n}$ (with $n$ the number of components of $L$) which we call the total bead of $D$ (at this point, it is not an invariant of the diagram).  


\item The $\HKR$ invariant is given by the following theorem. 
\end{itemize}

\begin{theorem} \cite[Th 2.9]{GPP}
Let $H$ be a finite-dimensional Hopf algebra. 
For each manifold $M$, the scalar $ \HKR_H(M) $ is a manifold invariant defined as 
$$ \HKR_H(M) := \delta^{-s} \mu^{\otimes n}(PT(D)) \in \korps $$
where $D$ is a diagram of a surgery link of $M$, $s \in \mathbb{Z}$ is the signature of the linking matrix of $L$ and $n$ is the number of components of $L$. 

\end{theorem}

This theorem provides a reformulation of the 3-manifold invariant introduced by Hennings \cite{Hen96} and by Kauffman and Radford \cite{KR95}. 
A proof can be found in \cite[Th 2.9]{GPP} considering $G = \{ 0 \}$.  

\Rq The beads on the rightmost crossing in the Figure \ref{fig:FoncPerleGPP} are denoted $ r_i$ and $S(s_i)$ instead of $S^{-1}(r_i)$ and $s_i$ as in other references (see \cite[Part. 2.2]{GPP}).
Both conventions are equivalent because $(S \otimes S) (R) = R$. 
\vspace{5pt}


\section{The chromatic spherical invariant $\mathcal{K}$}

In this section, we fix $H$ to be a spherical Hopf algebra over a field $\korps$. 

\subsection{Virtual Heegaard diagrams}

Next, we will define what we will call \emph{virtual Heegaard diagrams}. 
Roughly speaking, these are Heegaard diagrams allowing intersection points over the $\beta$ curves. 

We assume that all mentioned curve are oriented. 

\begin{defi}[Heegaard diagrams]
We call \emph{Heegaard diagram} a triplet $D =(\Sigma_{\genre}, \alpha, \beta)$ such that

\begin{itemize}
\item $\Sigma_{\genre}$ is a closed oriented surface of genus ${\genre} \in \mathbb{N}$. 
\item $\alpha = (\alpha_1, ..., \alpha_{\genre})$ is a collection of ${\genre}$ simple closed disjoint curves.
\item $\beta = (\beta_1, ..., \beta_{\genre})$ is a collection of ${\genre}$ simple closed disjoint curves.
\item The complement of $\alpha$ and the complement of $\beta$ in $\Sigma_{\genre}$ are connected. 
\item Every intersection between two curves is transverse. 
\end{itemize}
\end{defi}

In this article, we choose to consider the curves in a Heegaard diagram as oriented, although this is not usually the case in the literature on Heegaard diagrams. 

Every Heegaard diagram defines a $3$-manifold by gluing together two handlebodies determined by the sets of curves $\alpha$ and $\beta$, with boundary the surface $\Sigma_{\genre}$ (more details in \cite[Part 2]{Ozsvath_Szabo}).  
Our interest in these diagrams stems from the following classical result (see \cite[Theorem 2.1 and Remark 2.6]{Ozsvath_Szabo}).

\begin{theorem} 
Every oriented closed $3$-manifold admits a Heegaard diagram.
\end{theorem}

In this article, we define and use a more general and abstract type of diagram encompassing Heegaard diagrams.

\begin{defi}[Virtual Heegaard diagrams]
We denote by $D^v_{He}$ the set of triplets $D =(\Sigma_{\genre}, \alpha, \beta)$ such that 

\begin{itemize}
\item $\Sigma_{\genre}$ is a closed oriented surface of genus ${\genre} \in \mathbb{N}$. 
\item $\alpha = (\alpha_1, ..., \alpha_{\genre})$ is a collection of ${\genre}$ simple closed disjoint curves.
\item $\beta = (\beta_1, ..., \beta_{\genre})$ is a collection of ${\genre}$ closed immersed curves.
\item The complement of $\alpha$ in $\Sigma_{\genre}$ is connected. 
\item  Every (self-)intersection of the curves is transverse. 
\end{itemize}

We call \emph{virtual Heegaard diagrams} the elements of $D^v_{He}$.

\end{defi}

\Rq It is clear that a regular Heegaard diagram is also a virtual Heegaard diagram. 
\vspace{5pt}

\begin{figure}[ht]
\centering
\includegraphics[scale=0.75]{figs/Stabilisation.pdf}
\caption{Stabilization on a diagram $D$ or destabilization on a diagram $D'$}\label{fig:Stabilisation}
\end{figure}

\begin{defi}

Let $D = (\Sigma_{\genre}, \alpha, \beta) \in D^v_{He}$ be a virtual Heegaard diagram. 
Let us consider the Heegaard diagram of genus $1$ of the sphere $S^3$, $(T, \alpha_0, \beta_0)$ (as represented in Figure \ref{fig:Stabilisation}). 
Let $\Sigma_{\genre}'$ be a connected sum of $\Sigma_{\genre}$ with the torus $T$ along a disk disjoint from the sets of curves $\alpha, \alpha_0, \beta$ and $\beta_0$. 
Define $\alpha' = \alpha_0 \cup \alpha$ and $\beta' = \beta_0 \cup \beta$. 
We say that the virtual Heegaard diagram $D' =  (\Sigma_{\genre}', \alpha', \beta')$ is a \emph{stabilization} of $D$.

Conversely, we say that $D$ is a \emph{destabilization} of $D'$. 
\end{defi}



\begin{figure}[ht]
\centering
\includegraphics[scale=0.5]{figs/MouvH2.pdf}
\caption{Diagrams differing by a $R_{II}$ move (here, between $\beta$ curves).}\label{fig:MouvR2}
\end{figure}

\begin{defi}
We say that two Heegaard diagrams are equivalent if we can link one to the other through a sequence of isotopies of the surface, handle-slides (of $\beta$ curves or $\alpha$ curves between themselves), stabilizations and destabilizations, type $2$ Reidemeister moves between $\beta$ and $\alpha$ curves (also called $R_{II}$ moves, see Figure \ref{fig:MouvR2}) and orientation changes on $\alpha$ and $\beta$ curves. 
\end{defi}


\begin{theorem}
Two Heegaard diagrams representing the same manifold are equivalent. 
\end{theorem}


\Rq This Theorem (more details in \cite[Theorem 2.9]{Ozsvath_Szabo}) can be seen as a direct consequence or a Corollary of Reidemeister\cite{Reidemeister}-Singer\cite{Singer}'s Theorem, for which proof can be found in \cite{Laudenbach}. 

\begin{figure}[ht]
\centering
\includegraphics[scale=0.5]{figs/MouvR_3.pdf}
\caption{$R_{III}$ move}\label{fig:MouvR_3}
\end{figure}


On virtual Heegaard diagrams, we also consider the following moves : 
\begin{itemize}
\item Handle slides of $\beta$ curves over $\alpha$ curves, 
\item Type $3$ Reidemeister moves between $\beta$ curves (also called $R_{III}$ moves (see Figure \ref{fig:MouvR_3}), 
\end{itemize}



\Rq In the rest of this article, we use the diagram representations of \cite{Chang_Cui} and described below. 
\vspace{5pt}

\begin{figure}[ht]
\centering
\includegraphics[scale=0.13]{figs/DiagHeegaardS3.pdf} 
\caption{Genus ${\genre}$ Heegaard diagram of $\mathbb{S}^3$}\label{fig:DiagHeegType}
\end{figure}

Let $\genre$ be a natural integer. 
We consider, in $\mathbb{R}^2$, $\genre$ pairs of disks $(D_i^1, D_i^2)_{1 \leq i \leq g} \subset \mathbb{R}^2$ of the same radius $< \frac{1}{3}$ and with centers $(1,i)$ and $(2,i)$, respectively.
For each pair $(D_i^1, D_i^2)$, we consider $\alpha_i$ the minimum length segment connecting $D_i^1$ and $D_i^2$, oriented from $D_i^1$ to $D_i^2$. 
We see the boundaries of these disks as curves $\gamma_i^1$ and $\gamma_i^2$, oriented such that their intersections with $\alpha_i$ verify $\alpha_i \cdot \gamma_i^1 = \alpha_i \cdot \gamma_i^2 = +1$ (see Figure \ref{fig:DiagHeegType}).

We define the \emph{geometric intersection matrix} of two families of ${\genre}$ curves, $\alpha$ and $\gamma$, with transverse intersections, as $\MatInter{\alpha}{\gamma} := \big(\# (\alpha_i \cap \gamma_j)\big)_{i,j \in \{1, ..., {\genre} \}}$. 

\begin{defi}
We say that a Heegaard diagram $(\Sigma_{\genre}, \alpha, \gamma)$ of $\mathbb{S}^3$ is \emph{standard} if $\MatInter{\alpha}{\gamma}= \Id_{\genre}$ and if all intersections between $\alpha$ and $\gamma$ are positive. 

Let $(\Sigma_{\genre}, \alpha', \gamma')$ be a standard diagram of $\mathbb{S}^3$, and let $\PtInf$ be a point on the surface $\Sigma_{\genre} \setminus (\alpha' \cup \gamma')$. 
For all $i \in \{1, ..., {\genre}\}$, let $V_i = \gamma'_i \times [-\varepsilon, \varepsilon]$ (with $\varepsilon > 0$) be a tubular neighborhood of $\gamma'_i$ with its two boundaries denoted by $\gamma'^1_i = \gamma'_i \times -\{\varepsilon\}$ and $\gamma'^2_i = \gamma'_i \times \{ \varepsilon \}$. 

A \emph{standard projection} is an orientation preserving diffeomorphism
$$\psi : \Sigma_{\genre} \setminus \big( \{ \PtInf \} \cup \underset{i \in \{1, ..., {\genre}\}}{\bigcup} \mathring{V_i} \big) \to \mathbb{R}^2  \setminus \underset{i \in \{1, ..., {\genre}\}, j \in \{1,2\}}{\bigcup} \mathring{D_i^j} $$
which sends the set of curves $\{\alpha'_i \}_{i \in \{1, ..., {\genre}\}}$ over the previously described set of curves $\{ \alpha \}_{i \in \{1, ..., {\genre}\}}$. 
This induces that the boundaries $\{ \gamma'^1_i \}_{i \in \{1, ..., {\genre}\}}$ and $ \{ \gamma'^2_i \}_{i \in \{1, ..., {\genre}\}}$ of $\Sigma_{\genre} \setminus \big( \{ \PtInf \} \cup \underset{i \in \{1, ..., {\genre}\}}{\bigcup} \mathring{V_i} \big)$ are mapped onto the boundaries $\{ \gamma^1_i \}_{i \in \{1, ..., {\genre}\}}$ and $ \{ \gamma^2_i \}_{i \in \{1, ..., {\genre}\}}$ of $\mathbb{R}^2  \setminus \underset{i \in \{1, ..., {\genre}\}, j \in \{1,2\}}{\bigcup} \mathring{D_i^j}$, respectively. 
\end{defi}

Let $\phi$ be the index permutation defined by $\psi(\alpha'_i) = \alpha_{\phi(i)}$ for all $i \in \{1, ..., {\genre}\}$.
This permutation is also the one permuting the projections of the indices of $\gamma'^1$ and $\gamma'^2$. 
Therefore, we find that $\psi((\alpha'_i, \gamma'^1_i, \gamma'^2_i)) = (\alpha_{\phi(i)}, \gamma^1_{\phi(i)}, \gamma^2_{\phi(i)})$, for all $i \in \{1, ..., {\genre}\}$. 

We can make the identification $\Sigma \setminus \gamma' \simeq \Sigma \setminus \overline{V_i}$. 
Through that identification, $\gamma'^1_i$ and $\gamma'^2_i$ represent the same curve $\gamma'_i$ of $\Sigma_{\genre}$. 
In the rest of this article, we will also use $\gamma_{\phi(i)}$ for such images obtained from a standard projection of curves $\gamma'_i$. 

\Rq In \cite{Chang_Cui} the notion of standard diagrams also appears, however, curves are non-oriented in that article. 

\begin{defi}\label{def:DiagStandardisé}
Let $D = (\Sigma_{\genre}, \alpha, \beta)$ be a virtual Heegaard diagram along with a fixed point $\PtInf \in \Sigma_{\genre} \setminus (\alpha, \beta)$. 
Let us consider a family of curves $\gamma \subset \Sigma_{\genre} \setminus \{ \PtInf \}$ such that $(\Sigma_{\genre}, \alpha, \gamma)$ is standard and that the intersections $\beta \cap \gamma$ are transverse. 
We then say that $(\Sigma_{\genre}, \alpha, \beta, \PtInf, \gamma)$ is a \emph{standardized} diagram. 
\end{defi}


\Rq For all virtual Heegaard diagrams $(\Sigma_{\genre}, \alpha, \beta)$ and all fixed points $\PtInf \in \Sigma_{\genre} \setminus (\alpha, \beta)$, there exists at least a family $\gamma \subset (\Sigma_{\genre} \setminus \{\PtInf\})$ of ${\genre}$ simple disjoint closed curves such that $\MatInter{\alpha}{\gamma} = \Id_{\genre}$. 

Indeed, the surface $\Sigma_{\genre}$ with the $\alpha$ curves removed is diffeomorphic to an open disk with $2{\genre}-1$ holes. 
We can then establish on that disk a family $\gamma \subset \Sigma_{\genre}$ of ${\genre}$ simple disjoint curves with connected complement, such that $\MatInter{\alpha}{\gamma} = \Id_{\genre}$. 

Up to changes on the orientation of some curves of $\gamma$, we can deduce from this that there always exists a family of curves $\gamma$ for which $(\Sigma_{\genre}, \alpha, \gamma)$ is standard. 
Therefore, for all virtual Heegaard diagrams $(\Sigma_{\genre}, \alpha, \beta)$, there exists at least one standardized virtual Heegaard diagram $(\Sigma_{\genre}, \alpha, \beta,\allowbreak \PtInf, \gamma)$. 


\begin{defi}
Let $(\Sigma_{\genre}, \alpha, \beta, \PtInf, \gamma)$ be a standardized virtual Heegaard diagram.
When we perform the connected sum between a curve $\beta_j$ and the boundary of a tubular neighborhood of $\gamma_i \cup \alpha_i$, $i,j \in \{1, ..., {\genre}\}$, we say that we perform a \emph{$G_{\gamma}$ move}. 
\end{defi}


\textit{Examples :}

The previously mentioned handle-slides of $\beta$ over $\alpha$, and $G_{\gamma}$ moves can be represented on the plane $\mathbb{R}^2$ by standard projections, as pictured in Figures \ref{fig:MouvGlissBA} and \ref{fig:MouvDoublGliss}, respectively. 

