\section{Preliminaries} \label{sec:preliminaries}


\subsection{Quantum unipotent coordinate rings} \label{Sec: qcr}
In this subsection, we briefly review basics of quantum groups and their quantum unipotent coordinate rings. 

\begin{definition}
A quintuple $ (\cmA,\wlP,\Pi,\wlP^\vee,\Pi^\vee) $ is called a  (symmetrizable) {\it Cartan datum} if it
consists of
 a generalized  \emph{Cartan matrix} $\cmA=(a_{ij})_{i,j\in I}$,
 a free abelian group $\wlP$,
its dual $\wlP^{\vee} := \Hom_{\Z}( \wlP, \Z )$, the set $\Pi := \{ \alpha_i \in \wlP \mid i\in I \}$ of \emph{simple roots} and the set $\Pi^{\vee} := \{ h_i \in \wlP^\vee \mid i\in I\}$ of \emph{simple coroots} such that    
 \bnum
\item $\lan h_i, \alpha_j \ran = a_{ij}$ for $i,j \in I$,
\item $\Pi$ is linearly independent over $\Q$,
\item for each $i\in I$, there exists $\Lambda_i \in \wlP$ such that $\lan h_j,\Lambda_i \ran =\delta_{j,i}$ for all $j \in I$.
\item there is a symmetric bilinear 
form $( \cdot \, , \cdot )$ on $\wlP$ satisfying 
$(\al_i,\al_i)\in\Q_{>0}$ and 
$ \lan h_i,  \lambda\ran = {2 (\alpha_i,\lambda)}/{(\alpha_i,\alpha_i)}$. 
\ee
\end{definition}


Let $\prD$  be the set of \emph{positive roots}, and define 
 $ \rlQ^+ \seteq \bigoplus_{i \in I} \Z_{\ge 0} \alpha_i$ and $\rlQ^- := -\rlQ^+ $. We write $\weyl = \langle s_i \mid i\in I \rangle$ for the \emph{Weyl group} associated with $\cmA$, where $s_i$ is the $i$th simple reflection. For $w\in \weyl$, we denote by $\rR(w)$ the set of all reduced expression of $w$, i.e.,  
\begin{align} \label{Eq: reduced ex}
\rR(w) := \{ (i_1, i_2, \ldots, i_l) \in I^t \mid w = s_{i_1} s_{i_2} \cdots s_{i_l} \}
\end{align}
where $l = \ell(w)$. When $\cmA$ is of finite type, we write $w_\circ$ for the longest element of $\weyl$. For any $w = s_{i_1}s_{i_2} \cdots s_{i_m} \in \weyl$, we set 
$$
\supp(w) := \{ i_1, i_2, \ldots, i_m \}. 
$$ 
Note that $\supp(w)$ does not depend on the choice of reduced expressions of $w$. 


Let $q$ be an indeterminate and define 
$\bfk \seteq \Q(q)$, $q_i\seteq q^{(\al_i,\al_i)/2}$ and
$$ 
[n]_{q_i}= \dfrac{q_i^n-q_i^{-n}}{q_i-q_i^{-1}}, \quad [n]_{q_i}! = \prod_{k=1}^n [k]_{q_i} \qtq
\begin{bmatrix}
n \\ m
\end{bmatrix}_{q_i} = \dfrac{[n]_{q_i}!}{[m]_{q_i}![n-m]_{q_i}!},
$$
where $i\in I$ and $n \ge m \in \Z_{\ge0}$. 
The \emph{quantum group} $U_q(\g)$ associated with the Cartan datum $(\cmA,\wlP,\Pi,\wlP^\vee,\Pi^\vee)$ is the $\bfk$-algebra
generated by $e_i,f_i$ $(i \in I)$ and $q^h$ $(h \in \wl^\vee)$ subject to certain defining relations (see \cite{HK02, LusztigBook} for details).
Let $U_q^-(\g)$ be the subalgebra of $U_q(\g)$ generated by $f_i$ $(i \in I)$ and $U_{\Zq}^-(\g)$ the $\Zq$-subalgebra of
$U_q(\g)$ generated by $f_i^{(n)} \seteq f_i^n/[n]_{q_i}!$ $(i \in I, n\in \Z_{>0})$. 
For an element $x$ in the \emph{weight space} $U_q^-(\g)_\beta$ of $U_q^-(\g)$, we write $\wt(x):=\beta \in \rlQ^-$.



The \emph{quantum unipotent coordinate ring} $\qA_q(\n)$ of $U_q(\g)$ is defined by 
$$
\qA_q(\n) \seteq \bigoplus_{\beta \in \rlQ^-} \qA_q(\n)_\beta, \quad \text{ where } \qA_q(\n)_\beta \seteq \Hom_{\bfk}(U_q^-(\g)_{\beta},\bfk),
$$
where the multiplication of $\qA_q(\n)$ is defined by using the comultiplication of $U_q(\g)$ (see \cite[Section 8]{KKKO18} for details).
There exists a distinguished basis $\Gup(\infty)$ of $\qA_q(\n)$, which is called the \emph{upper global basis} (or \emph{dual canonical basis}) of $\qA_q(\n)$. We refer the reader to \cite{K91,K93, L90, LusztigBook} and references therein for precise definitions (see also \cite[Section 8]{KKKO18}). 
We set $\qA_\Zq(\n)$ (resp.\ $\qA_{\Z[q]}(\n)$) to be the $\Zq$-lattice (resp.\ $\Z[q]$-lattice) of $\qA_q(\n)$ generated by the upper global basis $\Gup(\infty)$.
For any $\La\in \wlP^+$, $w,v \in \weyl$ with $v \le w$, we denote by 
$\qmD (w \La, v \La) \in \qA_q(\n)$ the \emph{quantum unipotent minor} associated with $w \La $ and $v\La$ (see \cite[Section 9]{KKKO18} for precise definition). Note that $\qmD (w \La, v \La)$ is contained in $\Gup(\infty)$.
For any $x, y \in \qA_q(\n) $, we write 
$$
x \eqq y \qquad \text{ if  $ x = q^t y$ for some integer $t$.}
$$
For any $A, B \subset A_q(\n)$, we write $A \eqq B $ if there is a bijection $f: A \buildrel \sim \over \rightarrow B$ such that $x \eqq f(x)$ for all $x\in A$. 



Fix $w\in \weyl$ and take $\bfi=(i_1,\ldots,i_l) \in \rR(w)$. 
We set $w_{\le 0}= 1$, $w_{\le k} := s_{i_1}s_{i_2} \cdots s_{i_k}$ and $w_{<k} := w_{\le k-1}$ for $1\le k \le l$.
Let 
\begin{align} \label{Eq: beta_k}
\beta_{\bfi, k} := w_{<k}(\al_{i_k}),
\end{align} 
and write simply $\beta_{k}= \beta_{\bfi, k}$ if no confusion arises.
The set $\prD \cap w \nrD = \{ \beta_{ k}  \ | \ 1 \le k \le l \}$ has the \emph{convex} order given by
$$
\beta_{ a} \le_{\bfi} \beta_{  b} \quad \text{ for any } a \le b.
$$ 
We denote by 
$$
\{\Fup_{\bfi}(\beta_k)\}_{k\in [1,l]} \subset \qA_q(\n)
$$ 
the set of \emph{dual PBW vectors} with respect to $\bfi$, which is the dual of the set of \emph{PBW vectors} $\{ {\mathrm{F}}_{\bfi}(\beta_k) := T_{i_1} T_{i_2} \cdots T_{i_{k-1}} (f_{i_k}) \}_{k\in [1,l]} $, where $T_i$ are Lusztig's braid symmetries $T'_{i,-1}$ in the notation of \cite[Chapter 37]{LusztigBook}. Note that, when $i\ne j$,   
\begin{equation*}
\begin{aligned}
  T_i(f_j) = \sum_{r+s = -c_{i,j}}  (-1)^{ r} q_i^{r} f_{i}^{(s)} f_{j} f_{i}^{(r)}. 
\end{aligned}
\end{equation*}
Note that the dual PBW vectors $\Fup_{\bfi}(\beta_k)$ are contained in the upper global basis $\Gup(\infty)$.
We define $\qA_q(\n(w))$ to be the $\bfk$-subalgebra of $\qA_q(\n)$ generated by the dual PBW vectors $\{\Fup_{\bfi}(\beta_k)\}_{k\in [1,l]}$.
The algebra $\qA_q(\n(w))$ does not depend on the choice of $\bfi$ and respects the upper global basis, i.e., the intersection
$$
\Gup(w) := \qA_q(\n(w)) \cap \Gup(\infty) 
$$
forms a $\bfk$-linear basis of $A_q(\n(w))$ (\cite{Kimura12}).
For any $\bfa = (a_1, a_2, \ldots, a_l) \in \Z_{\ge0}^{l}$, we define 
$$
\Fup_{\bfi} (\bfa) = 
f_{\bfi, \epsilon}^{\up} (\beta_\ell) ^{\{a_\ell\}} f_{\bfi, \epsilon}^{\up} (\beta_{\ell-1}) ^{\{a_{\ell-1}\}} \cdots 	f_{\bfi, \epsilon}^{\up} (\beta_{1}) ^{\{a_{1}\}}
$$
where $ \Fup_{\bfi}(\beta_k)^{\{a\}} := q_{i_k}^{a(a-1)/2} \Fup_{\bfi}(\beta_k)^a$ for $k\in [1,l]$. Then the set $\{ \Fup_{\bfi} (\bfa)  \}_{\bfa \in \Z_{\ge0}^{l}}$ becomes a $\bfk$-basis of $ \qA_q(\n(w))$, which is called the \emph{dual PBW basis} of $\qA_q(\n(w))$ with respect to $\bfi$. Since there is a uni-triangular property between the dual PBW basis and the upper global basis, for any element $x \in \Gup(w)$, there exists $\bfa \in \Z_{\ge0}^l$ such that 
$$
\Fup_{\bfi} (\bfa) \equiv x \qquad \mod q \qA_{\Z[q]}(\n).
$$
We write $\PBW_\bfi (x) := \bfa$, which is called the \emph{PBW datum} of $x$ with respect to $\bfi$. 


We assume that $\supp(w) = I$.
For any $i\in I$, we define the quantum unipotent minor
\begin{align} \label{Eq: frozen}
\qmC^w_{i} := \qmD ({w \La_{i}, \La_{i}} ).
\end{align}
Note that the minor $\qmC^w_{i}$ is contained in $\Gup(w)$ and it commutes with any element of $\Gup(w)$ up to a multiple of $q$. We set 
$\tqA_q(\n(w))$ to be the algebra obtained by localizing $\qA_q(\n(w))$ by the $q$-central elements $\{ \qmC^w_i \mid i\in I \}$. Then the upper global basis $\tGup (w)$ of the localized algebra $\tqA_q(\n(w))$ is determined by 
\begin{align*} 
\tGup (w) = \{ q^{a(x,\bfa)} x \cdot  \qmC^w(\bfa) \mid x \in \Gup(w),\ \bfa \in \Z^{I}  \}, 
\end{align*}
where 
\begin{align} \label{Eq: C(a)}
\qmC^w(\bfa) := \prod_{i\in I} (\qmC^w_i)^{a_i}
\end{align}
and $a(x,\bfa)$ is the integer such that $q^{a(x,\bfa)} x \cdot  \qmC^w(\bfa)$ becomes \emph{dual bar-invariant}.
We simply write $\qmC_i$ and $\qmC(\bfa)$ instead of $\qmC^w_i$ and $\qmC^w(\bfa)$ if no confusion arises.


Let $\eta_w$ be the \emph{quantum twist automorphism} on the localized algebra $\tqA_q(\n(w))$ introduced in \cite{KiOy21} (see \cite[Theorem 6.1]{KiOy21} for precise definition). 
The twist automorphism $\eta_w$ is given by 
\begin{align*}
\eta_w(\qmD (v \La, \La))  \eqq
\qmD (w \La, \La)^{-1} \qmD(w\La, v\La) \qquad 
\text{ for any $v \in \weyl$ with $v \le w$ and $\La \in \wlP^+$.}
\end{align*}
 Moreover, the twist automorphism $\eta_w$ permutes the upper global basis. 
\begin{theorem} [{\cite[Theorem 6.1]{KiOy21}}] \label{Thm: tw tGup}
The twist automorphism $\eta_w$ restricts to a permutation on $\tGup (w)$.
\end{theorem}

\subsection{Quiver Hecke algebras} \label{Sec: QHA}

 For $i,j\in I$, we choose polynomials
$\qQ_{i,j}(u,v) $ in two variables $u,v$ over a field $\bR$ such that
$\qQ_{i,j}(u,v) = \qQ_{j,i}(v,u)$ and 
\begin{align*}
\qQ_{i,j}(u,v) =\bc
                   \sum\limits
_{p(\alpha_i , \alpha_i) + q(\alpha_j , \alpha_j)=-2(\alpha_i , \alpha_j)} t_{i,j;p,q} u^pv^q &
\text{if $i \ne j$,}\\[1.5ex]
0 & \text{if $i=j$,}
\ec
\end{align*}
where $t_{i,j;-a_{ij},0} \in  \bR^{\times}$.
For $\beta\in \rlQ_+$ with $ \Ht(\beta)=n$, we set
$$
I^\beta\seteq  \left\{\nu=(\nu_1, \ldots, \nu_n ) \in I^n \mid \sum_{k=1}^n\alpha_{\nu_k} = \beta \right\}.
$$
The {\em quiver Hecke algebra} $R(\beta)$ associated with the generalized Cartan matrix $\cmA$, $\beta\in\rlQ_+$ and $(\qQ_{i,j}(u,v))_{i,j\in I}$
is the $\bR$-algebra generated by
$$
\{e(\nu) \mid \nu \in I^\beta \}, \; \{x_k \mid 1 \le k \le n \},
\; \{\tau_l \mid 1 \le l \le n-1 \}
$$
satisfying certain defining relations (see \cite{KL1, KL2, R08} and see also \cite[Section 2]{KKKO18} for precise definition).
The algebra $R(\beta)$ has a natural $\Z$-graded algebra structure as follows:
\begin{align*}
\deg(e(\nu))=0, \quad \deg(x_k e(\nu))= ( \alpha_{\nu_k} ,\alpha_{\nu_k}), \quad  \deg(\tau_l e(\nu))= -(\alpha_{\nu_{l}} , \alpha_{\nu_{l+1}}).
\end{align*}
Let $R(\beta)\gmod$ be the category of finite-dimensional graded $R(\beta)$-modules and set $R\gmod := \bigoplus_{\beta\in \rlQ^+} R(\beta)\gmod$. For a module $M \in R(\beta)\gmod$, the dual space  
\begin{align} \label{Eq: star}
M^\star := \mathrm{Hom}_\bR(M, \bR)
\end{align}
admits an $R(\beta)$-module structure (see \cite[Section 2]{KKKO18} for example).

For any $\nu\in I^\beta$ and $\nu'\in I^{\beta'}$, let $e(\nu, \nu')$ be the idempotent generator associated with the concatenation
$\nu\ast\nu'$ of $\nu$ and $\nu'$, and define
$$
e(\beta, \beta') \seteq \sum_{\nu \in I^\beta, \nu' \in I^{\beta'}} e(\nu, \nu')
{\hs{2ex} \in R(\beta+\beta').}
$$
For $M \in R(\beta)\gmod$ and $N \in R(\gamma)\gmod$, we define 
$$
M \conv N := R(\beta+\gamma)e(\beta, \gamma) \tens_{R(\beta)\tens R(\gamma)} (M \tens N).
$$
We denote by $\conv$ the \emph{convolution product} on $R\gmod$, which makes $R\gmod$ a monoidal category (see \cite[Section 2]{KKKO18} for details). 
We denote by $M \hconv N$ the \emph{head} of the convolution $M \circ N$. A simple module $X$ is \emph{real} if $X \conv X$ is simple. If $X$ is not real, $X$ is said to be \emph{imaginary}. If $X \conv Y$ is simple for simple $R$-modules $X$ and $ Y$, we say that $X$ and $Y$ \emph{strongly commute}.

Let $i\in I$ and $n\in \Z_{\ge0}$. We denote by $\ang{i^n}$ the self-dual simple $R(n\al_i)$-module. We simply write $\ang{i} = \ang{i^1}$. The \emph{character} of $M \in R(\beta)\gmod$ is defined by 
$$
\qch(M) := \sum_{\nu \in I^{\Ht(\beta)}} \qdim (e(\nu)M) \nu,
$$
where $\qdim(V)$ is the graded dimension of a $\Z$-graded vector space $V$.
For $M \in R(\beta)\gmod$, we define
\begin{align} \label{Ei divEi}
E_i(M) := e(\al_i, \beta-\al_i) M \qtq 
E_i^{(n)}(M) :=  \mathrm{Hom}_{R(n\alpha_i)}(P(i^{n}), e(n\al_i, \beta-n\al_i)M ),
\end{align}
where $P(i^{n})$ is the projective cover of $(i^n)$. Note that $E_i$ categorifies the $q$-derivation $e_i'$ on $\qA_q(\n)$ (\cite[(3.4.4)]{K91}).
For a simple module $X$ in $R(\beta)\gmod$, we define 
\begin{align} \label{Eq: ep in Rgmod}
\ep_i(X) := \max\{ k \in \Z_{\ge0} \mid e(k\al_i, \beta-k\al_i)X \ne 0 \}.
\end{align}

For any $w\in \weyl$, we define $\cC_{w}$ to be the  full subcategory of $R\gmod$ consisting of objects $M$ such that
\begin{align*} 
\gW(M) \subset \Sp( \prD \cap w \nrD ),
\end{align*}
where $\gW(M) = \{  \gamma \in  \rlQ_+ \cap (\beta - \rlQ_+)  \mid  e(\gamma, \beta-\gamma) M \ne 0  \}$. 

For a monoidal subcategory $C$ of $R\gmod$, we denote by $K_q(C)$ the Grothendieck ring of $C$. The \emph{grading shift functor} $q$ gives a $\Zq$-module structure to $K_q(C)$. 
We also denote by $K(C)$ the Grothendieck ring of the ungraded category $C_0$ obtained from $C$ by forgetting the grading.
Note that $K(C)$ is equal to the specialization of $K_q(C)$ at $q=1$. 
We write $[X]$ for the element in $K(C)$ (resp.\ $K_q(C)$) corresponding to an object $X \in C$.
If no confusion arises, then we write $X$ instead of $[X]$.
Then we have the categorification of $\qA_q(\n(w))$ (see \cite{KL1, KL2, R08} and see also \cite{KKKO18, KKOP18}).



\begin{prop} \label{Prop: categorification}
There exists an isomorphism between 
\begin{align} \label{Eq: categorification Aqnw}
K_q(\cC_w) \simeq \qA_\Zq(\n(w)).
\end{align}
\end{prop}

For $\La \in \wlP^+$ and $w,v \in \weyl$ with $v \le w$, we denote by $ \dM(w\La, v\La)$ the \emph{determinantial module}, which corresponds to the quantum minor $\qmD (w \La, v\La)$ via the categorification \eqref{Eq: categorification Aqnw} (See \cite{KKKO18} and see also \cite[Section 4]{KKOP18} for details). 
We assume that $\supp(w) = I$. Let $\tcC_w$ be the \emph{localization} of the category $\cC_w$ by the determinantial modules $\dM(w\La_i, \La_i)$ ($i\in I$) (see \cite[Section 5]{KKOP21C} for precise definition). By construction, we have the isomorphism 
\begin{align} \label{Eq: categorification localized}
K_q(\tcC_w) \simeq \tqA_\Zq(\n(w)).
\end{align}
We denote by $\Gs(\infty)$ (resp.\ $\Gs(w)$, $\tGs(w)$) the set of the isomorphic classes of self-dual simple objects in $R\gmod$ (resp.\ $\cC_w$, $\tcC_w$) with respect to $\star$ (\eqref{Eq: star}). Note that $\tGs(w)$ and $\tGup(w)$ coincide via the categorification when $R$ is of symmetric type, but they are different in general. 


It is shown in \cite{KKOP21C, KKOP23} that the localized category $\tcC_w$ is rigid. Thus there exists the right dual functor of $\tcC_w$, which is denoted by $\dual_w$. Note that $\dual_w^{-1}$ is the left dual on $\tcC_w$. We simply write $\dual$ for $\dual_w$ if no confusion arises. Note that $\dual$ is a permutation of $\tGs(w)$ (if the grading is ignored). The following proposition was proved in Appendix B of \cite{IO21_arXiv2}. Note that Appendix B of \cite{IO21_arXiv2} is not included in the published version \cite{IO21}.  
The anti-automorphism $\sigma : R\gmod \buildrel \sim \over \rightarrow R\gmod$ is defined by $\sigma[M] = q^{-(\beta,\beta)/2}[M^\star]$ for $M \in R(\beta)\gmod$.

\begin{prop}[{\cite[Theorem B.22]{IO21_arXiv2}}] \label{Prop: eta_w=dual^-1}
We identify  $K_q(\tcC_w) $ with $ \tqA_\Zq(\n(w))$ via the categorification \eqref{Eq: categorification localized}. 
\bni
\item 
As algebra automorphisms, we have
$$
\eta_w = [\dual^{-1} \circ \sigma].
$$
\item For any $x \in \tGup(w)$ (resp.\ $x \in \tGs(w)$), we have
$$
\eta_w(x) \eqq [\dual^{-1}](x).
$$
This means that $\eta_w$ coincides with $[\dual^{-1}]$ as permutations of $\tGup(w)$ and $\tGs(w)$ 
\ee
\end{prop}







\subsection{Monoidal categorification} \label{Sec: MC}



In this subsection, we briefly review the monoidal categorification of the algebra $\qA_q(\n(w))$ using quiver Hecke algebras (\cite{KKKO18}). We assume that $\supp(w) = I$.


It is known that the algebra $\qA_q(\n(w))$ has a (quantum) cluster algebra structure  (\cite{GLS11, GLS13}). 
Let us fix $\bfi=(i_1, i_2,\ldots,i_l) \in \rR(w)$ and define 
\begin{equation} \label{Eq: k+ k-} 
\begin{aligned}
    k^+ &:= \min (  \{ l+1 \} \cup \{  k+1 \le j \le l \mid i_j = i_k \}  ), \\
    k^- &:= \max (  \{ 0 \} \cup \{  1 \le j \le k-1 \mid i_j = i_k \}  )
\end{aligned}
\end{equation}
for $1 \le k \le l$.
We define $J := \{ 1,2, \ldots, l \}$,  $J_\fr := \{j\in J \mid j^+ = l+1 \}$ and $J_\uf := J \setminus J_\fr$, and set the quantum unipotent minor
$\qmD_k^{\bfi} := \qmD  ({w_{\le k} \varpi_{i_k}, \varpi_{i_k}} ) $ for $1 \le k \le l$.
The \emph{exchange matrix} $\tB = (b_{s,t})_{s \in J, t\in J_\uf}$ associated with $\bfi$ is given by 
\begin{align*} 
    b_{s,t} = 
    \begin{cases}
        1 & \text{ if } s = t^+, \\
         a_{i_s, i_t}  & \text{ if } t < s < t^+ < s^+, \\
        -1 & \text{ if } s^+ = t, \\
         -a_{i_s, i_t}  & \text{ if } s < t < s^+ < t^+, \\
        0 & \text{ otherwise,}
    \end{cases}
\end{align*}
where $a_{i,j}$ is the $(i,j)$-entry of the generalized Cartan matrix $\cmA$. Then the pair 
$$
\seed_\bfi := ( \{ \qmD_k^{\bfi} \}_{k\in J}, \tB) 
$$
is the GLS seed of the algebra $\qA_q(\n(w))$ (\cite{GLS11, GLS13}).
Note that the frozen variables $\{ \qmD_k^{\bfi} \}_{k\in J_\fr}$ coincide with the $q$-central elements $\{\qmC^w_{i}\}_{i\in I}$ (see \eqref{Eq: frozen}).
Let $\dM_k^{\bfi} := \dM  ({w_{\le k} \varpi_{i_k}, \varpi_{i_k}} )$  for $1 \le k \le l$.
We now consider the corresponding \emph{monomial seed} of $\cC_w$ 
\begin{align} \label{Eq: m seed}
 ( \{ \dM_k^{\bfi} \}_{k\in J}, \tB),
\end{align}
which is also denoted by the same notation $\seed_\bfi$.
When $R$ is of symmetric type, it was proved in \cite{KKKO18} that the initial seed \eqref{Eq: m seed} \emph{admits} successive mutations in all directions, which tells that $\cC_w$ is a monoidal categorification of $\qA_q(\n(w))$. However, it is still open when $R$ is of non-symmetric case. 

Since the bases $\tGup(w)$ and $\tGs(w)$ of $\tqA_q(\n(w))$ are \emph{pointed} and $\emph{copointed}$ with respect to $\seed_\bfi$, the two kind of $g$-vectors $\gL_\bfi(x)$ and $\gR_\bfi(x)$, which are \emph{degree} and \emph{codegree} with respect to the \emph{dominance order} arising from $\seed_\bfi$, are well-defined for $x\in \tGup(w)$ (resp.\ $x\in \tGs(w)$) (see \cite{Qin17, Qin20} for $\tGup(w)$, \cite{KK19, KKOP24} for $\tGs(w)$, and see also \cite[Section 5.3]{KKOP24} for details).  

\begin{prop} [{\cite[ Lemma 3.9, Proposition 4.4 and Corollary 5.14]{KKOP24}}] \label{Prop: GrGl for Rgmod}
Let $X \in \Gs(w)$.
\bni
\item There exist $\bfa, \bfb \in \Z_{\ge0}^{J}$ such that 
$$
\dM^{\bfi}(\bfa) \hconv  X  \simeq \dM^{\bfi}(\bfb).
$$
Moreover we have $\gL_\bfi(X) = \bfb-\bfa$.
\item There exist $\bfa, \bfb \in \Z_{\ge0}^{J}$ such that 
$$
X \hconv \dM^{\bfi}(\bfa) \simeq \dM^{\bfi}(\bfb).
$$
Moreover we have $\gR_\bfi(X) = \bfb-\bfa$.
\ee
Here we set $\dM^{\bfi}(\bfc) = \conv_{k\in J} (\dM^\bfi_k)^{\conv c_k}$ for $\bfc = (c_k)_{k\in J } \in \Z_{\ge0 }^{J}$.
\end{prop}

The following lemma will be used Section \ref{Sec: twist auto and LB} for comparing g-vectors for $\tGup(w)$ and $\tGs(w)$.

\begin{lemma} \label{Lem: ei and seed}
Let $i\in I$.
\bni
\item Let $M, N$ be simple $R$-modules.
\bna
\item $\ep_i(M\conv N) = \ep_i(M) + \ep_i(N)$.
\item If $M$ is real and commutes strongly with the simple $R(\al_i)$-module $\ang{i}$, then 
$\ep_i(M\hconv N) = \ep_i(M) + \ep_i(N)$.
\ee
\item Let $\bfi=(i_1, i_2,\ldots,i_l) \in \rR(w)$ and suppose that $i=i_1$. We set $\bfi' := (i_2,\ldots,i_l) \in \rR(s_iw)$.
Then we have $\dM_1^\bfi = \ang{i}$ and 
$$
\dM_k^{\bfi'} = E_i^{(n_k)} ( \dM_{k+1}^{\bfi} )
\qquad \text{for $k\in [1,l-1]$,}
$$
where $n_k = \langle h_i, s_{i_2} \cdots s_{i_k} \La_{i_k} \rangle$.
\ee
\end{lemma}
\begin{proof}
(i) 
The first one follows from the shuffle lemma \cite[Lemma 2.20]{KL1} and the second follows from \cite[Lemma 3.2]{KKOP18}.

(ii) Since $[\dM_k^\bfi] = \qmD_k^\bfi$, it follows from the properties of quantum unipotent minors (see \cite[Lemma 1.7]{KKOP18} for example).
\end{proof}




