\section{Localized crystals} \label{Sec: LB}
In this section, we introduce localized crystals and show PBW and string parametrizations. 
We refer the reader to \cite{K91, K93, K95} for details on crystals. 

\begin{definition}
	A \emph{crystal} is a set $B$ endowed with  maps $\wt\col  B \rightarrow \wlP$,  $\varphi_i$,  $\ep_i \col  B \rightarrow \Z \,\sqcup \{ -\infty \}$
	and $\te_i$, $\tf_i \col  B \rightarrow B\,\sqcup\{0\}$ 
 for all $i\in I$ which satisfy the following axioms: 
	\bna
	\item $\varphi_i(b) = \ep_i(b) + \langle h_i, \wt(b) \rangle$,
	\item $\wt(\te_i b) = \wt(b) + \alpha_i$ if $\te_i b\in B$, and 
$\wt(\tf_i b) = \wt(b) - \alpha_i$ if $\tf_i b\in B$, 
	\item for $b,b' \in B$ and $i\in I$, $b' = \te_i b$ if and only if $b = \tf_i b'$,
	\item for $b \in B$, if $\varphi_i(b) = -\infty$, then $\te_i b = \tf_i b = 0$,
	\item if $b\in B$ and $\te_i b \in B$, then $\ep_i(\te_i b) = \ep_i(b) - 1$ and $ \varphi_i(\te_i b) = \varphi_i(b) + 1$,
	\item if $b\in B$ and $\tf_i b \in B$, then $\ep_i(\tf_i b) = \ep_i(b) + 1$ and $ \varphi_i(\tf_i b) = \varphi_i(b) - 1$.
\ee
\end{definition}
We set $B(\infty)$ to be the \emph{infinite crystal} of the negative half $U_{q}^-(\g)$. 
Since the crystal can be understood as the specialization of the upper global basis $\Gup(\infty)$ at $q=0$, the basis $\Gup(\infty)$ can be written as 
$$
\Gup(\infty) = \{ \Gup(b) \mid b\in B(\infty) \}.
$$
It is shown in \cite{LV11} that the basis $\Gs(\infty)$ has a crystal structure which is isomorphic to $B(\infty)$. Thus we have 
$$
\Gs(\infty) = \{ L(b) \mid b\in B(\infty) \},
$$
where $L(b)$ is the self-dual simple $R$-module corresponding to $b$.

The $\bfk$-antiautomorphism 
$$
*: U_q(\g) \rightarrow U_q(\g) \quad \text{defined by }  e_i \mapsto e_i,\ f_i \mapsto f_i, \ \  q^h \mapsto q^{-h}
$$
gives the $*$-twisted crystal operators to $B(\infty)$ as follows:
$$
\tes_i := * \circ \te_i \circ * \qtq \tfs_i := * \circ \tf_i \circ *.
$$
For $b\in B(\infty)$, we write 
$$
\tem_i(b) = \te_i^{m}(b)\qtq \tesm_i(b) = {\te_i}^{* n}(b),
$$
where $m = \ep_i(b)$ and $n = \eps_i(b)$. We denote by $\one$ the highest weight vector in $B(\infty)$.
Let $(e_i')^{(n)} := (e_i')^n / [n]_{q_i} ! $, where $e_i'$ is the $q$-derivation (\cite[(3.4.4)]{K91}), and let $E_i^{(n)}$ be the counterpart of $(e_i')^{(n)}$ given in \eqref{Ei divEi}.


\begin{lemma} [{\cite[Lemma 5.1.1]{K93} and \cite[Section 2.5.1]{LV11}}] \label{Lem: ei' max}
Let $b \in B(\infty)$ and $n = \ep_i(b)$. Then we have 
$$
(e_i')^{(n)} (\Gup(b)) = \Gup(\te_i^n b) \qtq 
E_i^{(n)} (L(b)) = L(\te_i^n b).
$$  
\end{lemma}
Note that $\ep_i(b) = \ep_i(L(b))$ (see \eqref{Eq: ep in Rgmod}) for $b\in B(\infty)$.



Let $w$ be a fixed element in the Weyl group $\weyl$ and assume that $\supp(w) = I$. We define 
$$
B(w) := \{ b\in B(\infty) \mid \Gup(b) \in \qA_q(\n(w)) \}.
$$
Note that $B(\infty)$ coincides with $B(w_\circ)$ when $U_q(\g)$ is of finite type. 
For any $i\in I$, we denote by $\fz^w_i $ the element in the crystal $B(\infty)$ determined by
\begin{align} \label{Eq: fzwi}
\Gup(\fz^w_i) = \qmC_{i} = \qmD(w\La_i, \La_i). 
\end{align}
We simply write $\fz_i = \fz^w_i$ if no confusion arises.
Let $(b, \bfa), (b', \bfa')  \in B(w) \times \Z^{\oplus I}$ and write 
$\bfa = (a_i)_{i\in I}$ and $\bfa' = (a_i')_{i\in I}$. 
We define 
\begin{align} \label{Eq: equiv rel}
(b, \bfa) \sim (b', \bfa') 
\end{align}
if there exists a positive integer $N$ such that $N + \min_{i\in I}\{ a_i, a_i' \}  \ge 0$ and
\begin{align} \label{Eq: LB and Gup}
\Gup(b) \prod_{i\in I}\Gup( \fz_i)^{N+a_i}  \eqq  \Gup(b') \prod_{i\in I}\Gup( \fz_i)^{N+a_i'}.
\end{align}
It is easy to see that $\sim$ is an equivalence relation on $B(w) \times \Z^{\oplus I}$. We define $\LB(w)$ to be the set of all equivalence classes by $\sim$ in $B(w) \times \Z^{\oplus I}$, i.e,  
\begin{align} \label{Eq: localized crystal}
\LB(w) := B(w) \times \Z^{\oplus I} / \sim. 
\end{align}
For any $b\in B(w)$ and $\bfa = (a_i)_{i\in I} \in \Z^{\oplus I}$, we simply write 
$$
b \cdot \fz(\bfa) = b \cdot \prod_{i\in I}\fz_i^{a_i} := [(b, \bfa)] \in \tB(w)
$$
if no confusion arises. 
When $w = w_\circ$, we simply write $\LB(\infty)$ instead of $\LB(w_\circ)$.
\begin{definition} \label{Def: localized crystal}
We call $\LB(w)$ the \emph{localized crystal} of $B(w)$ by the elements $\{ \fz_i\}_{i\in I}$.
\end{definition}


\begin{remark} \label{Rmk: LB}
Nakashima introduced the notion of localized crystals in studying the categorical crystal structure on $\tqA_q(\n)$ with cellular crystals when $\cmA$ is of finite type (\cite{Nakashima22}).  
Although categorical crystals and cellular crystals are dealt mainly in \cite{Nakashima22}, 
it is not difficult to obtain Definition \ref{Def: localized crystal} by abstracting the result in \cite{Nakashima22}. 
%The localized crystals over a general setting is studied by Kashiwara and Nakashima (see \cite{KN25_arXiv1}).
\end{remark}

For any $x,y \in \LB(w)$, we write 
\begin{align} \label{Eq: equiv for fr}
x \eqfr y \quad \text{ if and only if \quad $x = y \cdot \fz(\bfa)$ for some $\bfa \in \Z^{\oplus I}$,}  
\end{align}
which means that $x$ and $y$ are same up to a multiple of frozens.
 For any element $b \cdot \fz(\bfa) \in \LB(w)$, we define the element $\tGup(b \cdot \fz(\bfa)) \in \tGup (w) $ by
$$
\tGup(b \cdot \fz(\bfa)) \eqq   \Gup(b)\cdot \qmC(\bfa),
$$
where $\qmC(\bfa)$ is given in \eqref{Eq: C(a)}.
Thus the map  $\tGup: \LB(w) \longrightarrow \tGup(w)$ is bijective and
$$
\tGup(w) = \{\tGup(x) \mid x \in \LB(w) \}.
$$
In the same manner, we define the element $L(b \cdot \fz(\bfa)) \in \tGs (w) $ by
\begin{align} \label{Eq: L(x)}
[L(b \cdot \fz(\bfa))] \eqq   [L(b)]\cdot \qmC(\bfa). 
\end{align}
Note that $[\dM_i] = \qmC_i$ for $i\in I$.
Thus we have
$$
\tGs(w) = \{ [L(x)] \mid x \in \LB(w) \}.
$$



By Theorem \ref{Thm: tw tGup} and Proposition \ref{Prop: eta_w=dual^-1}, we can define the permutation $\cdual_w$ on $\LB(w)$ such that the following diagram commutes:
\begin{equation} \label{Eq: Dw and etaw}
\begin{aligned} 
\xymatrix{
 \tGs(w) \ar[d]_{[ \dual_w^{-1}] }  &&  \ar[ll]_\sim  \LB(w)  \ar[rr]^\sim \ar[d]_{\cdual_w^{-1}} && \tGup(w) \ar[d]_{\eta_w} \\
\tGs(w) && \ar[ll]_\sim \LB(w) \ar[rr]^\sim && \tGup(w)
}.
\end{aligned}
\end{equation}
Note that $\cdual_w$ corresponds to the right dual functor $\dual_w$ of $\tcC_w$.



From now until the end of this section, we fix a reduced expression 
$$
\bfi = (i_1, i_2, \ldots, i_m) \in R(w).
$$
In the following subsections, we introduce two parametrizations of $\LB(w)$. 

\subsection{PBW parametrization}



For any $b\in B(w)$, we define $\PBW_\bfi (b) := \PBW_\bfi( \Gup(b) ) $ and set 
$$
\cP_\bfi(w) := \{ \PBW_\bfi(b) \mid b \in B(w) \} \subset \Z_{\ge0}^{[1,m]}
$$
so that the map $\PBW_\bfi: B(w) \rightarrow \cP_\bfi(w)$ is bijective (\cite[Chapter 40]{LusztigBook}). 

For each $j\in I $, we define $P_j := \PBW_\bfi(\fz_j)$ for any $j\in I$.
It is known that 
$$
P_j = (a_t)_{t\in [1,m] } \qquad \text{ by $a_t = \delta_{i_{t}, j} $ for $ t\in [1,m]$} 
$$ 
(see \cite[Section 6.1.3]{Kimura12} and \cite[Corollary 4.7]{KKOP18} for example).
We now extend $\PBW_\bfi$ to the localized crystal $\LB(w)$ as follows: 
for any $x = b \cdot \prod_{i\in I}\fz_i^{a_i} \in \LB(w)$,
$$
\PBW_\bfi(x) = \PBW_\bfi(b) + \sum_{i\in I} a_i P_i \in \Z^{[1,m]}.
$$
Note that, by \eqref{Eq: LB and Gup}, $\PBW_\bfi(x)$ does not depend on the choice of expression of $x$.
If we define 
$$
\tcP_\bfi(w) := \cP_\bfi(w) + \sum_{k\in I} \Z P_k \subset \Z^{[1,m]},
$$
we have the bijection 
\begin{align} \label{Eq: LB PBW}
\pbwP_\bfi :  \LB(w) \buildrel \sim \over \longrightarrow \tcP_\bfi(w), 
\qquad x \mapsto \PBW_\bfi(x).
\end{align}
The set $\tcP_\bfi(w)$ is called the \emph{PBW parametrization} of the localized crystal $\LB(w)$ with respect to the reduced expression $\bfi$ of $w$.  


\subsection{String parametrization}
 For any $b \in B(w)$, we define 
$$ 
\STR_{\bfi} (b) := (t_k)_{k\in [1,m]},
$$ 
where $t_k = \ep_{i_k}( \te_{i_{k-1}}^{t_{k-1}} \cdots \te_{i_2}^{t_2}\te_{i_1}^{t_1}(b))$
for $k\in [1,m]$, and set 
$$
\cS_\bfi(w) := \{ \STR_\bfi(b) \mid b\in B(w) \}.
$$


\begin{lemma} \label{Lem: STR wrt w}
Let $\bfi = (i_1, i_2, \ldots, i_m) \in R(w)$.  
\bni
\item For any $b\in B(w)$, we have 
$$
\te_{i_{m}}^{t_{m}} \cdots \te_{i_2}^{t_2}\te_{i_1}^{t_1}(b) = \one,
$$
where $\STR_{\bfi} (b) = (t_k)_{k\in [1,m]}$.
\item The map 
$
\STR_{\bfi}: B(w) \longrightarrow \cS_\bfi(w)
$
is bijective.
\ee
\end{lemma}
\begin{proof}
(i) 
Let $  F_{\bfi, k} (k\in [1,m])$ be  the dual PBW root vector associated with $\bfi$, and let $f_{\bfi, k}$ be the corresponding element in $B(w)$, i.e., $\Gup(f_{\bfi, k}) = F_{\bfi, k}$. Since the dual PBW vector $F_{\bfi, k} $ is the quantum unipotent minor $ \qmD ({w_{\le k} \La_{i_k}, w_{< k} \La_{i_k}} ) $, we have 
$$
  \tem_{i_{m}} \cdots \tem_{i_2}\tem_{i_1}( f_{\bfi, k} ) = \one
  \qquad \text{for all $k\in [1,m]$}
$$
by \cite[Lemma 1.7]{KKOP18}. 
Lemma \ref{Lem: ei' max} says that 
$$
(e'_{i_{m}})^{\max} \cdots (e'_{i_2})^{\max} (e'_{i_1})^{\max}( F_{\bfi, k} ) \in \bfk,
$$
where $(e_i')^{\max} ( x) := (e_i')^{(\ep_i(x))} (x) $ for $x \in \Gup(\infty)$.



Since $e_i'$ is the $q$-derivation (\cite[(3.4.4)]{K91}) and the dual PBW vectors $F_{\bfi, k}$ ($k\in [1,m]$) generate the algebra $A_q(\n(w))$,  we conclude that 
$$
  \tem_{i_{m}} \cdots \tem_{i_2}\tem_{i_1}( b ) = \one
  \qquad \text{for any $b\in B(w)$.}
$$

(ii) It follows from (i) directly.
\end{proof}

\begin{remark}
Lemma \ref{Lem: STR wrt w}  can be proved by using \cite[Proposition 3.3]{KKOP23} in terms of quiver Hecke algebras.\end{remark}


For each $j\in I $, we define $S_j := \STR_\bfi(\fz_j)$.
It follows from \cite[Lemma 1.7]{KKOP18} that $ S_j = (t_k)_{k\in [1,m] } $ is given as
$$
t_k =   \langle h_{i_k}, s_{i_{k+1}} \cdots s_{i_{m-1}} s_{i_{m}} \La_{j} \rangle \qquad \text{ for } k\in [1,m].
$$
We now extend $\STR_\bfi$ to the localized crystal $\LB(w)$ as 
$$
\STR_\bfi(x) = \STR_\bfi(b) + \sum_{i\in I} a_i S_i \in \Z^{[1,m]}
\qquad \text{ for any $x = b \cdot \prod_{i\in I}\fz_i^{a_i} \in \LB(w)$}.
$$
By \eqref{Eq: LB and Gup}, $\STR_\bfi(x)$ does not depend on the choice of expression of $x$.
Define 
$$
\tcS_\bfi(w) := \cS_\bfi(w) + \sum_{k\in I} \Z S_k \subset \Z^{[1,m]},
$$
which gives a bijection 
\begin{align} \label{Eq: LB STR}
\strS_\bfi :  \LB(w) \buildrel \sim \over \longrightarrow \tcS_\bfi(w), 
\qquad x \mapsto \STR_\bfi(x).
\end{align}
The set $\tcS_\bfi(w)$ is called the \emph{string parametrization} of the localized crystal $\LB(w)$ with respect to the reduced expression $\bfi$ of $w$.  



\vskip 2em  



\section{Twist automorphisms and localized crystals} \label{Sec: twist auto and LB}

In this section, we give a description of $ \cdual_w$ in terms of localized crystals. 

Let $w\in \weyl$ and assume that $\supp(w) = I$. We fix 
$$
\bfi = (i_1, i_2, \ldots, i_m) \in \rR(w).
$$
Recall the bijections $\pbwP_\bfi: \LB(w) \buildrel \sim \over \longrightarrow \tcP_\bfi(w)$ and $\strS_\bfi: \LB(w) \buildrel \sim \over \longrightarrow \tcS_\bfi(w)$ given in \eqref{Eq: LB PBW} and \eqref{Eq: LB STR} respectively. We define the bijection $\psi_\bfi :=  \strS_\bfi \circ \pbwP_\bfi^{-1}  $, i.e., 
\begin{align} \label{Eq: PBW STR}
\psi_\bfi : \tcP_\bfi(w) \buildrel \sim \over \longrightarrow \tcS_\bfi(w), \qquad  P + \sum_{i\in I} a_i P_i \mapsto \psi_\bfi(P) +  \sum_{i\in I} a_i S_i.
\end{align}
Note that $\psi_\bfi$ is not $\Z$-linear.

We now recall two kind of $g$-vectors $\gR_\bfi $ and $\gL_\bfi$ given in Section \ref{Sec: MC}. For any $x \in \LB(w)$, we set 
$$
\gL_\bfi(x) := \gL_\bfi(\Gup(x)) \qtq \gR_\bfi(x) := \gR_\bfi(\Gup(x))
$$ and define 
$$
\GL_\bfi(w) := \{ \gL_\bfi(x) \mid b\in \LB(w)\} \qtq \GR_\bfi(w) := \{ \gR_\bfi(x) \mid b\in \LB(w)\}.
$$
Note that 
\begin{align} \label{Eq: GrGlZm}
\GL_\bfi(w) = \Z^{[1,m]} = \GR_\bfi(w)
\end{align}
and the maps 
$$
\gL_\bfi: \LB(w) \buildrel \sim \over \longrightarrow \GL_\bfi(w) \qtq
\gR_\bfi: \LB(w) \buildrel \sim \over \longrightarrow \GR_\bfi(w)
$$
are bijective (\cite{Qin17} and \cite[Corollary 3.17 and Corollary 3.18]{KK19}).



Define $m\times m$ matrices  
\begin{align}\label{Eq: N M}
N_\bfi = (n_{p,q})_{p,q \in [1,m]} \qtq 
M_\bfi = (m_{p,q})_{p,q \in [1,m]}
\end{align}
by
\begin{align*}
n_{p,q} = 
\begin{cases}
1 & \text{ if } p=q,  \\
-1 & \text{ if } p^+ = q, \\
0  & \text{ otherwise,}
\end{cases}
\qquad
m_{p,q} = 
\begin{cases}
 \langle h_{i_{ p}}, s_{i_{ p+1}} s_{i_{p+2}} \cdots s_{i_{q}} \La_{i_q}   \rangle  & \text{ if } p\le q,   \\
0  & \text{ otherwise,}
\end{cases}
\end{align*}
where $k^+$ is defined in \eqref{Eq: k+ k-}.
Then it is shown in \cite{KK19, KKOP24, FuOy20} that the bijections  $\gR_\bfi \circ \pbwP_\bfi^{-1}$ and $ \strS_\bfi \circ (\gL_\bfi)^{-1}$ are described explicitly in terms of the matrices $N_\bfi$ and $M_\bfi$.


\begin{prop} \label{Prop: gM gN}   \  
\bni
\item For any $x \in \LB(w)$, we have 
$$
\gL_\bfi ( x) =  \gL_\bfi (L(x)) \qtq
\gR_\bfi ( x) =  \gR_\bfi (L(x)),
$$
where $L(x) \in \tGs (w)$ is the simple object defined in \eqref{Eq: L(x)}.

\item We define $\gM_\bfi :=  \strS_\bfi \circ (\gL_\bfi)^{-1}$, i.e., 
$$ 
\gM_\bfi: \GL_\bfi(w) \buildrel \sim \over \longrightarrow \tcS_\bfi(w).
$$
For any $v = (v_k)_{k\in [1,m]}\in \GL_\bfi(w)$,  we have $\gM_\bfi(v) = (v_k')_{k\in [1,m]}$, where
$$
v_k' = \sum_{t=1}^m m_{k,t} v_t \qquad \text{ for any $k\in [1,m]$},
$$
i.e., we have 
$
\gM_\bfi(v) =   M_\bfi \cdot v.
$
\item We define $\gN_\bfi :=  \gR_\bfi \circ \pbwP_\bfi^{-1}$, i.e., 
$$ 
\gN_\bfi: \tcP_\bfi(w) \buildrel \sim \over \longrightarrow \GR_\bfi(w).
$$
For any $v = (v_k)_{k\in [1,m]}\in \tcP_\bfi(w)$,  we have $\gN_\bfi(\bfa) = (v_k')_{k\in [1,m]}$, where
$$
v_k' = \sum_{t=1}^m n_{k,t} v_t \qquad \text{ for any $k\in [1,m]$},
$$
i.e., we have 
$
\gN_\bfi(v) =   N_\bfi \cdot v .
$

\ee	
\end{prop}	
\begin{proof}
By \cite[Theorem 6.5]{FuOy20}, we have (ii). 

We shall now prove (i). Let $x \in \LB(w)$. Since the seed $\seed_\bfi$ is contained in both of $\Gup(w)$ and $\tGs(w)$, there is no harm to assume that $x\in B(w)$. We set $X := L(x) \in \Gs(w)$ and define 
$\STR_\bfi (X) = (\xi_1, \xi_2, \ldots, \xi_m) $, where $\xi_{k} = \ep_{i_k}( E_{i_{k-1}}^{(\xi_{k-1})} \cdots E_{i_2}^{(\xi_2)}E_{i_1}^{(\xi_1)}(X))$ for $k\in [1,m]$.
Lemma \ref{Lem: ei' max} tells us that 
\begin{align} \label{Eq: same str}
\STR_\bfi (x) = \STR_\bfi (X).
\end{align}
By Proposition \ref{Prop: GrGl for Rgmod}, there exist $\bfa=(a_k)_{k\in [1,m]}, \bfb=(b_k)_{k\in [1,m]} \in \Z_{\ge0}^{[1,m]}$ such that 
$$
\dM^{\bfi}(\bfa) \hconv  X  \simeq \dM^{\bfi}(\bfb).
$$
It follows from Lemma \ref{Lem: ei and seed} (i) and \cite[Lemma 1.7]{KKOP18} that 
\bna
\item $ \ep_{i_1}(X) + \sum_{k\in [1,m]} a_k \ep_{i_1} (\dM^{\bfi}_k) = \ep_{i_1} (\dM^{\bfi}(\bfa) \hconv  X) =  \ep_{i_1} (\dM^{\bfi}(\bfb) ) = \sum_{k\in [1,m]} b_k \ep_{i_1} (\dM^{\bfi}_k)$, 
\item $\ep_{i_1}(\dM^{\bfi}_k) = \langle h_{i_1}, s_{i_{ 2}} s_{i_{3}} \cdots s_{i_{k}} \La_{i_k} \rangle = m_{1,k}$.
\ee
This implies that 
$$
\ep_{i_1} (X) = \sum_{k\in [1,m]} m_{1,k} (b_k - a_k) = \sum_{k\in [1,m]} m_{1,k} g_k,
$$
where $ \gL_\bfi (X) = (g_k)_{k\in [1,m]}$ by Proposition \ref{Prop: GrGl for Rgmod}. Thus
Lemma \ref{Lem: ei and seed} (ii) says that $  \STR_\bfi (X)=  M_\bfi \cdot \gL_\bfi (X) $ by the standard induction argument. By (ii) and \eqref{Eq: same str}, we have  
$$
\gL_\bfi (x) = \gL_\bfi (X).
$$
Since $ \gR_\bfi(b) + \gL_\bfi(\cdual_w(b)) =0$ by \cite[Lemma 3.13]{KK19} and \cite[Corollary 4.6]{KKOP24}, we also obtain
$$\gR_\bfi (x) = \gR_\bfi (X),
$$ which completes the proof for (i).

By (i), we have (iii) by  \cite[Proposition 3.14]{KK19} and \cite[Proposition 4.5]{KKOP24}.
\end{proof}

\begin{remark} \
\bni
\item 
By construction, the matrices $N_\bfi$ and $M_\bfi$ are upper-triangular matrices whose diagonal entries are all $1$.
Proposition \ref{Prop: gM gN} says that $\gN_\bfi$ and $\gM_\bfi$ are $\Z$-linear.

\item Although two bases $\Gup(w)$ and $\Gs(w)$ are different in general, their $g$-vectors coincide by Proposition \ref{Prop: gM gN} (i). Thus when dealing with $g$-vectors in this paper, we will sometimes not distinguish between two bases $\Gup(w)$ and $\Gs(w)$.
\item By Proposition \ref{Prop: gM gN} and \eqref{Eq: GrGlZm}, we have 
$$
\tcS_\bfi(w) = \Z^{[1,m]} = \tcP_\bfi(w).
$$
\ee
\end{remark}


Recall the crystal isomorphism $\psi_\bfi$ given in \eqref{Eq: PBW STR},  the twist automorphism $\eta_w$ on the localized quantum coordinate ring $\tqA_q(\n(w))$ given in Section \ref{Sec: qcr} and the permutation $\cdual_w$ on the localized crystal $\LB(w)$ given in \eqref{Eq: Dw and etaw}. 
Note that we have the following bijections:
\begin{equation} \label{Eq: isom}
\begin{aligned} 
\xymatrix{
&&& \LB(w) \ar[ld]_{\pbwP_\bfi} \ar[rd]^{\strS_\bfi}
\\
\GR_\bfi(w) && \ar[ll]_ {\gN_\bfi} \tcP_\bfi(w) \ar[rr]^ {\psi_\bfi} && \tcS_\bfi(w) && \ar[ll]_{\gM_\bfi} \GL_\bfi(w).
}
\end{aligned}
\end{equation}

\begin{theorem} \label{Thm: main}
Let $w\in \weyl$, $\bfi \in \rR(w)$ and $b \in \LB(w)$.
Under the identification 
$$
\GL_\bfi(w) = \Z^{[1,m]} = \GR_\bfi(w),
$$ 
we have the following: for any $b \in \LB(w)$,
\bni 
\item $ \gL_\bfi( b ) =  \gM_\bfi^{-1} \circ \psi_\bfi \circ \gN_\bfi^{-1} (\gR_\bfi( b )) $,
\item $\gL_\bfi( \cdual_w( b) ) = - \gN_\bfi \circ \psi_\bfi^{-1} \circ \gM_\bfi (\gL_\bfi( b))$,
\item $\gR_\bfi( \cdual_w( b) ) = \gN_\bfi \circ \psi_\bfi^{-1} \circ \gM_\bfi ( -  \gR_\bfi( b))$,
\item $ \PBW_{\bfi}( \cdual_w(b) )  =  \psi_\bfi^{-1} \circ \gM_\bfi \circ \gN_\bfi (  -   \PBW_{\bfi}(b )) $,
\item $ \STR_{\bfi}( \cdual_w(b) )  = -   \gM_\bfi \circ \gN_\bfi \circ \psi_\bfi^{-1} (\STR_{\bfi}(b )) $.
\ee
\end{theorem}	
\begin{proof}
Since $\cdual_w$ is the crystal-theoretic counter part of the right dual functor $\dual_w$ in the localized category $\tcC_w$ (see \eqref{Eq: Dw and etaw}), by \cite[Lemma 3.13]{KK19} and \cite[Corollary 4.6]{KKOP24}, we have 
\begin{align} \label{Eq: gR gL}
 \gR_\bfi(b) + \gL_\bfi(\cdual_w(b)) =0. 
\end{align}

Then (i) follows from \eqref{Eq: isom}, and the others follow from (i) and \eqref{Eq: gR gL}.	
\end{proof}


\begin{remark} \
