\section{Minuscule representations} \label{Sec: MR}

In this section, when $\g$ is of finite classical type and $b$ is an element of the \emph{$*$-twisted minuscule crystal}, we shall describe $\cdual(b)$ explicitly in terms of combinatorics of Young diagrams. Throughout this section, we assume that $\g$ is of finite classical type, i.e., of type $A_n$, $B_n$, $C_n$ or $D_n$. We shall also use the standard convention for Dynkin diagrams (see \cite[Chapter 4]{Kac90} for example).  


Let $B(\La)$ be the crystal of the irreducible module $V(\La)$ with highest weight $\La \in \wlP^+$. We denote by $b_\La$ the highest weight element of $B(\La)$ and consider the embedding
$$
\iota: B(\La) \hookrightarrow B(\infty)
$$ 
defined by $\iota(b_\La)= \one $ and $\iota(\te_i(b)) = \te_i(\iota(b))$ for any $b\in B(\La)$ and $i\in I$. 
Note that the embedding $\iota$ is the crystal counterpart of the dual map of the canonical projection $U_q^-(\g) \twoheadrightarrow V(\Lambda)$ sending $x$ to $x \cdot v_\La$, where $v_\La$ is the highest weight vector of $V(\La)$.
It is known that the image $\iota(B(\La))$ is equal to $\{ b \in B(\infty) \mid \eps_i(b) \le \La(h_i) \text{ for all } i\in I   \}$. We identify $B(\La)$ with the image $\iota(B(\La))$ if no confusion arises. Similarly, we define 
\begin{align} \label{Eq: *-twisted MC}
B(\Lambda)^* := \{ b\in B(\infty) \mid \ep_i(b) \le \La(h_i) \text{ for all } i\in I  \},
\end{align}
which is called the $*$-twisted crystal. It is easy to see that the involution $*$ takes $B(\La)$ to $B(\La)^*$ as subsets of $B(\infty)$.



We define 
\begin{align*}
\IM = 
\begin{cases}
I & \text{ if $\weyl$ is of type $A_n$}, \\
\{ n \} & \text{ if $\weyl$ is of type $B_n$}, \\
\{ 1 \} & \text{ if $\weyl$ is of type $C_n$}, \\
\{1, n-1, n \} & \text{ if $\weyl$ is of type $D_n$}, 
\end{cases}
\end{align*}
and an index $i \in \IM $ is called a \emph{minuscule} index.


For a minuscule index $t \in I_{\mathrm{M}}$, we define $\weyl_t$ to be the subgroup of $\weyl$ generated by the generators $s_i$ for $i\in I \setminus \{t \}$.
It is known that the weight map
\begin{align} \label{Eq: bij bw B and WLa}
 B(\La_t)^* \buildrel \wt \over \longrightarrow \weyl \cdot \La_t
\end{align}
is bijective (see \cite[Section 1]{P20} for example).
Let $x_t$ be the longest element of the set of minimal-length coset representatives for $\weyl_t \backslash \weyl$, and we simply write $ \cdual $ for $\cdual_{x_t}$ if no confusion arises. 


\subsection{Type $A_n$}
In this case, we have $I = \IM$. We take and fix $t \in I$. 

For a \emph{partition} $\la = (\la_1 \ge \la_2 \ge \cdots \ge \la_l >0)$ with $N = \sum_{k=1}^l \la_k$, we set $|\la|:=N$. We identify partitions with \emph{Young diagrams} using English convention. 
We write a box $\bx = (i,j) \in \la$ if there is a box in the $i$th row and the $j$th column of $\la$.
A \emph{standard tableau} $T$ of shape $\la$ is a bijection from the set of boxes in $\la$ to the set $[1,N]$ such that the entries in rows and columns increase from left to right and top to bottom respectively.
Define $\ST(\la)$ to be the set of all standard tableaux of shape $\la$.
We denote by $T^\la$ the \emph{initial tableau}, which is the distinguished standard tableau where we fill the boxes with $[1,N]$ along successive rows from top to bottom. 


For a box $\bx = (i,j) \in \la$,
we define 
$$
\res_t(\bx) := t-i+j,
$$ which is called the \emph{residue} of $\bx$. 
We simply write $\res(\bx) $ for $\res_t(\bx)$ if no confusion arises.
The weight of $\la$ is defined by 
\begin{align} \label{Eq: wt for la}
\wt(\la) := \sum_{\bx\in \la} \al_{\res(\bx)}.
\end{align}
For a standard tableau $T$ of shape $\la$, we define 
\begin{align} \label{Eq: res of T}
\res(T) = ( \res(T^{-1}(1)), \res(T^{-1}(2)), \ldots, \res(T^{-1}(N))).
\end{align}

We define 
\begin{align} \label{Eq: la circ and bfi An}
\la^\circ_t := ( \underbrace{n-t+1, n-t+1, \ldots, n-t+1}_{t \text{ times}}), 
\qquad  \bfi := \res(T^{\la_t^\circ}),
\end{align}
and set $N := |\la_t^\circ|= t(n-t+1)$.
Note that $\bfi$ is a reduced expression of the longest element $x_t$ of the set of minimal-length coset representatives for $\weyl_t \backslash \weyl$.

\begin{example} \label{Ex: An 1}
Let $n=5$ and $t=3$.  
Then we have $\lambda^\circ_3 = (3,3,3)$ and $N=9$. 
The residues for $\lambda^\circ_3$ are given as
$$
\la_3^\circ = 
\begin{tabular}{ |c|c|c| } 
 \hline
 3 & 4 & 5 \\ 
 \cline{1-3}
 2 & 3 & 4 \\
  \cline{1-3}
 1 & 2 & 3 \\ 
  \cline{1-3}
\end{tabular}\ ,
$$
where the number in a box $\bx \in \la_3^\circ$ is the residue $\res(\bx)$.
The residues tell us that $\wt(\la_3^\circ) = \al_1 + 2\al_2 + 3\al_3 + 2\al_4 + \al_5$.
The initial tableau $T^{\la_3^\circ}$ is give as
$$
T^{\la_3^\circ} = 
\begin{tabular}{ |c|c|c| } 
 \hline
 1 & 2 & 3 \\ 
 \cline{1-3}
 4 & 5 & 6 \\
  \cline{1-3}
 7 & 8 & 9 \\ 
  \cline{1-3}
\end{tabular},
$$ 
which gives  $\bfi = \res(T^{\la_3^\circ})= ( 3,4,5, 2,3,4, 1,2,3)$.
\end{example}



The following lemma can be obtained from the bijection between $B(\La_t)$ and its weight set 
%(see \cite[Section 3.5]{KR08} and \cite[Section 2.2]{P20} for example).
(see \cite{KR08} and \cite{P20} for example). 

\begin{lemma} \label{Lem: YD and WLat}
Let $\YD_t = \{ \la \vdash N \mid \la \subset \la^\circ_t \}$.
Then the correspondence $ \la \mapsto \La_t - \wt(\la) $ gives a bijection from $\YD_t$ to the set 
$\weyl \cdot \La_t$.
\end{lemma}

Thanks to Lemma \ref{Lem: YD and WLat}, we denote by $\la_{ \beta}$ the Young diagram in $\YD_t$ corresponding to the weight $\La_t-\beta \in \weyl \cdot \La_t$. 
If $b\in B(\La_t)^*$ is the corresponding element of $\la \in \YD_t$ (see \eqref{Eq: bij bw B and WLa}), we set $\la_b := \la_{\La_t - \wt(b)}$ and $b_\la := b$.


We briefly recall the homogeneous representations of the quiver Hecke algebra associated with minuscule representations (see \cite{KR08} and \cite{P20}), which will take a key role in proving Proposition \ref{Prop: homogenous YD A}. 
Let $R$ be the quiver Hecke algebra over a field $\bR$ associated with the Cartan matrix of type $A_n$ and polynomials $ \qQ_{i,j}$ satisfying certain conditions \cite[(2.1)]{P20}.
For $\la \subset \la_t^\circ$, we set $\Specht^\la := \bigoplus_{T \in \ST(\la)} \bR T $ and define an $R(\wt(\la))$-module structure on $\Specht^\la$ by 
$$
e(\nu) T = \delta_{\nu, \res(T)}T, \qquad x_i e(\nu) T = 0, \qquad 
\tau_j e(\nu) T = 
\begin{cases}
s_j T  & \text{ if $\nu = \res(T)$ and } s_j T \in \ST(\la),  \\
0 & \text{ otherwise,}
\end{cases}
$$
for $T \in \ST(\la)$ and admissible $i,j, \nu$. Here $s_j T$ is the tableau obtained from $T$ by swapping $j$ and $j+1$. Then $\Specht^\la$ becomes an irreducible $R$-module, which is called the \emph{Specht module}. 
By construction, we have $\ep_i(\Specht^\la) = \delta_{i,t}$ and  
\begin{align} \label{Eq: qch of S}
\qch(\Specht^\la) = \sum_{T \in \ST(\la)} \res(T).
\end{align}
Thus one can easily show $L(b_\la) \simeq \Specht^\la $.



We now take $\la \subset \la_t^\circ$. Given $ 1 \le k  \le N$, 
we take $\bx = (r,c) \in \la_t^\circ $ such that $ T^{\la_t^\circ}(\bx)=k $.
 We then define $a_k := 1$ if $(r,c) \in \la$ and $a_k := 0$ otherwise, and set 
\begin{align} \label{Eq: def si}
\bfs_\bfi (\la) := (a_1, a_2, \ldots, a_{N}) \in \{0,1 \}^N.
\end{align}
On the other hand, the Young diagram $\la$ can be decomposed into \emph{diagonal hooks}, i.e., 
\begin{align}
H(\la) = (H_1, H_2, \ldots, H_r),
\end{align}
where $H_1$ is the largest hook in $\la$ consisting of the first row and the first column; $H_2$ is the largest hook in the Young diagram obtained from $\la$ by removing $H_1$, and so on.   
Note that $\wt(H_k) \in \prD$ for all $k$. Let $ \HW_t := \{ \wt(H_k) \mid k\in [1,r] \} \subset \prD$. 
For a given $ 1 \le k  \le N$, we define $p_k := 1$ if $ \beta_k \in \HW_t $ and $p_k := 0$ otherwise, and set 
\begin{align}
\bfp_\bfi (\la) := (p_t)_{t\in [1,N]} \in \{0,1 \}^N,
\end{align}
where $\beta_k$ is the positive root given in \eqref{Eq: beta_k}.
We then have the following proposition.

\begin{prop} \label{Prop: homogenous YD A}
For any $b \in B(\La_t)^*$,  we have
\bni
\item $\PBW_\bfi(b) = \bfp_\bfi (\la_b)$,
\item $\STR_\bfi(b) = \bfs_\bfi (\la_b)$,
\item $\PBW_\bfi( \cdual^{-1}(b) ) = -\gN_\bfi^{-1} \circ \gM_\bfi^{-1}(\bfs_\bfi (\la_b)) $,
\item $\STR_\bfi( \cdual(b) ) = -\gM_\bfi \circ \gN_\bfi(\bfp_\bfi (\la_b)) $,
\ee
where $\gM_\bfi$ and $\gN_\bfi$ are the linear maps defined in Proposition \ref{Prop: gM gN}.
\end{prop}
\begin{proof}
We consider the Specht module $\Specht^{\la_b}$. Since $L(b) \simeq \Specht^{\la_b}$, we have the assertion (ii) by \eqref{Eq: ep in Rgmod} and \eqref{Eq: qch of S}.

On the other hand, we consider the diagonal hook decomposition $H(\la) = (H_1, H_2, \ldots, H_r)$.
By the same argument as in the proof of \cite[Theorem 3.4 (2)]{P20}, we have an isomorphism 
$$
\hd (\Specht^{H_1} \circ \Specht^{H_2} \circ \cdots \circ \Specht^{H_r} ) \simeq \Specht^{\la_b}.
$$
Since $\Specht^{H_k}$ ($k\in [1,r]$) are \emph{cuspidal modules} associated with $\bfi$, i.e., $\Specht^{H_k}$ belongs to the set of dual PBW vectors associated with $\bfi$ under the categorification, we have the assertion (i).
The other assertions (iii) and (iv) follows from Theorem \ref{Thm: main}.
\end{proof}



\begin{example}\label{ex: Type A (3,2,2) diagonal hook decomposition}
We keep all notations appearing in Example \ref{Ex: An 1}.
Let $\la = (3,2,2) \subset \la_3^\circ$. 
The residues for $\la$ are given as
