\subsubsection{Lattice path interpretation and periodicity}
We introduce a lattice path model that describes the inverse action of the twist automorphism $\mathcal{D}$ on certain elements of $\tcS_\bfi(x_t)$. This model gives a combinatorial method to track the orbit of $\qmD_k^{\bfi}$ in the GLS seed under the action of $\mathcal{D}^{-1}$, and thereby determines $\PD(x_t)$ for all $t \in [1,n]$.

For \( 0 < i < t \) and \( 0 < j < n - t + 1 \), we set
$$
i^c := t - i \qtq j^c := n - t + 1 - j.
$$
Note that 
$(i^c)^c = i$ and $(j^c)^c = j.$

Consider the set of lattice points $\mathcal{Z} = \mathbb{Z}_{> 0}^2 \subset \mathbb{R}^2$. For convenience in describing the correspondence between string parametrizations and lattice points later, we set the positive $x$-axis to point downward and the positive $y$-axis to point rightward.
\begin{definition}
    In $\mathbb{R}^2$, we define the following families of lines.
    \bni
        \item A \emph{horizontal line} is a line of the form $x = t \cdot m$ for some $m \in \mathbb{Z}_{> 0}$. It is called an \emph{odd horizontal line} if $m$ is odd, and an \emph{even horizontal line} if $m$ is even.

        \item A \emph{vertical line} is a line of the form $y = (n - t + 1) \cdot m$ for some $m \in \mathbb{Z}_{> 0}$. It is called an \emph{odd vertical line} if $m$ is odd, and an \emph{even vertical line} if $m$ is even.
    \ee
    \end{definition}


For $(x,y) \in \mathcal{Z}$, there are $m, u \in \mathbb{Z}_{\ge 0}$ satisfying 
\[
t \cdot m < x \le t \cdot (m+1)\quad\text{and}\quad (n - t + 1) \cdot  u  < y \le (n - t + 1) \cdot ( u  + 1).
\] 
We define $\kappa(x,y) :=(p,q)$ by
\[
p = \begin{cases}
i, & \text{if $m$ is even,}\\
i^c, & \text{if $m$ is odd,}
\end{cases}
\quad\text{and}\quad
q = \begin{cases}
j, & \text{if $ u $ is even,}\\
j^c, & \text{if $ u $ is odd.}
\end{cases}
\]



Now, we set 
$$p_0 := (i,j)$$ 
and construct a lattice path $L$ starting from $p_0 = (i,j)$.  
Given $p_n = (x,y)$ and a path $L_n$ from $p_0$ to $p_n$, we define $p_{n+1} = (x', y')$ and extend $L_n$ inductively as follows.

\textbf{Case 1.} Suppose $(x,y)$ lies on neither a horizontal nor a vertical line.  
Extend $L_n$ diagonally in the $(1,1)$ direction until it first intersects a horizontal or vertical line, say at $(u,v)$.  
Let $\widehat{L}_n$ denote the diagonally extended path. Then:

\begin{itemize}
\item If the intersection is with a horizontal line only, set
\[
(x', y') = (u + \iota, v), \quad \text{where } \iota = 
\begin{cases}
i^c & \text{if the line is odd,} \\
i & \text{if the line is even.}
\end{cases}
\]

\item If the intersection is with a vertical line only, set
\[
(x', y') = (u, v + \jmath), \quad \text{where } \jmath = 
\begin{cases}
j^c & \text{if the line is odd,} \\
j & \text{if the line is even.}
\end{cases}
\]

\item If it intersects both, set $(x', y') = (u, v)$.
\end{itemize}

Define $L_{n+1}$ by extending $\widehat{L}_n$ with the segment from $(u,v)$ to $(x', y')$.

\textbf{Case 2.} Suppose $(x,y)$ lies on both a horizontal and vertical line with associated indices $\kappa(x,y) = (p,q)$.  
Then set
\[
(x', y') = (x + p^c, y + q^c),
\]
and define $L_{n+1}$ by attaching the segments from $(x,y)$ to $(x + p^c, y)$ and then to $(x + p^c, y + q^c)$.


\begin{remark}\label{rem: the lattice path}
The path proceeds in three possible directions: $(1,0)$, $(0,1)$, and $(1,1)$. Among these, the steps in the $(1,0)$ and $(0,1)$ directions occur only immediately after the path crosses a horizontal or vertical line, as follows:
\begin{itemize}
\item If the path crosses an even horizontal line, it contributes $i$ steps in the $(1,0)$ direction.
\item If the path crosses an odd horizontal line, it contributes $i^c$ steps in the $(1,0)$ direction.
\item If the path crosses an even vertical line, it contributes $j$ steps in the $(0,1)$ direction.
\item If the path crosses an odd vertical line, it contributes $j^c$ steps in the $(0,1)$ direction.
\end{itemize}
\end{remark}

Let $\mathcal{P} = \{p_0, p_1, \ldots\}$ be the resulting sequence of points.  
Note that no $p_n$ lies solely on a horizontal or solely on a vertical line.
For each point $p_k = (x,y)$ with $\kappa(x,y) = (p,q)$, where $p \in \{i, i^c\}$ and $q \in \{j, j^c\}$, we define $\cS(p_k) \in \tcS_\bfi(w)$ as follows:
\bni
\item If $p_k$ lies on neither a horizontal nor a vertical line, set
\[
\cS(p_k) := R_{(\bar{x} - p, \bar{y} - q), (p, q)}
\]
where $\bar{x}$ and $\bar{y}$ denote the residues of $x$ modulo $t$ and $y$ modulo $n - t + 1$, respectively.
\item If $p_k$ lies on both a horizontal and a vertical line, set
\[
\cS(p_k) := R_{(0, q^c), (p^c, q)}.
\]
\ee

\begin{lemma}\label{lem: D of path model}
For each point $p_k$ in the sequence,
\[
\mathcal{D}^{-1}(\cS(p_k)) = \cS(p_{k+1}).
\]
\end{lemma}

\begin{proof}
The assertion follows by a straightforward case-by-case verification using Proposition \ref{prop: rule for D minuscule type A}. 
\end{proof}


