We analyze specific points in $\mathcal{P}$ which helps us to prove the main theorem. For each $u \in \mathbb{Z}_{>0}$, define
\begin{align}\label{eq: y(u)}
    y(u) := (n - t + 1) \cdot u +
    \begin{cases}
        j & \text{if } u \text{ is even},\\
        j^c & \text{if } u \text{ is odd}.
    \end{cases}
\end{align}
By the construction of $\mathcal{P}$, there exists a unique $x(u) \in \mathbb{Z}_{>0}$ such that $(x(u), y(u)) \in \mathcal{P}$. 
Observe that $(x(u), y(u))$ is the point in $\mathcal{P}$ reached after crossing $u$ vertical lines. 
Let $\mathcal{L}(u)$ be the associated lattice path from $(i,j)$ to $(x(u), y(u))$.
For instance, in Figure \ref{Figure: P and L}, $(x(1),y(1)) = p_1, \mathcal{L}(1) = L_1$ and $(x(2),y(2)) = p_4, \mathcal{L}(2) = L_4$.


\begin{lemma}\label{lem: x(u) and e}
    Let $u \ge 1$, and denote by $D(u)$ the number of $(1,1)$-moves in $\mathcal{L}(u)$.

    \bni
    \item The value $x(u)$ is determined by $D(u)$, and is explicitly given by
    \begin{align*}
        x(u) = 2 \left\lfloor \frac{D(u)}{t} \right\rfloor t +
        \begin{cases}
            i + \overline{D(u)} & \text{if } \overline{D(u)} < i^c, \\
            t + \overline{D(u)} & \text{if } \overline{D(u)} \ge i^c,
        \end{cases}
    \end{align*}
    where $\overline{D(u)} \in [0, t-1]$ such that $\overline{D(u)} = D(u) \bmod t$.

    \item  Let $e \in \mathbb{Z}_{>0}$ such that $p_e = (x(u), y(u))$. 
    Then
    \begin{align*}
        e = 
        u + 2  \left\lfloor \frac{D(u)}{t} \right\rfloor +
        \begin{cases}
            0 & \text{if } \overline{D(u)} < i^c,\\
            1 & \text{if } \overline{D(u)} \ge i^c.
        \end{cases}
    \end{align*}
    \item The value $D(u)$ is given by 
    \[
    D(u) = (n - t + 1) \cdot \left\lfloor \frac{u}{2} \right\rfloor +
\begin{cases}
0 & \text{if } u \text{ is even}, \\[4pt]
j^c & \text{if } u \text{ is odd}.
\end{cases}
    \]

    \ee
\end{lemma}



\begin{proof}
(i) By Remark~\ref{rem: the lattice path}, the $(1,0)$-steps in $\mathcal{L}(u)$ arise solely from horizontal lines crossed by the path. Since the contribution pattern of horizontal lines repeats every $t$ diagonal steps, the path crosses $\left\lfloor \frac{D(u)}{t} \right\rfloor$ even horizontal lines and the same number of odd horizontal lines, and crosses one additional odd horizontal line if $\overline{D(u)} \ge i^c$. Therefore, the formula follows.

(ii) By construction of the path, $e$ is equal to the total number of horizontal and vertical lines crossed by the path $\mathcal{L}(u)$. The expression for $e$ then follows directly from (i) and \eqref{eq: y(u)}.

(iii) 
Let $E(u)$ denote the number of $(0,1)$-steps in the path $\mathcal{L}(u)$. 
Since $\mathcal{L}(u)$ crosses $u$ vertical lines, it follows from Remark~\ref{rem: the lattice path} that
\[
E(u) = (n - t + 1) \cdot \left\lfloor \frac{u}{2} \right\rfloor +
\begin{cases}
0 & \text{if } u \text{ is even}, \\[4pt]
j^c & \text{if } u \text{ is odd}.
\end{cases}
\]
Since $y(u) = D(u) + E(u) + j$, the desired expression for $D(u)$ follows.
\end{proof}


We now state the main result of this subsection.
Recall the element $x_t$ defined in \eqref{Eq: xt}.
\begin{theorem}\label{thm: period of minuscule type A}
    When the Weyl group is of type $A_n$ and $t \in [1,n]$, we have
    \[
    \PD(x_t) = 
    \begin{cases}
        1 & \text{if } t = 1, n, \\[6pt]
        2 & \text{if } n =3 \text{ and } t = 2, \\[6pt]
        n + 1 & \text{if } n \ge 4 \text{ and } t = 2, n - 1,\\[6pt]
        \dfrac{2 (n + 1)}{\gcd(n + 1, t)} & \text{otherwise.}
    \end{cases}
    \]
\end{theorem}


\begin{proof}
Let $1 \le k \le l$, and let $(i^k, j^k) \in \lambda_t^\circ$ be the box defined in \eqref{Eq: ipjp}. Define $\xi_{i^k,j^k} := \xi_k$ and $d_{i^k,j^k}:=d_k$, where $\xi_k$ is given in Proposition~\ref{prop: period of minors determines total period} and $d_k$ is given in Lemma \ref{lem: string of qmD_bfi, k}.
Since, by Lemma~\ref{lem: type A minuscule, STR_i(d_k) frozen}, we have $\xi_{a,b} = 1$ whenever $a = t$ or $b = n - t + 1$, Proposition~\ref{prop: period of minors determines total period} says 
\[
\PD(x_t) = \lcm\{ \xi_{a,b} \mid 0 < a < t \text{ and } 0 < b < n - t + 1 \}.
\]

Let $0 < a < t$ and $0 < b < n - t + 1$.
By Lemma~\ref{lem: string of qmD_bfi, k}, we have
\begin{align}\label{eq: STR d_k}
    \STR_\bfi(d_{a,b}) = b_{a,b} = R_{(0,0),(a,b)}.
\end{align}
Let $\mathcal{P} = \{p_0, p_1, \ldots\}$ denote the sequence of points defined in this subsubsection, with initial point $p_0 = (a,b)$. 
Then, by Lemma~\ref{lem: D of path model} and~\eqref{eq: STR d_k}, the value $\xi_{a,b}$ is equal to the minimal integer $e \ge 1$ such that $\cS(p_e) \eqfr R_{(0,0),(a,b)}$.



To characterize such points $\cS(p_e)$, we analyze when a lattice point $(x,y) \in \mathcal{Z}$ satisfies $\cS(x,y) \eqfr R_{(0,0),(a,b)}$. 
This condition is equivalent to the following
\begin{equation}\label{eq: return condition}
\begin{cases}
x \equiv a \mod t, \\[2pt]
y \equiv b \mod (n - t + 1), \\[2pt]
\kappa(x,y) = (a,b).
\end{cases}
\end{equation}
If a point $(x,y) \in \mathcal{P}$ satisfies~\eqref{eq: return condition}, then there exists $u \ge 1$ such that $(x,y) = (x(u), y(u))$. 
We now determine the condition on $u$ under which $(x(u), y(u))$ satisfies~\eqref{eq: return condition}.

To proceed, we distinguish the following four types of $u$ depending on its parity and the value of $\overline{D(u)}$:
\begin{enumerate}[label=(\text{T}\alph*)]
    \item $u$ is even and $\overline{D(u)} = 0$,
    \item $u$ is even and $\overline{D(u)} = a$,
    \item $u$ is odd and $\overline{D(u)} = 0$,
    \item $u$ is odd and $\overline{D(u)} = a$.
\end{enumerate}
By inspecting the expressions for $x(u)$ and $y(u)$ given in Lemma \ref{lem: x(u) and e} (i) and~\eqref{eq: y(u)}, we deduce the following characterization for when $(x(u), y(u))$ satisfies the condition~\eqref{eq: return condition}:
\begin{equation}\label{eq: i j condition}
\begin{aligned}
&\text{If } a \ne a^c \text{ and } b \ne b^c, &&\text{then } (x(u), y(u)) \text{ satisfies } \eqref{eq: return condition} \text{ if and only if } u \text{ is of (Ta)}. \\[2pt]
&\text{If } a \ne a^c \text{ and } b = b^c, &&\text{then } (x(u), y(u)) \text{ satisfies } \eqref{eq: return condition} \text{ if and only if } u \text{ is of (Ta) or (Tc)}. \\[2pt]
&\text{If } a = a^c \text{ and } b \ne b^c, &&\text{then } (x(u), y(u)) \text{ satisfies } \eqref{eq: return condition} \text{ if and only if } u \text{ is of (Ta) or (Tb)}. \\[2pt]
&\text{If } a = a^c \text{ and } b = b^c, &&\text{then } (x(u), y(u)) \text{ satisfies } \eqref{eq: return condition} \text{ if and only if } u \text{ is of one of (Ta)--(Td)}.
\end{aligned}
\end{equation}


Note that type (Ta) arises in all four cases listed in~\eqref{eq: i j condition}. Let $d := \gcd(n - t + 1, t)$. Then the minimal value of $u$ such that $(x(u), y(u))$ is of type (Ta) is
\begin{equation}\label{eq: minimal u case a}
u = 2 \cdot \frac{t}{d}.
\end{equation}

We now analyze the following cases:

\smallskip
\noindent
\textbf{Case 1.} Suppose $t = 1$ or $t = n$. In this case, no mutable variable appears, and hence $\PD(x_t) = 1$.


%\smallskip
\noindent
\textbf{Case 2.} 
Suppose $n \ge 4$ and $2 < t < n - 1$. 
Then the pair $(a,b) = (1,1)$ satisfies $a \ne a^c$ and $b \ne b^c$. 
For this pair, the minimal value of $u$ such that $(x(u), y(u))$ satisfies the condition~\eqref{eq: return condition} is given by~\eqref{eq: minimal u case a}, due to~\eqref{eq: i j condition}.
By Lemma~\ref{lem: x(u) and e}~(ii) and (iii), if $p_e = (x(u), y(u))$, then
\[
e = 2 \cdot \frac{t}{d} + 2 \cdot \frac{n - t + 1}{d} = 2 \cdot \frac{n + 1}{d},
\]
which is the minimal integer such that $\cS(p_e) \eqfr R_{(0,0),(1,1)}$. 
Hence, we obtain $\xi_{1,1} = 2 \cdot \frac{n + 1}{d}$.


For all other pairs $(a,b) \ne (1,1)$, 
$\cdual^{\xi_{1,1}} (d_{a,b}) \eqfr d_{a,b}$  by~\eqref{eq: i j condition}
since type (Ta) appears in every case.
Thus the values $\xi_{a,b}$ divide $2 \cdot \frac{n + 1}{d}$, which says 
\[
\PD(x_t) = 2 \cdot \frac{n + 1}{d}.
\]
Finally, since $d = \gcd(n - t + 1, t) = \gcd(n + 1, t)$, the claim follows.

%\smallskip
\noindent
\textbf{Case 3.} Suppose $n \ge 4$ and $t = 2$. 
Then every pair $(a,b)$ satisfies $a = a^c = 1$. 
In particular, the pair $(a,b) = (1,1)$ satisfies $b \ne b^c$, since $n - t + 1 \ge 3$.
For this pair, the minimal value of $u$ such that $(x(u), y(u))$ satisfies the condition~\eqref{eq: return condition} is determined as follows:
\begin{itemize}
    \item If $n$ is odd, then type (Ta) yields $u = 2$, while type (Tb) does not occur.
    \item If $n$ is even, then type (Ta) yields $u = 4$, while type (Tb) yields $u = 2$.
\end{itemize}
In either case, the minimal $u$ is $2$. 
By Lemma~\ref{lem: x(u) and e}~(ii) and (iii), if $p_e = (x(2), y(2))$, then $e = 2 + (n - 1) = n + 1$, so $\xi_{1,1} = n + 1$.

For all other pairs $(a,b) \ne (1,1)$, we again have $\xi_{a,b} \mid n + 1$ by~\eqref{eq: i j condition}. 
Therefore,
\[
\PD(x_t) = n + 1.
\]


%\smallskip
\noindent
\textbf{Case 4.} Suppose $n \ge 4$ and $t = n - 1$. This is analogous to Case~3, and again we obtain $\PD(x_t) = n + 1$.

%\smallskip
\noindent
\textbf{Case 5.} Suppose $n = 3$ and $t = 2$. A direct computation using Lemma~\ref{lem: D of path model} shows that $\PD(x_t) = 2$.

%\smallskip
This completes the proof.
\end{proof}


\begin{remark} \label{rem: periodicity for A}
When $\g$ is of type $A_n$, the quantum unipotent coordinate ring $\qA_q(\n(x_t))$ can be understood as a quantum-analogue of the coordinate ring of the Grassmannian $\Gr(t, n+1)$ of $t$-dimensional subspaces in an $(n+1)$-dimensional space (see \cite{GLS08}). In Grassmannian cluster categories, the twist automorphism $\eta_{x_t}$ can be interpreted in terms of Auslander-Reiten translations and there is a result on its finite periodicity (\cite[Section 3.5]{Baur21}). Thus Theorem \ref{thm: period of minuscule type A} recovers the finite periodicity result \cite[Proposition 3.15]{Baur21} in terms of crystals. This periodicity is also related to Keller's result \cite{Keller13} on the periodicity conjecture (see \cite[Remark 3.16]{Baur21}). 
\end{remark}


\subsection{Further observations} \label{Sec: FO}
In this subsection, we assume that $\g$ is of finite type. 
Based on Theorem \ref{Thm: main}, one can compute $\cdual_w$ for arbitrary elements $w \in \weyl$ using \textsc{SageMath}~\cite{sage}. In this subsection, we present a collection of conjectures on the periodicity $\PD(w)$, motivated by patterns observed in the computational data.

\subsubsection{Minuscule or cominuscule cases}
For general finite type, we define a subset $I_{\mathrm{MC}} \subset I$ consisting of indices that are either minuscule or cominuscule:
\begin{align*}
    I_{\mathrm{MC}} = 
    \begin{cases}
        I & \text{if the Weyl group is of type $A_n$}, \\
        \{ 1, n \} & \text{if the Weyl group is of type $B_n$ or $C_n$}, \\
        \{ 1, n-1, n \} & \text{if the Weyl group is of type $D_n$}, \\
        \{ 1, 6 \} & \text{if the Weyl group is of type $E_6$}, \\
        \{ 7 \} & \text{if the Weyl group is of type $E_7$}, \\
        \emptyset & \text{if the Weyl group is of type $E_8$, $F_4$, or $G_2$}.
    \end{cases}
\end{align*}
We call an index $t \in I_{\mathrm{MC}}$ a \emph{minuscule or cominuscule index}.  
For type $A$, Theorem~\ref{thm: period of minuscule type A} determines $\PD(x_t)$ for all such $t$.  
For other types, we conjecture the following values of $\PD(x_t)$ based on computational data.


\begin{conjecture}
    Let $t \in I$. Then $\PD(x_t)$ is finite if and only if $t \in I_{\mathrm{MC}}$.  
Moreover, if $t \in I_{\mathrm{MC}}$, then the following hold:
    \bni
        \item When the Weyl group is of type \( B_n \) or \( C_n \):
        \begin{enumerate}
            \item If \( t = 1 \), then \(\PD(x_1) = 2\).
            \item If \( t = n \), then
            $
            \PD(x_t) = 
            \begin{cases}
                2 & \text{if } n = 2, \\[6pt]
                4 & \text{otherwise}.
            \end{cases}
            $
        \end{enumerate}

        \item When the Weyl group is of type \( D_n \):
        \begin{enumerate}
            \item If \( t = 1 \), then \(\PD(x_1) = 2\).
            \item If \( t \in \{ n-1, n \} \), then
            $
            \PD(x_t) = 
            \begin{cases}
                2 & \text{if } n = 4, \\[6pt]
                8 & \text{if } n \text{ is odd}, \\[6pt]
                4 & \text{otherwise}.
            \end{cases}
            $
        \end{enumerate}

        \item When the Weyl group is of type \( E_6 \) and \( t \in \{1, 6\} \), we have \(\PD(x_t) = 6\).

        \item When the Weyl group is of type \( E_7 \) and \( t = 7 \), we have \(\PD(x_t) = 4\).
    \ee
\end{conjecture}
This conjecture is supported by computations using \textsc{SageMath}. For all types $B_n$, $C_n$, $D_n$, $E_6$, and $E_7$ with rank $n \le 10$, we have verified that $\PD(x_t)$ agrees with the stated values when $t \in I_{\mathrm{MC}}$, and that $\PD(x_t) > 1000$ when $t \notin I_{\mathrm{MC}}$.

\subsubsection{Coxeter element cases}
We investigate the periodicity of a certain Coxeter element. We write $I = I_o \sqcup I_e$ such that $a_{i,j} = 0$ for all $i \in I_o$ and $j \in I_e$, and define the Coxeter element
\[
c := \left(\prod_{i\in I_o} s_i\right) \left(\prod_{j\in I_e} s_j \right) \in \weyl
\]
We now consider two classes: class $(A)$ consists of types $A_n$, $D_n$ (with $n$ odd), and $E_6$, and class $(B)$ consists of types $B_n$, $C_n$, $D_n$ (with $n$ even), $F_4$, and $G_2$.

\begin{conjecture}
Let $m \in \mathbb{Z}_{>0}$ be such that $m \cdot \ell(c) \le \ell(w_\circ)$. Then
\[
\PD(c^m) = 
\begin{cases}
h+m & \text{if } m = 2 \text{ and } \weyl \text{ is in class } (A), \\[6pt]
\dfrac{2(h+m)}{\gcd(h,m)} & \text{if } m > 2 \text{ and } \weyl \text{ is in class } (A), \\[6pt]
\dfrac{h+m}{2} & \text{if } m = 2 \text{ and } \weyl \text{ is in class } (B), \\[6pt]
\dfrac{h+m}{\gcd(h/2, m)} & \text{if } m > 2 \text{ and } \weyl \text{ is in class } (B),
\end{cases}
\]
where $h$ is the Coxeter number of $W$. 
\end{conjecture}
This conjecture has also been confirmed using \textsc{SageMath} for all types of rank $n \le 10$, in agreement with the previous conjecture.


