	\title{The Logarithmic Laplacian on General Graphs}

	\author{Rui Chen}
	\address{School of Mathematical Sciences, Fudan University, Shanghai 200433, China}
	\email{chenrui23@m.fudan.edu.cn}

	\author{Wendi Xu}
	\address{Shanghai Institute for Mathematics and Interdisciplinary Sciences, Shanghai 200082, China}
	\email{xuwendi@simis.cn}


\begin{abstract}
	We introduce a Bochner integral formula of the logarithmic Laplacian on weighted graphs and derive its pointwise representation under stochastic completeness:
{\scriptsize
	\[
	\log(-\Delta)u(x)
	=\frac{1}{\mu(x)}\sum_{y\neq x}W_{\log}(x,y)\,(u(x)-u(y))
	-\frac{1}{\mu(x)}\sum_{y}W(x,y)\,u(y)
	+\Gamma'(1)\,u(x).
	\]
}On weighted lattice graphs with uniformly positive vertex weights, we establish sharp estimates for the log‐kernel, show that \(\log(-\Delta)\) is unbounded on \(\ell^2\), and give an alternative proof of the above pointwise representation.  We also prove strong \(\ell^p\) (\(1<p\le\infty\)) convergence of the difference quotients \(\bigl((-\Delta)^s - I\bigr)/s\) to \(\log(-\Delta)\). Finally, on the lattice $\mathbb{Z}^d$, we explicitly compute the Fourier multipliers associated with both the fractional and logarithmic Laplacians. We then determine the precise large-time behavior and off-diagonal asymptotics of their corresponding diffusion kernels, along with the exact asymptotic constants.
\end{abstract}

\begin{abstract}
We are the first to present a Bochner integral representation of the logarithmic Laplacian on weighted graphs and to derive, under the assumption of stochastic completeness, its explicit pointwise form:
{\scriptsize
	\[
	\log(-\Delta)u(x)
	=\frac{1}{\mu(x)}\sum_{y\neq x}W_{\log}(x,y)\,(u(x)-u(y))
	-\frac{1}{\mu(x)}\sum_{y}W(x,y)\,u(y)
	+\Gamma'(1)\,u(x).
	\]
}For weighted lattice graphs with uniformly positive vertex measures, we establish sharp upper and lower bounds for the associated log‐kernel, prove that \(\log(-\Delta)\) fails to be bounded on \(\ell^2\), and offer an alternative derivation of the above formula.  Moreover, we show that for $u\in C_c\left(\mathbb{Z}^d\right)$
{\scriptsize	\[
	\frac{(-\Delta)^su - u}{s}
	\;\longrightarrow\;
	\log(-\Delta)u
	\quad\text{strongly in }\ell^p,\quad 1<p\le\infty,\quad s\to0^+.
	\]}Finally, on the integer lattice \(\mathbb{Z}^d\), we compute the Fourier multipliers of both the fractional and logarithmic Laplacians, and derive the exact large-time behavior and off-diagonal asymptotics of their heat kernels, including all sharp asymptotic constants.
\end{abstract}



