\section{Enlargements and Saturation}
\fancyhead[LO]{Enlargements and Saturation}
\subsection{Definitions and Basic Properties}

Throughout this section, assume that $*:\mathbb U\to\mathbb V$ is a transfer map for a set $X$.



%\begin{definition}\label{defn_enlargement_saturation}\rm 
%Suppose that $\kappa$ is a cardinal.
%\begin{enumerate}[(i)]\item $*:\mathbb U\to\mathbb V$ is a $\kappa$-{\em enlargement} iff whenever $\mathcal A\subseteq\mathbb U$ is a family of sets of cardinality $<\kappa$ such that $\mathcal A$ has the f.i.p., then $\bigcap {}^\sigma\mathcal A=\bigcap\{{}^*A:A\in\mathcal A\}$ is non-empty.\\
%$*$ is an {\em enlargement} if it is a $|\mathbb U|^+$-enlargement, or, what is equivalent, if it is a  $\kappa$-enlargement for any cardinal $\kappa$.
%\item $*:\mathbb U\to\mathbb V$ is $\kappa$-{\em saturated} iff whenever $\mathcal B\subseteq {}^*\mathbb U$ is a family of internal sets of cardinality $<\kappa$ such that $\mathcal B$ has the f.i.p., then $\bigcap\mathcal B\neq \varnothing$.\\
%$*$ is {\em polysaturated} if it is $|\mathbb U|^+$-saturated.
%\end{enumerate}\endbox
%\end{definition}
Recall Convention \ref{convention_expanded_language}.
Let $\mathcal L_{\mathbb U}$ denote the expansion of the langue $\mathcal L_\in$ (or some expansion thereof) with additional constant symbols for element of $\mathbb U$. Similarly, let $\mathcal L_{{}^*\mathbb U}$ denote the expansion with constant symbols for every internal set.

Recall also that a family $\mathcal A$ of sets has the {\em finite intersection property} (f.i.p.) if and only if the intersection of any finitely many members of $\mathcal A$ is non-empty.

\begin{definition}\label{defn_enlargement_saturation}\rm 
Suppose that $\kappa$ is an infinite cardinal.
\begin{enumerate}[(i)]\item $*:\mathbb U\to\mathbb V$ is a $\kappa$-{\em enlargement} if and only if for every set $\Sigma(x)$ of $<\kappa$-many bounded formulas of $\mathcal L_{\mathbb U}$, if $\Sigma(x)$ is finitely satisfiable in $\mathbb U$ by elements of some set  $T\in\mathbb U$, then $\Sigma(x)$ is satisfiable in $\mathbb V$ by an element of $^*\mathbb U$.\\
$*$ is an {\em enlargement} if it is a $|\mathbb U|^+$-enlargement, or, what is equivalent, if it is a  $\kappa$-enlargement for any cardinal $\kappa$.
\item $*:\mathbb U\to\mathbb V$ is $\kappa$-{\em saturated}  if and only if for every set $\Sigma(x)$ of $<\kappa$-many bounded formulas of $\mathcal L_{{}^*\mathbb U}$, if $\Sigma(x)$ is finitely satisfiable in $\mathbb V$ by elements of some set  $T\in{}^*\mathbb U$, then $\Sigma(x)$ is satisfiable in $\mathbb V$ by an element of $^*\mathbb U$.\\
$*$ is {\em polysaturated} if it is $|\mathbb U|^+$-saturated.
\end{enumerate}\endbox
\end{definition}

\begin{theorem}\label{thm_enlargement_saturation_intersection}
\begin{enumerate}[(a)]\item $*:\mathbb U\to\mathbb V$ is a $\kappa$-{\em enlargement} if and only if whenever $\mathcal A\subseteq\mathbb U$ is a family of sets of cardinality $<\kappa$ such that $\mathcal A$ has the f.i.p., then $\bigcap {}^\sigma\mathcal A=\bigcap\{{}^*A:A\in\mathcal A\}$ is non-empty.
\item $*:\mathbb U\to\mathbb V$ is $\kappa$-{saturated} if and only if whenever $\mathcal A\subseteq {}^*\mathbb U$ is a family of internal sets of cardinality $<\kappa$ such that $\mathcal A$ has the f.i.p., then $\bigcap\mathcal A$ is non-empty.
\end{enumerate}
\end{theorem}

\bproof 
(a) Suppose first that $*:\mathbb U\to\mathbb V$ is a $\kappa$-enlargement, and that $\mathcal A:=\{A_\beta:\beta<\alpha\}\subseteq\mathbb U$ is a family of sets of cardinality $<\kappa$ such that $\mathcal A$ has the f.i.p. By replacing each $A_\beta$ by $A_\beta\cap A_0$ we may without loss of generality assume that each $A_\beta\subseteq A_0$ --- This does not affect the f.i.p. nor the intersection of all the $A_\beta$.  Let $\Sigma(x):=\{\sigma_\beta(x):\beta<\alpha\}$, where $\sigma_\beta(x)\equiv x\in A_\beta$. Then $\Sigma(x)$ is a set of $<\kappa$-many bounded formulas of $\mathcal L_{\mathbb U}$ which is finitely satisfiable by elements of $A_0$. Hence $\Sigma(x)$ is satisfiable in $\mathbb V$ by an element of $^*\mathbb U$. Thus there is $a\in {}^*\mathbb U$ such that $a\in {}^*A_\beta$ for all $\beta<\alpha$, so that $\bigcap{}^\sigma\mathcal A\neq \varnothing$.

For the reverse direction,  suppose we have a set $\Sigma(x)=\{\sigma_\beta(x):\beta<\alpha\}$ of $<\kappa$-many bounded formulas of $\mathcal L_{\mathbb U}$, and that $\Sigma(x)$ is finitely satisfiable in $\mathbb U$ by elements of some set  $T\in\mathbb U$. Let $A_\beta:=\{t\in T: \mathbb U\vDash \sigma_\beta(t)\}$. As $\Sigma(x)$ is finitely satisfiable, the family $\mathcal A:=\{A_\beta:\beta<\alpha\}$ has the f.i.p. If $s\in\bigcap{}^\sigma\mathcal A$, then $s\in {}^*\mathbb U$. As $\mathbb U\vDash \forall x\in A_\beta(\sigma_\beta(x))$, we have $\mathbb V\vDash \forall x\in {}^*A_\beta(\sigma_\beta(x))$ so that $\mathbb V\vDash \Sigma(s)$.

(b) Suppose first that $*:\mathbb U\to\mathbb V$ is $\kappa$-saturated, and that $\mathcal A:=\{A_\beta:\beta<\alpha\}\subseteq{}^*\mathbb U$ is a family of internal sets of cardinality $<\kappa$ such that $\mathcal A$ has the f.i.p. By replacing each $A_\beta$ by $A_\beta\cap A_0$ we may without loss of generality assume that each $A_\beta\subseteq A_0$ --- This does not affect the f.i.p. nor the intersection of all the $A_\beta$.  Let $\Sigma(x):=\{\sigma_\beta(x):\beta<\alpha\}$, where $\sigma_\beta(x)\equiv x\in A_\beta$. Then $\Sigma(x)$ is a set of $<\kappa$-many bounded formulas of $\mathcal L_{{}^*\mathbb U}$ which is finitely satisfiable by elements of $A_0$. Hence $\Sigma(x)$ is satisfiable in $\mathbb V$ by an element of $^*\mathbb U$. Thus there is $a\in {}^*\mathbb U$ such that $a\in A_\beta$ for all $\beta<\alpha$, so that $\bigcap\mathcal A\neq \varnothing$.


For the reverse direction,  suppose we have a set $\Sigma(x)=\{\sigma_\beta(x):\beta<\alpha\}$ of $<\kappa$-many bounded formulas of $\mathcal L_{{}^*\mathbb U}$, and that $\Sigma(x)$ is finitely satisfiable in $\mathbb V$ by elements of some set  $T\in{}^*\mathbb U$. Let $A_\beta:=\{t\in T:  \sigma_\beta(t)\}$. By the internal definition principle, each $A_\beta$ is internal. As $\Sigma(x)$ is finitely satisfiable by members of $T$, the family $\mathcal A:=\{A_\beta:\beta<\alpha\}$ has the f.i.p. If $s\in\bigcap\mathcal A$, then $s\in {}^*\mathbb U$, and  $\mathbb V\vDash \Sigma(s)$.
\eproof 

Note that we do  not demand that $\mathcal A\in\mathbb U$ in (a), or that $\mathcal A\in\mathbb V$ in (b) of Theorem \ref{thm_enlargement_saturation_intersection}. However:

\begin{theorem} \label{thm_fip_element} To verify that a transfer map $*:\mathbb U\to\mathbb V$ for a set $X$ is a $\kappa$-enlargement, it suffices to consider sets $\mathcal A\in\mathbb U$ in (a)  of of Theorem \ref{thm_enlargement_saturation_intersection}.
\\To verify that a transfer map $*:\mathbb U\to\mathbb V$ for a set $X$ is $\kappa$-saturated, it suffices to consider sets  $\mathcal A$ which are subsets of standard sets --- and thus in $\mathbb V$ --- in (b) of of Theorem \ref{thm_enlargement_saturation_intersection}.
\end{theorem}

\bproof Suppose that $*$ satisfies (i) of Definition \ref{defn_enlargement_saturation} for sets $\mathcal A\in\mathbb U$. Let $\mathcal A'\subseteq\mathbb U$ be a set of cardinality $<\kappa$ which satisfies the f.i.p. Choose $A_0\in\mathcal A'$, and let $\mathcal A:=\{A\cap A_0:A\in\mathcal A'\}$. Observe that $|\mathcal A|<\kappa$, that $\mathcal A$ satisfies the f.i.p. as well, and that since $\mathcal A\subseteq\mathcal P(A_0)$ we have $\mathcal A\in\mathbb U$. By assumption, $\bigcap{}^\sigma\mathcal A\neq \varnothing$. Now as ${}^*(A\cap A_0)\subseteq {}^*A$ for all $A\in\mathcal A'$, we have $\varnothing\neq \bigcap {}^\sigma\mathcal A=\bigcap{}^\sigma\mathcal A'$.

Next, suppose that $*$ satisfies (ii) of Definition \ref{defn_enlargement_saturation} for $\mathcal B\subseteq {}^*\mathcal A$, where $\mathcal A\in\mathbb U$.  Let $\mathcal B'\subseteq{}^*\mathbb U$ be a family of internal sets of cardinality $<\kappa$ which satisfies the f.i.p. Choose $B_0\in\mathcal B'$, and let $\mathcal B:=\{B\cap B_0:B\in\mathcal B'\}$. Observe that $|\mathcal B|<\kappa$, that $\mathcal B$ has the f.i.p. also, and that  $\mathcal B\subseteq {}^*\mathbb U\cap \mathcal P(B_0)$. By Lemma \ref{lemma_internal_subsets},  $P:={}^*\mathbb U\cap \mathcal P(B_0)$ is internal, and hence there is some transitive $\mathcal A\in\mathbb U$ such that $P\in{}^*\mathcal A$. Then also $\mathcal B\subseteq {}^*\mathcal A$, and hence by assumption we have that $\bigcap\mathcal B\neq 0$. Hence $\varnothing\neq \bigcap\mathcal B=\bigcap\mathcal B'$.
\eproof

\begin{remark}\rm It follows from Theorem \ref{thm_enlargement_equiv} that $*:\mathbb U\to\mathbb V$ is an enlargement if and only if it is a $|\mathbb U|$-enlargement, as $\mathcal A\in\mathbb U$ implies $|\mathcal A|<|\mathbb U|$.\endbox
\end{remark}

Suppose that $B\in{}^*\mathbb U$ is an infinite internal set. Then for $b\in B$, the set $B_b:=\{c\in B:c\neq b\}$ $= B-\{b\}$ is internal, by the internal definition principle and the transitivity of ${}^*\mathbb U$. Clearly $\mathcal B:=\{B_b:b\in B\}$ has the f.i.p., yet $\bigcap\mathcal B=\varnothing$. Hence $*$ cannot be a $|B|^+$-saturated extension. In particular, if $*:\mathbb U\to\mathbb V$ is a  $\kappa$-saturated transfer map for an infinite set $X$ of atoms, then necessarily $|{}^*X|\geq\kappa$.
It is therefore impossible to find an extension which is $\kappa$-saturated for every cardinal $\kappa$.

The above argument also shows that:
\begin{proposition} If  $*:\mathbb U\to\mathbb V$ is $\kappa$-saturated and $B\in\mathbb V$ has cardinality $|B|<\kappa$, then $B$ is external.
\endbox
\end{proposition}

\begin{lemma}\label{lemma_polysaturated_implies_enlargement} If $*:\mathbb U\to\mathbb V$ is $\kappa$-saturated, it is a $\kappa$-enlargement. Hence a polysaturated extension is an enlargement.
\end{lemma}
\bproof If $\mathcal A\subseteq\mathcal U$ is a family of sets with the f.i.p., then $\mathcal B:={}^\sigma\mathcal A$ is a family of internal  (indeed, standard) sets with the f.i.p. For, given $A_1,\dots, A_n\in\mathcal A$, transfer of the  bounded sentence $\exists x\in A_1(x\in A_2\land\dots\land x\in A_n)$ shows that ${}^*A_1\cap\dots\cap{}^*A_n\neq \varnothing$. Clearly $|\mathcal B|=|\mathcal A|$.\eproof


\subsection{Enlargements, Concurrency and Hyperfinite Approximation}


\begin{theorem} A  transfer map $*:\mathbb U\to\mathbb V$ for an infinite set $X$ is $\omega_1$-enlargement if and only if it is a nonstandard embedding.

\end{theorem}
\bproof $(\Rightarrow)$: Suppose that $*$ is an $\omega_1$-enlargement. To show that $*$ is a nonstandard embedding, it suffices to show that there is a countable $C\in\mathbb U$ such that ${}^\sigma C\subsetneqq {}^*C$. So let $C\subseteq X$ be countable. Since $\mathcal P(X)\in\mathbb U$ and $\mathbb U$ is transitive, we have $C\in\mathbb U$. Let $\mathcal C:=\{C-\{c\}:c\in C\}$. Then $\mathcal C$ has the f.i.p. and $|\mathcal C|<\omega_1$, so $\bigcap {}^\sigma\mathcal C\neq \varnothing$. Pick $c_0\in \bigcap {}^\sigma\mathcal C$. Then $c_0\in {}^*(C-\{c\})={}^*C-\{{}^*c\}$ for every $c\in C$. Hence $c_0\in {}^*C-{}^\sigma C$.

$(\Leftarrow)$: Now assume that $*$ is a nonstandard embedding. Let $\mathcal A\subseteq \mathbb U$ be a family of sets with the f.i.p. such that $|\mathcal A|<\omega_1$, i.e. $|\mathcal A|$ is countable. Let $\mathcal A=\{A_1,A_2,\dots\}$ be an enumeration of $\mathcal A$. Without loss of generality (by renaming elements if necessary), we may assume that $\mathbb N\subseteq X$. Let $f:\mathbb N\twoheadrightarrow\mathcal P(A_1):n\mapsto\bigcap_{k\leq n}A_k$. Then $f\in\mathbb U$, and $\varnothing\not\in \text{ran} f$. By transfer, $\varnothing\not\in \text{ran}\,{}^*f$, since ${}^*\varnothing =\varnothing$ and ${}^*(\text{ran} f)= \text{ran}\,{}^*f$. In particular, for all $n\in {}^*\mathbb N$, ${}^*f(n)\neq \varnothing$.  
Now fix an arbitrary $n\in\mathbb N$, and note that \[\mathbb U\vDash\forall m\in \mathbb N\;(m>n\to f(m)\subseteq A_n).\] By transfer
\[\mathbb V\vDash \forall m\in {}^*\mathbb N\;(m>n\to {}^*f(m)\subseteq {}^*A_n).\] (Recall ${}^*x=x$ for all $x\in X$, and thus ${}^*n=n$.)
Since $*$ is a nonstandard embedding, it follows from Theorem \ref{thm_nonstandard_framework_nonstandard_elements} that there exists $m_0\in {}^*\mathbb N-{}^\sigma\mathbb N$ for which we have both ${}^*f(m_0)\neq \varnothing$ and $m_0\geq n$. It follows that ${}^*f(m_0)\subseteq {}^*A_n$. Since $n\in\mathbb N$ was arbitrary, we have that $\varnothing\neq  f(m_0)\subseteq\bigcap_{n\in\mathbb N} {}^*A_n=\bigcap{}^\sigma \mathcal A$. This shows that $*$ is an $\omega_1$-enlargement.
\eproof


As a corollary we immediately see that:
\begin{corollary}
Every enlargement, and hence every polysaturated extension, is a nonstandard embedding.\endbox
\end{corollary}


\begin{definition}\rm A binary relation $R$ is {\em concurrent} if and only if for every finite $\{x_1,\dots, x_n\}\subseteq\dom(R)$ there is $y\in \ran(R)$ such that $x_iRy$ for all $i=1,\dots, n$.\endbox
\end{definition}

For a set $A$, and  important example of a concurrent relation is the set \[R:=\{(a,F): a\in F\in\mathcal P^{<\omega}(A)\}.\] Indeed, given $a_1,\dots, a_n\in A=\dom(R)$, we can define $F:=\{a_1,\dots, a_n\}$, and then observe that $a_iRF$ for all $i=1,\dots, n$.

\begin{theorem}\label{thm_enlargement_equiv} Suppose that $*:\mathbb U\to \mathbb V$ is a transfer map for a set $X$. Then the following are equivalent: 
\begin{enumerate}[(i)]\item $*:\mathbb U\to \mathbb V$ is a $\kappa$-enlargement.
\item For every concurrent binary relation $R\in\mathbb U$ with $|\dom(R)|<\kappa$ there is $y_0\in
\mathbb V$ such that ${}^*x({}^*R)y_0$ for all $x\in \dom(R)$.
\item (Hyperfinite Approximation) For each set $A\in \mathbb  U$ with $|A|<\kappa$ there is a hyperfinite subset $B$ of ${}^*A$ which contains all the standard members of ${}^*A$, i.e.\[{}^\sigma A\subseteq B\in {}^*\mathcal P^{<\omega}(A).\]
\end{enumerate}
\end{theorem}

\bproof
(i) $\Rightarrow$ (ii): Suppose $|\dom(R)|<\kappa$. For $x\in \dom(R)$, let $A_x:=\{y\in \ran(R): xRy\}$, and let $\mathcal A:=\{A_x:x\in\dom(R)\}$. Then $\mathcal A\subseteq\mathcal P(\ran(R))$, so $\mathcal A\in\mathbb  U$. Since $R$ is concurrent, $\mathcal A$ has the f.i.p. In addition $|\mathcal A|<\kappa$. Since $*$ is a $\kappa$-enlargement, there is $y_0\in\bigcap {}^\sigma\mathcal A$. Then $y_0\in {}^*A_x$ for all $x\in\dom(R)$. Now $\mathbb U\vDash \forall y\in A_x\;(xRy)$, so by transfer we have $\mathbb V\vDash \forall y\in{}^*A_x\;({}^*x({}^*R)y)$. It follows that ${}^*x({}^*R)y_0$ for all $x\in \dom(R)$.\\
(ii)$\Rightarrow$ (iii): Given a set $A\in\mathbb U$ with $|A|<\kappa$, define the concurrent relation $R$ by  \[R:=\{(a,F): a\in F\in\mathcal P^{<\omega}(A)\}.\] Then $|\dom(R)|<\kappa$, so by assumption, there is $B\in\mathbb V$ such that  ${}^*a({}^*R)B$ --- i.e. such that ${}^*a\in B$  --- for all $a\in A$. Thus ${}^\sigma A\subseteq B$. Now as $B\in \ran({}^*R)$, and since $\ran(R)\subseteq\mathcal P^{<\omega}(A)$, we have that $\ran({}^*R)\subseteq {}^*\mathcal P^{<\omega}(A)$, so that $B\in {}^*\mathcal P^{<\omega}(A)$.\\
(iii) $\Rightarrow$ (i):  Let $\mathcal A\in \mathbb U$ have the f.i.p. with $|\mathcal A|<\kappa$, and let $T\in\mathbb U$ be transitive so that $\mathcal A\subseteq T$. Then $A\subseteq T$ for all $A\in\mathcal A$, and hence \[\mathbb U\vDash\forall \mathcal F\in\mathcal P^{<\omega}(\mathcal A)\;\exists x\in T\;\forall A\in\mathcal F\;(x\in A).\] By assumption, there is a hyperfinite $\mathcal B\subseteq {}^*\mathcal A$ such that ${}^\sigma\mathcal A\subseteq \mathcal B$. Then by transfer, with $\mathcal F=\mathcal B\in {}^*\mathcal P^{<\omega}(\mathcal A)$, there is $x\in {}^*T$ such that $x\in A$ for all $A\in\mathcal B$. In particular, $x\in {}^*A$ for all $A\in\mathcal A$.
\eproof

\subsection{Saturation and Concurrency}\label{section_saturation}

\begin{theorem}\label{thm_saturation_concurrency} Suppose that $*:\mathbb U\to \mathbb V$ is a nonstandard transfer map.
Then the following are equivalent:
\begin{enumerate}[(i)]\item $*:\mathbb U\to \mathbb V$ is $\kappa$-saturated.
\item For every {\em internal} concurrent binary relation $R\in\mathbb V$ with and every (internal or external) $A\subseteq \dom(R)$ with  $|A|<\kappa$,  there is $y_0\in
\mathbb V$ such that $xRy_0$ for all $x\in A$.
\end{enumerate}
\end{theorem}

\bproof
(i) $\Rightarrow$ (ii): Suppose that $R\in\mathbb V$ is an internal concurrent relation, and that $A\subseteq\dom(R)$ is such that $|A|<\kappa$. For each $x\in A$, let $A_x:=\{y\in \ran(R): xRy\}$. By the internal definition principle, each $A_x$ is internal. Put $\mathcal A:=\{A_x:x\in A\}$, so that $\mathcal A$ is a family of internal sets with $|\mathcal A|<\kappa$. Since $R$ is concurrent, $\mathcal A$ has the f.i.p. By $\kappa$-saturation, there is $y_0\in\bigcap \mathcal A$. Then $y_0\in A_x$ for all $x\in A$, i.e. $xRy_0$ holds for all $x\in A$.

(ii) $\Rightarrow$ (i): Suppose that $\mathcal A$ is a family of internal sets with the f.i.p., where $|\mathcal A|<\kappa$. We must show that $\bigcap\mathcal A\neq\varnothing$. Fix $A_0\in \mathcal A$. By replacing each $A\in\mathcal A$ by $A\cap A_0$, we may assume that $A\subseteq A_0$ for each $A\in\mathcal A$. Thus $\mathcal A\subseteq \mathcal P(A_0)\cap{}^*\mathbb U$.  By Lemma \ref{lemma_internal_subsets_internal}, $P(A_0)\cap{}^*\mathbb U$ is an internal set. Consider the relation
\[R:=\{(A,a)\in(P(A_0)\cap{}^*\mathbb U)\times A_0: a\in A\}.\]
By the internal definition principle, $R$ is internal. Now $\mathcal A\subseteq \dom(R)$, as each $A\in\mathcal A$ is non-empty (by the f.i.p.). Hence there is $a_0\in\mathbb V$ such that $(A,a_0)\in R$ for all $A\in\mathcal A$. But then $a_0\in\bigcap\mathcal A$.
\eproof


\subsection{Comprehensiveness}\label{section_comprehensiveness}

\begin{definition}\label{defn_comprehensiveness}\rm Let $\kappa$ be an infinite cardinal. A transfer map $*:\mathbb U \to\mathbb V$ is said to be {\em $\kappa$-comprehensive} if and only if for any sets $A,B\in\mathbb U$ such that $|A|<\kappa$, and any map $f:A\to {}^*B$, there is an {\em internal} function ${}^+\!f:{}^*A\to {}^*B$ with the property that ${}^+\!f({}^*a)=f(a)$ for all $a\in A$.\\
$*:\mathbb U \to\mathbb V$ is said to be {\em comprehensive} if and only if it is $\kappa$-comprehensive for every cardinal $\kappa$, or equivalently, if it is $|\mathbb U|^+$--comprehensive.\\
$*:\mathbb U \to\mathbb V$ is said to be {\em countably  comprehensive} if and only if it is $\omega_1$-comprehensive. \endbox\end{definition}

Here is a small improvement:
\begin{proposition}\label{propn_comprehensiveness} If a transfer map $*:\mathbb U \to\mathbb V$ is $\kappa$-comprehensive, then for any set $A\in\mathbb U$ of cardinality $|A|<\kappa$, and any {\em internal} set $B\in \mathbb V$, if $f:A\to B$, then there  is an {\em internal} function ${}^+\!f:{}^*A\to B$ with the property that ${}^+\!f({}^*a)=f(a)$ for all $a\in A$.
\end{proposition}

\bproof
Suppose that  $f:A\to B$, where $A\in\mathbb U$ and that $B\in \mathbb V$ is internal. Let $T\in\mathbb U$ be transitive such that $B\in {}^*T$. Since ${}^*T$ is transitive, we have that $B\subseteq {}^*T$, so that $f:A\to {}^*T$. By definition of comprehensiveness, there is an internal function ${}^+\!g:{}^*A\to {}^*T$ such that ${}^+\!g({}^*a)=f(a)$ for all $a\in A$. Choose an arbitrary $b_0\in B$, and define 
%\[{}^+\!f=\Big({}^+\!g\cap {}^*A\times B\Big) \cup\big \{(a,b)\in {}^*A\times B: \exists c\in {}^*T-B((a,c)\in {}^+\!g)\land b=b_0\big\}.\]
\[{}^+\!f:=\Big\{(a,b)\in {}^*A\times B: \exists c\in{}^*T\;\Big((a,c)\in{}^+\!g\land(c\in B\to b=c)\land (c\in {}^*T-B\to b=b_0)\Big)\Big\}.\]
By Lemmas \ref{lemma_define_simple_notions}, \ref{lemma_internal_preservation} and the internal definition principle, ${}^+\!f$ is internal.  Moreover, if $a\in {}^*A$, then if ${}^+\!g(a)\in B$, we have $(a,{}^+\!g(a))\in {}^+\!f$, whereas if ${}^+\!g(a)\in {}^*T-B$, then $(a, b_0)\in {}^+\!f$. Thus ${}^+\!f$ is an internal function ${}^+\!f:{}^*A\to B$. Finally, if $a\in A$, then ${}^+\!g({}^*a)=f(a)\in B$, and hence $({}^*a, {}^+g({}^*a))\in {}^+\!f$, i.e. ${}^+\!f({}^*a)=f(a)$ when $a\in A$.
\eproof

The most useful application of comprehensiveness is in the countable case:
\begin{corollary} Suppose that $*:\mathbb U \to\mathbb V$ is a countably comprehensive transfer map, where $\mathbb U$ is a universe over a set $X$ that contains $\mathbb N$. Suppose also that  $B$ is internal and that $(b_n:n\in\mathbb N)$ is a sequence of members of $B$. Then there is an internal sequence $(b_n:n\in{}^*\mathbb N)$ which extends the sequence $(b_n:n\in\mathbb N)$.
\end{corollary}
\bproof Define $f:\mathbb N\to B:n\mapsto b_n$, and let ${}^+\!f:{}^*\mathbb N\to B$ be the map provided by Proposition \ref{propn_comprehensiveness}.
Then since ${}^*n=n$ for all $n\in\mathbb N$, we have  ${}^+\!f(n)={}^+\!f({}^*n)=f(n)=b_n$ for $n\in\mathbb N$. For $n\in {}^*\mathbb N-\mathbb N$, define $b_n:={}^+\!f(n)$.\eproof



\begin{theorem}\label{thm_saturation_implies_comprehensive} Suppose that $*:\mathbb U\to\mathbb V$ is a $\kappa$-saturated nonstandard embedding. Then $*$ is $\kappa$-comprehensive.
\end{theorem}
\bproof
Suppose that $*$ is $\kappa$-saturated. Let $A,B\in\mathbb U$, where $|A|<\kappa$, and suppose that $f:A\to {}^*B$. 
%Let $T\in\mathbb U$ be a transitive set such that $A, B\in T$. For $a\in A$, define sets $B_a$ by
\[B_a:=\{g\in{}^*\mathcal P(A\times B):  \text{$g$ is a function}\land \dom(g)={}^*A\land ({}^*a, f(a))\in g\}.\]
By the internal definition principle, each $B_a$ is internal.

 Let $\mathcal B:=\{B_A:a\in A\}$, so that $|\mathcal B|<\kappa$. To apply $\kappa$-saturation, we must show that $\mathcal B$ has the f.i.p.
 Now given for each $n\in \mathbb N$, we have that \[\mathbb U\vDash\forall x_1\dots x_n\in B\;\exists g\in \mathcal P(A\times B)\;\Big(\text{$g$ is a function}\land\dom(g)=A\land (a_1, x_1)\in g\land\dots\land (a_n,x_n)\in g\Big).\]
 Thus by transfer, setting $x_i:=f(a_i)$ for $a_1,\dots, a_n\in A$, there is $g\in{}^*\mathcal P(A\times B)$ such that
 \[\mathbb V\vDash \text{$g$ is a function}\land\dom(g)={}^*A\land ({}^*a_1, f(a_1))\in g\land\dots\land ({}^*a_n,f(a_n))\in g,\]
 and then clearly $g\in\bigcap_{i\leq n}B_{a_i}$. As $n\in\mathbb N$ is arbitrary, it follows that $\mathcal B$ has the f.i.p.

By $\kappa$-saturation,  there is an element ${}^+\!f\in\bigcap\mathcal B$. Then as ${}^+\!f\in{}^*\mathcal P(A\times B)$, it is an internal function ${}^*A\to {}^*B$ with the property that ${}^+\!f({}^*a)=f(a)$ for all $a\in A$.
\eproof

In the case of $\omega_1$-saturation, we also have the converse:
\begin{theorem} Suppose that $*:\mathbb U\to\mathbb V$ is a nonstandard embedding, where $\mathbb U$ is a universe over a set $X$ that contains $\mathbb N$. The following are equivalent:
\begin{enumerate}[(i)]
\item $*$ is $\omega_1$-saturated, i.e. every countable family $\mathcal A$ of internal sets with the f.i.p. has non-empty intersection.
\item $*$ is countably comprehensive.

\end{enumerate}
\end{theorem}
\bproof 
This follows directly from Theorem \ref{thm_saturation_implies_comprehensive}.

(ii) $\Rightarrow$ (i): Suppose that $*$ is countably comprehensive, and that $\mathcal A:=\{A_n:n\in\mathbb N\}$ is a countable family of internal sets with the f.i.p. By replacing $A_n$ with $\bigcap_{m\leq n}A_n$, we may assume that the $A_n$ form a decreasing sequence of non-empty internal sets. As $A_0$ is internal, there is a transitive $T$ such that $A_0\in {}^*T$. Then as ${}^*T$ is transitive, we see that each $A_n$ is an internal subset of ${}^*T$, and thus $A_n\in{}^*\mathcal P(T)$.
Thus we have a map $f:\mathbb N\to{}^*\mathcal P(T):n\to A_n$. By countable comprehensiveness, there is an internal map ${}^+\!f:{}^*\mathbb N\to {}^*\mathcal P(T)$ such that ${}^+\!f(n)=A_n$ for every $n\in\mathbb N$. For $n\in{}^*\mathbb N-\mathbb N$, define $A_n:={}^+\!f(n)$. Then $(A_n:n\in{}^*\mathbb N)$ is an internal hypersequence of internal subsets of ${}^*T$ that extends the sequence $(A_n:n\in\mathbb N)$. Let \[X:=\{n\in{}^*\mathbb N: \forall k\in{}^*\mathbb N\;(k\leq n\to {}^+\!f(k)\supseteq{}^+\!f(n))\land {}^+\!f(n)\neq\varnothing\}\]%=\{n\in{}^*\mathbb N: \forall k\in{}^*\mathbb N\;(k\leq n\to A_k\supseteq A_n)\land A_n\neq\varnothing\}.\]
Then $X$ is internal, by the internal definition principle. By assumption, $\mathbb N\subseteq X\subseteq{}^*\mathbb N$. As $\mathbb N$ is not internal, there is $N\in {}^*\mathbb N-\mathbb N$ such that $N\in X$. Then $\bigcap_{n\in\mathbb N}A_n\supseteq A_N\neq\varnothing$. (One could also apply overflow to the set $X$ to deduce that $X$ has an infinite member.)

\eproof




