\section{Related Work}
\label{sec:appdx_related_work}

\paragraph{DNNs as vision models.}
Within the last decade, Deep Neural Networks (DNNs) have been proposed as models of the human visual system \citep{doerig2023neuroconnectionist, kriegeskorte2015deep, cichy2019deep, kietzmann2017deep}, not only because they form the only class of image-computable models that achieves human-level performance on benchmark tasks like ImageNet \citep{russakovsky2015imagenet}, but also because performance-optimized DNNs are the best predictors of biological neural activations \citep{yamins2014performance, kubilius2019brain, zhuang2021unsupervised}. However, the suitability of DNNs as models of vision is debated \citep{Bowers2022, wichmann2023deep, maniquet2024recurrent, serre2019deep}, as is the question of how comparisons should best be conducted \citep{firestone2020performance, lonnqvist2021comparative, wichmann2023deep}.

\paragraph{Error Consistency.}
The underlying idea motivating error consistency is that of ``molecular psychophysics'' \citep{green1963consistency}, which is to go beyond aggregate measures like accuracy, and instead compare behavior on a trial-by-trial basis. EC promises to achieve this by building on Cohen's $\kappa$ \citep{cohen1960coefficient,Mart_n_Andr_s_2024}, which considers the trial-level agreement observed for a pair of classifiers. \cite{geirhos2020beyond} proposed EC in the context of human-machine comparison, but in principle, the method applies to the general setting of comparing arbitrary classifiers. \cite{Mart_n_Andr_s_2024} observe that $\kappa$ is a biased estimator and should be corrected, which we support in our implementation. \cite{safak2020min} also observe the problem of $\kappa's$ dependency on the marginals, which we outline in \cref{sec:explanation}. They propose to scale $\kappa$ between its theoretical limits in an attempt to obtain a measure of error consistency that is orthogonal to accuracy. \cite{goel2025great} propose to apply Cohen's $\kappa$ directly to the responses given by both classifiers $\hat{y}_i$ rather than the correctness values $r_i$, and adapt the marginal probabilities of independent classifiers to reflect their accuracy. We still focus on the standard error consistency proposed by \cite{geirhos2020beyond} because it has seen the widest application. In principle, our bootstrapping methodology also works for these other metrics.

\paragraph{Uncertainties in Benchmarking.}
Benchmarking has a long history and is central to modern machine learning \citep{koch2024protoscience, singh2025leaderboard, hardt2025emerging, orr2024ai}. For example, the popular Papers with Code database lists approximately 14,000 different benchmarks \citep{PaperswithCode}.
With the emergence of modern benchmarks and leaderboards, issues such as overfitting to benchmarks \citep{singh2025leaderboard}, the limitations of metrics \citep{thomas2020problem}, and various sources of uncertainty have been identified and challenged \citep{lehmann2025quantifying, bouthillier2021accounting}. In general, it has been criticized that benchmarks should not be the primary goal of scientific machine learning research \citep{alzahrani2024benchmarks}. At the same time, it has been pointed out that benchmarking itself requires a scientific approach and some kind of standard methodology \citep{thiyagalingam2022scientific, sculley2018winner, hardt2025emerging}. Similar to our work, \cite{nado2021uncertainty} argued that uncertainty is an important aspect to consider for benchmarks. In contrast to previous work, we focus on uncertainty in the behavioral comparison of classifiers using error consistency.


\section{Proof of Proposition 2}
\label{sec:appdx_proof}

\begin{proof}
    The underlying distributions translate into the observed distributions $P_1 = \tilde{P}_1$ and $P^{(2)} = p_{copy}\tilde{P}^{(1)} + (1-p_{copy})\tilde{P}^{(2)}$. Inverting the marginal $P^{(2)}$, we get $\tilde{P}^{(2)}(y) = \frac{P^{(2)}(y) - p_{copy}\cdot P^{(1)}(y)}{1-p_{copy}}$.

    For the joint distribution, we have $P(y, y) = \tilde{P}^{(1)}(y)(p_{copy} + (1-p_{copy})\tilde{P}_2(y))$ because the second classifier makes the same prediction as the first in all copy cases ($p_{copy}$) and in those cases, in which it does not copy but coincidentally makes the same prediction ($(1-p_{copy})P^{(2)}(y)$). 

    \begin{align*}
        \kappa 
        &= \frac{ p_{obs} - p_{exp} }{ 1 - p_{exp} } 
        \\ 
        &= \frac{ \sum_{y=1}^K P^{(1,2)}(y, y) - \sum_{y=1}^K P^{(1)}(y) P^{(2)}(y) }{ 1 - \sum_{y=1}^K P^{(1)}(y) P^{(2)}(y) }
        \\ 
        &= \frac{\sum_{y=1}^K \Big( P^{(1)}(y) (p_{copy} + (1-p_{copy})\tilde{P}_2(y)) \Big) - \sum_{y=1}^K P^{(1)}(y) P^{(2)}(y) }{ 1 - \sum_{y=1}^K P^{(1)}(y) P^{(2)}(y) }
        \\ 
        &= \frac{ \sum_{y=1}^K \Big( P^{(1)}(y) ( p_{copy} + P^{(2)}(y) - p_{copy}\cdot P^{(1)}(y) ) \Big)  - \sum_{y=1}^K P^{(1)}(y) P^{(2)}(y) }{ 1 - \sum_{y=1}^K P^{(1)}(y) P^{(2)}(y) }
        \\ 
        &= p_{copy} \frac{ \sum_{y=1}^K \Big( P^{(1)}(y) - P^{(1)}(y) \cdot P^{(1)}(y) ) \Big) }{ 1 - \sum_{y=1}^K P^{(1)}(y) P^{(2)}(y) } 
        \\
        &= p_{copy} \cdot \left( \frac{ 1 - \sum_{y=1}^K P^{(1)}(y)^2 }{ 1 - \sum_{y=1}^K P^{(1)}(y) P^{(2)}(y) } \right)
    \end{align*}
\end{proof}

\section{Proof of Ceiling Effects}
\label{sec:appdx_proof_ceiling}

In \cref{sec:explanation}, we claim that as soon as one classifier achieves perfect accuracy on the investigated sequence of trials, the EC of the pair will be 0 irrespective of the accuracy of the other one. Here, we proof this claim, which is easiest to derive from a confusion matrix as shown in \cref{tab:matrix}. The observed agreement is found on the diagonal, $p_{obs} = a + d$,  while the expected agreement is what would be on the diagonal if observers were independent ($p_{exp} = (a+b)(a+c) + (c+d)(b+d)$). For the proof, consider without loss of generality that classifier 2 was perfect, i.e. $a + c = 1$.

\begin{table}[h]
  %\vspace{-1em}
  \setlength{\tabcolsep}{8pt} % column separation
  \renewcommand{\arraystretch}{1.3} % row height
  \centering
  \begin{tabular}{cccc}
    & $r^{(2)} = 1$ & $r^{(2)} = 0$ & \\
    %\hline \\
    $r^{(1)} = 1$ & \cellcolor{gray!20}$a$ & $b$                    & $a+b$ \\
    $r^{(1)} = 0$ & $c$                    & \cellcolor{gray!20}$d$ & $c+d$ \\
    %\hline \\
    & $a+c$ & $b+d$ & $1.0$ \\
  \end{tabular}
  \caption{Error consistency matrix.}
  \label{tab:matrix}
\end{table}

\begin{proof}
Let $a + c = 1$, then $b + d = 0$, so $p_{exp} = (a+b)(a+c) + (c+d)(b+d) = (a + b)$. Since $b \geq 0$ and $d \geq 0$, $b = d = 0$.
    \begin{align*}
        \kappa 
        &= \frac{ p_{obs} - p_{exp} }{ 1 - p_{exp} } 
        \\ 
        &= \frac{(a+d) - (a + b)}{1 - (a + b)} \\
        &= \frac{d - b}{1 - (a + b)} \\
        &= 0 \\
    \end{align*}
\end{proof}

By symmetry, the same argument holds for the case where one classifier gives incorrect responses on all trials. 

