Adding the fairness constraint \eqref{eq:fairness} on the Pareto optimal rules leads to the following characterization of AFPO taxation rules.\\

\begin{corollary}[Characterization of AFPO taxation rules]

A taxation rule $\mathbf{T}=\left(T_1, \cdots, T_n\right)$ is AFPO if and only if there exists $(\alpha_{1}, \ldots, \alpha_{n}) \ \in \Delta^n_+$ and a function $\Lambda: A \rightarrow \mathbb{R}_{+}$ such that 
        $$
        \begin{array}{ll}
        \alpha_i v_i^{\prime}\left(T_i(s_\varepsilon)\right)=\Lambda(s_\varepsilon) & \text { if } 0<T_i(s_\varepsilon)<w_i-\pi_i \\
        \alpha_i v_i^{\prime}\left(T_i(s_\varepsilon)\right) \geq \Lambda(s_\varepsilon) & \text { if } T_i(s_\varepsilon)=0 \\
        \alpha_i v_i^{\prime}\left(T_i(s_\varepsilon)\right) \leq \Lambda(s_\varepsilon) & \text { if } T_i(s_\varepsilon)=w_i-\pi_i\\
        \text{and} \ \mathbb{E}\left[T_{i}(S_\varepsilon)\right]=\mathbb{E}[\varepsilon_i] & \text{ for all} \ i=1, \dots, n .
        \end{array}
        $$
    \label{prob2}
\end{corollary}
\noindent The existence and unicity of AFPO taxation rules are given in \cite{Buhlmann1978,buhlmann_optimal_1979}. We refer to Theorem 2 in \cite{Buhlmann1978} for the proof.\\
\begin{theorem}
Under Assumption \ref{H1}, the AFPO taxation rule characterized in Corollary \ref{prob2} exists and is unique. 
\end{theorem}


\section{Analytical study for the case of  two regions \label{sect4}}
This section is dedicated to a complete analytic study of two regions ($n=2$), each with a constant absolute risk aversion. The procedure for determining the AFPO taxation rule is detailed, which provides an explicit solution for this particular case. 


\subsection{Analytic solution under CARA disutilities}\label{sec:subsec:analytical}
This case study is based on \cite{feng_decentralized_2023} (Chapter 6, Example 6.7). The economy under consideration consists of two regions, with their initial wealth of $w_1$ and $w_2$. For simplicity, let us assume that $\pi_1=\pi_2=0$, which means no insurer exists, and the regions directly share their losses. After a catastrophe, the loss occurring to a region is given by  $X_i=\tau_iw_i$, where $\tau_i$ is the random proportion of wealth that region $i$ loses due to catastrophes. The aggregate wealth loss to be shared between the two regions is  $S_\varepsilon = S = X_1+X_2$. The disutility functions of the two regions are assumed to be with constant absolute risk aversion (CARA), that is   $v_1(x)=\gamma_1 e^{\frac{x}{\gamma_1}}$ and $v_2(x)=\gamma_2 e^{\frac{x}{\gamma_2}}$, where $\gamma_i$ is the risk tolerance parameter of region $i$. The larger the value of $\gamma_i$, the more risk-tolerant is region $i$. Without loss of generality, we order the region by increasing value of $\frac{w_i}{\gamma_i}$.\\

\begin{assumption}\label{hyp:ex}
The setting of the  2-regions example is the following 
\begin{itemize}
\item $v_1(x)=\gamma_1 e^{\frac{x}{\gamma_1}}$ and $v_2(x)=\gamma_2 e^{\frac{x}{\gamma_2}}$
\item $\frac{w_1}{\gamma_1} \leq \frac{w_2}{\gamma_2}$
\item $S_\varepsilon=X_1+X_2$ follows a mixed distribution: with probability $p_0$ it is exactly $0$ (a Dirac mass at $0$), and with probability $1-p_0$ it is uniformly distributed on the interval $[0, w_1+w_2]$ with mean $\mu_1+\mu_2$ where $\mu_i:= \mathbb E [X_i]$.
\end{itemize}
\end{assumption}

\noindent Proposition \ref{prop1} computes explicitly the optimal taxation rule in this setting.\\

\begin{proposition}  Under Assumption~\ref{hyp:ex}, we define the following quantities
\[
\gamma = \frac{\gamma_2}{\gamma_1}, \quad
\mu = \frac{\mu_2}{\mu_1}, \quad
 \zeta = \ln\Bigl(\frac{\alpha_2}{\alpha_1}\Bigr),\quad
c = (1+\gamma)w_1 - \gamma_2\,\zeta .
\]
We introduce the sets of the parameters $(\mu_i,\gamma_i,w_i)_{i=1,2}$, characterized through the quantity
$$M = \left(\frac{2}{1-p_0}\right)^2\left(\mu+1\right)\left(\frac{\mu_1}{\gamma_1}\right)^2 : $$
\begin{eqnarray*}
A_1&:=&\Bigl\{\,(\mu_i,\gamma_i,w_i)_{i=1,2} \; / \; M \in \left[\frac{\gamma^2}{\mu}\left(\frac{w_2}{\gamma_2}\right)^2, \frac{\gamma}{\mu}\left(\frac{w_1}{\gamma_1}\right)^2+\frac{\gamma^2}{\mu}\left(\frac{w_2}{\gamma_2}\right)^2 \right] \Bigr\};  \\
A_2&:=&\Bigl\{\,(\mu_i,\gamma_i,w_i)_{i=1,2} \; / \; M \in \left[\left(\gamma + 1\right)  \left(\frac{w_1}{\gamma_1}\right)^2, \left(1-\gamma \right)  \left(\frac{w_1}{\gamma_1}\right)^2 + 2\gamma\frac{w_1}{\gamma_1}\frac{w_2}{\gamma_2} \right] \Bigr\};  \\
A_3&:=&\Bigl\{\,(\mu_i,\gamma_i,w_i)_{i=1,2} \; / \; M \in \left[ \left(\frac{w_1}{\gamma_1}\right)^2  , \left(\gamma + 1\right)  \left(\frac{w_1}{\gamma_1}\right)^2\right] \Bigr\}.
\end{eqnarray*}
The optimal weight  \(\zeta\),  the AFPO taxation rule \(T_1(s_\varepsilon)\) and  $T_2(s_\varepsilon)=s_\varepsilon-T_1(s_\varepsilon)$ are determined on each set as follows:\\
{\bf Case 1}: The set $A_1$ corresponds to the weight $\zeta  \in [0, \frac{w_1}{\gamma_1} ]$. Then 
\[
\zeta  = \frac{w_1}{\gamma_1}
  - \sqrt{ \frac{M\mu}{\gamma} - \gamma\bigl(\frac{w_2}{\gamma_2}\bigr)^2},
\quad
T_1(s_\varepsilon)=
\begin{cases}
s_\varepsilon, & 0\leq s_\varepsilon \leq \gamma_1\,\zeta ,\\
\frac{\gamma_1}{\gamma_1+\gamma_2}\,s_\varepsilon
 +\frac{\gamma_1\gamma_2}{\gamma_1+\gamma_2}\,\zeta ,
 & \gamma_1\zeta  \leq s_\varepsilon \leq c,\\
w_1, & c \leq s_\varepsilon \leq w_1+w_2.
\end{cases}
\]
{\bf Case 2}: The set $A_2$ corresponds to the weight $\zeta  \in [\frac{w_1}{\gamma_1}-\frac{w_2}{\gamma_2}, 0 ]$. Then
\[
\zeta  = \frac{1}{\gamma_2}\Bigl[
  \frac{(1+\gamma)w_1}{2}
  +\frac{2(\mu_1+\mu_2)}{1-p_0}\Bigl(\frac{\mu_1}{(1-p_0)w_1}-1\Bigr)
\Bigr],
\quad
T_1(s_\varepsilon)=
\begin{cases}
0, & 0\leq s_\varepsilon \leq -\gamma_2\zeta ,\\
\frac{\gamma_1}{\gamma_1+\gamma_2}\,s_\varepsilon
 +\frac{\gamma_1\gamma_2}{\gamma_1+\gamma_2}\,\zeta ,
 & -\gamma_2\zeta  \leq s_\varepsilon \leq c,\\
w_1, & c\leq s_\varepsilon \leq w_1+w_2.
\end{cases}
\]
{\bf Case 3}: The set $A_3$ corresponds to the weight $\zeta  \in [-\frac{w_2}{\gamma_2}, \frac{w_1}{\gamma_1}-\frac{w_2}{\gamma_2}]$. Then
\[
\zeta  = -\frac{w_2}{\gamma_2}
  + \sqrt{\frac{M}{\gamma}- \frac{1}{\gamma}\bigl(\frac{w_1}{\gamma_1}\bigr)^2},
\quad
T_1(s_\varepsilon)=
\begin{cases}
0, & 0 \leq s_\varepsilon\leq-\gamma_2\zeta ,\\
\frac{\gamma_1}{\gamma_1+\gamma_2}\,s_\varepsilon
 -\frac{\gamma_1\gamma_2}{\gamma_1+\gamma_2}\,\zeta ,
 & -\gamma_2\zeta  \leq s_\varepsilon\leq\frac{(\gamma+1)(w_1+w_2)-c}{\gamma},\\
s_\varepsilon-w_2, & \frac{(\gamma+1)(w_1+w_2)-c}{\gamma} \leq s_\varepsilon\leq w_1+w_2.
\end{cases}
\]

\label{prop1}
\end{proposition}
\noindent The proof of Proposition \ref{prop1} is postponed in Appendix \ref{proof}, and we comment below on this analytical result and in particular the impact of the parameter $\zeta = \ln (\frac{\alpha_2}{\alpha_1})$ on the risk sharing mechanism. Note that, with all else the same, an increase in $\alpha_i$ raises the threshold $\lambda_i$ at which region $i$ enters in the redistribution of loss, thereby reducing its burden in the taxation, whereas a decrease in $\alpha_i$ lowers this threshold, causing region $i$ to assume a larger share of losses.
 \\
For a CARA‐disutility case with 2 regions, each layer of loss is shared in \emph{quota‐share} fashion between the two regions.  In the middle quota‐share layer, both taxes are an increasing affine function of 
\(s_{\varepsilon}\), with slope respectively
\[
T_1'(s_{\varepsilon})
= \frac{\gamma_1}{\gamma_1 + \gamma_2},
\qquad
T_2'(s_{\varepsilon})
= \frac{\gamma_2}{\gamma_1 + \gamma_2}.
\]
Note that $\zeta$ determines the threshold at which region 1 enters and exits the quota-share layer; any change in $\zeta$ that shifts region 1’s thresholds also produces the corresponding shifts in region 2’s thresholds.

\begin{itemize}
  \item \textbf{Case 1 (\(\zeta \in [0,\frac{w_{1}}{\gamma_{1}}]\)):}  
    As \(\zeta\) increases, region 1’s deductible threshold \(\gamma_{1}\zeta\) becomes larger (i.e., sharing begins only after a higher loss) and its cap \(c=(1+\gamma)w_{1}-\gamma_{2}\zeta\) becomes smaller (i.e., the flat‐tax region starts earlier in terms of loss). Consequently, the shared interval \([\gamma_{1}\zeta,\,c]\) contracts. From region 2’s perspective, this means region 2 also shares over a narrower interval: it starts sharing only after a larger loss retained by region 1, and reaches its own cap sooner. Conversely, reducing \(\zeta\) enlarges the shared layer for both regions.

  \item \textbf{Case 2 (\(\zeta \in [\frac{w_{1}}{\gamma_{1}} - \frac{w_{2}}{\gamma_{2}},\,0]\)):}  
    Both breakpoints, region 2’s deductible (\(-\gamma_{2}\zeta\)) and region 1’s cap \(c=(1+\gamma)w_{1}-\gamma_{2}\zeta\), depend affinely on \(\zeta\) in the same way, so their difference remains constant at \((1+\gamma)w_{1}\). Hence, the width of the quota‐share layer does not change; rather, changing \(\zeta\) shifts the entire interval of sharing to occur at different loss levels without altering its size. From region 2’s viewpoint, increasing \(\zeta\) causes both its deductible and cap to correspond to smaller loss values (so sharing happens earlier), while decreasing \(\zeta\) corresponds to larger loss values (sharing happens later), but the span of losses over which sharing occurs remains fixed for both regions.

  \item \textbf{Case 3 (\(\zeta \in [-\frac{w_{1}}{\gamma_{1}},\frac{w_{1}}{\gamma_{1}}-\frac{w_{2}}{\gamma_{2}}]\)):}  
    Decreasing \(\zeta\) causes region 2’s deductible (\(-\gamma_{2}\zeta\)) to correspond to a higher loss level (so region 2 begins sharing only after a larger loss) and simultaneously causes region 1’s cap \(c=(1+\gamma)w_{1}-\gamma_{2}\zeta\) to correspond to a higher loss level (so region 1’s flat‐tax region begins later). Thus, the shared interval \([-\gamma_{2}\zeta,\,c]\) expands in length, meaning both regions share over a wider range of losses. Increasing \(\zeta\) within this case compresses that interval, so sharing occurs over a narrower range for both regions.
\end{itemize}


One can note that \(\zeta\) not only selects the applicable set \(A_i\) and controls the width of the quota‐share layer, but also induces additive shifts in the intercepts of the affine taxation rules: the slopes \(\tfrac{\gamma_1}{\gamma_1+\gamma_2}\) and \(\tfrac{\gamma_2}{\gamma_1+\gamma_2}\) remain unchanged inside that layer, while the deductible and cap thresholds move according to \(\zeta\).


\subsection{Sensitivity analysis}\label{sec:subsec:sensitivity}
To assess the robustness of the AFPO taxation rule under CARA disutility, we conduct two one‐dimensional sensitivity experiments around the baseline parameterization 
\[
w_{1}=4.5,\; w_{2}=10,\; p_{0}=0.2,\; \gamma_{1}=1,\; \gamma_{2}=2,\; \mu_{2}=4,\; \mu_{1}=(1-p_{0})\tfrac{w_{1}+w_{2}}{2}-\mu_{2}.
\]
First, for each value of the relative expected‐loss ratio \(\mu=\frac{\mu_{2}}{\mu_{1}}\) in \([0.1,10]\), we compute the three candidate expressions for the weight \(\alpha_{1}\) arising from Cases~1--3, then determine which case’s bound condition is met and retain the unique solution \(\alpha_{1}\) satisfying that case. Figure~\ref{fig:sensitivity_analysis} displays the resulting curve \(\alpha_{1}\) versus \(\mu\) (solid) and \(\alpha_{2}=1-\alpha_{1}\) (dashed), with segment colors (\textcolor{red}{red}/\textcolor{blue}{blue}/\textcolor{ForestGreen}{green}) indicating the active case; a secondary axis shows the log‐odds \(\zeta=\ln\ \bigl(\frac{(1-\alpha_{1})}{\alpha_{1}}\bigr)\), which uniquely determines both the deductible threshold \(\gamma_{1}\,\zeta\) and the cap shift \(c=(1+\gamma)\,w_{1}-\gamma_{2}\,\zeta\). Second, we vary the relative risk‐tolerance ratio \(\gamma=\frac{\gamma_{2}}{\gamma_{1}}\) over \([0.1,10]\), enforcing the feasibility \(\tfrac{w_{1}}{\gamma_{1}}\le \tfrac{w_{2}}{\gamma_{2}}\), and similarly identify the applicable case at each \(\gamma\) to plot \(\alpha_{1}\) and \(\alpha_{2}\) with respect to \(\gamma\) in Figure~\ref{fig:sensitivity_analysisfin}. In this second experiment, only two of the three cases arise within the chosen parameter range; for completeness, we include further sensitivity plot in Appendix \ref{addsen}. Overall, one observes that a larger \(\mu\) shifts the overall risk burden toward Region~2, while a smaller \(\gamma\) leads Region~2 to assume a greater share of small, frequent losses and a smaller share of large losses. Moreover, the log‐odds \(\zeta\) faithfully tracks how the pure‐retention, quota‐share and pure‐limit layers widen, narrow or translate as parameters vary, even though the within‐layer sharing rates \(\frac{\gamma_{1}}{(\gamma_{1}+\gamma_{2})}\) and \(\frac{\gamma_{2}}{(\gamma_{1}+\gamma_{2})}\) remain constant.






