\section{Pareto‐optimal solutions via weighted minimization \label{secA1}}

\noindent
We recall that a Pareto‐optimal allocation among \(n\) regions can be obtained by solving, for any weight vector \(\boldsymbol\alpha=(\alpha_{1},\dots,\alpha_{n})\) in the open unit simplex \(\Delta^n_{+}=\{\,\alpha_i>0,\ \sum_i\alpha_i=1\}\), the following weighted minimization problem over taxation rules \((T_{1}(\cdot),\dots,T_{n}(\cdot))\):
\[
\min_{(T_{1},\dots,T_{n})}\;\; 
\sum_{i=1}^n \alpha_i \,\mathbb{E}\bigl[v_i\bigl(T_i(S_\varepsilon)\bigr)\bigr]
\]
subject to, for each realized total loss \(s_{\varepsilon}\in\Omega_{-}\),
\[
\left\{
\begin{aligned}
  &\sum_{i=1}^n T_i(s_{\varepsilon}) \;=\; s_{\varepsilon}, 
    \quad\text{(full allocation condition)}\\
  &0 \;\le\; T_i(s_{\varepsilon}) \;\le\; w_i - \pi_i, 
    \quad i=1,\dots,n.
\end{aligned}
\right.
\]
Because the objective is additive over states \(s_{\varepsilon}\), it suffices to solve, for each fixed \(s_{\varepsilon}\), the finite‐dimensional problem
\[
\min_{(T_{1},\dots,T_{n}) \in \mathbb{R}^n}\;\; 
\sum_{i=1}^n \alpha_i \,v_i\bigl(T_i(s_{\varepsilon})\bigr)
\quad\text{subject to}\quad
\sum_{i=1}^n T_i(s_{\varepsilon}) = s_{\varepsilon}, 
\ \ 0 \le T_i(s_{\varepsilon}) \le w_i - \pi_i.
\]
We now derive the necessary optimality conditions via the Karush–Kuhn–Tucker (KKT) framework.

\medskip

\noindent\textbf{Lagrangian and first‐order conditions.}
Introduce multipliers 
\(\Lambda(s_{\varepsilon})\in\mathbb{R}\) for the equality \(\sum_i T_i = s_{\varepsilon}\), 
and for each \(i\) multipliers \(\eta_i(s_{\varepsilon})\ge0\) for the upper bound \(T_i \le w_i - \pi_i\), and \(\mu_i(s_{\varepsilon})\ge0\) for the lower bound \(T_i \ge 0\).  The Lagrangian for the pointwise problem at \(s_{\varepsilon}\) is
\[
\begin{aligned}
\mathcal{L}\bigl((T_i),\,\Lambda,\;(\eta_i),\,(\mu_i)\bigr)
&=
\sum_{i=1}^n \alpha_i\,v_i\bigl(T_i(s_{\varepsilon})\bigr)
\;-\;\Lambda(s_{\varepsilon})\Bigl(\sum_{i=1}^n T_i(s_{\varepsilon}) - s_{\varepsilon}\Bigr)\\
&\quad
+\sum_{i=1}^n \eta_i(s_{\varepsilon})\,\bigl(T_i(s_{\varepsilon}) - (w_i - \pi_i)\bigr)
\;-\;\sum_{i=1}^n \mu_i(s_{\varepsilon})\,T_i(s_{\varepsilon}).
\end{aligned}
\]
The first‐order conditions with respect to \(T_i(s_{\varepsilon})\) read:
\[
\frac{\partial \mathcal{L}}{\partial T_i(s_{\varepsilon})}
\;=\;
\alpha_i \,v_i'\bigl(T_i(s_{\varepsilon})\bigr)
\;-\;\Lambda(s_{\varepsilon})
\;+\;\eta_i(s_{\varepsilon})
\;-\;\mu_i(s_{\varepsilon})
\;=\;0,
\quad i=1,\dots,n,
\]
or equivalently
\[
\alpha_i \,v_i'\bigl(T_i(s_{\varepsilon})\bigr)
\;=\;\Lambda(s_{\varepsilon})
\;-\;\eta_i(s_{\varepsilon})
\;+\;\mu_i(s_{\varepsilon}).
\]
Complementary slackness and feasibility for each \(i\) impose:
\[
\left\{
\begin{aligned}
  &\eta_i(s_{\varepsilon}) \;\ge\; 0, \quad 
   T_i(s_{\varepsilon}) \;\le\; w_i - \pi_i, \quad
   \eta_i(s_{\varepsilon})\,\bigl(T_i(s_{\varepsilon}) - (w_i - \pi_i)\bigr)=0,\\
  &\mu_i(s_{\varepsilon}) \;\ge\; 0, \quad
   T_i(s_{\varepsilon}) \;\ge\; 0, \quad
   \mu_i(s_{\varepsilon})\,T_i(s_{\varepsilon}) = 0.
\end{aligned}
\right.
\]

\vspace{1ex}
\noindent\textbf{Case analysis.}
Depending on whether \(T_i(s_{\varepsilon})\) is at the lower bound (\(T_i = 0\)), at the upper bound (\(T_i = w_i - \pi_i\)), or strictly in the interior (\(0 < T_i < w_i - \pi_i\)), we obtain:

\begin{itemize}
    \item \emph{If \(T_i(s_{\varepsilon})=0\).} Then \(\mu_i>0\), \(\eta_i=0\).  By the first order conditions,
  \[
  \alpha_i\,v_i'(0) \;=\; \Lambda - 0 + \mu_i \;\ge\; \Lambda, \ \text{i.e.} \ \alpha_i\,v_i'(0)\ge \Lambda(s_{\varepsilon}).
  \]

  \item \emph{If \(T_i(s_{\varepsilon})=w_i-\pi_i\).} Then \(\eta_i>0\), \(\mu_i=0\).  The first order conditions give
  \[
  \alpha_i\,v_i'(w_i-\pi_i) \;=\; \Lambda \;-\;\eta_i \;\le\;\Lambda, \ \text{i.e.} \ \alpha_i\,v_i'(w_i-\pi_i)\le \Lambda(s_{\varepsilon}).
  \]

  \item \emph{If \(0< T_i(s_{\varepsilon})<w_i-\pi_i\).} Then \(\eta_i=\mu_i=0\).  The first order conditions yield
  \[
  \alpha_i\,v_i'\bigl(T_i(s_{\varepsilon})\bigr) \;=\; \Lambda(s_{\varepsilon}).
  \]
Thus in any interior region the weighted marginal disutilities must be equalized across all participating \(i\).
\end{itemize}
Finally, the multiplier \(\Lambda(s_{\varepsilon})\) is determined by the aggregate constraint \(\sum_{i}T_i(s_{\varepsilon})=s_{\varepsilon}\). 

\medskip

\noindent\textbf{Conclusion.}
The KKT conditions show that, at each loss level \(s_{\varepsilon}\), regions fall into three categories: those that pay zero tax (pure retention), those whose tax lies strictly between 0 and the cap and for which 
\(\alpha_i\,v_i'(T_i)=\Lambda(s_{\varepsilon})\), and those that reach their cap \(T_i = w_i - \pi_i\) (pure limit). The weight vector \(\boldsymbol\alpha\) governs the common multiplier \(\Lambda\) and hence the boundaries between these layers; varying \(\boldsymbol\alpha\) traces out the Pareto frontier.  Therefore, solving the weighted minimization for each \(\boldsymbol\alpha\in\Delta^n_{+}\) indeed yields all Pareto‐optimal taxation rules.



\section{Proof of the analytical solution for the case of two regions in Section \ref{sec:subsec:analytical} \label{proof}}
We consider the case of two regions with CARA disutility functions satisfying Assumption~\ref{hyp:ex}.  Under this setup, write
\[
\gamma = \frac{\gamma_2}{\gamma_1}, 
\quad
\mu = \frac{\mu_2}{\mu_1}, 
\quad
\zeta = \ln\ \!\Bigl(\frac{\alpha_2}{\alpha_1}\Bigr),
\quad
c = (1+\gamma)w_1 - \gamma_2\,\zeta,
\quad
M = \Bigl(\tfrac{2}{1-p_0}\Bigr)^2(\mu+1)\Bigl(\tfrac{\mu_1}{\gamma_1}\Bigr)^2.
\]
\begin{itemize}
    \item \textbf{Preliminary Step }: Set interval endpoints in the range of $\lambda$.\\
The marginal exponential utility of both regions is given by,  
$$ \alpha_1 v_1^{\prime}\left(x\right)=\alpha_1 e^{\frac{x}{\gamma_1}}, \quad \mbox{ and } \quad
 \alpha_2 v_2^{\prime}\left(x \right)=\alpha_2 e^{\frac{x}{\gamma_2}}
$$

with $\alpha_1 \in ]0,1[$ and $\alpha_2=1-\alpha_1$. We can distinguish three  cases according to the orders of magnitude of $\lambda_1=\alpha_1$ and $\lambda_2=1-\alpha_1$ on the one hand, and $\lambda_1^{\max}=\alpha_1 e^{\frac{w_1}{\gamma_1}}$ and $\lambda_2^{\max}= (1-\alpha_1) e^{\frac{w_2}{\gamma_2}}$ on the other hand. Namely, since the region are ordered such that $\frac{w_1}{\gamma_1} \leq \frac{w_2}{\gamma_2}$ (Assumption \ref{hyp:ex}), the following 3 cases are possible:
\begin{itemize}
    \item Case 1:
    $\lambda_1\leq\lambda_2\leq\lambda_1^{\max}\leq\lambda_2^{\max}$ which is equivalent to $0 \leq \zeta \leq \frac{w_1}{\gamma_1}$;
    \item Case 2:
    $\lambda_2\leq\lambda_1<\lambda_1^{\max}\leq\lambda_2^{\max}$ which is equivalent to $ \frac{w_1}{\gamma_1}- \frac{w_2}{\gamma_2}\leq\zeta \leq 0$;
   \item Case 3: $\lambda_2\leq\lambda_1\leq\lambda_2^{\max}\leq\lambda_1^{\max}$ which is equivalent to $-\frac{w_2}{\gamma_2} \leq \zeta \leq \frac{w_1}{\gamma_1}-\frac{w_2}{\gamma_2}$.
\end{itemize}
We investigate the optimal AFPO taxation rule in each case and characterize them in terms of the model parameters.

\end{itemize}



\paragraph{Case 1:  $0 \leq \zeta \leq \frac{w_1}{\gamma_1}$}\bigskip

\begin{itemize}
\item \textbf{Step 1}: Find $\mathcal{T}_i(\lambda)$ as piecewise-defined functions. \bigskip

By Theorem \ref{thm2}, the Pareto optimal taxation can be determined by first solving the equations $\alpha_i v_i^{\prime}\left(T_i(s_\varepsilon)\right)= \Lambda(s_\varepsilon)=\lambda$ for $i=1,2$. We shall represent $T_1(s_\varepsilon), T_2(s_\varepsilon)$ as functions of $\lambda$ using the notations {$\mathcal{T}_i(\lambda)$}. Observe that
$$
\begin{aligned}
& \mathcal{T}_1(\lambda)= \begin{cases}0 & 0\leq\lambda\leq\alpha_1 \\
\gamma_1 \ln \left(\frac{\lambda}{\alpha_1}\right) & \alpha_1\leq\lambda\leq\alpha_1 e^{\frac{w_1}{\gamma_1}} \\
w_1, & \alpha_1 e^{\frac{w_1}{\gamma_1}}\leq\lambda\end{cases} \\
& \mathcal{T}_2(\lambda)= \begin{cases}0 & 0\leq\lambda\leq 1-\alpha_1 \\
\gamma_2 \ln \left(\frac{\lambda}{1-\alpha_1}\right), & 1-\alpha_1\leq\lambda\leq(1-\alpha_1) e^{\frac{w_2}{\gamma_2}}\end{cases}
\end{aligned}
$$

\item \textbf{Step 2}: Find $s_{\varepsilon}(\lambda)$ and $\Lambda(s_\varepsilon)$ as piecewise-defined functions.\bigskip

It consists in inverting the function $s_\varepsilon(\lambda):=\mathcal{T}_1(\lambda)+\mathcal{T}_2(\lambda)$.
$$
s_{\varepsilon}(\lambda)= \begin{cases}\gamma_1 \ln \left(\frac{\lambda}{\alpha_1}\right), & \alpha_1\leq\lambda\leq 1-\alpha_1 \\ \ln \left(\frac{\lambda^{\gamma_1+\gamma_2}}{\alpha_1^{\gamma_1}\left(1-\alpha_1\right)^{\gamma_2}}\right), & 1-\alpha_1\leq\lambda\leq\alpha_1 e^{\frac{w_1}{\gamma_1}} \\ w_1+\gamma_2 \ln \left(\frac{\lambda}{1-\alpha_1}\right), & \alpha_1 e^{\frac{w_1}{\gamma_1}}\leq\lambda\leq(1-\alpha_1) e^{\frac{w_2}{\gamma_2}}\end{cases}
$$


Or one has $w_1>\zeta$ and $c>\zeta$ since by assumption $\frac{1}{\left(1+e^{\frac{w_1}{\gamma_1}}\right)}\leq\alpha_1$. Solving for the inverse function $\Lambda\left(s_{\varepsilon}\right)$ gives

$$
\Lambda\left(s_{\varepsilon}\right)= \begin{cases}\alpha_1 e^{\frac{s_{\varepsilon}}{\gamma_1}}, & 0\leq s_{\varepsilon}\leq \gamma_1 \zeta \\ \left(\alpha_1^{\gamma_1}\left(1-\alpha_1\right)^{\gamma_2} e^{s_{\varepsilon}}\right)^{\frac{1}{\left(\gamma_1+\gamma_2\right)}}, & \gamma_1 \zeta\leq s_{\varepsilon}\leq c \\ \left(1-\alpha_1\right) e^{\frac{\left(s_{\varepsilon}-w_1\right)}{\gamma_2}}, & c\leq s_{\varepsilon} \leq w_1+w_2\end{cases}
$$

\item \textbf{Step 3}: Find $T_i(s_\varepsilon)$ as a breakdown of $s_\varepsilon$.\bigskip

Inserting $\Lambda(s_\varepsilon)$ into $\mathcal{T}_i(\lambda)$ for $i=1,2$ yields the solution
$$
\begin{aligned}
& T_1\left(s_{\varepsilon}\right)=\mathcal{T}_1\left(\Lambda\left(s_{\varepsilon}\right)\right)= \begin{cases}s_{\varepsilon}, & 0\leq s_{\varepsilon}\leq\gamma_1 \zeta \\
\left(\frac{\gamma_1}{\left(\gamma_1+\gamma_2\right)}\right) s_{\varepsilon}+\left(\frac{\gamma_1 \gamma_2}{\left(\gamma_1+\gamma_2\right)}\right) \zeta, & \gamma_1 \zeta\leq s_{\varepsilon}\leq c \\
w_1, & c\leq s_{\varepsilon}\leq w_1+w_2\end{cases} \\
& T_2\left(s_{\varepsilon}\right)=\mathcal{T}_2\left(\Lambda\left(s_{\varepsilon}\right)\right)= \begin{cases}0, & 0\leq s_{\varepsilon}\leq \gamma_1 \zeta \\
\left(\frac{\gamma_2}{\left(\gamma_1+\gamma_2\right)}\right) s_{\varepsilon}-\left(\frac{\gamma_1 \gamma_2}{\left(\gamma_1+\gamma_2\right)}\right) \zeta, & \gamma_1 \zeta\leq s_{\varepsilon}\leq c \\
s_{\varepsilon}-w_1, & c\leq s_{\varepsilon}\leq w_1+w_2\end{cases}
\end{aligned}
$$


\item \textbf{Step 4}: Find the unique AFPO taxation rule by adding the fairness constraint.\bigskip
$$
\begin{aligned}
\mathbb{E}\left[T_1(S_\varepsilon ; \zeta)\right]= & (1-p_0) \left( \int_0^{\gamma_1 \zeta} \frac{s_\varepsilon}{w_1 + w_2}   d s_\varepsilon+\int_{\gamma_1 \zeta}^c\frac{1}{w_1 + w_2} \left(\left(\frac{\gamma_1}{\left(\gamma_1+\gamma_2\right)}\right) s_{\varepsilon}+ \left(\frac{\gamma_1 \gamma_2}{\left(\gamma_1+\gamma_2\right)} \right) \zeta\right) d s_\varepsilon \right)\\
& +(1-p_0) \left(\frac{1}{w_1+w_2} \int_c^{w_1+w_2} w_1  d s_\varepsilon \right)\\
= & (1-p_0) \left(\frac{w_1+w_2}{2}-\frac{1}{2(w_1+w_2)} \left(w_2^2 - (c-w_1)^2 + \frac{\gamma_2}{\gamma_1+\gamma_2} (c-\gamma_1 \zeta)^2\right) \right); \\
\mathbb{E}\left[T_2(S_\varepsilon ; \zeta)\right]= & (1-p_0) \left(\frac{1}{w_1+w_2} \int_{\gamma_1 \zeta}^c\left(\left(\frac{\gamma_2}{\left(\gamma_1+\gamma_2\right)}\right) s_{\varepsilon}-\left(\frac{\gamma_1 \gamma_2}{\left(\gamma_1+\gamma_2\right)}\right) \zeta\right)  d s_\varepsilon\right) \\
& +(1-p_0) \left(\frac{1}{w_1+w_2} \int_c^{w_1+w_2}\left(s_\varepsilon-w_1\right) d s_\varepsilon \right). \\
= & (1-p_0) \left(\frac{1}{2(w_1+w_2)} \left(w_2^2 - (c-w_1)^2 + \frac{\gamma_2}{\gamma_1+\gamma_2} (c-\gamma_1 \zeta)^2\right)\right),
\end{aligned}
$$
where they sum up to $(1-p_0)\frac{w_1+w_2}{2}$ as expected. By the actuarial fairness condition, $\zeta$ should be determined to satisfy
$$
\mathbb{E}\bigl[T_1(S_\varepsilon; \zeta)\bigr] = \mathbb{E}[X_1] = \mu_1,\quad
\mathbb{E}\bigl[T_2(S_\varepsilon; \zeta)\bigr] = \mathbb{E}[X_2] = \mu_2.
$$
It follows from the equation $\mathbb{E}\left[T_1(S_\varepsilon ; \zeta)\right]=\mu_1$ that


\begin{equation}
   \zeta  = \frac{w_1}{\gamma_1}
  - \sqrt{ \frac{M\mu}{\gamma} - \gamma\bigl(\frac{w_2}{\gamma_2}\bigr)^2}.
    \label{fixpoint}
\end{equation}
Equation \eqref{fixpoint} gives an explicit solution for the weight $\zeta$. One can see that $\zeta$ depends on the wealths $w_1, w_2$, the risk tolerance of regions modeled by $\gamma_1, \gamma_2$, and the distribution of losses of regions through $\mu_1, \mu_2$. The set of these parameters that leads to this solution $\zeta$ with $0 \leq \zeta\leq \frac{w_1}{\gamma_1}$ is given by: 
$$A_1:=\Bigl\{\,(\mu_i,\gamma_i,w_i)_{i=1,2} \; / \; M \in \left[\frac{\gamma^2}{\mu}\left(\frac{w_2}{\gamma_2}\right)^2, \frac{\gamma}{\mu}\left(\frac{w_1}{\gamma_1}\right)^2+\frac{\gamma^2}{\mu}\left(\frac{w_2}{\gamma_2}\right)^2 \right] \Bigr\}.$$

\end{itemize}

\paragraph{Case 2:  $ \frac{w_1}{\gamma_1}- \frac{w_2}{\gamma_2}\leq \zeta \leq 0$} \bigskip

\begin{itemize}
\item \textbf{Step 1}: Find $\mathcal{T}_i(\lambda)$ as piecewise-defined functions. 
$$
\begin{aligned}
& \mathcal{T}_1(\lambda)= \begin{cases}0 & 0\leq\lambda\leq\alpha_1 \\
\gamma_1 \ln \left(\lambda / \alpha_1\right) & \alpha_1\leq\lambda\leq\alpha_1 e^{w_1 / \gamma_1} \\
w_1, & \alpha_1 e^{w_1 / \gamma_1}\leq\lambda\end{cases} \\
& \mathcal{T}_2(\lambda)= \begin{cases}0 & 0\leq\lambda\leq1-\alpha_1 \\
\gamma_2 \ln \left(\lambda / 1-\alpha_1\right), & 1-\alpha_1\leq\lambda\end{cases}
\end{aligned}
$$

\item \textbf{Step 2}: Find $s_{\varepsilon}(\lambda)$ and $\Lambda(s_\varepsilon)$ as piecewise-defined functions.
$$
s_{\varepsilon}(\lambda)= \begin{cases}\gamma_2 \ln \left(\lambda / 1-\alpha_1\right), & 1-\alpha_1\leq\lambda\leq\alpha_1 \\ \ln \left(\lambda^{\gamma_1+\gamma_2} / \alpha_1^{\gamma_1}\left(1-\alpha_1\right)^{\gamma_2}\right), & \alpha_1\leq\lambda\leq\alpha_1 e^{w_1 / \gamma_1} \\ w_1+\gamma_2 \ln \left(\lambda / 1-\alpha_1\right), & \alpha_1 e^{w_1 / \gamma_1}\leq\lambda\end{cases}
$$
Solving for the inverse function $\Lambda\left(s_{\varepsilon}\right)$ gives

$$
\Lambda\left(s_{\varepsilon}\right)= \begin{cases}(1-\alpha_1) e^{s_{\varepsilon} / \gamma_2}, & 0\leq s_{\varepsilon}\leq-\gamma_2 \zeta \\ \left(\alpha_1^{\gamma_1}\left(1-\alpha_1\right)^{\gamma_2} e^{s_{\varepsilon}}\right)^{1 /\left(\gamma_1+\gamma_2\right)}, & -\gamma_2 \zeta\leq s_{\varepsilon}\leq c \\ \left(1-\alpha_1\right) e^{\left(s_{\varepsilon}-w_1\right) / \gamma_2}, & c\leq s_{\varepsilon}\end{cases}
$$

\item \textbf{Step 3}: Find $T_i(s_\varepsilon)$ as a breakdown of $s_\varepsilon$.
$$
\begin{aligned}
& T_1\left(s_{\varepsilon}\right)=\mathcal{T}_1\left(\Lambda\left(s_{\varepsilon}\right)\right)= \begin{cases}0, & 0\leq s_{\varepsilon}\leq-\gamma_2 \zeta \\
\left(\gamma_1 /\left(\gamma_1+\gamma_2\right)\right) s_{\varepsilon}+\left(\gamma_1 \gamma_2 /\left(\gamma_1+\gamma_2\right)\right) \zeta, &-\gamma_2 \zeta\leq s_{\varepsilon}\leq c \\
w_1, & c \leq s_{\varepsilon}\end{cases} \\
& T_2\left(s_{\varepsilon}\right)=\mathcal{T}_2\left(\Lambda\left(s_{\varepsilon}\right)\right)= \begin{cases}s_{\varepsilon}, & 0\leq s_{\varepsilon}\leq -\gamma_2 \zeta \\
\left(\gamma_2 /\left(\gamma_1+\gamma_2\right)\right) s_{\varepsilon}-\left(\gamma_1 \gamma_2 /\left(\gamma_1+\gamma_2\right)\right) \zeta, & -\gamma_2 \zeta\leq s_{\varepsilon}\leq c \\
s_{\varepsilon}-w_1, & c\leq s_{\varepsilon}\end{cases}
\end{aligned}
$$
\item \textbf{Step 4}: Find the unique AFPO taxation rule by adding the fairness constraint.\bigskip
$$
\begin{aligned}
\mathbb{E}\left[T_1(S_\varepsilon ; \zeta)\right]= & (1-p_0) \left(\int_{-\gamma_2 \zeta}^c\frac{1}{w_1 + w_2}\left(\left(\frac{\gamma_1}{\left(\gamma_1+\gamma_2\right)}\right) s_{\varepsilon}+ \left(\frac{\gamma_1 \gamma_2}{\left(\gamma_1+\gamma_2\right)} \right) \zeta\right) d s_\varepsilon  + \int_c^{w_1+w_2} \frac{w_1}{w_1+w_2}  d s_\varepsilon \right) \\
= & (1-p_0) \left(\frac{\gamma_1}{\gamma_1+\gamma_2} \frac{(c+\gamma_2 \zeta)^2}{2(w_1+w_2)}+w_1-\frac{w_1}{w_1+w_2}c\right).
\end{aligned}
$$
It follows from the equation $\mathbb{E}\left[T_1(S_\varepsilon ; \zeta)\right]=\mu_1$ that
\begin{equation*}
  \zeta=\frac{1}{\gamma_2} \left(\left(1+\gamma\right)\frac{w_1}{2} + \frac{2(\mu_1+\mu_2)}{1-p_0} \left(\frac{1}{1-p_0}\frac{\mu_1}{w_1}-1\right)\right).
  \label{fixpointv3}
\end{equation*}
The set of these parameters that leads to this solution $\zeta$ with $ \frac{w_1}{\gamma_1}- \frac{w_2}{\gamma_2}\leq\zeta \leq 0$ is given by: 
$$A_2:=\Bigl\{\,(\mu_i,\gamma_i,w_i)_{i=1,2} \; / \; M \in \left[\left(\gamma + 1\right)  \left(\frac{w_1}{\gamma_1}\right)^2, \left(1-\gamma \right)  \left(\frac{w_1}{\gamma_1}\right)^2 + 2\gamma\frac{w_1}{\gamma_1}\frac{w_2}{\gamma_2} \right] \Bigr\}.$$


\end{itemize}


\paragraph{Case 3: $-\frac{w_2}{\gamma_2} \leq \zeta \leq \frac{w_1}{\gamma_1}-\frac{w_2}{\gamma_2}$}

This case is equivalent to the case $1$ where the region $1$ is exchanged to the region $2$ that is:

\[
\zeta  = -\frac{w_2}{\gamma_2}
  + \sqrt{\frac{M}{\gamma}- \frac{1}{\gamma}\bigl(\frac{w_1}{\gamma_1}\bigr)^2},
\quad
T_1(s_\varepsilon)=
\begin{cases}
0, & 0 \leq s_\varepsilon\leq-\gamma_2\zeta ,\\
\frac{\gamma_1}{\gamma_1+\gamma_2}\,s_\varepsilon
 -\frac{\gamma_1\gamma_2}{\gamma_1+\gamma_2}\,\zeta ,
 & -\gamma_2\zeta  \leq s_\varepsilon\leq\frac{(\gamma+1)(w_1+w_2)-c}{\gamma},\\
s_\varepsilon-w_2, & \frac{(\gamma+1)(w_1+w_2)-c}{\gamma} \leq s_\varepsilon\leq w_1+w_2.
\end{cases}
\]
The set of the input parameters that leads to this solution $\zeta$ with $-\frac{w_2}{\gamma_2} \leq \zeta \leq \frac{w_1}{\gamma_1}-\frac{w_2}{\gamma_2}$ is given by: 

$$A_3:=\Bigl\{\,(\mu_i,\gamma_i,w_i)_{i=1,2} \; / \; M \in \left[ \left(\frac{w_1}{\gamma_1}\right)^2  , \left(\gamma + 1\right)  \left(\frac{w_1}{\gamma_1}\right)^2\right] \Bigr\}.$$



