The parameters present in the effective Lagrangian \eqref{Leff} are defined by the integrals below
\begin{equation}
\begin{gathered}
\label{integrals}
    M = 4\int_{-\infty}^{+\infty}dx\sech^2(\xi) \, W^2(\xi),\\
    m = \frac{4}{\gamma^2}\int_{-\infty}^{+\infty}dx\sech^2(\xi) \, \xi^2,\\
    \kappa = \frac{4}{\gamma} \int_{-\infty}^{+\infty}dx\sech^2(\xi) W(\xi) \, \xi ,\\
\alpha = 2\int_{-\infty}^{+\infty}dx\sech^2(\xi) \, \frac{f(t,x_0)}{g(t,x_0)} \, W(\xi) \xi
    , \\
\beta = \frac{2}{\gamma} \int_{-\infty}^{+\infty}dx\sech^2(\xi) \, \frac{f(t,x_0)}{g(t,x_0)} \, \xi^2
    ,\\
    V = 2\int_{-\infty}^{+\infty}dx\sech^2(\xi) \, \left( g(t,x) + g(t,x_0) \, \frac{\mathcal{F}(x)}{\mathcal{F}(x_0)}\gamma^2 - \frac{f^2(t,x_0)}{4 g^2(t,x_0)} \, \xi^2 \right) .
\end{gathered}
\end{equation}
Auxiliary functions $W$ and $f$ appearing in expressions for effective Lagrangian coefficients are as follows
\begin{equation} \label{W}
    W(\xi) = \frac{1}{2} \, \left( \frac{\partial_{x_0} {\cal F}(x_0)}{ {\cal F}(x_0)} - \frac{\partial_{x_0} { g}(t,x_0)}{ {g}(t,x_0)} \right) \, \xi + \sqrt{\frac{g(t,x_0)}{{\cal F}(x_0)}} \, \gamma , \,\,\,\,\, f(t,x_0) = \omega \varepsilon_1 \cos{(k x_0 - \omega t)} .
\end{equation}
All coefficients are functions of the dynamic variables $x_0(t)$ and $\gamma(t)$. Moreover, they depend explicitly on time.
Most of the above integrals can be calculated by obtaining the explicit dependence of the coefficients on the functions ${\cal F}(x_0)$ and $g(t,x_0)$ present in the lagrangian density and on their derivatives
\begin{equation}
\begin{gathered}
\label{integrals-fin}
    M = \frac{\pi^2}{6 \gamma} \sqrt{\frac{{\cal F}(x_0)}{g(t,x_0)}} \left( \frac{\partial_{x_0}{\cal F}(x_0)}{{\cal F}(x_0)} - \frac{\partial_{x_0} g(t,x_0)}{g(t,x_0)}\right)^2 + 8 \gamma \sqrt{\frac{g(t,x_0)}{{\cal F}(x_0)}},\\
    m = \frac{2 \pi^2}{3 \gamma^3} \sqrt{\frac{{\cal F}(x_0)}{g(t,x_0)}},\\
    \kappa = \frac{\pi^2}{3 \gamma^2} \sqrt{\frac{{\cal F}(x_0)}{g(t,x_0)}} \, \left( \frac{\partial_{x_0}{\cal F}(x_0)}{{\cal F}(x_0)} - \frac{\partial_{x_0} g(t,x_0)}{g(t,x_0)}\right) ,\\
\alpha = \frac{\pi^2}{6 \gamma} \, \sqrt{\frac{{\cal F}(x_0)}{g(t,x_0)}} \left( \frac{\partial_{x_0}{\cal F}(x_0)}{{\cal F}(x_0)} - \frac{\partial_{x_0} g(t,x_0)}{g(t,x_0)}\right) \frac{f(t,x_0)}{g(t,x_0)}  , \\
\beta = \frac{\pi^2}{3 \gamma^2} \, \sqrt{\frac{{\cal F}(x_0)}{g(t,x_0)}} \frac{f(t,x_0)}{g(t,x_0)}   ,\\
    V = 2 \int_{-\infty}^{+\infty} dx \sech^2 \xi \, g(t,x) +\frac{2 \gamma^2 g(t,x_0)}{{\cal F}(x_0)} \int_{-\infty}^{+\infty} dx \sech^2 \xi \, {\cal F}(x) - \frac{\pi^2 f^2(t,x_0)}{12 \gamma g^2(t,x_0)} \sqrt{\frac{{\cal F}(x_0)}{g(t,x_0)}}  .
