 Let $\sP(\mR^{d})$ be the space  of all probability measures, and  $\sP_{p}(\mR^{d})(p\ge1)$ denotes the subset   of $\sP(\mR^{d})$ such that for $\mu \in \sP_{p}(\mR^{d})$
 $$W_{p}(\mu):=\bigg(\bigg.\int_{\mR^{d}}|x|^{p}\mu(\dif x)\bigg)\bigg.^{\frac{1}{p}}<\infty.$$
For $ \mu, \nu\in \sP_{p}(\mR^{d})$, we define the
Wasserstein distance   as follows: $$W_{p}(\mu, \nu):=\inf_{\pi \in \Pi(\mu, \nu)}\bigg\{\bigg. \int_{\mR^{d}\times \mR^{d}}|x-y|^{p}\pi(\dif x, \dif y)   \bigg\}\bigg.^{\frac{1}{p}}, $$
where $\Pi(\mu, \nu)$ is the family of all coupling for $\mu$ and $ \nu.$ $\sP_{p}(\mR^{d})$ is a Polish space under $W_{p}$.



\subsection{Lions derivative}
Now we introduce the Lions derivative for a function $v: \sP_{2}(\mR^{d})\to \mR$.
\begin{defn}
$v: \sP_{2}(\mR^{d})\to \mR$ is said to be $L$-differentiable at $\mu\in \sP_{2}(\mR^{d})$ if there is an atomless probability space $(\Omega, \sA, \mP)$ and a random variable $Y\in L^2(\Omega, \sA, \mP; \mR^d)$ such that $\mu = \sL(Y)$ and the lifted function $V: L^2(\Omega, \sA, \mP; \mR^d)\to \mR$ defined by $V(Y)=v(\sL(Y))$ is Frechet differentiable at $Y$.
\end{defn}
For any $Y, \tilde Y\in L^2(\Omega, \sA, \mP; \mR^d)$, by the mean value theorem (see \cite[chapter 5]{CD}), there exists a $\theta \in [0, 1]$ such that
\begin{align}\label{yml}
v(\sL(Y))-v(\sL(\tilde Y))=\mE \big[\langle \partial_{\nu}(\sL(\theta Y+(1-\theta)\tilde Y))(\theta Y+(1-\theta)\tilde Y), Y-\tilde Y\rangle\big].
\end{align}







\subsection{Definition of the LDP  }
\bd
Let $\mathcal{X}$ be a Polish space.   A real-valued function $I:\mathcal{X} \rightarrow [0, \infty] $ is called a rate function if it is lower
semicontinuous, i.e., for $a\in [0, \infty), $  the level set $I^{-1}([0,a])$ is a closed subset of $\mathcal{X}.$  Furthermore, if all level sets $I^{-1}([0,a]), a\in [0, \infty),$ are compact, then $I$ is called a good rate function.
\ed

\bd
Let $I$ be a rate function  and $\{\mu_{\epsilon}\}_{\epsilon > 0}$  be a family of probability measures on $\mathcal{X}$. We say that $\{\mu_{\epsilon}\}_{\epsilon > 0}$ satisfies an LDP on $\mathcal{X}$  with the rate function $I$ if
\begin{itemize}
\item[{\rm (i)}]  $\liminf_{\epsilon\rightarrow 0}\epsilon\log(\mu_{\epsilon}(O))\geq -\inf_{x\in O} I(x)$ for every open $O\subset \mathcal{X};$

\item[{\rm (ii)}] $\limsup_{\epsilon\rightarrow 0}\epsilon\log(\mu_{\epsilon}(U))\leq -\inf_{x \in U} I(x)$ for every closed $U\subset \mathcal{X}.$

\end{itemize}

\ed












\subsection{Main results}

\subsubsection{ The LDP  for non-degenerate MVSDEs with H\"{o}lder continuous drifts}
In this paper, we consider the following MVSDEs
\begin{equation}\label{a0}
\begin{cases}
  &X_t= x_{0}+\int^{t}_{0}b(s, X_s, \mu_{s})\dif s +\int^{t}_{0}\sigma( s,  X_s)\dif  B_s, t\in [0, T],\\
 &\mu_{t}=\sL(X_t):= \mbox{the probability distribution of } X_t,
 \end{cases}
 \end{equation}
 where the diffusion is independent of the the probability distribution of  $X_t$.
Now,  we impose some necessary assumptions on coefficients. Let $b: [0,T]\times\mR^{d}\times \sP_{2}(\mR^{d})\rightarrow \mR^{d},$ $\sigma: [0,T]\times\mR^{d}\rightarrow \mR^{d\times m}$ be measurable  mappings, and assume
\begin{itemize}
\item[(H1)]$b,\sigma$ are continuous for $t$ and there exists  a positive constant $L>0$ such that  all  $x,y \in \mR^{d}, \mu, \nu\in \sP_{2}(\mR^{d}),$
$$|b(t,x, \mu)-b(t,y,\nu)| \leq L(|x-y|+ W_{2}(\mu, \nu)),$$
$$ |\sigma(t,x)-\sigma(t, y)| \leq L|x-y|.$$
\end{itemize}

\begin{itemize}


\item[(H2)] \begin{itemize}
\item[$1^{\circ}$]$m=d$ and there exists a constant $\gamma>0$ such that $\frac{1}{\gamma}I_{d\times d}\leq \sigma\sigma^{*}\leq \gamma I_{d\times d}.$
\item[$2^{\circ}$]$b(t, x,\mu):=\beta(t, x, \langle \kappa_{1}, \mu \rangle),$ where $\beta:[0,T]\times\mR^{d}\times \mR \rightarrow \mR^{d}$   and  $\kappa_{1}: \mR^{d}\rightarrow \mR$  are measurable.  $\langle \kappa_{1}, \mu \rangle$ is denoted by $\int_{\mR^{d}}\kappa_{1}(x) \mu(\dif x).$ Moreover, there exist  constants $\Lambda> 0$ and $ 0< \alpha< 1 $ such that  for any $x, y \in  \mR^{d},  \mu_{1}, \mu_{2} \in \sP_{2}(\mR^{d}),$
\begin{align}
& | b(t,x, \mu_{1})- b(t,y, \mu_{2})|\leq \Lambda(|x-y|^{\alpha}+W_{2}(\mu_{1}, \mu_{2})), \label{46bn} \\
 &\|b\|_{T, \infty,\infty} +\sum_{i=0}^{2}\|\nabla^{i}\sigma\|_{T,\infty} +\|\nabla \sigma^{-1}\|_{T,\infty} +\| \sigma^{-1}\|_{T,\infty}< \infty, \label{45a}
\end{align}
where \begin{align*}
&\|f\|_{T,\infty,\infty}:= \sup_{t\in [0,T]}\sup_{x\in R^{d}, \mu \in \sP_{2}(\mR^{d}) }|f(t,x,\mu)|,\\
&\|g\|_{T,\infty}:= \sup_{t\in [0,T]}\sup_{x\in R^{d} }|g(t,x)|.
\end{align*}
\end{itemize}

\end{itemize}


\begin{rem}\label{yr1}
By $(\mathrm{H1})$  or $(\mathrm{H2}),$ one can see that there exists a positive constant $\tilde  L$ such that
$$|b(t,x,\mu)| \leq \tilde{L}(1+|x|+W_{2}(\mu, \delta_{0})) \mbox{ and } |\sigma(t,x)| \leq \tilde{L}(1+|x|). $$
Moreover, $(\mathrm{H2})$ implies that there exists a positive constant $\tilde  \Lambda$ such that
$$| \sigma(t, x)- \sigma(t,y)|\leq \tilde  \Lambda|x-y|.$$ \label{46bm}
\end{rem}

We now consider the following small perturbation of Eq.\eqref{a0}:
\begin{equation}\label{a1}
\begin{cases}
  &X^{\epsilon}_t= x_{0}+\int^{t}_{0}b(t, X^{\epsilon}_s, \mu^{\epsilon}_{s})\dif s +\sqrt{\epsilon}\int^{t}_{0}\sigma(t,   X^{\epsilon}_s)\dif  B_s, \,  t\in [0, T],\\
 &\mu^{\epsilon}_{t}:= \mbox{the probability distribution of } X^{\epsilon}_t.
 \end{cases}
 \end{equation}
As shown in \cite{RXZ},  under the assumption  $(\mathrm{H1})$, the family $\{X^{\epsilon}\}_{0<\epsilon<1}$ satisfies  an LDP on  $C_{x_{0}}([0,T], \mR^{d})\rightarrow \mR^{d}$ with the good rate function $I$ given by
$$I(\varphi) := \frac{1}{2}\int^{T}_{0}\bigg|\bigg.(\varphi'(t)-b(\varphi(t),\mu^{0}_{t}))\sigma^{-1}(\varphi(t))\bigg|\bigg.^{2}\dif t, \,\forall \varphi \in \mH^{1}_{x_{0}}([0,T], \mR^{d}).   $$

In this section, we assume that the coefficients of \eqref{a1} satisfy (H2). Let   $X^{0}$ be the solution of  the following equation:

\begin{align}\label{44+-}
\dif X^{0}_{t}&=b(t,X^{0}_t, \mu^{0}_{t})\dif t,
 \end{align}
where $ \mu^{0}_{t}$ is the distribution of $X^{0}_{t}.$  Since the coefficients in Eq.\eqref{44+-} are continuous and bounded,   there exist solutions for Eq.\eqref{44+-}, but may not be unique.
Now, among all the solutions of  Eq.\eqref{44+-},
 we will find one  that ensures $\{X^{\epsilon}\}_{0<\epsilon<1}$ satisfies  the LDP with a good rate function $I^{X} $ (defined in the proof) under the assumption  $(\mathrm{H2})$, i.e.

\bt \label{5.3}
Assume $(\mathrm{H2})$.    Then,   $\{X^{\epsilon}_t, t\in [0,T]\}$   satisfies the  LDP  in $C(0,T;\mR^{d})$ with the speed $\epsilon^{-1}$ and the good rate function $I^{X}.$
\et



\subsubsection{ The LDP for degenerate MVSDEs}
Consider the following degenerate MVSDEs on $\mR^{d_{1}+d_{2}}:$
\begin{equation}\label{58+}
\begin{cases}
  & \dif \widehat X^{\epsilon}_t= c( \widehat X^{\epsilon}_t, \widehat Y^{\epsilon}_t, \mu^{\widehat Y^{\epsilon}}_{t})\dif t,\\
   &\dif \widehat Y^{\epsilon}_t= \Gamma( \widehat X^{\epsilon}_t, \widehat Y^{\epsilon}_t,\mu^{\widehat Y^{\epsilon}}_{t})\dif t+ b(t, \widehat Y^{\epsilon}_t, \mu^{\widehat Y^{\epsilon}}_{t})\dif t +\sqrt{\epsilon}\sigma(t,   \widehat Y^{\epsilon}_t)\dif  B_t, t\in [0, T],\\
 & (\widehat X^{\epsilon}_0, \widehat Y^{\epsilon}_0)=(x_{0}, y_{0}).
 \end{cases}
 \end{equation}
where $\mu^{\widehat Y^{\epsilon}}_{t}$ is the distribution of $\widehat Y^{\epsilon}_{t},$   $\{B_t\}_{0\leq t\leq T}$ is a $d_{2}-$dimensional Brownian motion, $c:\mR^{d_{1}+d_{2}}\times \sP(\mR^{d_{2}})\rightarrow \mR^{d_{1}},$ $\Gamma:\mR^{d_{1}+d_{2}}\times \sP(\mR^{d_{2}})\rightarrow \mR^{d_{2}},$ $b: [0, T]\times \mR^{d_{2}}\times \sP(\mR^{d_{2}})\rightarrow \mR^{d_{2}}$ and $\sigma: [0, T]\times \mR^{d_{2}}\rightarrow \mR^{d_{2}}\times\mR^{d_{2}}$  are measurable.
We need the following assumptions later.
\begin{itemize}
\item[($\mathrm{H}4$)]Assume that $b$ and $ \sigma$  satisfy $(\mathrm{H}2),$ and there exists a constant $C> 0$ such that  for any $y_{1}, y_{2} \in  \mR^{d_{2}},z_{1}, z_{2} \in  \mR^{d_{1}+d_{2}},  \mu_{1}, \mu_{2} \in \sP_{2}(\mR^{d_{1}}), \nu_{1}, \nu_{2} \in \sP_{2}(\mR^{d_{2}}),$
\begin{align}
 &| c(z_{1}, \mu_{1})- c(z_{2}, \mu_{2})|\leq C(|z_{1}-z_{2}|+W_{2}(\mu_{1}, \mu_{2})). \label{56} \\
&| \Gamma(z_{1}, y_1, \nu_{1})- \Gamma(z_{2}, y_2, \nu_{2})|\leq C(|z_{1}-z_{2}|+|y_{1}-y_{2}|+W_{2}(\nu_{1}, \nu_{2})). \label{54}\\
& \|\Gamma\|_{\infty, \infty}+\|c\|_{\infty,\infty}\leq C. \label{56-}
\end{align}
\end{itemize}
\bt \label{ty3}
Let  $(\mathrm{H4})$ hold. Then the family $\{(\widehat X^{\epsilon}(t), \widehat Y^{\epsilon}(t))\}_{t\in [0, T]}$ obeys the  LDP on $C(0,T; \mR^{d_{1}+d_{2}})$ with  speed $\epsilon^{-1}$ and  rate function $I^{(\widehat X, \widehat Y)},$  where
$$I^{(\widehat X, \widehat Y)}=\frac{1}{2}\int^{T}_{0}\bigg|\bigg.(f_{2}'(t)-b_{t}^{\mu^{Y_{0}}}(f_{2}(t)))\sigma_{t}^{-1}(f_{2}(t))\bigg|\bigg.^{2}\dif t, \forall f:=(f_{1},f_{2}) \in \mH^{1}_{x_{0}}(0,T, \mR^{d_{1}+d_{2}}).$$
\et


