\section{ Proofs of the Main Results}

\subsection{Proof of Theorem \ref{5.3}.}


Since there may have many  solutions of  Eq.\eqref{44+-},
 we need find one  that ensures $\{X^{\epsilon}\}_{0<\epsilon<1}$ satisfies  the LDP under the assumption  $(\mathrm{H2})$.   To this end, we introduce the following partial differential equation:
 \begin{equation}\label{v1}
(\partial_{t}+\sA)u(t,x,
  \mu))=\beta(t, x,\langle \kappa_{1},\mu\rangle), \quad u(T, x,\mu)=0,
 \end{equation}
where $\sA$ is given by:
\begin{align}\label{v2}
\sA \psi(t,x,\mu)&:= \frac{1}{2}Tr[(\sigma \sigma^{*})( x)\partial^{2}_{x}\psi(t,x,\mu)] +\beta(t,x,\langle \kappa_{1},\mu\rangle)\partial_{x}\psi(t,x,\mu)\no\\
&\quad +\int_{\mR^{d}}\beta( t,z,\langle \kappa_{1},\mu\rangle)\partial_{\mu}\psi(t,x,\mu)(z)\dif \mu(z)\no\\
&\quad +\frac{1}{2}\int_{\mR^{d}}Tr[(\sigma \sigma^{*})( x)\partial_{z}(\partial_{\mu}\psi(t,x,\mu)(z)) ]\dif \mu(z).
 \end{align}
Mollifying the coefficients $\beta, \sigma$ and the functions $\kappa_{1}$ to get a sequence of coefficients  $\beta_{n}, \sigma_{n}$  and functions $\kappa_{1}^{n}, n\geq 1$ that converge uniformly to $\beta, \sigma,  \kappa_{1}$ respectively, and   denoting by $\sA_{n}$ the regularized version of the operator $\sA$ and $u^{n}$ the solution of the regularized version of Eq.\eqref{v1},
we have the following lemma which is taken from \cite{Ra}.
\bl\label{yl1}
For each $n,$ the regularized system of Eq. \eqref{v1}(i.e.  $\sA_{n}, \beta_{n}, \sigma_{n}, \kappa^{n}_{1}$ instead of $\sA, b, \sigma, \kappa_{1}$) admits a unique classical solution $u^{n}.$  Moreover, there exist  positive constants $T^*,$  $K$ and   $\delta$  depending only on known parameters in $(\mathrm{H2})$ such that,  for all $(t,x,u)\in [0,T]\times \mR^{d}\times \sP(\mR^{d})$ and all the positive integer  $n,$ $u^{n}$ satisfies
$$|\partial_{\mu}u^{n}(t,x,\mu)(z)|+|\partial_{\mu}(\partial_{x}u^{n}(t,x,\mu))(z)|+|\partial_{x}u^{n}(t,x,\mu)|+|\partial^{2}_{x}u^{n}(t,x,\mu)| \leq K T^{\delta},  $$
$\forall z\in \mR^{d}$ and  $T\le T^*.$
\el






The following estimate is needed.





\bl \label{201}
Assume $(H2).$ Then,
for any $\epsilon, \tilde{\epsilon}\in (0,1),$  we have
\begin{align*}
