\begin{proof} For convenience, we now use the  notations: $\partial_{1}:=\partial_{t}, \partial_{2}:=\partial_{x}, \partial_{3}:=\partial_{\mu}.$

Applying  It\^{o}'s formula to $x - u^n(t, x, \mu)$, we have
\begin{align}\label{v3}
X^{\epsilon}_{t} &= x- u^{n}(t, x, \delta_{x})+u^{n}(t, X^{\epsilon}_{t}, \mu^{\epsilon}_{t}) + \sqrt{\epsilon}\int^{t}_{0}\sigma(   s,X^{\epsilon}_{s})[I-\partial_{2}u^{n}(s, X^{\epsilon}_{s}, \mu^{\epsilon}_{s})]\dif B_{s}\no\\
&\quad + R^{\epsilon}_{t}(n),
 \end{align}
where
\begin{align*}
R^{\epsilon}_{t}(n):= \int^{t}_{0}(\beta(s,X^{\epsilon}_s,\langle \kappa_{1}, \mu^{\epsilon}_{t}\rangle)-\beta_{n}(s,X^{\epsilon}_s,\langle \kappa^{n}_{1}, \mu^{\epsilon}_{t}\rangle))\dif s
  + \int^{t}_{0}(\sA^{\epsilon}_{n}-\sA^{\epsilon})u^{n}(s, X^{\epsilon}_s, \mu^{\epsilon}_{s})\dif s,
\end{align*}
\begin{align*}
\sA^{\epsilon} \psi(t,x,\mu)&:= \frac{\epsilon}{2}Tr[(\sigma \sigma^{*})(t, x)\partial^{2}_{2}\psi(t,x,\mu)] +\beta(t, x,\langle \kappa_{1},\mu\rangle)\partial_{2}\psi(t,x,\mu)\no\\
&\quad +\int_{\mR^{d}}\beta(t, z,\langle \kappa_{1},\mu\rangle)\partial_{3}\psi(t,x,\mu)(z)\dif \mu(z)\no\\
&\quad +\frac{\epsilon}{2}\int_{\mR^{d}}Tr[(\sigma \sigma^{*})(t, x)\partial_{z}(\partial_{3}\psi(t,x,\mu)(z)) ]\dif \mu(z)
 \end{align*}
 and
 \begin{align*}
\sA^{\epsilon}_n \psi(t,x,\mu)&:= \frac{\epsilon}{2}Tr[(\sigma_n \sigma_n^{*})( t,x)\partial^{2}_{2}\psi(t,x,\mu)] +\beta_n(t, x,\langle \kappa_{1},\mu\rangle)\partial_{2}\psi(t,x,\mu)\no\\
&\quad +\int_{\mR^{d}}\beta_n(t, z,\langle \kappa_{1},\mu\rangle)\partial_{3}\psi(t,x,\mu)(z)\dif \mu(z)\no\\
&\quad +\frac{\epsilon}{2}\int_{\mR^{d}}Tr[(\sigma_n \sigma_n^{*})(t, x)\partial_{z}(\partial_{3}\psi(t,x,\mu)(z)) ]\dif \mu(z).
 \end{align*}
Then
 \begin{align}\label{yv4}
 \begin{split}
&|X^{\epsilon}_{t}-X^{\tilde{\epsilon}}_{t}|^2\leq |u^{n}(t, X^{\epsilon}_{t}, \mu^{\epsilon}_{t})-u^{n}(t, X^{\tilde{\epsilon}}_{t}, \mu^{\tilde{\epsilon}}_{t})|^2+\epsilon\bigg|\bigg.\int^{t}_{0}\big(\sigma( s,  X^{\epsilon}_{s})-\sigma( s,  X^{\tilde{\epsilon}}_{s})\big)\dif B_s\bigg|^2\bigg. \\
 &+\epsilon\bigg|\bigg.\int^{t}_{0}\sigma( s,  X^{\tilde{\epsilon}}_{s})\partial_{2}u^{n}(s, X^{\tilde{\epsilon}}_{s}, \mu^{\tilde{\epsilon}}_{s})-\sigma(  s, X^{\epsilon}_{s})\partial_{2}u^{n}(s, X^{{\epsilon}}_{s}, \mu^{{\epsilon}}_{s})\dif B_s\bigg|^2\bigg.\\
 &+\bigg|\bigg.(\sqrt{\epsilon}-\sqrt{\tilde{\epsilon}})\int^{t}_{0}\sigma(s,   X^{\tilde{\epsilon}}_{s})[I-\partial_{2}u^{n}(s, X^{\tilde{\epsilon}}_{s}, \mu^{\tilde{\epsilon}}_{s})]\dif B_{s}\bigg|^2\bigg.\\
 &+|R^{\epsilon}_{t}(n)|^2+|R^{\tilde{\epsilon}}_{t}(n)|^2=: I_1(t)+I_2(t)+I_3(t)+I_4(t)+|R^{\epsilon}_{t}(n)|^2+|R^{\tilde{\epsilon}}_{t}(n)|^2.
 \end{split}
 \end{align}
 By  \eqref{yml} and Lemma \ref{yl1}, there exist  positive constants $T^*,$  $K$ and  $\delta$ such that for $t\le T^*$
