&+8 \epsilon\int^{t}_{0}\big|\big.\sigma( s,  X^{\epsilon}_{s})\partial_{2}u^{n}(s, X^{\tilde{\epsilon}}_{s}, \mu^{\tilde{\epsilon}}_{s})-\sigma( s,  X^{\epsilon}_{s})\partial_{2}u^{n}(s, X^{{\epsilon}}_{s}, \mu^{{\epsilon}}_{s})\big|^2\big.\dif s.
