\end{align*}
For $I_{4},$ by the assumption (H2)  and  Lemma \ref{yl1}, we have
 $$I_{4}\leq {C} (\sqrt{\epsilon}-\sqrt{\tilde{\epsilon}})^{2}. $$
Thus,
\begin{align*}
\mE\sup_{0\leq s \leq t}|X^{\epsilon}_{s}-X^{\tilde{\epsilon}}_{s}|^{2}&\leq {C}T^{\delta}\mE\sup_{0\leq s \leq t}|X^{\epsilon}_{s}-X^{\tilde{\epsilon}}_{s}|^{2}+ {C}\int^{t}_{0}\mE\sup_{0\leq r \leq s}|X^{\epsilon}_{r}-X^{\tilde{\epsilon}}_{r}|^{2}\dif s\\
&\quad +2 \mE[|R^{\epsilon}_{t}(n)|^{2}]+2\mE[|R^{\tilde{\epsilon}}_{t}(n)|^{2}]+  {C}\epsilon+  {C}(\sqrt{\epsilon}-\sqrt{\tilde{\epsilon}})^{2}.
\end{align*}
Since for any $\epsilon, \tilde{\epsilon},$ $\mE[|R^{\epsilon_{m}}_{t}(n)|^{2}], \mE[|R^{\epsilon_{k}}_{t}(n)|^{2}]$ tends to 0 as $n$ tend to infinity,  one has
\begin{align*}
(1-{C}T^{\delta})\mE\sup_{0\leq s \leq t}|X^{\epsilon}_{s}-X^{\tilde{\epsilon}}_{s}|^{2}&\leq {C}\int^{t}_{0}\mE\sup_{0\leq r \leq s}|X^{\epsilon}_{r}-X^{\tilde{\epsilon}}_{r}|^{2}\dif s\\
&\quad + {C}\epsilon+{C}(\sqrt{\epsilon}-\sqrt{\tilde{\epsilon}})^{2}.
\end{align*}
Finally, we can find a positive $T^*$ such that ${C}T^{\delta}<1$ for any $T\leq T^*,$  and $t\in [0, T]$
\begin{align*}
\mE\sup_{0\leq s \leq t}|X^{\epsilon}_{s}-X^{\tilde{\epsilon}}_{s}|^{2}&\leq C(T)\int^{t}_{0}\mE\sup_{0\leq r \leq s}|X^{\epsilon}_{r}-X^{\tilde{\epsilon}}_{r}|^{2}\dif s+ \tilde{C}\epsilon+ \tilde{C}(\sqrt{\epsilon}-\sqrt{\tilde{\epsilon}})^{2}.
