 \end{equation}
where $ \sL^{\epsilon}u :=(\frac{1}{2}Tr(\epsilon(\sigma_{t})^{*}\nabla^{2}u_{1}\sigma_{t}),
\frac{1}{2}Tr(\epsilon(\sigma_{t})^{*}\nabla^{2}u_{2}\sigma_{t}), \cdots, \frac{1}{2}Tr(\epsilon(\sigma_{t})^{*}\nabla^{2}u_{d}\sigma_{t})^{*}  $ for any $u=(u_{1}, u_{2}, \cdots, u_{d})^{*}\in C^{2}(0,T; \mR^{d}).$  By  \cite[Lemma 2.1]{123},  there exists $\lambda_{0}> 0$  such that for any  $\lambda > \lambda_{0}$, Eq.\eqref{37b-1} has a unique solution satisfying
 \begin{align}\label{37b++}
