\begin{align}\label{48cc}
\partial_{t}\phi_{t}&+ (\sL^{\epsilon_{2}}- \lambda) \phi_{t} +\nabla_{b^{\mu^{\epsilon_{2}}}_{t}}\phi_{t}
=(b^{\mu^{\epsilon_{1}}}_{t}-b^{\mu^{\epsilon_{2}}}_{t})+\nabla_{(b^{\mu^{\epsilon_{1}}}_{t}-b^{\mu^{\epsilon_{2}}}_{t})}u^{\lambda, \mu^{\epsilon_{1}}}_{t}+ (\sL^{\epsilon_{1}}-\sL^{\epsilon_{2}})u^{\lambda, \mu^{\epsilon_{1}}}_{t}.
