=&-\frac{1}{2}\sum^{d}_{j=1}[(\nabla \theta^{-1}_{it})(\theta_{t}(x))]_{j}Tr\{\epsilon [(\nabla \theta_{t} \sigma)^{*}( x)[(\nabla \theta_{t}(x))^{-1}]^{*}[\nabla^{2}\theta_{jt}](x)(\nabla \theta_{t}(x))^{-1} (\nabla \theta_{t} \sigma)( x )]\}\no\\
= &-\frac{1}{2}\epsilon \sum^{d}_{j=1}[(\nabla \theta^{-1}_{it})(\theta_{t}(x))]_{j}Tr[(\sigma^{*}(x)\nabla^{2} \theta_{jt}(x)\sigma(x) ]\no\\
= &-(\nabla \theta_{it})^{-1}(x)\sL^{\epsilon}(\theta_{t})(x).
\end{align}
Hence, from \eqref{43mmn+}, \eqref{43mmn++} and   \eqref{43mmn++-}, it follows that
\begin{align}
