Additionally, analogous to  Lemma \ref{ccc5},  $\hat u^{\lambda, \mu^{\widehat Y^{\epsilon}}}$ has a limit    denoted by $\hat u^{\lambda, \mu^{Y^{0}}}$  as $\epsilon$ tends to $0$, which  is a solution of the following equation:
\begin{align}\label{37ba}
\partial_{t}\hat u_{t}^{\lambda, \mu^{0}}+ \nabla_{b^{\mu^{0}}_{t}}\hat u_{t}^{\lambda, \mu^{0}}+b^{\mu^{0}}_{t}=\lambda \hat u_{t}^{\lambda, \mu^{0}}.
 \end{align}
where $\mu^{0}_{t}$ is the distribution of $\widehat Y^{0}_{t}$.








Letting $\hat \theta_{t}^{\lambda, \mu^{Y^{\epsilon}}}(y):=y+\hat u_{t}^{\lambda, \mu^{\widehat Y^{\epsilon}}}(y)$ and using It\^{o}'s formula yields
\begin{equation}\label{60}
\begin{cases}
  & \dif \widehat X^{\epsilon}_t= c( \widehat X^{\epsilon}_t, \widehat Y^{\epsilon}_t)\dif t,\\
   &\dif \hat \theta_{t}^{\lambda, \mu^{\widehat Y^{\epsilon}}}(\widehat Y^{\epsilon}_t)=\lambda \hat u_{t}^{\lambda, \mu^{\widehat Y^{\epsilon}}}(\widehat Y^{\epsilon}_t)\dif t+ \nabla \hat\theta_{\lambda}(\widehat Y^{\epsilon}_t)\Gamma(\widehat X^{\epsilon}_t, \widehat Y^{\epsilon}_t)\dif t\\
    &\quad\quad \quad\quad\quad \quad\quad\quad \quad\quad\quad \quad\quad\quad \quad+ \sqrt{\epsilon}(\nabla \theta_{t}^{\lambda, \mu^{\widehat Y^{\epsilon}}}\sigma)(t, \widehat Y^{\epsilon}_t )\dif  B(t).
 \end{cases}
 \end{equation}
Let $\widehat {Z}^{\epsilon}_t:=\hat \theta_{t}^{\lambda, \mu^{\widehat Y^{\epsilon}}}(\widehat Y^{\epsilon}_t),$  then \eqref{60} can be rewritten as
\begin{equation}\label{60y}
\begin{cases}
  & \dif \widehat X^{\epsilon}_t= \hat {c}_{t}^{\mu^{\widehat Y^{\epsilon}}}( \widehat X^{\epsilon}_t, \widehat{Z}^{\epsilon}_t)\dif t,\\
   &\dif \widehat {Z}^{\epsilon}_t=\widehat{M}_{t}^{\mu^{\widehat Y^{\epsilon}}}(\widehat X^{\epsilon}_t, \widehat {Z}^{\epsilon}_t) + \sqrt{\epsilon}\hat{\sigma}_{t}^{\mu^{\widehat Y^{\epsilon}}}(\widehat {Z}^{\epsilon}_t )\dif  B(t),
 \end{cases}
 \end{equation}
where $\widehat{M}_{t}^{\mu^{\widehat Y^{\epsilon}}}(x,y):=\lambda u_{t}^{\lambda, \mu^{\widehat Y^{\epsilon}}}((\hat \theta_{t}^{\lambda, \mu^{\widehat Y^{\epsilon}}})^{-1}(y))+\epsilon\nabla \hat \theta_{\lambda}((\hat \theta_{t}^{\lambda, \mu^{\widehat Y^{\epsilon}}})^{-1}(y))\Gamma(x,(\hat  \theta_{t}^{\lambda, \mu^{\widehat Y^{\epsilon}}})^{-1}(y)),$\\ $ \hat{\sigma}_{t}^{\mu^{\widehat Y^{\epsilon}}}(y):=(\nabla \hat \theta_{t}^{\lambda, \mu^{Y^{\epsilon}}}\sigma)((\hat \theta_{t}^{\lambda, \mu^{\widehat Y^{\epsilon}}})^{-1}(y) ),$  $\hat{c}^{\mu^{\widehat Y^{\epsilon}}}_{t}(x,y):= c(x, (\hat \theta_{t}^{\lambda, \mu^{\widehat Y^{\epsilon}}})^{-1}(y)).$ \\

 Then, one can show that
 there exists a constant $C> 0$ such that  for any $y_{1}, y_{2} \in  \mR^{d_{2}},z_{1}, z_{2} \in  \mR^{d_{1}+d_{2}}$
\begin{align*}
 &| \hat{c}_{t}^{\mu^{\widehat Y^{\epsilon}}}(z_{1})- \hat{c}_{t}^{\mu^{\widehat Y^{\epsilon}}}(z_{2})|\leq C|z_{1}-z_{2}|,\\
&| \widehat{M}_{t}^{\mu^{\widehat Y^{\epsilon}}}(z_{1})- \tilde{M}_{t}^{\mu^{\widehat Y^{\epsilon}}}(z_{2})|\leq C|z_{1}-z_{2}|,\\
& | \hat{\sigma}_{t}^{\mu^{\widehat Y^{\epsilon}}}(y_{1})- \hat{\sigma}_{t}^{\mu^{\widehat Y^{\epsilon}}}(y_{2})|\leq C|y_{1}-y_{2}|,
\end{align*}
and
$$\lim_{\epsilon\rightarrow 0}\sup_{0\leq t\leq T}|\hat{c}_{t}^{\mu^{\widehat Y^{\epsilon}}}-\hat{c}_{t}^{\mu^{\widehat Y^{0}}}|=0,\quad \lim_{\epsilon\rightarrow 0}\sup_{0\leq t\leq T}|\widehat{M}_{t}^{\mu^{\widehat Y^{\epsilon}}}-\widehat{M}_{t}^{\mu^{\widehat Y^{0}}}|=0,$$
$$\lim_{\epsilon\rightarrow 0}\sup_{0\leq t\leq T}|\hat{\sigma}_{t}^{\mu^{\widehat Y^{\epsilon}}}-\hat{\sigma}_{t}^{\mu^{\widehat Y^{0}}}|=0.$$


 By   \cite[Lemma 1.2]{FW},  $\{(\widehat X^{\epsilon}_t, \widehat{Z}^{\epsilon}_t),  0\leq t\leq T\}$ satisfies the LDP with the speed $\epsilon^{-1}$ and the good  rate function given by
\begin{align}\label{38gg}
\hat{I}(f):=\frac{1}{2}\inf_{f= \hat{g}(h), h\in {\mH}^{1}(0,T; \mR^{d_{2}})}\|h\|_{{\mH}^{1}}^{2},
\end{align}
with
\begin{align}\label{442nn}
(\hat{g}(h))_t=\int^{t}_{0}(\hat{c}_{s}^{\mu^{\widehat Y^{0}}}((\hat{g}(h))_s, \widehat{M}^{\mu^{\widehat Y^{0}}}((\hat{g}(h))_s))\dif s + \int^{t}_{0}(0,\hat{\sigma}_{s}^{\mu^{\widehat Y^{0}}}((\hat{g}(h))_s))\dot{h}(s)\dif s,
\end{align}
where $(\hat{g}(h))_t:=((\hat{g}^{\widehat X}(h))_t, (\hat{g}^{\widehat Y}(h))_t).$
Define
\begin{align}\label{41nn}
\hat I(f):=\frac{1}{2}\int^{T}_{0}\bigg|\bigg.(f_{2}'(t)-b_{t}^{\mu^{Y_{0}}}(f_{2}(t)))\sigma^{-1}(f_{2}(t))\bigg|\bigg.^{2}\dif t, \forall f=(f_{1},f_{2}) \in {\mH}^{1}_{x_{0}}([0,T], \mR^{d_{1}+d_{2}}).
\end{align}
and
$(\Upsilon^{\mu^{Y^{\epsilon}}}_{\lambda}(\xi))_{t}=(\xi^{1}_{t}, \theta_{t}^{\lambda,\mu^{Y^{\epsilon}}}(\xi^{2}_{t})),t\in [0,T], \xi =(\xi^{1}, \xi^{2})\in C([0,T]; \mR^{d_{1}+d_{2}}).$

The proof of Theorem \ref{ty3} can be demonstrated by following the approach used in the proof of Theorem \ref{5.3}.





















