\section{Derivations}
\subsection{Loss derivation}\label{app:alternative_loss}
In its more general form, the Woodbury matrix identity (also known as the Sherman-Morrison-Woodbury formula) states
that $(A + U C V)^{-1} = A^{-1} - A^{-1} U (C^{-1} + V A^{-1} U)^{-1} V A^{-1}$
and the matrix determinant lemma (also known as the Weinstein-Aronszajn identity) states that
$\left|A + U C V\right| = \left| C \right| \left| A \right| \left|C^{-1} + V A^{-1} U\right|$.

Recall that $A_{\theta}^{(i)} = R_{(i), (i)^{+}} F_{\theta}^{(i)} R_{(i)^{+}, (i)} + \sigma_{N}^{2} R_{(i), (i)}$.
Applying Woodbury to $(A_{\theta}^{(i)})^{-1}$ and defining $L^{(i)} = R_{(i)^{+}, (i)} R^{\dagger}$ and
$W^{(i)} = R_{(i)^{+}, (i)} R^{\dagger}_{(i), (i)} R_{(i), (i)^{+}}$, we get
\begin{equation*}
    \begin{split}
      (A_{\theta}^{(i)})^{-1}
      =
      &\frac{1}{\sigma_{N}^{2}} R_{(i), (i)}^{\dagger}
      -
      \frac{1}{\sigma_{N}^{2}} R_{(i), (i)}^{\dagger} R_{(i), (i)^{+}}
      ((F_{\theta}^{(i)})^{-1} + \frac{1}{\sigma_{N}^{2}} R_{(i)^{+}, (i)} R_{(i), (i)}^{\dagger} R_{(i), (i)^{+}})^{-1}
      \frac{1}{\sigma_{N}^{2}}R_{(i)^{+}, (i)} R_{(i), (i)}^{\dagger}
      \\
      =
      &\frac{1}{\sigma_{N}^{2}} R_{(i), (i)}^{\dagger}
      -
      \frac{1}{\sigma_{N}^{2}} L^{(i) \intercalp} F_{\theta}^{(i) \frac{1}{2}}
      (I + \frac{1}{\sigma_{N}^{2}} F_{\theta}^{(i) \frac{1}{2}} W^{(i)} F_{\theta}^{(i) \frac{1}{2}})^{-1}
      \frac{1}{\sigma_{N}^{2}} F_{\theta}^{(i) \frac{1}{2}} L^{(i)}
      \\
      =
      &\frac{1}{\sigma_{N}^{2}} R_{(i), (i)}^{\dagger}
      -
      \frac{1}{\sigma_{N}^{2}} L^{(i) \intercalp} F_{\theta}^{(i) \frac{1}{2}}
      (B_{\theta}^{(i)})^{-1}
      \frac{1}{\sigma_{N}^{2}} F_{\theta}^{(i) \frac{1}{2}} L^{(i)}
      .
    \end{split}
\end{equation*}
Moreover, for $|A_{\theta}^{(i)}|$ we have
\begin{equation*}
    \begin{split}
      |A_{\theta}^{(i)}|
      &=
      |\sigma_{N}^{2} R_{(i), (i)}|_{+}
      |F_{\theta}^{(i)}|
      |(F_{\theta}^{(i)})^{-1} + \frac{1}{\sigma_{N}^{2}} W^{(i)}|
      \\
      &=
      |\sigma_{N}^{2} R_{(i), (i)}|_{+}
      |F_{\theta}^{(i)}|
      |F_{\theta}^{(i) \frac{1}{2}}|^{-1}
      |I + \frac{1}{\sigma_{N}^{2}} F_{\theta}^{(i) \frac{1}{2}} W^{(i)} F_{\theta}^{(i) \frac{1}{2}}|
      |F_{\theta}^{(i) \frac{1}{2}}|^{-1}
      \\
      &=
      |\sigma_{N}^{2} R_{(i), (i)}|_{+}
      |B_{\theta}^{(i)}|,
    \end{split}
\end{equation*}
where $|\cdot|_{+}$ stands for the pseudo-determinants.
As we discussed before, $R_{(i), (i)}$ should be strictly positive-definite but, due to numerical precision,
$R_{(i), (i)}$ could contain eigenvalues close to zero, or negative.
This is why we use $R_{(i), (i)}^{\dagger}$ and why we would only consider de positive eigenvalues for the computation of $|\sigma_{N}^{2} R_{(i), (i)}|_{+}$.

\subsection{Held-out chromosome prediction using public data}\label{app: held in vs held out}

We essentially show that, since Eqn.~\ref{eqn: hat beta gen} is derived from Eqn.~\ref{eqn: y gen}, their likelihoods can only differ by a constant.

The negative log likelihood of $y$ using only held-in chromosomes $X_\mathrm{in}$ (Eqn.~\ref{eqn: y gen}) minus the log likelihood of the null ($F=0$) is
\begin{equation}\label{eqn: y diff lik}
\frac 1 2 \bigg[y^{\intercalp} (X_{\mathrm{in}}^{\intercalp} F_\mathrm{in} X_{\mathrm{in}}+\sigma^2 I)^{-1}y-y^{\intercalp} (\sigma^2 I)^{-1}y + \log|X_{\mathrm{in}}^{\intercalp} F_\mathrm{in} X_{\mathrm{in}}+\sigma^2 I| - \log |\sigma^2 I|\bigg]
\end{equation}
while the same equation for $\hat\beta$ (Eqn.~\ref{eqn: hat beta gen}) is, defining pseudo-determinants $|\cdot|_+$,
\begin{equation}\label{eqn: beta diff lik}
\frac 1 2 \bigg[\hat\beta^{\intercalp} (R_\mathrm{in} F_\mathrm{in} R_\mathrm{in}+\sigma_N^2 R_\mathrm{in})^{\dagger}\hat\beta-\hat\beta^{\intercalp} (\sigma_N^2 R_\mathrm{in})^{\dagger}\hat\beta + \log|R_\mathrm{in} F_\mathrm{in} R_\mathrm{in}+\sigma_N^2 R_\mathrm{in}|_+ - \log |\sigma_N^2 R_\mathrm{in}|_+\bigg].
\end{equation}

By Woodbury, the first two terms Eqn.~\ref{eqn: y diff lik} are equal to
\begin{equation*}
\begin{aligned}
    \frac 1 2 \bigg[-\frac{1}{\sigma^4}y^{\intercalp} X_{\mathrm{in}}^{\intercalp}( F_\mathrm{in}^{-1} +\sigma^{-2} X_{\mathrm{in}}^{\intercalp} X_{\mathrm{in}})^{-1}X_{\mathrm{in}}y\bigg]=&-\frac{1}{2\sigma_N^2}\hat\beta^{\intercalp}( \sigma_N^{2}F_\mathrm{in}^{-1} + R_{\mathrm{in}})^{-1}\hat\beta\\
    =&-\frac{1}{2\sigma_N^2}\hat\beta^{\intercalp}( \sigma_N^{2}F_\mathrm{in}^{-1} + R_{\mathrm{in}}R_{\mathrm{in}}^{\dagger}R_{\mathrm{in}})^{-1}\hat\beta\\
    =&\frac{1}{2\sigma_N^2}\hat\beta^{\intercalp}( R_{\mathrm{in}}\sigma_N^{-2}F_\mathrm{in}R_{\mathrm{in}} + R_{\mathrm{in}})^{\dagger}\hat\beta-\frac{1}{2\sigma_N^2}\hat\beta^{\intercalp}R_{\mathrm{in}}^{\dagger}\hat\beta
\end{aligned}
\end{equation*}
which is equal to the first two terms of Eqn.~\ref{eqn: beta diff lik}.
Meanwhile by a similar application of the matrix determinant lemma,
the last two terms Eqn.~\ref{eqn: y diff lik} are equal to the last two terms of Eqn.~\ref{eqn: beta diff lik}.
The same is true replacing $X_\mathrm{in}$ with only held out chromosomes $X_\mathrm{out}$.

\section{Data Collection}\label{app: download data}
\subsection{UKBB public statistics}\label{app: ukbb data}
We downloaded UK biobank LD matrices computed in \citet{Weissbrod2020-zo} from the Amazon web services S3 container \url{s3://broad-alkesgroup-ukbb-ld/UKBB_LD/}.
These matrices can have small negative eigenvalues, which we removed prior to training.
We also, as is standard, do not include regions with long-range LD in chromosomes 6, 8, and 11.

We downloaded UK biobank association statistics computed using BOLT-LMM~\citep{Loh2015-kd} from the UKBB\_409K folder in \url{https://console.cloud.google.com/storage/browser/broad-alkesgroup-public-requester-pays}.
These association statistics also contained  frequencies of each variant.
Any variants that have LD information but that are missing associations are discarded;
    all variants with association information also had LD information.

UKBB coordinates are in GrCh37 but many of our features below are in the GrCh38 build.
We used rsid's and pyliftOver (\url{https://github.com/konstantint/pyliftover}) to map to GrCh38.
For the handful of variants we could not map we gave them the location of a nearby variant.



\subsection{Coding variant annotations}\label{app: anno tracks}
We downloaded the predictions of the effects of variants in coding regions from various models from \url{https://www.dbnsfp.org/}.
We used six predictions labeled \texttt{ESM1b\_score, GERP++\_RS, SIFT\_score, PROVEAN\_score, FATHMM\_score, EVE\_score}.
For non-coding variants or variants missing a prediction, we set $C=0$.

