\title{Beyond Advertising: Mechanism Design for Platform-Wide Marketing Service ``QuanZhanTui''}

\author{Ningyuan Li$^{1}$\thanks{This work is done during internship at Alibaba Group.}, Zhilin Zhang$^2$, Tianyan Long$^1$, Yuyao Liu$^2$,
Rongquan Bai$^2$,\\ Yurong Chen$^{3}$\footnotemark[1], Xiaotie Deng$^1$, Pengjie Wang$^2$, Chuan Yu$^2$, Jian Xu$^{2}$\thanks{Corresponding author.}, Bo Zheng$^2$\\
