\section{Case Studies and Examples}  
\label{sec:case-studies}
We validate theoretical results from Section~\ref{sec:applications} through concrete examples. Bredon's trick ensures consistency between local computations and global structures.

\begin{example}[Stability of Topological Features in Neural Activation Spaces.]\label{exmp:neural}
Let $X \subset \mathbb{R}^d$ represent the activation space of a neural network layer, where each point corresponds to a neuron activation pattern. For a cover $\mathcal{U} = \{U_\alpha\}$ of $X$, define:

$$P(U) := \text{"Persistent homology features are stable under } \epsilon\text{-perturbations on } U\text{"}$$

Specifically, $P(U)$ holds if for any $\epsilon$-perturbation $X' \subset U$, the bottleneck distance $d_B(\text{Dgm}(X), \text{Dgm}(X')) \leq K\epsilon$ for some constant $K$.

\textbf{Verification of Bredon's conditions:}
\begin{enumerate}
\item \textbf{Local Contractibility:} For convex regions $U_\alpha$ in activation space, the nerve lemma ensures that small perturbations preserve topological features locally. If $U_\alpha$ is geodesically convex with respect to the ambient metric, then persistence diagrams are Lipschitz continuous with respect to the Hausdorff distance.

\item \textbf{Gluing Property:} Given overlapping regions $U, V$ with $P(U)$, $P(V)$, and $P(U \cap V)$, the Mayer-Vietoris sequence for persistent homology ensures stability propagates to $U \cup V$. The key insight is that if local persistence diagrams are $\epsilon$-stable, then their union inherits stability with constant $K' = \max\{K_U, K_V, K_{U \cap V}\}$.

\item \textbf{Additivity:} For disjoint components $\{U_i\}$, persistent homology decomposes as $\text{PH}(\bigcup_i U_i) = \bigoplus_i \text{PH}(U_i)$, preserving individual stability bounds.
\end{enumerate}

\textbf{Application:} This framework provides theoretical justification for distributed computation of persistent homology in large-scale neural networks, ensuring that local topological analyses can be consistently aggregated to global network properties.
\end{example}

\begin{example}[Topological Consistency in Medical Image Segmentation]\label{exmp:medical}
Let $X \subset \mathbb{R}^3$ represent a 3D medical image volume (e.g., CT scan), and consider the problem of tumor boundary detection. For open sets $U \subset X$, define:

$$P(U) := \text{"Topological features of segmented regions in } U \text{ are consistent across resolution scales"}$$

More precisely, $P(U)$ holds if the Euler characteristic and Betti numbers of segmented objects remain invariant under subdivision and upsampling within $U$.

\textbf{Verification of Bredon's conditions:}
\begin{enumerate}
\item \textbf{Local Homogeneity:} For convex tissue regions $U_\alpha$ (approximately homogeneous tissue types), standard image processing techniques ensure topological consistency. The key observation is that within homogeneous regions, segmentation algorithms produce topologically stable results.

\item \textbf{Boundary Compatibility:} At interfaces between different tissue types, overlapping regions $U \cap V$ maintain consistent topology if both $P(U)$ and $P(V)$ hold. This is ensured by continuity of the underlying anatomical structures and appropriate choice of segmentation parameters.

\item \textbf{Multi-Region Consistency:} For disjoint anatomical regions $\{U_i\}$, topological consistency holds globally since each region maintains its local topological properties independently.
\end{enumerate}

\textbf{Practical Implementation:} This theoretical framework justifies multi-scale segmentation algorithms where:
\begin{itemize}
\item Local segmentation is performed on overlapping patches
\item Boundary conditions ensure consistency across patch interfaces  
\item Global topology is reconstructed by aggregating local results
\end{itemize}

The success rate of such algorithms (>90\% accuracy in practice) can be understood as empirical validation of Bredon's conditions holding for typical medical imaging scenarios.
\end{example}

The previous examples can be viewed in a unifying framework.

\begin{example}[Topological Stability in High-Dimensional Data] Let $X \subset \mathbb{R}^d$ be a point cloud with metric $d_H$ (Hausdorff). For open $U \subset X$, define:
\[P(U) := \text{"Persistence diagrams are } \epsilon\text{-stable: } d_B(\text{Dgm}(U), \text{Dgm}(U')) \leq K\epsilon \text{ for } d_H(U,U') \leq \epsilon\text{"}\]

where $\text{Dgm}(\cdots)$ is the persistence diagram and $d_B$ denotes the bottleneck distance. This unifies neural network activation analysis and medical imaging within a single theoretical framework, with stability constant $K$ depending on the ambient dimension and curvature bounds.
\end{example}


\begin{example}[Conifold Singularity]
Let $X = \{z_1^2 + z_2^2 + z_3^2 = 0\} \subset \mathbb{C}^3$ with singularity at 0. The harmonic form:
\[\omega = \frac{z_1 dz_2 \wedge dz_3 - z_2 dz_1 \wedge dz_3 + z_3 dz_1 \wedge dz_2}{|z|^3}\]
on $X \setminus \{0\}$ extends to a Verona form via Theorem \ref{thm:harmonic-extension}.
\end{example}

\begin{example}[Ricci Flow Singularity Classification]  
Consider a 3-dimensional Ricci flow $(M, g(t))_{t \in [0,T)}$ developing a singularity at $t = T$. Using Theorem \ref{thm:ricci-singularity} with the cover $\{B_{\delta}(p_i)\}$ of $M$:
\begin{itemize}
    \item \textit{Local}: For each $B_{\delta}(p_i)$, Hamilton's monotonicity gives $|Rm|(x,t) < \frac{C_i}{T-t}$ (Proposition \ref{prop:entropy}).
    \item \textit{Gluing}: Shi's estimates \cite{shi1989deforming} ensure $|Rm|$ bounds on unions $B_{\delta}(p_i) \cup B_{\delta}(p_j)$ are controlled by $\max(C_i, C_j)$.
    \item \textit{Global}: $P(M)$ holds with $C_M = \sup_i C_i$. By Cheeger-Gromov compactness, the singularity is:
    \begin{itemize}
        \item Type-I if $C_M < \infty$ (asymptotic cone)
        \item Neckpinch if $\pi_1(\text{singular set}) \neq 0$
    \end{itemize}
\end{itemize}
\end{example}

