\subsection{Main results}
This section gathers the proofs of our main results, along with the key auxiliary lemmas and technical estimates that are essential for establishing them.
\begin{proof}[Proof of Lemma \ref{lemma:integral}]
	We begin by applying the following change of variables to the integrand in \eqref{eq:genint}:
	\begin{equation*}
		x_1=ut; \quad x_2=v t, \quad x_3=t.
	\end{equation*}
	This change of variables is motivated by the idea of scaling all coordinates relative to the largest one, $t$, which serves as a natural normalization factor and which will be considered as the scaling variable. This transformation maps the original domain into a subdomain in the unit cube for the new variables.
	Geometrically, this corresponds to analyzing all triangles up to scale, with $t$ and $(u,v)$ describing the relative shape of the triangle. Also, by the analytical point of view, this choice aligns well with the structure of the function $\Delta$, since 
	\begin{equation*}
		\Delta(x_1,x_2,x_3)= t^4	\Delta(u,v,1) = t^4 Q(u,v).
	\end{equation*}
	Also, this factorization will be extremely helpful in integration, as it separates scale from shape. \\
	Under this change of variables, the integrand must be multiplied by the Jacobian $J$ determinant associated with the transformation, which accounts for the change in volume element. The Jacobian $J$ is given by
	\begin{equation*}
		J=\begin{pmatrix}
			t & 0 & u\\
			0 & t & v\\
			0 & 0 & 1 
		\end{pmatrix},
	\end{equation*}
	and $\text{det}J = t^2$.\\
	With regard to the integration domain, observe that the scaling variable $t$ lies in the interval $t\in(r/u,1)$. This follows from the constraints $t=x_3<1$, and $x_1=tu>r$, which jointly imply $t>r/u$. To determine the corresponding domain for the variables $(u,v)$,  begin by noting that both $u$ and $v$ must be strictly less than 1. Additionally, since. Additionally, since $u>r/t$ and $t<1$, it follows that $u>r$. Turning to $v$, we observe that $x_2=vt>x_1=ut$, implying $v>u$. Furthermore, applying the triangle inequality in the new coordinate system and dividing by $t$, we obtain the condition 
	\begin{equation*}
		v-u<1<u+v.
	\end{equation*}	
	The first inequality always holds, while the second gives $v>1-u$. Thus, combining these constraints, we find: 
	\begin{equation*}
		\max(u,1-u) <v<1.
	\end{equation*}
	It is easy to verify that $\max(u,1-u)= u $ whenever $u>1/2$. This observation motivates the definition of the subdomains $\Omega_{1,r}$, $\Omega_{2,r}$ and hence the full domain $\Omega_{r}$, as specified in Equation \eqref{eq:omegadomain}.\\
	Thus, defining $\lambda=a+b+c-4d+3$, Equation \eqref{eq:genint} becomes
	\begin{equation*}
		\begin{split}
			D_r(a,b,c,d) & = \int_{\Omega_r} \frac{u^av^b}{Q^{d}(u,v)} \left(\int_{\frac{r}{u}}^{1} t^{\lambda-1} \diff t \right) \diff u \diff v
		\end{split}.
	\end{equation*}
	Solving the integral with respect to the scaling variable leads to the integral \eqref{eq:Gfinale}, which only depends on the shapes variable and is finite for all the elements of the domain $\Omega_r$.
\end{proof}
\begin{proof}
	On the one hand, consider the following explicit formula for the Wigner $3j$ symbol with $m_1=m_2=m_3=0$ (see for example \cite[Eq. 3.61]{MaPeCUP}):%
	\begin{equation}\label{eq:wigner1}
		\begin{split}
			\wigner{\ell _{1}}{\ell _{2}}{\ell _{3}}{0}{0}{0}
			&=\left( -1\right) ^{\frac{\ell _{1}+\ell _{2}+\ell _{3}}{2}}\frac{\left( \frac{\ell
					_{1}+\ell _{2}+\ell _{3}}{2}\right) !}{\left( \frac{\ell _{1}+\ell _{2}-\ell
					_{3}}{2}\right) !\left( \frac{\ell _{1}-\ell _{2}+\ell _{3}}{2}\right)
				!\left( \frac{-\ell _{1}+\ell _{2}+\ell _{3}}{2}\right) !} \\
			&\times \sqrt{\frac{\left( \ell _{1}+\ell _{2}-\ell _{3}\right) !\left(
					\ell _{1}-\ell _{2}+\ell _{3}\right) !\left( -\ell _{1}+\ell _{2}+\ell
					_{3}\right) !}{\left( \ell _{1}+\ell _{2}+\ell _{3}+1\right) !}}\text{ ;}
		\end{split}
	\end{equation}%
	On the other hand, recall the Stirling approximation for the factorials (see, for example, \cite[Eq. 6.1.28]{handbook}): for any $n\in \mathbb{N}$, 
	\begin{equation}\label{eq:stirling}
		n! \simeq \sqrt{2\pi n} \left(\frac{n}{e}
		\right)^{n}
	\end{equation}
	Combining Eqq. \eqref{eq:wigner1} and \eqref{eq:stirling} we can approximate $\wigner{\ell _{1}}{\ell _{2}}{\ell _{3}}{0}{0}{0}$ with
	\begin{equation*}\label{eq:wigner2}
		\begin{split}
			\left( -1\right) ^{\frac{\ell _{1}+\ell _{2}+\ell _{3}}{2}}\sqrt{\frac{2e}{\pi}} \left(\frac{\ell_1+\ell_2+\ell_3}{\ell_1+\ell_2+\ell_3+1}\right)^{\frac{\ell_1+\ell_2+\ell_3-1}{2}}\\
			\times \left( \left( \ell _{1}+\ell
			_{2}+\ell _{3}+1\right) \left( \ell _{1}+\ell _{2}-\ell _{3}\right) \left(
			\ell _{1}-\ell _{2}+\ell _{3}\right) \left( -\ell _{1}+\ell _{2}+\ell
			_{3}\right) \right) ^{-\frac{1}{4}}  .
		\end{split}
	\end{equation*}
	Observe that for large $\ell_1,\ell_2,\ell_3$, we can approximate the last multiplicand in the previous formula with  $\Delta\left( \ell _{1},\ell _{2},\ell _{3}\right) ^{-\frac{1}{4}}$.
	Let us now define $\lambda=\ell_1+\ell_2+\ell_3$, so that 
	\begin{equation*}
		\begin{split}
			\left(\frac{\ell_1+\ell_2+\ell_3}{\ell_1+\ell_2+\ell_3+1}\right)^{\frac{\ell_1+\ell_2+\ell_3-1}{2}} &= 	\left(\frac{\lambda}{\lambda+1}\right)^{\frac{\lambda-1}{2}}\\
			&= 	\left(1-\frac{1}{\lambda+1}\right)^{\frac{\lambda-1}{2}}
		\end{split} .
	\end{equation*}
	Note that 
	\begin{equation*}
		\begin{split}
			\log \left(1-\frac{1}{\lambda+1}\right)^{\frac{\lambda-1}{2}} & = \frac{\lambda-1}{2}	\log \left(1-\frac{1}{\lambda+1}\right)\\ 
			&\underset{\lambda \rightarrow \infty}
			{\approx	}\frac{\lambda-1}{2}\frac{-1}{\lambda+1} \\
			& = -\frac{1}{2}+O\left(\frac{1}{\lambda}\right).	
		\end{split}
	\end{equation*}
	Thus 
	\begin{equation*}
		\left(\frac{\ell_1+\ell_2+\ell_3}{\ell_1+\ell_2+\ell_3+1}\right)^{\frac{\ell_1+\ell_2+\ell_3-1}{2}} \approx e^{-\frac{1}{2}},
	\end{equation*}
	and we obtain therefore \eqref{FlashGordon1}. 
\end{proof}
