		\etal^{\text{lim}} =C_{\eta^2} \frac{\ell _{1}^{1-\alpha}\ell_{2}^{1-\alpha}\ell _{3}^{1+\alpha}}  {\Delta\left(\ell_1,\ell_2, \ell_3\right)^{\frac{1}{2}}} .
	\end{align*}%
	Indeed, for $\ell_1 <\ell_2<\ell_3$, the dominant term in $\Gamma _{\ell _{1}\ell_{2}\ell _{3}}^{2}$ is $C_{\ell_1}C_{\ell_2}/C_{\ell_3}$, approximated by 
	\begin{equation*}
		A \left(\frac{\ell_1\ell_2}{\ell_3}\right)^{-\alpha}; 
	\end{equation*}
	in view of Lemma \ref{LemmaFlashGordon}, the squared Wigner $3j$-symbol $\begin{pmatrix}
		\ell _{1} & \ell _{2} & \ell _{3} \\ 
		0 & 0 & 0%
	\end{pmatrix}%
	^{2}$ is approximated by 
	\begin{equation*}
		\frac{2}{\pi} \Delta\left(\ell_1,\ell_2, \ell_3\right)^{-\frac{1}{2}};
	\end{equation*}
	finally, $\hal^2$ is approximated by 
	\begin{equation*}
		4\left(\frac{2}{ \pi}\right)^3\ell_1\ell_2\ell_3.
	\end{equation*}
	Thus we can approximate $\Seta$ with 
	\begin{align*}
		\Seta^{\text{lim}}= C_{\eta^2} \summinus \etal^{\text{lim}}.
	\end{align*}
	Analogously reasoning allows us to approximate
	\begin{equation*}
		\kappal =  \frac{(2\ell_1+1)(2\ell_2+1)^2(2\ell_3+1)^2}{(4\pi)^{3}}
		\begin{pmatrix}
			\ell _{1} & \ell _{2} & \ell _{3} \\ 
			0 & 0 & 0%
		\end{pmatrix}%
		^{4}\Gamma _{\ell _{1}\ell _{2}\ell _{3}}^{4}, 
	\end{equation*}
	with
	\begin{align*}
		\kappal^{\text{lim}} =C_{\kappa} \frac{\ell _{1}^{1-2\alpha}\ell_{2}^{2\left(1-\alpha\right)}\ell _{3}^{2\left(1+\alpha\right)}}  {\Delta\left(\ell_1,\ell_2, \ell_3\right)} ,
	\end{align*}
	such that  $\Skappa$ can be approximated with 
	\begin{align*}
		\Skappa^{\text{lim}}= C_{\kappa} \summinus \kappal^{\text{lim}}
	\end{align*}
	Also, as $L$ grows to infinity, $\Seta^{\text{lim}}$ and $\Skappa^{\text{lim}}$ are well-approximated by the Riemann integrals
	\begin{align*}
		& \int_{A_r}   \frac{ \left(Lx_1 \right)^{1-\alpha}  \left(Lx_2 \right)^{1-\alpha} \left(Lx_3 \right)^{1+\alpha}} {\Delta\left(L\ell_1,L\ell_2, L\ell_3\right)^{\frac{1}{2}}} L^3 \diff x_1 \diff x_2 \diff x_3 = 	L^{4-\alpha}I_{\eta^2;r}\left(\alpha\right),\\
		& \int_{A_r}   \frac{\left(Lx_1 \right)^{1-2\alpha}\left(Lx_2 \right)^{2\left(1-\alpha\right)}\left(Lx_3 \right)^{2\left(1+\alpha\right)}}  {\Delta\left(L\ell_1,L\ell_2, L\ell_3\right)} L^3 \diff x_1 \diff x_2 \diff x_3 = 	L^{4-2\alpha}I_{\kappa,r}\left(\alpha\right)
	\end{align*}
	where $A_r$ is given by \eqref{eq:intdomain} and the exponents are obtained by scaling the integrand functions, observing that $\Delta$ is homogeneous of degree $4$. \\
	In view of the results contained in Lemma \ref{lemma:integral} with $a=b=1-\alpha$, $c=1+\alpha$ and $d=1/2$,  we obtain $\lambda = 4-\alpha$ and 
	\begin{equation*}
		I_{\eta^2} (\alpha) = \frac{1}{4-\alpha} \int_{\Omega_r} \frac{(uv)^{1-\alpha}}{Q(u,v)^{\frac{1}{2}}} \left(1-\left(\frac{r}{u}\right)^{4-\alpha} \right) \diff u \diff v.
	\end{equation*}
	Analogously, for $a=1-2\alpha$, $b=2(1-\alpha)$, $c=2(2+\alpha)$ and $d=1$,  we obtain $\lambda = 4-2\alpha$ and 
	\begin{equation*}
		I_{\kappa} (\alpha) = \frac{1}{2(2-\alpha)} \int_{\Omega_r} \frac{u^{1-2\alpha}v^{2(1-\alpha)}}{Q(u,v)} \left(1-\left(\frac{r}{u}\right)^{2(2-\alpha)} \right) \diff u \diff v,
	\end{equation*}
	as claimed.
\end{proof}
\begin{proof}[Proof of Lemma \ref{lemmaest}]
	First, note that combinng the results in Proposition \ref{prop:Best} with Equations \eqref{eq:Bisp} and \eqref{eq:vec}, it holds that
	\begin{equation*}
		\begin{split}
			\Ex{\fNLest} & =  \Ex{\frac{H^T Y}{H^T H}}\\
			&=\frac{H^T \Ex{Y}}{H^T H}\\
			&=\fNL \frac{H^T H}{H^T H} + o\left(\fNL\right)\\
			&=\fNL + o\left(\fNL\right),
		\end{split}
	\end{equation*}
	Aiming at the variance, using the uncorrelation between the entries of $Y$ and the fact that $\Var{Y} = \bm{1}_{N_L}$, where $\bm{1}_{N_L}$ is the identity matrix of dimension $N_L$, we have that	
	\begin{equation*}
		\begin{split}
			\Var{ \fNLest } &= \Var{\frac{H^TY}{H^TH}}\\
			&=  \frac{1}{\left(H^TH\right)^2} H^T \Var{Y} H \\ 
			&=  \frac{1}{\left(H^TH\right)^2} H^T\bm{1}_{N_L} H \\
			& =  \frac{1}{H^TH}\\
			& =  \frac{1}{\summinus \etal ^2}\\
			&= \Seta^{-1}.
		\end{split}
	\end{equation*}
	Using Lemma \ref{lemma:eta} yields
	\begin{equation*}
		\begin{split}
			\Var{ \fNLest } &= \frac{1}{C_{\eta^2;r}I_{\eta^2;r}\left(\alpha\right)} L^{\alpha-4}+ o\left(L^{\alpha-4}\right)\\
			& = \sigma_{\fNL}^2 L^{\alpha-4}+ o\left(L^{\alpha-4}\right),
		\end{split}
	\end{equation*}
	as claimed.\\
	On the other hand, observe that 
	\begin{equation*}
		\begin{split}
			\cumq{\fNLest} & = \cumq{\frac{H^TY}{H^TH}}\\
			&= \frac{1}{\left(H^TH\right)^4}	\cumq{H^TY} \\
			& =  \frac{1}{\left(\summinus \etal ^2\right)^4}  \summinus \etal ^4 \cumq{\Bispest}\\
			& \leq  \frac{1}{\left(\summinus \etal ^2\right)^4}  \summinus \kappa_{\ell_1,\ell_2,\ell_3}\etal ^4  \frac{12}{2\ell_1+1}\\
			&= \frac{\Skappa}{\Seta^4}
		\end{split} 
	\end{equation*}
	Using Lemma \ref{lemma:eta} leads to
	\begin{equation*}
		\begin{split}
			\cumq{\fNLest} % & = frac{C_{\kappa}I_{\kappa;r}\left(\alpha\right)L^{2\left(2-\alpha\right)}}{C_{\eta^2}^4 I^4_{\eta;r}\left(\alpha\right) L^{4\left(4-\alpha\right)}}\\
			& = \frac{C_{\kappa}I_{\kappa;r}\left(\alpha\right)}{C_{\eta^2}^4 I^4_{\eta;r}\left(\alpha\right) }L^{-12+2\alpha}+o\left(L^{-12+2\alpha}\right)\\
			& = K_{\fNL}L^{-12+2\alpha}+o\left(L^{-12+2\alpha}\right).
		\end{split} 
	\end{equation*}
	This completes the proof.
\end{proof}
\begin{proof}[Proof of Theorem \ref{thm:main}]
	As detailed in \cite{noupebook}, see also \cite{MaPeCUP}, the following bound holds
	\begin{equation*}
		\dW\left( \fNLest - \fNL, Z \right) \leq \frac{2\sqrt{2}}{3}
		\sqrt{\frac{\cumq{\fNLest} }{\left(\Var{\fNLest}\right)^2 }}.
	\end{equation*}
	Using the results collected in Proposition \ref{lemmaest}, We have that 
	\begin{equation*}
		\begin{split}
			\frac{\cumq{\fNLest} }{\left(\Var{\fNLest}\right)^2} &= \frac{K_{\fNL}}{\sigma^4_{\fNL}} L^{-4}\\
			&= \frac{C_{\kappa}I_{\kappa;r}(\alpha)}{C_{\eta^2;r}^2I^{2}_{\eta^2;r}(\alpha)} L^{-4}.
		\end{split}
	\end{equation*}
	Finally, note that 
	\begin{equation*}
		\begin{split}
			\frac{C_{\kappa}}{C_{\eta^2;r}^2} = \frac{3A^2}{8\pi^8}\frac{16\pi^8}{A^2}=6.
		\end{split}
	\end{equation*}
	Thus, 
	\begin{align*}
		\frac{2\sqrt{2}}{3}\sqrt{\frac{\cumq{\fNLest} }{\left(\Var{\fNLest}\right)^2 }} & =\frac{4}{\sqrt{3}}\frac{I^{\frac{1}{2}}_{\kappa;r}\left(\alpha\right)}{I_{\eta^2;r}\left(\alpha\right)} L^{-2},
	\end{align*}
	as claimed.
\end{proof}
