\textbf{Remark 1}: \emph{To further illustrate the relationship between time-scaled wideband doubly-dispersive channels \cite{d1} considered in this paper and narrowband channels \cite{d9}, we consider a communication system with bandwidth $B$, carrier frequency $f_c$ and duration $T$, i.e. $t \in \left[ 0 , T\right] , f \in \left[ - \frac{B}{2} , \frac{B}{2} \right]  $. Then, the time-scaled wideband doubly-dispersive channels can be simplified to narrowband case with the following conditions \cite{d3}:}

\emph{(1) The transmission bandwidth $B$ is negligible relative to the carrier frequency $f_c$, i.e.} $B / f_c \ll 1$.

\emph{(2) The relative position of the transmitter and receiver does not change significantly relative to the positional resolution of the transmitted signal, i.e.} $ v / \tilde{c} = \alpha \ll 1 / (BT)$,\footnote{\label{n1}Note that the relative velocity and Doppler scale factor of $i$-th path are the corresponding $v_i$ and $\alpha_i$, respectively.} \emph{where} $v$ \emph{is the relative velocity of the transmitter and receiver,} $\tilde{c}$ \emph{is the propagation medium speed.}

\emph{Under the above two conditions, the wideband time-frequency response} $G(t, f)$ \emph{in \eqref{2}}  \emph{can be reduced to}
\begin{align}\label{3}
	G(t,f) \approx \sum_{i=1}^{P} {h}_i e^{- j 2 \pi f \tau_i} e^{j 2 \pi \nu_i  t },
\end{align}
\emph{which is consistent with the narrowband channel model \cite{d9}.}

\subsection{AFDM Transmission}
In this paper, we consider the AFDM transmission of $N$ constellation mapped symbols (such as QPSK, 16QAM) with duration $T = N \varDelta t$ and bandwidth $B = N \varDelta f$, where $\varDelta t = 1 / B$ and $\varDelta f = 1 / T$. The transmitted symbols $x[m], m= 0, 1, ... , N-1$ from a constellation alphabet $  \mathbb{A} \!=\! \left\lbrace a_1 , a_2 , ..., a_Q \right\rbrace $ are firstly mapped into the DAF domain.
Then, the time domain signal $x_{\text{T}} [n]$ is obtained by applying the inverse DAF (IDAF) transform to $x[m]$,
\begin{align}\label{4}
	x_{\text{T}} [n] = \frac{1}{\sqrt{N}} \sum_{m=0}^{N-1} x[m] e^{j 2 \pi \left(c_1 n^2 + m n / N + c_2 m^2 \right) },
\end{align}
where $n = 0, 1, ..., N-1$. $c_1$\footnote{\label{n2}Note that the AFDM chirp parameter $c_1 > 0$ or $c_1 < 0$ only represents the positive and negative chirp rates. In this paper, we primarily discuss the case of $c_1 > 0$ and the similar observations can be also obtained for the case of $c_1 < 0$.} and $c_2$ are the AFDM chirp parameters, which can be optimized to improve the system performance based on channel spread characteristics. We will discuss the detailed design guidelines of AFDM chirp parameters in Section \uppercase\expandafter{\romannumeral3}. 

To combat ISI and maintain the periodicity of AFDM symbols under time-scaled wideband doubly-dispersive channels, we develop an efficient CPP and CPS transmission frame structure for AFDM system. With the AFDM symbols periodicity defined in \cite{d9}, the CPP and CPS can be expressed as
\begin{subequations}\label{5}
	\begin{equation}
		{x}_{\text{T}} [n] = x_{\text{T}} [n + N] e^{- j 2 \pi c_1 \left( N^2 + 2 N n\right) } , n \in \left[ - L_{cpp} , 0 \right),
	\end{equation}
	\begin{equation}
		x_{\text{T}} [n] = x_{\text{T}} [n - N] e^{ j 2 \pi c_1 \left(  N^2 + 2 N n \right) } , n \in \left[  N , N + L_{cps}\right],
	\end{equation}
\end{subequations}
where $L_{cpp}$ and $L_{cps}$ are the length of added CPP and CPS, respectively. Here, we denote $T_{cpp} = L_{cpp} \varDelta t$ and $T_{cps} = L_{cps} \varDelta t$ as the continuous time length of CPP and CPS. For simplicity, we consider the AFDM symbol starting time of $1$-st path as the time reference, the correspondingly received observation window is given by $\left[ 0 , T \right) $. According to \eqref{1}, the time-scale $t$ of the $i$-th path AFDM symbol satisfies 
	\begin{align}\label{6}
		0 \leq t - \left( \tau_i - \alpha_i t \right) < T , i = 1, 2, ..., P.
\end{align}

Consequently, the corresponding start and end time of the $i$-th path AFDM symbol are given by $\tau_i / (1 + \alpha_i)$ and $(T + \tau_i) / (1 + \alpha_i)$, as shown in Fig. \ref{fig_1}. Therefore, adding the CPP with duration $ T_{cpp} > \tau_{max} / (1 - \alpha_{max})$ and CPS with duration $ T_{cps} > \alpha_{max} T / (1 + \alpha_{max} )$ are essential to combat the delay and time-scaling effects and 
ensure the continuous periodicity of received AFDM symbols within the observation window.
The total duration $T_f$ of each AFDM frame is given by $T_f = T_{cpp} + T + T_{cps}$.\footnote{\label{n3}Note that the maximum Doppler scale factor $\alpha_{max}$ is typically small in practice. We can use the wideband underwater acoustic channels and the wideband wireless communication channels as examples for explanation. 
The maximum residual Doppler scale factor after resampling usually satisfies $\alpha_{max} < 10^{-4}$ in underwater acoustic channels \cite{d39, d40, d41} and $\alpha_{max} < 10^{-6}$ in wideband wireless radio communication channels \cite{d42, d43, d44}. Consequently, the duration of $T_{cps}$ is usually very small and has a negligible impact on spectral efficiency in practice.}

According to \cite{d10, d11, d12}, the correspondingly continuous time domain AFDM signal $x_{\text{T}}(t)$ can be given by 
\begin{align}\label{7}
	x_{\text{T}} (t) = \sum_{m=0}^{N-1} x[m] \Phi_{t} (m),  t \in \left[0 , T \right),
\end{align}
where 
\begin{align}\label{8}
	\Phi_{t} (m) = \frac{1}{\sqrt{N}} e^{j 2 \pi \left( c_1 \frac{N^2}{T^2} t^2 + \frac{m t}{T} + c_2 m^2 - \frac{\psi_{m, t} N}{T} t \right)   },
\end{align}
$\psi_{m, t}$ is the piece-wise function on intervals corresponding to the specific time partition, i.e.,
\begin{align}\label{9}
	\psi_{m, t} = 
	\begin{cases}
		0 , & 0 \leq t < \tilde{t}_{m,1} \\ 
		1 , & \tilde{t}_{m,1} \leq t < \tilde{t}_{m,2} \\
		~~\vdots, & ~~~~~~~\vdots \\
		\tilde{C}, & \tilde{t}_{m,\tilde{C}} \leq t < T
	\end{cases}
\end{align}
with
\begin{align}\label{10}
	\tilde{t}_{m, \rho} = 
	\begin{cases}
		0 , & \rho = 0 \\ 
		\left( \frac{N-m}{2N c_1} + \frac{\rho - 1}{2 c_1}\right) \frac{T}{N}  , & \rho = 1, 2, ..., \tilde{C}
	\end{cases}
\end{align}
and $\tilde{C} = 2 N c_1$.
