Then, the discrete time domain received signal $ y_{\text{T}}[n] $ can be obtained by sampling $ y_{\text{T}}(t)$, 
\begin{align}\nonumber
	 & y_{\text{T}} [n] = y_{\text{T}}(t) \left. \right|_{t = n \varDelta t} \\ \label{13}
	& = \sum_{i = 1}^{P} {h}_i {x}_{\text{T}} \left(  (n - {\ell}_{i} + \alpha_i n) \varDelta t  \right)  e^{j 2 \pi  k_{i} n / N} + \omega_{\text{T}} (n \varDelta t) ,
\end{align}
where $n = 0, 1, ..., N-1$,  $ \ell_{i} = \tau_i / \varDelta t$ and  $  k_{i} = \nu_i N  \varDelta t$.

The corresponding input-output relationship of discrete time domain signal can be vectorized as
\begin{align}\label{14}
	\mathbf{y}_{\text{T}} = \bar{\mathbf{H}}_{\text{T}} \mathbf{x}_{\text{T}} + \boldsymbol{\omega}_{\text{T}} = \sum_{i=1}^{P} h_i \mathbf{H}_{\text{T},i} \mathbf{x}_{\text{T}} + \boldsymbol{\omega}_{\text{T}},
\end{align}
where $\bar{\mathbf{H}}_{\text{T}} = \sum_{i=1}^{P} h_i \mathbf{H}_{\text{T},i} $ is the time domain equivalent channel matrix and ${H}_{\text{T},i} [\bar{p},\bar{q}]$ is given by
\begin{align}\label{15}
	H_{\text{T},i}[\bar{p},\bar{q}] =  e^{j 2 \pi  \left[c_1 \left( \bar{p} - \ell_i + \alpha_i \bar{p}\right)^2 - c_1\bar{q}^2 + k_{i} \bar{p} / N \right]  } \mathcal{F}_{\text{T},i} [\bar{p},\bar{q}]
\end{align}
with
\begin{align}\nonumber
	& \mathcal{F}_{\text{T},i}  [\bar{p},\bar{q}] = \label{16} \\
	&\frac{1}{N} \sum_{m=0}^{N-1} e^{j 2 \pi \left\lbrace \left[ (1 + \alpha_i)\bar{p} \!-\! \bar{q} \!-\! \ell_i\right]  \frac{m}{N} \!-\! \left( \psi_{m, (\bar{p} \!-\! \ell_i \!+\! \alpha_i \bar{p}) \varDelta t } \!-\! \psi_{m, \bar{q}\varDelta t } \right) \right\rbrace}.
\end{align}

Finally, the AFDM output symbol $y[m]$ can be obtained by applying the DAF transform to $y_{\text{T}}[n]$,
\begin{align}\label{17}
	y[m] = \frac{1}{\sqrt{N}} \sum_{n=0}^{N-1} y_{\text{T}}[n] e^{-j 2 \pi \left(c_1 n^2 + m n / N + c_2 m^2 \right) } .
\end{align}

By substituting \eqref{7} and \eqref{13} into \eqref{17}, the input-output relationship of AFDM system in time-scaled wideband doubly-dispersive channels can be given by
\begin{align}\label{18}
	\mathbf{y} = \bar{\mathbf{H}} \mathbf{x} + \boldsymbol{\omega} = \sum_{i=1}^{P} {h}_i \mathbf{H}_i \mathbf{x} + \boldsymbol{\omega},
\end{align}
where $\boldsymbol{\omega}$ is the DAF domain noise with same distribution as $\boldsymbol{\omega}_{\text{T}}$. $\bar{\mathbf{H}} = \sum_{i=1}^{P} {h}_i \mathbf{H}_i $ is the DAF domain equivalent channel matrix and  $H_i \left[ p , q \right] $ is given by
\begin{align}\label{19}
	H_i[p,q] = \frac{1}{N} e^{j 2 \pi \left[ c_1 \ell_{i}^2 - q \ell_{i}/N + c_2 (q^2 - p^2) \right] } \mathcal{F}_i \left( p , q \right)
\end{align}
with
\begin{align}\nonumber
	&\mathcal{F}_i \left( p , q \right) \!=\! \label{20} \\
	&\sum_{n=0}^{N-1} \! e^{j 2 \pi \left\lbrace c_1 \left( \alpha_i^2 \!+\! 2 \alpha_i \right) n^2 \!-\! \left[ p \!-\! (1 \!+\! \alpha_i) q \!+\! 2 N c_1 (1 \!+\! \alpha_i) \ell_{i}  \!-\! k_{i} \!+\! \psi_{m, t_i'} \alpha_i N \right] \frac{n}{N} \right\rbrace }\!
\end{align}
and  $t_i' = (n - {\ell}_{i} + \alpha_i n) \varDelta t$. 
Alternatively, we can describe the relationship between time domain signal $\left\lbrace \mathbf{y}_{\text{T}}, \mathbf{x}_{\text{T}}, \boldsymbol{\omega}_{\text{T}} \right\rbrace $ and DAF domain signal $\left\lbrace \mathbf{y}, \mathbf{x}, \boldsymbol{\omega} \right\rbrace $ in vector representation with
\begin{align}\label{21}
	\mathbf{y} = \mathbf{U} \mathbf{y}_{\text{T}},   
	\mathbf{x} = \mathbf{U} \mathbf{x}_{\text{T}},  \boldsymbol{\omega} = \mathbf{U} \boldsymbol{\omega}_{\text{T}},
\end{align}
where $\mathbf{U} = {\boldsymbol{\Lambda}_{c_2} \mathbf{F}_{N} \boldsymbol{\Lambda}_{c_1}} $ is the DAF transform matrix, $\boldsymbol{\Lambda}_{c_b} = \text{diag} \{e^{-j2\pi c_b n^2}, n = 0, 1, ..., N-1, b = 1,2\}$, and the corresponding IDAF transform matrix is given by $\mathbf{U}^{\text{H}}$. 
Similarly, we can also describe the relationship between time domain equivalent channel $\bar{\mathbf{H}}_{\text{T}}$ and the DAF domain equivalent channel $\bar{\mathbf{H}}$ in matrix representation with
\begin{align}\label{22}
	\bar{\mathbf{H}} = \mathbf{U} \bar{\mathbf{H}}_{\text{T}} \mathbf{U}^{\text{H}}.
\end{align}

\subsection{Principle of Stationary Phase (POSP) Approximation}
To effectively explore the potential of AFDM systems in time-scaled wideband doubly-dispersive channels, it is essential to analyze the DAF domain equivalent channel structure $\bar{\mathbf{H}}$. From \eqref{19}, we observe that the structure of $H_i[p,q]$ primarily depends on $ \mathcal{F}_i \left( p , q \right) $. However, since  $ \mathcal{F}_i \left( p , q \right) $ involves summation of complex exponential terms with quadratic phase variation, deriving an analytical expression is challenging. 
To intuitively explain the structure of DAF domain equivalent channel, we employ the POSP method to obtain a simplified approximate analytical expression of $  \mathcal{F}_i \left( p , q \right) $. 

For the integral (summation for discrete signals) of a continuous complex exponential signal with quadratic phase variation and a slowly time-varying envelope, the POSP method can effectively approximate the true solution. A typical application of POSP method is in approximating the analytical solution of the linear frequency modulation (LFM) signal spectrum \cite{d45}.
To facilitate analysis, we can rewrite $\mathcal{F}_i \left( p , q \right)$ as
\begin{align}\label{23}
	\mathcal{F}_i \left( p , q \right) = \sum_{n=0}^{N-1} \underbrace{\text{Rect} \left( \frac{n}{N-1}\right) e^{j 2 \pi \theta_{p,q} \left( n \right) } }_{\mathcal{E}_i \left(p,q \right) } ,
\end{align}
where
\begin{subequations}\label{24}
	\begin{align}
		& \theta_{p,q} \left( n \right)  =  K n^2 / 2 - \varphi_{p,q} n, \\
		& K = 2 c_1 \left( \alpha_i^2 + 2 \alpha_i \right), \\
		& \varphi_{p,q} = \left[ p \!-\! (1 \!+\! \alpha_i) q \!+\! 2 N c_1 (1 \!+\! \alpha_i) \ell_{i}  \!-\! k_{i} \!+\! \psi_{m, t_i'} \alpha_i N \right]  / N.
	\end{align}
\end{subequations}

The $\text{Rect} \left( \cdot \right) $ denotes the rectangular window function, which is given by
\begin{align}\label{25}
	\text{Rect} \left( \frac{n}{N-1} \right) = 
	\begin{cases}
		1 , 0 \leq  \frac{n}{N-1} \leq 1 \\ 
		0 , \text{otherwise} 
	\end{cases}\!\!\!\!.
\end{align}

We can observe that the envelope of the signal $\mathcal{E}_i \left( p , q \right) $ remains constant over the integration interval, i.e., $\text{Rect} \left( \frac{n}{N-1}\right) $, which satisfies the POSP approximation constraints condition for a slowly time-varying envelope. According to POSP, the main contribution to the summation in \eqref{23} is from the nearby region of the stationary phase point. 
Then, the stationary phase point $\tilde{n}$ can be obtained by $\partial \theta_{p,q} / \partial n = 0$, i.e.,
\begin{align}\label{26}
	\tilde{n}  = \frac{\varphi_{p,q}}{K} 	= \frac{p \!-\! (1 \!+\! \alpha_i) q \!+\! 2 N c_1 (1 \!+\! \alpha_i) \ell_{i}  \!-\! k_{i} \!+\! \psi_{m, t_i'} \alpha_i N}{2 N c_1 \left( \alpha_i^2 \!+\! 2 \alpha_i \right) } .
\end{align}

According to the POSP method \cite{d45}, $  \mathcal{F}_i \left( p , q \right) $ can be finally approximated as
\begin{align}\label{27}
	\mathcal{F}_i \left( p , q \right) \approx \frac{1}{\sqrt{K}} \text{Rect} \left(  \frac{\tilde{n}}{N-1}   \right)  e^{j 2 \pi \left( \frac{K}{2} \tilde{n}^2 - \varphi_{p,q} \tilde{n}\right) } .
\end{align}

Here, we directly apply the conclusions of the POSP method and omit the mathematical derivations due to the space limitation. More details about POSP method can refer to \cite{d45}. Subsequently, the magnitude of $\left| H_i \left( p, q \right)  \right| $ can be approximated as
\begin{align}\nonumber
	\left| H_i \left( p, q \right)  \right| & = \left| \frac{1}{N} e^{j 2 \pi \left[ c_1 \ell_{i}^2 - q \ell_{i}/N + c_2 (q^2 - p^2) \right] } \mathcal{F}_i \left( p , q \right)  \right| \\ \label{28}
	& = \frac{1}{N} \left| \mathcal{F}_i \left( p , q \right) \right| \approx \frac{1}{N \sqrt{K}} \text{Rect} \left(  \frac{\tilde{n}}{N-1}   \right).
\end{align}

\subsection{Equivalent Channel Sparsity Analysis}
According to \eqref{28}, the $i$-th path non-zero elements satisfy
\begin{align}\label{29}
	0 \leq \frac{p - (1 + \alpha_i) q + 2 N c_1 (1 + \alpha_i) \ell_{i}  - k_{i} + \psi_{m, t_i'} \alpha_i N }{2 N (N-1) c_1 \left( \alpha_i^2 + 2 \alpha_i \right) } \leq 1.
\end{align}

It is worth noting that we primarily discuss the case of 
$c_1 > 0$ in this paper, and the maximum Doppler scale factor usually satisfies $\alpha_{max} < 10^{-4}$, i.e., $ |2 \alpha_{i}| > \alpha_{i}^2 $. Therefore, it can be shown that the $p$-th row of DAF domain equivalent channel in the $i$-th path satisfies $ \left|  H_i \left( p , q \right) \right| \neq 0 $ under POSP approximation only when
\begin{align}\label{30}
	q \in [Q_{\ell_i,\alpha_i} , \tilde{Q}_{\ell_i,\alpha_i}]_N,
\end{align}
where 
\begin{subequations}\label{31}
\begin{align}
	Q_{\ell_i,\alpha_i} \!\!=\! \!
	\begin{cases}
		2 N c_1 \ell_{i} \!+\! \frac{p  \!-\! k_{i} \!-\! 2  c_1 \left( \alpha_i^2 \!+\! 2 \alpha_i \right) N \left( N \!-\! 1 \right) + \psi_{m, t_i'} \alpha_i N }{1 \!+\! \alpha_i},\!\!\!\!\! & \alpha_i \! \geq  \! 0 \\ 
		2 N c_1 \ell_{i} + \frac{p  - k_{i} + \psi_{m, t_i'} \alpha_i N}{1 + \alpha_i} \!,\! &  \alpha_i \!<\! 0
	\end{cases}
\end{align}
and
\begin{align}
	\tilde{Q}_{\ell_i,\alpha_i} \!\!=\! \!
	\begin{cases}
		2 N c_1 \ell_{i} + \frac{p  - k_{i} +\psi_{m, t_i'} \alpha_i N}{1 + \alpha_i}, & \alpha_i \! \geq 0  \! \\ 
		2 N c_1 \ell_{i} \! + \! \frac{p  \!-\! k_{i} \!-\! 2  c_1 \left( \alpha_i^2 \!+\! 2 \alpha_i \right) N \left( N \!-\! 1 \right)  + \psi_{m, t_i'} \alpha_i N}{1 \!+\! \alpha_i},\!\!\!\!\! & \alpha_i \!< \! 0
	\end{cases}
	\!.\!
\end{align}
\end{subequations}

According to \eqref{9}, $\psi_{m, t_i'}$ is the piece-wise function and $\psi_{m, t_i'} \in [0, 2 N c_1]$, we then further strengthen the boundary in \eqref{31} as
\begin{subequations}\label{32}
	\begin{align}
		Q_{\ell_i,\alpha_i} \!=\! 
		\begin{cases}
			2 N c_1 \ell_{i} \!+\! \frac{p  \!-\! k_{i} \!-\! 2  c_1 \left( \alpha_i^2 \!+\! 2 \alpha_i \right) N \left( N \!-\! 1 \right)}{1 \!+\! \alpha_i},\! & \alpha_i  \geq 0 \\ 
			2 N c_1 \ell_{i} + \frac{p  - k_{i} + 2 c_1 \alpha_i N^2 }{1 + \alpha_i} \!,\! &  \alpha_i < 0
		\end{cases}
	\end{align}
	and
	\begin{align}
		\tilde{Q}_{\ell_i,\alpha_i} \! =\! 
		\begin{cases}
			2 N c_1 \ell_{i} + \frac{p  - k_{i} + 2 c_1 \alpha_i N^2}{1 + \alpha_i}, & \alpha_i  \geq 0 \\ 
			2 N c_1 \ell_{i} \! + \! \frac{p  \!-\! k_{i} \!-\! 2  c_1 \left( \alpha_i^2 \!+\! 2 \alpha_i \right) N \left( N \!-\! 1 \right) }{1 \!+\! \alpha_i}\!,\! & \alpha_i < 0
		\end{cases}
		\!.\!
	\end{align}
\end{subequations}


