%	Q_{\ell_i,\alpha_i} \approx \tilde{Q}_{\ell_i,\alpha_i} \approx p + 2 N c_1 \ell_{i}  - k_{i}
%\end{align}

\emph{The input-output relationship in \eqref{35} can be reduced to}
\begin{align}\nonumber
	y \left[ p \right] \approx & \sum_{i=1}^{P} \frac{1}{N} {h}_i \sum_{q = [ Q_{\ell_i,\alpha_i} \!-\! N_v ]_N }^{[ Q_{\ell_i,\alpha_i} \!+\! N_v ]_N }  x[q]  e^{j 2 \pi \left[ c_1 \ell_{i}^2 \!-\! q \ell_{i}/N \!+\! c_2 (q^2 \!-\! p^2) \right] } \\ \label{38}
	& \times \frac{e^{-j 2 \pi \left( p - q + 2 N c_1  \ell_{i} - k_{i}\right) } - 1}{e^{-j \frac{2 \pi}{N} \left( p - q + 2 N c_1  \ell_{i} - k_{i}\right) } - 1} + \omega [p],
\end{align}
\emph{which is consistent with the input-output relationship of narrowband AFDM systems  mentioned in \cite{d9}.}

