\section{AFDM Chirp Parameters Optimization}
From \eqref{33}, we observe that the wideband DAF domain equivalent channel representation depends on AFDM chirp parameters $c_1$ and $c_2$, where $c_1$ affects the DAF domain equivalent channel sparsity structure and $c_2$ only affects the phase shift. Therefore, we mainly focus on optimizing the chirp parameter $c_1$ to exploit the underlying wideband channel diversity, while $c_2$ is selected as an arbitrary irrational number as mentioned in \cite{d9}. 

According to \eqref{32}, we can obtain $Q_{\ell_i,\alpha_{max}} < Q_{\ell_i,-\alpha_{max}}$ and $\tilde{Q}_{\ell_i,\alpha_{max}} < \tilde{Q}_{\ell_i,-\alpha_{max}}$. 
For any $\ell_i \in [0, \ell_{max}]$, $\alpha_i \in \left[ - \alpha_{max} , \alpha_{max} \right]$ and  $k_i \in \left[ - k_{max} , k_{max} \right]$, the any $p$-th row non-zero elements range of $  \mathbf{H}_i $ can be given by
\begin{align}\label{39}
	q \in [ Q_{\ell_i,\alpha_{max}} - N_v , \tilde{Q}_{\ell_i , - \alpha_{max}} + N_v  ]_N .
\end{align}

Then, our target is to ensure that the non-zero entries in $\mathbf{H}_i$ and $\mathbf{H}_j$ do not overlap for any $i$ and $j$. In other words, the intersection of the non-zero entries between the $i$-th path and the  $j$-th path should be empty, i.e.,
\begin{align}\nonumber
	& [ Q_{\ell_i,\alpha_{max}} - N_v , \tilde{Q}_{\ell_i , - \alpha_{max}} + N_v ]_N  ~ \cap \\ \label{40}
	& [ Q_{\ell_j,\alpha_{max}} - N_v , \tilde{Q}_{\ell_j , - \alpha_{max}} + N_v ]_N  = \emptyset ,
\end{align}
where $i, j \in \left\lbrace 1, ... , P \right\rbrace$ and $i \neq j$. Here, we assume that $\ell_i < \ell_j$, then the constraint \eqref{40} can be converted to the following inequalities,
\begin{subequations}\label{41}
	\begin{align}
		Q_{\ell_j,\alpha_{max}} - N_v & > \tilde{Q}_{\ell_i , - \alpha_{max}} + N_v ,\label{41a} \\ 
		(\tilde{Q}_{\ell_{max} , - \alpha_{max}} + N_v)  & - (Q_{0,\alpha_{max}} - N_v) < N. \label{41b}
	\end{align}
\end{subequations}

Under the constraint \eqref{41a}, we can substitute \eqref{32} into \eqref{41a}, and the AFDM chirp parameter $c_1$ should satisfy
\begin{align}\label{42}
	c_1 > \frac{ 2 k_{{max}}  +  2 p \alpha_{max} +  2 (1 - \alpha_{max}^2) N_v }{  2 N[ \left( 1 \!-\! \alpha_{max}^2 \right)( \ell_{{j}} \!-\! \ell_{{i}}) \!-\! 2 \alpha_{max} \left( 2 \!-\! \alpha_{max}^2 \right) \left( N \!-\! 1 \right) ] }.
\end{align}

To ensure \eqref{42} always holds for any $p \in [0, N-1]$, $\ell_i$ and $\ell_j$ with $\ell_i < \ell_j$, while minimizing $c_1$ to achieve a more sparser DAF domain equivalent channel representation, the AFDM chirp parameter $c_1$ can be set as
\begin{align}\label{43}
	c_1 \!=\! \frac{2 k_{{max}} \!+\!  2 \alpha_{max} (N-1)  \!+\!  2 (1 \!-\! \alpha_{max}^2) N_v  \!+\! 1 }{ 2 N[ \left( 1 \!-\! \alpha_{max}^2 \right)( \ell_{\tilde{j}} \!-\! \ell_{\tilde{i}}) \!-\! 2 \alpha_{max} \left( 2 \!-\! \alpha_{max}^2 \right) \left( N \!-\! 1 \right) ] },
\end{align}
where
\begin{align}\label{44}
	\tilde{i},\tilde{j} = \arg\min\limits_{i,j} \left( \ell_j - \ell_i\right), \ell_i < \ell_j .
\end{align}

Specially, we assume that $\min(\ell_{{j}} - \ell_{{i}}) = 1$ for the scenarios with dense delays and ignore the term of $\alpha_{max}^2$, since the Doppler scale factor $\alpha_{max}$ is typically a small value in practice.\footref{n3} we can further simplify \eqref{43}  as
\begin{align}\label{45}
	c_1 \approx \frac{2 k_{{max}}  + 2 \alpha_{max} \left( N - 1 \right) + 2 N_v + 1 }{ 2N [1 - 4 \alpha_{max} \left( N - 1 \right)] }.
\end{align}

In addition, to ensure that $c_1 > 0$\footref{n2} always hold for \eqref{45}, the number of transmitted symbols $N$ should satisfy 
\begin{align}\label{46}
	N < \frac{1 }{ 4 \alpha_{max}} + 1.
\end{align}

On the other hand, under the constraint \eqref{41b}, we can substitute \eqref{32} into \eqref{41b}, and the AFDM chirp parameter $c_1$ should satisfy
\begin{align}\label{47}
	c_1 < \frac{ \left( 1 - \alpha_{max}^2 \right) (N - 2N_v) - 2 k_{{max}  }- 2\alpha_{max} \left( N - 1 \right) }{ 2N[\left( 1 -\alpha_{max}^2 \right) \ell_{{max}} + 2 \alpha_{max} \left( 2 - \alpha_{max}^2 \right)  \left( N - 1 \right)]}.
\end{align}

We again ignore the term $\alpha_{max}^2$ and further simplify \eqref{47} as
\begin{align}\label{48}
	c_1 < \frac{ N - 2 k_{{max}  }- 2\alpha_{max} \left( N - 1 \right) - 2 N_v}{2N [\ell_{{max}} + 4 \alpha_{max} \left( N - 1 \right)]}.
\end{align}

By substituting \eqref{45} into \eqref{48}, we can obtain the constraint relationship with the number of transmitted symbols $N$ as
\begin{align}\label{49}
	a_N N^2 + b_N N + c_N < 0,
\end{align}
where
\begin{subequations}\label{50}
	\begin{align}
		& a_N \!=\! 4 \alpha_{max}, \\ 
		& b_N \!=\! 2 \alpha_{max} \ell_{max} \!-\! 1,  \\ 
		& c_N \!=\! (2 k_{max} \!+\! 2 N_v) (\ell_{max} \!+\! 1) \!+\!  \ell_{max} \!-\! (2 \ell_{max} \!+\! 6) \alpha_{max}. 
	\end{align}
\end{subequations}

Note that \eqref{49} is a quadratic inequality about variable $N$. Then, the range of parameter $N$ with constraint \eqref{46} and \eqref{49} can be given by
\begin{align}\label{51}
	x_{L,N}  < N < \min \left( x_{H,N}, \frac{1}{4 \alpha_{max}} + 1\right), 
\end{align}
where
\begin{subequations}\label{52}
	\begin{align}
		x_{L,N} & = \frac{-b_N - \sqrt{b_N ^2 - 4 a_N c_N}}{2 a_N} , \\ 
		x_{H,N} & = \frac{-b_N + \sqrt{b_N ^2 - 4 a_N c_N}}{2 a_N} .
	\end{align}
\end{subequations}

The Doppler scale factor $\alpha_{max}$ is typically a small value in practice.\footref{n3} Consequently, the coefficients of the quadratic polynomial in \eqref{50} satisfy $a_N > 0, b_N < 0$ and $c_N > 0$. Therefore, $x_{L,N} > 0 $ always holds. Additionally, to ensure that \eqref{52} always has real solutions, we should satisfy the constraint
\begin{align}\label{53}
	b_N^2 - 4 a_N c_N > 0.
\end{align}

Note that \eqref{51} and \eqref{53} impose the constraints for the number of transmitted symbols $N$ and  channel spread characteristics, respectively. These are primarily due to the fact that the non-zero entries width $\mathcal{L}_i$ of the DAF domain equivalent channel in \eqref{34} is proportional to the number of transmitted symbols $N$ and Doppler scale factor $\alpha_{max}$, 
then it may fail to distinguish the channel paths 
for particularly large number of transmitted symbols  $N$ and large Doppler scale factor $\alpha_{max}$. 
Fortunately, the constraint \eqref{53} always holds in practice, and we can always determine a suitable number of  transmitted symbols $N$ for improving the AFDM system performance under time-scaled wideband doubly-dispersive channels. Without loss of generality, we take a typical time-scaled wideband underwater acoustic channel as an example, where the maximum Doppler factor $\alpha_{max} = 10^{-4}$ and maximum delay $\tau_{max} = 20$ms \cite{d39,d40,d41}. The carrier frequency is set as $f_c = 6$kHz with a transmission bandwidth $B = 4$kHz \cite{d41} and set $N_v = 2$. The constraint \eqref{53} can be calculated as $b_N ^2 - 4 a_N c_N \approx 0.17 > 0$. Therefore, the real solutions of $x_{L,N}$ and $x_{H,N}$ always exist in practice. Finally, to guarantee the underlying wideband channel diversity, we can set the AFDM chirp parameter $c_1$ as \eqref{45} and the number of transmitted symbols $N$ satisfies the constraint $\eqref{51}$.

\textbf{Remark 4:} \emph{In specific, if the AFDM system satisfies the narrowband approximation conditions mentioned in \textbf{Remark 1}, i.e.} $B \ll f_c $ \emph{and} $\alpha_i \ll  1/N$, \emph{the AFDM chirp parameter} $c_1$ \emph{in \eqref{45} can be simplified as}
\begin{align}\label{54}
	c_1 \approx \frac{2 k_{{max}} + 2 N_v + 1}{2N},
\end{align}
\emph{and the constraint \eqref{49} can be simplified as}
\begin{align}\label{55}
	\left(  2 k_{{max}} + 2 N_v \right)   \left( \ell_{{max}} + 1 \right)  + \ell_{{max}} < N,
\end{align}
\emph{which are consistent with the narrowband AFDM chirp parameter conditions} \emph{mentioned in \cite{d9}}.


\section{Performance Analysis}
Based on our optimized AFDM chirp parameter $c_1$ in \eqref{45} under time-scaled wideband doubly-dispersive channels, we analyze the correspondingly theoretical error performance based on PEP in this section. To facilitate the PEP analysis, \eqref{18} can be re-expressed as
\begin{align}\label{56}
	\mathbf{y} = \sum_{i=1}^{P} {h}_i \mathbf{H}_i \mathbf{x} + \boldsymbol{\omega} = \boldsymbol{\Phi} \left( \mathbf{x} \right) \mathbf{h} + \boldsymbol{\omega},
\end{align}
where 
\begin{subequations}\label{57}
	\begin{align}
		\mathbf{h} & = \left[ h_1, h_2, ..., h_P\right]^{\text{T}} \in \mathbb{C}^{P \times 1}, \\
		\boldsymbol{\Phi} \left( \mathbf{x} \right) & = \left[ \mathbf{H}_1 \mathbf{x}, \mathbf{H}_2 \mathbf{x}, ..., \mathbf{H}_P \mathbf{x}\right] \in \mathbb{C}^{N \times P}.
	\end{align}
\end{subequations}

The perfect channel state information (CSI) is assumed at the receiver. For a given time-scaled wideband doubly-dispersive channel, the conditional PEP of transmitted symbol $\mathbf{x}$ but erroneously decoded it as $\hat{\mathbf{x}}$ at receiver is given by
\begin{align}\label{58}
	P \left( \mathbf{x} \rightarrow \hat{\mathbf{x}} \left| \mathbf{h} \right.  \right) = Q \left( \sqrt{\frac{\left| \left[  \boldsymbol{\Phi} \left( \mathbf{x} \right) - \boldsymbol{\Phi} \left(  \hat{\mathbf{x}} \right) \right]   \mathbf{h} \right|^2  }{2 N_0}}\right), 
\end{align}
where $Q(x)$ represents the tail distribution function of a standard
Gaussian distribution. Here, we define $\boldsymbol{\Omega}_{ \mathbf{x}, \hat{\mathbf{x}}}  = \left[  \boldsymbol{\Phi} \left( \mathbf{x} \right) - \boldsymbol{\Phi} \left(  \hat{\mathbf{x}} \right) \right]^{\text{H}} \left[  \boldsymbol{\Phi} \left( \mathbf{x} \right) - \boldsymbol{\Phi} \left(  \hat{\mathbf{x}} \right) \right]  $, which is a Hermitian matrix and can be eigenvalue decomposed as $\boldsymbol{\Omega}_{ \mathbf{x}, \hat{\mathbf{x}}} = \mathbf{\tilde{U}}^{\text{H}} \boldsymbol{\tilde{\Lambda}} \mathbf{\tilde{U}} $, where $\mathbf{\tilde{U}} \in \mathbb{C}^{P \times P}$ is a unitary matrix and $\boldsymbol{\tilde{\Lambda}} = \text{diag} \left\lbrace \lambda_1, \lambda_2, ..., \lambda_P \right\rbrace $. 
The corresponding rank and the non-zero eigenvalues are defined as $R$ and $\lambda_i, i = 1, 2, ..., R$, respectively. We then have
\begin{align}\nonumber
	\left| \left[  \boldsymbol{\Phi} \left( \mathbf{x} \right) - \boldsymbol{\Phi} \left(  \hat{\mathbf{x}} \right) \right]   \mathbf{h} \right|^2  & = \mathbf{h}^{\text{H}} \boldsymbol{\Omega}_{ \mathbf{x}, \hat{\mathbf{x}}}  \mathbf{h} \\ \label{59}
	& =  \tilde{\mathbf{h}}^{\text{H}} \boldsymbol{\tilde{\Lambda}} \tilde{\mathbf{h}} = \sum_{i=1}^{R} \lambda_i \left| \tilde{h}_i \right|^2, 
\end{align}
where  $\tilde{\mathbf{h}} = \mathbf{\tilde{U}} \mathbf{h}$. According to $ Q \left( x \right) \leq \exp \left( 1/2 x^2 \right) , \forall x > 0 $, \eqref{58} can be further simplified as 
\begin{align}\label{60}
	P \left( \mathbf{x} \rightarrow \hat{\mathbf{x}} \left| \mathbf{h} \right.  \right) \leq \exp \left(- \frac{\sum_{i=1}^{R} \lambda_i \left| \tilde{h}_i \right|^2 }{4 N_0} \right). 
\end{align}

We assume that $h_i$ follows a Gaussian distribution with mean $0$ and variance $1/P$, i.e., $h_i \sim \mathcal{CN} \left( 0 , 1/P \right) $, such that $\tilde{h}_i$ also follows the distribution of $\mathcal{CN} \left( 0 , 1/P \right)$ since $\tilde{\mathbf{U}}$ is an unitary matrix. The final PEP can be calculated by averaging  channel statistics and given by
\begin{align}\label{61}
	P \left( \mathbf{x} \rightarrow \hat{\mathbf{x}}  \right) \leq \frac{1}{ \left(\frac{1}{4 N_0} \right)^R  \prod \limits_{i=1}^{R}  \frac{\lambda_i}{P}}.
\end{align}

From the above analysis, the average bit error rate (BER) can be upper bounded by
\begin{align}\label{62}
	P_e \leq \frac{1}{Q^{N} N \log_2Q} \sum_{\mathbf{x}}  \sum_{\mathbf{x} \neq \hat{\mathbf{x}}} P \left( \mathbf{x} \rightarrow \hat{\mathbf{x}}  \right) \mathbf{e} \left(\mathbf{x} , \hat{\mathbf{x}} \right), 
\end{align}
where $\mathbf{e} \left(\mathbf{x} , \hat{\mathbf{x}} \right)  $ represents the number of bits in difference for the corresponding pairwise error event. 

