Although the ML detector can achieve the optimal BER performance, it is impractical due to its exponentially growing complexity with the system dimensions. From \eqref{33}, we observe that the DAF domain equivalent channel exhibits a significant sparse structure, which facilitates the application of reduced complexity sparse detection algorithms. However, 
the sparse DAF domain channel will be very dense with increasing the number of transmission symbols $N$ and Doppler scale factor $\alpha$ according to \eqref{34}, leading to a high detection complexity even with sparse detection algorithms. To tackle this issue, we focus on the sparser time domain channel for reduced complexity receiver design. 
To intuitively illustrate the sparse characteristics of the time domain and DAF domain equivalent channel, we present the corresponding equivalent channel structure in Fig. \ref{fig_5}.
It is obvious that the time domain equivalent channel $\bar{\mathbf{H}}_{\text{T}}$ has a more sparser structure than DAF domain equivalent channel $\bar{\mathbf{H}}$ under time-scaled wideband doubly-dispersive channels. 
This observation motivates us to consider the more sparser time domain equivalent channel for reduced complexity detector design.

%In this section, we propose a CD-D-OAMP detector, which can effectively leverage the sparser time domain channel structure to reduce AFDM symbol detection complexity under wideband doubly-dispersive channels.

\subsection{Cross Domain Distributed OAMP detector}
According to \eqref{14} and \eqref{18}, we can decouple the problem of AFDM symbol detection into the following constraints, i.e.,
\begin{subequations}\label{63}
	\begin{align}
		\text{Linear constraint}  ~\{\boldsymbol{\Gamma}\} &: \mathbf{y}_{\text{T}} = \bar{\mathbf{H}}_{\text{T}} \mathbf{x}_{\text{T}} + \boldsymbol{\omega}_{\text{T}}, \label{63a} \\ 
		\text{Non-linear constraint} ~ \{\boldsymbol{\Phi}\} &:  \mathbf{x} \in \mathbb{A}^{N \times 1}. \label{63b}
	\end{align}
\end{subequations}

Then, we aim to find the MMSE estimation of $\mathbf{x}$. For this issue, we propose an efficient CD-D-OAMP detector, which is described in Fig. \ref{fig_6}. It iteratively optimize the linear module in time domain and the nonlinear module in DAF domain to converge towards overall MMSE estimation.
In addition, it can effectively leverage the sparse time domain channel structure for complexity reduction and achieve desired complexity and performance trade-off. The proposed CD-D-OAMP detection algorithm is summarized in \textbf{Algorithm 1} and the specific details are introduced as following.

\begin{figure*}[t!]
	\centering
	\includegraphics[scale=0.68]{D_CD.eps}
	\caption{Proposed cross domain distributed detection structure.}
	\label{fig_6}
\end{figure*} 

\textbf{$\left. \boldsymbol{1} \right) $ Linear constraint} $\{\boldsymbol{\Gamma}\}$ \textbf{in time domain with distributed LMMSE (D-LMMSE) estimation}: Under the linear constraint in \eqref{63a}, we propose the D-LMMSE time domain estimator to leverage the sparse time domain channel structure for complexity reduction.
Specifically, we divide the time domain received signal $\mathbf{y}_{\text{T}}$ into $C$ groups and the number of each group received signal is $N_c = N / C$. When $ C = 1$, the D-LMMSE estimator reduces to the original LMMSE estimator. Then, the time domain received signal $\mathbf{y}_{\text{T}}$, channel matrix $\bar{\mathbf{H}}_{\text{T}}$ and noise $\boldsymbol{\omega}_{\text{T}}$ can be partitioned as
\begin{subequations}\label{65}
\begin{align}
	\mathbf{y}_{\text{T}} & = [\mathbf{y}_{\text{T},1}^{\text{T}}, \mathbf{y}_{\text{T},2}^{\text{T}}, ..., \mathbf{y}_{\text{T},C}^{\text{T}}]^{\text{T}}, \\
	\bar{\mathbf{H}}_{\text{T}} & = [\bar{\mathbf{H}}_{\text{T},1}^{\text{T}}, \bar{\mathbf{H}}_{\text{T},2}^{\text{T}}, ..., \bar{\mathbf{H}}_{\text{T},C}^{\text{T}}]^{\text{T}}, \\
	\boldsymbol{\omega}_{\text{T}} & = [\boldsymbol{\omega}_{\text{T},1}^{\text{T}}, \boldsymbol{\omega}_{\text{T},2}^{\text{T}}, ..., \boldsymbol{\omega}_{\text{T},C}^{\text{T}}]^{\text{T}},
\end{align}
\end{subequations}
where $ \mathbf{y}_{\text{T},c} \in \mathbb{C}^{N_c \times 1}$, $ \bar{\mathbf{H}}_{\text{T},c} \in \mathbb{C}^{N_c \times N}$ and $ \boldsymbol{\omega}_{\text{T},c} \in \mathbb{C}^{N_c \times 1}$. The $c$-th group received signal $\mathbf{y}_{\text{T},c}$ can be given by
\begin{align}\label{66}
	\mathbf{y}_{\text{T},c} = \bar{\mathbf{H}}_{\text{T},c} \mathbf{x}_{\text{T}} + \boldsymbol{\omega}_{\text{T},c} , c = 1, 2, ..., C.
\end{align}

Due to the sparse structure of the time domain equivalent channel matrix, only a small subset $\mathbf{x}_{\text{T},c} = \mathbf{x}_{\text{T}} [\mathcal{D}_c] \in \mathbb{C}^{|\mathcal{D}_c| \times 1} $ is associated with $\mathbf{y}_{\text{T},c}$, where $\mathcal{D}_c$ is the index set of $\mathbf{x}_{\text{T}}$ correlated to $\mathbf{y}_{\text{T},c}$ and $|\mathcal{D}_c| $ is the size of $\mathcal{D}_c$. Therefore, we can only retain the column elements with indices $\mathcal{D}_c$ from $\bar{\mathbf{H}}_{\text{T},c}$ and form a  smaller-dimension channel matrix $\mathbf{\tilde{H}}_{\text{T},c} \in \mathbb{C}^{N_c \times |\mathcal{D}_c|}$, i.e.,  $\mathbf{\tilde{H}}_{\text{T},c} = \bar{\mathbf{H}}_{\text{T},c} [:, \mathcal{D}_c]$. Typically, $|\mathcal{D}_c|$ is much smaller than $N$ due to the sparse property of the time domain equivalent channel. Fig. \ref{fig_7} intuitively illustrates the distributed time domain input-output relationship with three groups as an example. We can further simplify \eqref{66} as 
\begin{align}\label{67}
	\mathbf{y}_{\text{T},c} = \mathbf{\tilde{H}}_{\text{T},c} \mathbf{x}_{\text{T},c} + \boldsymbol{\omega}_{\text{T},c}.
\end{align}


%Therefore, the posteriori distribution of time domain signal $\mathbf{x}_{\text{T}}$ can be approximated as
%\begin{align}\label{64}
%	P \left( \mathbf{x}_{\text{T}} \left| \mathbf{y}_{\text{T}}, \mathbf{H}_{\text{T}} \right. \right) & \approx \prod_{c=1}^{C} P \left( \mathbf{x}_{\text{T},c} \left| \mathbf{y}_{\text{T},c}, \mathbf{\tilde{H}}_{\text{T},c} \right. \right)  \\ \nonumber
%	& \sim \prod_{c=1}^{C} \mathcal{CN}  \left( \boldsymbol{\mu}_{\text{T},c}^{p,(t)} , \boldsymbol{\eta}_{\text{T},c}^{p,(t)} \right).
%\end{align}

According to LMMSE criterion, the posteriori mean $\boldsymbol{\mu}_{\text{T},c}^{p,(\iota)}$ and variance $\boldsymbol{\Sigma}_{\text{T},c}^{p,(\iota)}$ of $\mathbf{x}_{\text{T},c}$ in $(\iota)$-th iteration are given by
\begin{subequations}\label{68}
	\begin{align}
		\boldsymbol{\mu}_{\text{T},c}^{p,(\iota)} & = \boldsymbol{\mu}_{\text{T},c}^{a,(\iota)} + \mathbf{W}^{(\iota)}_{\text{T},c} \left( \mathbf{y}_{\text{T},c} - \mathbf{\tilde{H}}_{\text{T},c}  \boldsymbol{\mu}_{\text{T},c}^{a,(\iota)} \right), \label{68a} \\ 
		\boldsymbol{\eta}_{\text{T},c}^{p,(\iota)} & = \text{diag} \left\lbrace \boldsymbol{\Sigma}^{a,(\iota)}_{\text{T},c} - \mathbf{W}^{(\iota)}_{\text{T},c} \mathbf{\tilde{H}}_{\text{T},c} \boldsymbol{\Sigma}^{a,(\iota)}_{\text{T},c} \right\rbrace, \label{68b}
	\end{align}
\end{subequations}
where $\mathbf{W}^{(\iota)}_{\text{T},c} $ is the $c$-th group time domain LMMSE filter,
\begin{align}\label{69}
	\mathbf{W}^{(\iota)}_{\text{T},c} = \boldsymbol{\Sigma}^{a,(\iota)}_{\text{T},c} \mathbf{\tilde{H}}^{\text{H}}_{\text{T},c} \left( \mathbf{\tilde{H}}_{\text{T},c} \boldsymbol{\Sigma}^{a,(\iota)}_{\text{T},c} \mathbf{\tilde{H}}^{\text{H}}_{\text{T},c} + \mathbf{I}_{N_c} N_0 \right)^{-1},
\end{align}
and $ \boldsymbol{\Sigma}^{a,(\iota)}_{\text{T},c} = \text{diag} \left\lbrace \boldsymbol{\eta}^{a,(\iota)}_{\text{T},c} \right\rbrace $.
The $\boldsymbol{\mu}_{\text{T},c}^{a,(\iota)}$ and $\boldsymbol{\eta}_{\text{T},c}^{a,(\iota)}$ are the priori mean and variance in $(\iota)$-th iteration, which can be initialized as  $\boldsymbol{\mu}_{\text{T},c}^{a,(1)} = \boldsymbol{0}_{N_c} $ and $\boldsymbol{\eta}_{\text{T},c}^{a,(1)} = \boldsymbol{1}_{N_c} $ in the first iteration.


