	\centering
	\includegraphics[scale=0.4]{D_OAMP.eps}
	\caption{Distributed input-output relationship with three groups as an example.}
	\label{fig_7}
\end{figure} 
%\begin{subequations}\label{65}
%	\begin{align} 
%		\boldsymbol{\Sigma}_{\text{T},c}^{p,(\iota)} & = \left( \mathbf{\tilde{H}}^{\text{H}}_{\text{T},c}  \boldsymbol{\Sigma}_{\omega}^{-1} \mathbf{\tilde{H}}_{\text{T},c} + \text{diag} \left\lbrace \boldsymbol{\eta}^{a,(\iota)}_{\text{T},c} \right\rbrace^{-1}  \right)^{-1}  \label{65a} \\
%		\boldsymbol{\mu}_{\text{T},c}^{p,(\iota)} & = \boldsymbol{\Sigma}_{\text{T},c}^{p,(\iota)} \left( \mathbf{\tilde{H}}^{\text{H}}_{\text{T},c} \boldsymbol{\Sigma}_{\omega}^{-1}  \mathbf{y}_{\text{T},c} + \text{diag} \left\lbrace \boldsymbol{\eta}^{a,(\iota)}_{\text{T},c} \right\rbrace^{-1}  \boldsymbol{\mu}_{\text{T},c}^{a,(\iota)} \right)  , \label{65b} 
%	\end{align}
%\end{subequations}
%where $ \boldsymbol{\Sigma}_{\omega} = \mathbf{I}_{N_c} N_0 $. The $\boldsymbol{\mu}_{\text{T},c}^{a,(\iota)}$ and $\boldsymbol{\eta}_{\text{T},c}^{a,(\iota)}$ are the priori mean and variance in $(\iota)$-th iteration, which can be initialized as  $\boldsymbol{\mu}_{\text{T},c}^{a,(1)} = \boldsymbol{0}_{N_c} $ and $\boldsymbol{\eta}_{\text{T},c}^{a,(1)} = \boldsymbol{1}_{N_c} $ in the first iteration. We assume the DAF domain transmitted signal $\mathbf{x}$ is approximated as i.i.d Gaussian, then the time domain $\mathbf{x}_{\text{T}}$ is also i.i.d Gaussian, since the transform matrix $\mathbf{U}^{\text{H}}$ is unitary matrix. Therefore, we can discard the non-diagonal entries of $\boldsymbol{\Sigma}_{\text{T},c}^{p,(\iota)}$ and generate the posteriori variance $\boldsymbol{\eta}_{\text{T},c}^{p,(\iota)}  $ in $(\iota)$-th iteration as
%\begin{align}\label{66}
%	\boldsymbol{\eta}_{\text{T},c}^{p,(\iota)} = \text{diag} \left\lbrace \boldsymbol{\Sigma}_{\text{T},c}^{p,(\iota)} \right\rbrace. 
%\end{align}



Then, the extrinsic mean $\boldsymbol{\mu}_{\text{T},c}^{e,(\iota)}$ and variance $\boldsymbol{\eta}_{\text{T},c}^{e,(\iota)} $ can be obtained by
\begin{subequations}\label{70}
	\begin{align}
		{\eta}_{\text{T},c}^{e,(\iota)} [d]   & = \left( \frac{1}{{\eta}_{\text{T},c}^{p,(\iota)} [d]}  -  \frac{1}{{\eta}_{\text{T},c}^{a,(\iota)} [d]} \right)^{-1}  , \label{70a} \\
		{\mu}_{\text{T},c}^{e,(\iota)} [d] & = {\eta}_{\text{T},c}^{e,(\iota)} [d]  \left( \frac{{\mu}_{\text{T},c}^{p,(\iota)} [d]}{{\eta}_{\text{T},c}^{p,(\iota)} [d]}  -  \frac{{\mu}_{\text{T},c}^{a,(\iota)} [d]}{{\eta}_{\text{T},c}^{a,(\iota)} [d]} \right), \label{70b}
	\end{align}
\end{subequations}
where $d = 1, 2, ..., |\mathcal{D}_c|$.
Following the Gaussian message combining rule, we can update the extrinsic marginal distribution $P_{E}^{(\iota)} \left( \mathbf{x}_{\text{T}} \right)  \sim \mathcal{CN} \left( \boldsymbol{\mu}_{\text{T}}^{e,(\iota)} , \boldsymbol{\eta}_{\text{T}}^{e,(\iota)} \right) $ with
\begin{subequations}\label{71}
	\begin{align}
		{\eta}_{\text{T}}^{e,(\iota)} [j]  & = \left( \sum_{\bar{c}_j \in \bar{C}_j}  \frac{1}{{\eta}_{\text{T},\bar{c}_j}^{e,(\iota)} [\mathcal{I}_{j}]}   \right)^{-1}, \label{71a} \\
		{\mu}_{\text{T}}^{e,(\iota)} [j]  & = {\eta}_{\text{T}}^{e,(\iota)} [j] \left( \sum_{\bar{c}_j \in \bar{C}_j} \frac{{\mu}_{\text{T},\bar{c}_j}^{e,(\iota)} [\mathcal{I}_{j}]}{{\eta}_{\text{T},\bar{c}_j}^{e,(\iota)} [\mathcal{I}_{j}]} \right), \label{71b}
	\end{align}
\end{subequations}
where $j = 1, 2, ..., N$, $\bar{c}_j \in \bar{C}_j$ is the index of $j$-th detection symbol associated with $\mathbf{x}_{\text{T},\bar{c}_j}$ and $\mathcal{I}_{j}$ is the corresponding position in $\bar{c}_j$-th group, $\bar{C}_j$ is the index set of $\bar{c}_j$.



%$\bar{c}_j \in \bar{C}_j$ is the index of group $c$ satisfying $j \cap \mathcal{D}_c \neq \emptyset, c = 1, 2, ..., C $ and $\bar{C}_j$ is the set of $\bar{c}_j$. $\mathcal{I}_{j}$ is the corresponding position satisfying $\mathcal{D}_{\bar{c}_j} [\mathcal{I}_{j}] = j$. 

Then, we can transform the time domain extrinsic mean $\boldsymbol{\mu}_{\text{T}}^{e,(\iota)} $ and variance $\boldsymbol{\eta}_{\text{T}}^{e,(\iota)} $ into DAF domain as the \emph{a priori}  mean $\boldsymbol{\mu}_{D}^{a,(\iota)}$ and variance $\boldsymbol{\eta}_{D}^{a,(\iota)}$ by DAF transform $\mathbf{U}$, i.e.,
\begin{align}\label{72}
	\boldsymbol{\mu}_{D}^{a,(\iota)} = \mathbf{U} \boldsymbol{\mu}_{\text{T}}^{e,(\iota)},  
	\boldsymbol{\eta}_{D}^{a,(\iota)} = \boldsymbol{\eta}_{T}^{e,(\iota)}.
\end{align}

Furthermore, we do the sample average of variance $\boldsymbol{\eta}_{D}^{a,(\iota)}$ as
\begin{align}\label{73}
	\bar{\eta}_{D}^{a,(\iota)}  = \frac{1}{N} \sum_{j=1}^{N} {\eta}_{\text{D}}^{a,(\iota)} [j]. 
\end{align}

Next, the priori mean $\boldsymbol{\mu}_{D}^{a,(\iota)}$ and average variance $\bar{\eta}_{D}^{a,(\iota)}$ are passed to the non-linear detection module.

\textbf{$\left. \boldsymbol{2} \right) $ Non-linear constraint $\{\boldsymbol{\Phi}\}$ in DAF domain with symbol-by-symbol detection}: The posteriori distribution of $j$-th DAF domain symbol can be given by
\begin{align}\label{74}
	\bar{P}^{(\iota)} \left( x_j = \chi \right) \propto P_D \left( x_j = \chi \right) \exp \left(- \frac{\left| \chi - {\mu}_{D}^{a,(\iota) } [j] \right|^2 }{\bar{\eta}_{D}^{a,(\iota)}}  \right),
\end{align}
where $\chi \in \mathbb{A}$. $ P_D \left( x_j = \chi \right)$ denotes the \emph{a priori} probability and is also assumed to be equiprobable symbols if no priori information observed. Then, we can project the $j$-th symbol posteriori probability $\bar{P}^{(\iota)} (x_j) $ into a Gaussian distribution $\mathcal{CN} \left( {\mu}_{D}^{p,(\iota) } [j], {\eta}_{D}^{p,(\iota) } [j] \right) $ with
\begin{subequations}\label{75}
	\begin{align}
		{\mu}_{D}^{p,(\iota) } [j] & = \sum_{\chi \in \mathbb{A}} \chi \bar{P}^{(\iota)} \left( x_j = \chi \right), \\
		{\eta}_{D}^{p,(\iota) } [j] & = \sum_{\chi \in \mathbb{A}} \bar{P}^{(\iota)} \left( x_j = \chi \right) \left| \chi - {\mu}_{D}^{p,(\iota) } [j] \right|^2. 
	\end{align}
\end{subequations}

Similarly, we further do the sample average of the variance $\boldsymbol{\eta}_{D}^{p,(\iota) }$, i.e., 
\begin{align}\label{76}
	\bar{\eta}_{D}^{p,(\iota) }  = \frac{1}{N}\sum_{{j}=1}^{N} {\eta}_{D}^{p,(\iota) } [{j}].
\end{align}

%\textbf{$\left. \boldsymbol{4} \right) $ Cross domain message passing: from DAFT domain to time domain based on unitary transform $\{\mathbf{U}^{\text{H}}\}$}: under the constraint (57d), 

The DAF domain posteriori mean $\boldsymbol{\mu}_{\text{D}}^{p,(\iota)} $ and average variance $\bar{\eta}_{\text{D}}^{p,(\iota)} $ can be transformed into time domain by IDAF transform $\mathbf{U}^{\text{H}}$, i.e.,
\begin{align}\label{77}
	\boldsymbol{\mu}_{\text{T}}^{p,(\iota)} = \mathbf{U}^{\text{H}} \boldsymbol{\mu}_{\text{D}}^{p,(\iota)}, 
	\bar{\eta}_{\text{T}}^{p,(\iota)} = \bar{\eta}_{\text{D}}^{p,(\iota)}.
\end{align}

The priori mean $\boldsymbol{\mu}_{\text{T},c}^{a,(\iota+1)}$ and variance $\boldsymbol{\eta}_{\text{T},c}^{a,(\iota+1)}$ in $c$-th group at $(\iota+1)$-th iteration can be obtained by
\begin{subequations}\label{78}
	\begin{align}
		{\eta}_{\text{T},c}^{a,(\iota+1)} [d] & = \left( \frac{1}{\bar{\eta}_{\text{T}}^{p,(\iota)}   }  - \frac{1}{\eta_{\text{T},c}^{e,(\iota)}[d] }  \right)^{-1}, \label{78a} \\
		{\mu}_{\text{T},c}^{a,(\iota+1)} [d] & \!=\! {\eta}_{\text{T},c}^{a,(\iota+1)} [d]  \left(  \frac{{\mu}_{\text{T}}^{p,(\iota)} [\mathcal{D}_c (d)] }{\bar{\eta}_{\text{T}}^{p,(\iota)}} \!-\!  \frac{{\mu}_{\text{T},c}^{e,(\iota)} [d] }{\eta_{\text{T},c}^{e,(\iota)} [d]} \right). \label{78b}
	\end{align}
\end{subequations}

Finally, we can pass the priori mean $\boldsymbol{\mu}_{\text{T},c}^{a,(\iota+1)}$ and variance $\boldsymbol{\eta}_{\text{T},c}^{a,(\iota+1)}$ of $c$-th group to the  linear module and form the iterative loop.

\textbf{$\left. \boldsymbol{5} \right) $ Convergence indicator}: When all DAF domain symbols are updated, we can compute the convergence indicator $\theta^{\left( \iota \right) } $ by
\begin{equation}\label{79}
	\theta^{\left(\iota \right) } = \frac{1}{N} \sum_{j = 1}^{N} \mathbb{I} \left(  \mathop{\max}\limits_{\chi \in \mathbb{A}} {\bar{P}^{\left( \iota \right) } \left( x_j = \chi \right)} \geq 1 - \varrho \right)
\end{equation}
with a small $\varrho > 0$ and $\mathbb{I} \left( \cdot \right) $ is the indicator function.

\textbf{$\left. \boldsymbol{6} \right) $ Update criterion}: If $\theta^{\left( \iota \right)} \geq \theta^{\left( \iota-1 \right) }$, we can update
\begin{equation}\label{80}
	{{P}} \left( x_j \right)  = \bar{{P}}^{\left( \iota \right) } \left( x_j \right), j = 1, 2, ..., N.
\end{equation}

\textbf{$\left. \boldsymbol{7} \right) $ Stopping criterion:} The CD-D-OAMP detector terminates when either $\theta^{\left( \iota \right) } = 1$ or the maximum iteration number $n_{t}$ is reached. Then, we can make the final decisions as
\begin{equation}\label{81}
	\hat{x}_j = \mathop{\arg \max}\limits_{\chi \in \mathbb{A}} {P} \left( x_j = \chi \right), j = 1, 2, ..., N.
\end{equation}


\textbf{Remark 5}: \emph{Note that both the D-LMMSE estimation in time domain and the symbol-by-symbol detection in DAF domain can support parallel computing processes, which can significantly reduce the computational latency. When C=1, our proposed CD-D-OAMP detector can be reduced to cross domain OAMP (CD-OAMP) detector for AFDM system. In addition, our proposed CD-D-OAMP detector can also be simplified as the distributed OAMP (D-OAMP) detector by directly performing D-LMMSE estimation and symbol-by-symbol detection in DAF domain. Furthermore, the D-OAMP detector is reduced to the OAMP detector when $C=1$ \cite{d31}.}


%Then we also demonstrate our proposed CD-DOAMP detector has the better detection performance and lower complexity compare to the non-cross domain DOAMP detector based simulation analysis in Fig. 9, since the time domain channel matrix has the sparser channel structure, which corresponds to lower interference for the symbols estimation of each group.

\begin{algorithm}[t!]
	\caption{CD-D-OAMP Iterative Detector }\label{alg1}
	Input: $\mathbf{y}_{\text{T}}$, $\bar{\mathbf{H}}_{\text{T}}$,  $n_{t}$, $ {P}_{D} \left( \mathbf{x} \right) $\\
	Initialize: $\boldsymbol{\mu}_{\text{T},c}^{a,(1)} = \boldsymbol{0}_{N_c} $, $\boldsymbol{\eta}_{\text{T},c}^{a,(1)} = \boldsymbol{1}_{N_c} $ and $\iota = 1$, $c = 1, 2, ..., C$ \\
	\textbf{Repeat}
	\begin{algorithmic}[1]
		\STATE Perform the D-LMMSE estimation and generate the time domain posteriori mean $\boldsymbol{\mu}_{\text{T},c}^{p,(\iota)}$ and variance $\boldsymbol{\eta}_{\text{T},c}^{p,(\iota)}$ by \eqref{68}, $c = 1, 2, ..., C$;
		\STATE Generate the time domain extrinsic mean $\boldsymbol{\mu}_{\text{T}}^{e,(\iota)}$ and variance $\boldsymbol{\eta}_{\text{T}}^{e,(\iota)}$ by \eqref{71};
		\STATE Transform the time domain extrinsic mean and variance into DAF domain as priori mean $\boldsymbol{\mu}_{D}^{a,(\iota)}$ and variance $\bar{\eta}_{D}^{a,(\iota)}$ by \eqref{72} and \eqref{73};
		\STATE Perform the symbol-by-symbol detection in DAF domain and generate posteriori mean $\boldsymbol{\mu}_{D}^{p,(\iota)}$ and variance $\bar{\eta}_{D}^{p,(\iota)}$ by \eqref{75} and \eqref{76};
		\STATE Transform the DAF domain posteriori mean and variance into the time domain mean $\boldsymbol{\mu}_{\text{T}}^{p,(\iota)}$ and variance $\bar{\eta}_{\text{T}}^{p,(\iota)}$ in \eqref{77};
		\STATE Generate the $c$-th group time domain priori mean $\boldsymbol{\mu}_{\text{T},c}^{a,(\iota+1)}$ and variance $\boldsymbol{\eta}_{\text{T},c}^{a,(\iota+1)}$  by \eqref{78}, $c = 1, 2, ..., C$;
		\STATE Compute the convergence indicator in \eqref{79};
		\STATE Update $P (\mathbf{x}) = \bar{P}^{(\iota)} (\mathbf{x})$ in \eqref{80};
		\STATE  $ \iota = \iota + 1 $;
	\end{algorithmic}
	\textbf{Until} : $\theta^{\left( \iota \right) } = 1$ or $\iota = n_{t}$; \\
	\textbf{Output}  : The decisions of the transmitted symbols in \eqref{81}.
	\label{alg1}
\end{algorithm} 

\subsection{MSE Performance Analysis via State Evolution}
In this sub-section, we investigate the average MSE performance of the proposed CD-D-OAMP detector based on state evolution. Since the time domain D-LMMSE estimator involves multi-group symbols estimation and combination, we track the time domain output variance of each group to better characterize the state evolution process. The finally state evolution can be characterized by
\begin{subequations}\label{82}
	\begin{align}
		&\!\bar{\eta}_{\text{D}}^{p,(\iota)}  \!=\! f_{\text{D}} \!\left(\! f_{\text{C}} \!\left(\! \left[\!  \text{diag} \!\left\lbrace\! f_{\text{T}} \!\left(\! \boldsymbol{\eta}_{\text{T},c}^{a,(\iota)} \!\right) \! \right\rbrace^{\!-1} \!-\! \text{diag} \!\left\lbrace \! \boldsymbol{\eta}_{\text{T},c}^{a,(\iota)} \! \right\rbrace^{\!-1} \! \right]^{\!-1} \!\right) \!\right)\!,\!   \\
		&\boldsymbol{\eta}_{\text{T},c}^{a,(\iota+1)}  \!=\! \left(\!  \frac{\boldsymbol{1}_{N_c}}{\bar{\eta}_{\text{D}}^{p,(\iota)}} \!-\! \left[ \! \text{diag} \! \left\lbrace \! f_{\text{T}} \! \left( \! \boldsymbol{\eta}_{\text{T},c}^{a,(\iota)} \! \right) \! \right\rbrace^{\!-\!1}  \!-\! \text{diag} \! \left\lbrace \! \boldsymbol{\eta}_{\text{T},c}^{a,(\iota)} \! \right\rbrace^{\!-\!1} \!\right]  \!\right)^{\!-\!1}
	\end{align}
\end{subequations}
with initialization $\boldsymbol{\eta}_{\text{T},c}^{a,(1)} = \boldsymbol{1}_{N_c} $, where $c = 1, 2, ..., C$. $f_{\text{C}} \left( \cdot \right) $ denotes the combination operation of D-LMMSE detection and is associated with trimmed channel matrix $\mathbf{\tilde{H}}_{\text{T},c}$, which can be given by \eqref{71a} and average by \eqref{73}. 
$f_{\text{T}} \left( \cdot \right) $ denotes the posteriori variance of time domain LMMSE estimator given the corresponding priori information, which can be obtained by \eqref{68b}. $f_{\text{D}} \left( \cdot \right) $ denotes the posteriori variance of symbol-by-symbol detection in DAF domain given the corresponding priori information, it can be regarded as the AWGN observation with corresponding priori variance. For example, for a given AWGN observation $\hat{x}$ with average noise variance $\bar{\eta}_{\text{D}}^{a,(\iota)} $, i.e.,
\begin{align}\label{83}
	\hat{x} = x + \sqrt{\bar{\eta}_{\text{D}}^{a,(\iota)}} z,
\end{align}
where $z$ is a Gaussian variable with distribution $\mathcal{CN} \left(0, 1\right) $. The posteriori variance $f_{\text{D}} \left( \bar{\eta}_{\text{D}}^{a,(\iota)} \right) $ of $x$ given $\hat{x}$ can be given by
\begin{align}\label{84}
	f_{\text{D}} \left( \bar{\eta}_{\text{D}}^{a,(\iota)} \right) = \mathbb{E} \left\lbrace \left| x - \mathbb{E} \left[ x | \hat{x}\right] \right|^2  \right\rbrace.
\end{align}

Note that \eqref{84} is  a nonlinear function with respect to the specific constellation shape $\mathbb{A}$ and it is challenge to obtain a theoretical expression. Thus, we consider using a Monte Carlo approach to approximate the average posteriori variance and verify the convergence of the proposed algorithm \cite{d38}. 


