\title{Pseudo-Equilibria, or: How to Stop Worrying About Crypto and Just Analyze the Game}

\author{}
\date{}
\author{Alexandros Psomas\thanks{Purdue University. Email: apsomas@purdue.edu} \and Athina Terzoglou\thanks{Purdue University. Email: aterzogl@purdue.edu} \and Yu Wei\thanks{Georgia Tech. Email: ywei368@gatech.edu} \and Vassilis Zikas\thanks{Georgia Tech. Email: vzikas@gatech.edu}}



