\section{Introduction}
The two-sample testing problem for large covariance matrices has attracted considerable attention in recent years, particularly in modern multivariate analysis, random matrix theory, and their applications \citep{ding2024two, zhang2022asymptotic, lichen2012, chenzhangzhong2010, jiang_yang_2013}. Given two independent samples of possibly different sizes with $p$-dimensional covariance matrices $\bfSigma_{n,1}$ and $\bfSigma_{n,2}$, respectively, the testing problem is formulated as
\begin{align} \label{eq_hypothesis}
    &\mathsf{H}_{0,n} : \bfSigma_{n,1} = \bfSigma_{n,2}
    \quad  \textnormal{vs.}  \quad 
    \mathsf{H}_{1,n} : \bfSigma_{n,1} \neq \bfSigma_{n,2} .
\end{align}

\noindent\textbf{Two influential models for high-dimensional data.}
Besides the challenges of high dimensionality, the data analyst rarely has certainty about the underlying data-generating model. 
Modern statistical methodology is therefore often accompanied by theoretical guarantees under general data-generating models that go well beyond the classical normal distribution. 
Among the most prominent classes of data-generating models are elliptical distributions and independent component models. To be precise, we say that a random vector $\bfx$ in $\R^p$ with mean vector $\boldsymbol{\mu}\in \R^p$ and covariance matrix $\bfSigma\in \R^{p\times p}$ follows an \textit{elliptical model (EM)} if it admits a representation of the form 
\begin{align} \label{eq_em}
    \bfx = \xi \bfSigma^{1/2} \bfu + \boldsymbol{\mu}, \tag{EM}
\end{align}
where $\bfu$ is uniformly distributed on the $p$-dimensional unit sphere and $\xi$ is a non-negative scalar random variable independent of $\bfu$ satisfying $\E [ \xi^p]=p.$ In a different modeling approach, $\bfx$
  follows an \textit{independent component model (ICM)}, where $\bfx$ is given by 
  \begin{align} \label{eq_icm}
      \bfx = \bfSigma^{1/2} \bfy + \boldsymbol{\mu} \tag{ICM}
  \end{align}
  for some random vector $\bfy$ in $\R^p$ with independent entries. 
Despite superficial similarities between EMs and ICMs, they different fundamentally in their modeling capacities with important consequences for application areas \citep{wang2023bootstrap}.
Most notably, elliptical models induce dependence across coordinates of the random vector $\xi \bfu$ via the common scaling factor $\xi$, whereas ICMs assume componentwise independence for $\bfy$. More information on advantages and applications of EMs can be found in \cite{gupta2013elliptically, mcneil2015quantitative, elkaroui2009, owen1983elliptical, kariya2014robustness}.

In applications, the data analyst can typically not be sure about the data-generating model. Recent work has begun to address this issue by proposing goodness-of-fit tests for high-dimensional normal data \citep{chen2023normality} and elliptical distributions \citep{wang2024testing}. However, applying such tests prior to the main data analysis raises the classical challenge of pretesting \citep{bancroft1944biases}. Standard remedies like sample splitting are particularly problematic in high-dimensional settings, as they further diminish the effective sample size relative to the dimension.
It is therefore desirable to avoid pretesting altogether and instead turn to procedures that remain valid and powerful across a broad range of data-generating mechanisms.

\noindent \textbf{Our contributions.} 
Our contributions to tackling the aforementioned challenges are threefold: 
\begin{enumerate}[label=(\roman*)]
    \item We revisit the influential test by \cite{lichen2012}, originally developed for ICMs, and establish asymptotic level control and power consistency under EMs. To the best of our knowledge, the proposed test is the first one for the two-sample problem \eqref{eq_hypothesis} in the model \eqref{eq_em} with theoretical guarantees. Moreover, together with the results of \cite{lichen2012}, this test is thus valid for both ICMs and EMs.
    \item The statistical methodology builds on our key theoretical contribution: a central limit theorem for U-statistics estimating the squared Frobenius norm of $\bfSigma_{n,1}-\bfSigma_{n,2}$ under EMs. Notably, the limiting variance generally differs from that in the ICM case (see Figure \ref{fig:histograms}), reflecting the typical challenges of extending results from independent component models to elliptical models.
    \item We conduct a comprehensive numerical study demonstrating that our method is consistently valid and powerful across a wide range of scenarios. In contrast, competing methods developed for ICMs show erratic performance under EMs, being reliable only in some cases but not others. Additionally, we analyze S\&P 500 stock return data, where our method is the only one to detect a difference.
\end{enumerate}


\noindent\textbf{Related work.}
Two-sample testing for high-dimensional covariance matrices has been extensively studied under the assumption that the data follows an ICM. For instance, \cite{zou2021, zheng2012central, zheng_et_al_2015} developed tests based on the eigenvalues of $F$-matrices which requires $p<n_1$ or $p<n_2.$ In this setting, likelihood-based approaches, such as the corrected likelihood ratio tests in \cite{baietal2009, jiang_yang_2013, jiang2015, dettedoernemann2020} for high-dimensional normal distributions have also been proposed, where the distributional assumption was weakened to ICMs in \cite{dornemann2023likelihood}.
The test proposed by \cite{zhang2022asymptotic} combines leading eigenvalues above the phase-transition threshold with linear spectral statistics, and requires equal sample sizes as well as an asymptotically proportional relationship between dimension and sample size for its theoretical guarantees.
The tests developed by \cite{srivastava2010testing} for normally distributed data, \cite{lichen2012} based on U-statistics estimating the squared Frobenius norm of $\bfSigma_{n,1} - \bfSigma_{n,2}$, \cite{cai2013two} for sparse settings
work under more flexible asymptotic regimes. 
\cite{yu2024fisher} Fisher-combined the tests by \cite{lichen2012} and \cite{cai2013two} to enhance power in both sparse and dense settings. 
 \cite{ding2024two} developed a test for the ultra-high dimensional regime where the dimension is much larger than both samples sizes.
In summary, all of these works provide theoretical guarantees under ICM-type models or even the normal distribution, see also Table \ref{table_method}. 
A recent contribution by \cite{li2025tests} considers shape matrices under both EM and ICM and again requires the dimension not to exceed at least one sample size. Note that shape matrices, unlike covariance matrices, are scale-invariant and encode only directional structure.

In recent years, several researchers have begun addressing the challenge of extending results from ICMs to EMs, making it an increasingly active area of research.
A few general references contribute to the understanding of high-dimensional covariance matrices generated by elliptical data. 
For instance, the fluctuations of linear spectral statistics were studied in \cite{hu_et_al_2019,yang_et_al_2021, zhang2022clt}, with a parametric bootstrap procedure provided by \cite{wang2023bootstrap}. Leading eigenvalues under EMs were considered in \cite{jun2022tracy, ding2023extreme}. 
 For most of these results, moving beyond the ICM setting, has historically required considerable time, highlighting the technical challenges involved. 
These challenges are also reflected in the fact that, compared to inference under ICMs, hypothesis testing in EMs remains much less touched.
 Initial progress has primarily focused on one-sample problems in EMs, including sphericity tests \citep{xu2024adjusted} and tests based on linear spectral statistics \citep{hu_et_al_2019, yang_et_al_2021}.
To the best of our knowledge, however, no two-sample test for \eqref{eq_hypothesis} with theoretical guarantees for EMs exists. This work aims to close this gap.

 \noindent\textbf{Overview.} The remainder of this paper is organized as follows. Section \ref{sec_method} introduces the statistical test. Section \ref{sec_theory} presents the model, assumptions, and theoretical guarantees under the null and alternative hypotheses. Section \ref{sec_numerics} investigates finite-sample performance using synthetic data and an application to S\&P 500 stock returns. The proofs of the main theoretical results are gathered in Appendix \ref{sec_proofs}, while additional technical lemmas are placed in Appendix \ref{sec_appendix_b}.


\section{A two-sample test for large-dimensional covariance matrices}


\subsection{Methodology} \label{sec_method}
We consider two independent samples $\bfx_1^{(i)}, \ldots, \bfx_{n_i}^{(i)}$, $i\in \{1,2\},$ with covariance matrices $\bfSigma_{n,1}$ and $\bfSigma_{n,2}$, respectively, and wish to test \eqref{eq_hypothesis}. 

\noindent\emph{Estimating the squared Frobenius norm.}
The proposed test is based on the squared Frobenius norm
\begin{align} \label{eq_decomp}
\| \bfSigma_{n,1} - \bfSigma_{n,2}\|_F^2 := 
    \tr \lb \bfSigma_{n,1} - \bfSigma_{n,2} \rb ^2
    = \tr \lb \bfSigma_{n,1}^2 \rb  + \tr \lb \bfSigma_{n,2}^2 \rb 
    - 2 \tr \lb \bfSigma_{n,1} \bfSigma_{n,2} \rb.
\end{align}
For this purpose, we estimate each term on the right hand side of \eqref{eq_decomp} individually. Define 
\begin{align} 
     U_{n,i} & = \frac{1}{ (n_i)_2}\sum_{1 \leq j , k \leq n_i}^\star \lb \bfx_j^{(i)^\top} \bfx_k^{(i)} \rb^2 
      -\frac{2}{(n_i)_3}\sum_{1 \leq j,k,l \leq n_i  }^{\star} \bfx_j^{(i)^\top}\bfx_k^{(i)}\bfx_k^{(i)^\top}\bfx_{l}^{(i)} \nonumber \\ & \quad 
       +\frac{1}{(n_i)_4}\sum_{1 \leq j, k , l, m \leq n_i }^{\star} \bfx_j^{(i)^\top}\bfx_k^{(i)}\bfx_{l}^{(i)^\top}\bfx_m^{(i)}
     , ~ \quad i \in \{1,2\}, 
     \label{eq_def_U}
\end{align}
 where $\sum^\star$ stands for the summation over pairwise distinct indices and $(n_i)_m:= n_i(n_i-1) \cdot \ldots \cdot (n-m+1)$ for $1 \leq m \leq n_i. $
Then, $U_{n,i}$ is an unbiased estimator for the second spectral moment $\tr \bfSigma_{n,i}^2$ of $\bfSigma_{n,i}$. As an unbiased estimator for $\tr \lb \bfSigma_{n,1} \bfSigma_{n,2} \rb$, we use $V_n,$ where
\begin{align}
    V_n & = \frac{1}{ n_1 n_2} \sum_{j=1}^{ n_1 } \sum_{k=1}^{n_2 } \lb \bfx_i^{(1)^\top} \bfx_j^{(2)} \rb^2
    - \frac{1}{n_1 n_2 (n_1 -1)} \sum_{1 \leq k,l \leq n_1}^\star \sum_{j=1}^{n_2} \bfx_l^{(1)^\top} \bfx_j^{(2)} \bfx_j^{(2)^\top} \bfx_k^{(1)} \nonumber \\
    & \quad  -   \frac{1}{n_2 n_1 (n_2 -1)} \sum_{1 \leq k,l \leq n_2}^\star \sum_{j=1}^{n_1} \bfx_l^{(2)^\top} \bfx_j^{(1)} \bfx_j^{(1)^\top} \bfx_k^{(2)} \nonumber \\ & \quad 
    + \frac{1}{(n_1)_2 (n_2)_2} \sum_{1 \leq i,k \leq n_1}^\star \sum_{1 \leq j,l \leq n_2}^\star 
    \bfx_i^{(1)^\top} \bfx_j^{(2)} \bfx_k^{(1)^\top} \bfx_l^{(2)^\top} 
    .
     \label{eq_def_V}
\end{align}
Then, we propose $T_n$ as an estimator of $\| \bfSigma_{n,1} - \bfSigma_{n,2} \|_F^2,$ where
\begin{align*}
    T_n : =  U_{n,1 } + U_{n,2 } - 2 V_n.
\end{align*}

\noindent\emph{Estimating the variance of $T_n$.}
We will show in Theorem \ref{thm_conv_non_feasible} that the leading order term in the variance of $T_n$ under EMs equals
  \begin{align} 
        \sigma_n^2 & := \sum_{i=1,2} \Bigg\{ 
        \frac{4}{ n_i^2} \tr^2 \bfSigma_{n,i}^2 
         + \frac{8}{n_i} \tr  \left\{ \bfSigma_{n,i} \lb \bfSigma_{n,1} - \bfSigma_{n,2} \rb   \right\} ^2 
         \nonumber \\ & \quad ~ \quad ~ \quad  
        + \frac{4 (\tau_i - 2) }{p n_i}  \tr^2 \lb \bfSigma_{n,i} \lb \bfSigma_{n,1} - \bfSigma_{n,2} \rb \rb 
         \Bigg\} 
        + \frac{8}{n_1 n_2} \tr^2 \lb \bfSigma_{n,1} \bfSigma_{n,2}\rb.  \label{eq_def_sigma_n}
    \end{align}
   Here, $\tau_i$ is a constant independent of $n$ and is related to the variance of the scalar variable in \eqref{eq_em}. 
   It will be formally introduced in \eqref{eq_ass_xi}. 
    Under $\mathsf{H}_{0,n},$ we denote $\bfSigma_{n,0} = \bfSigma_{n,1} = \bfSigma_{n,2}$ and the expression for $\sigma_n^2$ simplifies to 
    \begin{align}
        \sigma_{n,0}^2 & = 4 \lb \frac{1}{n_1} + \frac{1}{n_2} \rb^2 \tr^2 \lb \bfSigma_{n,0}^2 \rb .
    \end{align}
Then, the proposed estimator for $\sigma_{n,0}$ is given by 
\begin{align*}
    \hat\sigma_{n,0} = \frac{2}{n_1} U_{n,1} + \frac{2}{n_2} U_{n,2} .
\end{align*}

\noindent\emph{Test decision.}
For the testing problem \eqref{eq_hypothesis}, we propose to reject $\mathsf{H}_{0,n}$ in favor of $\mathsf{H}_{1,n}$ at a prescribed level $\alpha \in (0,1)$, whenever
\begin{align} \label{eq_test_decision}
    \hat{\mathcal{T}}_{n} := \frac{1}{\hat\sigma_{n,0}}  T_n > z_{1-\alpha} ,
\end{align}
where $z_{1-\alpha}$ denotes the $(1-\alpha)$-quantile of a standard normal distribution. 

\subsection{Theoretical results} \label{sec_theory}



\begin{assumption} 
\noindent

\begin{enumerate}[label=(A\arabic*)] 
\item \label{ass_model}
    The samples $\bfx_1^{(1)}, \ldots, \bfx_{n_1}^{(1)}$ and $\bfx_2^{(2)}, \ldots, \bfx_{n_2}^{(2)}$ are independent. 
    For $i=1,2$, the observations $\bfx_1^{(i)}, \ldots, \bfx_{n_i}^{(i)}$ follow a generalized elliptical distribution with mean vector $\boldsymbol{\mu}_{n,i}\in\R^p$ and covariance matrix $\bfSigma_{n,i}\in \R^{p\times p}$, that is,
    \begin{align*}
    \bfx_j^{(i)} = \xi_{i,j} \bfSigma_{n,i}^{1/2} \bfu_{i,j} + \boldsymbol{\mu}_{n,i}, \quad 1 \leq j \leq n_i.
\end{align*}
    Here, $(\bfu_{i,1}, \xi_{i,1}), \ldots, (\bfu_{i,n_i}, \xi_{i,n_i})$ are i.i.d. random vectors in $\R^p \times [0,\infty)$ such that
    $\bfu_{i,1}$ is uniformly distributed on the $p$-dimensional unit sphere, $\xi_{i,1}$ is independent of $\bfu_{i,1}$. Moreover, $\xi_{i,1}$ satisfies the following moment assumptions
    \begin{align}
       \E [ \xi_{i,1}^2]  = p, \quad  
       \Var \lb \frac{\xi_{i,1}^2}{\sqrt{p}} \rb  =  \tau_i + o(1), \quad 
       \E \left| \frac{\xi_{i,1}^2 - p}{\sqrt{p}} \right|^{8} = o(p^2),
       \label{eq_ass_xi}
    \end{align}
    for some fixed $\tau_i>0$ independent of $n$. 
    \item The parameters $p=p(n), n_1 = n_1(n), n_2=n_2(n) \in\N$  are functions of $n\in\N$, and $p, n_1, n_2\to\infty$, as $n\to\infty$. Moreover, $n_1/(n_1 + n_2)$ is asymptotically of order $1.$ \label{ass_n_p}
    \item \label{ass_cov}
    For any $i,j,k,l\in \{1,2\}$, we have that $\tr ( \bfSigma_k \bfSigma_l ) \to \infty$ and
    \begin{align*}
        \tr \lb \bfSigma_{n,i} \bfSigma_{n,j} \bfSigma_{n,k} \bfSigma_{n,l}\rb = o \left\{ \tr \lb \bfSigma_{n,i} \bfSigma_{n,j} \rb \tr \lb \bfSigma_{n,k} \bfSigma_{n,l} \rb \right\} .
    \end{align*}
    \end{enumerate}
\end{assumption}
\begin{remark} {\rm
Assumption \ref{ass_model} appeared in many previous works analyzing high-dimensional elliptical data and describes the way how $\xi_{i,1}^2/\sqrt{p} $ degenerates. Examples of specific distributions satisfying these conditions, as well as further discussion, can be found in \cite{wang2023bootstrap, hu_et_al_2019, wang2024testing, hu2019central}. Assumption \ref{ass_n_p} on the sample sizes $n_1, n_2$ being comparable is conventional for two-sample testing problems \citep{srivastava2010testing, cai2013two, schott2007test, baietal2009}. Notably, it does not impose restriction on the magnitude of the dimension-to-sample size ratio $p/n.$
Assumption \ref{ass_cov} was introduced by \cite{lichen2012}, while \cite{yu2024fisher} impose a stronger version of \ref{ass_cov}.  }
\end{remark}

