\begin{theorem} \label{thm_conv_non_feasible}
Suppose that assumptions \ref{ass_model}- \ref{ass_cov} are satisfied. Then, it holds 
\begin{align*}
    \frac{1}{\sigma_n} \lb T_n - \| \bfSigma_{n,1} - \bfSigma_{n,2} \|_F^2 \rb  \cond Z \sim \mathcal{N}(0,1),
\end{align*}
where $\sigma_n$ is defined in \eqref{eq_def_sigma_n}.
\end{theorem}
The proof of Theorem \ref{thm_conv_non_feasible} is deferred to Section \ref{sec_proof_main}. 
\begin{remark}
{\rm
    \cite{lichen2012} showed a central limit theorem for $T_n$ for an ICM-type model. (In fact, the authors allow for a mild relaxation of the model presented in \eqref{eq_icm} and in particular replace the assumption of independent components by the factorizing of mixed moments up to order 8.) In this case, the asymptotic variance equals
       \begin{align*}
         \gamma_n^2 & := \sum_{i=1,2} \Bigg\{ 
        \frac{4}{ n_i^2} \tr^2 \bfSigma_{n,i}^2 
         + \frac{8}{n_i} \tr  \left\{ \bfSigma_{n,i} \lb \bfSigma_{n,1} - \bfSigma_{n,2} \rb   \right\} ^2 
         \nonumber \\ & \quad ~ \quad ~ \quad  
        + \frac{4 ( \nu_{i,3} -3 )}{n_i} \tr \left\{ \bfSigma_{n,i}^{1/2} \lb \bfSigma_{n,1} - \bfSigma_{n,2} \rb \bfSigma_{n,i}^{1/2} \circ \bfSigma_{n,i}^{1/2} \lb \bfSigma_{n,1} - \bfSigma_{n,2} \rb \bfSigma_{n,i}^{1/2}  \right\}
         \Bigg\} \\ & 
        + \frac{8}{n_1 n_2} \tr^2 \lb \bfSigma_{n,1} \bfSigma_{n,2}\rb. 
    \end{align*}
    Here, $'\circ '$ denotes the Hadamard product, and $\nu_{i,3}$ denotes the fourth moment of the independent component. 
    It is important to emphasize that their result is not valid for elliptical data-generating distributions as captured by assumption \ref{ass_model}.
    In general, their asymptotic variance significantly differs from the variance $\sigma_n^2$ for the EM. This observation is illustrated numerically in Figure \ref{fig:histograms}, where we display histograms of    
    $(1/\gamma_n) (T_n - \| \bfSigma_{n,1} - \bfSigma_{n,2}\|_F^2)$ (left column) 
    and $(1/\sigma_n) (T_n - \| \bfSigma_{n,1} - \bfSigma_{n,2}\|_F^2)$ (right column)
    for two elliptical distributions. The black curve indicates the density of the standard normal distribution. It can be observed, that under  \ref{ass_model}, $1/\gamma_n$ does not standardize $T_n$, with $\gamma_n$ overestimating (upper left) or underestimating (lower left) the variance.


    For the normal case, however, we have $\xi_{1,1}^2, \xi_{2,1}^2\sim \mathcal{X}^2_p$, $\tau_1 = \tau_2 = 2$, and $\nu_{1,3} = \nu_{2,3} = 3$. Thus, the variances $\gamma_n^2$ and $\sigma_n^2$ coincide in this special case. }
\end{remark}
Next, we provide the ratio-consistency of the estimator $\hat\sigma_{n,0}$ for $\sigma_{n,0}$ under the null hypothesis and show that its deterministic approximate under the alternative is given by
\begin{align*}
    \tilde\sigma_{n} & =  \frac{2}{n_1} \tr \lb  \bfSigma_{n,1}^2 \rb + \frac{2}{n_2} \tr \lb  \bfSigma_{n,2}^2 \rb. 
\end{align*}
The proof can be found in Section \ref{sec_proof_power_consistent}.
\begin{proposition} \label{prop_consistent_sigma}
     Suppose that assumptions \ref{ass_model}- \ref{ass_cov} are satisfied. Then, it holds
     \begin{align*}
         \frac{\hat\sigma_{n,0}}{\tilde\sigma_{n}} \conp 1.
     \end{align*}
     In particular, if $\mathsf{H}_{0,n}$ holds true for all large $n$, then  $\hat\sigma_{n,0}$ is a ratio-consistent estimator of $\sigma_{n,0}$, that is,
     \begin{align*}
         \frac{\hat\sigma_{n,0}}{\sigma_{n,0}} \conp 1.
     \end{align*}
\end{proposition}
Recall the definition of $ \hat{\mathcal{T}}_{n}$ in \eqref{eq_test_decision}. Then, Proposition \ref{prop_consistent_sigma} and Theorem \ref{thm_conv_non_feasible} imply that the level of the test proposed in \eqref{eq_test_decision} can be asymptotically controlled. 
\begin{corollary}[Level control] \label{cor_level}
    Suppose that assumptions \ref{ass_model}- \ref{ass_cov} are satisfied. 
  If $\mathsf{H}_{0,n}$ holds true for all large $n,$ we have 
            \begin{align*}
                \lim_{n\to\infty} \PR \lb \hat{\mathcal{T}}_{n} > z_{1-\alpha} \rb  = \alpha.
            \end{align*}
\end{corollary}
\begin{remark}
    The analogue of Corollary \ref{cor_level} was proven in \cite{lichen2012} for ICM-type models. Thus, the test based on $\hat{\mathcal{T}}_{n}$ is valid under both ICMs and EMs. 
\end{remark}
The following theorem specifies when the proposed test attains asymptotically power one. This result will be proven in Section \ref{sec_proof_power_consistent}. 
\begin{theorem}[Power consistency] \label{thm_power}
 Suppose that assumptions \ref{ass_model}- \ref{ass_cov} are satisfied. 
  If $\| \bfSigma_{n,1} - \bfSigma_{n,2} \|_F^2 / \sigma_n \to \infty,$ then
    \begin{align*}
          \lim_{n\to\infty} \PR \lb \hat{\mathcal{T}}_{n} > z_{1-\alpha} \rb 
         = 1.
    \end{align*}
\end{theorem}
Theorem \ref{thm_power} says that the proposed test attains nontrivial power if the signal $\| \bfSigma_{n,1} - \bfSigma_{n,2} \|_F^2$ is large compared to the noise $\sigma_n.$ It is not hard to show that a sufficient condition for the test to be powerful is that 
\begin{align*}
   \tilde\sigma_n =  \frac{1}{n_1} \tr \bfSigma_{n,1}^2 + \frac{1}{n_2} \tr \bfSigma_{n,2}^2 = \mathcal{O} \lb \| \bfSigma_{n,1} - \bfSigma_{n,2} \|_F^2 \rb. 
\end{align*}
Sufficient conditions for the latter are discussed in \cite{lichen2012} and will not be repeated here for the sake of brevity. 

