\begin{appendix}
 \section{Proofs of main results} \label{sec_proofs}

In our proofs, we use a notation to compare the size of two sequences of positive numbers $(a_n)_{n \in \mathbb{N}}$ and $(b_n)_{n \in \mathbb{N}}$. We write $a_n \lesssim b_n$, if there exists a non-random constant $C>0$, independent of $n$ such that $a_n \leq C\, b_n$ for all $n\in \N$.
Moreover, we suppress the dependence on $n$ of $\bfSigma_{n,i}$ in our notation, and set  $\bfSigma_{n,i}=:\bfSigma_i$ for $i\in \{1,2\}$. 

\subsection{Proof of Theorem \ref{thm_conv_non_feasible}} \label{sec_proof_main}


\noindent\textbf{Reduction of $T_n$.} 
Note that the statistic $T_n$ is invariant under location shift (see also \cite{lichen2012}), and thus, we may and will assume w.l.o.g. that $\boldsymbol{\mu}_{n,1} = \boldsymbol{\mu}_{n,2} = \mathbf{0}.$ In this case, the leading order terms in the variance of $T_n$ are contributed by the first terms in $U_{n,i}$ and $V_n$, respectively. That is, it suffices to analyze $\tilde T_n = U_{n,1,1} + U_{n,2,1} - 2 V_{1,n},$ where 
\begin{align}
    U_{n,i,1} & =  \frac{1}{ (n_i)_2}\sum_{1 \leq j , k \leq n_i}^\star \lb \bfx_j^{(i)^\top} \bfx_k^{(i)} \rb^2 
    \quad i = 1,2, \label{def_u_ni1} \\ 
    V_{1,n} & = \frac{1}{ n_1 n_2} \sum_{j=1}^{ n_1 } \sum_{k=1}^{n_2 } \lb \bfx_i^{(1)^\top} \bfx_j^{(2)} \rb^2
    .
    \label{def_v_n1}
\end{align}
More formally, the two main steps in the proof of Theorem \ref{thm_conv_non_feasible} lie in the verification of 
\begin{align}
    \label{eq_clt_tilde_T_n}
       \frac{1}{\sigma_n} \lb \tilde T_n - \| \bfSigma_1 - \bfSigma_2 \|_F^2 \rb  \cond Z \sim \mathcal{N}(0,1)
\end{align}
and 
\begin{align} \label{eq_remainder_negl}
    T_n - \tilde T_n = o_{\PR}(\sigma_n). 
\end{align}
The latter fact \eqref{eq_remainder_negl} will be proven in Section \ref{sec_proof_remainder}, while we proceed in the following with a preparatory step for the proof of \eqref{eq_clt_tilde_T_n} via the martingale CLT. 

\noindent\textbf{Preparations for the proof of \eqref{eq_clt_tilde_T_n}.}
Recall that we assume w.l.o.g. that $\boldsymbol{\mu}_{n,i}=\mathbf{0}$.
To facilitate the application of the martingale CLT, we proceed with some preparations. By the means of a martingale decomposition, we write $\tilde T_n$ as a sum of martingale differences. 
For this purpose, we define the triangular array of random variables
\begin{align*}
    \bfx_{j,n} = \bfx_j  = \begin{cases}
        \bfx_{j}^{(1)} & : \textnormal{ if } 1 \leq j \leq n_1, \\
        \bfx_{j - n_1 }^{(2)} & : \textnormal{ if } n_1 +1 \leq j \leq n_1 + n_2,
    \end{cases}
    \quad 1 \leq j \leq n_1 + n_2. 
\end{align*}
Moreover, let $\E_k$ denote the conditional expectation with respect to the $\sigma-$field $\mathcal{F}_k$ generated by $\bfx_1, \ldots, \bfx_k$, $1 \leq k \leq n_1 + n_2.$  More precisely, we have
\begin{align*}
    \tilde T_n =  T_{n,1} + T_{n,2} + T_{n,3},
\end{align*}
where 
\begin{align*}
      T_{n,1} & := \sum_{k=1}^{ n_1 + n_2}  T_{n,k,1}(t) 
      := \sum_{k=1}^{n_1 + n_2} ( \E_k - \E_{k-1} ) \left[  U_{n,1,1}(t) \right] ,\\
     T_{n,2} & := \sum_{k=1}^{n_1 + n_2}  T_{n,k,2}(t)  
     := \sum_{k=1}^{n_1 + n_2} ( \E_k - \E_{k-1} ) \left[  U_{n,2,1}(t)   \right] , \\
    T_{n,3} & := \sum_{k=1}^{n_1 + n_2}  T_{n,k,3} (t) 
    := - 2\sum_{k=1}^{n_1 + n_2} ( \E_k - \E_{k-1} ) \left[  V_{1,n}(t)  \right],
\end{align*}
where $ U_{n,i}, V_n $ are defined in \eqref{eq_def_U} and \eqref{eq_def_V}, respectively. 
 In the following, we will find more handy representations for $T_{n,k,i}$, $i\in \{1,2,3\}$,  by using basic properties of the conditional expectation  
For the first term, we have for $k\leq n_1$
\begin{align*}
    T_{n,k,1} & = \frac{1}{n_1 ( n_1 - 1 )} \sum_{\substack{i,j=1 \\ i \neq j }}^{ n_1 } ( \E_k - \E_{k-1} ) \lb \bfx_i^\top \bfx_j \rb^2 \\ 
    & =   \frac{2}{n_1 ( n_1 - 1 )} \sum_{\substack{i=1 \\ i \neq k }}^{ n_1 } ( \E_k - \E_{k-1} ) \lb \bfx_i^\top \bfx_k \rb^2
    \\ 
    & = \frac{2}{n_1 ( n_1 - 1 )} \sum_{\substack{i=1 }}^{k-1} ( \E_k - \E_{k-1} ) \lb \bfx_i^\top \bfx_k \rb^2 
    +  \frac{2}{n_1 ( n_1 - 1 )} \sum_{\substack{i=k+1 }}^{n_1} ( \E_k - \E_{k-1} ) \lb \bfx_i^\top \bfx_k \rb^2 
    \\ 
    & = \frac{2}{n_1 ( n_1 -1) } \Big\{ \sum_{i=1}^{k-1} \lb \lb \bfx_i^\top \bfx_k \rb^2 - \bfx_i^\top \bfSigma_1 \bfx_i \rb 
    + ( n_1 - k) \lb \bfx_k^\top \bfSigma_1 \bfx_k - \tr \bfSigma_1^2 \rb 
    \Big\} \\ 
    & = \frac{2}{n_1 ( n_1 -1) }  \sum_{i=1}^{k-1} \left\{  \bfx_k^\top \lb \bfx_i \bfx_i^\top - \bfSigma_1 \rb \bfx_k -  \tr \lb  \bfSigma_1 \lb \bfx_i \bfx_i^\top  - \bfSigma_1 \rb \rb  \right\}
    \\ & ~ +  \frac{2 ( k -1) }{n_1 ( n_1 -1) }
    \lb \bfx_k^\top \bfSigma_1 \bfx_k - \tr \bfSigma_1^2 \rb 
     +  \frac{2 ( n_1 - k ) }{n_1 ( n_1 -1) }
    \lb \bfx_k^\top \bfSigma_1 \bfx_k - \tr \bfSigma_1^2 \rb 
    \\ 
    & = \frac{2}{n_1 ( n_1 -1) }  \sum_{i=1}^{k-1} \left\{  \bfx_k^\top \lb \bfx_i \bfx_i^\top - \bfSigma_1 \rb \bfx_k -  \tr \lb  \bfSigma_1 \lb \bfx_i \bfx_i^\top  - \bfSigma_1 \rb \rb  \right\}
    \\ ~& +  \frac{2  }{n_1  }
    \lb \bfx_k^\top \bfSigma_1 \bfx_k - \tr \bfSigma_1^2 \rb.
\end{align*}
For $k \geq n_1 +1,$ it holds $T_{n,k,1} = 0.$
Similarly to $T_{n,1}$, we get for the second term $T_{n,k,2}=0$ for $k \leq n_1$ and for $k\geq n_1 +1$, we have 
\begin{align*}
    T_{n,k,2} & = \frac{2}{ n_2 ( n_2 -1) }  \sum_{i= n_1 +1}^{k-1} \left\{  \bfx_k^\top \lb \bfx_i \bfx_i^\top - \bfSigma_2 \rb \bfx_k -  \tr \bfSigma_2 \lb \bfx_i \bfx_i^\top  - \bfSigma_2 \rb \right\}
    \\ ~& +  \frac{2  }{n_2  }
    \lb \bfx_k^\top \bfSigma_2 \bfx_k - \tr \bfSigma_2^2 \rb .
\end{align*}
We now turn to the computation of the third term. Let us first assume that $k \leq n_1.$ In this case, we get
\begin{align*}
    - \frac{1}{2}  T_{n,k,3} & = \frac{1}{n_1 n_2 } \sum_{i=1}^{ n_1} \sum_{l= n_1+1}^{n_1+ n_2} ( \E_k - \E_{k-1} ) \tr \bfx_i \bfx_i^\top \bfx_l \bfx_l^\top \\
    & = \frac{1}{n_1 n_2 } \sum_{i=1}^{k-1} \sum_{l=n_2}^{n_1 + n_2} ( \E_k - \E_{k-1} ) \tr \bfx_i \bfx_i^\top \bfx_l \bfx_l^\top
    \\ & \quad + \frac{1}{n_1 n_2 } \sum_{i=k+1 }^{ n_1} \sum_{l=n_1+1}^{n_1 + n_2} ( \E_k - \E_{k-1} ) \tr \bfx_i \bfx_i^\top \bfx_l \bfx_l^\top \\ 
    & \quad + \frac{1}{n_1 n_2 }  \sum_{l=n_1+1}^{n_1 + n_2} ( \E_k - \E_{k-1} ) \tr \bfx_k \bfx_k^\top \bfx_l \bfx_l^\top \\ 
    & = \frac{1}{n_1 n_2 }  \sum_{l=n_1+1}^{n_1 + n_2} ( \E_k - \E_{k-1} ) \tr \bfx_k \bfx_k^\top \bfx_l \bfx_l^\top \\
    & = \frac{ 1}{n_1 } \lb \bfx_k^\top \bfSigma_2 \bfx_k - \tr \bfSigma_1 \bfSigma_2 \rb.
\end{align*}
Similar calculations show in the case $k \geq n_1+1$ that
\begin{align*}
   - \frac{1}{2} T_{n,k,3} &= \frac{1}{n_1 n_2 } \sum_{i=1}^{ n_1} \sum_{l=n_1+1}^{n_1 + n_2} ( \E_k - \E_{k-1} ) \tr \bfx_i \bfx_i^\top \bfx_l \bfx_l^\top \\
   & = \frac{1}{n_1 n_2 } \sum_{i=1}^{ n_1}  ( \E_k - \E_{k-1} ) \tr \bfx_i \bfx_i^\top \bfx_k \bfx_k^\top \\
   & = \frac{1}{n_1 n_2 }  \left[   \bfx_k \lb \sum_{i=1}^{ n_1} \bfx_i \bfx_i^\top \rb  \bfx_k  - 
   \tr \bfSigma_2 \lb \sum_{i=1}^{n_1} \bfx_i \bfx_i^\top \rb  
   \right]  \\
   &=  \frac{1}{n_1 n_2 }  \left[   \bfx_k \lb \sum_{i=1}^{n_1} \bfx_i \bfx_i^\top - \bfSigma_1 \rb  \bfx_k  - 
   \tr \bfSigma_2 \lb \sum_{i=1}^{n_1} \bfx_i \bfx_i^\top - \bfSigma_1 \rb  
   \right] \\  & \quad 
   +  \frac{1}{  n_2 } \left[ \bfx_k^\top \bfSigma_1 \bfx_k - \tr \bfSigma_1 \bfSigma_2
   \right].
\end{align*}
Now define 
\begin{align}
    \bfA_{l':l} = \sum_{i=l'}^{l} \lb  \bfx_i \bfx_i^\top - \bfSigma_{\kappa(l)} \rb , \quad 1 \leq l' \leq l \leq n_1 + n_2 , 
    \label{eq_def_A_1k}
\end{align}
where $\kappa(l)=1$ for $1 \leq l \leq n_1$ and $\kappa(l)=2$ for $n_1+1 \leq l \leq {n_1 + n_2}.$
Then, in summary, we have
\begin{align}
    T_{n,k} & := T_{n,k,1} + T_{n,k,2} + T_{n,k,3},
    \label{eq_t_nk_formula}
\end{align}
where for $1 \leq k \leq n_1$ and $n_1 +1 \leq k' \leq n_1 + n_2$,
\begin{align}
    T_{n,k}
    & =  \frac{2}{n_1 ( n_1 -1) }   \left\{  \bfx_k^\top \bfA_{1:(k-1)} \bfx_k -  \tr \bfSigma_1 \bfA_{1:(k-1)} \right\}
    + \frac{2  }{n_1  }
    \lb \bfx_k^\top \bfSigma_1 \bfx_k - \tr \bfSigma_1^2 \rb
   \nonumber \\ & \quad  - \frac{2}{n_1} \lb \bfx_k^\top \bfSigma_2 \bfx_k - \tr \bfSigma_1 \bfSigma_2 \rb
   \nonumber \\ & 
   =  \frac{2}{n_1 }   \Bigg\{  \bfx_k^\top \lb \frac{1}{n_1 - 1} \bfA_{1:(k-1)} + \bfSigma_1 - \bfSigma_{2} \rb \bfx_k \nonumber \\ & 
   -  \tr \bfSigma_1 \lb \frac{1}{ n_1 - 1} \bfA_{1:(k-1)} + \bfSigma_1 - \bfSigma_{2} \rb \Bigg\}
    , \label{eq_t_nk} \\
    T_{n,k'} & = \frac{2}{ n_2 ( n_2 -1) }  \left\{  \bfx_{k'}^\top \bfA_{(n_1+1):(k'-1)} \bfx_{k'} -  \tr \bfSigma_2 \bfA_{(n_1+1) : (k'-1) } \right\} \nonumber \\
    & \quad 
   +  \frac{2  }{n_2  }
    \lb \bfx_{k'}^\top \bfSigma_2 \bfx_{k'} - \tr \bfSigma_2^2 \rb -  \frac{2}{n_1 n_2 }  \left[   \bfx_{k'} \bfA_{1:n_1} \bfx_{k'}  - 
   \tr \bfSigma_2 \bfA_{1:n_1} 
   \right] \nonumber  \\ 
    & \quad  -  \frac{2}{ n_2 } \left[ \bfx_{k'}^\top \bfSigma_1 \bfx_{k'} - \tr \bfSigma_1 \bfSigma_2
   \right] \nonumber \\ 
   & = \frac{2}{  n_2  }  \Bigg\{  
   \bfx_{k'}^\top  \lb \frac{1}{ n_2 -1}  \bfA_{(n_1+1):(k'-1)} - \frac{1}{n_1} \bfA_{1:n_1} + \bfSigma_2 - \bfSigma_1 \rb  \bfx_{k'} \nonumber \\ 
   & \quad -  \tr \bfSigma_2 \lb \frac{1}{ n_2 -1}  \bfA_{(n_1+1):(k'-1)} - \frac{1}{n_1} \bfA_{1:n_1} + \bfSigma_2 - \bfSigma_1 \rb  \Bigg\}.  \label{eq_t_nk'}
\end{align}
We now turn to the computation of the covariance kernel. 
By the martingale CLT and \eqref{eq_t_nk_formula}, we need to compute 
\begin{align*}
    \sum_{k=1}^{n_1 + n_2} \sigma_{n,k}  := \sum_{k=1}^{n_1 + n_2} \E_{k-1} \left[  T_{n,k}^2 \right] . 
\end{align*}
We will show the following auxiliary results. Recall the definition of $\sigma_n^2$ in \eqref{eq_def_sigma_n}. 
\begin{lemma} \label{lem_cov_mean}
Under the assumptions of Theorem \ref{thm_conv_non_feasible}, it holds
    \begin{align*}
         & \E \left[ \sum_{k=1}^{n_1 + n_2}  \sigma_{n,k}^2 \right] 
          =  \sigma_n^2
    + o \lb \sigma_n^2 \rb .
    \end{align*}
\end{lemma}

\begin{lemma}
    \label{lem_cov_var}
   Under the assumptions of Theorem \ref{thm_conv_non_feasible}, it holds
    \begin{align*}
        \E \left[  \sum_{k=1}^{n_1 + n_2}  \sigma_{n,k}^2 \right] - \sum_{k=1}^{n_1 + n_2}  \sigma_{n,k}^2 = o_{\PR}(\sigma_n^2). 
    \end{align*}
\end{lemma}
From Lemma \ref{lem_cov_mean} and Lemma \ref{lem_cov_var}, it follows that 
\begin{align}
    \label{eq_conv_var}
   \frac{ \sum_{k=1}^{n_1 + n_2}  \sigma_{n,k}^2  }{ \sigma_n^2} \conp  1.
\end{align}
 The following lemma says that $\sum_{k=1}^{n_1 + n_2} T_{n,k} / \sigma_n $ satisfies the Lindeberg-type condition. 
\begin{lemma} 
\label{lem_lindeberg}
Under the assumptions of Theorem \ref{thm_conv_non_feasible}, it holds
    \begin{align*}
        \frac{   \sum_{k=1}^{n_1 + n_2}  \E [ T_{n,k}^4  ] }{ \sigma_n^4} = o(1) .
    \end{align*}
\end{lemma}

From \eqref{eq_conv_var} and Lemma \ref{lem_lindeberg}, we conclude \eqref{eq_clt_tilde_T_n} by an application of the martingale CLT \citep[Theorem 18.1]{billingsley1999}. Thus, the next task lies in verifying the lemmas stated in this section. 

\subsubsection{Proofs of Lemma \ref{lem_cov_mean}, Lemma \ref{lem_cov_var} and Lemma \ref{lem_lindeberg}}
In this section, we give the proofs of the auxiliary results needed in the proof of Theorem \ref{thm_conv_non_feasible}. 
\begin{proof}[Proof of Lemma \ref{lem_cov_mean}]
We decompose
\begin{align*}
    \sum_{k=1}^{n_1 + n_2} \sigma_{n,k}^2  = 
    \sum_{k=1}^{n_1} \E_{k-1} \left[ T_{n,k}^2\right]
    + \sum_{k=n_1+1}^{n_1 + n_2} \E_{k-1} \left[ T_{n,k}^2\right]
\end{align*}
Let $k \leq n_1$ and define
\begin{align} \label{eq_def_B1}
    \bfB_1 = \bfB_{1,k} = \lb \frac{1}{ n_1 - 1} \bfA_{1:(k-1)} + \bfSigma_1 - \bfSigma_{2} \rb. 
\end{align}
Using \eqref{eq_t_nk}, Lemma \ref{lem_quad_form_formula} \ref{lem_part1} and Assumption \ref{ass_model}, we have 
\begin{align}
& \E_{k-1} [ T_{n,k}^2(t) ] \nonumber \\
   &=  \frac{4}{n_1^2  }\E_{k-1} \lb \bfx_k^\top \bfB_1 \bfx_k 
    - \tr \bfSigma_1 \bfB_1 \rb^2 \nonumber \\  
    & = \frac{4}{n_1^2  } \Big\{ \frac{\E [ \xi_{1,1}^4 ]}{p(p+2)} \lb \lb \tr  \bfSigma_1 \bfB_1 \rb ^2  + 2 \tr \lb \bfSigma_1 \bfB_1 \rb^2 \rb - \lb  \tr  \bfSigma_1 \bfB_1 \rb^2 \Big\}. \label{a1}
\end{align}
Note that 
\begin{align*}
    \E \tr \lb \bfSigma_1 \bfB_1 \rb^2 
   &  = \frac{1}{ ( n_1 - 1 ) ^2 } \E \left[ \tr \lb  \bfSigma_1 \bfA_{1:(k-1)} \rb^2 \right] + \tr \left\{ \bfSigma_1 \lb \bfSigma_1 - \bfSigma_2 \rb \right\} ^2, \\ 
    \E \tr^2 \lb \bfSigma_1 \bfB_1 \rb 
   &  = \frac{1}{ ( n_1 - 1 ) ^2 } \E \left[ \tr^2 \lb  \bfSigma_1 \bfA_{1:(k-1)} \rb \right] + \tr^2 \lb \bfSigma_1 \lb \bfSigma_1 - \bfSigma_2 \rb \rb .
\end{align*}
Using Lemma \ref{lem_tr_sq}, Lemma \ref{lem_tr} and Assumption \ref{ass_cov}, we see that the term 
\begin{align} \label{eq_1stcase}
\frac{1}{ n_1^2 ( n_1 - 1 ) ^2 } \lb \frac{\E [ \xi_{1,1}^4 ]}{p(p+2)} - 1\rb   \E \left[ \tr^2 \lb  \bfSigma_1 \bfA_{1:(k-1)} \rb \right]
\end{align}
does asymptotically not contribute to the mean of \eqref{a1}.
Using these results, we get for the mean of \eqref{a1}
\begin{align}
\sum_{k=1}^{n_1} \E \left[ \E_{k-1} [ T_{n,k}^2(t) ] \right] 
&= \E \left[ \frac{8}{n_1^2 (n_1 - 1)^2 } \sum_{k=1}^{n_1} \tr \lb \bfSigma_1 \bfA_{1: ( k-1 ) }\rb^2 \right] + \frac{8}{n_1} \tr  \left\{ \bfSigma_1 \lb \bfSigma_1 - \bfSigma_2 \rb   \right\} ^2 \nonumber \\ 
 & + \frac{4}{n_1} \lb \frac{\E [ \xi_{1,1}^4 ]}{p(p+2)} - 1\rb  \tr^2 \lb \bfSigma_1 \lb \bfSigma_1 - \bfSigma_2 \rb \rb \nonumber \\
 & \quad 
    + o \lb \sum_{k=1}^{n_1} \E \left[ \E_{k-1} [ T_{n,k}^2(t) ] \right] \rb \\ 
& = 
    \frac{4}{n_1^2} \tr^2 \bfSigma_1^2 
    + \frac{8}{n_1} \tr  \left\{ \bfSigma_1 \lb \bfSigma_1 - \bfSigma_2 \rb   \right\} ^2 \nonumber \\ 
    & + \frac{4}{n_1} \lb \frac{\E [ \xi_{1,1}^4 ]}{p(p+2)} - 1\rb  \tr^2 \lb \bfSigma_1 \lb \bfSigma_1 - \bfSigma_2 \rb \rb \nonumber \\ 
    & \quad 
    + o \lb \sum_{k=1}^{n_1} \E \left[ \E_{k-1} [ T_{n,k}^2(t) ] \right] \rb  ,
     \label{e1}
\end{align}
where used Lemma \ref{lem_tr} for the last step. 
We now turn to the case $k\geq n_1+1.$ For this purpose, we define
\begin{align}
    \bfB_{2,k} = \bfB_2 = \lb \frac{1}{ n_2 -1}  \bfA_{(n_1+1):(k-1)} - \frac{1}{n_1} \bfA_{1:n_1} + \bfSigma_2 - \bfSigma_1 \rb.
     = : \mathbf{C}_2 + \bfSigma_2 - \bfSigma_1. \label{eq_def_C}
\end{align}
Using \eqref{eq_t_nk'}, Lemma \ref{lem_quad_form_formula} \ref{lem_part1} and Assumption \ref{ass_model}, we have 
\begin{align}
& \E_{k-1} [ T_{n,k}^2(t) ] \nonumber \\
   &=  \frac{4}{n_2^2  }\E_{k-1} \lb \bfx_k^\top \bfB_2 \bfx_k 
    - \tr \bfSigma_2 \bfB_2 \rb^2 \nonumber \\  
    & = \frac{4}{n_2^2  } \Big\{ \frac{\E [ \xi_{2,1}^4 ]}{p(p+2)} \lb \lb \tr  \bfSigma_2 \bfB_2 \rb ^2  + 2 \tr \lb \bfSigma_2 \bfB_2 \rb^2 \rb - \lb  \tr  \bfSigma_2 \bfB_2 \rb^2 \Big\}. \label{a10}
\end{align}
Now we want to identify the dominating terms in the mean of \eqref{a10}. To this end, we note that 
\begin{align} \label{eq_extra_term}
    \frac{4}{n_2^2  } \lb \frac{\E [ \xi_{2,1}^4 ]}{p(p+2)} - 1 \rb   \E \left[ \tr^2  \bfSigma_2 \bfC_2  \right] 
\end{align}
does asymptotically not contribute to the mean of \eqref{a10},
which follows similarly to the analysis of \eqref{eq_1stcase} in the first case of this proof. 
Using this fact and $\E[\xi_{2,1}^4]=p^2 + \mathcal{O}(p)$, we see that the dominating term in the mean of \eqref{a10} will be 
\begin{align}
    & \frac{8}{n_2^2 } \E  \tr \lb \bfSigma_2 \bfB_2 \rb^2 
    +  \frac{4}{( n- n_1)^2} \lb \frac{\E [ \xi_{2,1}^4 ]}{p(p+2)} - 1\rb  \tr^2 \lb \bfSigma_2 \lb \bfSigma_1 - \bfSigma_2 \rb \rb \nonumber 
    \\ & = \frac{8}{n_2^2 } \E \tr \lb \bfSigma_2 \mathbf{C}_2 \rb^2 
    + \frac{8}{n_2^2 } \E \tr \left\{ \bfSigma_2 \lb \bfSigma_1 - \bfSigma_2 \rb \right\}^2
    + \frac{16}{n_2^2 } \E \tr \lb \bfSigma_2 \mathbf{C}_2 \lb \bfSigma_2 - \bfSigma_1 \rb \rb \nonumber \\
    & \quad  +  \frac{4}{( n- n_1)^2} \lb \frac{\E [ \xi_{2,1}^4 ]}{p(p+2)} - 1\rb  \tr^2 \lb \bfSigma_2 \lb \bfSigma_1 - \bfSigma_2 \rb \rb \\ 
    & =  \frac{8}{n_2^2 } \E \tr \lb \bfSigma_2 \mathbf{C}_2 \rb^2 
    + \frac{8 }{n_2^2 }  \tr \left\{ \bfSigma_2 \lb \bfSigma_1 - \bfSigma_2 \rb \right\}^2 \nonumber 
    \\ & \quad + \frac{4}{( n- n_1)^2} \lb \frac{\E [ \xi_{2,1}^4 ]}{p(p+2)} - 1\rb  \tr^2 \lb \bfSigma_2 \lb \bfSigma_1 - \bfSigma_2 \rb \rb \nonumber \\ 
    &= \frac{8}{ n_2^2 ( n_2 - 1 )^2 } \E \tr \lb \bfSigma_2 \bfA_{(n_1+1):(k-1)} \rb^2 
    +  \frac{8}{ n_2^2 n_1^2 } \E \tr \lb \bfSigma_2 \bfA_{1:n_1} \rb ^2 
    \label{h1}
    \\ & \quad  + \frac{8}{ n_2^2 }  \tr \left\{ \bfSigma_2 \lb \bfSigma_1 - \bfSigma_2 \rb \right\}^2
     +  \frac{4}{( n- n_1)^2} \lb \frac{\E [ \xi_{2,1}^4 ]}{p(p+2)} - 1\rb  \tr^2 \lb \bfSigma_2 \lb \bfSigma_1 - \bfSigma_2 \rb \rb, \nonumber 
\end{align}
where we used 
\begin{align*}
    \E \tr \lb \bfSigma_2 \mathbf{C}_2 \lb \bfSigma_2 - \bfSigma_1 \rb \rb = 0.
\end{align*}
Now note that the two summands in \eqref{h1} are computed in Lemma \ref{lem_tr}. 
This gives
\begin{align}
    & \sum_{k= n_1+1}^{n_1 + n_2} \E \E_{k-1} [T_{n,k}^2] \nonumber \\ 
    & = \frac{4}{n_2^2} \tr^2 \bfSigma_2^2
    + \frac{8}{n_2 n_1} \tr^2 \bfSigma_2 \bfSigma_1 \nonumber \\ & \quad +
    \frac{8}{ n_2 }  \tr \left\{ \bfSigma_2 \lb \bfSigma_1 - \bfSigma_2 \rb \right\}^2
     +  \frac{4}{n- n_1} \lb \frac{\E [ \xi_{2,1}^4 ]}{p(p+2)} - 1\rb  \tr^2 \lb \bfSigma_2 \lb \bfSigma_1 - \bfSigma_2 \rb \rb
    \nonumber \\ & \quad 
    + o \lb \sum_{k= n_1+1}^n \E \E_{k-1} [T_{n,k}^2]  \rb . \label{e2}
\end{align}
The proof concludes by combining \eqref{e1} and \eqref{e2}.
\end{proof}
We continue with the proof of Lemma \ref{lem_lindeberg}. 
\begin{proof}[Proof of Lemma \ref{lem_lindeberg}]
    To begin with, we consider the summands for $k\leq n_1.$ Using the formula for $T_{n,k}$ in \eqref{eq_t_nk} and the definition of $\bfB_{1,k}$ in \eqref{eq_def_B1}, we obtain
    \begin{align}
        \sum_{k=1}^{n_1} \E [ T_{n,k}^4]
        &= \frac{4}{n_1^4} \sum_{k=1}^{n_1} \E \lb \bfx_k^\top \bfB_{1,k} \bfx_k - \tr \bfSigma_1 \bfB_{1,k} \rb^4 \nonumber \\
        & \lesssim \frac{1}{n_1^4} \sum_{k=1}^{n_1} \E \left[  \tr^2 \lb \bfSigma_1 \bfB_{1,k} \rb^2 \right] + \frac{1}{n_1^4} o \lb \frac{1}{p}\rb  \sum_{k=1}^{n_1}  \E \left[ \tr^4 \lb \bfSigma_1 \bfB_{1,k} \rb \right]  , 
        \label{eq_est_t_4thmom}
    \end{align}
    where we used Lemma \ref{lem_quad_form_est} for the inequality. 
    First, we concentrate on bounding the first term, namely,
    \begin{align*}
        S_{n,1} = \frac{1}{n_1^4} \sum_{k=1}^{n_1} \E \left[  \tr^2 \lb \bfSigma_1 \bfB_{1,k} \rb^2 \right] .
    \end{align*}
    By the definition of $\bfB_{1,k}$ in \eqref{eq_def_B1}, we obtain
    \begin{align*}
        S_{n,1} \lesssim S_{n,1,1} + S_{n,1,2},
    \end{align*}
    where
    \begin{align*}
        S_{n,1,1} & = \frac{1}{n_1^4 ( n_1-1 )^4} \sum_{k=1}^{n_1} \E \left[  \tr^2 \lb \bfSigma_1 \bfA_{1:(k-1)} \rb^2 \right] , \\
        S_{n,1,2} & = \frac{1}{n_1^3}   \tr^2 \lb \bfSigma_1 \lb \bfSigma_1 - \bfSigma_2 \rb  \rb^2 .
    \end{align*}
    From \eqref{eq_def_sigma_n}, we see that 
    \begin{align*}
        \sigma_n^4 \gtrsim \frac{1}{n_1^2} \tr^2 \left\{ \bfSigma_1 ( \bfSigma_1 - \bfSigma_2) \right\}^2. 
    \end{align*}
    This implies that $S_{n,1,2} = o ( \sigma_n^4). $ Next,  we turn to $S_{n,1,1}$. Since $\bfx_i \bfx_i^\top = \bfSigma_1$ and $\bfx_i$ and $\bfx_j$ are independent for $i \neq j$, we obtain the representation
    \begin{align*}
         & \E \left[  \tr^2 \lb \bfSigma_1 \bfA_{1:(k-1)} \rb^2 \right] \\ 
        & = \sum_{i,j,l,m=1}^{k-1} \E \left[ \tr \lb \bfSigma_{1} \lb \bfx_i \bfx_i^\top - \bfSigma_1 \rb  \bfSigma_{1} \lb \bfx_j \bfx_j^\top - \bfSigma_1 \rb \rb \tr \lb \bfSigma_{1} \lb \bfx_l \bfx_l^\top - \bfSigma_1 \rb  \bfSigma_{1} \lb \bfx_m \bfx_m^\top - \bfSigma_1 \rb \rb \right] \\ 
        & = \sum_{i,j=1}^{k-1} \E \left[ \tr \lb \bfSigma_{1} \lb \bfx_i \bfx_i^\top - \bfSigma_1 \rb \rb^2 \tr \lb \bfSigma_{1} \lb \bfx_j \bfx_j^\top - \bfSigma_1 \rb \rb^2 \right] 
        \\ & \quad
        + 2 \sum_{i,j=1}^{k-1} \E \left[ \tr^2 \lb \bfSigma_{1} \lb \bfx_i \bfx_i^\top - \bfSigma_1 \rb  \bfSigma_{1} \lb \bfx_j \bfx_j^\top - \bfSigma_1 \rb \rb \right] .
    \end{align*}
   Next, we apply the Cauchy-Schwarz inequality for the Frobenius inner product as well as the fact $(a+b)^2 \lesssim a^2 +b^2$ for $a,b\geq 0$. This gives 
    \begin{align*}
         \E \left[  \tr^2 \lb \bfSigma_1 \bfA_{1:(k-1)} \rb^2 \right] 
        & \lesssim \sum_{i,j=1}^{k-1} \E \left[ \tr \lb \bfSigma_{1} \lb \bfx_i \bfx_i^\top - \bfSigma_1 \rb \rb^2 \tr \lb \bfSigma_{1} \lb \bfx_j \bfx_j^\top - \bfSigma_1 \rb \rb^2 \right] \\
        & =  \E \left[ \sum_{i=1}^{k-1} \tr \lb \bfSigma_{1} \lb \bfx_i \bfx_i^\top - \bfSigma_1 \rb \rb^2  \right]^2
        \\ & = \E \left[ \sum_{i=1}^{k-1} \tr \lb \lb \bfSigma_1 \bfx_i \bfx_i^\top \rb^2 - 2 \bfSigma_1 \bfx_i \bfx_i^\top \bfSigma_1 + \bfSigma_1^4  \rb  \right]^2
        \\ 
        & \lesssim 
        \E \left[ \sum_{i=1}^{k-1} \lb \bfx_i^\top \bfSigma_1 \bfx_i - \tr \bfSigma_1^2 \rb^2\right]^2
         + \E \left[ \sum_{i=1}^{k-1} \lb \bfx_i^\top \bfSigma_1^2 \bfx_i - \tr \bfSigma_1^3 \rb  \right]^2 \\ & \quad 
        + ( k - 1 ) ^2 \tr^4 \bfSigma_1^2 + (k - 1)^2 \tr^2 \bfSigma_1^3 \\
        & \lesssim (k-1)
        \E   \lb \bfx_1^\top \bfSigma_1 \bfx_1 - \tr \bfSigma_1^2 \rb^4
        + (k-1)^2 \left\{ \E   \lb \bfx_1^\top \bfSigma_1 \bfx_1 - \tr \bfSigma_1^2 \rb^2 \right\}^2 \\ & \quad 
         + (k - 1) \E   \lb \bfx_1^\top \bfSigma_1^2 \bfx_1 - \tr \bfSigma_1^3 \rb ^2 \\ & \quad 
        + ( k - 1 ) ^2 \tr^4 \bfSigma_1^2 + (k - 1)^2 \tr^2 \bfSigma_1^3 .
    \end{align*}
    We are now in the position to apply Lemma \ref{lem_quad_form_est}. This gives for the summands in $S_{n,1,1}$ 
 \begin{align*}
      \E \left[  \tr^2 \lb \bfSigma_1 \bfA_{1:(k-1)} \rb^2 \right]    
        & \lesssim (k - 1) \tr^2 \bfSigma_1^4 + (k - 1) o(1/p) \tr^4 \bfSigma_1^2 
        \\ & \quad + ( k - 1)^2 \lb  \tr \bfSigma_1^4 +  o(1/\sqrt{p}) \tr^2 \bfSigma_1^2 \rb^2  \\ 
        & \quad + (k-1) \tr \bfSigma_1^6 + (k-1) o(1/\sqrt{p}) \tr^2 \bfSigma_1^3 \\
        & \quad 
        + ( k - 1 ) ^2 \tr^4 \bfSigma_1^2 + (k - 1)^2 \tr^2 \bfSigma_1^4 \\ 
        & \lesssim ( k - 1 ) ^2 \tr^4 \bfSigma_1^2 + (k - 1)^2 \tr^2 \bfSigma_1^4 + (k -1) \tr^3 \bfSigma_1^2
       ,
 \end{align*}
 where we used the inequality $\tr\bfSigma_1^6 \leq \tr^3 \bfSigma^2$ for the last estimate.
    Assumption \ref{ass_cov} implies that the last term is of order 
    \begin{align*}
            ( k - 1 ) ^2 \tr^4 \bfSigma_1^2 + o \lb ( k - 1 ) ^2 \tr^4 \bfSigma_1^2 \rb .
    \end{align*}
    Thus, we get for $S_{n,1,1}$
    \begin{align*}
        S_{n,1,1} \lesssim \frac{1}{n_1^5} \tr^4 \bfSigma_1^2 + o \lb \frac{1}{n_1^5} \tr^4 \bfSigma_1^2 \rb .
    \end{align*}
    As a consequence of \eqref{eq_sigma_n_lower_bound}, we note that  
    \begin{align} \label{eq_bound_sigma_power4}
        \sigma_n^4 \gtrsim \frac{1}{n_1^4} \tr^4 \bfSigma_1^2 .
    \end{align}
    Thus, we conclude that  
    \begin{align} \label{eq_s_n11_result}
        S_{n,1,1}= o ( \sigma_n^4).
    \end{align}
    We now turn to the investigation of the second summand in \eqref{eq_est_t_4thmom}, that is,
    \begin{align*}
        S_{n,2} = \frac{1}{n_1^4} o \lb \frac{1}{p}\rb  \sum_{k=1}^{n_1}  \E \left[ \tr^4 \lb \bfSigma_1 \bfB_{1,k} \rb \right].
    \end{align*}
   By using the definition of $\mathbf{B}_{1,k}$ in \eqref{eq_def_B1}, we obtain
    \begin{align*}
        S_{n,2} & \lesssim S_{n,2,1} + S_{n,2,2}, 
    \end{align*}
    where
    \begin{align*}
        S_{n,2,1} & = \frac{1}{n_1^4 ( n_1-1)^4} o \lb \frac{1}{p}\rb  \sum_{k=1}^{n_1}  \E \left[ \tr^4 \lb \bfSigma_1 \bfA_{1:(k-1)} \rb \right], \\
        S_{n,2,2} & = \frac{1}{n_1^4} o \lb \frac{1}{p}\rb  \sum_{k=1}^{n_1}   \tr^4 \lb \bfSigma_1 \lb \bfSigma_1 - \bfSigma_2 \rb \rb .
    \end{align*}
    Similarly to $S_{n,1,2}$, it follows that $S_{n,2,2} = o ( \sigma_n^4). $ In the following, we use the basic fact that for centered and independent random variables $y_1, \ldots, y_m$ it holds
    \begin{align*}
        \E \left[ \lb \sum_{i=1}^m y_i \rb^4  \right] = \sum_{i=1}^m \E [y_i^4] + 3 \sum_{i \neq j} \E[y_{i}^2] \E[y_j^2].
    \end{align*}
    Combining this equality with Lemma \ref{lem_quad_form_est}, we get for the summands of $S_{n,2,1}$
    \begin{align*}
        & \E \left[ \tr^4 \lb \bfSigma_1 \bfA_{1:(k-1)} \rb \right] 
         = \E \left[ \sum_{i=1}^{k-1} \lb \bfx_i^\top \bfSigma_1 \bfx_i - \tr \bfSigma_1^2 \rb  \right]^4 \\ 
        & \lesssim  (k -1) \E  \lb \bfx_1^\top \bfSigma_1 \bfx_1 - \tr \bfSigma_1^2 \rb ^4
        + (k-1)^2 \left\{ \E  \lb \bfx_1^\top \bfSigma_1 \bfx_1 - \tr \bfSigma_1^2 \rb ^2 \right\}^2 \\ 
        & \lesssim (k-1) \tr^2 \bfSigma_1^4 
        + (k-1) o(1/p) \tr^4 \bfSigma_1^2 
        + (k-1)^2 \lb  \tr \bfSigma_1^4 +  o(1/\sqrt{p}) \tr^2 \bfSigma_1^2 \rb^2 \\
        & \lesssim (k-1)^2 \tr^2 \bfSigma_1^4 
        + (k-1)^2 o(1/p) \tr^4 \bfSigma_1^2 .
    \end{align*}
    Similarly to $S_{n,1,1}$, we obtain $S_{n,2,1} = o ( \sigma_n^4 ) . $
    The case $k > n_1$ can be treated similarly, and we omit the details for the sake of brevity. 
\end{proof}

\begin{proof}[Proof of Lemma \ref{lem_cov_var}] 
    To begin with, we show that 
    \begin{align} \label{eq_new_goal}
         \Var \lb \frac{8}{n_1^2} \sum_{k=1}^{n_1} \tr \lb \bfSigma_1 \bfB_{1,k} \rb^2 \rb ,
         \Var \lb \frac{8}{n_2^2} \sum_{k=n_1+1}^{n_1 + n_2} \tr \lb \bfSigma_2 \bfB_{2,k} \rb^2 \rb
         = o (\sigma_n^4). 
    \end{align}
    In the following, we are going to investigate the first term, and note that the second one can be handled similarly. 
    It follows from the definition of $\bfB_{1,k}$ in \eqref{eq_def_B1} that
    \begin{align}
        & \Var \lb \frac{1}{n_1^2} \sum_{k=1}^{n_1} \tr \lb \bfSigma_1 \bfB_{1,k} \rb^2 \rb 
       \nonumber \\ &  = \frac{1}{n_1^4}  
         \Var \lb \frac{1}{(n_1 - 1)^2} \sum_{k=1}^{n_1} \tr \lb \bfSigma_1 \bfA_{1:(k-1)} \rb^2 + \frac{2}{n_1 - 1} \sum_{k=1}^{n_1} \tr  \lb \bfSigma_1 \bfA_{1:(k-1)}  \lb \bfSigma_1 - \bfSigma_2\rb \rb   \rb 
         \nonumber \\ 
        & \lesssim  \frac{1}{n_1^8} \Var \lb  \sum_{k=1}^{n_1} \tr \lb \bfSigma_1 \bfA_{1:(k-1)} \rb^2 \rb 
        + \frac{1}{n_1^6 }\Var \lb \sum_{k=1}^{n_1} \tr  \lb \bfSigma_1 \bfA_{1:(k-1)}  \lb \bfSigma_1 - \bfSigma_2\rb \rb \rb =: V_{1,n}+ V_{2,n} ,
        \label{e4}
    \end{align}
    where $V_{1,n}$ and $V_{2,n}$ are defined in the obvious way. Thus, to prove \eqref{eq_new_goal}, it suffices to show that 
    \begin{align}
        \label{eq_goal_vn}
        V_{1,n}, V_{2,n} = o(\sigma_n^4). 
    \end{align}
    First, we analyze $V_{1,n}$ in \eqref{e4} and get 
    \begin{align}
    & \frac{1}{n_1^8} \Var \lb  \sum_{k=1}^{n_1} \tr \lb \bfSigma_1 \bfA_{1:(k-1)} \rb^2 \rb \nonumber \\ 
        & = \frac{1}{n_1^8} \sum_{k=1}^n \Var \lb   \tr \lb \bfSigma_1 \bfA_{1:(k-1)} \rb^2 \rb
        + \frac{2}{n_1^8} \sum_{1 \leq k<j \leq n_1} \cov \lb \tr \lb \bfSigma_1 \bfA_{1:(k-1)} \rb^2, \tr \lb \bfSigma_1 \bfA_{1:(j-1)} \rb^2 \rb \nonumber \\
        & = \frac{2}{n_1^8} \sum_{1 \leq k<j \leq n_1} \cov \lb \tr \lb \bfSigma_1 \bfA_{1:(k-1)} \rb^2, \tr \lb \bfSigma_1 \bfA_{1:(j-1)} \rb^2 \rb + o ( \sigma_n^4), \label{b2}
    \end{align}
    where the estimate follows from \eqref{eq_s_n11_result}.
    Using the definition of $\bfA_{1:(k-1)}$ in \eqref{eq_def_A_1k}, we obtain
    \begin{align}
        &  \sum_{1 \leq k<j \leq n_1} \cov \lb \tr \lb \bfSigma_1 \bfA_{1:(k-1)} \rb^2, \tr \lb \bfSigma_1 \bfA_{1:(j-1)} \rb^2 \rb \nonumber \\
        & = \sum_{1 \leq k<j \leq n_1} \sum_{m,m'=1}^{k-1} \sum_{l, l' =1}^{j-1} \cov \Big( \tr \left\{ \bfSigma_1 \lb \bfx_m \bfx_m^\top - \bfSigma_1 \rb \bfSigma_1 \lb \bfx_{m'} \bfx_{m'}^\top - \bfSigma_1 \rb    \right\}, \nonumber \\ 
        & \quad \quad \quad \quad ~ \quad \quad \quad \quad \quad \quad \quad \tr \left\{ \bfSigma_1 \lb \bfx_l \bfx_l^\top - \bfSigma_1 \rb \bfSigma_1 \lb \bfx_{l'} \bfx_{l'}^\top - \bfSigma_1 \rb    \right\} \Big) \nonumber \\
        & = 2 \sum_{1 \leq k<j \leq n_1} \sum_{m,l=1}^{k-1} \Var \lb \tr \left\{ \bfSigma_1 \lb \bfx_m \bfx_m^\top - \bfSigma_1 \rb \bfSigma_1 \lb \bfx_{l} \bfx_{l}^\top - \bfSigma_1 \rb    \right\} \rb \nonumber \\
        &= 2 \sum_{k=1}^{n_1} (n_1-k) (k-1) \Var \lb \tr \left\{ \bfSigma_1 \lb \bfx_1 \bfx_1^\top - \bfSigma_1 \rb     \right\}^2 \rb 
        \nonumber \\ & + 
       2  \sum_{k=1}^{n_1} (n_1-k) (k-1)^2 \Var \lb \tr \left\{ \bfSigma_1 \lb \bfx_1 \bfx_1^\top - \bfSigma_1 \rb \bfSigma_1 \lb \bfx_{2} \bfx_{2}^\top - \bfSigma_1 \rb    \right\} \rb \nonumber \\
        & = 2 n_1^3 \Var \lb \tr \left\{ \bfSigma_1 \lb \bfx_1 \bfx_1^\top - \bfSigma_1 \rb     \right\}^2 \rb 
         + 2
        n_1^4 \Var \lb \tr \left\{ \bfSigma_1 \lb \bfx_1 \bfx_1^\top - \bfSigma_1 \rb \bfSigma_1 \lb \bfx_{2} \bfx_{2}^\top - \bfSigma_1 \rb    \right\} \rb \nonumber \\
        & \lesssim n_1^3 \Var \lb \left\{ \bfx_1^\top \bfSigma_1 \bfx_1 \right\}^2 \rb 
        + n_1^3 \Var \lb  \bfx_1^\top \bfSigma_1^3 \bfx_1  \rb
        + n_1^4 \Var \lb \left\{ \bfx_1^\top \bfSigma_1 \bfx_2 \right\}^2 \rb 
        + n_1^4 \Var \lb  \bfx_1^\top \bfSigma_1^3 \bfx_1  \rb  \label{b_help}\\ 
        & \lesssim n_1^3 \Var \lb \left\{ \bfx_1^\top \bfSigma_1 \bfx_1 \right\}^2 \rb 
        + n_1^4 \Var \lb \left\{ \bfx_1^\top \bfSigma_1 \bfx_2 \right\}^2 \rb 
        + n_1^4 \Var \lb  \bfx_1^\top \bfSigma_1^3 \bfx_1  \rb,
        \label{b3}
    \end{align}
    where we used for \eqref{b_help} the crude upper bound $\Var (X+Y) \lesssim \Var(X) + \Var(Y)$ for two random variables $X,Y.$
    Thus, by \eqref{b2} and \eqref{b3}, it is left to show that 
    \begin{align}
        n_1 ^{-5} \Var \lb \left\{ \bfx_1^\top \bfSigma_1 \bfx_1 \right\}^2 \rb & = o ( \sigma_n^4), \label{b4}\\ 
        n_1^{-4} \Var \lb \left\{ \bfx_1^\top \bfSigma_1 \bfx_2 \right\}^2 \rb & = o ( \sigma_n^4), \label{b5}\\ 
        n_1^{-4} \Var \lb  \bfx_1^\top \bfSigma_1^3 \bfx_1  \rb & = o ( \sigma_n^4 ). \label{b6}
    \end{align}
    First, we have by Lemma \ref{lem_quad_form_est} and Lemma \ref{lem_quad_form_formula} \ref{lem_part1}
    \begin{align*}
        \Var \lb \left\{ \bfx_1^\top \bfSigma_1 \bfx_1 \right\}^2 \rb 
        & = \Var \lb \left\{ \bfx_1^\top \bfSigma_1 \bfx_1 - \tr\bfSigma_1^2\right\}^2 + \lb  2 \tr\bfSigma_1^2 \rb  \bfx_1^\top \bfSigma_1 \bfx_1 \rb \\
         & \lesssim \E \lb  \bfx_1^\top \bfSigma_1 \bfx_1 - \tr\bfSigma_1^2\rb^4 + \tr^2\bfSigma_1^2 \E \lb \bfx_1^\top \bfSigma_1 \bfx_1  - \tr\bfSigma_1^2 \rb^2 \\
         & \lesssim \tr^2 \bfSigma_1^4 + o(1/p) \tr^4 \bfSigma_1^2
         + \tr^2\bfSigma_1^2 \lb \tr \bfSigma_1^4 +\frac{1}{p} \tr^2 \bfSigma_1^2 \rb \\ 
         & = o \lb \tr ^4 \bfSigma_1^2\rb. 
    \end{align*}
    Using the bound $\sigma_n^4 \gtrsim n_1^{-4} \tr^4 \bfSigma_1^2$ from \eqref{eq_bound_sigma_power4}, the assertion \eqref{b4} follows. 

    For the term in \eqref{b5}, we use Lemma \ref{lem_quad_form_formula} \ref{lem_part5} and obtain
    \begin{align*}
        n_1^{-4} \Var \lb \left\{ \bfx_1^\top \bfSigma_1 \bfx_2 \right\}^2 \rb & \lesssim n_1^{-4} \E \lb  \bfx_1^\top \bfSigma_1 \bfx_2  \rb ^4 \lesssim n_1^{-4} \lb \tr^2 \bfSigma_1^4 + \tr \bfSigma_1^8 \rb \\ 
        & = o \lb n_1^{-4} \tr^4 \bfSigma_1^2 \rb, 
    \end{align*}
    which is \eqref{b5}. For the last term, we obtain from Lemma \ref{lem_quad_form_formula} \ref{lem_part1} and assumption \ref{ass_cov}
    \begin{align*}
        n_1^{-4} \Var \lb  \bfx_1^\top \bfSigma_1^3 \bfx_1  \rb 
        & = n_1^{-4} \E \lb  \bfx_1^\top \bfSigma_1^3 \bfx_1 - \tr\bfSigma_1^4 \rb^2 \\
        & \lesssim n_1^{-4} \lb \tr \bfSigma_1^8 + \frac{1}{p} \tr^2 \bfSigma_1^4 \rb 
        = o \lb n_1^{-4} \tr^4 \bfSigma_1^2 \rb.
    \end{align*}
    Thus, \eqref{b6} holds true, and  $V_{1,n} = o(\sigma_n^4).$
    To complete the proof of \eqref{eq_goal_vn}, we continue with the analysis of the second summand $V_{2,n}$ in \eqref{e4}.
    \begin{align*}
       V_{2,n} & = \frac{1}{n_1^6 }\Var \lb \sum_{k=1}^{n_1} \tr  \lb \bfSigma_1 \bfA_{1:(k-1)}  \lb \bfSigma_1 - \bfSigma_2\rb \rb \rb \\ 
       & = \frac{1}{n_1^6 } \sum_{k=1}^{n_1}  \Var \lb \tr  \lb \bfSigma_1 \bfA_{1:(k-1)}  \lb \bfSigma_1 - \bfSigma_2\rb \rb \rb \\ & 
       + \frac{2}{n_1^6 } \sum_{1 \leq k<j\leq n_1} \cov \lb \tr  \lb \bfSigma_1 \bfA_{1:(k-1)}  \lb \bfSigma_1 - \bfSigma_2\rb \rb , \tr  \lb \bfSigma_1 \bfA_{1:(j-1)}  \lb \bfSigma_1 - \bfSigma_2\rb \rb \rb \\
       & = \frac{1}{n_1^6 } \sum_{k=1}^{n_1} (k-1) \Var \lb \tr  \lb \bfSigma_1 \bfx_1 \bfx_1^\top  \lb \bfSigma_1 - \bfSigma_2\rb \rb \rb \\ & 
       + \frac{2}{n_1^6 }  \sum_{1 \leq k<j\leq n_1} (k-1) \Var \lb \tr  \lb \bfSigma_1 \bfx_1 \bfx_1^\top  \lb \bfSigma_1 - \bfSigma_2\rb \rb \rb \\
       & \lesssim \frac{1}{n_1^3}  \tr \lb \bfSigma_1^2 \lb \bfSigma_1 - \bfSigma_2\rb \rb^2
       + \frac{1}{n_1^3} o (1/p) \tr^2 \lb \bfSigma_1^2 \lb \bfSigma_1 - \bfSigma_2\rb \rb
       \\ 
       & \lesssim \frac{1}{n_1^3} \tr \lb \bfSigma_1^2 (\bfSigma_1 - \bfSigma_2) \rb^2 
       \lesssim \frac{1}{n_1^3} \tr \lb \bfSigma_1^2 \rb  \tr \lb \bfSigma_1 (\bfSigma_1 - \bfSigma_2) \rb^2 ,
    \end{align*}
    where we applied Lemma \ref{lem_quad_form_formula} \ref{lem_part1} for the third to last inequality, the fact $\tr^2 \bfC \leq p \tr \bfC^2 $ for any $\bfC\in \R^{p \times p}$ for the second to last inequality and the crude inequality $\tr \bfA \bfB \leq \tr \bfA \tr \bfB$ for positive definite matrices $\bfA, \bfB \in \R^{p\times p}$ in the last step.
    From \eqref{eq_def_sigma_n}, we have the lower bound
    \begin{align} \label{eq_ref_lower_bound_sigma}
      \sigma_n^4 \gtrsim \frac{1}{n_1^3} \tr^2   \lb \bfSigma_1^2 \rb  \tr \lb \bfSigma_1 (\bfSigma_1 - \bfSigma_2) \rb^2 .
    \end{align}
    Combining \eqref{eq_ref_lower_bound_sigma} and assumption \ref{ass_cov}, it follows that $V_{2,n} = o(\sigma_n^4)$, and the proof of \eqref{eq_goal_vn} concludes. This completes the proof of \eqref{eq_new_goal}.

Combining \eqref{eq_new_goal} with \eqref{a1} and \eqref{a10}, we find that
\begin{align} \label{q1}
      \E \left[  \sum_{k=1}^{n_1 + n_2}  \sigma_{n,k}^2 \right] - \sum_{k=1}^{n_1 + n_2}  \sigma_{n,k}^2
      = \operatorname{Rem} + o_{\PR}(\sigma_n^2),
\end{align}
where the remainder satisfies 
\begin{align}
   | \operatorname{Rem} | & \lesssim 
  \E \left[ \sum_{k=1}^{n_1} \frac{1}{n_1^4 p} \tr^2 \lb \bfSigma_1 \bfA_{1:(k-1)} \rb   \right]
   + \sum_{k=1}^{n_1} \frac{1}{n_1^4 p} \tr^2 \lb \bfSigma_1 \bfA_{1:(k-1)} \rb  \label{eq_first_line} \\ & 
   + \E \left[ \sum_{k=n_1 + 1}^{n_2} \frac{1}{n_2^2 p} \tr^2 \lb  \bfSigma_2 \bfC_{2,k} \rb  \right]
    +  \sum_{k=n_1 + 1}^{n_2} \frac{1}{n_2^2 p} \tr^2 \lb  \bfSigma_2 \bfC_{2,k} \rb ,\label{eq_second_line}
\end{align}
and we recall the definition of $\bfC_{2,k}= \bfC_2$ in \eqref{eq_def_C}.
For the terms in \eqref{eq_first_line}, we obtain the order $o_{\PR}(\sigma_n^2)$ from Lemma \ref{lem_tr_sq}. The terms in \eqref{eq_second_line} can be treated similarly, which implies that the right hand side of \eqref{q1} is of order $o_{\PR}(\sigma_n^2)$. 
\end{proof}

\subsubsection{Proof of \eqref{eq_remainder_negl}} \label{sec_proof_remainder}
 \begin{proof}[Proof of \eqref{eq_remainder_negl}]

We begin with the decomposition 

\begin{align*}
    T_n - \tilde{T}_n 
    & =  \sum_{i=1,2} \lb U_{n,i,2} + U_{n,i,3} \rb
    + V_{n,2} + V_{n,3}+ V_{n,4},
\end{align*}
where $U_{n,i,k}$ and $V_{n,k}$ stand for the $k$th summand appearing the definition of $U_{n,i}$ in \eqref{eq_def_U} and $V_n$ in \eqref{eq_def_V}. More precisely, we define for $i\in \{1,2\}$
\begin{align*}
     U_{n,i,2} & := -\frac{2}{(n_i)_3}\sum_{1 \leq j,k,l \leq n_i  }^{\star} \bfx_j^{(i)^\top}\bfx_k^{(i)}\bfx_k^{(i)^\top}\bfx_{l}^{(i)}   \quad  \\ 
       U_{n,i,3} & := \frac{1}{(n_i)_4}\sum_{1 \leq j, k , l, m \leq n_i }^{\star} \bfx_j^{(i)^\top}\bfx_k^{(i)}\bfx_{l}^{(i)^\top}\bfx_m^{(i)}, \\
       V_{n,2} &: =  - \frac{1}{n_1 n_2 (n_1 -1)} \sum_{1 \leq k,l \leq n_1}^\star \sum_{j=1}^{n_2} \bfx_l^{(1)^\top} \bfx_j^{(2)} \bfx_j^{(2)^\top} \bfx_k^{(1)}, \\
    V_{n,3} := &  -   \frac{1}{n_2 n_1 (n_2 -1)} \sum_{1 \leq k,l \leq n_2}^\star \sum_{j=1}^{n_1} \bfx_l^{(2)^\top} \bfx_j^{(1)} \bfx_j^{(1)^\top} \bfx_k^{(2)} , \\ 
    V_{n,4} & := \frac{1}{(n_1)_2 (n_2)_2} \sum_{1 \leq i,k \leq n_1}^\star \sum_{1 \leq j,l \leq n_2}^\star 
    \bfx_i^{(1)^\top} \bfx_j^{(2)} \bfx_k^{(1)^\top} \bfx_l^{(2)^\top} .
\end{align*}
Recalling that $\boldsymbol{\mu}_{n,1} =\boldsymbol{\mu}_{n,2} = \mathbf{0}, $ we have 
\begin{align*}
    \E [ U_{n,i,2}] = \E [ U_{n,i,3}] = \E [ V_{n,k}] = 0 , \quad i\in \{1,2\}, ~ k \in \{2,3,4\}. 
\end{align*}
Thus, it suffices to show that 
\begin{align}
    \Var ( U_{n,i,2}) , \Var (V_{2,n}), \Var(V_{n,3}) & = o (\sigma_n^2), \label{goal1}\\
    \Var ( U_{n,i,3}) , \Var (V_{n,4}) = o (\sigma_n^2). \label{goal2}
\end{align} 
For symmetry reasons, we may concentrate on the case $i=1$ and, to facilitate notation, we again write $\bfx_k^{(1)}=\bfx_k$ for $1 \leq k \leq n_1$. 
    Combining the identities in Lemma \ref{lem_quad_form_formula} \ref{lem_part2}-\ref{lem_part3} with assumption \ref{ass_model}, we obtain 
    \begin{align} 
        \Var ( U_{n,1, 2} ) 
       &  \lesssim \frac{1}{n_1^6} \sum_{1 \leq j,k,l \leq n_1  }^{\star}
        \sum_{1 \leq j',k',l' \leq n_1  }^{\star}
        \cov \lb  \bfx_j^\top \bfx_k \bfx_k^\top \bfx_l ,\bfx_{j'}^\top \bfx_{k'} \bfx_{k'}^\top \bfx_{l'} \rb 
       \label{eq_cov} \\& 
        \lesssim \frac{1}{n^2} \Var  \lb \bfx_1^{\top} \bfx_2 \bfx_2^\top \bfx_3 \rb
        = 
        \frac{1}{n_1^2} \left\{ \frac{\E \xi_{1,1}^4}{p(p+2)} \lb \tr^2 \bfSigma_{1}^2 + 2 \tr \bfSigma_{1}^4 \rb - \tr^2\bfSigma_1^2 \right\}  \nonumber \\
        & \lesssim   \frac{1}{n_1^2 p} \tr^2 \bfSigma_{n,1}^2 +  \frac{1}{n_1^2}\tr\bfSigma_1^4
        = o \lb \frac{1}{n_1^2} \tr^2 \bfSigma_{1}^2 \rb = o(\sigma_n^2).
        \label{eq_bound_un112}
    \end{align}
    Here, we note that covariance terms in \eqref{eq_cov} are zero if $j,l\notin \{j',l',k'\}$ or $j',l' \notin \{ j,l,k\}$, as the random vectors $\bfx_1,\ldots, \bfx_{n_1}$ are independent and centered. 
    For the last estimate in \eqref{eq_bound_un112}, we used the fact that $\sigma_n^2 \gtrsim \frac{1}{n_1^2} \tr^2 \bfSigma_{n,1}^2.$ We note that the terms $V_{n,2}$ and $V_{n,3}$ can be handled similarly as they also include a summation over three pairwise indices. Thus, the proof of \eqref{goal1} conludes, and it suffices to show \eqref{goal2} (the case of four pairwise indices). 
    For similar reasons as above, we restrict ourselves to the proof of  $\Var ( U_{n,1,3}) = o(\sigma_n^2)$ and note the analogue assertion for $V_{n,4}$ can be shown similarly.  
    Combining Lemma \ref{lem_quad_form_formula} \ref{lem_part4} with assumption \ref{ass_model}, we obtain
    \begin{align} \label{eq_cov2}
        \Var (U_{n,1,3}) & \lesssim 
        \frac{1}{n_1^8}\sum_{1 \leq j, k , l, m \leq n_i }^{\star} \sum_{1 \leq j', k' , l', m' \leq n_i }^{\star} 
    \cov \lb \bfx_j \bfx_k \bfx_{l} \bfx_m , \bfx_{j'} \bfx_{k'} \bfx_{l'} \bfx_{m'} \rb 
        \\
        & \lesssim  \frac{1}{n_1^4}   \E \lb \bfx_1^\top \bfx_2 \bfx_3^\top \bfx_4 \rb^2 
        = \frac{1}{n_1^4} \tr^2 \bfSigma_{n,1}^2 = o (\sigma_{n}^2),  \label{eq_bound_un113}
    \end{align}
    Here, we note that covariance terms in \eqref{eq_cov2} are zero if $|\{i,j,k,l,i',j',k',l\}|>4$, since the random vectors $\bfx_1, \ldots \bfx_{n_1}$ are independent and centered. 
    Also, we used $\sigma_n^2 \gtrsim \frac{1}{n_1^2} \tr^2 \bfSigma_{n,1}^2$ for the last estimate in \eqref{eq_bound_un113}.
    This concludes the proof of \eqref{eq_remainder_negl}.
 \end{proof}

\subsection{Proofs of Proposition \ref{prop_consistent_sigma} and Theorem \ref{thm_power}} \label{sec_proof_power_consistent}

\begin{proof}[Proof of Proposition \ref{prop_consistent_sigma}]
It is sufficient to show the first assertion of the theorem, as the second one is an immediate consequence. 
To this end, we assume $i=1$ for convenience.   We may again assume w.l.o.g. that $\boldsymbol{\mu}_i = \mathbf{0.}$ 
It is straightforward to show that $\frac{2}{n_1}U_{n,1}$ is an unbiased estimator for $\frac{2}{n_1} \tr \bfSigma_{n,i}^2$ for $i \in \{1,2\}$. Recall the decomposition $U_{n,1} = U_{n,1,1} + U_{n,1,2} + U_{n,1,3} $, where $U_{n,1,1}$ is defined in \eqref{def_u_ni1}.  From \eqref{eq_bound_un112} and \eqref{eq_bound_un113}, we know that 
\begin{align*}
    \Var (U_{n,1,2} ), \Var (U_{n,1,3} ) = o \lb  \tr^2 \bfSigma_1^2 \rb. 
\end{align*}
For the variance of $U_{n,1,1}$, we have
\begin{align}
    \Var ( U_{n,1,1} ) & \lesssim \frac{1}{n_1^2} \Var \lb \lb \bfx_1^\top \bfx_2\rb^2 \rb + \frac{1}{n_1} \cov \lb \lb \bfx_1^\top \bfx_2\rb^2, \lb \bfx_1^\top \bfx_3\rb^2\rb 
    \lesssim \frac{1}{n_1} \Var \lb \lb \bfx_1^\top \bfx_2\rb^2 \rb  \label{t1}
    .
\end{align}
We also note that, under assumption \ref{ass_model},
 $$ \E \xi_{1,1}^4 = p^2 + \tau_i p+ o(p).$$
For upper bound in \eqref{t1}, we obtain, using Lemma \ref{lem_quad_form_formula} \ref{lem_part5} and assumption \ref{ass_model},
\begin{align*}
   \frac{1}{n_1}  \Var \lb \lb \bfx_1^\top \bfx_2\rb^2 \rb 
    & \lesssim \frac{1}{n_1} \E \lb  \bfx_1^\top \bfx_2\rb^4
    = \frac{3}{n_1}  \lb \frac{\E \xi_{1,1}^4}{p(p+2)} \rb^2 \lb \tr^2 \bfSigma_1^2 + \frac{2}{n_1^2} \tr \bfSigma_1^4\rb 
     = \mathcal{O} \lb \frac{1}{n_1 } \tr^2 \bfSigma_1^2 \rb  \\ &  = o \lb  \tr^2 \bfSigma_1^2 \rb .
\end{align*}
This concludes the proof. 
\end{proof}

\begin{proof}[Proof of Theorem \ref{thm_power}]
 As a preparatory step, we show that 
\begin{align} \label{eq_bound_r}
     \frac{\tilde \sigma_n}{\sigma_n} \lesssim 1.
\end{align}
To this end, we will first verify that the variance $\sigma_n^2$ defined in \eqref{eq_def_sigma_n} satisfies
     \begin{align}
         \sigma_n^2 \geq \frac{4}{n_1^2} \tr^2 \lb \bfSigma_{n,1}^2\rb + \frac{4}{n_2^2} \tr^2 \lb \bfSigma_{n,2}^2\rb. \label{eq_sigma_n_lower_bound}
    \end{align}
 To see this, we first note that $\tr ^2 \bfA \leq p \tr \bfA^2$ for any $p \times p$ matrix $\bfA$ as a consequence from the Cauchy-Schwarz inequality. Using also that $\tau_i\geq 0,$ we obtain  
     \begin{align}
        &    \frac{8}{n_i} \tr  \left\{ \bfSigma_{n,i} \lb \bfSigma_{n,1} - \bfSigma_{n,2} \rb   \right\} ^2   
        + \frac{4 (\tau_i - 2) }{p n_i}  \tr^2 \lb \bfSigma_{n,i} \lb \bfSigma_{n,1} - \bfSigma_{n,2} \rb \rb 
      \nonumber   \\ & \geq \frac{8}{n_i} \tr  \left\{ \bfSigma_{n,i} \lb \bfSigma_{n,1} - \bfSigma_{n,2} \rb   \right\} ^2   
        - \frac{8  }{p n_i}  \tr^2 \lb \bfSigma_{n,i} \lb \bfSigma_{n,1} - \bfSigma_{n,2} \rb \rb 
        \geq 0. \label{eq_ineq_sigma_term_positive}
     \end{align}
     Then, \eqref{eq_sigma_n_lower_bound} follows from the definition of $\sigma_n^2$ in \eqref{eq_def_sigma_n}. 

    Let $k_n = n_1 / (n_1 + n_2). $ Using \eqref{eq_sigma_n_lower_bound}, it is not hard to show that (see p. 914 in \cite{lichen2012})
    \begin{align*}
        \frac{ \tilde\sigma_n }{\sigma_n} \leq \frac{1}{k_n ( 1-k_n)} \lesssim 1. 
    \end{align*}
    This concludes the proof of \eqref{eq_bound_r}.

    Now define $\mu_n = \| \bfSigma_{n,1} - \bfSigma_{n,2} \|_F^2.$  We decompose
    \begin{align*}
            \frac{1}{\hat\sigma_n}T_n
           & = \frac{1}{\hat\sigma_n} \lb T_n - \mu_n \rb + \frac{\mu_n}{\hat\sigma_n}
            = \frac{\tilde\sigma_n}{\hat\sigma_n} \frac{\sigma_n}{\tilde\sigma_n} \frac{1}{\sigma_n} (T_n - \mu_n) + \frac{\mu_n}{\tilde\sigma_n} \frac{\tilde\sigma_n}{\hat\sigma_n}
            = \frac{\mu_n}{\tilde\sigma_n} \frac{\tilde\sigma_n}{\hat\sigma_n} \lb \frac{\sigma_n}{\mu_n} \frac{1}{\sigma_n} (T_n - \mu_n) +1  \rb \\
            & = \frac{\mu_n}{\tilde\sigma_n}  \lb \frac{\sigma_n}{\mu_n} \mathcal{O}_{\PR}(1)  +1  \rb \mathcal{O}_{\PR}(1),
    \end{align*}
    where we used Proposition \ref{prop_consistent_sigma} and Theorem \ref{thm_conv_non_feasible} in the last step. 
    Since $\mu_n / \tilde \sigma_n \gtrsim \mu_n / \sigma_n \to \infty$ by \eqref{eq_bound_r} and our assumption, we have
    \begin{align*}
       \lim_{n\to\infty} \PR \lb\frac{1}{\hat\sigma_n}T_n > z_{1-\alpha} \rb = 1.  
    \end{align*}
\end{proof}

  \section{Background results} \label{sec_appendix_b}
We first collect formulas for mixed moments of bilinear forms in elliptical random vectors. 
\begin{lemma} \label{lem_quad_form_formula}
 Suppose that the $p-$dimensional random vectors $\bfx, \bfx_1, \ldots, \bfx_4$ are independent and satisfy \eqref{eq_em} with $\boldsymbol{\mu}=\mathbf{0}.$
 \begin{enumerate}[label=(\alph*)]
     \item \label{lem_part1}
     Let $\bfC_1, \bfC_2$ be deterministic symmetric $p\times p$ matrices. Then, we have
    \begin{align*}
        & \E \lb \bfx^\top  \bfC_1 \bfx - \tr \bfSigma \bfC_1 \rb \lb \bfx^\top  \bfC_2 \bfx - \tr \bfSigma \bfC_2 \rb \\ 
        & = \frac{\E [ \xi^4 ]}{p(p+2)} \lb \tr \bfSigma \bfC_1 \tr \bfSigma\bfC_2 
        +2 \tr \bfSigma \bfC_1 \bfSigma \bfC_2 \rb - \tr \bfSigma \bfC_1 \tr \bfSigma \bfC_2.
    \end{align*}
    \item \label{lem_part2} It holds
\begin{align*}
    \E \left[ \lb \bfx_1^{\top} \bfx_2 \bfx_2^\top \bfx_3 \rb^2 \right] 
    = \frac{\E \xi_{}^4}{p(p+2)} \lb \tr^2 \bfSigma^2 + 2 \tr \bfSigma^4 \rb. 
    \end{align*}
    \item \label{lem_part3} 
    It holds 
    \begin{align*}
        \E \left[ \lb \bfx_1^\top \bfx_2\rb^2\right] = \tr \bfSigma^2.
    \end{align*}
    \item \label{lem_part4} 
    It holds
    \begin{align*}
        \E \left[ \lb \bfx_1^\top \bfx_2 \bfx_3^\top \bfx_4 \rb^2 \right]  = \tr^2 \bfSigma^2. 
    \end{align*}
    \item \label{lem_part5} 
    It holds
    \begin{align*}
        \E \left[ \lb \bfx_1^\top \bfx_2 \rb ^4 \right] = 3 \lb \frac{\E [\xi^4]}{p(p+2)} \rb^2 \left\{  \tr^2 \lb \bfSigma^2 \rb + 2 \tr \lb \bfSigma^4\rb \right\}  .
    \end{align*}
 \end{enumerate}

\end{lemma}
Part \ref{lem_part1} is an immediate consequence of \cite[Lemma A.1]{hu_et_al_2019}, Part 
\ref{lem_part3} can be verified by a direct computation. Parts \ref{lem_part2}, \ref{lem_part4}, \ref{lem_part5} are given in \cite[Lemma D.2]{wang2023bootstrap}. 

The following lemma provides estimates for higher-order moment of centered quadratic forms in elliptical random vectors. 
\begin{lemma}[Lemma D.4 in \cite{wang2024testing}]
\label{lem_quad_form_est}
    Let $\bfC$ be a deterministic symmetric $p\times p$ matrix. Suppose that the $p-$dimensional random vector $\bfx$ satisfies \eqref{eq_em} with $\boldsymbol{\mu}=\mathbf{0}$ and $\xi$ satisfying condition \eqref{eq_ass_xi}. 
    Then, it holds for any $1 \leq q \leq 8,$
    \begin{align*}
        \E \lb \bfx^\top  \bfC \bfx - \tr \bfSigma \bfC  \rb^q
        \lesssim \tr^{q/2} \lb \bfC \bfSigma \rb^2 
        + o \lb \frac{1}{p^{q/4}} \rb \tr^q \lb  \bfC \bfSigma \rb.
    \end{align*}
\end{lemma}


Next, we compute terms arising in the asymptotic variance of $T_n$ in the proof of Lemma \ref{lem_cov_mean}. To this end, recall the definition of $\bfA_{1:(k-1)}$ in \eqref{eq_def_A_1k}. 
\begin{lemma} \label{lem_tr_sq}
    Under the assumptions of Theorem \ref{thm_conv_non_feasible}, it holds
     $$ \E \left[ \frac{1}{n_1^4 } \sum_{k=1}^{n_1 } \lb \tr  \bfSigma_1 \bfA_{1: (k-1) }\rb ^2 \right]
     =  
     o \lb \frac{1}{n_1^2} \tr^2 \bfSigma_1^2 \rb. $$
\end{lemma}
\begin{proof}[Proof of Lemma \ref{lem_tr_sq}]
    Using Lemma \ref{lem_quad_form_formula} \ref{lem_part1}, we obtain 
    \begin{align*}
         \E \left[  \lb \tr  \bfSigma_1 \bfA_{1: (k-1) }\rb ^2 \right] 
         &= \sum_{i=1}^{k-1} \E \lb \bfx_i^\top \bfSigma_1 \bfx_i - \tr \bfSigma_1^2 \rb ^2 \\
         &=  \sum_{i=1}^{k-1} \left\{ \frac{\E \xi_{1,1}^4}{p ( p +2)} \lb 2 \tr \bfSigma_1^4 +  \tr^2 \bfSigma_1^2 \rb  - \tr^2 \bfSigma_1^2 \right\} \\ 
         &= (k-1) \left\{ \frac{\E \xi_{1,1}^4}{p ( p +2)} \lb 2 \tr \bfSigma_1^4 +  \tr^2 \bfSigma_1^2 \rb  - \tr^2 \bfSigma_1^2 \right\}.
    \end{align*}
    Using $\sum_{k=1}^{n_1} (k-1) = (n_1-1) n_1 /2$, \ref{ass_model} and \ref{ass_cov}, this implies 
    \begin{align*}
        & \E \left[ \frac{1}{n_1^4 } \sum_{k=1}^{n_1 } \lb \tr  \bfSigma_1 \bfA_{1: (k-1) }\rb ^2 \right] \\ 
        & = \frac{1}{n_1^4 } \sum_{k=1}^{n_1 }(k-1) \left\{ \frac{\E \xi_{1,1}^4}{p ( p +2)} \lb 2 \tr \bfSigma_1^4 +  \tr^2 \bfSigma_1^2 \rb  - \tr^2 \bfSigma_1^2 \right\} \\
         & = \frac{(n_1 -1)}{2 n_1^3 }  \left\{ \frac{\E \xi_{1,1}^4}{p ( p +2)} \lb 2 \tr \bfSigma_1^4 +  \tr^2 \bfSigma_1^2 \rb  - \tr^2 \bfSigma_1^2 \right\} \\ 
         &  = \frac{(n_1 -1)}{2 n_1^3 }  \left\{
            (1+o(1)) \tr\bfSigma_1^4 + 
            \frac{\tau_1-2 +o(1)}{p+2} \tr^2 \bfSigma_1^2
         \right\}  \\ 
         & =   o \lb \frac{1}{n^2} \tr^2 \bfSigma_1^2 \rb.
    \end{align*}
\end{proof}

\begin{lemma} \label{lem_tr}
 Under the assumptions of Theorem \ref{thm_conv_non_feasible}, it holds for 
      $k \leq n_1,$ 
     $$  \E \left[ \frac{4}{n_1^2 (n_1 - 1)^2 } \sum_{k=1}^{n_1} \tr \lb \bfSigma_1 \bfA_{1: ( k-1 ) }\rb^2 \right] = \frac{2}{n_1^2} \tr^2 \bfSigma_1^2 + o \lb \frac{1}{n_1^2} \tr^2 \bfSigma_1^2 \rb,  $$
     and for $k> n_1$,
      \begin{align*}  
      & \E \left[ \frac{4}{n_2^2 (n_2 - 1)^2 } \sum_{k=n_1+1}^{n} \tr \lb \bfSigma_1 \bfA_{(n_1+1): ( k-1 ) }\rb^2 \right] \\ 
      & = \frac{2}{n_2^2} \tr^2 \bfSigma_2^2 + o \lb \frac{1}{n_2^2} \tr^2 \bfSigma_2^2 \rb .
      \end{align*}
      Moreover, we have
      \begin{align*}
 \E \left[ \frac{8}{ n_2^2 n_1^2 } \tr \lb \bfSigma_2 \bfA_{1:n_1} \rb ^2 \right] = \frac{8}{ n_2^2 n_1 } \tr^2 \bfSigma_1 \bfSigma_2 + o \lb \frac{1}{ n_2^2 n_1 } \tr^2 \bfSigma_1 \bfSigma_2\rb .  
      \end{align*}
\end{lemma}
\begin{proof}[Proof of Lemma \ref{lem_tr}]
We first use Lemma \ref{lem_quad_form_formula} \ref{lem_part1} and get
    \begin{align*}
         \E \left[ \tr \lb \bfSigma_1 \bfA_{1: ( k-1 ) }\rb^2  \right] 
          &= \sum_{i=1}^{k-1} \E \tr \lb \bfSigma_1 \lb \bfx_i \bfx_i^\top - \bfSigma_1 \rb \rb^2 \\
          &= \sum_{i=1}^{k-1} \E \left[ \lb \bfx_i^\top \bfSigma_1 \bfx_i \rb ^2 
          - 2 \bfx_i^\top \bfSigma_1^3 \bfx_i + \tr \bfSigma_1^4
          \right] \\
          &= \sum_{i=1}^{k-1} \E \left[ \lb \bfx_i^\top \bfSigma_1 \bfx_i \rb ^2 
           - \tr \bfSigma_1^4
          \right] \\ 
         & =  \sum_{i=1}^{k-1} \E \left[ \lb \bfx_i^\top \bfSigma_1  \bfx_i - \tr \bfSigma_1^2 \rb ^2 
          - \tr^2 \bfSigma_1^2 
          + 2 \lb \tr \bfSigma_1^2 \rb \bfx_i^\top \bfSigma_1 \bfx_i 
           - \tr \bfSigma_1^4
          \right] \\
            & =  \sum_{i=1}^{k-1} \E \left[ \lb \bfx_i^\top \bfSigma_1  \bfx_i - \tr \bfSigma_1^2 \rb ^2 
          + \tr^2 \bfSigma_1^2 
           - \tr \bfSigma_1^4
          \right] \\
          &= (k -1 ) \Big\{ \frac{\E \xi_{1,1}^4}{p(p+2)} 
          \left[ \tr^2 \bfSigma_1^2 + 2 \tr \bfSigma_1^4  \right] -  \tr \bfSigma_1^4 
          \Big\}.
    \end{align*}
    Using $\sum_{k=1}^{n_1} (k-1)= n_1 (n_1-1)/2$, \ref{ass_model} and \ref{ass_cov}, this implies
    \begin{align*}
        & \E \left[ \frac{4}{n_1^2 (n_1 - 1)^2 } \sum_{k=1}^{n_1} \tr \lb \bfSigma_1 \bfA_{1: ( k-1 ) }\rb^2 \right] \\ 
        & = \frac{2}{n_1 ( n_1 -1)} \Big\{ \frac{\E \xi_{1,1}^4}{p(p+2)} 
          \left[ \tr^2 \bfSigma_1^2 + 2 \tr \bfSigma_1^4  \right] -  \tr \bfSigma_1^4 
          \Big\} \\
          & =  \frac{2}{n_1^2} \tr^2 \bfSigma_1^2 + o \lb \frac{1}{n^2}  \tr^2 \bfSigma_1^2 \rb  .
    \end{align*}
      This shows the first assertion of the lemma. The second one follows for symmetry reasons. The third assertion follows very similar to the first one, and we do not repeat the arguments here for the sake of brevity. 
\end{proof}



