\section{Non braid positivity}
In this section, we prove that $K_n$ is not braid positive when $n$ is even. Our proof is based on Ito's criterion using the HOMFLY polynomial \cite{Ito22B}.

%%%%%%%%%%%%%%%
\subsection{HOMFLY polynomial and its zeroth coefficient polynomial}
For an oriented link $L$, the HOMFLY polynomial $P_L(v,z)$ is a two--variable Laurent polynomial defined by the skein relation
\[
v^{-1}P_{L_+}(v,z)-vP_{L_-}(v,z)=zP_{L_0}(v,z),
\]
together with $P_{U}(v,z)=1$, where $U$ is the unknot. Here, the links (or diagrams) $L_+$, $L_-$ and $L_0$ coincide outside a small $3$--ball, and inside the $3$--ball, they differ by having the $+1$, $-1$ and $0$--tangle, respectively. Throughout this paper, all braids are assumed to be oriented from left to right.

In \cite{Ito22B}, Ito provided a criterion for the braid positivity of a link using the HOMFLY polynomial. We state the result in the case of knots. Let 
\[
\widetilde P_K(\alpha,z)=(-\alpha)^{-g(K)}P_K(v,z)|_{-v^2=\alpha},
\]
where $g(K)$ denotes the genus of a knot $K$.

\begin{theorem}[{\cite[Theorem 2]{Ito22B}}]\label{thm_Ito_braidpositive}
If $K$ is a braid positive knot, then $\widetilde P_K(\alpha,z)$ is positive, that is, all non-zero coefficients of $\widetilde P_K(\alpha,z)$ are positive integers.
\end{theorem}

The HOMFLY polynomial $P_L(v,z)$ can be expressed in the form
\[
P_L(v,z)=(v^{-1}z)^{-\# L+1}\sum_{i=0}p^i_{L}(v)z^{2i},
\]
where $\# L$ is the number of components of the link $L$. The polynomial $p^i_L(v)$ is called the {\it $i$-th coefficient (HOMFLY) polynomial\/} of $L$. In this paper, we focus on the {\it zeroth coefficient polynomial} $p^0_L(v)$. It is known that this polynomial satisfies several important properties\textup{;} see, for example \cite[Section 2]{Ito22A} and \cite[Section 2]{Tak24}.

The zeroth coefficient polynomial $p^0_L(v)$ satisfies the following skein relation\textup{:}
\begin{equation}\label{zeroth_skein}
v^{-2}p^0_{L_+}(v)-p^0_{L_-}(v)=\left\{
\begin{array}{ll}
p^0_{L_0}(v) & (\delta=0),\\
0 & (\delta=1),
\end{array}
\right.
\end{equation}
where $\delta=\frac{1}{2}(\#L_+-\#L_0+1)\in\{0,1\}$. In particular, $\delta=0$ if $L_+$ is a knot. 
Furthermore, for a two--component link $L=k_1\cup k_2$, we have
\begin{equation}\label{zeroth_skein_link}
p^0_L(v)=(v^{-2}-1)v^{2\cdot \lk(k_1,k_2)}p^0_{k_1}(v)p^0_{k_2}(v),
\end{equation}
where $\lk(k_1,k_2)$ is the linking number of $k_1$ and $k_2$. 
In particular, when $L_+$ is a knot (hence $L_-$ is also a knot and $L_0$ is a two--component link $k_1\cup k_2$), the skein relation \eqref{zeroth_skein} can be rewritten as
\begin{equation}\label{zeroth_skein_NtoP}
p^0_{L_-}(v)=v^{-2}p^0_{L_+}(v)+(1-v^{-2})v^{2\cdot \lk(k_1,k_2)}p^0_{k_1}(v)p^0_{k_2}(v).
\end{equation}

%%%%%%%%%%%%%%%%


\subsection{Degree of $p^0_L$ for a braid positive link $L$}
For a braid $\beta$, let $L(\beta)$ denote the closure of $\beta$. 
A positive braid $\beta$ is a {\it minimal positive braid} if the number of strands of $\beta$ is minimum among all the positive braid representative of $L(\beta)$.
The following proposition is useful when applying the skein relation to a braid positive link.

\begin{proposition}[{\cite[Lemma 2]{vB85}}]\label{Prop_positive_fulltwist}
Let $L$ be a braid positive link that is not an unlink. Then there exists a positive braid $\beta$ such that $L$ is the closure of a positive braid of the form $\sigma_i^2\beta$ for some $i$. Moreover, such a positive braid representative $\sigma_i^2\beta$ of $L$ can be taken so that it is a minimal positive braid.
\end{proposition}


\begin{lemma}\label{Lem_zeroth_degree_bound}
Let $\beta$ be a positive $n$--braid, and let $e$ be the number of crossings of $\beta$. 
Then the degree of the zeroth coefficient polynomial satisfies
\[
\deg p^0_{L(\beta)}(v)\le n+e-\#L(\beta).
\]
\end{lemma}
\begin{proof}
We prove this lemma by induction on $e$. For an unlink $U$, 
\[
p^0_U(v)=(v^{-2}-1)^{\#U-1},
\] 
so $\deg p^0_U(v)=0$.

Assume that $L(\beta)$ is not an unlink. By Proposition \ref{Prop_positive_fulltwist}, we can write $L(\beta)=L(\sigma_i^2 \beta')$ for some $i$, where $\beta'$ is a positive $n$--braid with $e-2$ crossings. (If necessary, we may increase the number of crossings to realize $\beta'$ as an $n$--braid.)

Applying the skein relation \eqref{zeroth_skein}, we get
\[
p^0_{L(\beta)}(v)=p^0_{L(\sigma_i^2\beta')}(v)=v^2p^0_{L(\beta')}(v)+\left\{
\begin{array}{ll}
v^2p^0_{L(\sigma_i\beta')}(v) & (\delta=0),\\
0 & (\delta=1).
\end{array}
\right.
\]
Note that $\#L(\beta')=\#L(\beta)$, and $\#L(\sigma_i\beta')=\#L(\beta)+1$ if $\delta=0$.
By the assumption of induction, we have
\begin{align*}
\deg v^2p^0_{L(\beta')}(v)&\le 2+(n+e-2-\#L(\beta'))\\
&=n+e-\#L(\beta),
\end{align*} 
and if $\delta=0$,
\begin{align*}
\deg v^2p^0_{L(\sigma_i\beta')}(v)&\le 2+(n+e-1-\#L(\sigma_i\beta'))\\
&=n+e-\#L(\beta).
\end{align*}
Therefore, the claim follows.
\end{proof}

\begin{definition}
A positive $n$--braid $\beta$  is said to be {\it sharp\/} if 
\[
\deg p^0_L(\beta)(v)=n+e-\#L(\beta),
\]
where $e$ is the number of crossings of $\beta$.
\end{definition}

We now state several lemmas concerning the notion of sharpness.

\begin{lemma}\label{Lem_nonsharp_1}
If positive braid $\sigma_i^2\beta$ is sharp, then at least one of $\beta$ and $\sigma_i\beta$ is sharp.
\end{lemma}
\begin{proof}
The claim follows immediately from the proof of Lemma \ref{Lem_zeroth_degree_bound}.
\end{proof}

\begin{lemma}\label{Lem_nonsharp_2}
If a positive braid $\beta$ is not a minimal positive braid, then $\beta$ is not sharp.
\end{lemma}
\begin{proof}
Let $\beta$ be a positive $n$--braid that is not minimal, and let $\beta'$ be a minimal positive braid representative of $L(\beta)$ with $n'$ strands ($n'<n$). The number of crossings of $\beta$ and $\beta'$ are given by
\[
n-\chi(L(\beta))\ \text{and}\ n'-\chi(L(\beta)),
\]
respectively \cite{Sta76}. Here $\chi(L)$ is the maximal Euler characteristic among all compact, connected, oriented surfaces whose boundary is a link $L$.

By Lemma \ref{Lem_zeroth_degree_bound}, 
\begin{align*}
\deg p^0_{L(\beta)}(v) &\le n'+n'-\chi(L(\beta))-\#L(\beta)\\
&<n+n-\chi(L(\beta))-\#L(\beta).
\end{align*}
This implies that $\beta$ is not sharp.
\end{proof}


\begin{lemma}\label{Lem_nonsharp_3}
Let $L=k_1 \cup k_2$ be a two--component link represented as the closure of a positive braid $\beta$. Suppose that each component knot $k_1$ and $k_2$ can also be represented as the closure of positive braids $\beta_1$ and $\beta_2$, respectively.
If $\beta$ is sharp, then both $\beta_1$ and $\beta_2$ are sharp.
\end{lemma}
\begin{proof}
Let $n,n_1,n_2$ be the numbers of strands, and $e,e_1,e_2$ be the numbers of crossings of $\beta$, $\beta_1$ and $\beta_2$, respectively. Then, 
\[
n=n_1+n_2,\ e=e_1+e_2+\lk(k_1,k_2).
\]
By \eqref{zeroth_skein_link} and Lemma \ref{Lem_zeroth_degree_bound}, we have
\begin{align*}
\deg p_L^0 &\le 2\cdot \lk(k_1,k_2)+(n_1+e_1-1)+(n_2+e_2-1)\\
&=n+e-2.
\end{align*}
The equality holds if and only if $\beta_1$ and $\beta_2$ are sharp.
Since $\beta$ is sharp, the equality holds, and the result follows. 
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Non--braid positivity for $K_n$}
We are ready to prove that $K_n$ is not braid positive when $n$ is even.

\begin{lemma}\label{lem_Kn_topterm}
For $n\ge 2$, the top term of $p^0_{K_n}(v)$ is $(-1)^nv^{3n^2+3n}$.
\end{lemma}
\begin{proof}
We prove this by induction on $n$. Using the Sage Mathematics Software System \cite{Sage}, one can confirm that the top term of $p^0_{K_2}(v)$ is $v^{18}$.

Throughout the following, we identify each braid with its closure diagram in the skein tree.

\begin{figure}
\centering
\includegraphics[scale=0.07]{K_n_main_skein.pdf}
\caption{The skein tree for the knot $K_n$. Consider the crossing change and the smoothing at the crossing indicated by the dashed circle.}
\label{K_n_main_skein}
\end{figure}

Assume that $n\ge 3$. From the skein tree shown in Figure \ref{K_n_main_skein} and equation \eqref{zeroth_skein_NtoP}, we obtain
\begin{align*}
p^0_{K_n}(v) =& (1-v^{-2})v^{2(3(n-1)\cdot 1+1)}p^0_{T_{2,3}}(v)p^0_{K_{n-1}}(v)\\
&+(1-v^{-2})v^{-2}\cdot v^{2(3(n-2)\cdot 2+2)}p^0_{(T_{2,3})_{2,7}}(v)p^0_{K_{n-2}}(v)\\
&+\cdots\\
&+(1-v^{-2})v^{-2(n-2)}\cdot v^{2(3\cdot1\cdot(n-1)+n-1}p^0_{(T_{2,3})_{n-1,3n-2}}(v)p^0_{K_1}(v)\\
&+v^{-2(n-1)}p_{K_n^+}(v)\\
=& \sum_{k=1}^{n-1}v^{-2(k-1)}(1-v^{-2})v^{2(3(n-k)\cdot k+k)}p^0_{(T_{2,3})_{k,3k+1}}(v)p^0_{K_{n-k}}(v)\\
&+v^{-2(n-1)}p_{K_n^+}(v),
\end{align*}
where $(T_{2,3})_{k,3k-1}$ denotes the $(k,3k-1)$--cable of the right-handed trefoil, $K_n^+$ is the braid positive knot shown in the bottom of Figure \ref{K_n_main_skein}.


%%%
By the induction assumption and the fact $\deg p^0_{K_1}(v)=\deg p^0_{T_{2,5}}(v)=6$, we have $\deg p^0_{K_i}=3i^2+3i$ for $1\le i\le n-1$. Since $(T_{2,3})_{k,3k+1}$ is represented by the closure of the positive braid $X_k^3\cdot[1,2,\ldots,k-1]$, Lemma \ref{Lem_zeroth_degree_bound} gives
\begin{align*}
&\deg \left(v^{-2(k-1)}(1-v^{-2})v^{2(3(n-k)\cdot k+k)}p^0_{(T_{2,3})_{k,3k+1}}(v)p^0_{K_{n-k}}(v) \right)\\
&\le -2(k-1)+2(3(n-k) k+k)+(2k+3k^2+(k-1)-1)+3(n-k)^2+3(n-k)\\
&=3n^2+3n.
\end{align*}
Equality holds if and only if the positive braid $X_k^3\cdot[1,2,\ldots,k-1]$ is sharp.

\begin{claim}\label{claim_cable_nonsharp}
For $k\ge 2$, the positive braid $X_k^3\cdot[1,2,\ldots,k-1]$ is not sharp. 
\end{claim}
\begin{proof}
We consider the skein tree
\[
\begin{array}{ccccccccccccc}
D_0 & \rightarrow & D_1 & \rightarrow & \cdots & \rightarrow & D_i & \rightarrow & D_{i+1} & \rightarrow & \cdots & \rightarrow & D_k,\\
\downarrow & & \downarrow & & &  & \downarrow & & \downarrow & & \\
D_0^s & & D_1^s & & & & D_i^s & &D_{i+1}^s
\end{array}
\]
where $D_0$ is the braid $X_k^3 \cdot [1,2,\ldots,k-1]$ and each $D_i\ (i=1,\ldots,k)$ and $D_i^s\ (i=0,\ldots,k-1)$ are as illustrated in Figures \ref{cable_skein_i} and \ref{cable_skein_i_smooth}. The right arrows correspond to crossing changes, and the down arrows correspond to smoothings. Note that all links in the skein tree are braid positive links.

$D_k$ contains exactly one occurrence of the generator $\sigma_{2k-1}$, and is hence a non-minimal positive braid. Each $D_i^s$ ($0 \le i \le k-1$) is also non-minimal as shown in Figures \ref{cable_skein_i_smooth_nonsharp} and \ref{cable_skein_k-1_smooth_nonsharp}. Thus, by Lemma \ref{Lem_nonsharp_1} and \ref{Lem_nonsharp_2}, the claim follows.
\end{proof}

\begin{figure}
