\begin{lemma}\label{lem_genus}
When $n$ is even, the genus of $K_n$ is given by
\[
g(K_n)=\frac{3}{2}n^2-\frac{1}{2}n+1.
\]
\end{lemma}
\begin{proof}
By \cite{Ni07} and Proposition \ref{prop_Lspace} below, $K_n$ is an $L$--space knot, and hence fibered. A quasi-positive Seifert surface for $K_n$ can be constructed by attaching $3n^2+n+1$ bands to $2n$ disks, where one of the bands corresponds to the braid 
\[
[-1,-2,\ldots,-(n-1),n,n-1,\ldots,2,1]
\] 
and the remaining bands correspond to the other positive crossings. By \cite{Rud89}, the surface is incompressible and therefore serves as the fiber surface of $K_n$. A direct calculation then yields the genus $g(K_n)=\frac{3}{2}n^2-\frac{1}{2}n+1$.
\end{proof}

\begin{proposition}\label{prop_non_braid_positive}
If $n$ is even, then $K_n$ is not braid positive.
\end{proposition}
\begin{proof}
Set $n=2k$. By Lemmas \ref{lem_Kn_topterm} and \ref{lem_genus}, the top term of $(-\alpha)^{-g(K_{2k})}p^0_{K_{2k}}(v)|_{-v^2=\alpha}$ is
\begin{align*}
(-\alpha)^{-(6k^2-k+1)}(-1)^{2k}(-\alpha)^{6k^2+3k}
&=(-\alpha)^{4k-1}\\
&=-\alpha^{4k-1}.
\end{align*}
Since this is the term of $z^0$ in $\widetilde{P}_{K_n}(\alpha,z)$, $\widetilde{P}_{K_n}(\alpha,z)$ is a non-positive polynomial. Therefore, Theorem \ref{thm_Ito_braidpositive} implies that $K_n$ is not braid positive.
\end{proof}

















