\caption{A strongly invertible position of the link $K \cup C_1 \cup C_2 \cup C_3$. The dashed boxes total $2k-1$: $k$ in the upper part and $k-1$ in the lower part.}
\label{strongly_invertible}
\end{figure}

\begin{proposition}\label{prop_Lspace}
The $(12k^2 + 2k)$--surgery on $K_{2k}$ yields an $L$--space. 
\end{proposition}

\begin{proof}
When $k=1$, the $14$--surgery on $K_2=o9\_30634$ yields an $L$--space \cite{BK24}. Assume that $k\ge 2$.
Consider the quotient of the link in Figure \ref{strongly_invertible} under the involution around the axis, as shown in Figure \ref{quotient}. Note that the surgery coefficient on $K$ is $4k^2 + 2k$, and the writhe of $K$ in the diagram is $4k^2 + 2k + 1$. Hence, $(4k^2 + 2k)$--surgery on $K$ corresponds to a tangle replacement by the $(-1)$--tangle.

