\section{Hyperbolicity}

To complete the proof of Theorem \ref{thm_main}, we show that $K_n$ is hyperbolic. To this end, we prove that the braid $\beta_n$ representing $K_n$, regarded as an element of the mapping class group of a punctured $2$--disk, is pseudo-Anosov in the sense of the Nielsen--Thurston classification. We apply the criterion of Bestvina and Handel \cite{BH95}, see also \cite{HK06}.

Let $D$ be a $2$-disk, and $P=\{p_1,\ldots,p_k\}$ be a set of $k$ punctures. Take $k$ small circles $c_i$ $(i=1,\ldots,k)$, each centered at $p_i$, such that the interior of $c_i$  contains no other punctures. Choose a finite graph $G$ embedded in $D$ such that it is homotopy equivalent to $D \setminus P$, and contains $C = \{c_1, \ldots, c_k\}$ as a subgraph. We allow $G$ to have loops, but assume that it has no vertices of valence $1$ or $2$. Let $V(G)$ and $E(G)$ denote the sets of vertices and edges of $G$, respectively. A {\it walk\/} $\tau$ in $G$ is a finite sequence alternating between vertices and edges $(v_1,e_1,v_2,e_2,\ldots,v_{\ell},e_{\ell},v_{\ell+1})$, where $v_1,\ldots,v_{\ell+1}\in V(G)$ and $e_1,\ldots,e_{\ell}\in E(G)$ such that the endpoints of $e_i$ are $v_i$ and $v_{i+1}$. There is no confusion in denoting this walk by $\tau=e_1e_2 \cdots e_{\ell}$. Let $W(G)$ be the set of all walks in $G$.

A homeomorphism $f$ on $D$ that preserves the set of punctures $P$ induces a {\it graph map\/} 
\[
g\colon (V(G),W(G))\to (V(G),W(G)),
\]
which preserves the set $C$ set-wise. (The definition of a graph map involves the notion of a {\it fibered surface\/} associated with $G$, but we omit those details here.) 


\begin{definition}
A graph map $g$ is said to be {\it efficient\/} if there are no integers $m\ge 1$ and edges $e\in E(G)$ such that 
\[
g^m(e)=\cdots e_i e_i \cdots
\]
for some $e_i\in E(G)$. If such integer $m\ge 1$ and an edge $e\in E(G)$ exist, then we say that $g^m(e)$ has a {\it back track\/}.
\end{definition}


Let $\mathrm{Vec}(G)$ be the real vector space spanned by $E(G)$. Each walk in $G$ determines an element of $\mathrm{Vec}(G)$ by mapping to the linear combination in which the coefficient of each $e_i$ is its multiplicity in the walk. For a graph map $g$, we define its transition matrix $T_g$ as the linear transformation
\[
\mathcal{T}_g\colon\textrm{Vec}(G)\to\textrm{Vec}(G)
\]
that maps each edge $e$ to $g(e)$, regarded as an element of $\mathrm{Vec}(G)$. 

Let $C^{\textrm{pre}}$ be the set of edges $e\in E(G)$ such that $g^m(e)$ is contained in $C$ for some $m\ge 1$, and define the set of {\it real edges} by 
\[
E^{\textrm{re}}(G)=E(G)\backslash (C\cup C^{\textrm{pre}}).
\]
By the definition of $g$ and $C^{\textrm{pre}}$, the transition matrix $\mathcal{T}_g$
has the block form:
\[
\mathcal{T}_g=\left(
\begin{array}{ccc}
\mathcal{C} & \mathcal{A} & \mathcal{B}\\
0 & \mathcal{C}^{\textrm{pre}} & \mathcal{D}\\
0 & 0 & \mathcal{T}_g^{\textrm{re}}
\end{array}
\right)
\]
where $\mathcal{C}$, $\mathcal{C}^{\textrm{pre}}$ and $\mathcal{T}_g^{\textrm{re}}$ are the transition matrices associated with $C$, $C^{\textrm{pre}}$ and $E^{\textrm{re}}(G)$, respectively. 

Recall that a nonnegative square matrix $M$ is called {\it irreducible\/} if, for any indices $(i,j)$, there exists  $m\ge 1$ such that the $(i,j)$--entry of $M^m$ is positive. Then, by the Perron--Frobenius theorem, such a matrix $M$ has a real, positive eigenvalue greater than the absolute values of all other eigenvalues.  This eigenvalue is called the {\it Perron--Frobenius eigenvalue\/} and is denoted by $\lambda(M)$ (which coincides with the spectral radius of M).

\begin{theorem}[\cite{BH95}]\label{thm_BH}
Let $f$ be a homeomorphism on $D$ that preserves the set of punctures $P$, and $g$ be an induced graph map for $f$. Suppose that
\begin{itemize}
\item $g$ is efficient, and
\item the transition matrix $\mathcal{T}_g^{{\rm re}}$ with respect to the real edges is irreducible with $\lambda(\mathcal{T}_g^{{\rm re}})>1$.
\end{itemize}
Then the mapping class of $f$ (up to isotopy) is pseudo-Anosov with dilatation equal to $\lambda(\mathcal{T}_g^{{\rm re}})$.
\end{theorem}

\begin{lemma}\label{lem_pA}
The mapping class corresponding to the braid 
\[
\beta_n=X_n^3\cdot [-1,-2,\ldots,-(n-1),n,n-1,n-2,\ldots,2,1,1,2,3,\ldots,n]\ (n\ge 2)
\]
is pseudo-Anosov.
\end{lemma}
\begin{proof}
When $n=2$, the braid $\beta_2$ is pseudo-Anosov by the Sage Mathematics Software System \cite{Sage}. Assume that $n\ge 3$.

Consider the braid 
\[
\beta'_n=[n,n-1,n-2,\ldots,2,1,1,2,3,\ldots,n]\cdot X_n^3\cdot [-1,-2,\ldots,-(n-1)],
\]
which is conjugate to $\beta_n$.

\begin{figure}
\centering
\includegraphics[scale=0.13]{graph.pdf}
\caption{The graph $G$ embedded in $D\backslash \{p_1,\ldots,p_{2n}\}$. Each integer inside a circle $c_i$ represents a puncture.}
\label{graph}
\end{figure}

\begin{figure}
\centering
\includegraphics[scale=0.08]{graph_deform_1_2.pdf}
\caption{The deformation of $G$ induced by the braid $\beta'_n$.}
\label{graph_deform_1_2}
\end{figure}

\begin{figure}
\centering
\includegraphics[scale=0.12]{graph_deform_3.pdf}
\caption{Continued from Figure \ref{graph_deform_1_2}. Here, the deformation from the right bottom in Figure \ref{graph_deform_1_2} to the bottom of this figure is by an isotopy.}
\label{graph_deform_3}
\end{figure}

Let $G$ be a graph embedded in $D\backslash \{p_1,\ldots,p_{2n}\}$ as shown in Figure \ref{graph}. 
Figures \ref{graph_deform_1_2} and \ref{graph_deform_3} illustrate a deformation of $G$ induced by the braid $\beta'_n$. The induced graph map $g$ acts on the real edges as follows: 
\begin{align*}
g(e_i) & =e_{n+1+i}\ \text{for}\ i=1,\ldots,n-1,\\
g(e_{n+i}) & =e_i\ \text{for}\ i=1,\ldots,n-1,\\
g(e_n) & =e_{2n+1}e_{n-1}c_{n-1}\cdots e_{2n}c_{2n}e_{2n}e_{n+1},\\
g(e_{2n}) & =e_{2n+1},\\
g(e_{2n+1}) & =e_{n+1}c_{n+1}e_{n+1}\cdots e_{2n}c_{n-1}e_{2n+2},\ \text{and}\\
g(e_{2n+2}) & = e_n c_n e_n\cdots e_{n-1} e_{2n+1}e_n.
\end{align*}
Note that $e_1,\ldots,e_{2n+2}$ are real edges, and $g(e)$ has no back tracks for any real edge $e$.

Suppose that $g^k(e)$ has a back track for some $e\in E^{\textrm{re}}(G)$ and $k\ge 1$. Then it must occur at $e_n$, that is, $g^k(e)$ contains a sub-walk of the form
\[
g^k(e)=\cdots e_{2n+1} e_n e_n e_{2n+1} \cdots.
\]
This implies that $g^{k-1}(e)$ contains a sub-walk of the form 
\[
g^{k-1}(e)=\cdots e_{2n+2} e_{2n}\cdots \ \text{or}\ \cdots e_{2n}e_{2n+2}\cdots,
\]
which does not occur by Figure \ref{graph_deform_3}. Hence, $g$ is efficient.

Since $g(e_n)$ passes through all real edges of $G$, and for any real edge $e$, there exists $k\ge 1$ such that $g^k(e)$ passes through $e_n$, it follows that some power $(\mathcal{T}_g^{{\rm re}})^m$ of the transition matrix has all entries that are positive integers. Moreover, we can choose $m$ such that the trace of $(\mathcal{T}_g^{{\rm re}})^m$ is greater than $\# E^{\textrm{re}}(G)$. Therefore, $(\mathcal{T}_g^{{\rm re}})$ is irreducible and satisfies $\lambda(\mathcal{T}_g^{\textrm{re}})>1$. By Theorem \ref{thm_BH}, $\beta_n'$ is pseudo-Anosov, and hence so is $\beta_n$.
\end{proof}



\begin{proposition}\label{prop_hyperbolic}
$K_n$ $(n\ge 2)$ is a hyperbolic knot.
\end{proposition}
\begin{proof}
Note that $K_n$ can be obtained by the closure of the braid $X_n\beta_nX^{-1}_n$, and $X_n\beta_nX^{-1}_n$ is also pseudo-Anosov by Lemma \ref{lem_pA}.

\begin{figure}
\centering
\includegraphics[scale=0.08]{K_n_Dehornoy.pdf}
\caption{(Top) The braid $X_n\beta_nX_n^{-1}$. (Middle) The braid obtained by rewriting the braid $\Delta^{-4}X_n\beta_nX_n^{-1}$, where $\Delta$ is the Garside fundamental $2n$--braid. Here the box with $-2$ indicates two left-handed full-twists. (Bottom) The braid obtained by further modifying the middle braid. Since this braid is $\sigma_1$--positive, we have $\Delta^4<_{\textrm{D}}X_n\beta_nX_n^{-1}$ where $<_{\textrm{D}}$ is the Dehornoy order.}
\label{K_n_Dehornoy}
\end{figure}

By Figure \ref{K_n_Dehornoy}, the Dehornoy floor of $X_n\beta_nX^{-1}_n$ is greater than $1$ (see \cite{Ito11} for definition of the Dehornoy floor).
Therefore, by Theorem 1.3 of \cite{Ito11}, the closure of $\beta_n$, namely $K_n$, is a hyperbolic knot.
\end{proof}


\begin{proof}[Proof of Theorem \ref{thm_main}]
By Propositions \ref{prop_non_braid_positive}, \ref{prop_Lspace} and \ref{prop_hyperbolic}, we have the conclusion.
\end{proof}

