%
Let an orthonormal set of vectors $\bfe_i$ ($i=1,2,3$) define a fixed coordinate frame, with $\bfe_1 = \bfN$ and $\bfe_2$ lying on the deformation plane,
%and are respectively perpendicular and parallel to the layers of the unreformed laminate, 
as shown in Fig. \ref{Sch_AL}(a). 
%
In what follows, we refer the components of all vectors and tensors to the fixed Cartesian system with basis vectors $\bfe_i$. We restrict our considerations to the special case that the material is subjected macroscopically to a unidirectional loading along $\bfe_2$, so that the macroscopic deformation gradient, first Piola-Kirchhoff, and Cauchy stress tensors have the following matrix forms
%
\begin{equation}
	\left[ \oF \right] = \text{diag}\{\ol_{1}, \ol_{2}, 1\}, \quad\quad 
	\left[ \oP \right] = \text{diag}\{0, \oP_{2}, \oP_{3}\}, \quad\quad 
	\left[ \osig \right] = \text{diag}\{0, \osig_{2}, \osig_{3}\}
	\label{AL_MacroFields}
\end{equation}
%
respectively, where the notation ``$\text{diag}$'' indicates the diagonal components of a matrix in the orthonormal basis $\bfe_i$.
%
It follows from the more general relation (\ref{SigmaBar}) that the unknown components in (\ref{AL_MacroFields}) are related by
%
\begin{equation}
	\oP_2 = \ol_1 \osig_2 \quad\quad 
	\oP_3 = \ol_1 \ol_2 \osig_3.
	\label{P2P3}
\end{equation}
%
Next, letting $\ol_{2}$ be the (prescribed) loading parameter, we make use of the constitutive relations for the local and macroscopic behavior of the laminate in order to determine the variables $\ol_{1}$, $\osig_{2}$, and $\osig_{3}$ in terms of $\ol_{2}$. The details of this calculation in the pre- and post-bifurcation regime are given in the following subsections \ref{PSol} and \ref{PBSol}, respectively.



\subsection{Principal solution}
\label{PSol} 



To simplify the analysis, we first anticipate that the principal solution for the deformation gradient and Cauchy stress tensors in the constituent phases of the laminate have the following matrix forms 
%
\begin{equation}
	\left[ \oF^{(r)} \right] = \text{diag}\{\ol^{(r)}_1, \ol^{(r)}_2, \ol^{(r)}_3\}, \quad\quad
	\left[ \osig^{(r)} \right] = \text{diag}\{\osig^{(r)}_1, \osig^{(r)}_2, \osig^{(r)}_3\},
	\label{AL_MicroFields}
\end{equation}
%
respectively, with $r=1,2$. Thus, the volume average identities $(\ref{AVEIDS})_1$ and $(\ref{AVEID_TCC_C})_1$ for these tensors reduce to
%
\begin{equation}
	c_0^{(1)} \ol^{(1)}_i +c_0^{(2)} \ol^{(2)}_i = \ol_i, \quad\quad
	c^{(1)} \osig^{(1)}_i +c^{(2)} \osig^{(2)}_i = \osig_i, \quad\quad i=1,2,3,
	\label{AL_VolAveIDs}
\end{equation}
%
where $\ol_3 = 1$ and $\osig_1 = 0$, and where it is recalled that $c_0^{(r)}$ and 
%%MA
% $c^{(r)} = c_0^{(r)} \det \obfF^{(r)} / \det \obfF$ 
$c^{(r)}$
%%
are the volume fractions of the phases in the reference and current configuration, respectively. In addition, the continuity conditions $(\ref{PBConds})_1$ and $(\ref{AVEID_TCC_C})_2$ for the deformation and traction vectors on the phase boundaries of the composite reduce to
%
\begin{equation}
	\ol^{(r)}_2 = \ol_2, \quad\quad
	\ol^{(r)}_3 = \ol_3 = 1,
	\label{AL_DCC}
\end{equation}
%
and
%
\begin{equation}
	\osig^{(r)}_{1} = 0, 
	\label{AL_TCC}
\end{equation}
%
respectively. Moreover, the multiplicative decomposition $\obfF^{(r)} = \obfF^{(r,e)} \obfF^{(r,p)}$ for each phase $r$ may be expresses as 
%
\begin{equation}
	\ol^{(r)}_i =\ol^{(r,e)}_i \ol^{(r,p)}_i, \quad\quad i=1,2,3,
	\label{AL_Lr}
\end{equation}
%
where $\ol^{(r,e)}_i$ and $\ol^{(r,p)}_i$ are respectively the elastic and plastic parts of the total stretch $\ol^{(r)}_i$. Making use of the compatibility conditions (\ref{AL_DCC}), it is convenient to rewrite the decomposition $(\ref{AL_Lr})$ for $i=2$ and $i=3$, along with the plastic incompressibility constraint $\ol^{(r,p)}_1 \ol^{(r,p)}_2 \ol^{(r,p)}_3 = 1$, in the following form
%
\begin{equation}
	\ol^{(r,e)}_2 = \frac{\ol_2}{\ol^{(r,p)}_2}, \quad\quad
	\ol^{(r,e)}_3 = \ol^{(r,p)}_1 \ol^{(r,p)}_2, \quad\quad
	\ol^{(r,p)}_3 = \frac{1}{\ol^{(r,p)}_1 \ol^{(r,p)}_2},
	\label{AL_LEr2LEr3LPr3}
\end{equation}
%
thus, reducing the unknown stretches in the phases to $\ol^{(r,e)}_1$, $\ol^{(r,p)}_1$, and $\ol^{(r,p)}_2$. These unknown, together with the accumulated plastic strain $\oeps^{(r,p)}$ in each phase, are determined in terms of the loading parameter $\ol_{2}$ by making use of the traction continuity condition  $(\ref{AL_TCC})$, along with the constitutive equations of the phases, as detailed in the sequel.



For simplicity, we restrict further our considerations to the special case that the elastic part of the local material behavior is described by the Neo-Hookean stored-energy function
%
\begin{equation}
	W^{(r)} \left( \obfF^{(r,e)}  \right)= \frac{\mu^{(r)}}{2} \left(\oI^{(r,e)} -3 -2\ln \oJ^{(r,e)} \right) + \frac{\beta^{(r)}}{2} \left( \oJ^{(r,e)}-1 \right)^2, \quad\quad
	\beta^{(r)} = \kappa^{(r)} - \frac{2 \mu^{(r)}}{3},
	\label{WrNH}
\end{equation}
%
where $\oI^{(r,e)} = \obfF^{(r,e)} \cdot \obfF^{(r,e)}$, $\oJ^{(r,e)} = \det \obfF^{(r,e)}$, and $\beta^{(r)}$, $\mu^{(r)}$, and $\kappa^{(r)}$ are respectively the Lame, shear, and bulk modulus of phase $r$ at zero strain. For this special case, it can be easily shown that 
%
\begin{equation}
	\osig^{(r)}_{i} = \mu^{(r)} \frac{ \left(\ol^{(r,e)}_{i} \right)^2 - 1 }{  \ol^{(r,e)}_1 \ol_2 \ol^{(r,p)}_1  } + 
	\beta^{(r)} \left(  \ol^{(r,e)}_1 \ol_2 \ol^{(r,p)}_1  - 1 \right), \quad\quad i=1,2,3.
	\label{AL_Sr}
\end{equation}
% 
It can also be shown that the Mandel stress tensor $\obfSig^{(r)}$ in each phase $r$ is equal to the corresponding Kirchhoff stress  $\obftau^{(r)} = \oJ^{(r,e)} \obfsig^{(r)}$. Thus, the associated equivalent stress measure $\oSig^{(r)}_{eq}$ that enters the definition of the von Mises yield criterion for phase $r$ takes the form
%
\begin{equation}
	\oSig^{(r)}_{eq} = \Bigg{\{} \frac{3}{2} \left[ \left(\oSig^{(r,d)}_1 \right)^2 + \left(\oSig^{(r,d)}_2 \right)^2 + \left(\oSig^{(r,d)}_3 \right)^2 \right] \Bigg{\}}^{1/2},
	\label{AL_YFcn2}
\end{equation}
%
where $\oSig^{(r,d)}_i$ are the principal components of the deviatoric part of $\obfSig^{(r)}$, given by
%
\begin{equation}
	\oSig^{(r,d)}_1 = \frac{ \mu^{(2)} } {3} \left[2 \left( \ol^{(r,e)}_{1} \right)^2 - \left( \ol_{2} / \ol^{(r,p)}_{2} \right)^2 - \left( \ol^{(r,p)}_1 \ol^{(r,p)}_2 \right)^2 \right], \quad
	\oSig^{(r,d)}_2 = \frac{ \mu^{(2)} } {3} \left[2 \left( \ol_{2} / \ol^{(r,p)}_{2} \right)^2 - \left( \ol^{(r,e)}_1 \right)^2 - \left( \ol^{(r,p)}_1 \ol^{(r,p)}_2 \right)^2 \right], 
	\label{AL_MandelSigmar}
\end{equation}
%
and $\oSig^{(r,d)}_3 = - \oSig^{(r,d)}_1 - \oSig^{(r,d)}_2$.



Given expression $(\ref{AL_Sr})$ for the stress component $\osig^{(r)}_{1}$, the traction continuity condition $(\ref{AL_TCC})$ defines a quadratic equation for $\ol^{(r,e)}_1$, the positive root of which is given by
%
\begin{equation}
	\ol^{(r,e)}_1 = \frac{ \beta^{(r)} \ol_2 \ol^{(r,p)}_1 + \sqrt{ \left(\beta^{(r)} \ol_2 \ol^{(r,p)}_1 \right)^2 + 4 \mu^{(r)} \left[ \mu^{(r)} + \beta^{(r)} \left( \ol_2 \ol^{(r,p)}_1 \right)^2 \right]} }{2  \left[ \mu^{(r)} + \beta^{(r)} \left( \ol_2 \ol^{(r,p)}_1 \right)^2 \right]}.
	\label{AL_LE1r}
\end{equation}
%
Thus, the unknown variables reduce to $\ol^{(r,p)}_1$, $\ol^{(r,p)}_2$, and $\oeps^{(r,p)}_2$. These variables are treated as the principal unknowns and are obtained from the consistency condition and the components of the normality rule in directions 1 and 2, which read respectively as
%
\begin{equation}
	\dot{\Sigma}^{(r)}_{eq} = \frac{d \Sigma^{(r)}_y}{d \oeps^{(r,p)}} \dot{\oeps}^{(r,p)}, \quad\quad
	\frac{\dot{\l}^{(r,p)}_1}{\l^{(r,p)}_1} = \frac{3 \dot{\oeps}^{(r,p)}}{2 \Sigma^{(r)}_y} \Sigma^{(r,d)}_1, \quad\quad 
	\frac{\dot{\l}^{(r,p)}_2}{\l^{(r,p)}_2} = \frac{3 \dot{\oeps}^{(r,p)}}{2 \Sigma^{(r)}_y} \Sigma^{(r,d)}_2,  
	\label{AL_ODEs}
\end{equation}
%
where $\Sigma^{(r)}_y$ is the current yield stress of phase $r$ and the superimposed dot on a variable indicates the derivative of that variable with respect to $\ol_2$.
The above expressions $(\ref{AL_ODEs})$ constitute a nonlinear system of ODEs for the variables $\ol^{(r,p)}_1$, $\ol^{(r,p)}_2$, and $\oeps^{(r,p)}_2$, which must be integrated numerically along any portion of the loading path involving plastic deformations. For any part of the loading path involving only elastic deformations, the variables $\ol^{(r,p)}_{1}$, $\ol^{(r,p)}_{2}$, and $\oeps^{(r,p)}$ are fixed and equations $(\ref{AL_LE1r})$ determine the elastic stretches $\ol^{(r,e)}_1$ explicitly in terms of $\ol_2$. In any case, given the stretches $\ol^{(r,p)}_1$, $\ol^{(r,p)}_2$, and $\ol^{(r,e)}_1$, the local and macroscopic response of the laminate may be readily obtained from $(\ref{AL_Sr})$ and $(\ref{AL_VolAveIDs})$. 
%
As can be seen from these results, due to special type of loading under consideration here, the stress-stretch response of each constituent phase of the laminate is independent from that of the other phase. 
%



Finally, under the considerations of this subsection, it turns out that the condition $(\ref{LOECond})$ for the loss of macroscopic ellipticity of the elastoplastic laminate takes the simple form
%
\begin{equation}
	\tilde{\cal{L}}_{1212} =0, \quad\quad
	\tilde{\cal{L}}_{1212} = c_0^{(1)} \frac{ \mu^{(1)} }{ (\ol^{(1,p)}_2)^2 } + c_0^{(2)} \frac{ \mu^{(2)} }{ (\ol^{(2,p)}_2)^2 } - 
	\frac{1}{\ol_2^2} \frac{ c_0^{(1)} c_0^{(2)} \left( \mu^{(2)} \ol_1^{(2,e)} / \ol_1^{(2,p)} - \mu^{(1)} \ol_1^{(1,e)} / \ol_1^{(1,p)} \right)^2 }{c_0^{(1)} \mu^{(2)} / (\ol_1^{(2,p)})^2 + c_0^{(2)} \mu^{(1)} / (\ol_1^{(1,p)})^2 }.
	\label{AL_LOEcond}
\end{equation}
%
The above result $(\ref{AL_LOEcond})_1$ implies that the laminate loses macroscopic ellipticity when its incremental strength in shear perpendicular to the layers, as measured by the effective modulus $\tilde{\cal{L}}_{1212}$, vanishes for the first time. 
%
It should be emphasized that, despite its appearance, the LOE condition $(\ref{AL_LOEcond})$ depends on both the loading path and the plastic properties of the constituent phases; this dependence enters through the dependence of the plastic stretches $\ol_1^{(r,p)}$ and $\ol_2^{(r,p)}$ on the latter factors and it is, therefore, implicit.
%
For the special case of a laminate with purely elastic phases, i.e., when $\ol_1^{(r,p)}=\ol_2^{(r,p)}=1$ for all values of $\ol_2$, expression $(\ref{AL_LOEcond})_2$ reduces to
%
\begin{equation}
	\tilde{\cal{L}}_{1212} = c_0^{(1)} \mu^{(1)} + c_0^{(2)} \mu^{(2)} - 
	\frac{1}{\ol_2^2} \frac{ c_0^{(1)} c_0^{(2)} \left( \mu^{(2)} \ol_1^{(2)} - \mu^{(1)} \ol_1^{(1)} \right)^2 }{c_0^{(1)} \mu^{(2)} + c_0^{(2)} \mu^{(1)}},
	\label{AL_LOEcond_E}
\end{equation}
%
where the purely elastic stretches $\ol_1^{(r)} = \ol_1^{(r,e)}$ are given explicitly in terms of the applied stretch $\ol_2$ by expression $(\ref{AL_LE1r})$ for $\ol_1^{(r,p)}=1$.
%
It is recalled that, when the macroscopic LOE condition $(\ref{AL_LOEcond})$ (or $(\ref{AL_LOEcond_E})$, if pertinent) is first met along the principal equilibrium path, a bifurcation to a long-wavelength mode becomes possible for the first time.



\subsection{Post-bifurcation solution}
\label{PBSol} 


%%MA
Next, we discuss the long-wavelength post-bifurcation solution for the class of elastoplastic laminates under the aligned loading conditions of interest. 
%
In particular, we search for a (non isochoric) solution that has (otherwise) the same form as the corresponding solution obtained by \cite{FPC18} for laminates with incompressible Neo-Hookean constituents.
%
The main features of this solution are illustrated schematically in Fig. \ref{Sch_AL}(c), which shows the corresponding deformed, post-bifurcation configuration of the material.
%
The state shown in Fig. \ref{Sch_AL}(c) is characterized by periodic lamellar domains that are formed at a ``mesoscopic'' length-scale $L'$ which is much larger than the ``microscopic'' length-scale $\ell$ of the original unit cell, but still much smaller than the ``macroscopic'' length-scale $L$ of the RVE $\Omega_0$, i.e., $L >> L' >> \ell$.
%
Thus, at its generic post-bifurcation state, the composite exhibits fine lamellar microstructures at two well-seperated length-scales and it is, therefore, a rank-2 laminate.
%
In what follows, the lamellar domains at the length-scale $L'$ are referred to as ``mesolayers,'' while their counterparts at the length-scale $\ell$ are termed ``microlayers.''
%
Furthermore, we make use of the labels ``+'' and ``-'' in order to distinguish between the two different types of mesolayers, while still using the labels ``1'' and ``2'' for the two different types of microlayers. 
%
The deformation gradient and first Piola-Kirchhoff stress fields are taken to be piece-wise uniform both at the level of microlayers and at the level of mesolayers, whereas the homogenized behavior of the mesolayers and the macroscopic, post-bifurcation behavior of the
rank-2 laminate are determined by making use of the piece-wise uniform solution of subsection \ref{PUF}, as detailed in the sequel.


%
%Given the fine character of the microstructures in the rank-2 laminate, it is reasonable to assume that the deformation gradient and first Piola-Kirchhoff stress fields are piece-wise uniform both at the level of microlayers and at the level of mesolayers. 
%
%Based on this assumption, the piece-wise uniform solution of subsection \ref{PUF} may then be used to compute both the  homogenized behavior of the mesolayers and the macroscopic, post-bifurcation behavior of the rank-2 laminate, as detailed in the sequel.
%%


%%MA
Based on the aforementioned solution of \cite{FPC18}, we first anticipate that the volume fraction of each type of mesolayer  is equal to $1/2$, while the corresponding lamination direction (i.e., the direction normal to the mesolayers) is 
%normal to $\bfN=\bfe_1$ and, therefore, 
parallel to the macroscopic loading direction $\bfe_2$, as shown in Fig. \ref{Sch_AL}(c). In addition, the deformation gradient and first Piola-Kirchhoff stress tensors in the mesolayers are taken to be of the forms
%
\begin{equation}
	\left[ \oF^{\pm} \right] =
	\begin{bmatrix}
		\ol_1 & \pm \ogamma^* & 0 \\
		0 & \ol_2 & 0 \\
		0 & 0 & 1
	\end{bmatrix}, \quad\quad
	\left[ \oP^{\pm} \right] =
	\begin{bmatrix}
		0 & 0 & 0 \\
		\pm \oG^*  & \oP_{2} & 0 \\
		0 & 0 & \oP_{3}
	\end{bmatrix},
	\label{PBS_MesoFields}
\end{equation}
%
where $\ogamma^*$ and $\oG^*$ are the corresponding amounts of shear deformation and stress in the mesolayers, which are unknown at this stage. 
%
Note that the matrices in (\ref{PBS_MesoFields}) are consistent with the volume average identities 
%
\begin{equation}
	\frac{1}{2} \left( \obfF^+ +  \obfF^- \right) = \obfF, \quad\quad 
	\frac{1}{2} \left( \obfP^+ +  \obfP^- \right) = \obfP,
	\label{PBS_AVEIDS}
\end{equation}
%
and the deformation- and traction-continuity conditions
%
\begin{equation}
	\obfF^+ -  \obfF^- = 2 \ogamma^* \bfe_1 \otimes \bfe_2, \quad\quad
	\obfP^+ \bfe_2 = \obfP^- \bfe_2 = \obfP \bfe_2.
	\label{PBS_PBConds}
\end{equation}
%
It is recalled that the tensors $\obfF$ and $\obfP$ in $(\ref{PBS_AVEIDS})$ and $(\ref{PBS_PBConds})$ are given by $(\ref{AL_MacroFields})_1$ and $(\ref{AL_MacroFields})_2$, respectively, and that the vector $\bfe_2$ in $(\ref{PBS_PBConds})$ stands for the lamination direction of the mesolayers. 
%
In addition, given that $\det \obfF^+ = \det \obfF^- = \det \obfF$, it follows from $(\ref{MSevol})$ that the volume fraction and the orientation of the mesolayers remain unchanged throughout the deformation. In contrast, making use of $\bfN=\bfe_1$ and expressions $(\ref{PBS_MesoFields})_1$ for $\obfF^+$ and $\obfF^-$ in $(\ref{MSevol})$, it is found that the lamination directions $\bfn^+$ and $\bfn^-$ of the microlayers in the two different sets of mesolayers are given by 
%
\begin{equation}
	\bfn^+ = \frac{\left(\obfF^+ \right)^{-T} \bfe_1 }{ \Big{|}\left(\obfF^+\right)^{-T} \bfe_1 \Big{|} }, \quad\quad
	\bfn^- = \frac{\left(\obfF^-\right)^{-T} \bfe_1 }{ \Big{|}\left(\obfF^-\right)^{-T} \bfe_1 \Big{|} }.
	\label{PBS_MSevol}
\end{equation}
%
It follows from $(\ref{PBS_MSevol})$ that the microlayers in the two sets of mesolayers rotate about $\bfe_3$ by the same angle $\phi$, but in opposite directions (see Fig. \ref{Sch_AL}(c)), such that $\cos \phi = \bfn^+ \cdot \bfe_1 = \bfn^- \cdot \bfe_1$. 



The unknown components of the matrices in $(\ref{PBS_MesoFields})$ are determined from the piece-wise uniform solution of subsection \ref{PUF} for the homogenized behavior of each type of mesolayers, coupled with the elastoplastic constitutive equations of the Appendix for the local material behavior of the underlying microlayers. 
%
Given, however, the symmetries of these matrices, is suffices to consider only one type of mesolayers. Thus, focusing on the mesolayers of the type +, and taking into account the corresponding deformation- and traction-continuity conditions at the phase boundaries of the microlayers, as well as the plane-strain character of the deformation, it follows that the deformation gradient and first Piola-Kirchhoff stress tensors in the microlayers of these mesolayers (of the type +) have the following matrix forms
%
\begin{equation}
	\left[ \oF^{(r)} \right] =
	\begin{bmatrix}
		\oF^{(r)}_{11} & \ogamma^* & 0 \\
		\oF^{(r)}_{21} & \ol_2 & 0 \\
		0 & 0 & 1
	\end{bmatrix}, \quad\quad
	\left[ \oP^{(r)} \right] =
	\begin{bmatrix}
		0 & \oP^{(r)}_{12} & 0 \\
		\oG^* & \oP^{(r)}_{22} & 0 \\
		0 & 0 & \oP^{(r)}_{33}
	\end{bmatrix}
	\label{PBS_MicroFields}
\end{equation}
%
with $r=1,2$. Thus, the volume average identities for these variables over the corresponding mesolayers reduce to
%
\begin{equation}
	c^{(1)}_0 \oF^{(1)}_{11} + c^{(2)}_0 \oF^{(2)}_{11} = \ol_1, \quad\quad 
	c^{(1)}_0 \oF^{(1)}_{21} + c^{(2)}_0 \oF^{(2)}_{21} = 0,
	\label{PBS_AVEF}
\end{equation}
%
and
%
\begin{equation}
	c^{(1)}_0 \oP^{(1)}_{12} + c^{(2)}_0 \oP^{(2)}_{12} = 0, \quad\quad 
	c^{(1)}_0 \oP^{(1)}_{22} + c^{(2)}_0 \oP^{(2)}_{22} = \oP_{2}, \quad\quad 
	c^{(1)}_0 \oP^{(1)}_{33} + c^{(2)}_0 \oP^{(2)}_{33} = \oP_{3}.
	\label{PBS_AVEP}
\end{equation}
%



%
Rewriting expressions $(\ref{PBS_AVEF})$ in the form
%
\begin{equation}
	\oF^{(1)}_{11} = \left( \ol_1 - c^{(2)}_0 \oF^{(2)}_{11} \right) / c^{(1)}_0, \quad\quad 
	\oF^{(1)}_{21} = - c^{(2)}_0 \oF^{(2)}_{21} / c^{(1)}_0,
	\label{PBS_VAF}
\end{equation}
%
and taking into account the fact that $\ol_2$ is treated here as the loading parameter, the unknown deformation-gradient components reduce to $\ol_1$, $\ogamma^*$, $\oF^{(2)}_{11}$, and $\oF^{(2)}_{21}$. 
%
These unknowns are determined in terms of $\ol_2$ by means of a system of ordinary differential equations of the following form
%
\begin{align}
	%\dot{\oP}_{11} &= 0 \Rightarrow 
	&\tilde{\cal{L}}_{1111} \dot{\ol}_1 + \tilde{\cal{L}}_{1122} \dot{\ol}_2 + \tilde{\cal{L}}_{1112} \dot{\ogamma}^* = 0, \label{PBS_ODE1} \\ 
	%\dot{\oP}_{12} &= 0 \Rightarrow 
	&\tilde{\cal{L}}_{1112} \dot{\ol}_1 + \tilde{\cal{L}}_{2212} \dot{\ol}_2 + \tilde{\cal{L}}_{1212} \dot{\ogamma}^* = 0, \label{PBS_ODE2} \\
	&\dot{\oF}^{(2)}_{11} = {\cal A}^{(2)}_{1111} \dot{\ol}_1 + {\cal A}^{(2)}_{1122} \dot{\ol}_2 + {\cal A}^{(2)}_{1112} \dot{\ogamma}^* \label{PBS_ODE3} \\
	&\dot{\oF}^{(2)}_{21} = {\cal A}^{(2)}_{2111} \dot{\ol}_1 + {\cal A}^{(2)}_{2122} \dot{\ol}_2 + {\cal A}^{(2)}_{2112} \dot{\ogamma}^*.
	\label{PBS_ODE4}
\end{align}
%
Equations $(\ref{PBS_ODE1})$ and $(\ref{PBS_ODE2})$ express the conditions $\dot{\oP}^{+}_{11}=0$ and $\dot{\oP}^{+}_{12}=0$, respectively, and follow from $(\ref{SFRF})_1$, whereas equations $(\ref{PBS_ODE3})$ and $(\ref{PBS_ODE4})$ are obtained from $(\ref{FBARrRF2})_2$. 
%
It is remarked that, with a little abuse of notation, the coefficients in $(\ref{PBS_ODE1})$ and $(\ref{PBS_ODE2})$ represent components of the incremental effective modulus tensor $\widetilde{\bmL}$ of the mesolayers of the type + and, accordingly, the coefficients in $(\ref{PBS_ODE3})$ and $(\ref{PBS_ODE4})$ represent components of the deformation-concentration tensor $\bmA^{(2)}$ in the microlayers of type 2 in these mesolayers. 
%
Recall that the tensors $\widetilde{\bmL}$ and $\bmA^{(2)}$ are given by expressions $(\ref{SFRF})_2$ and $(\ref{ArTens})_2$, respectively, in terms of the phase modulus tensors $\bmL^{(r)}$ of the elastoplastic microlayers, which are in turn obtained from expressions $(\ref{ArTens})_2$, evaluated at the corresponding deformation gradients $(\ref{PBS_MicroFields})$.
%
It is also remarked that the superimposed dot over quantities in equations $(\ref{PBS_ODE1}) - (\ref{PBS_ODE4})$ indicates the derivative of these quantities with respect to the loading parameter $\ol_2$. 
%



%
Note that, when evaluated along the principal equilibrium path of the previous subsection, the system of ODEs $(\ref{PBS_ODE1})-(\ref{PBS_ODE4})$ reduces to
%
\begin{equation}
	\tilde{\cal{L}}_{1111} \dot{\ol}_1 + \tilde{\cal{L}}_{1122} \dot{\ol}_2 = 0, \quad\quad 
	\tilde{\cal{L}}_{1212} \dot{\ogamma}^* = 0, \quad\quad
	\dot{\oF}^{(2)}_{11} = {\cal A}^{(2)}_{1111} \dot{\ol}_1 + {\cal A}^{(2)}_{1122} \dot{\ol}_2, \quad\quad
	\dot{\oF}^{(2)}_{21} = 0.
	\label{PS_ODEs}
\end{equation}
%
It is observed from $(\ref{PS_ODEs})_2$ that if $\tilde{\cal{L}}_{1212} \ne 0$ then $\dot{\ogamma}^* = 0$.
%
Hence, in the strongly elliptic regime of the laminate, within which $\tilde{\cal{L}}_{1212} > 0$, we have that $\ogamma^* = 0$ and, in extend, the solution $(\ref{PBS_MesoFields})$ under consideration here coincides with the principal solution $(\ref{AL_MacroFields})$ of the previous subsection. 
%
The first instance at which the system of ODEs $(\ref{PBS_ODE1})-(\ref{PBS_ODE4})$ admits a non-trivial solution for $\ogamma^*$ as the loading parameter $\ol_2$ increases and/or decreases from its original value $\ol_2=1$ in the undeformed state (Fig. \ref{Sch_AL}(a)) is when $\ol_2$ reaches a critical value, say $\ol^{cr}_2$, for which the macroscopic LOE condition $(\ref{AL_LOEcond})$ is first met. This value of $\ol_2$ defines the onset of a bifurcation from the principal to the post-bifurcation solution, which leads in turn to the formation of the mesoscopic lamellar domains of Fig. \ref{Sch_AL}(c).
%



%
Thus, the unknown deformation gradient components $\ol_1$, $\ogamma^*$, $\oF^{(2)}_{11}$, and $\oF^{(2)}_{21}$ are obtained in terms of $\ol_2$ by integrating the system of ODEs $(\ref{PBS_ODE1}) - (\ref{PBS_ODE2})$, together with the associated elastoplastic constitutive relations of the Appendix, along any given loading path, starting from the critical value $\ol_2 = \ol^{cr}_2$. 
%
The initial conditions for this integration, i.e., the values of these unknowns at $\ol_2 = \ol^{cr}_2$, are determined from the principal solution of the previous subsection. 
%
The unknown stress components in $(\ref{PBS_MicroFields})_2$ are obtained as a byproduct of this integration procedure (see subsection \ref{NI}), while their counterparts in $(\ref{PBS_MesoFields})_2$, including the macroscopic stress components $\oP_2$ and $\oP_3$, are determined by making use of the volume average identities $(\ref{PBS_AVEP})$.





\section{Results and Discussion}
\label{RD} 



In this section, we make use of the constitutive relations developed in the preceding section in order to study the effect of fiber plasticity on the macroscopic response and domain formation in soft biological composites. 


For simplicity, we focus our considerations on the class of laminates comprised of a purely elastic phase 1 and an elastoplastic phase 2, assuming that the elastic behavior of each phase $r$, with $r=1,2$, is described by means of the Neo-Hookean stored-energy function (\ref{WrNH}). In addition, we assume that plastic yielding in phase 2 is governed by the von Mises yield criterion $(\ref{YC})$, along with the following isotropic stain-hardening law
%
\begin{equation}\label{Eqn: specific hardening law}
	\Sigma_{y}^{(2)}= \Sigma_{0}^{(2)} + h^{(2)} \oeps^{(2,p)},
\end{equation}
%
where $\Sigma_{0}^{(2)}$ is the initial yield stress of phase 2, $h^{(2)}$ is the corresponding (constant) hardening modulus, and $\oeps^{(2,p)}$ is the accumulated plastic strain in phase 2. 
%
In order to model fiber plasticity, we focus our attention on the case that the elastoplastic phase (fibers) is elastically stiffer than the purely elastic phase (matrix), such that $\mu^{(2)} \ge \mu^{(1)}$ and $\kappa^{(2)} \ge \kappa^{(1)}$. 
%
Given that the actual biological composites of interest are typically subjected to unidirectional, cyclic loading conditions along the direction of the fibers, in this section we also restrict our considerations to  aligned, plane-strain, non-monotonic loading conditions, such that the applied macroscopic stretch $\ol_2$ is first increased monotonically from its original value $\ol_2 = 1$ up to a maximum value $\ol^{max}_2$, and then decreased monotonically from $\ol_2=\ol^{max}_2$ down to a minimum value $\ol^{min}_2$. Results are presented in the sequel for various values of $\ol^{max}_2$, but the same value $\ol^{min}_2 = 0.5$ is used in all calculations. 
%



%
The results of this section are organized into two parts. In the first part, we focus our considerations on the principal and post-bifurcation behavior of the composite materials of interest, while in the second part, we present detailed results concerning the critical conditions for the onset of long-wavelength bifurcations, as determined by the macroscopic LOE condition $(\ref{LOECond})$ for the special case that $\ol^{(1,p)}_1 = \ol^{(1,p)}_2 \equiv  1$ and $\ol^{(1,e)}_1 \equiv \ol^{(1)}_1$.
%
For brevity, the principal and post-bifurcation solutions are labeled PS and PBS, respectively.
%
Whenever necessary, the critical conditions at which the laminate loses macroscopic ellipticity for the first time along the principal path are indicated by a superimposed dot.
%
Results corresponding to purely elastic and elastoplastic incremental deformations are represented by dashed and continuous lines, respectively.




\subsection{Principal and post-bifurcation behavior}
\label{MR}



