\section*{Appendix: Finite elastic and plastic deformations}
\label{FDef}



In this appendix, following \cite{PAB1993}, we define constitutive relations for homogeneous solids undergoing finite elastic and plastic deformations. 
%
These relations are used in the main body of the article to characterize the local material behavior in the constituent phases of the composite materials of interest.


\subsection*{Kinematics}
\label{Kinematics}


Consider an arbitrary deformation $\bfx = \bfx (\bfX,t)$ of a homogeneous body from %some
a fixed reference configuration $\Omega_0$ at time $t_0$ to its current configuration $\Omega$ at time $t$, where the position vectors of a typical material point are denoted by $\bfX$ and $\bfx$, respectively. Let $\bfv = \dot{\bfx} (\bfX,t)$ denote the corresponding velocity field. The mapping $\bfx = \bfx (\bfX,t)$ is assumed to be one-to-one and differentiable, so that the deformation gradient tensor $\bfF$ and the velocity gradient tensor $\bfL = \dot{\bfF} \bfF^{-1}$, with components $F_{ij} = \p x_i / \p X_j$ and $L_{ij} = \p v_i / \p x_j = \dot{F}_{ik} F^{-1}_{kj}$, respectively, are well defined at each point. In addition, the deformation is required to satisfy the impenetrability condition $J \equiv \det \bfF > 0$.


Following Lee (1969), it is further assumed that, at any given point $\bfX$ in $\Omega_0$, the tensor $\bfF$ may be decomposed into a plastic part $\bfF^p$ and an elastic part $\bfF^e$ as follows
%
\begin{equation}
	\bfF = \bfF^e \bfF^p,
	\label{FeFp}
\end{equation}
%
where both mappings $\bfF^p$ and $\bfF^e$ are taken to be invertible and to have positive determinants, i.e., $J^p \equiv \det \bfF^p > 0$ and $J^e \equiv \det \bfF^e > 0$.
Note that, the decomposition (\ref{FeFp}) introduces a local intermediate configuration\footnote{Equation (\ref{FeFp}) defines the intermediate configuration only up to a rigid body rotation. This ambiguity does not affect the formulation of the constitutive equations for the isotropic materials under consideration in this work. Detailed discussions concerning the proper choice of this configuration for the case of anisotropic materials can be found in the work by \cite{PAB1993} and in references therein.} which may be regarded at the same time as the deformed state for the plastic part and as the reference state for the elastic part of the deformation. 
As detailed further below, the constitutive equations and symmetries for both the elastic and the plastic part of the material behavior may be conveniently stated in the intermediate configuration. 


Elastic and plastic strain measures may thus be defined in terms of $\bfF^e$ and $\bfF^p$, respectively. In this work, we will only make use of the Green elastic strain tensor
%
\begin{equation}
	\bfE^e = \frac{1}{2} \left( \bfC^e - \bfdel \right),
	\label{Ee}
\end{equation}
%
where $\bfC^e =  \bfF^{e T} \bfF^e$ is the elastic right Cauchy-Green deformation tensor and $\bfdel$ is the second-order identity tensor. 
%

Taking into account (\ref{FeFp}), the velocity gradient tensor $\bfL = \dot{\bfF} \bfF^{-1}$ takes the form
%
\begin{equation}
	\dot{\bfF}^e \bfF^{e-1} + \bfF^e \bfL^i  \bfF^{e-1}, \quad \quad 
	\bfL^i = \dot{\bfF}^p \bfF^{p-1},
	\label{L2} 
\end{equation}
%
where $\bfL^i$ is the velocity gradient in the intermediate configuration. The tensors $\bfL$ and $\bfL^i$ may be decomposed into the deformation rate tensors
%
\begin{equation}
	\bfD = \bfL_s \equiv \bfD^e + \bfD^p, \quad\quad 
	\bfD^e = \left( \dot{\bfF}^e \bfF^{e-1} \right)_s, \quad \quad
	\bfD^p = \left( \bfF^e \bfL^i \bfF^{e-1} \right)_s, 
	\quad \quad
	\bfD^i = \bfL^i_s,  
	\label{D}
\end{equation}
%
and the spin tensors 
%
\begin{equation}
	\bfW = \bfL_a \equiv \bfW^e + \bfW^p, \quad \quad 
	\bfW^e = \left( \dot{\bfF}^e \bfF^{e-1} \right)_a, \quad \quad
	\bfW^p = \left( \bfF^e \bfL^i \bfF^{e-1} \right)_a, 
	\quad \quad
	\bfW^i = \bfL^i_a,  
	\label{W}
\end{equation}
%
where the subscripts ``s'' and ``a'' indicate respectively the symmetric and anti-symmetric part of the second-order tensor to which they are attached. 



\subsection*{Stress power}
\label{SP}

It follows from the above definitions that the stress power $\mathcal{P}$ per unit volume of intermediate configuration may be decomposed accordingly into an elastic part $\mathcal{P}^e$ and a plastic part $\mathcal{P}^p$ as follows
%
\begin{equation}
	\mathcal{P} = \bftau \cdot \bfD \equiv \mathcal{P}^e + \mathcal{P}^p, \quad\quad  \mathcal{P}^e = \bfS \cdot \dot{\bfE}^e, \quad\quad  \mathcal{P}^p = \bfSig \cdot \bfL^i,
	\label{StressPower}
\end{equation}
%
where we have introduced the stress measures 
%
\begin{equation}
	\bftau = J^e \bfsig, \quad\quad
	\bfS = \bfF^{e-1} \bftau \bfF^{e -T}, \quad\quad \bfSig = \bfF^{e T} \bftau \bfF^{e -T},
	\label{StressTensors}
\end{equation}
%
with $\bfsig$ denoting the Cauchy stress tensor. The tensors $\bftau$, $\bfS$, and $\bfSig$ in (\ref{StressTensors}) are commonly referred to as the (elastic) Kirchhoff, the second Piola-Kirchhoff, and the Mandel stress, respectively. The Cauchy stress $\bfsig$ is assumed to be symmetric, so that the tensors $\bftau$ and $\bfS$ are also symmetric, but $\bfSig$ is not symmetric, in general. 


In this work, we focus our considerations on materials that are elastically isotropic with respect to the intermediate configuration. For this special class of materials, the Mandel stress tensor $\bfSig$ is also symmetric\footnote{This fact follows easily from $(\ref{StressTensors})_3$, which for this special case reduces to $\bfSig = \bfR_e^T \bftau \bfR_e = \bfSig^T$, where $\bfR_e$ is the rotation tensor from the polar decomposition of $\bfF^e$} and, therefore, the associated plastic stress power $(\ref{StressPower})_3$ reduces to
%
\begin{equation}
	\mathcal{P}^p = \bfSig \cdot \bfD^i.
	\label{PpIso}
\end{equation}
%
In addition, we restrict our attention on plastically incompressible materials, for which, taking into account the constraint $J^p = 1$, it follows that $J = J^e$ and that the total stress power $(\ref{StressPower})_1$ may also be written in the form
%
\begin{equation}
	\mathcal{P} = \bfP \cdot \dot{\bfF}, 
	\label{StressPowerRef}
\end{equation}
%
where 
%
\begin{equation}
	\bfP = \bftau \bfF^{-T} = J \bfsig \bfF^{-T}, 
	\label{FirstPK}
\end{equation}
%
is the first Piola-Kirchhoff stress tensor.


In the sequel, assuming that $(\ref{PpIso})$ and $(\ref{StressPowerRef})$ hold, we define the elastic and plastic part of the material behavior in the intermediate configuration. In particular, we first establish appropriate relations between the conjugate variables $(\bfS, \bfE^e)$ and $(\bfSig, \bfD^i)$, and then we combine these relations to obtain the  corresponding rate form of the elastoplastic equation for the conjugate pair $(\bfP, \bfF)$.


\subsection*{Elasticity}
\label{Elasticity}

The elastic properties of the material are assumed to be given in terms of an isotropic strain-energy density function such that $\mathcal{P}^e = \dot{\Psi}$ and, therefore,
%
\begin{equation}
	\bfS = \frac{\p \Psi}{\p \bfE^e}.
	\label{Sx}
\end{equation}
%
The above constitutive equation may also be written in the following rate %(or incremental) 
form 
%
\begin{equation}
	\dot{\bfS} = \bsC_e \dot{\bfE}^e, \quad\quad \bsC_e =\frac{\p^2 \Psi}{\p \bfE^e \p \bfE^e}.
	\label{Sxdot}
\end{equation}
% 
Making use of $(\ref{StressTensors})_2$ and $(\ref{Sxdot})$, it is straightforward to show that 
%
\begin{equation}
	\bftaut = \bsL_e \bfD^e, \quad\quad 
	\left( \bsL_e \right)_{ijkl} = F^e_{ip} F^e_{jq} F^e_{kr} F^e_{ls} \left( \bsC_e \right)_{pqrs} +
	\frac{1}{2} \left( \tau_{ik} \delta_{jl} + \tau_{il} \delta_{jk} + \delta_{ik} \tau_{jl} + \delta_{il} \tau_{jk}  \right),
	\label{taut}
\end{equation}
%
where we have introduced the notation $\bftaut = \dot{\bftau} + \bftau \bfW^e - \bfW^e \bftau$. Note that, the fourth-order modulus tensors $\bsL_e$ and $\bsC_e$ in (\ref{taut}) and (\ref{Sxdot}) possess both the major and the minor symmetries. 



\subsection*{Plasticity}
\label{Plasticity}

The plastic part of the material behavior, which is also assumed to be isotropic with respect to the intermediate configuration, is defined in terms of the following von Mises yield criterion with isotropic strain hardening
%
\begin{equation}
	\Phi (\bfSig, \eps^p) = \Sigma_{eq} - \Sigma_{y} (\eps^p) = 0, \quad\quad 
	\Sigma_{eq} = \sqrt{\frac{3}{2} \bfSig^{d} \cdot \bfSig^{d}},
	\label{YC}
\end{equation}
%
where $\bfSig^{d}$ is the deviatoric part of the Mandel stress tensor $\bfSig$ and $\Sigma_{y}$ is the associated yield stress, which is given as a function of the equivalent plastic strain $\eps^p$, to be determined further below. 


The purely plastic stretching tensor $\bfD^i$ in the intermediate configuration is determined in terms of its conjugate stress tensor $\bfSig$ (see equation (\ref{PpIso})) by the associative flow rule  
%
\begin{equation}
	\bfD^i = \dot{\Lambda} \bfM^i, \quad\quad \bfM^i = \frac{\p \Phi}{\p \bfSig} = \frac{3}{2 \Sigma_{eq}} \bfSig^{d},
	\label{Di}
\end{equation}
%
where the plastic multiplier $\dot{\Lambda} \ge 0$ is obtained from the consistency condition, as discussed further below. 
Taking into account the assumed isotropic plastic behavior, it follows that (see, e.g., \cite{PAB1993})
%
\begin{equation}
	\bfW^i = \bfzero.
	\label{Wi}
\end{equation}
%
Hence, the deformation gradient in the intermediate configuration $\bfL^i = \dot{\bfF}^p \bfF^{p-1} = \bfD^i$ is symmetric. 

Given $(\ref{Di})$ and $(\ref{Wi})$, the plastic stretching tensor $(\ref{D})_3$ in the current configuration takes the form
%
\begin{equation}
	\bfD^p = \dot{\Lambda} \bfM^p, \quad\quad \bfM^p = \left( \bfF^e \bfM^i \bfF^{e-1} \right)_s.
	\label{Dp}
\end{equation}
%
In addition, it follows from the representation theorems for isotropic functions and the elastic isotropy of the material that $\bfW^p = \bfzero$. Therefore, $\bfW = \bfW^e$ and the tensor $\bfF^e \bfL^i \bfF^{e-1} = \bfF^e \bfD^i \bfF^{e-1} = \dot{\Lambda} \bfF^e \bfM^i \bfF^{e-1}$ is symmetric.



The equivalent plastic strain $\eps^p$ is taken to be plastic-work conjugate to the equivalent stress $\Sigma_{eq}$, so that
%
\begin{equation}
	\mathcal{P}^p = \bfSig \cdot \bfD^i = \Sigma_{eq} \dot{\eps}^p.
	\label{PpIso2}
\end{equation}
%
It follows that 
%
\begin{equation}
	\dot{\eps}^p = \dot{\Lambda},
	\label{epdot}
\end{equation}
%
which constitutes the evolution equation for $\eps^p$. 


Given the yield condition $(\ref{YC})$ and the above evolution equation $(\ref{epdot})$, the consistence condition $\dot{\Phi} = 0$ takes the form
%
\begin{equation}
	\bfM^i \cdot \dot{\bfSig} - \dot{\Lambda} h = 0, \quad\quad h = \frac{d \Sigma_y}{d \eps^p}.
	\label{CC}
\end{equation}
%
Taking the time derivative of $(\ref{StressTensors})_3$ with respect to time, and making use of the result $(\ref{taut})$, it follows that 
%
\begin{equation}
	\dot{\bfSig} = \bfF^{e T} \left[ \left( \bsL_e + \bsT \right) \bfD^e \right] \bfF^{e -T},
	\label{Sigmadot}
\end{equation}
%
where
%
\begin{equation}
	\scT_{ijkl} = \frac{1}{2} \left( -\tau_{ik} \delta_{jl} - \tau_{il} \delta_{jk} + \delta_{ik} \tau_{jl} + \delta_{il} \tau_{jk} \right).
	\label{T}
\end{equation}
%
Note that the tensor $\bsT$ is anti-symmetric with respect to the first and symmetric with respect to the second pair of indexes.
Substituting expression $(\ref{Sigmadot})$ in the consistency condition $(\ref{CC})$, and making use of the fact that $\bfD^e = \bfD - \bfD^p$, with $\bfD^p$ given by $(\ref{Dp})$, 
it can be shown that 
%
\begin{equation}
	\dot{\Lambda} = \bfr \cdot \bfD,
	\label{ldot}
\end{equation}
%
where
%
\begin{equation}
	\bfr = \frac{1}{L} \left( \bfF^e  \bfM^i \bfF^{e-1} \right) \left( \bsL_e + \bsT \right), \quad\quad  
	L= \left( \bfF^e  \bfM^i \bfF^{e-1} \right) \cdot \left( \bsL_e + \bsT \right) \bfM^p + h.
	\label{rL}
\end{equation}
%
Given that the tensor $\bfF^e  \bfM^i \bfF^{e-1} = \bfM^p$ is symmetric and $\bsT$ is antisymmetric with respect to the first pair of indexes, it follows that $\left( \bfF^e  \bfM^i \bfF^{e-1} \right) \bsT = \bfzero$. Thus, equation $(\ref{ldot})$, with $(\ref{rL})$, simplifies to 
%
\begin{equation}
	\dot{\Lambda} = \frac{1}{L} \bfM^p \cdot \bsL_e \bfD, \quad\quad  
	L= \bfM^p \cdot \bsL_e \bfM^p + h.
	\label{ldot2}
\end{equation}
%



\subsection*{Incremental constitutive equations}
\label{IncrementalEqs}

Taking into account the fact that $\bfD^e = \bfD - \bfD^p$, as well as equation $(\ref{Dp})$ for $\bfD^p$, with $\dot{\Lambda}$ given by $(\ref{ldot2})$, the rate equation $(\ref{taut})$ may be recast in the form
%
\begin{equation}
	\bftauj = \bsL \bfD, \quad\quad 
	\bsL = \bsL_{e} -  \frac{u(\dot{\Lambda})}{L} \bsL_e \bfM^p \otimes \bfM^p \bsL_e
	\label{tauj}
\end{equation}
%
where $\bftauj = \dot{\bftau}- \bfW \bftau + \bftau \bfW $ is the Jaumann derivative of $\bftau$ and $u(\dot{\Lambda})$ is the unit step function; recall that $u(\dot{\Lambda})=1$ if $\dot{\Lambda} > 0$ and $u(\dot{\Lambda})=0$ otherwise. Note that, in the context of $(\ref{tauj})$, use has also been made of the fact that $\bfW=\bfW^e$ for the isotropic materials under consideration, which in turn implies that $\bftaut = \bftauj$. 
%
Note also that, the modulus tensor $\bsL$ in  $(\ref{tauj})_2$ has both the major and the minor symmetries.

Differentiating equation $(\ref{StressPowerRef})_2$ with respect to time and making use of the constitutive relation $(\ref{tauj})$, it is straightforward to show that
%
\begin{equation}
	\dot{\bfP} = \bmL \, \dot{\bfF}, \quad\quad 
	\mathcal{L}_{ijkl} = \left[\mathscr{L}_{ipkq} +  
	\frac{1}{2} \left( \delta_{ik} \tau_{pq} - \delta_{iq} \tau_{kp}  -
	\delta_{pq} \tau_{ik}  - \delta_{kp} \tau_{iq} \right) \right] F^{-1}_{jp} F^{-1}_{lq}.
	\label{Sdot}
\end{equation}
%
It is emphasized that the elastoplastic modulus tensor $\bmL$ in $(\ref{Sdot})$ depends on the current state of the material, as defined by the variables $\bfF^p$, $\bfF^e$, and $\eps^p$, as well as on the loading increment (through its dependence on $\dot{\Lambda}$). Note that, the modulus tensor $\bmL$ has the major symmetry, but it does not have the minor symmetries. For purely elastic increments, expression $(\ref{Sdot})_2$ takes the form 
%
\begin{equation}
	\mathcal{L}_{ijkl} = \left[ F^e_{ip} F^e_{kr} (\bsC_{e})_{pqrs} + \delta_{ik} S_{qs} \right] (\bfF^{p-1})_{jq} (\bfF^{p-1})_{ls},
	\label{LepEl}
\end{equation}
%
where we recall that the tensors $\bfS$ and $\bsC_{e}$ are respectively given by $(\ref{Sx})$ and $(\ref{Sxdot})_2$ in terms of the Green elastic strain tensor $\bfE^e$. For the special case of purely elastic deformations, i.e., for $\bfF = \bfF^e$, expression $(\ref{LepEl})$ reduces to
%
\begin{equation}
	\mathcal{L}_{ijkl} = F^e_{ip}  F^e_{kr}  (\bsC_{e})_{pjrl} + \delta_{ik} S_{jl} = \frac{\p \psi}{\p \bfF^e \p \bfF^e},
	\label{LeEl}
\end{equation}
%
as it should.

\subsection*{Numerical integration of the incremental constitutive equations}
\label{NI} 



For completeness, an algorithm for the numerical integration of the elastoplastic constitutive equations of this Appendix is presented next. 



Let $\Delta t = t_{n+1} - t_n$, with $n=0, 1, 2,  ...$, be the generic time increment
during an arbitrary homogeneous deformation history, prescribed by the deformation gradient tensor $\bfF = \bfF (t)$. Given the values of the variables $\bfF^e$, $\bfF^p$ and $\eps^p$ at time $t_n$, as well as the value of $\bfF$ at time $t_{n+1}$, the prime goal is to find the values of $\bfF^e$, $\bfF^p$ and $\eps^p$ at $t_{n+1}$. To this end, note first that, since $\bfD^i = \dot{\bfF}^p \bfF^{p-1}$, the normality rule (\ref{Di}) may be rewritten in the form 
%
\begin{equation}
	\dot{\bfF}^p = \dot{\Lambda} \bfM^i \bfF^p
	\label{Fpdot}
\end{equation}
%
Assuming that the direction of the plastic flow $\bfM^i$ is constant and equal to $\bfM_{i} (t_n)$ within the time increment $\Delta t$, and integrating the ODE (\ref{Fpdot}) over $\Delta t$, we obtain the result
%
\begin{equation}
	\bfF^{p-1}(t_{n+1}) =
	\bfF^{p-1}(t_{n}) \left[\bfdel -  \Delta \Lambda \bfM_{i}(t_{n}) + \frac{1}{2} \Delta \Lambda^2 \bfM_{i}^2(t_{n}) +  O\left( \Delta \Lambda^3 \bfM_{i}^3(t_{n}) \right)  \right]
	%\nn
	\label{Fpnp1}
\end{equation}
%
which, truncated to second-order in $\Delta \Lambda$, may be used to compute $\bfF_{p}(t_{n+1})$ in terms of $\Delta \Lambda$. Given this result, $\bfF^e(t_{n+1})$ may also be obtained in terms  of $\Delta \Lambda$ from the expression
%
\begin{equation}
	\bfF^e(t_{n+1}) = \bfF(t_{n+1}) \bfF^{p-1}(t_{n+1}).
	%\nn
	\label{Fenp1}
\end{equation}
%
In addition, integrating the evolution equation (\ref{epdot}), we find that 
%
\begin{equation}
	\eps^p(t_{n+1}) = \eps^p(t_{n}) + \Delta \Lambda.
	%\nn
	\label{epnp1}
\end{equation}
%
Hence, the unknown variables $\bfF^p(t_{n+1})$, $\bfF^e(t_{n+1})$, and $\eps^p(t_{n+1})$ may be readily determined from (\ref{Fpnp1}), (\ref{Fenp1}), and (\ref{epnp1}), respectively, in terms of $\Delta \Lambda$.



In order to find the principal unknown $\Delta \Lambda$, we assume first that the deformations within the increment $\Delta t$ are purely elastic, so that $\Delta \Lambda = 0$, and compute the variables
%
%
\begin{equation}
	\bfC^e(t_{n+1}) = \bfF^{e T}(t_{n+1}) \bfF^e(t_{n+1}), \quad\quad
	\bfE^e(t_{n+1}) = \frac{1}{2} \left[ \bfC^e(t_{n+1}) - \bfdel \right],
\end{equation}
%
%
\begin{equation}
	\bfS(t_{n+1}) = \frac{\p \Psi}{\p \bfE^e} \left[ \bfE^e( t_{n+1}) \right], \quad\quad
	\bfSig( t_{n+1}) = \bfC^e(t_{n+1}) \bfS(t_{n+1}), \quad\quad
	\Sigma_{eq} \left[\bfSig( t_{n+1})\right] = \sqrt{\frac{3}{2} \bfSig^{d}( t_{n+1}) \cdot \bfSig^{d}(t_{n+1})},
	%\nn
	\label{Snp1}
\end{equation}
%
%
\begin{equation}
	\Phi \left[\bfSig( t_{n+1}), \eps^p( t_{n})\right] = \Sigma_{eq} \left[\bfSig( t_{n+1})\right] - \Sigma_{y} \left[\eps^p( t_{n})\right].
	%\nn
	%\label{YC}
\end{equation}
%
If $\Phi \left[\bfSig( t_{n+1}), \eps^p( t_{n})\right] < 0$, the deformations within $\Delta t$ are indeed purely elastic and the unknown variables at the end of the increment are $\bfF^p(t_{n+1}) = \bfF^p(t_{n})$, $\bfF^e(t_{n+1}) = \bfF(t_{n+1}) \bfF^{p-1}(t_{n})$, and $\eps^p(t_{n+1}) = \eps^p(t_{n})$. If, on the other hand, $\Phi \left[\bfSig( t_{n+1}), \eps^p( t_{n})\right] \ge 0$ the principal unknown $\Delta \Lambda$ is obtained by solving the yield condition at the end of the increment: 
%
\begin{equation}
	\Phi \left[\bfSig( t_{n+1}), \eps^p( t_{n+1})\right] = \Sigma_{eq} \left[\bfSig( t_{n+1})\right] - \Sigma_{y} \left[\eps^p( t_{n+1})\right] = 0,
	%\nn
	\label{YCnp1}
\end{equation}
%
where we recall that the variables $\bfSig( t_{n+1})$ and $\eps^p( t_{n+1})$ are determined in term of $\Delta \Lambda$ by means of the expressions (\ref{Fpnp1})-(\ref{Snp1}). Equation (\ref{YCnp1}) is nonlinear and must be solved numerically for $\Delta \Lambda$, e.g., by means of Newton's method.
%
Given $\bfF( t_{n+1})$, $\bfF^e( t_{n+1})$, and $\bfSig( t_{n+1})$, the stress tensors $\bftau$, $\bfsig$, and $\bfP$ may be determined at time $t_{n+1}$ by making use of the equations $(\ref{StressTensors})_3$, $(\ref{StressTensors})_1$, and $(\ref{FirstPK})$ respectively.


