\subsection{Composition: General case}
\label{sec:general-case}

Now, we prove the general case of composition of pebble transducers.

\begin{theorem}\label{thm:composition-general-case}
  Let $\trans=(Q,\Sigma,\delta,n,q_i,q_f,\Gamma,\mu)$ be a \emph{reversible} $n$-pebble
  transducer (possibly with equality tests) computing a function
  $f\colon\Sigma^{*}\to\Gamma^{*}$.
%   
  Let $\trans'=(Q',\Gamma,\delta',m,q'_i,q'_f,\Delta,\mu')$ be a \emph{deterministic}
  $m$-pebble transducer computing a function $g\colon\Gamma^{*}\to\Delta^{*}$.
% 
  Let $r=(n+1)(m+1)-1$.
  We can construct a \emph{deterministic} $r$-pebble transducer
  $\trans''=(Q'',\Sigma,\delta'',r,q''_i,q''_f,\Delta,\mu'')$ \emph{with equality tests}
  computing the composition $g\circ f\colon\Sigma^{*}\to\Delta^{*}$.
  The number of states of $\trans''$ is at most $\mathcal{O}(|Q|^{m+2}\cdot|Q'|\cdot(n+1)^{m+3})$.
%   
  Moreover, if $\trans'$ is \emph{reversible} then so is $\trans''$.
\end{theorem}

To simplify the construction, we first show that we may restrict to reversible pebble 
transducers that do not move their head when dropping or lifting a pebble.

\begin{lemma}\label{lem:drop-lift-move}
  For each reversible $n$-pebble transducer
  $\trans=(Q,\Sigma,\delta,n,q_i,q_f,\Gamma,\mu)$, we can construct a reversible
  $n$-pebble transducer $\trans'=(Q',\Sigma,\delta',n,q'_i,q'_f,\Gamma,\mu')$ with
  $|Q'|\leq 3|Q|$, computing the same function, and such that every transition in $\trans'$ 
  which moves the head has operation $\nop$. 
\end{lemma}

\begin{proof}
  Let $Q_\op=Q\times \{\drop{},\lift{} \}$. We let 
  $Q'=Q\cup Q_\op$, $q'_{i}=q_{i}$, $q'_{f}=q_{f}$, $Q'_{0}=Q_{0}\cup Q_\op$, 
  $Q'_{+1}=Q_{+1}$ and $Q'_{-1}=Q_{-1}$. We define now $\delta'$ and $\mu'$.
  Each transition $t=(q,a,\varphi,\nop,s)$ of $\trans$ also appears in $\trans'$,
  and for each transition $t=(q,a,\varphi,\op,s)$ of $\trans$ where $\op\neq\nop$, we
  define the following two transitions of $\trans'$:
  \begin{align*}
    t' &= (q,a,\varphi,\op,(q,\op)) \\
    t'' &= ((q,\op),\op(\varphi)\wedge\overline{\reverse{\op}},\nop,s)
  \end{align*}
  with output $\mu'(t')=\mu(t)$ and $\mu'(t'')=\varepsilon$.
 Note that we abuse notation as we forget the index of the action $\op$ in the state $(q,\op)$.
  We claim that $\trans'$ is reversible (see~\cref{claim:drop-lift-move:rev} below).

  Finally, it is easy to see that there is a one-to-one correspondence between the 
  accepting runs of $\trans$ and the accepting runs of $\trans'$, moreover this 
  correspondence preserves the output string produced. Hence, $\sem{\trans}=\sem{\trans'}$.


\begin{claim}\label{claim:drop-lift-move:rev}
	Transducer \( \trans' \) from \cref{lem:drop-lift-move} is reversible.
\end{claim}

\begin{claimproof}
	We call $t_i$ a transition that appears in both $\trans$ and $\trans'$ (i.e. a transition whose action is $\nop$).
	For $i\in\{1,2\}$, let $t'_{i}$ and $t''_{i}$ be the transitions constructed from 
	$t_{i}=(q,a,\varphi_{i},\op_{i},s_{i})$. 

	First, let us consider the case where two transitions are enabled at $C=(q,\pebbles,\head)$ for $\trans'$. Then they are either $t_i$ or $t'_i$ transitions.
	If $t'_{i}$ is enabled at $C=(q,\pebbles,\head)$ then $t_{i}$ is enabled at $C$ for $\trans$.
	Hence, in both cases we obtain $t_{1}$ and $t_{2}$ that are enabled at $C$ for $\trans$. By determinism of $\trans$ we get $t_{1}=t_{2}$. If $\op_i=\nop$ then $t_{1}=t_{2}$ in $\trans'$, or $\op_i\neq\op$ and we have $t'_{1}=t'_{2}$.

		Second, if two transitions $t'_{i}$ are reverse-enabled at $C'=((q,\op),\pebbles',\head)$
		then there are transitions $t_i=(q,a,\varphi_i,\op_i,s_i)$ in $\delta$ that are enabled at
		$C_i=(q,\reverse{\op_i}(\pebbles',\head),\head)$.
		Remark that given a pebble stack, the only $\drop{}$ action that can be reverse-enabled is
		$\drop{j}$ where $j$ is the size of the pebble stack.  Similarly, the only possible
		$\lift{j}$ action is when $j$ is the size of the pebble stack plus one.
		Then as the transitions $t'_{i}$ are reverse-enabled at $(q,\op)$, by construction of
		$\trans'$ the actions $\op_i$ of the $t_{i}$ have the same index.
		This means that $\reverse{\op_1}(\pebbles',\head)=\reverse{\op_2}(\pebbles',\head)$ and
		that $C_1=C_2$ and by determinism of $\trans$, $t_1=t_2$ which means $t'_1=t'_2$.

	Third, assume that $t''_{i}$ is enabled at $C'=((q,\op),\pebbles',\head)$.
	We claim that $t_{i}$ is enabled at $C_i=(q,\reverse{\op_i}(\pebbles',\head),\head)$.
	Indeed, let $\pebbles^{i}=\reverse{\op_{i}}(\pebbles',\head)$, which is well defined since 
	$\pebbles',\head\models\overline{\reverse{\op_{i}}}$. 
	We have $\pebbles'=\op_{i}(\pebbles^{i},\head)$ and using 
	$\pebbles',\head\models\op_{i}(\varphi_{i})$ we get $\pebbles^{i},\head\models\varphi_{i}$.
	Therefore $(q,\pebbles^{i},\head)\xra{t_{i}}(s,\pebbles',\head+s)$. 
	Thanks to the previous remark, the actions $\op_i$ are the same and hence $\pebbles^{i}$
	are equals.
	By determinism of $\trans$, we get that $t_1=t_2$ and hence $t''_1=t''_2$.

	For the last case, assume that two transitions are reverse-enabled at 
	$C'=(s,\pebbles',\head')$. 
	If both transitions also appear in $\trans$ then they are equal by reverse-determinism of $\trans$.
	If a transition (or both) is a $t''_{i}$ transition, 
	let $t_{i}=(q_{i},a,\varphi_{i},\op_{i},s)$. 
	We claim that $t_{i}$ is reverse-enabled at $C'$.
	Let $\head=\head'-s$ and
	$\pebbles^{i}=\reverse{\op_{i}}(\pebbles',\head)$, we can easily check that
	$(q,\pebbles^{i},\head)\xra{t_{i}}(s,\pebbles',\head+s)$.
	We get that the transition $t_i$ is reverse-enabled at $C'$ 
	and we conclude by reverse-determinism of $\trans$.
\end{claimproof}


\end{proof}


The rest of the section is devoted to the proof of \cref{thm:composition-general-case}.

As in \cref{sec:simple-case}, we assume that transducer $\trans$ outputs at most one letter
on each transition, and that it writes $\lrend v$ with $v\in\Gamma^{*}$ when running on
$\lrend u$ with $u\in\Sigma^{*}$.  Using \cref{lem:drop-lift-move}, we also assume that
transitions $t'=(q',a',\varphi',\op',s')$ of $\trans'$ do not both drop/lift a pebble and
move the head: if $\op'\neq\nop$ then $s'\in Q'_{0}$.

We fix $u\in\dom{f}\subseteq\Sigma^{*}$ and $v=f(u)\in\Gamma^{*}$.  
We consider the accepting run of $\trans$ on $\lrend u$ producing $\lrend v$:
\begin{equation}
  C_{0}\xra{t_{0}}C_{1}\xra{t_{1}}C_{2}\xra{t_{2}}\cdots C_{N}\xra{t_{N}}C_{N+1} 
  \label{eq:run-T-u}
\end{equation}
where $C_{\ell}=(q_{\ell},\pebbles_{\ell},\head_{\ell})$ 
are configurations and $t_{\ell}\in\delta$ are transitions of $\trans$.

As in \cref{sec:simple-case}, for each position $i\in\epos{v}$, we let $\enc{i}$ be
the index of the transition in the above run producing the letter at position $i$ in
$\lrend v$.
Again, the main idea is to encode a position $i\in\epos{v}$ by the configuration 
$C_{\enc{i}}$. Since $\trans'$ has pebbles, this encoding is used not only for the 
head $\head'$ of $\trans'$, but also for the pebbles dropped by $\trans'$.

Recall that the $\ell$-th configuration in \eqref{eq:run-T-u} is
$C_{\ell}=(q_{\ell},\pebbles_{\ell},\head_{\ell})$.
Consider a configuration $C'=(q',\pebbles',\head')$ of $\trans'$ on $\lrend v$. 
Let $k=|\pebbles'|$, $j_{i}=\enc{\pebbles'_{i}}$ for $1\leq i\leq k$, and $j=\enc{\head'}$. 
Let $[n+1]=\{1,\ldots,n+1\}$.
Define $\enc{C'}=C''=(q'',\pebbles'',\head'')$ where
\begin{align*}
  q'' &= ( q_{j},q',(q_{j_{i}})_{1\leq i\leq k},(1+|\pebbles_{j_{i}}|)_{1\leq i\leq k} )
  \in Q\times Q'\times Q^{k}\times[n+1]^{k} \subseteq Q''_{0} \\
  \pebbles'' &= \pebbles_{j_{1}}\head_{j_{1}} \cdots \pebbles_{j_{k}}\head_{j_{k}} \pebbles_{j} 
  \hspace{15mm}\text{and}\hspace{15mm}
  \head'' = \head_{j} \,.
\end{align*}


The set $Q''_{0}$ of $0$-states of $\trans''$ contains
$\bigcup_{k=0}^{m} Q\times Q'\times Q^{k}\times[n+1]^{k}$.
The initial and final states are 
$q''_{i}=(q_{i},q'_{i},(),())$ and $q''_{f}=(q_{i},q'_{f},(),())$ respectively.
It remains to define the other states in $Q''$, the transition function $\delta''$ and
the output function $\mu''$.

We explain below how a transition $C'\xra{t'}C'_{1}$ of $\trans'$ will be simulated in
$\trans''$ by a sequence of transitions of the form $\enc{C'}\xra{+}\enc{C'_{1}}$.

Consider a state $q''=(q,q',\overline{x},\overline{y})\in Q\times Q'\times 
Q^{k}\times[n+1]^{k}$ for some $0\leq k\leq m$, with 
$\overline{x}=(x_{i})_{1\leq i\leq k}$ and $\overline{y}=(y_{i})_{1\leq i\leq k}$.
Let $t=(q,a,\varphi,\op,s)$ be a transition of $\trans$ which produces an output letter
$a'=\mu(t)\in\Gamma$.  Consider a transition $t'=(q',a',\varphi',\op',s')$ of $\trans'$
which reads the output produced by $t$.  The goal is to synchronize the pair of
transitions $(t,t')$ as we did in \cref{sec:simple-case}.  We first explain how to write a
test $\xi$ checking whether both $t$ and $t'$ are ``enabled'' at a configuration
$C''=(q'',\pebbles'',\head)$ of $\trans''$.  This is intended to be used in particular
when $C''$ is of the form $\enc{C'}$ for some configuration $C'$ of $\trans'$.

We introduce some notation.
For each $0\leq\ell\leq k$, we let $d_\ell=y_{1}+\cdots+y_{\ell}$ which
can be recovered from the state $q''$ of $\trans''$.
Given an offset $d\geq0$ and a test $\varphi$ of $\trans$, we write 
$\varphi^{+d}$ the test obtained by adding $d$ to the pebble indices: 
$\pebble_{i}=\pebble_{j}$ is replaced with $\pebble_{i+d}=\pebble_{j+d}$
and $\head=\pebble_{j}$ is replaced with $\head=\pebble_{j+d}$.
Finally, let $\xi_{0}=(\pebble_{0}=\pebble_{0})\wedge\neg(\pebble_{n+1}=\pebble_{n+1})$
which will be used, shifted by some offset, to check the size of the pebble stack.

\begin{claim}\label{claim:xi}
  Let $C''=(q'',\pebbles'',\head)$ be a configuration of $\trans''$ with
  $q''=(q,q',\overline{x},\overline{y})$.  Let $\psi$ be a test of $\trans$ and $\psi'$ be
  a test of $\trans'$.
  \begin{enumerate}
    \item \label{item:0}  
    $\pebbles'',\head\models\xi_{0}^{+d_{k}}$ if and only if $d_{k}\leq|\pebbles''|\leq d_{k}+n$. 

    We assume below that we are in this case and we write $\pebbles''=
    \pebbles^{1}\head^{1} \cdots \pebbles^{k}\head^{k} \pebbles$ with 
    $|\pebbles^{\ell}\head^{\ell}|=y_{\ell}$ for $1\leq\ell\leq k$
    and $0\leq|\pebbles|\leq n$.

    \item \label{item:1}
    $\pebbles'',\head\models\psi^{+d_{k}}$ if and only if $\pebbles,\head\models\psi$.

    \item \label{item:2}
    We can construct a formula $\overline{\xi}(q'',\psi')$ such that,
    for all $\pebbles',\head'$ with $|\pebbles'|=k$ and
    (a) $\pebbles'_{i}=\pebbles'_{j}$ iff $x_{i}=x_{j}$, $\pebbles^{i}=\pebbles^{j}$ and
    $\head^{i}=\head^{j}$; and
    (b) $\head'=\pebbles'_{j}$ iff $q=x_{j}$, $\pebbles=\pebbles^{j}$ and 
    $\head=\head^{j}$, 
    we have $\pebbles'',\head\models\overline{\xi}(q'',\psi')$ 
    if and only if $\pebbles',\head'\models\psi'$.
  \end{enumerate}
\end{claim}

\begin{claimproof}
  \cref{item:0,item:1} are clear. For \cref{item:2} we let $\overline{\xi}(q'',\psi')$ be the 
  formula $\psi'$ in which we replace each atom of the form $\head'=\pebble'_{i}$ by
  \begin{itemize}
    \item  $\false$ if $i>k$ or $x_{i}\neq q$,

    \item  $\Big(\bigwedge_{\ell=1}^{y_{i}-1} \pebble_{\ell+d_{k}}=\pebble_{\ell+d_{i}-1} 
    \Big) \wedge (\head=\pebble_{d_{i}}) \wedge 
    \neg(\pebble_{y_{i}+d_{k}}=\pebble_{y_{i}+d_{k}})$ otherwise;
  \end{itemize}
  and each atom of the form $\pebble'_{i}=\pebble'_{j}$ by
  \begin{itemize}
    \item  $\false$ if $i>k$ or $j>k$ or $x_{i}\neq x_{j}$ or $y_{i}\neq y_{j}$,

    \item  $\bigwedge_{\ell=1}^{y_{i}} \pebble_{\ell+d_{i-1}}=\pebble_{\ell+d_{j}-1}$ 
    otherwise.
    \claimqedhere
  \end{itemize}
\end{claimproof}

Let $\xi=(\xi_{0}\wedge\varphi\wedge\overline{\op})^{+d_{k}}
\wedge\overline{\xi}(q'',\varphi'\wedge\overline{\op'})$.
From \cref{claim:xi}, assuming that $C''=\enc{C'}$, we see that 
$C''\models\xi$ if and only if $t$ is enabled at $C=(q,\pebbles,\head)$ and $t'$ is 
enabled at $C'=(q',\pebbles',\head')$.
We explain now how to synchronize the pair of transitions $(t,t')$ from state $q''$.
Given an offset $d\geq0$ and an operation $\op$ of $\trans$, we write $\op^{+d}$ the
operation shifted by $d$: $\drop{i}^{+d}=\drop{i+d}$, $\lift{i}^{+d}=\lift{i+d}$ and
$\nop^{+d}=\nop$.

\noindent\textbf{Case $\nop$:} 
We have $t'=(q',a',\varphi',\nop,s')$ with $s'\in Q'$.
We check whether the pair $(t,t')$ is enabled with $\xi$ and we implement the move 
induced by $s'$ of the head of $\trans'$ on $\# v$ as we did in \cref{sec:simple-case}.
To do so, we introduce the following transition with $\mu''(t'')=\mu'(t')$:
\begin{align}
  t''=(q,q',\overline{x},\overline{y}) & \xra{a,\xi,\op^{+d_{k}}}
  (\hat{s},s',\overline{x},\overline{y}) 
  &&\text{if } s'\in Q'_{+1}
  \tag{\textsf{gtr-a}}\label{eq:general-tr+}
  \\
  t''=(q,q',\overline{x},\overline{y}) & \xra{a,\xi,\nop} 
  (\hat{q},s',\overline{x},\overline{y}) 
  &&\text{if } s'\in Q'_{-1}
  \tag{\textsf{gtr-b}}\label{eq:general-tr-}
  \\
  t''=(q,q',\overline{x},\overline{y}) & \xra{a,\xi,\nop} 
  (q,s',\overline{x},\overline{y})
  &&\text{if } s'\in Q'_{0}
  \tag{\textsf{gtr-c}}\label{eq:general-tr0}
\end{align}
Here, $\widehat{Q}=\{\hat{q}\mid q\in Q\}$ is a disjoint copy of $Q$.
The polarity of a simulation state $(\hat{q},q',\overline{x},\overline{y})
\in\widehat{Q}\times(Q'_{-1}\cup Q'_{+1})\times Q^{k}\times[n+1]^{k}$ with $0\leq k\leq m$
is the product of the polarity of $q$ and the polarity of $q'$.
When in a simulation state $(\hat{q},q',\overline{x},\overline{y})$, we simulate 
$\trans$ forward or backward depending on the polarity of $q'$ using transitions 
producing $\varepsilon$ until we reach a transition producing a symbol from $\Gamma$.
For each transition $t=(q,a,\varphi,\op,s)$ of $\trans$ with $\mu(t)=\varepsilon$ we
introduce the following transition $t''$ in $\trans''$ with $\mu''(t'')=\varepsilon$:
\begin{align}
  t''=(\hat{q},q',\overline{x},\overline{y}) & \xra{a,\varphi^{+d_{k}},\op^{+d_{k}}} 
  (\hat{s},q',\overline{x},\overline{y}) &&\text{if } q'\in Q'_{+1}
  \tag{\textsf{gmv-a}}\label{eq:general-mv+}
  \\
  t''=(\hat{s},q',\overline{x},\overline{y}) & \xra{a,(\reverse{(\varphi,\op)})^{+d_{k}}} 
  (\hat{q},q',\overline{x},\overline{y}) &&\text{if } q'\in Q'_{-1}
  \tag{\textsf{gmv-b}}\label{eq:general-mv-}
\end{align}
and for each transition $t=(q,a,\varphi,\op,s)$ of $\trans$ with $\mu(t)\in\Gamma$ we
introduce the following transition $t''$ in $\trans''$ with $\mu''(t'')=\varepsilon$ in 
order to switch back from the simulation mode to the synchronization mode:
\begin{align}
  t''=(\hat{q},q',\overline{x},\overline{y}) & \xra{a,(\varphi\wedge\overline{\op})^{+d_{k}},\nop} 
  (q,q',\overline{x},\overline{y}) 
  &&\text{if } q'\in Q'_{+1}
  \tag{\textsf{gsw-a}}\label{eq:general-sw+}
  \\
  t''=(\hat{s},q',\overline{x},\overline{y}) & \xra{a,(\reverse{(\varphi,\op)})^{+d_{k}}}
  (q,q',\overline{x},\overline{y}) 
  &&\text{if } q'\in Q'_{-1}
  \tag{\textsf{gsw-b}}\label{eq:general-sw-}
\end{align}
As in the proof of \cref{thm:composition-simple-case}, we can show that $\trans''$ is 
reversible at simulation states of the form $(\hat{q},q',\overline{x},\overline{y})$.
We can also prove similarly the following analog of \cref{claim:simple-simulate}.

\begin{claim}\label{claim:genearl-simulate}
  Assuming that the operation of $t'$ is $\nop$, there is a transition of $\trans'$
  $C'=(q',\pebbles',\head')\xra{t'}C'_{1}=(s',\pebbles',\head'+s')$ on
  $\lrend v$ if and only if there is a nonempty run $\enc{C'}\xra{+}\enc{C'_{1}}$ of
  $\trans''$ on $\lrend u$ where intermediate states are simulation states.
\end{claim}

\noindent\textbf{Case $\lift{}$:} 
We have $t'=(q',a',\varphi',\lift{k'},s')$ with $1\leq k'\leq m$ and $s'\in Q'_{0}$ from
our assumption on $\trans'$ (\cref{lem:drop-lift-move}).
We still check that the pair $(t,t')$ is enabled with 
$\xi=(\xi_{0}\wedge\varphi\wedge\overline{\op})^{+d_{k}}
\wedge\overline{\xi}(q'',\varphi'\wedge\overline{\lift{k'}})$.
Thanks to $\overline{\xi}(q'',\overline{\lift{k'}})$, we get $k'=k$, $q=x_{k}$,
$\pebbles^{k}=\pebbles$ and $\head^{k}=\head$.
We use the lift-gadget given in \cref{fig:composition-lift} to pop the top $y_{k}$
pebbles, i.e., $\head^{k}\pebbles$ (in reverse order).
We enter and leave the lift-gadget with the following transitions where
$s''=(q,s',(x_{1},\ldots,x_{k-1}),(y_{1},\ldots,y_{k-1}))\in Q''_{0}$,
$\xi'=(\xi_{0}\wedge\varphi\wedge\overline{\op})^{+(d_{k}-y_{k})}
\wedge\overline{\xi}(s'',\op'(\varphi')\wedge\overline{\reverse{\op'}})$,
$\mu''(t''_{\mathsf{first}})=\mu'(t')$ and $\mu''(t''_{\mathsf{last}})=\varepsilon$:
\begin{align}
  t''_{\mathsf{first}} &= q'' \xra{a,\xi,\nop} (q'',-1)
  \tag{\textsf{lift-a}}\label{eq:general-lift-first}
  \\
  t''_{\mathsf{last}} &= (q'',0) \xra{a,\xi',\nop} s'' 
  \tag{\textsf{lift-b}}\label{eq:general-lift-last}
\end{align}

\begin{figure}[tbh]
  \centering
  \gusepicture{composition-lift}
  \caption{Simulation of $\lift{k}$. 
  The first state is
  $q''=(q,q',(x_{1},\ldots,x_{k}),(y_{1},\ldots,y_{k}))\in Q''_{0}$
  and $d_{k}=y_{1}+\cdots+y_{k}$.
  The internal states are of the from $(q'',-\ell)\in Q''_{+1}$ for $0\leq\ell\leq y_{k}$.
  The last state is $s''=(q,s',(x_{1},\ldots,x_{k-1}),(y_{1},\ldots,y_{k-1}))\in Q''_{0}$.
  The test on the first transition is $\xi=(\xi_{0}\wedge\varphi\wedge\overline{\op})^{+d_{k}}
  \wedge\overline{\xi}(q'',\varphi'\wedge\overline{\op'})$.
  The test on the last transition is 
  $\xi'=(\xi_{0}\wedge\varphi\wedge\overline{\op})^{+(d_{k}-y_{k})}
  \wedge\overline{\xi}(s'',\op'(\varphi')\wedge\overline{\reverse{\op'}})$.
  }
  \label{fig:composition-lift}
\end{figure}

The blue tests are added to ensure reverse determinism at the internal states.
Also, when the before last transition is taken we see $\pebble_{d_{k}}$.  Hence, the head
is on the same position at the beginning and at the end of the gadget.


\noindent\textbf{Case $\drop{}$:} The operation of transition $t'$ is 
$\op'=\drop{k'}$ ($1\leq k'\leq m$).
We still check that the pair $(t,t')$ is enabled with 
$\xi=(\xi_{0}\wedge\varphi\wedge\overline{\op})^{+d_{k}}
\wedge\overline{\xi}(q'',\varphi'\wedge\overline{\drop{k'}})$.
Thanks to $\overline{\xi}(q'',\overline{\drop{k'}})$, we get $k'=k+1$.
We use the drop-gadget given in \cref{fig:composition-drop} to push
$\head$ and then $\pebbles$ (in this order) on the pebble stack. 
We enter and leave the drop-gadget with the following transitions where
$1\leq z\leq n+1$,
$s''=(q,s',(x_{1},\ldots,x_{k},q),(y_{1},\ldots,y_{k},z))\in Q''_{0}$,
$\xi'=(\xi_{0}\wedge\varphi\wedge\overline{\op})^{+(d_{k}+z)}
\wedge\overline{\xi}(s'',\op'(\varphi')\wedge\overline{\reverse{\op'}})$,
$\mu''(t''_{\mathsf{first}})=\mu'(t')$ and $\mu''(t''_{\mathsf{last}})=\varepsilon$:
\begin{align}
  t''_{\mathsf{first}} &= q'' \xra{a,\xi,\drop{d_{k}+z}} (q'',z,1)
  \tag{\textsf{drop-a}}\label{eq:general-drop-first}
  \\
  t''_{\mathsf{last}} &= (q'',z,z) \xra{a,\xi',\nop} s'' 
  \tag{\textsf{drop-b}}\label{eq:general-drop-last}
\end{align}

\begin{figure}[tbh]
  \centering
  \gusepicture{composition-drop}
  \caption{Simulation of $\drop{k+1}$ with $z$ any number such that $1\leq z\leq n+1$. \\
  The first state is $q''=(q,q',(x_{1},\ldots,x_{k}),(y_{1},\ldots,y_{k}))\in Q''_{0}$ 
  and $d_{k}=y_{1}+\cdots+y_{k}$. 
  The internal states are of the from $(q'',z,\ell)\in Q''_{+1}$ for $1\leq\ell\leq z$.
  The last state is $s''=(q,s',(x_{1},\ldots,x_{k},q),(y_{1},\ldots,y_{k},z))\in Q''_{0}$.
  The test on the first transition is $\xi=(\xi_{0}\wedge\varphi\wedge\overline{\op})^{+d_{k}}
  \wedge\overline{\xi}(q'',\varphi'\wedge\overline{\op'})$.
  The test on the last transition is 
  $\xi'=(\xi_{0}\wedge\varphi\wedge\overline{\op})^{+(d_{k}+z)}
  \wedge\overline{\xi}(s'',\op'(\varphi')\wedge\overline{\reverse{\op'}})$.
  }
  \label{fig:composition-drop}
\end{figure}

On the first transition of the gadget, the test $\xi$ makes sure that the pebble stack is 
of the form $\pebbles''=\pebbles^{1}\head^{1} \cdots \pebbles^{k}\head^{k} \pebbles$ with 
$|\pebbles^{\ell}\head^{\ell}|=y_{\ell}$ for $1\leq\ell\leq k$ and $0\leq|\pebbles|\leq n$.
The operation $\drop{d_{k}+z}$ on the first transition is only possible if 
$z=|\pebbles|+1$ and it allows to determine the size of $\pebbles$.
% 
Since $\reverse{\op'}=\lift{k+1}$, the test $\xi'$ on the last transition contains 
$\overline{\xi}(s'',\overline{\lift{k+1}})$ which contains the test $\pebble_{d_{k}+z}$.
This test makes sure that at the end of the gadget, the head of $\trans''$ is on the same
position of the input word $\#u$ as it was at the beginning.
% 
The drop gadget is deterministic at the internal states. The blue tests are added
to make this gadget reverse deterministic at the internal states.


We conclude by proving that the construction is preserves determinism and reverse-determinism.

\begin{claim}\label{claim:general-det}
	The transducer $\trans''$ from \cref{thm:composition-general-case} is deterministic.
\end{claim}

\begin{claimproof}
	Consider two transitions $t''_{1}$ and $t''_{2}$ of $\trans''$ reading some letter
	$a\in\Sigma$ and which are both enabled at some configuration $C''$ of $\trans''$.

\noindent\textbf{Case 1:} $C''=(q'',\pebbles'',\head)$ with
	$q''=(q,q',\overline{x},\overline{y})\in Q\times Q'\times
	Q^{k}\times[n+1]^{k}\subseteq Q''_{0}$ and $0\leq k\leq m$.
	% 
	For $i\in\{1,2\}$, consider the transitions $t_{i}=(q,a,\varphi_{i},\op_{i},s_{i})$ and 
	$t'_{i}=(q',a'_{i},\varphi'_{i},\op'_{i},s'_{i})$ used to construct $t''_{i}$
	using one of (\cref{eq:general-tr+,eq:general-tr-,eq:general-tr0,eq:general-lift-first,eq:general-drop-first}).

	Let $\xi_{i}=(\xi_{0}\wedge\varphi_{i}\wedge\overline{\op_{i}})^{+d_{k}}
	\wedge\overline{\xi}(q'',\varphi'_{i}\wedge\overline{\op'_{i}})$ be the test of 
	$t''_{i}$. Since $\pebbles'',\head\models\xi_{0}^{+d_{k}}$ we may write
	$\pebbles''=\pebbles^{1}\head^{1} \cdots \pebbles^{k}\head^{k} \pebbles$ with 
	$|\pebbles^{\ell}\head^{\ell}|=y_{\ell}$ for $1\leq\ell\leq k$ and $0\leq|\pebbles|\leq n$.
	By \cref{claim:xi}, we get first 
	$\pebbles,\head\models\varphi_{i}\wedge\overline{\op_{i}}$ and we deduce that $t_{i}$ 
	is enabled at $C=(q,\pebbles,\head)$. It follows that $t_{1}=t_{2}$ by determinism of 
	$\trans$. Hence, $t'_{1}$ and $t'_{2}$ both read the same letter $a'=\mu(t_{1})$ and 
	start from the same state $q'$. Let $\pebbles',\head'$ be constructed as in 
	\cref{item:2} of \cref{claim:xi}. We get 
	$\pebbles',\head'\models\varphi'_{i}\wedge\overline{\op'_{i}}$ and we deduce that 
	$t'_{i}$ is enabled at $C'=(q',\pebbles',\head')$.  It follows that $t'_{1}=t'_{2}$ by
	determinism of $\trans'$. We conclude that $t''_{1}=t''_{2}$.

\noindent\textbf{Case 2:} $C''=(q'',\pebbles'',\head)$ with
	$q''\in \widehat{Q}\times Q'\times Q^{k}\times[n+1]^{k}$ and $0\leq k\leq m$.

	The proof is similar to the proof for the corresponding case in \cref{claim:simple-det}.

\noindent\textbf{Case 3:} Internal state of the lift-gadget:
	$C''=((q'',-\ell),\pebbles'',\head)$ with
	$q''=(q,q',\overline{x},\overline{y})\in Q\times Q'\times 
	Q^{k}\times[n+1]^{k}$, $1\leq k\leq m$ and $0\leq\ell\leq y_{k}$.

	If $\ell\neq 0$ there are only two transitions starting from state $(q'',-\ell)$, 
	the self-loop with test $\neg\pebble_{d_{k}+y_{k}-\ell}$ and operation $\nop$ and the
	transition with operation $\lift{d_{k}+y_{k}-\ell}$. These two cannot be simultaneously 
	enabled.

	Assume that $\ell=0$. 
	For $i\in\{1,2\}$, consider the transitions $t_{i}=(q,a,\varphi_{i},\op_{i},s_{i})$ and 
	$t'_{i}=(q',a'_{i},\varphi'_{i},\op'_{i},s'_{i})$ used to construct $t''_{i}$
	using \eqref{eq:general-lift-last}.
	Let $\xi'_{i}=(\xi_{0}\wedge\varphi_{i}\wedge\overline{\op_{i}})^{+(d_{k}-y_{k})}
	\wedge\overline{\xi}(s'',\op'_{i}(\varphi'_{i})\wedge\overline{\reverse{\op_{i}'}})$ be
	the test of $t''_{i}$.  
	Since $\pebbles'',\head\models\xi_{0}^{+(d_{k}-y_{k})}$ we may write
	$\pebbles''=\pebbles^{1}\head^{1} \cdots \pebbles^{k-1}\head^{k-1} \pebbles$ with 
	$|\pebbles^{\ell}\head^{\ell}|=y_{\ell}$ for $1\leq\ell<k$ and $0\leq|\pebbles|\leq n$.
	By \cref{claim:xi}, we get first 
	$\pebbles,\head\models\varphi_{i}\wedge\overline{\op_{i}}$ and we deduce that $t_{i}$ 
	is enabled at $C=(q,\pebbles,\head)$. It follows that $t_{1}=t_{2}$ by determinism of 
	$\trans$. Hence, $t'_{1}$ and $t'_{2}$ both read the same letter $a'=\mu(t_{1})$ and 
	start from the same state $q'$. Let $\pebbles',\head'$ be constructed from 
	$\pebbles'',\head$ as in \cref{item:2} of \cref{claim:xi}. 
	%   
	We get 
	$\pebbles',\head'\models\op'_{i}(\varphi'_{i})\wedge\overline{\reverse{\op_{i}'}}$.
	We deduce that $t'_{i}$ is enabled at $C'=(q',\reverse{\op_{i}'}(\pebbles',\head'),\head')$.  
	It follows that $t'_{1}=t'_{2}$ by determinism of $\trans'$. 
	We conclude that $t''_{1}=t''_{2}$.

\noindent\textbf{Case 4:} Internal state of the drop-gadget:\\
	$C''=((q'',z,\ell),\pebbles'',\head)$ with
	$q''=(q,q',\overline{x},\overline{y})\in Q\times Q'\times 
	Q^{k}\times[n+1]^{k}$, $0\leq k<m$, $1\leq z\leq n+1$ and $1\leq\ell\leq z$.

	If $\ell\neq z$ there are only two transitions starting from state $(q'',z,\ell)$, 
	the self-loop with test $\neg\pebble_{d_{k}+\ell}$ and the transition with test
	$\pebble_{d_{k}+\ell}$.  These two cannot be simultaneously enabled.

	Assume that $\ell=z$. 
	As before, the self-loop with test $\neg\pebble_{d_{k}+z}$ cannot be simultaneously 
	enabled with a transition $((q'',z,z),a,\xi',\nop,s'')$ since the test $\xi'$ 
	checks $\pebble_{d_{k}+z}$ inside $\overline{\xi}(s'',\overline{\lift{k+1}})$.

	Assume now that $t''_{i}=((q'',z,z),a,\xi'_{i},\nop,s''_{i})$ for $i\in\{1,2\}$.
	%   
	Let $t_{i}=(q,a,\varphi_{i},\op_{i},s_{i})$ and
	$t'_{i}=(q',a'_{i},\varphi'_{i},\drop{k+1},s'_{i})$ 
	be the transitions used to construct $t''_{i}$ using \eqref{eq:general-drop-last}.

	The test on $t''_{i}$ is
	$\xi'_{i}=(\xi_{0}\wedge\varphi_{i}\wedge\overline{\op_{i}})^{+d_{k}+z}
	\wedge\overline{\xi}(s''_{i},\drop{k+1}(\varphi'_{i})\wedge\overline{\lift{k+1}})$.
	Since $\pebbles'',\head\models\xi_{0}^{+d_{k}+z}$ we may write
	$\pebbles''=\pebbles^{1}\head^{1} \cdots \pebbles^{k+1}\head^{k+1} \pebbles$ with 
	$|\pebbles^{\ell}\head^{\ell}|=y_{\ell}$ for $1\leq\ell\leq k$,
	$|\pebbles^{k+1}\head^{k+1}|=z$ and $0\leq|\pebbles|\leq n$.
	Since $\pebbles'',\head\models(\varphi_{i}\wedge\overline{\op_{i}})^{+d_{k}+z}$,
	we get $\pebbles,\head\models\varphi_{i}\wedge\overline{\op_{i}}$ by \cref{claim:xi}. 
	We deduce that $t_{1}$ and $t_{2}$ are both enabled at $C=(q,\pebbles,\head)$. 
	It follows that $t_{1}=t_{2}$ by determinism of $\trans$. 
	Hence, $t'_{1}$ and $t'_{2}$ both read the same letter $a'=\mu(t_{1})$ and 
	start from the same state $q'$.
	Let $\pebbles',\head'$ be constructed from $\pebbles'',\head$ as in 
	\cref{item:2} of \cref{claim:xi}.  Using $\pebbles'',\head\models
	\overline{\xi}(s''_{i},\drop{k+1}(\varphi'_{i})\wedge\overline{\lift{k+1}})$, we get
	$\pebbles',\head'\models\drop{k+1}(\varphi'_{i})\wedge\overline{\lift{k+1}}$.
	We deduce that $t'_{i}$ is enabled at $C'=(q',\lift{k+1}(\pebbles',\head'),\head')$.
	%   
	It follows that $t'_{1}=t'_{2}$ by determinism of $\trans'$.  We conclude that
	$t''_{1}=t''_{2}$.
\end{claimproof}

\begin{claim}\label{claim:general-rev-det}
	If $\trans'$ from \cref{thm:composition-general-case} is reverse-deterministic then $\trans''$ is reverse-deterministic.
\end{claim}

\begin{claimproof}
	Consider two transitions $t''_{1}$ and $t''_{2}$ of $\trans''$ reading some letter
	$a\in\Sigma$ and which are both reverse-enabled at some configuration $C''$ of $\trans''$.

\noindent\textbf{Case 1:} $C''=(s'',\pebbles'',\head)$ with
	$s''=(q,s',\overline{x},\overline{y})\in Q\times Q'\times
	Q^{k}\times[n+1]^{k}\subseteq Q''_{0}$ and $0\leq k\leq m$.
	If $s'\in Q'_{+1}\cup Q'_{-1}$ then both transitions $t''_{1}$ and $t''_{2}$ are 
	constructed from the same case \eqref{eq:general-sw+} or \eqref{eq:general-sw-} 
	respectively. We prove that $t''_{1}=t''_{2}$ as in the corresponding case of 
	\cref{claim:simple-rev-det}. We assume bolow that $s'\in Q'_{0}$.

	For $i\in\{1,2\}$, consider the transitions $t_{i}=(q,a,\varphi_{i},\op_{i},s_{i})$ and 
	$t'_{i}=(q'_{i},a'_{i},\varphi'_{i},\op'_{i},s')$ used to construct $t''_{i}$ using one 
	of (\cref{eq:general-tr0,eq:general-lift-last,eq:general-drop-last}). 
	Let $\xi'_{i}=(\xi_{0}\wedge\varphi_{i}\wedge\overline{\op_{i}})^{+d_{k}}
	\wedge\overline{\xi}(s'',\op'_{i}(\varphi'_{i})\wedge\overline{\reverse{\op_{i}'}})$ be
	the test of $t''_{i}$.  Notice that, if $t''_{i}$ is constructed from
	\eqref{eq:general-tr0} then $\op'_{i}=\nop$ and
	$\xi'_{i}=(\xi_{0}\wedge\varphi_{i}\wedge\overline{\op_{i}})^{+d_{k}}
	\wedge\overline{\xi}(s'',\varphi'_{i})=\xi_{i}$ since $\overline{\xi}(s'',\cdot)$ does
	not depend on the $Q'$ component of $s''$.
	Transition $t''_{i}$ is reverse-enabled at $C''$, its operation is $\nop$ and it does 
	not move the head, hence $\pebbles'',\head\models\xi'_{i}$. Therefore, 
	we may write
	$\pebbles''=\pebbles^{1}\head^{1} \cdots \pebbles^{k}\head^{k} \pebbles$ with 
	$|\pebbles^{\ell}\head^{\ell}|=y_{\ell}$ for $1\leq\ell\leq k$ and $0\leq|\pebbles|\leq n$.
	By \cref{claim:xi}, we get first 
	$\pebbles,\head\models\varphi_{i}\wedge\overline{\op_{i}}$ and we deduce that $t_{i}$ 
	is enabled at $C=(q,\pebbles,\head)$. It follows that $t_{1}=t_{2}$ by determinism of 
	$\trans$. Hence, $t'_{1}$ and $t'_{2}$ both read the same letter $a'=\mu(t_{1})$ and 
	end at the same state $s'$.  Let $\pebbles',\head'$ be constructed from
	$\pebbles'',\head$ as in \cref{item:2} of \cref{claim:xi}.  We get
	$\pebbles',\head'\models\op'_{i}(\varphi'_{i})\wedge\overline{\reverse{\op_{i}'}}$ and
	we deduce that $t'_{i}$ is reverse-enabled at $C'=(s',\pebbles',\head')$.  It follows that
	$t'_{1}=t'_{2}$ by reverse-determinism of $\trans'$ and then $t''_{1}=t''_{2}$.

\noindent\textbf{Case 2:} $C''=(q'',\pebbles'',\head)$ with
	$q''\in \widehat{Q}\times Q'\times Q^{k}\times[n+1]^{k}$ and $0\leq k\leq m$.

	The proof is similar to the proof for the corresponding case in \cref{claim:simple-rev-det}.

\noindent\textbf{Case 3:} Internal state of the lift-gadget:
	$C''=((q'',-\ell),\pebbles'',\head)$ with
	$q''=(q,q',\overline{x},\overline{y})\in Q\times Q'\times 
	Q^{k}\times[n+1]^{k}$, $1\leq k\leq m$ and $0\leq\ell\leq y_{k}$.

	If $1<\ell<y_{k}$ there are only two transitions ending at state $(q'',-\ell)$, 
	the self-loop with test $\neg\pebble_{d_{k}-\ell+1}$ and the transition with test
	$\pebble_{d_{k}-\ell+1}$.  These two cannot be simultaneously reverse-enabled.

	Assume that $\ell=1$. 
	As before, the self-loop cannot be simultaneously 
	reverse-enabled with a transition $(q'',a,\xi,\nop,(q'',-1))$ since the test $\xi$ 
	checks $\pebble_{d_{k}}$ inside $\overline{\xi}(q'',\overline{\lift{k}})$, and this is 
	incompatible with the test $\neg\pebble_{d_{k}}$ of the self-loop.

	Assume now that $t''_{i}=(q'',a,\xi_{i},\nop,(q'',-1))$ for $i\in\{1,2\}$.
	Since $t''_{i}$ is reverse-enabled at $C''$, we see that $t''_{i}$ is enabled at
	$(q'',\pebbles'',\head-1)$. By \cref{claim:general-det} we deduce that $t''_{1}=t''_{2}$.

\noindent\textbf{Case 4:} Internal state of the drop-gadget:\\
	$C''=((q'',z,\ell),\pebbles'',\head)$ with
	$q''=(q,q',\overline{x},\overline{y})\in Q\times Q'\times 
	Q^{k}\times[n+1]^{k}$, $0\leq k<m$, $1\leq z\leq n+1$ and $1\leq\ell\leq z$.

	If $\ell\neq 1$ there are only two transitions ending at state $(q'',z,\ell)$, 
	the self-loop with test $\neg\pebble_{d_{k}+z+\ell-1}$ and operation $\nop$, and the
	transition with operation $\drop{d_{k}+z+\ell-1}$.  These two cannot be simultaneously
	enabled.

	Assume that $\ell=1$. As before, the self-loop with test 
	$\neg\pebble_{d_{k}+z}$ and operation $\nop$ cannot be simultaneously 
	reverse-enabled with a transition having operation $\drop{d_{k}+z}$.

	Assume now that $t''_{i}=(q'',a,\xi_{i},\drop{d_{k}+z},(q'',z,1))$ for $i\in\{1,2\}$.
	Since $t''_{i}$ is reverse-enabled at $C''$, we see that $t''_{i}$ is enabled at
	$(q'',\lift{d_{k}+z}(\pebbles'',\head-1),\head-1)$. 
	By \cref{claim:general-det} we deduce that $t''_{1}=t''_{2}$.
\end{claimproof}

\section{Generators for  Pebble Transducers}
\subparagraph{Set of generators.}
In~\cite{bojanpebble}, the class of polyregular functions is defined as the smallest class of functions closed under composition that contains the sequential functions, the squaring function and the iterated reverse function. The iterated reverse function acts on an alphabet $\Sigma$ enriched with a special symbol
$!$ and maps a word $u_0!  u_1!  \ldots !  u_n$ to $u_0^r !  u_1^r !  \ldots !
u_n^r$.
By proving that each of these generators can easily be realized by a reversible pebble transducer and using \cref{thm:composition-general-case}, 
we prove that reversible pebble transducers realize all polyregular functions. This also gives a way to generate them using these basic blocks and composition.

Using~\cite[Theorem~2]{DFJL17} as well as \cref{rem:0peb2w}, we get that any sequential function, realized by a transducer $T$ with $n$ states, can be realized by a reversible $0$-pebble transducer with $\mathcal{O}(n^2)$ states.
A reversible $1$-pebble transducer for the squaring function was given in \cref{ex:squaring}.
Finally, we give a reversible $0$-pebble transducer for the iterated reverse in \cref{fig:iterRev}. 

