\begin{lemma}\label{lem:run}
	Let $(q, \head, \pebbles) \xrightarrow{t=(q, a, \varphi, \op,q')} (q', \head', \pebbles')$ in  $\auto$ be a transition. Then  we have $((q,\Phi_1(\pebbles)), \head, \pebbles) \xrightarrow{t'=((q,\Phi_1(\pebbles)), a,\Phi_2(\head,\pebbles), \op, (q', \Phi_1(\pebbles')))} ((q',\Phi_1(\pebbles')), \head', \pebbles')$ in  $\basic$. 
	Conversely, for any transition $((q,\Phi_1(\pebbles)), \head, \pebbles) \xrightarrow{t'=((q,\Phi_1(\pebbles)), a,\Phi_2(\head,\pebbles), \op, (q', \Phi_1(\pebbles')))} ((q',\Phi_1(\pebbles')), \head', \pebbles')$ in  $\basic$, we can find a transition 
	$(q, \head, \pebbles) \xrightarrow{t=(q, a, \varphi, \op,q')} (q', \head', \pebbles')$ in  $\auto$. 

\end{lemma}
\begin{proof}

	Assume that $C_1=(q, \head, \pebbles) \xrightarrow{t=(q, a, \varphi, \op,q')} C_2=(q', \head', \pebbles')$ in  $\auto$.  To enable a corresponding transition in $\basic$, we go through the following steps.


	\begin{enumerate}
		\item \emph{Choose a $(\alpha,b)$}: First of all, by the construction of $\basic$, we know that there is a transition $t'=((q,\alpha), a,b, \op, (q',\alpha'))$ corresponding to $t$ 
		so that $(\alpha,b)$ respects basic consistency and transition consistency. 
		\cref{lem:basic,lem:trans} tell us that the pair $(\Phi_1(\pebbles), \Phi_2(\head,\pebbles))$ satisfies basic and transition consistency, given  $C_1$ and $t$.  
		Thus, this pair is a good candidate for $(\alpha, b)$ in $t'$. 



		\item \emph{Show that the chosen $(\alpha,b)$ enables the transition.} We show that from configuration $C'_1=((q,\Phi_1(\pebbles), \head, \pebbles)$, $t'$ is  
		enabled in $\basic$.  
		\cref{lem:trans} tells us that $(\Phi_1(\pebbles), \Phi_2(\head, \pebbles)) \models \varphi, \op$. The resultant configuration has the new head as $\head'$ and the new pebble stack as $\pebbles'$. It remains to show that the resultant configuration in $\basic$ is $C'_2$; we need to fix $\alpha'$ in $t'$ and $C'_2$. 


		\item \emph{Choose the target state.}
		\cref{lem:trans} also tells us the resultant $\alpha'$ obtained after executing $\varphi, \op$ in $t$.  $\alpha'=\op(\alpha,b)=\op((\Phi_1(\pebbles), \Phi_2(\head, \pebbles))=\Phi_1(\op(\pebbles,\head))=\Phi_1(\pebbles')$. 


	\end{enumerate}


	Thus, we have obtained $\alpha=\Phi_1(\pebbles)$, $b=\Phi_2(\pebbles, \head), \alpha'=\Phi_1(\pebbles')$ so that $t'=((q,  \Phi_1(\pebbles)), (a, \Phi_2(\pebbles, \head)), \op, (q', \Phi_1(\pebbles'))$ is enabled from $C'_1$. The resultant configuration 
	is indeed $C'_2=((q', \Phi_1(\pebbles')), \pebbles', \head')$ in 
	$\basic$.


	Now for the reverse direction.
	Let 
	\[((q,\Phi_1(\pebbles)), \head, \pebbles) \xrightarrow{t'=((q,\Phi_1(\pebbles)), a,\Phi_2(\head,\pebbles), \op, (q', \Phi_1(\pebbles')))} ((q',\Phi_1(\pebbles')), \head', \pebbles')\]
	in  $\basic$. 
	Let $(\alpha, b)=(\Phi_1(\pebbles), \Phi_2(\pebbles, \head))$. 
	\begin{enumerate}
		\item By construction of $\basic$ and \cref{lem:basic} we know that 
		$(\alpha, b)$ satisfies basic consistency
		\item By construction of $\basic$ and  \cref{lem:trans} we know that $\alpha, b \models \op$
		\item By construction of $\basic$, there is a transition $t=(q,a,\varphi, \op, q')$ in $\auto$ such that $\alpha, b \models \varphi$. By \cref{lem:trans}, we know that 
		this implies $\head, \pebbles \models \varphi$. 
	\end{enumerate}
	Hence, indeed $t$ can be fired from $(q, \pebbles, \head)$ in $\auto$ obtaining 
	$(q', \pebbles', \head')$. 
	This establishes the reverse direction. 
\end{proof}

\begin{lemma}\label{lem:det}
	$\basic$ is deterministic if $\auto$ is deterministic.	

\end{lemma}
\begin{proof}
	Assume $\auto$ is deterministic. 

	Consider a transition $t'=((q,\alpha), a,b, \op, (q',\alpha'))$ in $\basic$ enabled from a configuration $C'=((q,\alpha),\pebbles, \head)$.   
	We claim there is a unique transition $t$ in $\auto$ corresponding to $t'$ enabled 
	from a configuration $C=(q,\pebbles, \head)$. 
	Assume on the contrary, that we have 
	$t_1=(q,a,\varphi_1,\op_1, q_1)$ and $t_2=(q,a,\varphi_2, \op_2,q_2)$ enabled from $C$.  By the construction  of $t'$ in $\basic$ from $t_1, t_2$, we know that $\op_1=\op_2=\op$ and 
	$q_1=q_2=q'$. Since $t_1, t_2$ are both enabled from $C$ and $\auto$ is deterministic, we have 
	$\varphi_1=\varphi_2$. Hence, $t_1=t_2$ is a unique transition in $\auto$ corresponding 
	to $t'$. 



	Now we show that $\basic$ is deterministic. 	
	Let two transitions 
	$t'_i=((q, \alpha), a,b, \op_i, (q_i',\alpha_i'))$, $i=1,2$ in $\basic$ be enabled from 
	$C'=((q,\alpha),\pebbles, \head)$. 
	From the above, we know that there is a unique $t_i$ in $\auto$ corresponding to each $t'_i$.
	Let $t_i=(q,a,\varphi_i, \op_i, q'_i)$. 

	From \cref{lem:conf}, we know that there exists $\pebbles, \head$ such that $\alpha=\Phi_1(\pebbles), b=\Phi_2(\pebbles,\head)$. 
	By \cref{lem:trans} we know that $\alpha,b \models \varphi_i \Rightarrow (\head, \pebbles)\models \varphi_i$, and $\alpha,b \models \op_i \Rightarrow (\head, \pebbles)\models \op_i$. If $t_1,t_2$ are enabled from $C=(q, \pebbles, \head)$, then by determinism of $\auto$, 
	we have $t_1=t_2$. Hence, $\op_1=\op_2=\op$. Also, by \cref{lem:trans}, $\alpha'_i=\op_i(\alpha,b)=\op(\alpha,b)$ for $i=1,2$.  
	This implies $t'_1=t'_2$. Thus, $\basic$ is deterministic. 
\end{proof}


\begin{lemma}\label{lem:rev}
	$\basic$ is reverse deterministic if $\auto$ is reverse deterministic.  	

\end{lemma}
\begin{proof}
	Assume $\auto$ is reverse deterministic.  
	Let $t'_i=((q_i, \alpha_i), a,b, \op_i, (q', \alpha'))$ for $i=1,2$ be two transitions 
	in $\basic$. If $t'_1, t'_2$ are both simultaneously reverse enabled, we want to show that 
	$t'_1=t'_2$. 
	Assume that we have configurations $C'_1, C'_2, C'$ such that 
	$C'_1=((q_1, \alpha_1),  \pebbles^1, \head^1) \xrightarrow{t'_1} C'=((q', \alpha'), \pebbles', \head')$, and $C'_2=((q_2, \alpha_2),  \pebbles^2, \head^2) \xrightarrow{t'_2} C'=((q', \alpha'), \pebbles', \head')$. 

	\begin{enumerate}
		\item By \cref{lem:conf}, we know that $\alpha_1=\Phi_1(\pebbles^1), \alpha_2=\Phi_1(\pebbles^2)$. 
		Also, $\head^1=\head^2=\head'-q'=\head$
		\item By \cref{lem:run}, corresponding to $t'_1, t'_2$, for $i=1,2$ we 
		have the transitions 

		$(q_i, \pebbles^i, \head) \xrightarrow{t_i=(q_i, a, \varphi_i, \op_i, q')} (q', \pebbles', \head')$ in $\auto$. 
		Since $\auto$ is reverse deterministic, we know that 
		$t_1=t_2$. $t_1=t_2$ implies that $\op_1=\op_2$, $\varphi_1=\varphi_2$, $q_1=q_2$. 
		\item From \cref{sec:reversing}, we know that $\pebbles^i=\reverse{\op}(\pebbles', \head)$ for $i=1,2$. That is, $\pebbles^1=\pebbles^2$.
		\item Hence, $\alpha_1=\Phi_1(\pebbles^1)=\Phi_1(\pebbles^2)=\alpha_2$.
		\item Thus we have $t'_1=t'_2$.
	\end{enumerate}
	Hence, $\basic$ is reverse deterministic. 
\end{proof} 


\begin{theorem}
	The basic $k$-pebble transducer $\basic$ constructed above is deterministic and reversible if  $\auto$ is. Further, $\sem{\basic}=\sem{\auto}$.
\end{theorem}
\begin{proof}
	\cref{lem:run,lem:det} show that every run in $\auto$ has a corresponding 
	unique run in $\basic$ and conversely.  By construction of $\basic$, the outputs of corresponding transitions 
	in $\basic$ are the same as those of $\auto$. 
\end{proof}


