%----------------------------------------------------------------
\subsection{Notation}
%----------------------------------------------------------------

Fix a natural number $n$.
Let $S_n$ be the symmetric group of order $n$, viewed as the set of functions from $\set{1, \ldots, n}$ to itself, so that
\begin{equation}
  (vw)(i) = v\paren[\big]{w(i)}
  \quad\text{for $v, w \in S_n$ and $i \in \set{1, \ldots, n}$.}
\end{equation}
The group $S_n$ is generated by the \emph{adjacent transpositions},
\begin{equation}
  s_i = (i \leftrightarrow i+1)
  \quad\text{for $i \in \set{1, \ldots, n-1}$},
\end{equation}
which satisfy $s_i^2 = \id$ and the \emph{braid relations}:
\begin{equation}\begin{gathered}
  s_i s_{(i+1)} s_i = s_{(i+1)} s_i s_{(i+1)}
  \qquad\text{for $i \in \set{1, \ldots, n-2}$}, \\
  s_i s_k = s_k s_i
  \qquad\text{for $\abs{i - k} > 1$}.
\end{gathered}\end{equation}
We sometimes write a permutation in one-line notation, as
\begin{equation}
  w = [w(1), \ldots, w(n)].
\end{equation}
In particular, the \emph{longest permutation} is the permutation
\begin{equation}
  w_0 = [n, \ldots, 1].
\end{equation}

A \emph{Hessenberg function} is a function $h : \set{1, \ldots, n} \to \set{1, \ldots, n}$ such that
\begin{equation}\begin{gathered}
  i \leq h(i) \qquad\text{for $i \in \set{1, \ldots, n}$}, \\
  h(i) \leq h(i+1) \qquad\text{for $i \in \set{1, \ldots, n-1}$}.
\end{gathered}\end{equation}
Like permutations, we sometimes write them in one-line notation, as
\begin{equation}
  h = [h(1), \ldots, h(n)].
\end{equation}

We write $\Lambda$ for the ring of symmetric polynomials in $n$ variables, and $\Lambda_0$ for the ideal of symmetric polynomials with no constant term:
\begin{equation}
  \Lambda_0 = \set{f \in \Lambda \mid f(0, \ldots, 0) = 0}.
\end{equation}

We are interested in two commuting $S_n$-actions on the polynomial ring
\begin{equation}
  R = \CC[t_1, \ldots, t_n; x_1, \ldots, x_n]
\end{equation}
by $\CC$-algebra morphisms: the \emph{dot} action, on the left, where $w \in S_n$ permutes the $t_i$ variables and fixes the $x_i$ variables:
\begin{equation}
  w \cdot t_i = t_{w(i)}, \qquad
  w \cdot x_i = x_i,
\end{equation}
and the \emph{star} action, on the right, where $w \in S_n$ fixes the $t_i$ variables and permutes the $w_i$ variables:
\begin{equation}
  t_i * w = t_i, \qquad
  x_i * w = x_{w^{-1}(i)}.
\end{equation}
These two actions are named following Tymoczko~\cite{tymoczko07}, who considered the corresponding actions on the ring of functions
\begin{equation}
  H = \Fun(S_n, \CC[t_1, \ldots, t_n]),
\end{equation}
defined for $w \in S_n$ and $f \in H$ by
\begin{equation}\begin{aligned}
  (w \cdot f)(v; t_1, \ldots, t_n) &= f(w^{-1}v; t_{w(1)}, \ldots, t_{w(n)}), \\
  (f * w)(v; t_1, \ldots, t_n) &= f(vw^{-1}; t_1, \ldots, t_n).
\end{aligned}\end{equation}
The correspondence is given by the following $\CC$-algebra morphism, which respects both actions:
\begin{equation}\begin{aligned}
  \varphi : R &\to H \\
  t_i &\mapsto (v \mapsto t_i) \\
  x_i &\mapsto (v \mapsto t_{v(i)}).
\end{aligned}\end{equation}
By abuse of notation, we will write $t_i$ and $x_i$ for $\varphi(t_i)$ and $\varphi(x_i)$ in $H$.

For each adjacent transposition $s_i$, there is a corresponding \emph{divided difference operator} $\partial_i$ defined by
\begin{equation}
  \partial_i(f) = \frac{f * (1 - s_i)}{x_i - x_{(i+1)}}.
\end{equation}
This definition makes sense in the ring $R$, where the quotient always exists as a (unique) polynomial.
However, it only makes partial sense in the ring $H$, where the quotient may not exist (but is unique if it does exist).
One of our contributions in this paper is to detail some suitable domains and codomains for $\partial_i$ on $H$ (see \autoref{sec:domain-codomain}).
For now, note that, on the appropriate domains, the divided difference operators satisfy $\partial_i^2 = 0$ and the braid relations:
\begin{equation}\begin{gathered}
  \partial_i \partial_{(i+1)} \partial_i = \partial_{(i+1)} \partial_i \partial_{(i+1)}
  \qquad\text{for $i \in \set{1, \ldots, n-2}$}, \\
  \partial_i \partial_k = \partial_k \partial_i
  \qquad\text{for $\abs{i - k} > 1$},
\end{gathered}\end{equation}
since
\begin{multline}
  \partial_i \partial_{(i+1)} \partial_i(f) = \partial_{(i+1)} \partial_i \partial_{(i+1)}(f) \\
  = \frac{f * (1 - s_i - s_{(i+1)} + s_i s_{(i+1)} + s_{(i+1)} s_i - s_i s_{(i+1)} s_i)}{(x_i - x_{(i+1)}) (x_i - x_{(i+2)}) (x_{(i+1)} - x_{(i+2)})}
\end{multline}
and
\begin{equation}
\partial_i \partial_k(f) = \partial_k \partial_i(f)
= \frac{f * (1 - s_i - s_k + s_i s_k)}{(x_i - x_{(i+1)}) (x_k - x_{(k+1)})}.
\end{equation}
The divided difference operators are not ring homomorphisms, but they are $\CC$-linear and satisfy a (skew) product rule:
\begin{equation}
  \partial_i(fg) = \partial_i(f) g + (f * s_i) \partial_i(g).
\end{equation}

%----------------------------------------------------------------
\subsection{First pass: ordinary cohomology}
%----------------------------------------------------------------

Consider the variety of complete flags in $\CC^n$,
\begin{equation}
  X = \set[\big]{V_\bullet = (V_0 \subseteq \cdots \subseteq V_n) \bigm| \text{$\dim(V_i) = i$ for $i \in \set{0, \ldots, n}$}}.
\end{equation}
The Borel presentation for its ordinary cohomology ring is the polynomial ring quotient
\begin{equation}
  H^*(X) = \frac{\CC[x_1, \ldots, x_n]}{\gen{f(x_1, \ldots, x_n) \mid f \in \Lambda_0}},
\end{equation}
where $x_i$ is the first Chern class of the line bundle $V_i / V_{(i-1)}$ over $X$ (see, for example, \cite{kaji15} and references therein).

This ring has a very nice $\CC$-linear basis, given by the Schubert polynomials (for their history, see~\cite{lascoux95}).
These polynomials are indexed by the permutations in $S_n$, and they can be defined recursively by starting at the longest permutation, and applying divided difference operators to obtain the others:
\begin{equation}\begin{gathered}
  \SC_{w_0} = x_1^{n-1} x_2^{n-2} \cdots x_n^0, \\
  \SC_{w s_i} = \partial_i(\SC_w) \qquad\text{if $w(i) > w(i+1)$}.
\end{gathered}\end{equation}
Note that the divided difference operators are well-defined on $H^*(X)$ because they respect the ideal $\gen{f(x_1, \ldots, x_n) \mid f \in \Lambda_0}$ by the product rule; and that the indexing by permutations is well-defined because of the braid relations.

%----------------------------------------------------------------
\subsection{Second pass: equivariant cohomology}
%----------------------------------------------------------------

Consider the $n$-dimensional complex torus $T = (\CC^\times)^n$, whose classifying space is $BT = (\CC P^\infty)^n$.
The equivariant cohomology ring of a single point, equipped with the trivial $T$-action, is the polynomial ring
\begin{equation}
  H_T^*(\pt) = H^*(BT) = \CC[t_1, \ldots, t_n],
\end{equation}
where $t_i$ it the first Chern class of the tautological line bundle over the $i$th factor $\CC P^\infty$ of $BT$ (see, for example, \cite{tymoczko05} and references therein).

The flag variety $X$ can be equipped with a $T$-action by identifying $T$ with the group of invertible diagonal matrices on $\CC^n$.
The Borel presentation for its equivariant cohomology ring is the polynomial ring quotient
\begin{equation}\label{eq:equivariant-borel}
  H_T^*(X) = \frac{\CC[t_1, \ldots, t_n; x_1, \ldots, x_n]}{\gen{f(t_1, \ldots, t_n) - f(x_1, \ldots, x_x) \mid f \in \Lambda}}.
\end{equation}

We can recover the ordinary cohomology by setting $t_1 = \cdots = t_n = 0$.
The divided difference operators respect the quotienting ideal in~(\ref*{eq:equivariant-borel}), and we can lift the $\CC$-linear basis of Schubert polynomials for $H^*(X)$ to a $H_T^*(\pt)$-module basis of \emph{double} Schubert polynomials for $H_T^*(X)$, as follows:
\begin{equation}\begin{gathered}
  \SC'_{w_0} = \prod_{i+k \leq n} (x_i - t_k), \\
  \SC'_{w s_i} = \partial_i(\SC'_w) \qquad\text{if $w(i) > w(i+1)$}.
\end{gathered}\end{equation}
This basis shows that $H_T^*(X)$ is a free module over $\CC[t_1, \ldots, t_n]$, but in fact the same basis shows that $H_T^*(X)$ is also a free module over $\CC[x_1, \ldots, x_n]$.

As noted in~\cite{tymoczko07}, the dot action acts trivially on the subring $\CC[x_1, \ldots, x_n]$, so we can consider $H_T^*(X)$ as a representation of $S_n$ over $\CC[x_1, \ldots, x_n]$; this representation is a single copy of the regular representation of $S_n$.

The dot action acts non-trivially on $\CC[t_1, \ldots, t_n]$, but it does send this subring to itself, so we can consider $H_T^*(X)$ as a \emph{twisted} representation of $S_n$ over $\CC[t_1, \ldots, t_n]$; this representation consists of $n!$ copies of the (twisted) trivial representation of $S_n$.

%----------------------------------------------------------------
\subsection{Third pass: Hessenberg varieties}
%----------------------------------------------------------------

Now we consider some sub-varieties of the flag variety $X$.
Fix a diagonal matrix $M$ with distinct eigenvalues.
The specific choice does not matter for this story, only that:
\begin{itemize}
  \item
    the Jordan blocks of $M$ all have size one (so that $M$ is semisimple),
  \item
    the Jordan blocks have distinct eigenvalues (so that $M$ is regular),
  \item
    $M$ commutes with the torus $T$.
\end{itemize}
Then, for every Hessenberg function $h$, we have the corresponding (regular semisimple) Hessenberg variety
\begin{equation}
  X(h) = \set[\big]{V_\bullet \in X \bigm| \text{$MV_i \subseteq V_{h(i)}$ for $i \in \set{1, \ldots, n}$}}.
\end{equation}
As two extreme examples, note that $X([n, \ldots, n])$ is the entire flag variety, and that $X([1, \ldots, n])$ consists of just $n!$ isolated points, the permutation flags, which are the fixed points of the $T$-action on $X$.

For each Hessenberg function, the sub-variety $X(h) \subseteq X$ is preserved by the $T$-action, so we can consider its equivariant cohomology ring.
Instead of the Borel presentation as a quotient of the ring $R$, we have the GKM presentation~\cite{tymoczko07}, which exhibits $H_T^*(X(h))$ as a subring of $H$ (see \autoref{sec:divisibility-conditions}).
However, note that the kernel of the map $\varphi : R \to H$ is precisely the quotienting ideal in~\eqref{eq:equivariant-borel}, so the two presentations are closely related.

The concept which generalizes the basis of double Schubert polynomials is the concept of a \emph{flow-up} basis~\cite{harada-tymoczko17}. These are bases
\begin{equation}
  \set{f_w \mid w \in S_n} \subseteq H_T^*(X(h)),
\end{equation}
over $H_T^*(\pt)$, indexed by permutations, where
\begin{equation}
  f_w(v) = 0 \quad\text{if $w \not\leq v$ in Bruhat order},
\end{equation}
and where $f_w(w)$ is a prescribed product of factors of the form $(t_i - t_k)$.
In the case of the entire flag variety, the double Schubert polynomials are the unique flow-up basis, but in general the flow-up bases are not unique.
Still, flow-up bases do exist, and they show that $H_T^*(X(h))$ is a free module over $\CC[t_1, \ldots, t_n]$, and a free module over $\CC[x_1, \ldots, x_n]$.

The dot action on $H$ preserves the subring $H_T^*(X(h))$.
When we consider it as a representation of $S_n$ over $\CC[x_1, \ldots, x_n]$, its graded Frobenius characteristic is a unicellular LLT polynomial.
When we consider it as a twisted representation of $S_n$ over $\CC[t_1, \ldots, t_n]$, its graded Frobenius characteristic is a chromatic quasisymmetric function (up to the fundamental involution on symmetric functions)~\cite{brosnan-chow18,carlsson-mellit18,guay-paquet16,lascoux-leclerc-thibon97,shareshian-wachs12,shareshian-wachs16,stanley95}.

Both unicellular LLT polynomials and chromatic quasisymmetric functions are known to satisfy the modular relation (a variant on the deletion-contraction recurrence for chromatic polynomials of graphs), which states that, for certain triples $(h_{-}, h, h_{+})$ of Hessenberg functions:
\begin{equation}\label{eq:modular-csf}
  (1+q) \csf_q(h) = \csf_q(h_{+}) + q \csf_q(h_{-})
\end{equation}
In fact, together with a relatively small set of base cases, the modular relation uniquely determines these two families of symmetric functions~\cite{abreu-nigro21,guay-paquet13,orellana-scott14}.

Another contribution of this paper is to give a decomposition of the dot representation on $H_T^*(X(h))$ which corresponds to the modular relation, by using divided difference operators (see \autoref{thm:stable} and \autoref{thm:almost-stable}).

Note that Horiguchi, Masuda and Sato~\cite{horiguchi-masuda-sato24} have also given such a decomposition, which is nicely motivated by the geometry of Hessenberg varieties.
They exhibit the blow-up of $X(h_{+})$ along $X(h_{-})$ as a $\CC P^1$-bundle over $X(h)$ equipped with a $T$-action.
Based on this, they identify a certain subring of
\begin{equation}
  H_T^*(X(h)) \oplus \paren[\big]{H_T^*(X(h)) * s_i}
\end{equation}
as being isomorphic to both:
\begin{itemize}
  \item
    the direct sum of a plain copy of $H_T^*(X(h))$ and a degree-shifted copy of $H_T^*(X(h))$, corresponding to the left-hand side of~\eqref{eq:modular-csf}, and
  \item
    the direct sum of a plain copy of $H_T^*(X(h_{+}))$ and a degree-shifted copy of $H_T^*(X(h_{-}))$, corresponding to the right-hand side.
\end{itemize}

In contrast, our decomposition is only algebraic, and corresponds to a version of~\eqref{eq:modular-csf} which is divided by $(1+q)$.
Using the divided difference operators, we identify a sub-representation
\begin{equation}
  H_T^*(X(h_{+}))^{*s_i} \subseteq H_T^*(X(h_{+}))
\end{equation}
such that $H_T^*(X(h_{+}))$ is the direct sum of a plain copy and a degree-shifted copy of $H_T^*(X(h_{+}))^{*s_i}$; similarly for $H_T^*(X(h_{-}))$.
Then, we show that a single, plain copy of $H_T^*(X(h))$ is the direct sum of a plain copy of $H_T^*(X(h_{+}))^{*s_i}$ and a degree-shifted copy of $H_T^*(X(h_{-}))^{*s_i}$.

%----------------------------------------------------------------
\section{Divisibility conditions}\label{sec:divisibility-conditions}
%----------------------------------------------------------------

We now describe a family of subrings of the ring of functions $H$, which will be a convenient setting for the divided difference operators, and among which are the equivariant cohomology rings of Hessenberg varieties.

For an element $f \in H$ and a transposition $\tau = (i \leftrightarrow k) \in S_n$, we say that \emph{$f$ satisfies condition $\tau$} if
\begin{equation}
  f * (1 - \tau) \quad\text{is a multiple of}\quad (x_i - x_k).
\end{equation}
Note that, in particular, any multiple of $(x_i - x_k)$ satisfies condition $\tau$:
\begin{equation}
  \paren[\big]{(x_i - x_k) f} * (1 - \tau) = (x_i - x_k) \paren[\big]{f * (1 + \tau)}.
\end{equation}
The set of elements which satisfy condition $\tau$ is closed under addition and multiplication, so they form a subring of $H$, which we call $H_\tau$.
More generally, for a set of transpositions $C \subseteq S_n$, we write
\begin{equation}
  H_C = \bigcap_{\tau \in C} H_\tau
\end{equation}
for the subring of elements which satisfy all conditions in $C$.
If $C$ is the empty set, then $H_C$ is the entire ring $H$.

Note that the elements $t_1, \ldots, t_n$ and $x_1, \ldots, x_n$ satisfy all divisibility conditions, so the entire image of $\varphi : R \to H$ does too.

If $w \in S_n$ and $f$ satisfies condition $\tau$, then
\begin{equation}\begin{gathered}
  \text{$w \cdot f$ satisfies condition $\tau$, and} \\
  \text{$f * w$ satisfies condition $w^{-1}\tau w$,}
\end{gathered}\end{equation}
so each $H_C$ is closed under the dot action, but usually \emph{not} the star action.

For a Hessenberg function $h$, the GKM presentation of the equivariant cohomology ring for the corresponding Hessenberg variety is
\begin{equation}
  H_T^*(X(h)) = H_{C(h)},
\end{equation}
with the following set of divisibility conditions:
\begin{equation}\label{eq:hessenberg-conditions}
  C(h) = \set{(i \leftrightarrow k) \mid i < k \leq h(i)}.
\end{equation}

Recall that the definition of the $i$th divided difference operator is
\begin{equation}
  \partial_i(f) = \frac{f * (1 - s_i)}{x_i - x_{(i+1)}},
\end{equation}
if the quotient exists in $H$.
Since this is the defining condition of the subring $H_{s_i}$, we can write the largest domain of definition of $\partial_i$ as:
\begin{equation}
  \partial_i : H_{s_i} \to H.
\end{equation}
For Hessenberg functions, note that $s_i \in C(h)$ whenever $h(i) \neq i$.
We give a more careful account of some domains and codomains for $\partial_i$ in \autoref{sec:domain-codomain}.

We record here some of the convenient computational properties of divided differences which follow directly from the definition.
\begin{lemma}\label{lem:compute}
  For $f, g \in H_{s_i}$ and $w \in S_n$, we have:
  \begin{enumerate}
    \item $\partial_i(f + g) = \partial_i(f) + \partial_i(g)$,
    \item $\partial_i(f g) = \partial_i(f) \, g + (f * s_i) \, \partial_i(g)$,
    \item $\partial_i(f g) = f \, \partial_i(g)$ when $\partial_i(f) = 0$,
    \item $\partial_i(f) = 0$ exactly when $f * s_i = f$,
    \item $\partial_i(w \cdot f) = w \cdot \partial_i(f)$,
    \item $\partial_i(f * s_i) = -\partial_i(f)$,
    \item $\partial_i(f) * s_i = \partial_i(f)$,
    \item $\partial_i(f) * w = \partial_k(f * w)$ when $w(k) = i$ and $w(k+1) = i+1$,
    \item $\partial_i(t_k) = 0$,
    \item $\partial_i$ is $\CC[t_1, \ldots, t_n]$-linear,
    \item $\partial_i(x_i) = 1$,
    \item $\partial_i(x_{(i+1)}) = -1$,
    \item $\partial_i(x_k) = 0$ when $k \notin \set{i, i+1}$.
  \end{enumerate}
\end{lemma}
\begin{proof}
  By direct computation, keeping in mind that if the quotient exists, then $(f/g) * w = (f*w)/(g*w)$.
\end{proof}

