%----------------------------------------------------------------
\section{Domains and codomains}\label{sec:domain-codomain}
%----------------------------------------------------------------

The divided difference operators aren't defined on all of $H$, and don't preserve the subrings $H_C$ in general.
But, motivated by the following lemma, we say that a set of conditions $C$ is \emph{$s_i$-stable} if
\begin{equation}
  s_i \in C
  \quad\text{and}\quad
  s_i C s_i = C.
\end{equation}

\begin{lemma}\label{lem:stability}
  If $C$ is $s_i$-stable, then $\partial_i$ is defined on $H_C$, and $\partial_i(H_C) \subseteq H_C$.
\end{lemma}

Since $H_C \subseteq H_D$ whenever $D \subseteq C$, we can also consider the largest $s_i$-stable subset of $C$ and phrase this equivalently as:

\begin{corollary}
  If $s_i \in C$ and $D = C \cap s_i C s_i$, then $\partial_i$ is defined on $H_C$, and $\partial_i(H_C) \subseteq H_D$.
\end{corollary}

\begin{proof}[Proof of \autoref*{lem:stability}]
Since $s_i \in C$, it's immediate that $\partial_i$ is defined on $H_C$.
To show that $\partial_i(H_C) \subseteq H_C$, we will reduce to the case of three specific sets $C$, each of which can be checked on a small $\CC[t_1, \ldots, t_n]$-submodule of $H_C$, and provide an explicit basis for this submodule.

As a first reduction, it suffices to check that $\partial_i(H_C) \subseteq H_C$ for the \emph{minimal} $s_i$-stable sets $C$, which are of the form
\begin{equation}
  C(i, \tau) = \set{s_i,\; \tau,\; s_i \tau s_i}
  \quad\text{for a transposition $\tau \in S_n$,}
\end{equation}
because for a general $s_i$-stable set $C$, we have
\begin{equation}
  H_C = \bigcap_{\tau \in C} H_{C(i, \tau)}.
\end{equation}

As a second reduction, it suffices to check the three specific $s_1$-stable sets
\begin{equation}\begin{aligned}
  C(1, s_1) &= \set{(1 \leftrightarrow 2)} \\
  C(1, s_2) &= \set{(1 \leftrightarrow 2), (1 \leftrightarrow 3), (2 \leftrightarrow 3)} \\
  C(1, s_3) &= \set{(1 \leftrightarrow 2), (3 \leftrightarrow 4)},
\end{aligned}\end{equation}
because each $C(i, \tau)$ can be reduced to one of them, depending on the case:
\begin{description}
  \item[Case $s_i = \tau$:]
    Let $w \in S_n$ be a permutation with
    \begin{equation}
      w(i) = 1, \qquad
      w(i+1) = 2.
    \end{equation}
    Then, using ``$\subseteq^?$'' to denote the inclusion we are reducing to, we have
    \begin{equation}\begin{aligned}
      \partial_i\paren[\big]{H_{C(i, \tau)}}
      = \partial_i\paren[\big]{H_{C(1, s_1)} * w}
      &= \partial_1\paren[\big]{H_{C(1, s_1)}} * w \\
      &\subseteq^? H_{C(1, s_1)} * w = H_{C(i, \tau)}.
    \end{aligned}\end{equation}

  \item[Case $s_i \neq \tau$ and $\tau \neq s_i \tau s_i$:]
    In this case, $\tau$ and $s_i \tau s_i$ must be of the form $(i \leftrightarrow k)$ and $(i+1 \leftrightarrow k)$, in some order, for some $k \notin \set{i, i+1}$.
    Let $w \in S_n$ be a permutation with
    \begin{equation}
      w(i) = 1, \qquad
      w(i+1) = 2, \qquad
      w(k) = 3.
    \end{equation}
    Then, we have
    \begin{equation}\begin{aligned}
      \partial_i\paren[\big]{H_{C(i, \tau)}}
      = \partial_i\paren[\big]{H_{C(1, s_2)} * w}
      &= \partial_1\paren[\big]{H_{C(1, s_2)}} * w \\
      &\subseteq^? H_{C(1, s_2)} * w = H_{C(i, \tau)}
    \end{aligned}\end{equation}

  \item[Case $s_i \neq \tau$ and $\tau = s_i \tau s_i$:]
    In this case, $\tau$ must be of the form $(j \leftrightarrow k)$ for some $\set{j, k}$ disjoint from $\set{i, i+1}$.
    Take $w \in S_n$ such that
    \begin{equation}
      w(i) = 1, \quad
      w(i+1) = 2, \quad
      w(j) = 3, \quad
      w(k) = 4.
    \end{equation}
    Then, we have
    \begin{equation}\begin{aligned}
      \partial_i\paren[\big]{H_{C(i, \tau)}}
      = \partial_i\paren[\big]{H_{C(1, s_3)} * w}
      &= \partial_1\paren[\big]{H_{C(1, s_3)}} * w \\
      &\subseteq^? H_{C(1, s_3)} * w = H_{C(i, \tau)}
    \end{aligned}\end{equation}
\end{description}

As an independent reduction, it suffices to check that $\partial_i(H_C) \subseteq H_C$ on a certain $\CC[t_1, \ldots, t_n]$-submodule of $H_C$.
Specifically, let $\gen{C}$ be the subgroup of $S_n$ generated by $C$, and let $1_{\gen{C}} \in H_C$ be defined by
\begin{equation}
  1_{\gen{C}}(v; t_1, \ldots, t_n) = \begin{cases}
    1 &\text{if $v \in \gen{C}$} \\
    0 &\text{otherwise.}
  \end{cases}
\end{equation}
Then, $1_{\gen{C}} H_C$ is the $\CC[t_1, \ldots, t_n]$-submodule of functions in $H_C$ which are zero outside of $\gen{C}$.
The unit element in $H_C$ decomposes as
\begin{equation}
  1 = \sum_w w \cdot 1_{\gen{C}},
\end{equation}
where the sum is over an arbitrary choice of representatives $w$ for the cosets $w \gen{C} \subseteq S_n$.
For an element $f \in H_C$ and a permutation $w \in S_n$, let
\begin{equation}
  f_w = 1_{\gen{C}} \, (w^{-1} \cdot f) \in 1_{\gen{C}} H_C.
\end{equation}
Then, the element $f$ can be decomposed as
\begin{equation}
  f = \sum_w w \cdot f_w,
\end{equation}
so that
\begin{equation}
  \partial_i(f) = \sum_w w \cdot \partial_i(f_w).
\end{equation}
Thus, $\partial_i(H_C) \subseteq H_C$ is implied by $\partial_i\paren[\big]{1_{\gen{C}} H_C} \subseteq H_C$.

Given all of these reductions, the remaining task is to compute $\partial_1$ on a $\CC[t_1, \ldots, t_n]$-linear basis of $1_{\gen{C}} H_C$ for $C \in \set{C(1, s_1),\; C(1, s_3),\; C(1, s_2)}$.
