%----------------------------------------------------------------
\section{Decompositions of dot representations}
%----------------------------------------------------------------

Now that we have a handle on the domain and range of the divided difference operators, we can use them to decompose of some of the subrings $H_C$.

%----------------------------------------------------------------
\subsection{The \texorpdfstring{$s_i$}{sᵢ}-stable case}
%----------------------------------------------------------------

\begin{theorem}\label{thm:stable}
  Let $C$ be an $s_i$-stable set of divisibility conditions.
  Then, we have the internal direct sum decomposition
  \begin{equation}
    H_C = H_C^{*s_i} \oplus (x_i - x_{(i+1)}) H_C^{*s_i}
  \end{equation}
  as $\CC[t_1, \ldots, t_n]$-submodules of $H$ equipped with the dot action, where
  \begin{equation}
    H_C^{*s_i} = \set{f \in H_C \mid f * s_i = f}.
  \end{equation}
\end{theorem}

\begin{proof}
  Since $C$ is $s_i$-stable, the subgroup $\set{\id, s_i} \subseteq S_n$ of order two acts on the right on $H_C$ by the star action, and we have the natural decomposition
  \begin{equation}
    H_C = H_C^{*s_i} \oplus H_C^{*-s_i},
  \end{equation}
  where we write
  \begin{equation}
    H_C^{*-s_i} = \set{f \in H_C \mid f * s_i = -f}
  \end{equation}
  for the $(-1)$-eigenspace of the involution $f \mapsto f * s_i$.
  We claim that
  \begin{equation}
    H_C^{*-s_i} = (x_i - x_{(i+1)}) H_C^{*s_i},
  \end{equation}
  because we further claim that the maps
  \begin{equation}\begin{tikzpicture}[baseline=(a.base)]
    \node (a) at (0,0) {$H_C^{*-s_i}$};
    \node (b) at (4,0) {$H_C^{*s_i}$};
    \path[->]
    ($(a.east)+(0,3pt)$) edge node[above] {$\partial_i$} ($(b.west)+(0,3pt)$)
    ($(b.west)-(0,3pt)$) edge node[below] {$(x_i - x_{(i+1)})/2$} ($(a.east)-(0,3pt)$);
  \end{tikzpicture}\end{equation}
  form a bijection.
  This follows from the facts that
  \begin{equation}\begin{gathered}
    \partial_i(H_C^{*-s_i}) \subseteq \partial_i(H_C) \subseteq H_C^{*s_i}, \\
    (x_i - x_{(i+1)}) H_C^{*s_i} \subseteq H_C^{*-s_i}, \\
    \partial_i\paren[\big]{(x_i - x_{(i+1)}) f} / 2 = f * (1 + s_i) / 2 = f
    \quad\text{when $f \in H_C^{*s_i}$}, \\
    (x_i - x_{(i+1)}) \partial_i(f) / 2 = f * (1 - s_i) / 2 = f
    \quad\text{when $f \in H_C^{*-s_i}$},
  \end{gathered}\end{equation}
  which can be verified by direct computation.
\end{proof}

The proof of \autoref{thm:stable} yields an additional fact:
\begin{corollary}
  The kernel and image of $\partial_i : H_C \to H_C$ are equal to $H_C^{*s_i}$ when $C$ is $s_i$-stable.
\end{corollary}

%----------------------------------------------------------------
\subsection{The almost-\texorpdfstring{$s_i$}{sᵢ}-stable case}
%----------------------------------------------------------------

Motivated by the following decomposition, we define the notion of almost-stability. We say that a set of divisibility conditions $C$ is \emph{almost-$s_i$-stable} if $s_i \in C$ and there is a unique transposition $\tau$ such that $\tau \in C$ but $s_i \tau s_i \notin C$. If this is the case, then the sets
\begin{equation}
  C_{-} = C \setminus \set{\tau}, \qquad
  C_{+} = C \cup \set{s_i \tau s_i},
\end{equation}
obtained from $C$ by removing or adding a single condition, are $s_i$-stable.

Note that, for sets of divisibility conditions obtained from Hessenberg functions as in~\eqref{eq:hessenberg-conditions}, the notion of almost-stability corresponds to the notion of a modular triple in~\eqref{eq:modular-csf}.

\begin{theorem}\label{thm:almost-stable}
  Let $C$ be an almost-$s_i$-stable set of divisibility conditions, so that $C_{-} = C \setminus \set{\tau}$ and $C_{+} = C \cup \set{s_i \tau s_i}$ are $s_i$-stable.
  If $\tau = (i \leftrightarrow k)$, then we have the internal direct sum decomposition
  \begin{equation}
    H_C = H_{C_{+}}^{*s_i} \oplus (x_i - x_k) H_{C_{-}}^{*s_i}
  \end{equation}
  as $\CC[t_1, \ldots, t_n]$-submodules of $H$ equipped with the dot action.
  Otherwise, $\tau = (i+1 \leftrightarrow k)$ and we have the internal direct sum decomposition
  \begin{equation}
    H_C = H_{C_{+}}^{*s_i} \oplus (x_k - x_{(i+1)}) H_{C_{-}}^{*s_i}.
  \end{equation}
\end{theorem}

\begin{proof}
  We will assume that $\tau = (i \leftrightarrow k)$, since the case where $\tau = (i+1 \leftrightarrow k)$ follows by using the transformation
  \begin{equation}
    H_C * s_i = H_{s_i C s_i}.
  \end{equation}
  We claim that the decomposition is given by the following maps:
  \begin{equation}\begin{tikzpicture}[baseline=(a.base)]
    \node (a) at (0,0) {$H_{C_{+}}^{*s_i}$};
    \node (b) at (4,0) {$H_C$};
    \node (c) at (8,0) {$H_{C_{-}}^{*s_i}$};
    \path[->]
    ($(a.east)+(0,3pt)$) edge node[above] {$\id$} ($(b.west)+(0,3pt)$)
    ($(b.west)-(0,3pt)$) edge node[below] {$\partial_i \circ (x_k - x_{(i+1)})$} ($(a.east)-(0,3pt)$)
    ($(b.east)+(0,3pt)$) edge node[above] {$\partial_i$} ($(c.west)+(0,3pt)$)
    ($(c.west)-(0,3pt)$) edge node[below] {$(x_i - x_k)$} ($(b.east)-(0,3pt)$);
  \end{tikzpicture}\end{equation}
  To prove this, we need to check that:
  \begin{itemize}
    \item
      All four maps land in the stated codomain.
      Using the inclusions
      \begin{equation}\begin{gathered}
        H_{C_{+}} \subseteq H_C \subseteq H_{C_{-}} \\
        (x_i - x_k) H_{C_{-}} \subseteq H_C \\
        (x_k - x_{(i+1)}) H_C \subseteq H_{C_{+}},
      \end{gathered}\end{equation}
      we indeed have that
      \begin{equation}\begin{gathered}
        \id(H_{C_{+}}^{*s_i}) \subseteq H_{C_{+}} \subseteq H_C \\
        \partial_i(H_C) \subseteq \partial_i(H_{C_{-}}) \subseteq H_{C_{-}}^{*s_i} \\
        \partial_i\paren[\big]{(x_k - x_{(i+1)}) H_C} \subseteq \partial_i(H_{C_{+}}) \subseteq H_{C_{+}}^{*s_i} \\
        (x_i - x_k) H_{C_{-}}^{*s_i} \subseteq (x_i - x_k) H_{C_{-}} \subseteq H_C.
      \end{gathered}\end{equation}

    \item
      The two compositions $H_C \to H_C$ are complementary idempotents.
      Using the computational properties from \autoref{lem:compute}, we have
      \begin{equation}\begin{gathered}
        \partial_i\paren[\big]{(x_k - x_{(i+1)}) f} + (x_i - x_k) \partial_i(f) = f \\
        \partial_i\paren[\Big]{(x_k - x_{(i+1)}) \partial_i\paren[\big]{(x_k - x_{(i+1)}) f}} = \partial_i\paren[\big]{(x_k - x_{(i+1)}) f} \\
        (x_i - x_k) \partial_i\paren[\big]{(x_i - x_k) \partial_i(f)} = (x_i - x_k) \partial_i(f)
      \end{gathered}\end{equation}
      for every $f \in H_C$, as required.

    \item
      The compositions $H_{C_{-}}^{*s_i} \to H_{C_{-}}^{*s_i}$ and $H_{C_{+}}^{*s_i} \to H_{C_{+}}^{*s_i}$ are the identity.
      Again using \autoref{lem:compute}, we have
      \begin{equation}\begin{gathered}
        \partial_i\paren[\big]{(x_i - x_k) f} = f + (x_{(i+1)} - x_k) \partial_i(f) = f
        \quad\text{for $f \in H_{C_{-}}^{*s_i}$}, \\
        \partial_i\paren[\big]{(x_k - x_{(i+1)}) f} = f + (x_i - x_k) \partial_i(f) = f
        \quad\text{for $f \in H_{C_{+}}^{*s_i}$},
      \end{gathered}\end{equation}
      as required.
      \qedhere
  \end{itemize}
\end{proof}

